const Parent = layout.model.Parent;

pub const dvui_app: dvui.App = .{
    .config = .{ .startFn = start },
    .frameFn = frame,
    .initFn = init,
    .deinitFn = deinit,
};
/// Runs before SDL starts. SDL 3.4 falls back to XWayland on compositors
/// without the fifo-v1 protocol (COSMIC, for one), where it cannot see the
/// display scale; an editor wants correct scaling over frame pacing, so
/// Wayland comes first. SDL_VIDEO_DRIVER in the environment still wins.
fn start() dvui.App.StartOptions {
    if (dvui.backend.kind == .sdl3) {
        const c = dvui.backend.c;
        _ = c.SDL_SetHint(c.SDL_HINT_VIDEO_DRIVER, "wayland,x11");
        // The identifier becomes the Wayland app id, which the desktop uses
        // to find Graven's .desktop file and icon.
        _ = c.SDL_SetAppMetadata("Graven", layout.version, "com.mnemopyx.graven");
    }
    return .{
        .size = .{ .w = 1500, .h = 820 },
        .min_size = .{ .w = 800, .h = 500 },
        .title = "Graven",
        .app = "Graven",
        .org = "com.mnemopyx.graven",
    };
}

pub const main = dvui.App.main;

/// For the GUI's tests (harness_test.zig), which run Graven's frames under
/// DVUI's testing backend and drive its widgets by tag: the model and
/// history as they stand.
pub const testing_api = struct {
    pub fn model() *Model {
        return &state.model;
    }
    /// The fabrication checks last run: the panels checked (none when
    /// cleared or for another document), and whether out of date.
    pub fn checkedPanels() []const usize {
        if (!checksCurrent()) return &.{};
        const out = dvui.currentWindow().arena().alloc(usize, checks.len) catch return &.{};
        for (checks, out) |ck, *o| o.* = ck.panel;
        return out;
    }
    pub fn checkReport(panel: usize) ?layout.check.Report {
        if (!checksCurrent()) return null;
        for (checks) |ck| if (ck.panel == panel) return ck.report;
        return null;
    }
    pub fn checksOutOfDate() bool {
        return checksStale();
    }
    /// A plan's last checks: per operation and part.
    pub fn planChecks(id: layout.model.ObjectId) []const OpChecked {
        return if (planChecksFor(id)) plan_checks else &.{};
    }
    /// The active view's kind, and what it shows.
    pub fn activeView() docviews.View {
        return vl.views[vl.active];
    }
    /// How many windows (splits) the view area has.
    pub fn windowCount() usize {
        var n: usize = 0;
        for (vl.nodes) |nd| {
            if (nd.used and !nd.split) n += 1;
        }
        return n;
    }
    /// How many tabs the active view's window has.
    pub fn activeTabs() usize {
        const leaf = vl.leafOf(vl.active) orelse return 0;
        return vl.nodes[leaf].tab_count;
    }
    /// Another legend sheet over the first one's keys, named `name`.
    pub fn makeSheetLikeFirst(name: []const u8) bool {
        if (state.model.sheets.items.len == 0) return false;
        _ = act(.makeSheet, .{ name, state.model.sheets.items[0].scope }) catch return false;
        return true;
    }
    /// Sheet `i` opened as from the Browser (a double-click on it).
    pub fn openSheetFromBrowser(i: usize) void {
        showSheetView(state.model.sheets.items[i].id);
    }
    /// How many views show sheet `i`.
    pub fn sheetViews(i: usize) usize {
        var buf: [docviews.max_views]u8 = undefined;
        return vl.viewsOf(.sheet, @intFromEnum(state.model.sheets.items[i].id), &buf).len;
    }
    /// The split holding the active view's window: its direction (0 side
    /// by side, 1 stacked), share, and whether the active view's window is
    /// its first part; null when there is no split.
    pub fn activeSplit() ?struct { dir: u1, ratio: f32, first: bool } {
        const n = vl.splitOf(vl.active) orelse return null;
        const nd = vl.nodes[n];
        return .{ .dir = @intFromBool(nd.dir == .down), .ratio = nd.ratio, .first = nd.first == vl.leafOf(vl.active).? };
    }
    /// Whether a split's options are shown.
    pub fn dividerMenuOpen() bool {
        return divider_menu != null;
    }
    /// The shown space's layers, bottom first.
    pub fn shownLayers() []const layout.model.Layer {
        if (shown_space >= state.model.spaces.items.len) return &.{};
        return state.model.spaces.items[shown_space].layers.items;
    }
    /// Whether the view's own layer named `name` (`grid`, `axes`,
    /// `guides` …) is shown, and how many document layers lie below it
    /// (`maxInt(u16)`: above them all).
    pub fn viewLayer(name: []const u8) ?struct { shown: bool, below: u16 } {
        const v = std.meta.stringToEnum(ViewLayer, name) orelse return null;
        return .{ .shown = v.shown(), .below = overlayOf(shown_space, v).below };
    }
    /// The ribbon's drop open: "layers", "shape", "tracks", or "".
    pub fn dropRect() dvui.Rect.Physical {
        return drop_rect;
    }
    pub fn dropOpen() []const u8 {
        return if (drop_open) |d| @tagName(d) else "";
    }
    /// Whether view `v`'s tab is a preview.
    pub fn isPreview(v: u8) bool {
        return view_preview[v];
    }
    /// The active view's index.
    pub fn activeIndex() u8 {
        return vl.active;
    }
    /// Whether a window's + pop-up is open.
    pub fn addingView() bool {
        return tab_add_leaf != null;
    }
    /// The dropdown in the row tagged `tag` takes entry `label` next frame.
    pub fn choose(tag: []const u8, label: []const u8) void {
        test_choice = .{ .tag = tag, .label = label };
    }
    /// Whether a choice asked for is still waiting (its row not drawn, or
    /// no such entry).
    pub fn choicePending() bool {
        return test_choice != null;
    }
    /// Canvas point `p` (mm) on the screen (physical pixels), while the
    /// canvas is shown.
    pub fn toScreen(p: geom.Point) ?dvui.Point.Physical {
        const area = canvas_px orelse return null;
        return state.view.toPx(area, p);
    }
    /// Each pane's mode and where it was drawn, for a test's report.
    pub fn describePanes() void {
        for (all_panes) |p| std.debug.print("pane {s}: {s}, size {d}, rect {any}\n", .{ p.id, @tagName(p.mode), p.size, p.rect_px });
    }
    /// The middle of the key named `designator` on the screen, as placed
    /// now (its body's centre).
    pub fn tileCenter(designator: []const u8) ?dvui.Point.Physical {
        const id = state.model.findTile(designator) orelse return null;
        const f = findTile(id) orelse return null;
        const b = onSheet(f.parent, f.tile.body);
        return toScreen(.{ .x = (b.x0 + b.x1) / 2, .y = (b.y0 + b.y1) / 2 });
    }
    /// While an expression is edited on the canvas: its objects' boxes
    /// (not fields'), in drawing order (parts before what holds them), as
    /// screen rectangles; and the one chosen's kind.
    pub fn eqBoxes(out: []dvui.Rect.Physical) []dvui.Rect.Physical {
        var n: usize = 0;
        for (state.solved.items, 0..) |placed, k| {
            const pi = state.model.parentAt(k);
            const o = parentOrigin(pi);
            for (placed.labels) |l| {
                _ = eqPiece(pi, l) orelse continue;
                for (l.render.boxes) |b| {
                    if (b.kind == .field or n >= out.len) continue;
                    const bb = boxBounds(b);
                    const p0 = toScreen(.{ .x = bb.x0 + l.origin.x + o.x, .y = bb.y1 + l.origin.y + o.y }) orelse continue;
                    const p1 = toScreen(.{ .x = bb.x1 + l.origin.x + o.x, .y = bb.y0 + l.origin.y + o.y }) orelse continue;
                    out[n] = .{ .x = @min(p0.x, p1.x), .y = @min(p0.y, p1.y), .w = @abs(p1.x - p0.x), .h = @abs(p1.y - p0.y) };
                    n += 1;
                }
            }
        }
        return out[0..n];
    }
    pub fn eqChosenKind() ?glyphic.Kind {
        const c = eqChoice(dvui.currentWindow().arena()) orelse return null;
        return c.kind;
    }
    pub fn shownSpace() usize {
        return shown_space;
    }
    pub fn contextIsCanvas() bool {
        return switch (state.context) {
            .space => |si| si < state.model.spaces.items.len,
            else => false,
        };
    }
    pub fn contextTile() ?[]const u8 {
        return switch (state.context) {
            .tile => |id| state.model.tileConst(id).designator,
            else => null,
        };
    }
    /// The last tile in the document not removed: its designator.
    pub fn lastTile() ?[]const u8 {
        var i = state.model.tiles.items.len;
        while (i > 0) {
            i -= 1;
            if (!state.model.tiles.items[i].removed) return state.model.tiles.items[i].designator;
        }
        return null;
    }
    pub fn contextRegionName() ?[]const u8 {
        return switch (state.context) {
            .region => |r| state.model.regionsIn(r.parent)[r.region].name,
            else => null,
        };
    }
    pub fn flowCursor() bool {
        return track_cursor != null;
    }
    pub fn eqEditing() bool {
        return canvas_eq != null;
    }
    pub fn eqPicking() bool {
        const q = canvas_eq orelse return false;
        return q.head != null;
    }
    pub fn eqMeasured() bool {
        const q = canvas_eq orelse return false;
        const m = eq_measure orelse return false;
        return m.of.offset == q.offset and std.meta.eql(m.of.head, q.head) and std.meta.eql(m.of.head_end, q.head_end);
    }
    /// A point just inside tile `designator`'s outline (its left edge's
    /// middle): pointing there selects the tile, not its content.
    pub fn tileEdge(designator: []const u8) ?dvui.Point.Physical {
        const id = state.model.findTile(designator) orelse return null;
        const f = findTile(id) orelse return null;
        const b = onSheet(f.parent, f.tile.body);
        return toScreen(.{ .x = b.x0 + 0.3 * edgeMm(), .y = (b.y0 + b.y1) / 2 });
    }
    /// The screen box of tile `designator`'s first slot text set.
    pub fn anySlotRect(designator: []const u8) ?dvui.Rect.Physical {
        const id = state.model.findTile(designator) orelse return null;
        for (state.solved.items, 0..) |placed, pk| for (placed.labels) |l| {
            if (l.tile == null or l.tile.? != id) continue;
            const b = labelBox(state.model.parentAt(pk), l);
            const p0 = toScreen(.{ .x = b.x0, .y = b.y1 }) orelse return null;
            const p1 = toScreen(.{ .x = b.x1, .y = b.y0 }) orelse return null;
            return .{ .x = @min(p0.x, p1.x), .y = @min(p0.y, p1.y), .w = @abs(p1.x - p0.x), .h = @abs(p1.y - p0.y) };
        };
        return null;
    }
    /// The screen box of tile `designator`'s slot `slot`'s text.
    pub fn slotRect(designator: []const u8, slot: []const u8) ?dvui.Rect.Physical {
        const id = state.model.findTile(designator) orelse return null;
        const tracks = state.model.prototypeOf(id).tracks;
        const k = for (tracks, 0..) |t, i| {
            if (std.mem.eql(u8, t.name, slot)) break i;
        } else return null;
        for (state.solved.items, 0..) |placed, pk| for (placed.labels) |l| {
            if (l.tile == null or l.tile.? != id or l.slot != k) continue;
            const b = labelBox(state.model.parentAt(pk), l);
            const p0 = toScreen(.{ .x = b.x0, .y = b.y1 }) orelse return null;
            const p1 = toScreen(.{ .x = b.x1, .y = b.y0 }) orelse return null;
            return .{ .x = @min(p0.x, p1.x), .y = @min(p0.y, p1.y), .w = @abs(p1.x - p0.x), .h = @abs(p1.y - p0.y) };
        };
        return null;
    }
    pub fn screenOf(x: f64, y: f64) ?dvui.Point.Physical {
        return toScreen(.{ .x = x, .y = y });
    }
    pub fn guides() []const layout.model.Guide {
        if (shown_space >= state.model.spaces.items.len) return &.{};
        return state.model.spaces.items[shown_space].guides.items;
    }
    pub fn boundaryMode() bool {
        return boundary_mode;
    }
    pub fn setBoundaryMode(on: bool) void {
        boundary_mode = on;
    }
    /// A point just inside panel `name`'s left edge, mid-height.
    pub fn panelEdge(name: []const u8) ?dvui.Point.Physical {
        const pi = panelNamed(name) orelse return null;
        const b = state.model.panels.items[pi].box();
        return toScreen(.{ .x = b.x0 + 0.3 * edgeMm(), .y = (b.y0 + b.y1) / 2 });
    }
    pub fn handleCount() usize {
        var hb: [8]Handle = undefined;
        return resizeHandles(&hb);
    }
    /// The screen x of the left edges of glyphs `from` to `to` (exclusive,
    /// counting from 0 in drawing order) of tile `designator`'s slot `slot`.
    pub fn slotGlyphs(designator: []const u8, slot: []const u8, from: usize, to: usize) ?[3]f32 {
        const id = state.model.findTile(designator) orelse return null;
        const tracks = state.model.prototypeOf(id).tracks;
        const k = for (tracks, 0..) |t, i| {
            if (std.mem.eql(u8, t.name, slot)) break i;
        } else return null;
        var out: [3]f32 = undefined;
        for (state.solved.items, 0..) |placed, pk| for (placed.labels) |l| {
            if (l.tile == null or l.tile.? != id or l.slot != k) continue;
            const o = parentOrigin(state.model.parentAt(pk));
            var n: usize = 0;
            for (l.render.items) |it| switch (it) {
                .glyph => |gl| {
                    if (n >= from and n < to and n - from < out.len) {
                        const p = toScreen(.{ .x = gl.transform.e + l.origin.x + o.x, .y = l.origin.y + o.y }) orelse return null;
                        out[n - from] = p.x;
                    }
                    n += 1;
                },
                else => {},
            };
            return out;
        };
        return null;
    }
    pub fn hoverKind() ?[]const u8 {
        return if (hover_target) |t| @tagName(t) else null;
    }
    pub fn eqText() ?[]const u8 {
        const q = canvas_eq orelse return null;
        return eqContent(q);
    }
    pub fn promptOpen() bool {
        return filePromptOpen() or contention != null or leave_prompt != null or recovery != null;
    }
    pub fn canvasHasKeyboard() bool {
        return if (canvas_id) |id| dvui.focusedWidgetId() == id else false;
    }
    pub fn selectionCount() usize {
        return selection.items.len;
    }
    pub fn panelEditing() bool {
        return panel_edit != null;
    }
    pub fn toolName() []const u8 {
        return @tagName(state.tool);
    }
    pub fn canvasRect() ?dvui.Rect.Physical {
        return canvas_px;
    }
    pub fn contextName() []const u8 {
        return @tagName(state.context);
    }
    /// Adds the text sample (a track of three rows, two holding content)
    /// on the shown canvas, as GRAVEN_SAMPLE=text does; where it starts.
    pub fn loadTextSample() !geom.Point {
        return loadText();
    }
    /// The columns sample (GRAVEN_SAMPLE=columns): three text columns in
    /// a panel and two construction lines, constrained or not.
    pub fn loadColumns(constrained: bool) !void {
        return loadColumnsSampleWith(constrained);
    }
    pub fn objectsMenuOpen() bool {
        return constrain_objects_menu;
    }
    pub fn constraintPromptOpen() bool {
        return constrain_prompt != null;
    }
    pub fn constraintAt(i: usize) layout.model.Constraint {
        return state.model.constraints.items[i];
    }
    pub fn constraintCount() usize {
        return state.model.constraints.items.len;
    }
    /// The box of the object at name path `path`, in its parent's frame.
    pub fn boxAt(path: []const u8) ?geom.Box {
        const ref = state.model.resolve(path) orelse return null;
        return constrain.boxOf(&state.model, objectOfContext(contextOfRef(ref) orelse return null) orelse return null);
    }
    /// Chooses the objects at name paths `paths` together, as Ctrl-clicks
    /// do. False when one has no such name.
    pub fn chooseAll(paths: []const []const u8) bool {
        selection.clearRetainingCapacity();
        for (paths) |path| {
            const ref = state.model.resolve(path) orelse return false;
            const id = objectOfContext(contextOfRef(ref) orelse return false) orelse return false;
            selection.append(state.gpa, id) catch return false;
        }
        track_cursor = null;
        state.context = .selection;
        dvui.refresh(null, @src(), null);
        return true;
    }
    /// Imports the SVG file at `path` as a figure, as File, Import figure
    /// does; its index, null when nothing was imported.
    /// The document's figures' names, in the Browser's order.
    pub fn figureNames(a: std.mem.Allocator) ![]const []const u8 {
        const out = try a.alloc([]const u8, state.model.figures.items.len);
        for (state.model.figures.items, out) |f, *n| n.* = f.name;
        return out;
    }
    pub fn importFigureFile(path: []const u8) ?usize {
        const n = state.model.figures.items.len;
        importFigure(path);
        return if (state.model.figures.items.len > n) n else null;
    }
    // Scripting by name (decided 2026-11-20): objects by name path, UI
    // elements by id (see "Element ids"), through the paths a person's
    // input takes. Each takes effect in the next frame.

    /// Makes the object at name path `path` the context, as choosing it in
    /// the Browser does. False when nothing has that name.
    pub fn select(path: []const u8) bool {
        const ref = state.model.resolve(path) orelse return false;
        const ctx = contextOfRef(ref) orelse return false;
        track_cursor = null;
        state.context = ctx;
        dvui.refresh(null, @src(), null);
        return true;
    }
    /// Puts the flow cursor at item `index` of the flow of the track (or
    /// the flow) at `path`, the track made the context. False when the
    /// path names neither, or the flow is shorter.
    pub fn cursor(path: []const u8, index: usize) bool {
        const ref = state.model.resolve(path) orelse return false;
        const t: layout.model.TrackRef = switch (ref) {
            .region => |r| .{ .parent = r.parent, .region = r.region },
            .flow => |id| blk: {
                const fi = state.model.flowIndex(id) orelse return false;
                const f = state.model.flows.items[fi];
                if (f.tracks.items.len == 0) return false;
                const tr = state.model.trackById(f.tracks.items[0]) orelse return false;
                break :blk tr;
            },
            else => return false,
        };
        const head = state.model.threadHead(t.parent, t.region);
        if (index > state.model.flowItems(head.parent, head.region).len) return false;
        state.context = .{ .region = .{ .parent = t.parent, .region = t.region } };
        track_cursor = .{ .parent = head.parent, .region = head.region, .index = index };
        dvui.refresh(null, @src(), null);
        return true;
    }
    /// One step down the discovery path: the groups and elements directly
    /// in group `group` ("" for the top), each with whether it is on
    /// screen now and where (from the last frame drawn).
    pub const Discovered = struct { child: elements.Child, shown: bool, rect: dvui.Rect.Physical = .{} };
    pub fn discover(group: []const u8, out: []Discovered) []Discovered {
        var buf: [128]elements.Child = undefined;
        const kids = elements.children(group, &buf);
        const n = @min(kids.len, out.len);
        for (kids[0..n], out[0..n]) |c, *f| {
            f.* = .{ .child = c, .shown = false };
            if (c.group) {
                // A group is shown when any element in it is.
                var it = dvui.currentWindow().tags.map.iterator();
                while (it.next()) |e| {
                    if (!std.mem.startsWith(u8, e.key_ptr.*, c.id) or e.key_ptr.len <= c.id.len or e.key_ptr.*[c.id.len] != '.') continue;
                    if (dvui.tagGet(e.key_ptr.*)) |d| if (d.visible) {
                        f.shown = true;
                    };
                }
            } else if (dvui.tagGet(c.id)) |d| {
                f.shown = d.visible;
                f.rect = d.rect;
            }
        }
        return out[0..n];
    }
    /// Gives the field with id `id` the text `text`, as if typed there and
    /// accepted.
    pub fn setField(id: []const u8, text: []const u8) void {
        accepted.setScripted(id, text);
        dvui.refresh(null, @src(), null);
    }
    /// Whether a field is still to take a script's text (it was not drawn).
    pub fn fieldPending() bool {
        return accepted.script != null;
    }
    /// Whether the field given a script's text last refused it.
    pub fn fieldRefused() bool {
        return accepted.script_refused;
    }
    /// Presses the button, menu item, tool or checkbox with id `id`.
    pub fn press(id: []const u8) void {
        const n = @min(id.len, scripted_press_buf.len);
        @memcpy(scripted_press_buf[0..n], id[0..n]);
        scripted_press = scripted_press_buf[0..n];
        dvui.refresh(null, @src(), null);
    }
    /// The registry's button actions with no handler (none should be).
    pub fn unhandledButtons(out: [][]const u8) [][]const u8 {
        var n: usize = 0;
        for (elements.button_actions) |name| if (!buttonHandled(name)) {
            if (n < out.len) out[n] = name;
            n += 1;
        };
        return out[0..@min(n, out.len)];
    }
    /// A press asked for and not taken, given up.
    pub fn cancelPress() void {
        scripted_press = null;
    }
    /// Whether a press asked for is still waiting (nothing with its id was
    /// drawn).
    pub fn pressPending() bool {
        return scripted_press != null;
    }
    /// Runs the app's action named `name` (file.save, edit.undo, view.…)
    /// with `arg`, as its menu item or key does. False when no such action
    /// or it cannot be done now.
    pub fn run(name: []const u8, arg: i32) bool {
        for (0..keymap.R.action_count) |k| {
            const a: keymap.ActionId = @intCast(k);
            if (std.mem.eql(u8, keymap.R.actionName(a), name)) return runAction(.{ .action = a, .arg = arg });
        }
        return false;
    }

    /// The keyboard leaves whatever field has it, at the next frame's
    /// start, as a click elsewhere or Tab would take it away.
    pub fn leaveField() void {
        leave_field = true;
    }
    /// The undo history's length, in steps.
    pub fn undoSteps() usize {
        return hist.log.items.len;
    }
    /// Grid `gi` of panel `pi`'s point at `col`, `row` on the screen.
    pub fn gridPoint(pi: usize, gi: usize, col: u32, row: u32) ?dvui.Point.Physical {
        const p: Parent = .{ .panel = pi };
        return toScreen(onSheetPoint(p, state.model.gridPoint(p, gi, @floatFromInt(col), @floatFromInt(row))));
    }
    pub fn panelNamed(name: []const u8) ?usize {
        for (state.model.panels.items, 0..) |p, i| if (std.mem.eql(u8, p.name, name)) return i;
        return null;
    }
    /// The view centred on tile `designator`, at `ppm` px/mm.
    pub fn centreOnTile(designator: []const u8, ppm: f64) void {
        const id = state.model.findTile(designator) orelse return;
        const f = findTile(id) orelse return;
        const b = onSheet(f.parent, f.tile.body);
        setView((b.x0 + b.x1) / 2, (b.y0 + b.y1) / 2, ppm);
        dvui.refresh(null, @src(), null);
    }
    /// Where the active canvas looks: centre (mm) and zoom (px/mm).
    pub fn viewNow() struct { cx: f64, cy: f64, ppm: f64 } {
        return .{ .cx = state.view.cx, .cy = state.view.cy, .ppm = state.view.ppm };
    }
    /// The canvas's clear part (what pinned panes leave), and the context's
    /// box on screen when it has a place of its own: for checking reveals.
    pub fn canvasClear() ?dvui.Rect.Physical {
        return if (canvas_free) |cf| cf.free else null;
    }
    pub fn contextOnScreen() ?dvui.Rect.Physical {
        const b = revealBox() orelse return null;
        const cf = canvas_free orelse return null;
        return state.view.rect(cf.area, b);
    }
    /// The flow cursor's box on screen, if there is one.
    pub fn cursorOnScreen() ?dvui.Rect.Physical {
        const c = track_cursor orelse return null;
        const b = cursorBox(c) orelse return null;
        const cf = canvas_free orelse return null;
        return state.view.rect(cf.area, b);
    }
    pub fn setView(cx: f64, cy: f64, ppm: f64) void {
        state.view.cx = cx;
        state.view.cy = cy;
        state.view.ppm = ppm;
        state.view.fit = null;
    }
    pub fn history() *layout.history.History {
        return &hist;
    }
    pub fn statusText() []const u8 {
        return state.status;
    }
};
pub const panic = dvui.App.panic;
pub const std_options: std.Options = .{ .logFn = dvui.App.logFn };

/// The bundled example font, relative to the repository root. The GUI opens
/// with an installed Inter Medium if fontconfig finds one (system or user
/// fonts), else this file when run from the repository root, else the first
/// font found.
const example_font = "examples/fonts/Inter-Medium.otf";

const Font = struct {
    name: []const u8,
    path: []const u8,
    /// Face index within a collection (.ttc, .otc); 0 for a single font.
    index: u32 = 0,
    family: []const u8 = "",
    style: []const u8 = "",
};

const State = struct {
    gpa: std.mem.Allocator,
    fonts: []Font = &.{},
    font_choice: usize = 0,
    font_loaded: ?usize = null,
    face: ?*layout.Face = null,
    faces: [1]*layout.Face = undefined,
    model: Model,
    labels: ?layout.Labels = null,
    /// One solve per panel, in the panel's own frame.
    /// Each parent placed, by `Model.parentSlot`: the workspaces, then
    /// the panels (see `placedOf`).
    solved: std.ArrayList(layout.place.Placed) = .empty,
    placed_rev: u64 = std.math.maxInt(u64),
    /// Labels whose ink reaches into the worksheet's margins.
    intrusions: []layout.drc.MarginIntrusion = &.{},
    /// Panels out of compliance, as sheet and margin changes can leave them.
    panel_issues: []layout.drc.PanelIssue = &.{},
    /// Layers the checks flag (see `Model.layerIssues`).
    layer_issues: []layout.model.LayerIssue = &.{},
    /// The canvas tool, and a rectangle being dragged out with it.
    tool: Tool = .select,
    drag: ?struct { start: geom.Point, at: geom.Point } = null,
    /// The pointer's position on the worksheet, mm; null off the canvas.
    mouse: ?geom.Point = null,
    /// The press was used by a tool, so its release does not pick.
    press_consumed: bool = false,
    /// Where the pointer went down on the canvas, mm.
    press_at: ?geom.Point = null,
    /// A selected panel being dragged to a new place: shown at its preview
    /// position, committed on release.
    moving: ?struct { panel: usize, start: geom.Point, at: geom.Point } = null,
    /// The style new runs get, made with the first one; its size is the
    /// app's choice until the user sets it.
    label_style: ?layout.model.StyleId = null,
    label_style_set: bool = false,
    solve_ms: f64 = 0,
    flat: Flat,
    view: View = .{},
    /// The file's name; a new file is untitled until saved or renamed.
    file_name: []const u8 = "untitled",
    /// Whether the user has given the file name and the legend font. Until
    /// then they are the app's choices, shown in italic.
    file_name_set: bool = false,
    font_set: bool = false,
    /// What the tree, canvas, tools and properties are about.
    context: Context = .worksheet,
    /// Tree nodes the user has opened or closed, by context key.
    expanded: std.AutoHashMapUnmanaged(u64, bool) = .empty,
    status: []const u8 = "",
};

/// What a canvas drag does: pick things, or draw out a new panel.
const Tool = enum { select, construction, add_panel, add_tracks, add_art, select_area, constrain, join, new_sketch, insert_figure, add_array };

/// The array tool's choices (its drop): the cell counts across and down.
/// Apply arms the tool; a drag then lays the array's cells over the area
/// dragged, as a grid (the shared primitive: its points are the cells'
/// centres) on the canvas, a frame or a panel.
var array_tool: struct {
    cols: u32 = 4,
    rows: u32 = 3,
    /// A polar array: `cols` round a centre, `rows` rings; dragged out
    /// from the centre to its outer edge.
    polar: bool = false,
    around: u32 = 8,
    rings: u32 = 1,
    /// How far round it goes, degrees (360: all the way).
    sweep: f64 = 360,
} = .{};

/// The figure Insert figure places (its id), chosen in the Browser.
var insert_figure: layout.model.ObjectId = .none;

/// Join: the track a click on another track threads on into.
var join_from: ?struct { parent: Parent, region: usize } = null;

/// What Add shape draws: a closed path, dragged out as a box (a polygon
/// is clicked corner by corner).
const ShapeKind = enum { rect, rounded, circle, ellipse, slot, polygon };
var shape_kind: ShapeKind = .rounded;
/// A polygon's corners so far, on panel `polygon_panel`, worksheet mm.
var polygon_pts: std.ArrayList(geom.Point) = .empty;
var polygon_panel: usize = 0;

/// The Add tracks tool's choices: what sizes the rows or columns (a tile
/// prototype, or a text style), and which way the tracks run.
var tracks_tool: struct {
    size_to: SizeTo = .{ .prototype = .none },
    major: layout.model.Major = .row,
    /// A region (rows or columns added as content needs them) or one
    /// track laid out in advance, running the way it is drawn.
    kind: layout.model.TileRegion.Kind = .region,
} = .{};

/// What new tracks are sized to: a tile prototype's smallest tile, or a
/// text style's line pitch. A null style is the default Label style, made
/// when the tracks are.
const SizeTo = union(enum) {
    prototype: layout.model.PrototypeId,
    style: ?layout.model.StyleId,
};

/// The current context: a node of the component tree.
const Context = union(enum) {
    /// The file: everything, the worksheet included.
    file,
    worksheet,
    /// A workspace: the canvas, or a frame (by index).
    space: usize,
    panel: usize,
    region: struct { parent: Parent, region: usize },
    row: struct { parent: Parent, region: usize, row: usize },
    tile: TileId,
    /// Line art placed on a panel.
    art: struct { panel: usize, index: usize },
    /// A selection group of a space.
    group: layout.model.ObjectId,
    /// Objects picked together with Select area (see `selection`).
    selection,
    /// A view of another space, placed in space `space`.
    view: struct { space: usize, index: usize },
    /// A layer of a space.
    layer: struct { space: usize, index: usize },
    /// A raster image placed in a space.
    image: struct { space: usize, index: usize },
    /// A figure placed in a space.
    figure_place: struct { space: usize, index: usize },
    /// A construction line of a space.
    guide: struct { space: usize, index: usize },
    /// A view of a sketch, placed in a space.
    sketch: struct { space: usize, index: usize },
    /// The document's sketches, and one of them.
    sketches,
    sketch_def: usize,
    /// The document's figures (line art kept as prototypes), and one.
    figures,
    figure_def: usize,
    /// A grid on a panel.
    grid: struct { parent: Parent, index: usize },
    /// The file's tile prototypes, and one of them.
    prototypes,
    prototype: layout.model.PrototypeId,
    /// The document's flows, and one of them.
    flows,
    flow: layout.model.ObjectId,
    /// The document's legend sheets, and one of them.
    sheets,
    sheet: layout.model.ObjectId,
    /// The document's text styles, and one of them.
    styles,
    style: layout.model.StyleId,
    /// The document's style templates (each new flow's style is copied
    /// from one), and one of them.
    templates,
    template: layout.model.ObjectId,
    /// The document's process profiles, and one of them.
    processes,
    process: layout.model.ObjectId,
    /// Its manufacturing plans and materials, and one of each.
    plans,
    plan: layout.model.ObjectId,
    materials,
    material: layout.model.ObjectId,
    /// Every layout constraint in the document (the abandoned among them),
    /// and one of them.
    constraints,
    constraint: layout.model.ObjectId,

    fn key(c: Context) u64 {
        var h: std.hash.Wyhash = .init(0);
        std.hash.autoHash(&h, c);
        return h.final();
    }

    fn eql(a: Context, b: Context) bool {
        return std.meta.eql(a, b);
    }

    fn kindName(c: Context) []const u8 {
        return switch (c) {
            .file => "File",
            .worksheet => "Worksheet",
            .panel => "Panel",
            // A track laid out in advance is a track, not a region.
            .space => |si| if (si == 0) "Canvas" else "Frame",
            .region => |r| if (state.model.hasParent(r.parent) and r.region < state.model.regionsIn(r.parent).len and state.model.regionsIn(r.parent)[r.region].kind == .track) "Content layout: single track" else "Content layout",
            .row => "Row",
            .tile => "Tile",
            .art => "Line art",
            .figure_place => "Placed figure",
            .group => "Group",
            .selection => "Selection",
            .view => "View",
            .layer => "Layer",
            .image => "Image",
            .guide => "Construction line",
            .sketch => "Sketch view",
            .sketches => "Sketches",
            .sketch_def => "Sketch",
            .figures => "Figures",
            .figure_def => "Figure",
            .grid => "Grid",
            .prototypes => "Tile prototypes",
            .prototype => "Tile prototype",
            .flows => "Flows",
            .flow => "Flow",
            .sheets => "Legend sheets",
            .sheet => "Legend sheet",
            .styles => "Text styles",
            .style => "Text style",
            .templates => "Style templates",
            .template => "Style template",
            .processes => "Processes",
            .process => "Process profile",
            .plans => "Manufacturing plans",
            .plan => "Manufacturing plan",
            .materials => "Materials",
            .material => "Material",
            .constraints => "Constraints",
            .constraint => "Constraint",
        };
    }
};

/// The canvas view: the mm point at the canvas centre, and physical pixels
/// per mm. While `fit` holds a box, the view keeps that box centred and
/// filling the canvas (through window resizes) until the user zooms or pans.
const View = struct {
    cx: f64 = 0,
    cy: f64 = 0,
    ppm: f64 = 0,
    fit: ?geom.Box = null,

    fn toPx(v: View, area: dvui.Rect.Physical, p: geom.Point) dvui.Point.Physical {
        return .{
            .x = @floatCast(area.x + area.w / 2 + (p.x - v.cx) * v.ppm),
            .y = @floatCast(area.y + area.h / 2 - (p.y - v.cy) * v.ppm),
        };
    }

    fn toMm(v: View, area: dvui.Rect.Physical, p: dvui.Point.Physical) geom.Point {
        return .{
            .x = v.cx + (p.x - area.x - area.w / 2) / v.ppm,
            .y = v.cy - (p.y - area.y - area.h / 2) / v.ppm,
        };
    }

    fn rect(v: View, area: dvui.Rect.Physical, b: geom.Box) dvui.Rect.Physical {
        const tl = v.toPx(area, .{ .x = b.x0, .y = b.y1 });
        const br = v.toPx(area, .{ .x = b.x1, .y = b.y0 });
        return .{ .x = tl.x, .y = tl.y, .w = br.x - tl.x, .h = br.y - tl.y };
    }
};

/// What a filled shape came from: ink, faint preview text (source shown
/// literally while it is not valid), or a placeholder for what is to come.
const PieceKind = enum { ink, faint, placeholder };

/// One item's outline, flattened and resolved: its overlaps removed, as
/// simple loops and the triangles that fill them.
const Piece = struct { region: geom.fill.Region, kind: PieceKind };

/// Label outlines flattened to polylines in mm and triangulated, per
/// render, at a tolerance matched to the zoom. Rebuilt when the zoom
/// changes a lot or the panel is re-solved (renders may be freed then).
/// One shape of a tile's art, flattened: its region for the fill and its
/// contours as drawn for the edge.
const TilePiece = struct {
    shape: *const layout.art.Shape,
    region: geom.fill.Region,
    lines: []const []const geom.Point,
};

const Flat = struct {
    arena: std.heap.ArenaAllocator,
    map: std.AutoHashMapUnmanaged(*const layout.Render, []const Piece) = .empty,
    /// As `map`, with glyphs left empty: what is drawn from outlines when
    /// glyphs come from the atlas.
    paths: std.AutoHashMapUnmanaged(*const layout.Render, []const Piece) = .empty,
    /// Tile art, by its placed shapes (owned by the placement, which resets
    /// this cache when it changes).
    tiles: std.AutoHashMapUnmanaged([*]const layout.art.Shape, []const TilePiece) = .empty,
    tol: f64 = 0,

    fn reset(f: *Flat, tol: f64) void {
        f.map = .empty;
        f.paths = .empty;
        f.tiles = .empty;
        _ = f.arena.reset(.retain_capacity);
        f.tol = tol;
    }

    fn get(f: *Flat, r: *const layout.Render, faces: []const *layout.Face) ![]const Piece {
        return f.getWith(r, faces, false);
    }

    /// Item for item; with `paths_only`, glyphs' pieces empty.
    fn getWith(f: *Flat, r: *const layout.Render, faces: []const *layout.Face, paths_only: bool) ![]const Piece {
        const cache = if (paths_only) &f.paths else &f.map;
        if (cache.get(r)) |c| return c;
        const a = f.arena.allocator();
        var contours: std.ArrayList(Piece) = .empty;
        for (r.items) |item| {
            if (paths_only and item == .glyph) {
                try contours.append(a, .{ .region = .{ .loops = &.{}, .triangles = &.{} }, .kind = .ink });
                continue;
            }
            const o = switch (item) {
                .glyph => |g| try layout.render.glyphOutline(a, faces[g.face], g),
                .path => |p| p.outline,
            };
            const kind: PieceKind = switch (item) {
                .glyph => |g| if (g.faint) .faint else .ink,
                .path => |p| if (p.role == .placeholder) .placeholder else .ink,
            };
            // Overlaps resolved here, once: glyphs from variable fonts keep
            // overlapping and self-crossing contours, which DVUI's
            // triangulator fills wrongly. The triangles are drawn as they are.
            const polys = try a.alloc([]const geom.Point, o.contours.len);
            for (o.contours, polys) |c, *poly| {
                var pts: std.ArrayList(geom.Point) = .empty;
                for (c.segments) |s| try flatten(a, &pts, s, f.tol);
                poly.* = pts.items;
            }
            try contours.append(a, .{ .region = try geom.fill.nonzero(a, polys, f.tol * 0.1), .kind = kind });
        }
        const out = contours.items;
        try cache.put(a, r, out);
        return out;
    }
};

/// A tile's art shapes flattened and resolved, made once per placement and
/// zoom.
fn flatTile(f: *Flat, shapes: []const layout.art.Shape) ![]const TilePiece {
    if (shapes.len == 0) return &.{};
    if (f.tiles.get(shapes.ptr)) |c| return c;
    const a = f.arena.allocator();
    const out = try a.alloc(TilePiece, shapes.len);
    for (shapes, out) |*s, *piece| {
        const lines = try a.alloc([]const geom.Point, s.outline.contours.len);
        for (s.outline.contours, lines) |c, *line| {
            var pts: std.ArrayList(geom.Point) = .empty;
            for (c.segments) |seg| try flatten(a, &pts, seg, f.tol);
            line.* = pts.items;
        }
        piece.* = .{ .shape = s, .region = try geom.fill.nonzero(a, lines, f.tol * 0.1), .lines = lines };
    }
    try f.tiles.put(a, shapes.ptr, out);
    return out;
}

/// Strokes an outline's contours placed at worksheet point `at`.
fn strokeOutline(area: dvui.Rect.Physical, o: geom.Outline, at: geom.Point, width: f32, color: dvui.Color) void {
    const arena = dvui.currentWindow().arena();
    for (o.contours) |c| {
        var pts: std.ArrayList(geom.Point) = .empty;
        // Each segment adds the points after its start: the loop closes on
        // the last one, so the first point is not repeated.
        for (c.segments) |seg| flatten(arena, &pts, seg, state.flat.tol) catch return;
        strokeLoop(area, pts.items, at, width, color);
    }
}

/// Strokes a closed polyline placed at worksheet point `at`.
fn strokeLoop(area: dvui.Rect.Physical, line: []const geom.Point, at: geom.Point, width: f32, color: dvui.Color) void {
    if (line.len < 2) return;
    const lifo = dvui.currentWindow().lifo();
    const pts = lifo.alloc(dvui.Point.Physical, line.len) catch return;
    defer lifo.free(pts);
    for (line, pts) |q, *out| out.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
    glowUnder(pts, true, width, color);
    dvui.Path.stroke(.{ .points = pts }, .{ .thickness = width, .color = .{ .color = color }, .closed = true });
}

/// Appends a segment's points after its start, within `tol` of the curve.
fn flatten(a: std.mem.Allocator, pts: *std.ArrayList(geom.Point), s: geom.Segment, tol: f64) !void {
    switch (s) {
        .line => |p| try pts.append(a, p[1]),
        .conic => |c| {
            // Sampled by angle: enough pieces that each chord stays within
            // `tol` of the curve.
            const e = c.ellipse();
            const r = @max(@sqrt(e.a.x * e.a.x + e.a.y * e.a.y), @sqrt(e.b.x * e.b.x + e.b.y * e.b.y));
            const step = 2 * std.math.acos(@max(0, 1 - tol / @max(r, 1e-12)));
            const n: usize = @max(2, @min(256, @as(usize, @intFromFloat(@ceil(2 * e.half / @max(step, 1e-6))))));
            for (1..n + 1) |i| try pts.append(a, c.at(@as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(n))));
        },
        .quad => |p| {
            const dev = 0.25 * @sqrt(sq(p[0].x - 2 * p[1].x + p[2].x) + sq(p[0].y - 2 * p[1].y + p[2].y));
            const n: usize = @max(1, @as(usize, @intFromFloat(@ceil(@sqrt(dev / tol)))));
            for (1..n + 1) |i| {
                const t: f64 = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(n));
                const u = 1 - t;
                try pts.append(a, .{
                    .x = u * u * p[0].x + 2 * u * t * p[1].x + t * t * p[2].x,
                    .y = u * u * p[0].y + 2 * u * t * p[1].y + t * t * p[2].y,
                });
            }
        },
        .cubic => |p| {
            const d1 = @sqrt(sq(p[0].x - 2 * p[1].x + p[2].x) + sq(p[0].y - 2 * p[1].y + p[2].y));
            const d2 = @sqrt(sq(p[1].x - 2 * p[2].x + p[3].x) + sq(p[1].y - 2 * p[2].y + p[3].y));
            const dev = 0.75 * @max(d1, d2);
            const n: usize = @max(1, @as(usize, @intFromFloat(@ceil(@sqrt(dev / tol)))));
            for (1..n + 1) |i| {
                const t: f64 = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(n));
                const u = 1 - t;
                try pts.append(a, .{
                    .x = u * u * u * p[0].x + 3 * u * u * t * p[1].x + 3 * u * t * t * p[2].x + t * t * t * p[3].x,
                    .y = u * u * u * p[0].y + 3 * u * u * t * p[1].y + 3 * u * t * t * p[2].y + t * t * t * p[3].y,
                });
            }
        },
    }
}

fn sq(x: f64) f64 {
    return x * x;
}

var state: State = undefined;

fn init(win: *dvui.Window) !void {
    const gpa = win.gpa;
    initWindowFrame(win);
    // Match the desktop now, then follow its changes.
    main_window = win;
    // The whole interface in DejaVu Sans (`ui_fonts`, set with the theme in
    // `applyDesktop`); fields and cells say so too.
    ghost_pane.field_family = "DejaVu Sans";
    const settings = desktop.read(gpa, dvui.io);
    applyDesktop(win, settings);
    desktop.watch(dvui.io, settings, wakeGui);
    state = .{ .gpa = gpa, .model = .init(gpa), .flat = .{ .arena = .init(gpa) } };
    hist = .init(gpa);
    initWriter();
    // Work starts on a canvas, not a worksheet: the user picks its units.
    state.model.has_sheet = false;
    const installed: []Font = listFonts(gpa) catch &.{};
    if (std.Io.Dir.cwd().access(dvui.io, example_font, .{})) |_| {
        const fonts = try gpa.alloc(Font, installed.len + 1);
        fonts[0] = .{ .name = "Inter Medium (examples)", .path = example_font, .family = "Inter", .style = "Medium" };
        @memcpy(fonts[1..], installed);
        gpa.free(installed);
        state.fonts = fonts;
    } else |_| {
        state.fonts = installed;
    }
    state.font_choice = defaultFont(state.fonts);
    loadPrefs();
    // The display correction the config (or GRAVEN_DISPLAY) sets.
    applyDesktop(win, desk);
    // This version's news for the start screen: the cache at once, a
    // fetch (at most daily) on a thread of its own.
    motd.start(state.gpa, dvui.io, layout.version);
}

/// Asking for a new canvas's units, before anything is drawn.
var canvas_prompt = true;
/// The units the last canvas was made in: the next one's default. (Kept
/// for the session; shared preferences will keep it across sessions.)
var last_units: layout.model.Units = .mm;

/// The part of the canvas a new one first shows, mm: its origin near the
/// bottom left.
const canvas_view: geom.Box = .{ .x0 = -15, .y0 = -15, .x1 = 185, .y1 = 120 };

/// The space the canvas shows: the canvas itself (0), or a frame.
var shown_space: usize = 0;

/// Objects picked together with Select area, all in the shown space.
var selection: std.ArrayList(layout.model.ObjectId) = .empty;

/// The shown workspace, as a parent, if the document is a canvas.
fn shownParent() ?Parent {
    if (shown_space >= state.model.spaces.items.len) return null;
    return .{ .space = shown_space };
}

/// The context for empty space: the shown workspace on a canvas, else the
/// worksheet.
fn workspaceContext() Context {
    return if (shownParent() != null) .{ .space = shown_space } else .worksheet;
}

/// Whether what is directly in parent `p` can be picked: its layer (a
/// panel's own, a workspace's base layer) shown and not locked.
fn parentLayerOpen(p: Parent) bool {
    if (state.model.spaces.items.len == 0) return true;
    return switch (p) {
        .space => |si| si < state.model.spaces.items.len and layerOpen(si, state.model.spaces.items[si].base_layer),
        .panel => |pi| layerOpen(state.model.spaceOf(pi), panelLayer(pi)),
    };
}

/// The context for parent `p`: its workspace or its panel.
fn parentContext(p: Parent) Context {
    return switch (p) {
        .space => |si| .{ .space = si },
        .panel => |pi| .{ .panel = pi },
    };
}

/// Whether parent `p` is shown: the shown workspace, or a panel in it.
fn shownIn(p: Parent) bool {
    return switch (p) {
        .space => |si| si == shown_space,
        .panel => |pi| shownPanel(pi),
    };
}

/// The placed content of parent `p` (see `State.solved`), if placed.
fn placedOf(p: Parent) ?*const layout.place.Placed {
    if (!state.model.hasParent(p)) return null;
    const k = state.model.parentSlot(p);
    return if (k < state.solved.items.len) &state.solved.items[k] else null;
}

/// Whether panel `pi` is shown: it lives in the shown space (a worksheet
/// document shows every panel).
fn shownPanel(pi: usize) bool {
    if (state.model.spaces.items.len == 0) return true;
    return state.model.spaceOf(pi) == shown_space;
}

/// Shows the space the context belongs to.
fn followContext() void {
    if (state.model.spaces.items.len == 0) return;
    const pi: ?Parent = switch (state.context) {
        .space => |si| .{ .space = si },
        .panel => |pi| .{ .panel = pi },
        .art => |l| .{ .panel = l.panel },
        .region => |r| r.parent,
        .row => |r| r.parent,
        .grid => |g| g.parent,
        .tile => |id| if (findTile(id)) |f| f.parent else null,
        .group => |g| {
            if (state.model.spaceOfId(g)) |sp| shown_space = sp;
            return;
        },
        .view => |v| {
            shown_space = v.space;
            return;
        },
        .layer => |l| {
            shown_space = l.space;
            return;
        },
        .image => |im| {
            shown_space = im.space;
            return;
        },
        else => null,
    };
    if (pi) |p| if (state.model.hasParent(p)) {
        shown_space = state.model.spaceOfParent(p);
    };
    if (shown_space >= state.model.spaces.items.len) shown_space = 0;
}

/// Whether the document is an open canvas (no sheet).
fn openCanvas() bool {
    return !state.model.has_sheet;
}

/// The units lengths are shown and typed in: the sheet's, or the canvas's.
fn docUnits() layout.model.Units {
    return if (state.model.has_sheet) state.model.sheet.units else state.model.units;
}

/// Starts over with an empty document and asks for the new canvas's units.
fn newCanvas() void {
    // Nothing of the last document's clicks or editing carries over: a
    // first click in the new one picks, not "again, further out".
    last_click = null;
    hunt_clear();
    canvas_eq = null;
    // Ids may repeat in another document: no slot is remembered.
    expr_track = .none;
    resetViews();
    setFilePath(null);
    clearPlaced();
    forgetThreads();
    state.model.deinit();
    state.model = .init(state.gpa);
    state.model.has_sheet = false;
    if (state.labels) |*l| l.clear();
    state.label_style = null;
    state.label_style_set = false;
    state.context = .worksheet;
    state.tool = .select;
    state.drag = null;
    state.moving = null;
    state.placed_rev = std.math.maxInt(u64);
    track_cursor = null;
    state.view.fit = canvas_view;
    canvas_prompt = true;
    shown_space = 0;
    selection.clearRetainingCapacity();
}

/// Makes the canvas in `units`, and makes it the context.
fn createCanvas(units: layout.model.Units) void {
    const ci = state.model.startCanvas(units) catch return;
    // The new canvas is where its history starts: nothing to undo.
    hist.reset(&state.model) catch {};
    last_units = units;
    canvas_prompt = false;
    state.context = .{ .space = ci };
    state.view.fit = canvas_view;
}

// The start screen ---------------------------------------------------------
//
// Before there is a document, none of the canvas's interface shows: the
// window's middle is a splash (Graven's mark, name, version, licence), with
// two panes over it. On the left, the message of the day (news for this
// version, fetched and cached: motd.zig); on the right, what to start
// with: a new canvas in millimetres or in inches, Open file…, and the
// files opened or saved lately. Single keys: M, I, O, and 1 to 9 for the
// recent files. Choosing a canvas launches the main interface.

const start_pane_width = 300;

/// What the splash says the licence is (no licence file yet).
const licence_text = "Licence: not yet chosen";

/// Files opened or saved lately, the latest first (absolute paths), kept
/// in the local config as `files.recent`.
var recent_files: std.ArrayList([]u8) = .empty;
const recent_max = 9;

fn loadRecent(ps: *const settings_file.Store) void {
    const v = ps.get("files.recent") orelse return;
    if (v != .array) return;
    for (v.array) |x| {
        if (x != .string or recent_files.items.len >= recent_max) continue;
        recent_files.append(state.gpa, state.gpa.dupe(u8, x.string) catch continue) catch {};
    }
}

/// Puts `path` first in the recent files, and writes them out.
fn noteRecent(path: []const u8) void {
    const full = platform.absolutePath(dvui.io, state.gpa, path);
    defer if (full) |r| state.gpa.free(r);
    const abs: []const u8 = full orelse path;
    var k: usize = 0;
    while (k < recent_files.items.len) {
        if (std.mem.eql(u8, recent_files.items[k], abs)) {
            state.gpa.free(recent_files.orderedRemove(k));
        } else k += 1;
    }
    recent_files.insert(state.gpa, 0, state.gpa.dupe(u8, abs) catch return) catch return;
    while (recent_files.items.len > recent_max) state.gpa.free(recent_files.pop().?);
    const ps = &(prefs_store orelse return);
    const a = dvui.currentWindow().arena();
    const vals = a.alloc(settings_file.Value, recent_files.items.len) catch return;
    for (recent_files.items, vals) |f, *v| v.* = .{ .string = f };
    ps.put("files.recent", .{ .array = vals }, .local);
    if (ps.save(dvui.io)) |msg| state.status = msg;
}

/// Opens recent file `k`; one no longer there is dropped from the list.
fn openRecent(k: usize) void {
    if (k >= recent_files.items.len) return;
    const path = recent_files.items[k];
    std.Io.Dir.cwd().access(dvui.io, path, .{}) catch {
        state.status = "That file is no longer there: it is taken off the list. ";
        state.gpa.free(recent_files.orderedRemove(k));
        return;
    };
    const copy = dvui.currentWindow().arena().dupe(u8, path) catch return;
    openDocument(copy);
}

fn startScreen() void {
    var area = dvui.box(@src(), .{}, .{ .expand = .both, .background = true, .color_fill = .{ .color = colors.desk } });
    defer area.deinit();
    const ns = dvui.windowNaturalScale();
    const ar = area.data().contentRectScale().r;
    // Prompts (Open) centre on it.
    canvas_rect = .{ .x = ar.x / ns, .y = ar.y / ns, .w = ar.w / ns, .h = ar.h / ns };
    region_rect = canvas_rect;
    if (motd.poll()) dvui.refresh(null, @src(), null);
    // While the news is being fetched, look again now and then: nothing
    // else wakes an idle window.
    if (motd.busy() and dvui.timerDoneOrNone(area.data().id)) dvui.timer(area.data().id, 300_000);
    startKeys(area.data());
    splash();
    const g: f32 = 16;
    const h = @max(120, ar.h / ns - 2 * g);
    {
        var left = dvui.box(@src(), .{ .dir = .vertical }, startPaneOptions(1, .{ .x = g, .y = g, .w = start_pane_width, .h = h }));
        defer left.deinit();
        motdPane();
    }
    {
        var right = dvui.box(@src(), .{ .dir = .vertical }, startPaneOptions(2, .{ .x = @max(g, ar.w / ns - start_pane_width - g), .y = g, .w = start_pane_width, .h = h }));
        defer right.deinit();
        startChoices();
    }
}

fn startPaneOptions(id: usize, r: dvui.Rect) dvui.Options {
    return overlayOptions(id).override(.{ .rect = r, .padding = .all(14) });
}

/// View › Display correction… (or D on the start screen) is open.
var display_window = false;

/// The display correction window: midtones (gamma) and the brightest the
/// interface gets (white), live, with a gauge to judge them by. Esc or
/// Close closes it; Reset puts both back to 1.
fn displayWindow() void {
    const saved_group = pushGroup("dialog.display");
    defer popGroup(saved_group);
    if (!display_window) return;
    const win = dvui.currentWindow();
    const ws = win.rect_pixels;
    const ns = dvui.windowNaturalScale();
    const w: f32 = 440;
    const h: f32 = 340;
    var r: dvui.Rect = .{ .x = (ws.w / ns - w) / 2, .y = (ws.h / ns - h) / 2, .w = w, .h = h };
    // Opaque: the gauge is judged against nothing showing through.
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(14).override(.{ .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) } }));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(14) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), "Display correction", .{}, .{ .font = dvui.Font.theme(.heading) });
    const ink = dvui.themeGet().color(.window, .text);
    {
        var tl = dvui.textLayout(@src(), .{}, .{ .expand = .horizontal, .background = false, .padding = .{ .y = 4, .h = 8 } });
        tl.addText("For a screen that shows Graven too bright or washed out. Midtones above 1 darken greys and deepen colour; Brightest lowers white. Kept for this machine; exports are not affected.", .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = ink.opacity(0.75) } });
        tl.deinit();
    }
    var close = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        if (inv.action != kact("dialog.cancel")) continue;
        close = true;
        e.handle(@src(), fw.data());
    }
    var dc = display.get();
    const before = dc;
    displayGauge();
    displaySlider("Midtones", &dc.gamma, display.gamma_min, display.gamma_max, 1);
    displaySlider("Brightest", &dc.white, display.white_min, display.white_max, 2);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 10 } });
        defer row.deinit();
        keyButton(@src(), "Screen size…", 0, .{});
        keyButton(@src(), "Reset", 0, .{});
        keyButton(@src(), "Close", 0, .{});
    }
    if (!std.meta.eql(dc, before)) {
        display.set(dc);
        applyDesktop(win, desk);
        dvui.refresh(null, @src(), null);
    }
    if (close) {
        display_window = false;
        dvui.refresh(null, @src(), null);
    }
}

/// A slider from `lo` to `hi` with its value beside it.
fn displaySlider(name: []const u8, v: *f32, lo: f32, hi: f32, id: usize) void {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = id, .margin = .{ .y = 4 } });
    defer row.deinit();
    dvui.labelNoFmt(@src(), name, .{}, .{ .min_size_content = .{ .w = 80 }, .gravity_y = 0.5 });
    var frac = (v.* - lo) / (hi - lo);
    var vb: [16]u8 = undefined;
    const shown = std.fmt.bufPrint(&vb, "{d:.2}", .{v.*}) catch "";
    dvui.labelNoFmt(@src(), shown, .{}, .{ .gravity_x = 1, .gravity_y = 0.5, .font = dvui.Font.theme(.mono), .min_size_content = .{ .w = 44 } });
    if (dvui.slider(@src(), .{ .fraction = &frac }, .{ .expand = .horizontal, .gravity_y = 0.5 })) {
        // In steps of 0.05.
        v.* = @round((lo + std.math.clamp(frac, 0, 1) * (hi - lo)) * 20) / 20;
    }
}

/// What to judge the correction by: a ramp of greys from black to white
/// in tenths (each step should stand apart from its neighbours), and a
/// 50 % patch of fine black and white lines around a solid grey of the
/// same light on a standard (sRGB) screen. With the correction right for
/// the screen, the grey all but vanishes into the lines when seen from a
/// little way off.
fn displayGauge() void {
    var g = dvui.box(@src(), .{}, .{ .expand = .horizontal, .min_size_content = .{ .h = 96 }, .margin = .{ .y = 4, .h = 8 } });
    defer g.deinit();
    const r = g.data().contentRectScale().r;
    const ramp_h = @round(r.h * 0.38);
    const steps = 11;
    const sw = r.w / steps;
    for (0..steps) |i| {
        const v: u8 = @intFromFloat(@round(@as(f32, @floatFromInt(i)) * 25.5));
        const cell: dvui.Rect.Physical = .{ .x = @round(r.x + @as(f32, @floatFromInt(i)) * sw), .y = r.y, .w = @round(sw) + 1, .h = ramp_h };
        cell.fill(.square, .{ .color = .{ .color = display.fix(dvui.Color{ .r = v, .g = v, .b = v }) } });
    }
    // The lines: black and white, one device pixel each, so their light
    // averages to half of white's.
    const top = @round(r.y + ramp_h + 10);
    const lines: dvui.Rect.Physical = .{ .x = r.x, .y = top, .w = r.w, .h = @round(r.y + r.h - top) };
    const white = display.fix(dvui.Color{ .r = 255, .g = 255, .b = 255 });
    lines.fill(.square, .{ .color = .{ .color = .black } });
    var y = lines.y;
    while (y < lines.y + lines.h) : (y += 2) {
        (dvui.Rect.Physical{ .x = lines.x, .y = y, .w = lines.w, .h = 1 }).fill(.square, .{ .color = .{ .color = white } });
    }
    // Half of white's light, in sRGB: 188 of 255.
    const grey = display.fix(dvui.Color{ .r = 188, .g = 188, .b = 188 });
    const inner: dvui.Rect.Physical = .{ .x = @round(lines.x + lines.w / 3), .y = lines.y + 8, .w = @round(lines.w / 3), .h = @max(1, lines.h - 16) };
    inner.fill(.square, .{ .color = .{ .color = grey } });
}

/// View › Calibrate screen size… is open; the card outline's width while
/// it is (device pixels).
var size_window = false;
var card_px: f32 = 0;
/// Where the window is: placed once when opened, so the card's corner
/// stays put while its edge is dragged (it can be moved by its title).
var size_rect: dvui.Rect = .{};

/// Opens the screen size calibration, the card at the scale in use.
fn openSizeWindow() void {
    size_window = true;
    const ns = dvui.windowNaturalScale();
    card_px = display.pxPerMm(ns) * display.card_w_mm;
    const ws = dvui.currentWindow().rect_pixels;
    // Room for a card a third bigger than the estimate.
    const w = @max(520, 1.33 * card_px / ns + 60);
    size_rect = .{ .x = @max(0, (ws.w / ns - w) / 2), .y = @max(0, ws.h / ns * 0.2), .w = w, .h = 0 };
    dvui.refresh(null, @src(), null);
}

/// The screen size calibration: an outline of a bank card, dragged (or
/// moved with Left and Right, a device pixel at a time; Shift: ten) until
/// it covers a real card held against the screen. Save keeps the scale for
/// this machine; Use estimate forgets it; Cancel or Esc leaves it as it was.
fn sizeWindow() void {
    const saved_group = pushGroup("dialog.size");
    defer popGroup(saved_group);
    if (!size_window) return;
    const ns = dvui.windowNaturalScale();
    const card_w = card_px / ns;
    const card_h = card_w * display.card_h_mm / display.card_w_mm;
    size_rect.w = @max(size_rect.w, card_w + 60);
    size_rect.h = card_h + 300;
    var fw = dvui.floatingWindow(@src(), .{ .rect = &size_rect, .resize = .none }, overlayOptions(15).override(.{ .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) } }));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(14) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), "Screen size", .{}, .{ .font = dvui.Font.theme(.heading) });
    const ink = dvui.themeGet().color(.window, .text);
    {
        var tl = dvui.textLayout(@src(), .{}, .{ .expand = .horizontal, .background = false, .padding = .{ .y = 4, .h = 8 } });
        tl.addText("Hold a bank card (or any card of that size, 85.6 × 54 mm) against the screen, its top left corner on the outline's. Drag the outline, or press Left and Right (Shift for bigger steps), until its right edge meets the card's. Then View › Actual size shows designs at the size they will be made.", .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = ink.opacity(0.75) } });
        tl.deinit();
    }
    var do_save = false;
    var cancel = false;
    // The card.
    {
        var area = dvui.box(@src(), .{}, .{ .min_size_content = .{ .w = card_w, .h = card_h }, .max_size_content = .{ .w = card_w, .h = card_h }, .margin = .{ .y = 6, .h = 10 } });
        defer area.deinit();
        const cr = area.data().contentRectScale().r;
        const card: dvui.Rect.Physical = .{ .x = @round(cr.x), .y = @round(cr.y), .w = @round(card_px), .h = @round(card_px * display.card_h_mm / display.card_w_mm) };
        const rad = card_px / display.card_w_mm * display.card_radius_mm;
        card.fill(.round(rad), .{ .color = .{ .color = colors.select.opacity(0.10) } });
        card.stroke(.round(rad), .{ .thickness = 1, .color = .{ .color = colors.select } });
        // The right edge, to meet the card's.
        const edge: dvui.Rect.Physical = .{ .x = card.x + card.w - 2, .y = card.y + rad, .w = 2, .h = @max(1, card.h - 2 * rad) };
        edge.fill(.square, .{ .color = .{ .color = colors.select } });
        // Centimetre ticks along the top, as a check against a ruler.
        var mm: f32 = 10;
        while (mm < display.card_w_mm) : (mm += 10) {
            const x = @round(card.x + mm * card_px / display.card_w_mm);
            (dvui.Rect.Physical{ .x = x, .y = card.y, .w = 1, .h = 6 * ns }).fill(.square, .{ .color = .{ .color = colors.select.opacity(0.7) } });
        }
        const ad = area.data();
        for (dvui.events()) |*e| {
            if (keymap.match1(e, kmode("dialog.calibrate-size"))) |inv| {
                switch (inv.action) {
                    kact("dialog.calibrate-size.grow") => card_px += @floatFromInt(inv.arg),
                    kact("dialog.cancel") => cancel = true,
                    kact("dialog.confirm") => do_save = true,
                    else => continue,
                }
                e.handle(@src(), fw.data());
                dvui.refresh(null, @src(), null);
                continue;
            }
            if (!dvui.eventMatchSimple(e, ad)) continue;
            if (e.evt != .mouse) continue;
            const me = e.evt.mouse;
            switch (me.action) {
                .press => if (me.button.pointer()) {
                    e.handle(@src(), ad);
                    dvui.captureMouse(ad, e.num);
                    dvui.dragPreStart(me.button, me.p, .{ .cursor = .arrow_w_e });
                },
                .release => if (dvui.captured(ad.id)) {
                    e.handle(@src(), ad);
                    dvui.captureMouse(null, e.num);
                    dvui.dragEnd(me.button);
                },
                .motion => if (dvui.captured(ad.id)) {
                    e.handle(@src(), ad);
                    // The right edge follows the pointer.
                    card_px = me.p.x - card.x;
                    dvui.refresh(null, @src(), null);
                },
                .position => dvui.cursorSet(.arrow_w_e),
                else => {},
            }
        }
        card_px = std.math.clamp(card_px, display.px_per_mm_min * display.card_w_mm, display.px_per_mm_max * display.card_w_mm);
    }
    {
        const ppm = display.fromCardWidth(card_px);
        const est = display.estimatePxPerMm(ns);
        var lb: [96]u8 = undefined;
        const text = std.fmt.bufPrint(&lb, "{d:.3} pixels per mm: {d:.1} dpi", .{ ppm, display.dpi(ppm) }) catch "";
        dvui.labelNoFmt(@src(), text, .{}, .{ .font = dvui.Font.theme(.mono) });
        var sb: [128]u8 = undefined;
        const sub = std.fmt.bufPrint(&sb, "{d:.0} % of the estimate (96 dpi × {d:.2}). {s}", .{
            100 * ppm / est, ns,
            if (display.measuredPxPerMm() != null) "Measured before." else "Not measured yet.",
        }) catch "";
        dvui.labelNoFmt(@src(), sub, .{}, .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = ink.opacity(0.7) } });
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 10 } });
        defer row.deinit();
        keyButton(@src(), "Use estimate", 0, .{});
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), "Save", 0, .{ .style = .highlight });
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) do_save = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (do_save) {
        display.setPxPerMm(display.fromCardWidth(card_px));
        size_window = false;
    }
    if (cancel) size_window = false;
    if (!size_window) dvui.refresh(null, @src(), null);
}

/// View › Actual size: the zoom at which a millimetre on screen is a
/// millimetre, about the view's centre.
fn actualSize() void {
    zoomToPercent(100);
}

/// Zooms to `pct` per cent of actual size, about the view's centre.
fn zoomToPercent(pct: f64) void {
    state.view.fit = null;
    state.view.ppm = display.pxPerMm(dvui.windowNaturalScale()) * pct / 100;
    dvui.refresh(null, @src(), null);
}

/// The zoom, as a share of actual size.
fn zoomPercent() f64 {
    return 100 * state.view.ppm / display.pxPerMm(dvui.windowNaturalScale());
}

/// M, I, O, D and 1 to 9, while no prompt is open over the start screen.
fn startKeys(wd: *dvui.WidgetData) void {
    if (filePromptOpen() or recovery != null) return;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("start")) orelse continue;
        switch (inv.action) {
            kact("start.new-canvas") => createCanvas(if (inv.arg == 1) .inch else .mm),
            kact("start.open") => proceed(.open),
            kact("start.display-correction") => display_window = true,
            kact("start.open-recent") => openRecent(@intCast(inv.arg)),
            else => continue,
        }
        e.handle(@src(), wd);
        dvui.refresh(null, @src(), null);
    }
}

/// Graven's mark (a keycap with a legend on it), its name, version and
/// licence, centred.
fn splash() void {
    var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .gravity_x = 0.5, .gravity_y = 0.42 });
    defer col.deinit();
    {
        const size: f32 = 150;
        var mark = dvui.box(@src(), .{}, .{ .gravity_x = 0.5, .min_size_content = .{ .w = size, .h = size }, .margin = .{ .h = 18 } });
        defer mark.deinit();
        const r = mark.data().contentRectScale().r;
        const ns = dvui.windowNaturalScale();
        const ink = dvui.themeGet().color(.window, .text);
        // The key: its body, and its face a little up from the skirt.
        r.fill(.all(26 * ns), .{ .color = .{ .color = ink.opacity(0.14) } });
        const inset = 14 * ns;
        const face: dvui.Rect.Physical = .{ .x = r.x + inset, .y = r.y + inset * 0.6, .w = r.w - 2 * inset, .h = r.h - 2.2 * inset };
        face.fill(.all(18 * ns), .{ .color = .{ .color = colors.desk } });
        face.stroke(.all(18 * ns), .{ .thickness = 1.5 * ns, .color = .{ .color = ink.opacity(0.35) } });
        // Its legends: G, and √x set small below, as on a calculator key.
        var ov = dvui.overlay(@src(), .{ .expand = .both });
        defer ov.deinit();
        dvui.labelNoFmt(@src(), "G", .{}, .{ .gravity_x = 0.5, .gravity_y = 0.36, .font = dvui.Font.theme(.title).larger(30) });
        dvui.labelNoFmt(@src(), "√x", .{}, .{ .gravity_x = 0.5, .gravity_y = 0.8, .font = dvui.Font.theme(.body).larger(2), .color_text = .{ .color = ink.opacity(0.6) } });
    }
    dvui.labelNoFmt(@src(), "Graven", .{}, .{ .gravity_x = 0.5, .font = dvui.Font.theme(.title).larger(14) });
    dvui.labelNoFmt(@src(), "Text, symbols and legends, set as exact geometry", .{}, .{ .gravity_x = 0.5, .padding = .{ .y = 4, .h = 10 }, .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.7) } });
    dvui.label(@src(), "Version {s}", .{layout.version}, .{ .gravity_x = 0.5, .font = dvui.Font.theme(.body).larger(-1) });
    dvui.labelNoFmt(@src(), licence_text, .{}, .{ .gravity_x = 0.5, .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) } });
}

/// The message of the day: a `# ` line a heading, paragraphs between
/// blank lines.
fn motdPane() void {
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .h = 8 } });
        defer row.deinit();
        icons.image(@src(), .megaphone, 22, 0, null);
        dvui.labelNoFmt(@src(), "News", .{}, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.heading), .padding = .{ .x = 8 } });
    }
    {
        var scroll = dvui.scrollArea(@src(), .{ .horizontal = .none }, .{ .expand = .both });
        defer scroll.deinit();
        var it = std.mem.splitSequence(u8, motd.text(), "\n\n");
        var k: usize = 0;
        while (it.next()) |para_raw| : (k += 1) {
            const para = std.mem.trim(u8, para_raw, " \n\r");
            if (para.len == 0) continue;
            const is_heading = std.mem.startsWith(u8, para, "# ");
            const body = if (is_heading) para[2..] else para;
            var tl = dvui.textLayout(@src(), .{}, .{ .id_extra = k, .expand = .horizontal, .background = false, .padding = .{ .h = 8 } });
            // Line breaks inside a paragraph are spaces.
            var lines = std.mem.splitScalar(u8, body, '\n');
            var first = true;
            while (lines.next()) |line| {
                if (!first) tl.addText(" ", .{});
                first = false;
                tl.addText(line, .{ .font = if (is_heading) dvui.Font.theme(.heading).larger(-1) else dvui.Font.theme(.body) });
            }
            tl.deinit();
        }
    }
    const note = switch (motd.from()) {
        .builtin => if (motd.busy()) "Fetching the news…" else "No news fetched yet.",
        .cache => if (motd.busy()) "Checking for newer news…" else "Fetched earlier.",
        .fetched => "Fetched just now.",
    };
    dvui.labelNoFmt(@src(), note, .{}, .{ .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.55) } });
}

/// A choice on the start screen: an icon, its label (and below it, faint,
/// `sub`), and its key at the right. Whether it was chosen.
fn startRow(comptime i: icons.Icon, label: []const u8, sub: []const u8, key: []const u8, id: usize, faint: bool) bool {
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{ .id_extra = id, .expand = .horizontal, .padding = .{ .x = 8, .w = 8, .y = 6, .h = 6 }, .margin = .{ .h = 2 }, .corners = .all(6), .label = .{ .text = label } });
    bw.processEvents();
    bw.drawBackground();
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        icons.image(@src(), i, 26, 0, null);
        const text_col = dvui.themeGet().color(.window, .text);
        {
            var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal, .gravity_y = 0.5, .padding = .{ .x = 10 } });
            defer col.deinit();
            dvui.labelNoFmt(@src(), label, .{}, .{ .color_text = .{ .color = text_col.opacity(if (faint) 0.5 else 1) } });
            if (sub.len > 0) dvui.labelNoFmt(@src(), sub, .{}, .{ .font = dvui.Font.theme(.body).larger(-3), .color_text = .{ .color = text_col.opacity(0.55) } });
        }
        if (key.len > 0) dvui.labelNoFmt(@src(), key, .{}, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.mono), .padding = .{ .x = 6, .w = 6, .y = 1, .h = 1 }, .background = true, .corners = .all(4), .color_fill = .{ .color = text_col.opacity(0.08) }, .color_text = .{ .color = text_col.opacity(0.7) } });
    }
    const clicked = bw.clicked();
    bw.drawFocus();
    bw.deinit();
    return clicked;
}

fn startChoices() void {
    dvui.labelNoFmt(@src(), "Start", .{}, .{ .font = dvui.Font.theme(.heading), .margin = .{ .h = 8 } });
    if (startRow(.file_plus, "New canvas, millimetres", "", "M", 1, false)) createCanvas(.mm);
    if (startRow(.file_plus, "New canvas, inches", "", "I", 2, false)) createCanvas(.inch);
    if (startRow(.folder_open, "Open file…", "", "O", 3, false)) proceed(.open);
    if (startRow(.monitor, "Display correction…", "If Graven looks too bright or washed out", "D", 4, false)) display_window = true;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 14, .h = 6 } });
        defer row.deinit();
        icons.image(@src(), .clock_counter_clockwise, 20, 0, null);
        dvui.labelNoFmt(@src(), "Recent", .{}, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.heading).larger(-2), .padding = .{ .x = 8 } });
    }
    if (recent_files.items.len == 0) {
        dvui.labelNoFmt(@src(), "Files you open or save show here.", .{}, .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.55) } });
        return;
    }
    var scroll = dvui.scrollArea(@src(), .{ .horizontal = .none }, .{ .expand = .both });
    defer scroll.deinit();
    var chosen: ?usize = null;
    for (recent_files.items, 0..) |path, k| {
        var kb: [4]u8 = undefined;
        const key = std.fmt.bufPrint(&kb, "{d}", .{k + 1}) catch "";
        const there = if (std.Io.Dir.cwd().access(dvui.io, path, .{})) true else |_| false;
        // A long folder shown by its end, which tells files apart.
        const dir = std.fs.path.dirname(path) orelse "";
        const keep = 34;
        const shown = if (dir.len <= keep) dir else std.fmt.allocPrint(dvui.currentWindow().arena(), "…{s}", .{dir[dir.len - keep ..]}) catch dir;
        if (startRow(.file, std.fs.path.basename(path), shown, key, 10 + k, !there)) chosen = k;
    }
    if (chosen) |k| openRecent(k);
}

/// File › Export SVG is asking where to write.
var export_prompt = false;

fn exportSvg() void {
    if (canvas_prompt) return;
    export_prompt = true;
}

/// What Export SVG writes: the selected panel (or the workspace a chosen
/// content layout is set on), else the shown workspace's content layouts
/// and grids (on a worksheet, the first panel).
fn exportPanel() ?Parent {
    switch (state.context) {
        .panel => |pi| return .{ .panel = pi },
        .art => |l| return .{ .panel = l.panel },
        .region => |r| return r.parent,
        .row => |r| return r.parent,
        else => {},
    }
    if (shownParent()) |p| return p;
    return if (state.model.panels.items.len > 0) .{ .panel = 0 } else null;
}

/// The panel a 3MF is made of: the chosen one (only a panel is made).
fn exportPart() ?usize {
    return (exportPanel() orelse return null).panelIndex();
}

/// The export prompt: the file to write, then Export (or Enter); Esc or
/// Cancel closes it.
fn exportPrompt() void {
    const saved_group = pushGroup("dialog.export");
    defer popGroup(saved_group);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 460;
    const h: f32 = 185;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(10));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    const pi = exportPanel();
    const what = if (pi) |p| (if (p == .space) "the workspace's content layouts" else state.model.parentName(p)) else "nothing yet";
    dvui.label(@src(), "Export SVG: {s}", .{what}, .{ .font = dvui.Font.theme(.heading) });
    var go = false;
    var cancel = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => go = true,
            kact("dialog.cancel") => cancel = true,
            else => continue,
        }
        e.handle(@src(), fw.data());
    }
    var path: []const u8 = "graven.svg";
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        defer row.deinit();
        propName("File");
        var te = dvui.textEntry(@src(), .{ .text_initial = "graven.svg" }, .{ .expand = .horizontal });
        defer te.deinit();
        path = dvui.currentWindow().arena().dupe(u8, std.mem.trim(u8, te.textGet(), " ")) catch "graven.svg";
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), "Export", 0, .{});
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) go = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (cancel) {
        export_prompt = false;
        return;
    }
    if (!go) return;
    export_prompt = false;
    const p = pi orelse {
        state.status = "There is nothing to export yet. ";
        return;
    };
    if (placedOf(p) == null or path.len == 0) return;
    // Never a stale layout: threads followed to the end first.
    const labels = if (state.labels) |*l| l else return;
    const entries = layout.place.handoffs(state.gpa, &state.model, labels, thread_entries) catch {
        state.status = "The SVG could not be made. ";
        return;
    };
    defer state.gpa.free(entries);
    var current = layout.place.solveWith(state.gpa, &state.model, p, labels, entries) catch {
        state.status = "The SVG could not be made. ";
        return;
    };
    defer current.deinit();
    const svg = layout.output.panelSvg(state.gpa, &current, faceTable(), .{}) catch {
        state.status = "The SVG could not be made. ";
        return;
    };
    defer state.gpa.free(svg);
    std.Io.Dir.cwd().writeFile(dvui.io, .{ .sub_path = path, .data = svg }) catch {
        state.status = "The SVG could not be written there. ";
        return;
    };
    state.status = "Exported. ";
}

/// Adds the text sample (a track of text with an equation in it) to the
/// shown space's canvas, right of what it holds, with the cursor in it;
/// where its track starts (its first row's top left).
fn loadText() !geom.Point {
    const pi = shownParent() orelse return error.NoCanvas;
    const held = spaceExtents();
    const at: geom.Point = if (held.isEmpty()) .{ .x = 0, .y = 30 } else .{ .x = held.x1 + 20, .y = held.y1 };
    const r = try text_sample.build(&state.model, pi, try labelStyle(), at);
    try hist.snapshot(&state.model);
    state.context = .{ .region = .{ .parent = pi, .region = r } };
    track_cursor = .{ .parent = pi, .region = r, .index = 1, .offset = 0 };
    state.view.fit = .{ .x0 = at.x - 5, .y0 = at.y - 25, .x1 = at.x + 65, .y1 = at.y + 5 };
    return at;
}

/// Where prototype `id` is in the document's list, for dropdowns; 0 when
/// it is none of them.
/// The ID of space `si` (by position); `.none` without spaces (a
/// worksheet), as its panels have.
fn spaceId(si: usize) layout.model.ObjectId {
    return if (si < state.model.spaces.items.len) state.model.spaces.items[si].id else .none;
}

fn protoPos(id: layout.model.PrototypeId) usize {
    return state.model.protoIndex(id) orelse 0;
}

fn deinit(_: *dvui.Window) void {
    motd.deinit();
    for (recent_files.items) |f| state.gpa.free(f);
    recent_files.deinit(state.gpa);
    recent_files = .empty;
    hist.deinit();
    if (prefs_store) |*ps| ps.deinit();
    prefs_store = null;
    freeFonts(state.gpa);
    // The resolved faces point into the font window's: dropped first.
    if (resolved) |*r| r.deinit();
    resolved = null;
    fontwin.deinit();
    doc_fonts.deinit(state.gpa);
    doc_fonts = .init(state.gpa);
    doc_fonts_loaded = false;
    if (doc_fonts_for) |h| state.gpa.free(h);
    doc_fonts_for = null;
    if (fonts_from) |f| state.gpa.free(f);
    fonts_from = null;
    // Started again (the GUI's tests start Graven several times in one
    // process): a fresh start screen, one view, nothing chosen.
    canvas_prompt = true;
    if (file_path) |f| state.gpa.free(f);
    file_path = null;
    resetViews();
    selection.clearRetainingCapacity();
    track_cursor = null;
    panel_edit = null;
    dg_table.deinit(state.gpa);
    dg_table = .{};
    clearChecks();
    clearPlanChecks();
    op_hidden.clearAndFree(state.gpa);
    meshJobWait();
    if (mesh_arena) |*ar| ar.deinit();
    mesh_arena = null;
    mesh = .{};
    mesh_plan = .none;
    mesh_rev = std.math.maxInt(u64);
    cams = @splat(.{});
    tags_given.deinit(state.gpa);
    tags_given = .empty;
    clearPlaced();
    state.solved.deinit(state.gpa);
    if (state.labels) |*l| l.deinit();
    if (state.face) |f| f.deinit();
    state.flat.arena.deinit();
    if (atlas) |*a| a.deinit();
    atlas = null;
    if (resolved) |*r| r.deinit();
    resolved = null;
    state.expanded.deinit(state.gpa);
    forgetThreads();
    state.model.deinit();
}

/// The best match for Inter Medium, preferring installed fonts (they come
/// after the bundled one) and exact names: Inter Medium, then any Inter
/// family in Medium, then any Inter, then the first font.
fn defaultFont(fonts: []const Font) usize {
    var best: usize = 0;
    var best_score: u8 = 0;
    for (fonts, 0..) |f, i| {
        const inter = std.mem.startsWith(u8, f.family, "Inter") and !std.mem.startsWith(u8, f.family, "Inter Display");
        const medium = std.mem.eql(u8, f.style, "Medium");
        const installed: u8 = if (std.mem.eql(u8, f.path, example_font)) 0 else 1;
        const score: u8 = if (inter and medium and std.mem.eql(u8, f.family, "Inter"))
            6 + installed
        else if (inter and medium)
            4 + installed
        else if (inter)
            2 + installed
        else
            0;
        if (score > best_score) {
            best = i;
            best_score = score;
        }
    }
    return best;
}

/// Installed outline fonts from fontconfig (system and user folders, such
/// as ~/.local/share/fonts), sorted by name. Each face of a collection is
/// listed; a variable font is listed once, at its default instance, under
/// that instance's style (fontconfig also lists the font itself, unstyled).
/// fc-list's output, which the listed fonts' strings point into.
var fonts_text: []u8 = &.{};

/// Frees the font list (`state.fonts`) and what it points into.
fn freeFonts(gpa: std.mem.Allocator) void {
    for (state.fonts) |f| if (!std.mem.eql(u8, f.path, example_font)) gpa.free(f.name);
    gpa.free(state.fonts);
    state.fonts = &.{};
    gpa.free(fonts_text);
    fonts_text = &.{};
}

fn listFonts(gpa: std.mem.Allocator) ![]Font {
    const r = try std.process.run(gpa, dvui.io, .{ .argv = &.{ "fc-list", "--format", "%{family[0]}\t%{style[0]}\t%{index}\t%{file}\n" } });
    defer gpa.free(r.stderr);
    // The fonts' paths, families and styles point into it: kept until exit.
    fonts_text = r.stdout;
    var list: std.ArrayList(Font) = .empty;
    var lines = std.mem.splitScalar(u8, r.stdout, '\n');
    while (lines.next()) |line| {
        var fields = std.mem.splitScalar(u8, line, '\t');
        const family = fields.next() orelse continue;
        const style = fields.next() orelse continue;
        const index = std.fmt.parseInt(u32, fields.next() orelse continue, 10) catch continue;
        const path = fields.rest();
        const ext = std.fs.path.extension(path);
        const known = for ([_][]const u8{ ".otf", ".ttf", ".ttc", ".otc", ".woff", ".woff2" }) |e| {
            if (std.ascii.eqlIgnoreCase(ext, e)) break true;
        } else false;
        // Named instances of a variable font carry the instance above bit 16.
        if (!known or index >> 16 != 0) continue;
        const user = platform.isUserFontPath(path);
        const name = try std.fmt.allocPrint(gpa, "{s}{s}{s}{s}", .{ family, if (style.len > 0) " " else "", style, if (user) " (user)" else "" });
        const font: Font = .{ .name = name, .path = path, .index = index, .family = family, .style = style };
        // One entry per face of a file: a styled one replaces an unstyled.
        const same = for (list.items) |*f| {
            if (f.index == index and std.mem.eql(u8, f.path, path)) break f;
        } else null;
        if (same) |f| {
            if (f.style.len == 0 and style.len > 0) {
                gpa.free(f.name);
                f.* = font;
            } else gpa.free(name);
            continue;
        }
        try list.append(gpa, font);
    }
    std.mem.sort(Font, list.items, {}, struct {
        fn less(_: void, x: Font, y: Font) bool {
            return std.mem.lessThan(u8, x.name, y.name);
        }
    }.less);
    return list.toOwnedSlice(gpa);
}

/// Every workspace and panel laid out at once (`State.solved`), threads
/// entering where they did when last worked out (`thread_entries`).
fn solvePanels(labels: *layout.Labels) !void {
    clearPlaced();
    for (0..state.model.parentCount()) |k| {
        try state.solved.append(state.gpa, try layout.place.solveWith(state.gpa, &state.model, state.model.parentAt(k), labels, thread_entries));
    }
}

/// The reflow worker (see reflow.zig), made when a thread first crosses
/// panels, and where threads entered each panel when last worked out.
var reflower: ?reflow.Worker = null;
var thread_entries: []layout.place.Handoff = &.{};
/// Panels downstream are behind an edit: a batch is pending or running.
var catching_up = false;
var submitted_rev: u64 = std.math.maxInt(u64);

/// Another document: its threads start from nothing, and a batch still
/// running for the last one is ignored when it completes.
fn forgetThreads() void {
    state.gpa.free(thread_entries);
    thread_entries = &.{};
    submitted_rev = std.math.maxInt(u64);
    catching_up = false;
    doc_generation += 1;
}
var doc_generation: u64 = 0;

/// After the panels are laid out: where an edit moved where a thread goes
/// on into another panel, those downstream are behind; a batch for the
/// worker brings them up to date. With composed fonts (whose faces the
/// app keeps, not to be shared with a thread) it is worked out here.
fn followThreads(labels: *layout.Labels) !void {
    const gpa = state.gpa;
    var exits: std.ArrayList(layout.place.Handoff) = .empty;
    defer exits.deinit(gpa);
    for (state.solved.items) |pl| try exits.appendSlice(gpa, pl.exits);
    if (layout.place.sameHandoffs(exits.items, thread_entries)) {
        catching_up = reflower != null and reflower.?.busy();
        return;
    }
    if (resolved != null) {
        const e = try layout.place.handoffs(gpa, &state.model, labels, exits.items);
        gpa.free(thread_entries);
        thread_entries = e;
        try solvePanels(labels);
        catching_up = false;
        return;
    }
    catching_up = true;
    if (submitted_rev == state.model.revision) return;
    submitted_rev = state.model.revision;
    const doc = try layout.native.encode(gpa, &state.model);
    errdefer gpa.free(doc);
    const table = faceTable();
    const faces = try gpa.alloc(*layout.Face, table.len);
    var made: usize = 0;
    errdefer {
        for (faces[0..made]) |f| f.deinit();
        gpa.free(faces);
    }
    for (table, 0..) |f, k| {
        faces[k] = try f.clone(gpa);
        made += 1;
    }
    const first_guess = try gpa.dupe(layout.place.Handoff, exits.items);
    if (reflower == null) reflower = .{ .gpa = gpa, .io = dvui.io, .wake = wakeGui };
    reflower.?.submit(.{ .rev = state.model.revision, .generation = doc_generation, .doc = doc, .faces = faces, .start = first_guess });
}

/// Loads the chosen font if it changed, and re-solves when the model or the
/// font changed.
fn update() !void {
    followContext();
    if (state.font_loaded != state.font_choice and state.fonts.len > 0) {
        const f = state.fonts[state.font_choice];
        const bytes = try std.Io.Dir.cwd().readFileAlloc(dvui.io, f.path, state.gpa, .limited(64 << 20));
        defer state.gpa.free(bytes);
        const face = try layout.Face.init(state.gpa, bytes, f.index);
        clearPlaced();
        if (state.labels) |*l| l.deinit();
        if (state.face) |old| old.deinit();
        state.face = face;
        state.faces = .{face};
        state.labels = .init(state.gpa, &state.faces);
        state.font_loaded = state.font_choice;
        state.placed_rev = std.math.maxInt(u64);
        if (resolved) |*r| r.deinit();
        resolved = null;
        facesChanged();
    }
    const labels = if (state.labels) |*l| l else return;
    resolveFonts(labels);
    // A reflow batch done: where threads now enter each panel.
    if (reflower) |*w| if (w.take()) |res| {
        if (res.generation == doc_generation) {
            state.gpa.free(thread_entries);
            thread_entries = res.entries;
            state.placed_rev = std.math.maxInt(u64);
        } else state.gpa.free(res.entries);
    };
    if (state.placed_rev == state.model.revision and (resolved == null or resolved_rev == state.model.revision)) return;
    const t0: std.Io.Timestamp = .now(dvui.io, .awake);
    try solvePanels(labels);
    try followThreads(labels);
    state.intrusions = try layout.drc.marginIntrusions(state.gpa, &state.model, state.solved.items);
    state.panel_issues = try layout.drc.panelIssues(state.gpa, &state.model);
    state.layer_issues = try state.model.layerIssues(state.gpa);
    state.solve_ms = @as(f64, @floatFromInt(t0.untilNow(dvui.io, .awake).toNanoseconds())) / 1e6;
    state.placed_rev = state.model.revision;
    state.flat.reset(state.flat.tol);
    // Every view's: they hold the placement's renders.
    for (&view_slots) |*sl| if (sl.flat) |*f| f.reset(f.tol);
    // A selected row the flow no longer reaches gives way to its track.
    switch (state.context) {
        .row => |r| if (placedTrack(r.parent, r.region, r.row) == null and state.model.hasParent(r.parent) and r.region < state.model.regionsIn(r.parent).len) {
            state.context = .{ .region = .{ .parent = r.parent, .region = r.region } };
        },
        else => {},
    }
}

// Fonts ------------------------------------------------------------------------
//
// The fonts window (fontwin.zig) finds and composes fonts; the document's
// composed fonts are resolved against the installed fonts it indexes, and
// the canvas renders with the faces that gives.

/// The document's composed fonts resolved, while it has any.
var resolved: ?layout.fonts.Resolved = null;
var resolved_rev: u64 = std.math.maxInt(u64);
/// The font index's generation they were resolved against: a scan, an
/// install or a removal makes a new one (see fontwin.generation).
var resolved_gen: u32 = 0;

/// The face table labels render with: the resolved one, or the chosen
/// font alone.
/// GRAVEN_EXACT_TEXT set: text drawn from its outlines, not the atlas (to
/// compare the two).
var exact_text = false;

/// Glyph rasters from distance fields, for drawing text (see glyphs.zig).
/// Keyed by face: cleared whenever the faces change.
var atlas: ?glyphs.Atlas = null;

fn glyphAtlas() *glyphs.Atlas {
    if (atlas == null) {
        atlas = .init(state.gpa);
        // GRAVEN_FIELDS_INLINE set: fields made on the drawing thread (to
        // compare).
        if (platform.env("GRAVEN_FIELDS_INLINE") == null) atlas.?.startMaker(dvui.io, wakeGui);
    }
    return &atlas.?;
}

fn facesChanged() void {
    if (atlas) |*a| a.clear(true);
}

fn faceTable() []const *layout.Face {
    if (resolved) |*r| return r.faces.items;
    return &state.faces;
}

/// Resolves the document's styles' fonts again when the document changed.
fn resolveFonts(labels: *layout.Labels) void {
    const uses = for (state.model.styles.items) |st| {
        if (st.faces.items.len > 0) break true;
    } else false;
    if (!uses) {
        if (resolved) |*r| {
            labels.resolved = null;
            r.deinit();
            resolved = null;
            facesChanged();
            labels.deinit();
            state.labels = .init(state.gpa, &state.faces);
        }
        // Nothing holds the index's faces: earlier generations' can go.
        fontwin.releaseRetired();
        return;
    }
    const doc_changed = syncDocFonts();
    if (!doc_changed and resolved != null and resolved_rev == state.model.revision and resolved_gen == fontwin.generation) {
        fontwin.releaseRetired();
        return;
    }
    _ = fontwin.indexRecords(state.gpa, false);
    var names_arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer names_arena.deinit();
    // The document's font folders first, then the installed fonts: as the
    // CLI finds them (folders.zig).
    const installed = fontwin.catalog(names_arena.allocator());
    const cat = if (doc_fonts.faces.items.len > 0)
        (if (installed) |i| layout.fonts.join(names_arena.allocator(), doc_fonts.catalog(), i) catch return else doc_fonts.catalog())
    else
        installed orelse return;
    const next = layout.fonts.resolve(state.gpa, &state.model, cat, state.faces[0]) catch return;
    if (doc_changed) state.placed_rev = std.math.maxInt(u64);
    if (resolved) |*old| old.deinit();
    facesChanged();
    resolved = next;
    resolved_rev = state.model.revision;
    // Fonts may have come or gone without the document changing: place
    // again, with the faces resolved now.
    if (resolved_gen != fontwin.generation) state.placed_rev = std.math.maxInt(u64);
    resolved_gen = fontwin.generation;
    labels.syncResolved(&resolved.?) catch {};
    // Said once, when it changes: re-resolving after every edit would
    // otherwise put it over whatever the edit had to say.
    if (resolved.?.substitutions.items.len > 0) {
        const sub = resolved.?.substitutions.items[0];
        var tmp: [160]u8 = undefined;
        const msg = std.fmt.bufPrint(&tmp, "Font {s} {s} is not installed: {s}. ", .{ sub.wanted.family, sub.wanted.style, if (sub.got) |g| g.style else "left out" }) catch "";
        const h = std.hash.Wyhash.hash(0, msg);
        if (h != font_status_hash) {
            font_status_hash = h;
            @memcpy(font_status_buf[0..msg.len], msg);
            state.status = font_status_buf[0..msg.len];
        }
    } else font_status_hash = 0;
}
var font_status_buf: [160]u8 = undefined;
var font_status_hash: u64 = 0;

/// The document's font folders' fonts (a fonts folder beside it, then
/// $GRAVEN_FONTS or fonts/), loaded for the folder they are for.
var doc_fonts: folders.Folders = .init(std.heap.page_allocator);
var doc_fonts_for: ?[]u8 = null;
var doc_fonts_loaded = false;
/// Where an example opened as untitled came from: its fonts are beside it.
var fonts_from: ?[]u8 = null;

/// Loads the document's folders' fonts when the document's place changed;
/// whether it did.
fn syncDocFonts() bool {
    const want: ?[]const u8 = fonts_from orelse file_path;
    const same = if (want) |w| (if (doc_fonts_for) |h| std.mem.eql(u8, std.fs.path.dirname(w) orelse ".", h) else false) else doc_fonts_for == null;
    if (doc_fonts_loaded and same) return false;
    // Faces resolved from the old ones are dropped with them: resolve
    // again before anything draws.
    if (resolved) |*r| {
        if (state.labels) |*l| l.resolved = null;
        r.deinit();
        resolved = null;
        facesChanged();
    }
    doc_fonts.deinit(state.gpa);
    doc_fonts = .init(state.gpa);
    if (doc_fonts_for) |h| state.gpa.free(h);
    doc_fonts_for = if (want) |w| state.gpa.dupe(u8, std.fs.path.dirname(w) orelse ".") catch null else null;
    doc_fonts_loaded = true;
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const dirs = folders.dirsFor(arena.allocator(), want) catch return true;
    for (dirs) |d| doc_fonts.addDir(state.gpa, dvui.io, d) catch {};
    return true;
}

/// Each font-window change that takes two actions is undone as one.
var font_step: u64 = 0;

fn hostSetStyleFace(style: layout.model.StyleId, role: []const u8, font: ?layout.model.FontName) void {
    act(.setStyleFace, .{ style, role, font }) catch {};
}
fn hostSetStyleFamily(style: layout.model.StyleId, main_font: layout.model.FontName, variants: fontwin.Variants) void {
    font_step += 1;
    setFamily(mergeKey(.{ "font family", font_step }), style, main_font, variants);
}

/// Style `style`'s text face and its italic and bolds, as one step (merge
/// key `key`); a variant the family lacks is cleared.
fn setFamily(key: u64, style: layout.model.StyleId, main_font: layout.model.FontName, variants: fontwin.Variants) void {
    _ = actM(key, .setStyleFace, .{ style, "text", @as(?layout.model.FontName, main_font) }) catch return;
    _ = actM(key, .setStyleFace, .{ style, "italic", variants.italic }) catch {};
    _ = actM(key, .setStyleFace, .{ style, "bold", variants.bold }) catch {};
    _ = actM(key, .setStyleFace, .{ style, "bold_italic", variants.bold_italic }) catch {};
}

fn fontHost() fontwin.Host {
    return .{
        .model = &state.model,
        .setStyleFace = hostSetStyleFace,
        .setStyleFamily = hostSetStyleFamily,
    };
}

fn clearPlaced() void {
    state.gpa.free(state.intrusions);
    state.intrusions = &.{};
    state.gpa.free(state.panel_issues);
    state.panel_issues = &.{};
    state.gpa.free(state.layer_issues);
    state.layer_issues = &.{};
    for (state.solved.items) |*p| p.deinit();
    state.solved.clearRetainingCapacity();
    state.placed_rev = std.math.maxInt(u64);
}

/// A placed tile and the panel it is on.
const Found = struct { parent: Parent, tile: *const layout.place.PlacedTile };

fn findTile(id: TileId) ?Found {
    for (state.solved.items, 0..) |*p, k| if (p.findTile(id)) |t| return .{ .parent = state.model.parentAt(k), .tile = t };
    return null;
}

/// Where parent `p`'s frame origin sits in its space: a panel's (as
/// dragged, see `panelOrigin`), or a workspace's own (0, 0).
fn parentOrigin(p: Parent) geom.Point {
    return switch (p) {
        .space => .{ .x = 0, .y = 0 },
        .panel => |pi| panelOrigin(pi),
    };
}

/// Where panel `pi` sits on the worksheet: its origin, or its preview
/// position while it is being dragged (whole millimetres of travel).
fn panelOrigin(pi: usize) geom.Point {
    const o = state.model.panels.items[pi].origin;
    // It may be dragged past the sheet's edge, but keeps a grip on it.
    if (state.moving) |mv| if (mv.panel == pi) {
        // Its origin on the grid when snapping; else wherever it is taken.
        var sx = mv.at.x - mv.start.x;
        var sy = mv.at.y - mv.start.y;
        if (snapStep()) |st| {
            sx = snapShift(o.x, sx, st, &snap_guide.x);
            sy = snapShift(o.y, sy, st, &snap_guide.y);
        } else snap_guide = .{};
        return state.model.clampOnSheet(pi, .{ .x = o.x + sx, .y = o.y + sy });
    };
    return o;
}

fn panelBox(pi: usize) geom.Box {
    const p = state.model.panels.items[pi];
    const o = panelOrigin(pi);
    return .{ .x0 = o.x, .y0 = o.y, .x1 = o.x + p.w, .y1 = o.y + p.h };
}

/// A box in parent `pi`'s frame, moved into its space (onto the
/// worksheet).
fn onSheet(pi: Parent, b: geom.Box) geom.Box {
    const o = parentOrigin(pi);
    return .{ .x0 = b.x0 + o.x, .y0 = b.y0 + o.y, .x1 = b.x1 + o.x, .y1 = b.y1 + o.y };
}

/// Whether the document named on the command line has been opened.
var opened_arg = false;

/// GRAVEN_DUMP_OUTLINES=file.svg: the exact outlines of every glyph drawn,
/// in window pixels, written there (each frame's, at the start of the
/// next); to lay over a screenshot and see how the display path renders
/// them.
var dump_path: ?[]const u8 = null;
var dump_frame: u32 = 0;
var dump_svg: std.ArrayList(u8) = .empty;

fn dumpGlyph(area: dvui.Rect.Physical, face: *layout.Face, g: layout.render.GlyphItem, at: geom.Point) void {
    if (dump_path == null) return;
    const lifo = dvui.currentWindow().lifo();
    var arena: std.heap.ArenaAllocator = .init(lifo);
    defer arena.deinit();
    const o = layout.render.glyphOutline(arena.allocator(), face, g) catch return;
    for (o.contours) |c| {
        if (c.segments.len == 0) continue;
        const P = struct {
            fn px(ar: dvui.Rect.Physical, a: geom.Point, q: geom.Point) dvui.Point.Physical {
                return state.view.toPx(ar, .{ .x = q.x + a.x, .y = q.y + a.y });
            }
        };
        const s0 = P.px(area, at, c.segments[0].start());
        dumpPrint("M{d:.3} {d:.3}", .{ s0.x, s0.y });
        for (c.segments) |seg| switch (seg) {
            .line => |p| {
                const q = P.px(area, at, p[1]);
                dumpPrint("L{d:.3} {d:.3}", .{ q.x, q.y });
            },
            .quad => |p| {
                const q1 = P.px(area, at, p[1]);
                const q2 = P.px(area, at, p[2]);
                dumpPrint("Q{d:.3} {d:.3} {d:.3} {d:.3}", .{ q1.x, q1.y, q2.x, q2.y });
            },
            .cubic => |p| {
                const q1 = P.px(area, at, p[1]);
                const q2 = P.px(area, at, p[2]);
                const q3 = P.px(area, at, p[3]);
                dumpPrint("C{d:.3} {d:.3} {d:.3} {d:.3} {d:.3} {d:.3}", .{ q1.x, q1.y, q2.x, q2.y, q3.x, q3.y });
            },
            .conic => |cc| {
                const q = P.px(area, at, cc.p[2]);
                dumpPrint("L{d:.3} {d:.3}", .{ q.x, q.y });
            },
        };
        dumpPrint("Z", .{});
    }
}

fn dumpPrint(comptime fmt: []const u8, args: anytype) void {
    var buf: [256]u8 = undefined;
    const t = std.fmt.bufPrint(&buf, fmt, args) catch return;
    dump_svg.appendSlice(state.gpa, t) catch {};
}

/// Frame times over a sliding window: each frame's time from the start of
/// `frame` to its end (building the UI and drawing it), kept for
/// `frame_window_ns`, averaged for the status bar.
const frame_window_ns: i96 = 30 * std.time.ns_per_s;
const FrameSample = struct { at: i96, ns: i96 };
var frame_samples: [8192]FrameSample = undefined;
var frame_head: usize = 0;
var frame_count: usize = 0;
/// GRAVEN_FRAME_LOG set: each frame's time printed.
var frame_log = false;

fn recordFrame(at: i96, ns: i96) void {
    frame_samples[(frame_head + frame_count) % frame_samples.len] = .{ .at = at, .ns = ns };
    if (frame_count < frame_samples.len) frame_count += 1 else frame_head = (frame_head + 1) % frame_samples.len;
    // Drop what has slid out of the window.
    while (frame_count > 0 and at - frame_samples[frame_head].at > frame_window_ns) {
        frame_head = (frame_head + 1) % frame_samples.len;
        frame_count -= 1;
    }
}

/// The average frame time in the window, ms, and how many frames it holds.
fn frameAverage() struct { ms: f64, n: usize } {
    if (frame_count == 0) return .{ .ms = 0, .n = 0 };
    var total: i96 = 0;
    for (0..frame_count) |k| total += frame_samples[(frame_head + k) % frame_samples.len].ns;
    return .{ .ms = @as(f64, @floatFromInt(total)) / @as(f64, @floatFromInt(frame_count)) / 1e6, .n = frame_count };
}

var elements_log_opened = false;

fn frame() !dvui.App.Result {
    keymap.beginFrame();
    if (!elements_log_opened) {
        elements_log_opened = true;
        if (platform.env("GRAVEN_ELEMENTS_LOG")) |path| elements_log = std.Io.Dir.cwd().createFile(dvui.io, path, .{}) catch null;
    }
    // Elements drawn outside any group (menus, the tools) are in none.
    elem_group = "";
    base_group = "";
    // A press away from a field being edited ends the edit first.
    accepted.on_accept = newFieldStep;
    accepted.beginFrame();
    if (leave_field) {
        leave_field = false;
        // Fields are in the panes' own subwindows too (pinned over the
        // canvas): none keeps the keyboard, the main window takes it.
        for (all_panes) |p| if (p.sub_id) |id| dvui.focusWidget(null, id, null);
        dvui.focusSubwindow(dvui.currentWindow().data().id, null);
        dvui.focusWidget(null, null, null);
    }
    // Where the selection and the flow cursor are before this frame's keys.
    const step_from = stepSignature();
    // Buttons pressed last frame (or by a script): their actions.
    dispatchButtons();
    if (sample_sketch_space) {
        sample_sketch_space = false;
        newSketchInOwnSpace();
        followHome();
        if (sketch_edit != null) {
            _ = skEdit(.{ .circle = .{ .c = .{ .x = 0, .y = 0 }, .r = 12 } });
            _ = skEdit(.{ .circle = .{ .c = .{ .x = 0, .y = 0 }, .r = 5 } });
        }
    }
    ghost_pane.fieldsFollowTheme();
    const frame_start: std.Io.Timestamp = .now(dvui.io, .awake);
    defer {
        const end: std.Io.Timestamp = .now(dvui.io, .awake);
        recordFrame(end.nanoseconds, frame_start.durationTo(end).nanoseconds);
        if (frame_log) std.debug.print("frame {d:.2} ms\n", .{@as(f64, @floatFromInt(frame_start.durationTo(end).nanoseconds)) / 1e6});
    }
    // Glyph fields made since the last frame.
    if (atlas) |*ga| _ = ga.collect();
    if (dump_path) |p| {
        dump_frame += 1;
        if (dump_svg.items.len > 0) {
            const head = "<svg xmlns=\"http://www.w3.org/2000/svg\"><path fill=\"none\" d=\"";
            const doc = std.mem.concat(state.gpa, u8, &.{ head, dump_svg.items, "\"/></svg>\n" }) catch "";
            std.Io.Dir.cwd().writeFile(dvui.io, .{ .sub_path = p, .data = doc }) catch {};
            dump_svg.clearAndFree(state.gpa);
        }
    }
    if (desktop.take()) |s| applyDesktop(dvui.currentWindow(), s);
    // `graven-gui file.graven` opens that document.
    if (!opened_arg) {
        opened_arg = true;
        if (dvui.App.main_init) |mi| {
            const args = mi.minimal.args.toSlice(dvui.currentWindow().arena()) catch &.{};
            if (args.len > 1) openDocument(args[1]);
        }
        // GRAVEN_SAMPLE=hp15c or keyboard: a new canvas with that sample, for
        // trying the app (and its tests) without the menus.
        exact_text = platform.env("GRAVEN_EXACT_TEXT") != null;
        // GRAVEN_FONTS_WINDOW set: the Fonts window opens at start.
        if (platform.env("GRAVEN_FONTS_WINDOW") != null) fontwin.open = true;
        frame_log = platform.env("GRAVEN_FRAME_LOG") != null;
        keymap.log = platform.env("GRAVEN_KEY_LOG") != null;
        if (platform.env("GRAVEN_DUMP_OUTLINES")) |v| dump_path = v;
        if (platform.env("GRAVEN_TEXT_GAMMA")) |v| glyphs.gamma = std.fmt.parseFloat(f64, v) catch glyphs.gamma;
        if (platform.env("GRAVEN_TEXT_DARKEN")) |v| glyphs.darken = std.fmt.parseFloat(f64, v) catch glyphs.darken;
        if (platform.env("GRAVEN_SAMPLE")) |which| {
            if (canvas_prompt) createCanvas(.mm);
            // The two keyboards are example files (examples/, from the
            // repository's root), opened as untitled copies.
            if (std.mem.eql(u8, which, "hp15c")) openExample("examples/hp15c.graven") else if (std.mem.eql(u8, which, "keyboard")) openExample("examples/pc-keyboard.graven") else if (std.mem.eql(u8, which, "text")) _ = loadText() catch {} else if (std.mem.eql(u8, which, "sketch")) loadSketchSample() else if (std.mem.eql(u8, which, "sketch-panel")) loadSketchPanelSample() else if (std.mem.eql(u8, which, "sketch-space")) {
                sample_sketch_space = true;
            } else if (std.mem.eql(u8, which, "columns")) loadColumnsSample() catch {} else if (std.mem.eql(u8, which, "columns-free")) loadColumnsSampleWith(false) catch {};
        }
        // GRAVEN_FIGURE=file.svg: that drawing imported as a figure, made
        // the context.
        if (platform.env("GRAVEN_FIGURE")) |path| {
            if (canvas_prompt) createCanvas(.mm);
            importFigure(path);
        }
        // GRAVEN_VIEW=cx,cy,ppm: the view's centre (mm) and zoom (px/mm).
        if (platform.env("GRAVEN_VIEW")) |v| {
            var it = std.mem.splitScalar(u8, v, ',');
            var vals: [3]f64 = .{ state.view.cx, state.view.cy, state.view.ppm };
            for (&vals) |*x| x.* = std.fmt.parseFloat(f64, it.next() orelse break) catch x.*;
            state.view.cx = vals[0];
            state.view.cy = vals[1];
            state.view.ppm = vals[2];
            state.view.fit = null;
        }
    }
    try update();
    updateModeStack();
    // Digraphs take their characters before anything reads them; then the
    // place text is typed this frame is the next one's.
    digraphEvents();
    caret_mark = null;
    defer {
        digraphHint();
        caseHint();
        caseOverlay();
        text_wanted = dvui.currentWindow().textInputRequested();
    }

    var root = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .style = .window });
    defer root.deinit();
    // Undo and redo take their keys before any widget does.
    historyKeys(root.data());
    autosaveTick(root.data().id);
    // The fonts window, a window of its own, while open.
    fontwin.window(fontHost(), state.gpa);
    displayWindow();
    sizeWindow();

    if (titleBar()) |r| return r;

    // No document yet: the start screen, none of the canvas's interface.
    if (!canvas_prompt) ribbon();
    if (canvas_prompt) {
        startScreen();
        startPrompts();
        savePrefsIfChanged();
        updateWindowTitle();
        if (quit_now) return .close;
        return .ok;
    }

    {
        // The body, the docked bottom bar and the bottom edge's strip are
        // placed explicitly, so a tall pane can never push them off the
        // bottom of the window.
        var rest = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both });
        defer rest.deinit();
        body_px = rest.data().borderRectScale().r;
        panesForView();
        const size = rest.data().contentRect();
        const t: f32 = tab_size;
        // The edges' strips and the views; the panes lie over the views
        // (`overlays`), never moving them.
        const body_h = @max(0, size.h - t);
        {
            var body = dvui.box(@src(), .{ .dir = .horizontal }, .{ .rect = .{ .x = 0, .y = 0, .w = size.w, .h = body_h } });
            defer body.deinit();
            sideStrip(&tree_pane, body_h, 1);
            viewArea();
            rightStrip(body_h);
        }
        {
            // The bottom edge: the bottom bar's tab, as wide as the bar.
            var strip = dvui.box(@src(), .{}, .{ .rect = .{ .x = 0, .y = size.h - t, .w = size.w, .h = t }, .background = true, .color_fill = .{ .color = colors.titlebar } });
            defer strip.deinit();
            applyTab(&bottom_pane, ghost_pane.tab(&bottom_pane, .{ .x = t, .y = 0, .w = @max(0, size.w - 2 * t), .h = t }, 3));
        }
    }
    try overlays();
    // The ribbon's drops, over the panes.
    if (!canvas_prompt) ribbonDrops();
    savePrefsIfChanged();
    updateWindowTitle();
    if (quit_now) return .close;
    // Ghosts answer the pointer on their tabs when hot edges are on;
    // auto-hide panes always. Then the slides, and the hot corners.
    ghost_pane.hotEdges(&all_panes, root.data().id);
    ghost_pane.slide(&all_panes, root.data().id);
    hotCorners(root.data().id);
    sparkFrameEnd();
    revealStep(step_from);
    return .ok;
}

// Panes ---------------------------------------------------------------------
//
// The tree, the tools with the properties, and the bottom bar (the
// expression and status lines) are ghost panes (see ghost.zig): attached to
// an edge of the window, with a tab along that edge whose icons choose the
// pane's mode (ghost over the canvas, docked beside it, or hidden), and
// whose body makes a ghost pane active or ghost again.

var tree_pane: ghost_pane.Pane = .{ .id = "browser", .name = "Browser", .edge = .left, .size = default_tree_width, .look = .{} };
/// The right edge holds two panes, one above the other: the tool palette
/// and the properties. They meet at `tools_height` below the top, which
/// the grip between their tabs moves.
var tools_pane: ghost_pane.Pane = .{ .id = "tools", .name = "Tools", .edge = .right, .size = default_properties_width, .look = .{} };
var props_pane: ghost_pane.Pane = .{ .id = "properties", .name = "Properties", .edge = .right, .size = default_properties_width, .look = .{} };
/// The tool palette's height, logical pixels.
var tools_height: f32 = 260;
const split_grip = 8;
/// The grip between the right edge's panes is being dragged.
var split_dragging = false;
const min_pane_height = 48;
/// Docked by default: the expression line is typed into often.
var bottom_pane: ghost_pane.Pane = .{ .id = "expression-bar", .name = "Expression bar", .edge = .bottom, .size = default_status_height, .pinned = true, .active = true, .reveal = 1, .look = .{} };
const all_panes = [_]*ghost_pane.Pane{ &tree_pane, &tools_pane, &props_pane, &bottom_pane };

// Files ------------------------------------------------------------------------
//
// A document file holds the model as the history's checkpoint and the op
// log since it (see layout.history): saved, it reopens with its undo
// history. Save writes the whole file beside the old one and renames it
// over it, so a failed save never leaves half a file. New, Open and Quit
// with unsaved changes first ask whether to save them.

/// The document's file, once saved or opened (owned).
var file_path: ?[]u8 = null;

const FilePromptKind = enum { open, save_as, import_text, import_sheet, import_figure, replace_figure, export_sheet, export_3mf };
/// A file name is being asked for.
var file_prompt: ?FilePromptKind = null;
var file_prompt_new = false;

/// What waits on the unsaved-changes question, or on a save.
const Pending = union(enum) {
    new_canvas,
    open,
    quit,
    /// An example document, opened as an untitled copy.
    example: []const u8,
};
var leave_prompt: ?Pending = null;
var after_save: ?Pending = null;
var quit_now = false;

/// The extension Graven's documents take.
const doc_ext = ".graven";

fn setFilePath(path: ?[]const u8) void {
    // A document's fonts are found beside it from now on.
    if (fonts_from) |f| state.gpa.free(f);
    fonts_from = null;
    // Copied before the old one is freed: `path` may be it.
    const next = if (path) |p| state.gpa.dupe(u8, p) catch null else null;
    if (file_path) |old| state.gpa.free(old);
    file_path = next;
    if (file_path) |p| {
        state.file_name = std.fs.path.basename(p);
        state.file_name_set = true;
        noteRecent(p);
    } else {
        state.file_name = "untitled";
        state.file_name_set = false;
    }
}

var shown_title: [256]u8 = undefined;
var shown_title_len: usize = 0;

/// The window's title for the desktop: the file, marked while unsaved.
fn updateWindowTitle() void {
    if (dvui.backend.kind != .sdl3) return;
    var buf: [256]u8 = undefined;
    const dirty = !canvas_prompt and hist.isDirty();
    const t = std.fmt.bufPrintSentinel(&buf, "{s}{s} — Graven", .{ if (dirty) "• " else "", state.file_name }, 0) catch return;
    if (std.mem.eql(u8, t, shown_title[0..shown_title_len])) return;
    @memcpy(shown_title[0..t.len], t);
    shown_title_len = t.len;
    _ = dvui.backend.c.SDL_SetWindowTitle(dvui.currentWindow().backend.impl.window, t.ptr);
}

/// Does `p` now, or first asks about unsaved changes.
fn leave(p: Pending) void {
    if (!canvas_prompt and hist.isDirty()) {
        leave_prompt = p;
    } else proceed(p);
}

fn proceed(p: Pending) void {
    switch (p) {
        .new_canvas => newCanvas(),
        .open => {
            askForFile(.open);
        },
        .quit => quit_now = true,
        .example => |path| openExample(path),
    }
}

/// Saves to the document's file, or asks for one.
fn save() void {
    if (file_path) |p| {
        _ = writeDocument(p);
    } else saveAs();
}

fn saveAs() void {
    askForFile(.save_as);
}

// Files: writing, autosave, recovery and other writers -----------------------
//
// A save appends a segment to the document's file when the file is as this
// run left it, and otherwise writes the whole file beside it and renames
// it over it. Every few minutes (`files.autosave_minutes` in the config, 0
// for never) the steps since the last write are appended as unsaved work,
// which a later run can recover if this one ends without saving. Before
// every write the file is read again: if another run (or anything else)
// has written to it, nothing is written and the user decides.

/// This run, as the writer of what it adds to files: a fresh random ID.
var this_run: history.Writer = .{ .id = @splat(0) };
var device_buf: [platform.host_name_max]u8 = undefined;

fn initWriter() void {
    var random: [16]u8 = undefined;
    dvui.io.random(&random);
    const device = platform.hostName(&device_buf);
    this_run = .{ .id = history.writerId(random), .device = device, .tool = history.tool_version };
}

fn nowSeconds() i64 {
    return std.Io.Clock.real.now(dvui.io).toSeconds();
}

/// "2026-11-10 23:31" (UTC), for names and messages.
fn stamp(buf: []u8, seconds: i64, sep: u8) []const u8 {
    const es: std.time.epoch.EpochSeconds = .{ .secs = @intCast(@max(0, seconds)) };
    const yd = es.getEpochDay().calculateYearDay();
    const md = yd.calculateMonthDay();
    const ds = es.getDaySeconds();
    return std.fmt.bufPrint(buf, "{d}-{d:0>2}-{d:0>2} {d:0>2}{c}{d:0>2}", .{ yd.year, md.month.numeric(), md.day_index + 1, ds.getHoursIntoDay(), sep, ds.getMinutesIntoHour() }) catch "";
}

var autosave_minutes: u32 = 2;
/// Set when a write was refused or put off; cleared by the next save.
var autosave_paused = false;

/// Another run has written to the file: the write of this kind waits for
/// the user's choice.
var contention: ?history.WriteKind = null;

/// A file opened with unsaved steps in it, waiting for the user to keep or
/// discard them.
var recovery: ?struct { opened: history.Opened, path: []u8 } = null;

/// Whether a prompt about files is up, over the new-canvas prompt.
fn filePromptOpen() bool {
    return file_prompt != null or leave_prompt != null or recovery != null or contention != null;
}

/// Writes the document to `path` as a save.
fn writeDocument(path: []const u8) bool {
    return writeTo(path, .save, false);
}

/// `path` with " (<what> <time>)" before its extension: a backup or a copy.
fn sideName(buf: []u8, path: []const u8, what: []const u8) []const u8 {
    const ext = std.fs.path.extension(path);
    var tb: [32]u8 = undefined;
    const now = nowSeconds();
    return std.fmt.bufPrint(buf, "{s} ({s} {s}.{d:0>2}){s}", .{ path[0 .. path.len - ext.len], what, stamp(&tb, now, '.'), @as(u64, @intCast(@mod(now, 60))), if (ext.len > 0) ext else doc_ext }) catch path;
}

/// Copies the file at `path` aside, as it is, before it is overwritten.
fn backup(path: []const u8, buf: []u8) ?[]const u8 {
    const name = sideName(buf, path, "backup");
    const dir = std.Io.Dir.cwd();
    dir.copyFile(path, dir, name, dvui.io, .{}) catch return null;
    return name;
}

/// Writes `bytes` as the whole file at `path`: beside it first, then
/// renamed over it, so there is never half a file.
fn writeWhole(path: []const u8, bytes: []const u8) bool {
    var tmp_buf: [std.fs.max_path_bytes]u8 = undefined;
    const tmp = std.fmt.bufPrint(&tmp_buf, "{s}.saving", .{path}) catch return false;
    const dir = std.Io.Dir.cwd();
    dir.writeFile(dvui.io, .{ .sub_path = tmp, .data = bytes }) catch return false;
    dir.rename(tmp, dir, path, dvui.io) catch return false;
    return true;
}

/// Writes `bytes` into the file at `path` at offset `at`, and syncs it.
fn writeAt(path: []const u8, bytes: []const u8, at: u64) bool {
    const io = dvui.io;
    const f = std.Io.Dir.cwd().openFile(io, path, .{ .mode = .read_write }) catch return false;
    defer f.close(io);
    f.writePositionalAll(io, bytes, at) catch return false;
    f.sync(io) catch return false;
    return true;
}

/// Writes one write from the history to `path`.
fn put(path: []const u8, w: *const history.Write) bool {
    return if (w.at) |at| writeAt(path, w.bytes, at) else writeWhole(path, w.bytes);
}

/// Whether the file at `path` is as this run last left it; true when it
/// is gone (nothing to overwrite). Null when it cannot be read.
fn fileUnchanged(path: []const u8) ?bool {
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(1 << 30)) catch |err| switch (err) {
        error.FileNotFound => return true,
        else => return null,
    };
    defer state.gpa.free(bytes);
    return history.fileIsAsLeft(&hist, bytes);
}

/// Writes the document to `path`: a save, or an autosave of the steps
/// since the last write. Appends when it can; `fresh` writes the whole
/// file. Returns whether it was written.
fn writeTo(path: []const u8, kind: history.WriteKind, fresh_asked: bool) bool {
    var fresh = fresh_asked;
    const same = if (file_path) |p| std.mem.eql(u8, p, path) else false;
    if (!same) {
        fresh = true;
    } else if (!fresh) {
        const unchanged = fileUnchanged(path) orelse {
            state.status = "The document's file could not be read: nothing was written. ";
            return false;
        };
        if (!unchanged) {
            contention = kind;
            dvui.refresh(null, @src(), null);
            return false;
        }
        // Gone: written afresh.
        if (std.Io.Dir.cwd().access(dvui.io, path, .{})) |_| {} else |_| fresh = true;
    }
    // The views as they are, written with it.
    hist.views = encodeViews();
    var w = history.prepareWrite(&hist, state.gpa, this_run, nowSeconds(), kind, fresh) catch |err| {
        if (err == error.SavedStateLost) {
            autosave_paused = true;
            state.status = "Autosave is waiting for a save: the history no longer holds the saved document. ";
        } else state.status = "The document could not be made ready to write. ";
        return false;
    };
    defer w.deinit(state.gpa);
    if (!put(path, &w)) {
        state.status = "The document could not be written there. ";
        return false;
    }
    history.wrote(&hist, &w);
    if (kind == .save) {
        setFilePath(path);
        autosave_paused = false;
        state.status = "Saved. ";
    }
    dvui.refresh(null, @src(), null);
    if (kind == .save) if (after_save) |p| {
        after_save = null;
        proceed(p);
    };
    return true;
}

/// Every `autosave_minutes`, the steps since the last write go to the
/// file as unsaved work.
fn autosaveTick(id: dvui.Id) void {
    if (autosave_minutes == 0) return;
    if (dvui.timerDone(id)) autosave();
    if (dvui.timerDoneOrNone(id)) dvui.timer(id, @intCast(@as(u64, autosave_minutes) * 60 * std.time.us_per_s));
}

fn autosave() void {
    const path = file_path orelse return;
    if (autosave_paused or canvas_prompt or contention != null or recovery != null) return;
    if (!history.changedSinceWrite(&hist)) return;
    if (writeTo(path, .autosave, false)) {
        var tb: [32]u8 = undefined;
        state.status = std.fmt.bufPrint(&status_buf, "Autosaved at {s} UTC (unsaved until you save). ", .{stamp(&tb, nowSeconds(), ':')[11..]}) catch "Autosaved. ";
    }
}

var status_buf: [256]u8 = undefined;

/// The user chose not to save: the steps autosaved since the last save
/// are dropped from the file too, so they are not offered back later.
fn discardAutosaved() void {
    const path = file_path orelse return;
    var d = (history.prepareDiscard(&hist, state.gpa, this_run, nowSeconds()) catch return) orelse return;
    defer d.deinit(state.gpa);
    if ((fileUnchanged(path) orelse false) and put(path, &d)) history.wroteDiscard(&hist, &d);
}

var import_count: u64 = 0;
var import_status_buf: [320]u8 = undefined;

/// Where imported text goes: at the flow cursor; else at the end of the
/// flow chosen in the Browser; else into a new flow, unplaced.
const ImportTarget = union(enum) { cursor, flow_end: layout.model.ObjectId, new_flow };

fn importTarget() ImportTarget {
    if (track_cursor != null) return .cursor;
    if (state.context == .flow) if (state.model.flowIndex(state.context.flow) != null) return .{ .flow_end = state.context.flow };
    return .new_flow;
}

var import_title_buf: [160]u8 = undefined;

fn importTitle() []const u8 {
    return switch (importTarget()) {
        .cursor => "Import text (RTF or plain) at the flow cursor",
        .flow_end => |id| std.fmt.bufPrint(&import_title_buf, "Import text (RTF or plain) at the end of {s}", .{state.model.flows.items[state.model.flowIndex(id).?].name}) catch "Import text at the end of the flow",
        .new_flow => "Import text (RTF or plain) as a new flow",
    };
}

/// Reads the file at `path` (RTF, else plain text) into a flow (see
/// `importTarget`), recording where it came from, as one undoable step,
/// and says what came in and what did not.
fn importText(path: []const u8) void {
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(64 << 20)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    defer state.gpa.free(bytes);
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const aa = arena.allocator();
    const is_rtf = std.mem.startsWith(u8, std.mem.trimStart(u8, bytes, " \t\r\n"), "{\\rtf");
    const doc = if (is_rtf) richtext.rtf.read(aa, bytes) catch {
        state.status = "That RTF file could not be read. ";
        return;
    } else layout.import.plain(aa, bytes) catch return;
    import_count += 1;
    const key = mergeKey(.{ "import", import_count });
    const target = importTarget();
    // The flow, the place in it, the base style and the lines' spacing.
    var flow: layout.model.ObjectId = .none;
    var at: usize = 0;
    var base: layout.model.StyleId = undefined;
    switch (target) {
        .cursor => {
            const c = track_cursor.?;
            const region = state.model.regionsIn(c.parent)[c.region];
            flow = region.flow;
            at = c.index;
            base = region.style orelse (labelStyleIn(key) catch return);
        },
        .flow_end => |id| {
            flow = id;
            at = state.model.flows.items[state.model.flowIndex(id).?].items.items.len;
            base = labelStyleIn(key) catch return;
        },
        .new_flow => {
            const stem = std.fs.path.stem(path);
            flow = hist.doMerged(&state.model, key, .addFlow, .{if (stem.len > 0) stem else "Imported"}) catch {
                state.status = "The text could not be imported. ";
                return;
            };
            base = labelStyleIn(key) catch return;
        },
    }
    const pitch = state.model.flowPitch(flow) orelse styleLinePitch(base) orelse 5;
    var rep = layout.import.rich(state.gpa, &hist, &state.model, key, flow, at, doc, base, pitch) catch {
        state.status = "The text could not be imported. ";
        return;
    };
    // Where it came from: a URI (relative in the document's folder), the
    // hash of what was read, and when.
    {
        const abs = std.fs.path.resolve(aa, &.{path}) catch path;
        const doc_dir: ?[]const u8 = if (file_path) |fp| std.fs.path.dirname(std.fs.path.resolve(aa, &.{fp}) catch fp) else null;
        const uri = layout.import.sourceUri(aa, abs, doc_dir) catch "";
        const hash = layout.import.sha256Hex(bytes);
        if (uri.len > 0) _ = hist.doMerged(&state.model, key, .addFlowSource, .{ flow, .{ .uri = uri, .sha256 = &hash, .imported = nowSeconds() } }) catch {};
    }
    if (target == .new_flow) state.context = .{ .flow = flow };
    defer rep.deinit(state.gpa);
    // Fonts made for the text's families: their installed faces, with
    // their own italic and bolds.
    var missing: usize = 0;
    for (rep.fonts_made.items) |made| {
        const found = fontwin.installedFamily(state.gpa, made.family) orelse {
            missing += 1;
            continue;
        };
        setFamily(key, made.style, found.main, found.variants);
    }
    var notes: std.Io.Writer.Allocating = .init(arena.allocator());
    const w = &notes.writer;
    w.print("Imported {d} paragraph{s}", .{ rep.paragraphs, if (rep.paragraphs == 1) "" else "s" }) catch {};
    if (target == .new_flow) w.print(" into a new flow, {s}, unplaced (give it a track from a track's Flow)", .{state.model.flows.items[state.model.flowIndex(flow).?].name}) catch {};
    if (rep.styles_made > 0) w.print(", {d} new style{s}", .{ rep.styles_made, if (rep.styles_made == 1) "" else "s" }) catch {};
    if (rep.paragraph_styles_made > 0) w.print(", {d} new paragraph style{s}", .{ rep.paragraph_styles_made, if (rep.paragraph_styles_made == 1) "" else "s" }) catch {};
    w.writeAll(".") catch {};
    const sk = rep.skipped;
    if (missing > 0) w.print(" {d} font famil{s} not installed.", .{ missing, if (missing == 1) "y" else "ies" }) catch {};
    if (rep.tabs > 0) w.print(" {d} tab{s} set as spaces.", .{ rep.tabs, if (rep.tabs == 1) "" else "s" }) catch {};
    if (rep.coloured > 0) w.print(" Colour not kept ({d} span{s}).", .{ rep.coloured, if (rep.coloured == 1) "" else "s" }) catch {};
    if (sk.pictures > 0) w.print(" {d} picture{s} left out.", .{ sk.pictures, if (sk.pictures == 1) "" else "s" }) catch {};
    if (sk.table_rows > 0) w.print(" Tables as tabbed lines ({d} row{s}).", .{ sk.table_rows, if (sk.table_rows == 1) "" else "s" }) catch {};
    if (sk.footnotes > 0) w.print(" {d} footnote{s} left out.", .{ sk.footnotes, if (sk.footnotes == 1) "" else "s" }) catch {};
    if (sk.objects > 0) w.print(" {d} object{s} left out.", .{ sk.objects, if (sk.objects == 1) "" else "s" }) catch {};
    if (sk.fields > 0) w.print(" {d} field{s} kept as their text.", .{ sk.fields, if (sk.fields == 1) "" else "s" }) catch {};
    const msg = notes.written();
    const n = @min(msg.len, import_status_buf.len - 1);
    @memcpy(import_status_buf[0..n], msg[0..n]);
    import_status_buf[n] = ' ';
    state.status = import_status_buf[0 .. n + 1];
}

/// The sheet to export: the one shown, else the one chosen.
fn sheetToExport() ?layout.model.ObjectId {
    if (activeKind() == .sheet) {
        const id: layout.model.ObjectId = @enumFromInt(vl.views[vl.active].target);
        if (state.model.sheetIndex(id) != null) return id;
    }
    if (state.context == .sheet) if (state.model.sheetIndex(state.context.sheet) != null) return state.context.sheet;
    return null;
}

var sheet_export_name: [512]u8 = undefined;

/// The file a sheet is exported to at first: its name, `.csv`, beside the
/// document when it has a file.
fn sheetExportName() []const u8 {
    const id = sheetToExport() orelse return "";
    const name = state.model.sheets.items[state.model.sheetIndex(id).?].name;
    const dir: []const u8 = if (file_path) |fp| (std.fs.path.dirname(fp) orelse "") else "";
    return (if (dir.len > 0)
        std.fmt.bufPrint(&sheet_export_name, "{s}/{s}.csv", .{ dir, name })
    else
        std.fmt.bufPrint(&sheet_export_name, "{s}.csv", .{name})) catch "legends.csv";
}

var threemf_name: [600]u8 = undefined;

/// The panel's name as a .3mf file beside the document.
fn threeMfName() []const u8 {
    const pi = exportPart() orelse return "";
    const name = state.model.panels.items[pi].name;
    const dir: []const u8 = if (file_path) |fp| (std.fs.path.dirname(fp) orelse "") else "";
    return (if (dir.len > 0)
        std.fmt.bufPrint(&threemf_name, "{s}/{s}.3mf", .{ dir, name })
    else
        std.fmt.bufPrint(&threemf_name, "{s}.3mf", .{name})) catch "panel.3mf";
}

/// Writes the chosen panel as a 3MF at `path`: its fabrication layers
/// planned over its layout, one object a colour, as built (as the CLI's
/// `graven 3mf` does).
fn exportThreeMf(path: []const u8) void {
    const pi = exportPart() orelse return;
    const labels = if (state.labels) |*l| l else return;
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const entries = layout.place.handoffs(state.gpa, &state.model, labels, thread_entries) catch {
        state.status = "The 3MF could not be made. ";
        return;
    };
    defer state.gpa.free(entries);
    var placed = layout.place.solveWith(state.gpa, &state.model, .{ .panel = pi }, labels, entries) catch {
        state.status = "The 3MF could not be made. ";
        return;
    };
    defer placed.deinit();
    const zip = blk: {
        const plan = layout.fab.plan(a, &state.model, pi, &placed, faceTable()) catch break :blk null;
        const slabs = layout.fab.slabs(a, plan.steps) catch break :blk null;
        const parts = layout.threemf.parts(a, slabs, state.model.exportTolerance(), .colours) catch break :blk null;
        const ps = layout.threemf.orient(a, parts, .bottom) catch break :blk null;
        break :blk layout.threemf.package(a, state.model.panels.items[pi].name, ps) catch null;
    } orelse {
        state.status = "The 3MF could not be made. ";
        return;
    };
    std.Io.Dir.cwd().writeFile(dvui.io, .{ .sub_path = path, .data = zip }) catch {
        state.status = "That file could not be written. ";
        return;
    };
    state.status = std.fmt.bufPrint(&import_status_buf, "Exported {s} as 3MF ({d} KB). ", .{ std.fs.path.basename(path), zip.len / 1024 }) catch "Exported. ";
}

/// Writes the sheet to export as CSV at `path`.
fn exportSheet(path: []const u8) void {
    const id = sheetToExport() orelse return;
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const csv = layout.import.sheetToCsv(arena.allocator(), &state.model, id) catch {
        state.status = "The sheet could not be written out. ";
        return;
    };
    std.Io.Dir.cwd().writeFile(dvui.io, .{ .sub_path = path, .data = csv }) catch {
        state.status = "That file could not be written. ";
        return;
    };
    const sh = state.model.sheets.items[state.model.sheetIndex(id).?];
    state.status = std.fmt.bufPrint(&import_status_buf, "Exported {d} row{s} and {d} column{s} to {s}. ", .{ sh.rows.items.len, if (sh.rows.items.len == 1) "" else "s", sh.columns.items.len + 1, if (sh.columns.items.len == 0) "" else "s", std.fs.path.basename(path) }) catch "Exported. ";
}

/// Where a legend table goes: into the sheet shown or chosen; else a new
/// sheet over the grid, track or panel chosen.
fn sheetImportTarget() ?layout.import.SheetTarget {
    const m = &state.model;
    if (activeKind() == .sheet) {
        const id: layout.model.ObjectId = @enumFromInt(vl.views[vl.active].target);
        if (m.sheetIndex(id) != null) return .{ .into = id };
    }
    return switch (state.context) {
        .sheet => |id| if (m.sheetIndex(id) != null) .{ .into = id } else null,
        .grid => |g| .{ .new = .{ .name = "Legends", .scope = m.gridsIn(g.parent)[g.index].id } },
        .region => |r| .{ .new = .{ .name = "Legends", .scope = m.regionsIn(r.parent)[r.region].id } },
        .panel => |pi| .{ .new = .{ .name = "Legends", .scope = m.panels.items[pi].id } },
        else => null,
    };
}

var sheet_import_title: [160]u8 = undefined;

fn sheetImportTitle() []const u8 {
    const t = sheetImportTarget() orelse return "Import a legend sheet (CSV)";
    return switch (t) {
        .into => |id| std.fmt.bufPrint(&sheet_import_title, "Import a table (CSV) into {s}", .{state.model.sheets.items[state.model.sheetIndex(id).?].name}) catch "Import a table into the sheet",
        .new => "Import a table (CSV) as a new legend sheet",
    };
}

/// Reads the table at `path` (CSV, or tab- or semicolon-separated) into a
/// legend sheet (see `sheetImportTarget`), recording where it came from,
/// as one undoable step; a new sheet opens beside the canvas.
fn importSheet(path: []const u8) void {
    var target = sheetImportTarget() orelse return;
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(16 << 20)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    defer state.gpa.free(bytes);
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const aa = arena.allocator();
    const table = layout.import.parseTable(aa, bytes) catch return;
    if (table.rows.len < 2) {
        state.status = "That table has no rows under its header. ";
        return;
    }
    // A new sheet is named after the file, as an identifier
    // (keyboard-legends.csv: keyboardLegends), numbered if taken.
    var sheet_name_buf: [100]u8 = undefined;
    if (target == .new) {
        const stem = std.fs.path.stem(path);
        target.new.name = state.model.freshOrSame(&sheet_name_buf, .sheets, stem, "Legends");
    }
    import_count += 1;
    const key = mergeKey(.{ "sheet import", import_count });
    const rep = layout.import.sheetFromTable(state.gpa, &hist, &state.model, key, target, table) catch {
        state.status = "The table could not be imported. ";
        return;
    };
    {
        const abs = std.fs.path.resolve(aa, &.{path}) catch path;
        const doc_dir: ?[]const u8 = if (file_path) |fp| std.fs.path.dirname(std.fs.path.resolve(aa, &.{fp}) catch fp) else null;
        const uri = layout.import.sourceUri(aa, abs, doc_dir) catch "";
        const hash = layout.import.sha256Hex(bytes);
        if (uri.len > 0) _ = hist.doMerged(&state.model, key, .addSheetSource, .{ rep.sheet, .{ .uri = uri, .sha256 = &hash, .imported = nowSeconds() } }) catch {};
    }
    if (target == .new) openBeside(.{ .kind = .sheet, .target = @intFromEnum(rep.sheet) });
    var probs_rows: std.ArrayList(usize) = .empty;
    var probs_cols: std.ArrayList(usize) = .empty;
    state.model.sheetProblems(aa, rep.sheet, &probs_rows, &probs_cols) catch {};
    const msg = std.fmt.bufPrint(&import_status_buf, "Imported: {d} row{s} matched, {d} added, {d} column{s} added, {d} cell{s} set.{s}{s}{s} ", .{
        rep.rows_matched,                                  if (rep.rows_matched == 1) "" else "s",
        rep.rows_added,                                    rep.columns_added,
        if (rep.columns_added == 1) "" else "s",           rep.cells_set,
        if (rep.cells_set == 1) "" else "s",               if (rep.repeated > 0) " A name came twice: the later row stands." else "",
        if (probs_rows.items.len > 0) " Some rows name no key here (marked)." else "", if (probs_cols.items.len > 0) " Some columns match no slot (marked)." else "",
    }) catch "Imported. ";
    state.status = msg;
}

/// Opens the document at `path`, replacing the one open; when it holds
/// unsaved steps, asks first whether to keep them.
fn openDocument(path: []const u8) void {
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(1 << 30)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    defer state.gpa.free(bytes);
    var opened = history.openFile(state.gpa, bytes) catch |err| {
        state.status = switch (err) {
            error.BadFile, error.NoModel => "That is not a Graven document. ",
            error.TooNew => "That document is from a newer Graven. ",
            error.BadChecksum, error.Truncated => "That document is damaged where its model is stored: it cannot be opened. ",
            else => "That document could not be opened. ",
        };
        return;
    };
    if (opened.unsaved != null) {
        const p = state.gpa.dupe(u8, path) catch {
            opened.model.deinit();
            opened.history.deinit();
            return;
        };
        recovery = .{ .opened = opened, .path = p };
        dvui.refresh(null, @src(), null);
        return;
    }
    install(&opened, path);
    state.status = if (opened.damaged) "Opened. The end of the file was damaged: the last changes in it are lost. " else "Opened. ";
}

/// Opens the document at `path` as an untitled copy (Save asks where):
/// an example stays as it is. Its fonts are still looked for beside it.
fn openExample(path: []const u8) void {
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(1 << 30)) catch {
        state.status = "The example is not there: Graven looks for it in examples/, from where it was started. ";
        return;
    };
    defer state.gpa.free(bytes);
    var opened = history.openFile(state.gpa, bytes) catch {
        state.status = "The example could not be opened. ";
        return;
    };
    // Not a recovery: an example has no unsaved steps worth keeping.
    opened.discardUnsaved() catch {};
    install(&opened, path);
    setFilePath(null);
    fonts_from = state.gpa.dupe(u8, path) catch null;
    hist.markSaved();
    // Shown whole: its panels fill the view.
    var all: ?geom.Box = null;
    for (state.model.panels.items) |pn| {
        all = if (all) |b| b.join(pn.box()) else pn.box();
    }
    if (all) |b| state.view.fit = b;
    state.status = "Opened the example as a new, untitled document. ";
}

/// Makes `opened` the document open, from `path`.
fn install(opened: *history.Opened, path: []const u8) void {
    newCanvas();
    forgetThreads();
    state.model.deinit();
    state.model = opened.model;
    hist.deinit();
    hist = opened.history;
    canvas_prompt = false;
    shown_space = 0;
    state.context = if (state.model.spaces.items.len > 0) .{ .space = 0 } else .worksheet;
    for (state.model.styles.items) |st| {
        if (std.mem.eql(u8, st.name, "Label")) state.label_style = st.id;
    }
    state.view.fit = canvas_view;
    loadViews(opened.views);
    setFilePath(path);
    autosave_paused = false;
    dvui.refresh(null, @src(), null);
}

/// A centred modal prompt over the canvas.
fn promptWindow(src: std.builtin.SourceLocation, id: usize, w: f32, h: f32) ?*dvui.FloatingWindowWidget {
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return null;
    const S = struct {
        var r: dvui.Rect = .{};
    };
    S.r = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    return dvui.floatingWindow(src, .{ .rect = &S.r, .resize = .none, .modal = true }, overlayOptions(id));
}

/// The file holds steps after its last save, by a run that ended (or is
/// still open elsewhere) without saving them: keep them, or go back to
/// the save.
fn recoveryPrompt() void {
    const saved_group = pushGroup("dialog.recovery");
    defer popGroup(saved_group);
    const rec = &(recovery orelse return);
    const u = rec.opened.unsaved.?;
    var fw = promptWindow(@src(), 14, 600, 175) orelse return;
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.label(@src(), "{s} has changes that were never saved", .{std.fs.path.basename(rec.path)}, .{ .font = dvui.Font.theme(.heading) });
    var tb: [32]u8 = undefined;
    const by = if (u.device.len > 0) u.device else "another computer";
    dvui.label(@src(), "Made after its last save, on {s} at {s} UTC,", .{ by, stamp(&tb, u.time, ':') }, .{ .margin = .{ .y = 6 } });
    dvui.labelNoFmt(@src(), "by a session that ended without saving them, or is still open there.", .{}, .{});
    if (rec.opened.damaged) dvui.labelNoFmt(@src(), "The end of the file was damaged: the last of them are lost.", .{}, .{});
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 10 } });
    defer row.deinit();
    keyButton(@src(), "Cancel", 0, .{});
    keyButton(@src(), "Discard them", 0, .{});
    keyButton(@src(), "Keep them", 0, .{});
}

/// Installs the recovered document and writes its file afresh under this
/// run, so no file mixes two runs' unsaved work.
fn finishRecovery(rec: anytype, kind: history.WriteKind) void {
    install(&rec.opened, rec.path);
    _ = writeTo(rec.path, kind, true);
    state.gpa.free(rec.path);
    recovery = null;
}

/// Another run (or program) wrote to the file since this one did.
fn contentionPrompt() void {
    const saved_group = pushGroup("dialog.contention");
    defer popGroup(saved_group);
    var fw = promptWindow(@src(), 15, 640, 175) orelse return;
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.label(@src(), "{s} was changed elsewhere", .{state.file_name}, .{ .font = dvui.Font.theme(.heading) });
    dvui.labelNoFmt(@src(), "Another Graven session, or another program, has written to it", .{}, .{ .margin = .{ .y = 6 } });
    dvui.labelNoFmt(@src(), "since this one did, so nothing was written. Your changes are still here.", .{}, .{});
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 10 } });
    defer row.deinit();
    if (file_path == null) {
        contention = null;
        return;
    }
    keyButton(@src(), "Not now", 0, .{});
    keyButton(@src(), "Load theirs", 0, .{});
    keyButton(@src(), "Save mine as…", 0, .{});
    keyButton(@src(), "Overwrite with mine", 0, .{});
}

/// Asks for a file to open, import, save or export as: the system's file
/// dialog where there is one, else Graven's own prompt for a typed name.
fn askForFile(kind: FilePromptKind) void {
    file_prompt = kind;
    file_prompt_new = true;
    file_prompt_system = systemFileDialog();
}

/// Whether the file prompt now open is to be the system's dialog (shown by
/// the prompt's next frame).
var file_prompt_system = false;
/// Frames still to draw before the system's file dialog opens, so what
/// asked for it (a menu) has gone from the screen while it holds the frame.
var system_dialog_wait: u8 = 0;

/// Whether the system has a file dialog to show: Windows' and macOS's own;
/// on Linux, one of the programs tinyfiledialogs runs (zenity, kdialog …)
/// on the path. Never under the GUI's tests.
fn systemFileDialog() bool {
    if (comptime builtin.is_test or !dvui.useTinyFileDialogs) return false;
    if (comptime builtin.os.tag != .linux) return true;
    const cached = struct {
        var known: ?bool = null;
    };
    if (cached.known) |k| return k;
    const path = platform.env("PATH") orelse "";
    var found = false;
    var it = std.mem.splitScalar(u8, path, ':');
    outer: while (it.next()) |dir| {
        if (dir.len == 0) continue;
        for ([_][]const u8{ "zenity", "kdialog", "qarma", "matedialog", "yad" }) |prog| {
            var buf: [std.fs.max_path_bytes]u8 = undefined;
            const full = std.fmt.bufPrint(&buf, "{s}/{s}", .{ dir, prog }) catch continue;
            std.Io.Dir.cwd().access(dvui.io, full, .{}) catch continue;
            found = true;
            break :outer;
        }
    }
    cached.known = found;
    return found;
}

/// The system's file dialog for `kind`: to open or import, the file types
/// it reads; to save or export, a name to write. Null when cancelled.
fn systemFileChoice(a: std.mem.Allocator, kind: FilePromptKind) ?[:0]const u8 {
    return switch (kind) {
        .open => dvui.dialogNativeFileOpen(a, .{ .title = "Open a document", .filters = &.{"*" ++ doc_ext}, .filter_description = "Graven documents" }) catch null,
        .import_text => dvui.dialogNativeFileOpen(a, .{ .title = "Import text", .filters = &.{ "*.rtf", "*.txt" }, .filter_description = "RTF or plain text" }) catch null,
        .import_sheet => dvui.dialogNativeFileOpen(a, .{ .title = "Import a legend sheet", .filters = &.{"*.csv"}, .filter_description = "CSV files" }) catch null,
        .import_figure => dvui.dialogNativeFileOpen(a, .{ .title = "Import a figure", .filters = &.{"*.svg"}, .filter_description = "SVG drawings" }) catch null,
        .replace_figure => dvui.dialogNativeFileOpen(a, .{ .title = "Replace the figure's drawing", .filters = &.{"*.svg"}, .filter_description = "SVG drawings" }) catch null,
        .save_as => dvui.dialogNativeFileSave(a, .{ .title = "Save the document as", .path = file_path orelse "untitled" ++ doc_ext, .filters = &.{"*" ++ doc_ext}, .filter_description = "Graven documents" }) catch null,
        .export_sheet => dvui.dialogNativeFileSave(a, .{ .title = "Export the legend sheet", .path = sheetExportName(), .filters = &.{"*.csv"}, .filter_description = "CSV files" }) catch null,
        .export_3mf => dvui.dialogNativeFileSave(a, .{ .title = "Export the panel as 3MF", .path = threeMfName(), .filters = &.{"*.3mf"}, .filter_description = "3MF files" }) catch null,
    };
}

/// What the file prompt does with the file chosen.
fn fileChosen(kind: FilePromptKind, path: []const u8) void {
    switch (kind) {
        .open => openDocument(path),
        .import_text => importText(path),
        .import_sheet => importSheet(path),
        .import_figure => importFigure(path),
        .replace_figure => replaceFigureFrom(path),
        .export_sheet => exportSheet(path),
        .export_3mf => exportThreeMf(path),
        .save_as => {
            // A name without an extension takes Graven's.
            const full = if (std.fs.path.extension(path).len == 0) (std.mem.concat(dvui.currentWindow().arena(), u8, &.{ path, doc_ext }) catch path) else path;
            if (!writeDocument(full)) after_save = null;
        },
    }
}

/// The file prompt: a name to open or save as; Enter or the button does
/// it, Esc or Cancel closes it.
fn filePrompt(kind: FilePromptKind) void {
    if (file_prompt_system) {
        // The system's dialog, in place of Graven's prompt; it holds the
        // frame while open, so a frame is drawn first (the menu closed).
        if (file_prompt_new) {
            file_prompt_new = false;
            system_dialog_wait = 3;
        }
        if (system_dialog_wait > 0) {
            system_dialog_wait -= 1;
            dvui.refresh(null, @src(), null);
            return;
        }
        file_prompt_system = false;
        file_prompt = null;
        dvui.refresh(null, @src(), null);
        const chosen = systemFileChoice(dvui.currentWindow().arena(), kind) orelse {
            after_save = null;
            return;
        };
        fileChosen(kind, chosen);
        return;
    }
    const saved_group = pushGroup("dialog.file");
    defer popGroup(saved_group);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 460;
    const h: f32 = 185;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(12));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), switch (kind) {
        .open => "Open a document",
        .save_as => "Save the document as",
        .import_text => importTitle(),
        .import_sheet => sheetImportTitle(),
        .import_figure => "Import a figure from an SVG file",
        .replace_figure => "Replace the figure's drawing from an SVG file",
        .export_sheet => "Export the legend sheet as CSV",
        .export_3mf => "Export the panel as 3MF (its fabrication layers)",
    }, .{}, .{ .font = dvui.Font.theme(.heading) });
    var go = false;
    var cancel = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => go = true,
            kact("dialog.cancel") => cancel = true,
            else => continue,
        }
        e.handle(@src(), fw.data());
    }
    var path: []const u8 = "";
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        defer row.deinit();
        propName("File");
        const initial = switch (kind) {
            .save_as => file_path orelse "untitled" ++ doc_ext,
            .export_sheet => sheetExportName(),
            .export_3mf => threeMfName(),
            else => "",
        };
        var te = dvui.textEntry(@src(), .{ .text_initial = initial }, .{ .expand = .horizontal, .id_extra = @intFromEnum(kind) });
        defer te.deinit();
        if (file_prompt_new) {
            // The prompt's window takes the keys, so Enter and Esc reach it.
            dvui.focusSubwindow(fw.data().id, null);
            dvui.focusWidget(te.data().id, fw.data().id, null);
            file_prompt_new = false;
        }
        if (te.enter_pressed) go = true;
        path = dvui.currentWindow().arena().dupe(u8, std.mem.trim(u8, te.textGet(), " ")) catch "";
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), switch (kind) {
            .open => "Open",
            .save_as => "Save",
            .import_text, .import_sheet, .import_figure, .replace_figure => "Import",
            .export_sheet, .export_3mf => "Export",
        }, 0, .{});
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) go = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (cancel) {
        file_prompt = null;
        after_save = null;
        dvui.refresh(null, @src(), null);
        return;
    }
    if (!go or path.len == 0) return;
    file_prompt = null;
    dvui.refresh(null, @src(), null);
    fileChosen(kind, path);
}

/// Unsaved changes: Save (then go on), Don't save, or Cancel.
fn leavePrompt(p: Pending) void {
    const saved_group = pushGroup("dialog.leave");
    defer popGroup(saved_group);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 460;
    const h: f32 = 150;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none, .modal = true }, overlayOptions(13));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.label(@src(), "{s} has unsaved changes", .{state.file_name}, .{ .font = dvui.Font.theme(.heading) });
    const doing = switch (p) {
        .new_canvas => "starting a new canvas",
        .open => "opening another document",
        .quit => "quitting",
        .example => "opening the example",
    };
    dvui.label(@src(), "Save them before {s}?", .{doing}, .{ .margin = .{ .y = 6 } });
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 10 } });
    defer row.deinit();
    keyButton(@src(), "Cancel", 0, .{});
    keyButton(@src(), "Don't save", 0, .{});
    keyButton(@src(), "Save", 0, .{});
}

// Undo -------------------------------------------------------------------------
//
// Every change to the model is an action, done through `act` (or `actV`
// for those that cannot fail, `actM` for runs that undo as one step) and
// logged by the history: undo restores its checkpoint and replays the
// steps before the last; redo applies undone steps again.

var hist: history.History = undefined;

fn act(comptime tag: history.Tag, args: history.Args(@tagName(tag))) history.Error!history.Result(@tagName(tag)) {
    const before = Abandoned.now();
    const r = try hist.do(&state.model, tag, args);
    before.dropNew();
    return r;
}

/// The constraints abandoned (`constrain.abandoned`: an object they name
/// removed) before a change.
const Abandoned = struct {
    ids: [64]layout.model.ObjectId = undefined,
    n: usize = 0,

    fn now() Abandoned {
        var r: Abandoned = .{};
        for (state.model.constraints.items) |c| if (r.n < r.ids.len and constrain.abandoned(&state.model, c)) {
            r.ids[r.n] = c.id;
            r.n += 1;
        };
        return r;
    }

    /// The constraints the change abandoned (an equal size left with one
    /// object among them) removed in the same step (the owner,
    /// 2026-11-24). Those abandoned before it are left to be chosen and
    /// deleted (the Constraints list).
    fn dropNew(before: Abandoned) void {
        const m = &state.model;
        if (m.constraints.items.len == 0) return;
        const after = now();
        for (after.ids[0..after.n]) |id| {
            if (std.mem.indexOfScalar(layout.model.ObjectId, before.ids[0..before.n], id) != null) continue;
            _ = hist.join(m, .removeConstraint, .{id}) catch {};
        }
    }
};

/// An action that cannot fail but for memory to log it.
fn actV(comptime tag: history.Tag, args: history.Args(@tagName(tag))) void {
    const before = Abandoned.now();
    hist.do(&state.model, tag, args) catch {
        state.status = "That change could not be recorded. ";
        return;
    };
    before.dropNew();
}

/// The logical group of a context's elements (elements.zig).
fn contextGroup(c: Context) []const u8 {
    return switch (c) {
        .region => "track",
        .sketch => "sketch-view",
        .sketch_def => "sketch",
        .figure_def => "figure",
        else => @tagName(c),
    };
}

/// The Browser's context for an object reached by name.
fn contextOfRef(ref: layout.model.Model.Ref) ?Context {
    return switch (ref) {
        .space => |si| .{ .space = si },
        .panel => |pi| .{ .panel = pi },
        .region => |r| .{ .region = .{ .parent = r.parent, .region = r.region } },
        .grid => |g| .{ .grid = .{ .parent = g.parent, .index = g.index } },
        .art => |a| .{ .art = .{ .panel = a.panel, .index = a.index } },
        .tile => |t| .{ .tile = t },
        .collection => |c| switch (c) {
            .styles => .styles,
            .prototypes => .prototypes,
            .flows => .flows,
            .sheets => .sheets,
            .sketches => .sketches,
            .figures => .figures,
            .processes => .processes,
            .materials => .materials,
            .plans => .plans,
            .paragraph_styles => null,
        },
        .style => |id| .{ .style = id },
        .prototype => |id| .{ .prototype = id },
        .flow => |id| .{ .flow = id },
        .sheet => |id| .{ .sheet = id },
        .sketch => |i| .{ .sketch_def = i },
        .figure => |i| .{ .figure_def = i },
        .process => |id| .{ .process = id },
        .material => |id| .{ .material = id },
        .plan => |id| .{ .plan = id },
        .paragraph_style => null,
    };
}

/// Asked for by the tests: the keyboard leaves its field this frame.
var leave_field = false;

/// A field's accepted value is a step of its own, never merged into the
/// step before (an earlier accept in the same field included).
fn newFieldStep() void {
    hist.merge_key = null;
}

/// An action that joins the step before when that had the same `key`: a
/// run of nudges, or typing, undone as one.
fn actM(key: u64, comptime tag: history.Tag, args: history.Args(@tagName(tag))) history.Error!history.Result(@tagName(tag)) {
    const before = Abandoned.now();
    const r = try hist.doMerged(&state.model, key, tag, args);
    before.dropNew();
    return r;
}

fn mergeKey(parts: anytype) u64 {
    var h: std.hash.Wyhash = .init(0);
    std.hash.autoHashStrat(&h, parts, .Deep);
    return h.final();
}

/// The app's own keys (mode `global`): undo and redo (Ctrl+Z, Ctrl+Shift+Z,
/// and Ctrl+Y off macOS; held, they repeat), save, save as, open, new. Cmd
/// on macOS.
fn historyKeys(wd: *dvui.WidgetData) void {
    if (file_prompt != null or leave_prompt != null) return;
    for (dvui.events()) |*e| {
        if (keymap.shadowed(e, kmode("global"))) continue;
        const inv = keymap.match1(e, kmode("global")) orelse continue;
        // Taken even where it does nothing (Ctrl+S with no document).
        _ = runAction(inv);
        e.handle(@src(), wd);
        dvui.refresh(null, @src(), null);
    }
}

/// Runs an action of the app's own (`file.*`, `edit.*`) or of the view
/// (`view.*`): for keys and menus alike. Whether it was one of those and
/// could be done now.
fn runAction(inv: keymap.Invocation) bool {
    switch (inv.action) {
        kact("panes.toggle-auto") => toggleAutoPanes(),
        kact("view.scrolling") => {
            scroll_mode = switch (inv.arg) {
                1 => .zoom,
                2 => .pan,
                else => .auto,
            };
            state.status = switch (scroll_mode) {
                .auto => "Scrolling: a trackpad pans, a mouse wheel zooms; Ctrl and scrolling zooms. ",
                .zoom => "Scrolling zooms; Shift and scrolling pans across. ",
                .pan => "Scrolling pans; Ctrl and scrolling zooms. ",
            };
        },
        kact("views.split-across"), kact("views.split-down"), kact("views.close"), kact("views.maximize"), kact("views.next") => {
            if (canvas_prompt) return false;
            switch (inv.action) {
                kact("views.split-across") => splitView(.across),
                kact("views.split-down") => splitView(.down),
                kact("views.close") => if (vl.open[vl.active]) closeView(vl.active),
                kact("views.maximize") => vl.toggleMaximize(vl.active),
                else => {
                    // The next open view (Shift: the one before), in order.
                    var k: usize = vl.active;
                    for (0..docviews.max_views) |_| {
                        k = if (inv.arg == 1) (k + docviews.max_views - 1) % docviews.max_views else (k + 1) % docviews.max_views;
                        if (vl.open[k]) break;
                    }
                    if (k != vl.active) activateView(@intCast(k));
                },
            }
            dvui.refresh(null, @src(), null);
        },
        kact("panes.layout-next") => nextLayout(),
        kact("panes.layout-save-as") => {
            layout_prompt = true;
            layout_prompt_new = true;
        },
        kact("panes.layout-reset") => resetLayout(),
        kact("file.new") => leave(.new_canvas),
        kact("file.open") => leave(.open),
        kact("file.save"), kact("file.save-as"), kact("edit.undo"), kact("edit.redo") => {
            if (canvas_prompt) return false;
            switch (inv.action) {
                kact("file.save") => save(),
                kact("file.save-as") => saveAs(),
                kact("edit.undo") => undo(),
                else => redo(),
            }
        },
        kact("fab.check") => {
            if (canvas_prompt) return false;
            // In a manufacturing view: its plan's operations.
            if (activeKind() == .manufacture) {
                runPlanChecks(@enumFromInt(vl.views[vl.active].target));
            } else runChecks(checkTarget());
            return true;
        },
        kact("view.canvas-theme") => setCanvasTheme(if (inv.arg < 0 or inv.arg >= canvas_theme.all.len) canvas_theme.current.next() else @enumFromInt(inv.arg)),
        kact("view.snap-grid") => {
            snap_grid = !snap_grid;
            state.status = if (snap_grid) "Drags snap to the grid (Alt held lets go). " else "Drags no longer snap to the grid. ";
            return true;
        },
        kact("view.reveal") => {
            if (canvas_prompt) return false;
            revealContext();
        },
        kact("view.zoom-fit"), kact("view.zoom-all"), kact("view.zoom-to"), kact("view.zoom-in"), kact("view.zoom-out"), kact("view.frame-edit") => {
            if (canvas_prompt or !(state.view.ppm > 0)) return false;
            switch (inv.action) {
                kact("view.zoom-fit") => zoomToContext(),
                kact("view.zoom-all") => state.view.fit = contentExtents(),
                kact("view.zoom-to") => zoomToPercent(@floatFromInt(inv.arg)),
                kact("view.frame-edit") => frameEdit(),
                kact("view.zoom-in") => zoomToPercent(display.nextZoom(zoomPercent(), true)),
                else => zoomToPercent(display.nextZoom(zoomPercent(), false)),
            }
        },
        // A button's action given a key: its handler, on the context.
        else => {
            // The flow cursor's actions, from a menu: at the cursor.
            if (track_cursor != null and flowAction(inv)) {
                dvui.refresh(null, @src(), null);
                return true;
            }
            for (button_handlers) |h| if (h.action == inv.action) {
                h.run(inv.arg);
                dvui.refresh(null, @src(), null);
                return true;
            };
            return false;
        },
    }
    dvui.refresh(null, @src(), null);
    return true;
}

fn undo() void {
    // Undo and redo do not reveal (the selection is not in the history).
    no_step_reveal = true;
    const done = hist.undo(&state.model) catch {
        state.status = "Undo failed. ";
        return;
    };
    state.status = if (done) "" else "Nothing to undo. ";
    afterHistory();
}

fn redo() void {
    no_step_reveal = true;
    const done = hist.redoStep(&state.model) catch {
        state.status = "Redo failed. ";
        return;
    };
    state.status = if (done) "" else "Nothing to redo. ";
    afterHistory();
}

/// After undo or redo, what pointed into the model may point at nothing:
/// the context, the selection and the flow cursor fall back to what still
/// exists.
fn afterHistory() void {
    selection.clearRetainingCapacity();
    track_cursor = null;
    state.moving = null;
    if (!contextValid(state.context)) {
        if (shown_space >= state.model.spaces.items.len) shown_space = 0;
        state.context = workspaceContext();
    }
    if (shown_space >= state.model.spaces.items.len) shown_space = 0;
}

fn contextValid(c: Context) bool {
    const m = &state.model;
    const np = m.panels.items.len;
    return switch (c) {
        .file, .worksheet, .prototypes, .selection => true,
        .space => |si| si < m.spaces.items.len,
        .panel => |pi| pi < np,
        .region => |r| m.hasParent(r.parent) and r.region < m.regionsIn(r.parent).len,
        .row => |r| m.hasParent(r.parent) and r.region < m.regionsIn(r.parent).len and r.row < segmentCount(r.parent, r.region),
        .tile => |id| m.tileIndex(id) != null and !m.tileConst(id).removed,
        .art => |l| l.panel < np and l.index < m.panels.items[l.panel].art.items.len,
        .group => |g| m.group(g) != null,
        .view => |v| v.space < m.spaces.items.len and v.index < m.spaces.items[v.space].views.items.len,
        .layer => |l| l.space < m.spaces.items.len and l.index < m.spaces.items[l.space].layers.items.len,
        .image => |im| im.space < m.spaces.items.len and im.index < m.spaces.items[im.space].images.items.len,
        .figure_place => |fc| fc.space < m.spaces.items.len and fc.index < m.spaces.items[fc.space].figure_places.items.len,
        .guide => |g| g.space < m.spaces.items.len and g.index < m.spaces.items[g.space].guides.items.len,
        .sketch => |sc| sc.space < m.spaces.items.len and sc.index < m.spaces.items[sc.space].sketch_views.items.len,
        .sketches => true,
        .sketch_def => |i| i < m.sketches.items.len,
        .figures => true,
        .figure_def => |i| i < m.figures.items.len,
        .grid => |g| m.hasParent(g.parent) and g.index < m.gridsIn(g.parent).len,
        .prototype => |id| m.protoIndex(id) != null,
        .flows => true,
        .flow => |id| m.flowIndex(id) != null,
        .sheets => true,
        .sheet => |id| m.sheetIndex(id) != null,
        .styles => true,
        .style => |id| m.styleIndex(id) != null,
        .templates => true,
        .template => |id| m.styleTemplate(id) != null,
        .processes => true,
        .process => |id| m.processIndex(id) != null,
        .plans, .materials => true,
        .plan => |id| m.planIndex(id) != null,
        .material => |id| m.materialIndex(id) != null,
        .constraints => true,
        .constraint => |id| constraintById(id) != null,
    };
}

// Settings --------------------------------------------------------------------
//
// Preferences are read from the config files at start (see settings.zig:
// shared.toml, then local.toml over it) and written back when they change.
// Shared (how the user likes to work): the units a new canvas starts in,
// text construction, hot edges. Local (this machine's layout): each pane's
// mode, where the right edge's panes meet.

var prefs_store: ?settings_file.Store = null;

const Prefs = struct {
    units: layout.model.Units,
    show_construction: bool,
    grid: bg_grid.Mode,
    snap_grid: bool,
    boundary_mode: bool,
    canvas_theme: canvas_theme.Theme,
    scroll: ScrollMode,
    ribbon: RibbonSize,
    display: display.Correction,
    px_per_mm: ?f32,
    /// The pane layout in use: its name and how the panes are now.
    layout_name: [40]u8,
    layout_name_len: usize,
    layout: layouts.Layout,

    fn eql(a: Prefs, b: Prefs) bool {
        return std.meta.eql(a, b);
    }
};

/// The keys of each pane's mode before layouts (read once, to carry a
/// machine's arrangement over), in `all_panes` order.
const pane_keys = [all_panes.len][]const u8{ "panes.tree.mode", "panes.tools.mode", "panes.properties.mode", "panes.bottom.mode" };

var saved_prefs: ?Prefs = null;

fn currentPrefs() Prefs {
    var name: [40]u8 = @splat(0);
    @memcpy(name[0..layout_name.len], layout_name);
    return .{ .units = last_units, .show_construction = show_construction, .grid = grid_mode, .snap_grid = snap_grid, .boundary_mode = boundary_mode, .canvas_theme = canvas_theme.current, .scroll = scroll_mode, .ribbon = ribbon_size, .display = display.get(), .px_per_mm = display.measuredPxPerMm(), .layout_name = name, .layout_name_len = layout_name.len, .layout = currentLayout() };
}

/// Reads the config files and applies what they set; what they leave out
/// keeps its default.
fn tomlFloat(v: settings_file.Value) ?f32 {
    return switch (v) {
        .float => |f| @floatCast(f),
        .integer => |i| @floatFromInt(i),
        else => null,
    };
}

fn loadPrefs() void {
    var ps = settings_file.load(state.gpa, dvui.io);
    loadLocale(&ps);
    // How often unsaved work goes to the file, in minutes (0: never).
    if (ps.get("files.autosave_minutes")) |v| if (v == .integer) {
        autosave_minutes = @intCast(std.math.clamp(v.integer, 0, 30));
    };
    if (ps.get("canvas.units")) |v| if (v == .string) if (std.meta.stringToEnum(layout.model.Units, v.string)) |u| {
        last_units = u;
    };
    if (ps.get("view.grid")) |v| if (v == .string) if (std.meta.stringToEnum(bg_grid.Mode, v.string)) |g| {
        // How grids are drawn; "none" (whether there is one is now the
        // document's) reads as lines.
        grid_mode = if (g == .none) .lines else g;
    };
    if (ps.get("view.snap_grid")) |v| if (v == .boolean) {
        snap_grid = v.boolean;
    };
    if (ps.get("ribbon.size")) |v| if (v == .string) if (std.meta.stringToEnum(RibbonSize, v.string)) |z| {
        ribbon_size = z;
    };
    if (ps.get("view.boundary_mode")) |v| if (v == .boolean) {
        boundary_mode = v.boolean;
    };
    if (ps.get("view.canvas_theme")) |v| if (v == .string) if (std.meta.stringToEnum(canvas_theme.Theme, v.string)) |t| {
        canvas_theme.current = t;
        setPalette();
    };
    // How scrolling acts: the machine's, as its pointing devices are.
    if (ps.get("view.scrolling")) |v| if (v == .string) if (std.meta.stringToEnum(ScrollMode, v.string)) |m| {
        scroll_mode = m;
    };
    {
        var dc: display.Correction = .{};
        if (ps.get("display.gamma")) |v| if (tomlFloat(v)) |f| {
            dc.gamma = f;
        };
        if (ps.get("display.white")) |v| if (tomlFloat(v)) |f| {
            dc.white = f;
        };
        if (platform.env("GRAVEN_DISPLAY")) |e| if (display.Correction.parse(e)) |c| {
            dc = c;
        };
        display.set(dc);
        if (ps.get("display.px_per_mm")) |v| display.setPxPerMm(tomlFloat(v));
    }
    if (ps.get("view.show_text_construction")) |v| if (v == .boolean) {
        show_construction = v.boolean;
    };
    // Hot corners: an action's name each, or "" for nothing.
    for ([_][]const u8{ "top_left", "top_right", "bottom_left", "bottom_right" }, 0..) |name, i| {
        var kb: [48]u8 = undefined;
        const key = std.fmt.bufPrint(&kb, "panes.hot_corners.{s}", .{name}) catch continue;
        if (ps.get(key)) |v| if (v == .string) {
            if (v.string.len == 0) {
                corner_actions[i] = null;
            } else if (keymap.R.actionByName(v.string)) |a| {
                corner_actions[i] = a;
            } else state.status = "A hot corner names an action Graven does not have. ";
        };
    }
    // The pane layout in use (local.toml), as the config has it.
    if (ps.get("panes.layout")) |v| if (v == .string) if (layouts.validName(v.string)) setLayoutName(v.string);
    applyLayout(layouts.read(&ps, layout_name));
    // From before layouts: the panes' modes and the split, carried over
    // into the layout (written back as this machine's overrides).
    if (ps.get("panes.layout") == null) {
        for (all_panes, pane_keys) |p, key| if (ps.get(key)) |v| if (v == .string) if (modeByName(v.string)) |m| {
            p.mode = if (m == .hidden) .hidden else .auto;
            p.pinned = m == .pinned;
            p.active = p.pinned;
        };
        if (ps.get("panes.tools_height")) |v| if (tomlFloat(v)) |f| {
            tools_height = f;
        };
    }
    if (ps.problem()) |msg| state.status = msg;
    loadRecent(&ps);
    loadDigraphs(&ps);
    prefs_store = ps;
    saved_prefs = currentPrefs();
}

// Locale ----------------------------------------------------------------------
//
// The user's languages and measurement system: from `[locale]` in the
// config files when set there, else from the system (see locale.zig). The
// measurement system picks a new canvas's units (mm or inches) until the
// user has chosen units (`canvas.units`). The languages are kept for the
// interface text to come.

/// Preferred languages, most preferred first.
var languages: []const locale.Locale = &.{};
var measurement: locale.Measurement = .metric;
var measurement_source: locale.Source = .default;

/// The system's preferred languages, as SDL reports them.
fn systemLanguages(gpa: std.mem.Allocator) []const locale.Locale {
    if (dvui.backend.kind != .sdl3) return &.{};
    const c = dvui.backend.c;
    var n_locales: c_int = 0;
    const list = c.SDL_GetPreferredLocales(&n_locales) orelse return &.{};
    defer c.SDL_free(@ptrCast(list));
    const out = gpa.alloc(locale.Locale, @intCast(n_locales)) catch return &.{};
    var n: usize = 0;
    for (0..@intCast(n_locales)) |i| {
        const l = list[i] orelse continue;
        const lang = l.*.language orelse continue;
        out[n] = .{
            .language = gpa.dupe(u8, std.mem.span(lang)) catch continue,
            .country = if (l.*.country) |ct| gpa.dupe(u8, std.mem.span(ct)) catch null else null,
        };
        n += 1;
    }
    return out[0..n];
}

/// Reads `[locale]` from the config files and the system's locale, and
/// sets the languages, the measurement system and from it the default
/// units of a new canvas.
fn loadLocale(ps: *const settings_file.Store) void {
    const gpa = state.gpa;
    languages = systemLanguages(gpa);
    // `languages = ["en-GB", "de"]` (or one tag) in the config wins.
    if (ps.get("locale.languages")) |v| {
        var list: std.ArrayList(locale.Locale) = .empty;
        const tags: []const settings_file.Value = switch (v) {
            .array => |xs| xs,
            .string => &.{v},
            else => &.{},
        };
        for (tags) |t| if (t == .string) if (locale.parseTag(t.string)) |l| {
            list.append(gpa, .{ .language = gpa.dupe(u8, l.language) catch continue, .country = if (l.country) |ct| gpa.dupe(u8, ct) catch null else null }) catch {};
        };
        if (list.items.len > 0) languages = list.items;
    }
    const from_config: ?locale.Measurement = if (ps.get("locale.measurement")) |v| (if (v == .string) std.meta.stringToEnum(locale.Measurement, v.string) else null) else null;
    const d = locale.decide(from_config, locale.systemMeasurement(), languages);
    measurement = d.measurement;
    measurement_source = d.source;
    last_units = if (measurement == .imperial) .inch else .mm;
}

/// Writes the preferences back when one has changed since they were last
/// read or written.
fn roundTo(v: f32, k: f64) f64 {
    return @round(@as(f64, v) * k) / k;
}

fn savePrefsIfChanged() void {
    const ps = &(prefs_store orelse return);
    const now = currentPrefs();
    if (saved_prefs) |old| if (old.eql(now)) return;
    // A split being dragged is written once it rests.
    if (split_dragging) return;
    saved_prefs = now;
    ps.put("canvas.units", .{ .string = @tagName(now.units) }, .shared);
    ps.put("view.show_text_construction", .{ .boolean = now.show_construction }, .shared);
    ps.put("view.grid", .{ .string = @tagName(now.grid) }, .shared);
    ps.put("view.snap_grid", .{ .boolean = now.snap_grid }, .shared);
    ps.put("view.boundary_mode", .{ .boolean = now.boundary_mode }, .shared);
    ps.put("view.canvas_theme", .{ .string = @tagName(now.canvas_theme) }, .shared);
    ps.put("view.scrolling", .{ .string = @tagName(now.scroll) }, .local);
    // The ribbon's key size: this machine's (its screen).
    ps.put("ribbon.size", .{ .string = @tagName(now.ribbon) }, .local);
    // The screen's correction belongs to this machine.
    ps.put("display.gamma", .{ .float = roundTo(now.display.gamma, 100) }, .local);
    ps.put("display.white", .{ .float = roundTo(now.display.white, 100) }, .local);
    // Measured, else the estimate (written as 0: not measured).
    ps.put("display.px_per_mm", .{ .float = if (now.px_per_mm) |v| roundTo(v, 10000) else 0 }, .local);
    // The layout in use is this machine's; what has been changed by hand
    // goes in as this machine's overrides of it.
    ps.put("panes.layout", .{ .string = layout_name }, .local);
    writeLayout(ps, layout_name, now.layout, .local, false);
    if (ps.save(dvui.io)) |msg| state.status = msg;
}

/// Hot edges: holding the pointer on a ghost pane's tab activates it.

// Pane layouts ----------------------------------------------------------------
//
// Named arrangements of the panes (layouts.zig): each pane's mode, size
// and text scale. One is in use; View › Pane layout switches, saves the
// arrangement as a new one, or drops this machine's changes to it.

var layout_name_buf: [40]u8 = undefined;
var layout_name: []const u8 = "standard";

fn setLayoutName(n: []const u8) void {
    const k = @min(n.len, layout_name_buf.len);
    std.mem.copyForwards(u8, layout_name_buf[0..k], n[0..k]);
    layout_name = layout_name_buf[0..k];
}

/// A pane's state as a layout keeps it: hidden, pinned in, or auto-hide.
fn toLayoutMode(p: *const ghost_pane.Pane) layouts.Mode {
    if (p.chosen() == .hidden) return .hidden;
    return if (p.pinned) .pinned else .auto;
}

/// Sets the panes as layout `l` has them.
fn applyLayout(l: layouts.Layout) void {
    for (all_panes, l.panes) |p, set| {
        p.mode = if (set.mode == .hidden) .hidden else .auto;
        p.forced = null;
        p.view_hidden = null;
        p.pinned = set.mode == .pinned;
        p.active = p.pinned;
        p.hot = .{};
        if (set.size > 0) p.size = set.size;
        p.text_scale = set.text_scale;
    }
    tools_height = l.tools_height;
}

/// The panes as they are, as a layout (each pane's own mode, not one a
/// narrow window forced).
fn currentLayout() layouts.Layout {
    var l: layouts.Layout = .{ .panes = undefined, .tools_height = @round(tools_height) };
    for (all_panes, &l.panes) |p, *set| set.* = .{
        .mode = toLayoutMode(p),
        .size = if (p.edge == .bottom) 0 else @round(p.size),
        .text_scale = p.text_scale,
    };
    return l;
}

/// Writes layout `l` under `name` into `home`: every key (`all`), or only
/// those that differ from what the config already gives.
fn writeLayout(ps: *settings_file.Store, name: []const u8, l: layouts.Layout, home: anytype, all: bool) void {
    const was = layouts.read(ps, name);
    var kb: [160]u8 = undefined;
    for (std.enums.values(layouts.PaneId), l.panes, was.panes) |pid, set, old| {
        if (all or set.mode != old.mode) ps.put(layouts.key(&kb, name, pid, "mode"), .{ .string = @tagName(set.mode) }, home);
        // The column's width is the properties' to keep.
        if (pid != .@"expression-bar" and pid != .tools and (all or set.size != old.size)) ps.put(layouts.key(&kb, name, pid, "size"), .{ .integer = @intFromFloat(set.size) }, home);
        if (all or set.text_scale != old.text_scale) ps.put(layouts.key(&kb, name, pid, "text_scale"), .{ .float = roundTo(set.text_scale, 100) }, home);
    }
    if (all or l.tools_height != was.tools_height) ps.put(layouts.key(&kb, name, .tools, "height"), .{ .integer = @intFromFloat(l.tools_height) }, home);
}

/// The names of the layouts there are: the built-ins, then the config's.
fn layoutNames() []const []const u8 {
    const a = dvui.currentWindow().arena();
    const ps = &(prefs_store orelse return &.{});
    const keys = ps.keys(a) catch return &.{};
    return layouts.names(a, keys) catch &.{};
}

/// Puts layout `name` in use, as the config has it.
fn useLayout(name: []const u8) void {
    const ps = &(prefs_store orelse return);
    setLayoutName(name);
    applyLayout(layouts.read(ps, layout_name));
    state.status = "";
    dvui.refresh(null, @src(), null);
}

/// `panes.layout-next`: the next layout in the list.
fn nextLayout() void {
    const ns = layoutNames();
    if (ns.len == 0) return;
    var i: usize = 0;
    for (ns, 0..) |n, k| {
        if (std.mem.eql(u8, n, layout_name)) i = k;
    }
    const name = ns[(i + 1) % ns.len];
    useLayout(name);
    state.status = std.fmt.bufPrint(&layout_status, "Pane layout: {s}. ", .{name}) catch "";
}

var layout_status: [96]u8 = undefined;

/// Saves the panes as they are as layout `raw_name` (cleaned to a bare
/// key) in the shared settings, and puts it in use.
fn saveLayoutAs(raw_name: []const u8) void {
    const ps = &(prefs_store orelse return);
    var nb: [64]u8 = undefined;
    const name = layouts.cleanName(&nb, raw_name);
    if (!layouts.validName(name)) {
        state.status = "A layout's name needs letters or digits. ";
        return;
    }
    const now = currentLayout();
    writeLayout(ps, name, now, .shared, true);
    setLayoutName(name);
    applyLayout(layouts.read(ps, layout_name));
    if (ps.save(dvui.io)) |msg| state.status = msg else {
        state.status = std.fmt.bufPrint(&layout_status, "Saved the pane layout \"{s}\". ", .{layout_name}) catch "";
    }
}

/// Drops this machine's changes to the layout in use, back to the shared
/// settings' (or the built-in's) arrangement.
fn resetLayout() void {
    const ps = &(prefs_store orelse return);
    var kb: [80]u8 = undefined;
    _ = ps.dropLocal(layouts.prefix(&kb, layout_name));
    applyLayout(layouts.read(ps, layout_name));
    saved_prefs = currentPrefs();
    if (ps.save(dvui.io)) |msg| state.status = msg;
    dvui.refresh(null, @src(), null);
}

/// View › Pane layout › Save layout as… is asking for a name.
var layout_prompt = false;
var layout_prompt_new = false;

fn layoutPrompt() void {
    const saved_group = pushGroup("dialog.layout");
    defer popGroup(saved_group);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 420;
    const h: f32 = 170;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(16).override(.{ .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) } }));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), "Save the pane layout as", .{}, .{ .font = dvui.Font.theme(.heading) });
    var go = false;
    var cancel = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => go = true,
            kact("dialog.cancel") => cancel = true,
            else => continue,
        }
        e.handle(@src(), fw.data());
    }
    var name: []const u8 = "";
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        defer row.deinit();
        propName("Name");
        var te = dvui.textEntry(@src(), .{ .text_initial = layout_name }, .{ .expand = .horizontal });
        defer te.deinit();
        if (layout_prompt_new) {
            dvui.focusSubwindow(fw.data().id, null);
            dvui.focusWidget(te.data().id, fw.data().id, null);
            layout_prompt_new = false;
        }
        if (te.enter_pressed) go = true;
        name = dvui.currentWindow().arena().dupe(u8, te.textGet()) catch "";
    }
    dvui.labelNoFmt(@src(), "Kept in the shared settings; letters, digits, - and _.", .{}, .{ .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) } });
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), "Save", 0, .{ .style = .highlight });
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) go = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (cancel) {
        layout_prompt = false;
        dvui.refresh(null, @src(), null);
        return;
    }
    if (!go) return;
    layout_prompt = false;
    saveLayoutAs(name);
    dvui.refresh(null, @src(), null);
}

/// Where the body (all below the title bar) is, device pixels: its corners
/// are the hot corners.
var body_px: dvui.Rect.Physical = .{};

pub const Corner = enum { top_left, top_right, bottom_left, bottom_right };

/// What each hot corner does: an action, by name in the config
/// (`[panes.hot_corners]`, `bottom_right = "panes.toggle-auto"`), or
/// nothing. Bottom right shows or hides the auto-hide panes by default.
var corner_actions: [4]?keymap.ActionId = .{ null, null, null, kact("panes.toggle-auto") };
var corner_state: [4]struct { since: ?i128 = null, fired: bool = false } = @splat(.{});

/// How long the pointer must rest in a corner, ns.
const corner_delay_ns: i128 = 300 * std.time.ns_per_ms;

/// Hot corners, once a frame: the pointer resting in a corner of the body
/// (a tab's width square) runs that corner's action, once until it leaves.
fn hotCorners(timer_id: dvui.Id) void {
    if (canvas_prompt or body_px.w <= 0) return;
    const now = dvui.frameTimeNS();
    const m = dvui.currentWindow().mouse_pt;
    const t: f32 = tab_size * dvui.windowNaturalScale();
    const b = body_px;
    const squares = [4]dvui.Rect.Physical{
        .{ .x = b.x, .y = b.y, .w = t, .h = t },
        .{ .x = b.x + b.w - t, .y = b.y, .w = t, .h = t },
        .{ .x = b.x, .y = b.y + b.h - t, .w = t, .h = t },
        .{ .x = b.x + b.w - t, .y = b.y + b.h - t, .w = t, .h = t },
    };
    for (squares, &corner_state, corner_actions) |square, *st, act_id| {
        const a = act_id orelse continue;
        if (!square.contains(m)) {
            st.* = .{};
            continue;
        }
        if (st.fired) continue;
        const since = st.since orelse now;
        st.since = since;
        if (now - since >= corner_delay_ns) {
            st.fired = true;
            _ = runAction(.{ .action = a, .arg = 0 });
        } else {
            const us: i32 = @intCast(@divTrunc(since + corner_delay_ns - now, 1000) + 1);
            dvui.timer(timer_id, us);
        }
    }
}

/// `panes.toggle-auto`: brings every auto-hide pane in (and keeps it in,
/// as a click on its tab would), or, when all are in, lets them all go.
fn toggleAutoPanes() void {
    var any_out = false;
    for (all_panes) |p| if (p.mode == .auto and !p.active) {
        any_out = true;
    };
    for (all_panes) |p| {
        if (p.mode != .auto) continue;
        p.hot.clicked();
        if (any_out) p.active = true else ghost_pane.deactivate(p);
    }
    dvui.refresh(null, @src(), null);
}

/// The strips along the window's edges that hold the panes' tabs, logical
/// pixels.
const tab_size = 18;

/// The panes' sizes as Graven first opens (a layout sets them: see
/// layouts.zig).
const default_tree_width = 240;
const default_properties_width = 320;
/// The bottom area: the expression line above the status line, at the
/// interface's own text size (scaled with the bar's text).
const expression_line_height = 38;
const status_line_height = 32;
const default_status_height = expression_line_height + status_line_height;

fn expressionHeight() f32 {
    return @round(expression_line_height * bottom_pane.text_scale);
}

fn statusHeight() f32 {
    return @round(default_status_height * bottom_pane.text_scale);
}
/// Space between the key palette and the panes beside it.
const overlay_gap = 6;
/// How opaque an overlay's background is.
const overlay_alpha = 0.84;

/// The canvas's rectangle in logical pixels, from the last frame: overlays
/// anchor to it.
var canvas_rect: dvui.Rect = .{};
/// The views' whole region below the top tabs (logical): what the ghost
/// panes lie over and prompts centre on, whatever the splits.
var region_rect: dvui.Rect = .{};

/// A side edge's strip, holding its pane's tab as tall as the pane.
fn sideStrip(p: *ghost_pane.Pane, h: f32, id: usize) void {
    var strip = dvui.box(@src(), .{ .dir = .vertical }, .{
        .id_extra = id,
        .min_size_content = .{ .w = tab_size },
        .max_size_content = .width(tab_size),
        .expand = .vertical,
        .background = true,
        .color_fill = .{ .color = colors.titlebar },
    });
    defer strip.deinit();
    barEnd(strip.data());
    applyTab(p, ghost_pane.tab(p, .{ .x = 0, .y = tab_strip_h, .w = tab_size, .h = @max(0, h - tab_strip_h) }, id));
}

/// The tab bar runs the window's width: what lies beside the views (the
/// edges' strips, docked panes) starts below it, the bar's colour and its
/// bottom line drawn across their tops.
fn barEnd(wd: *dvui.WidgetData) void {
    const r = wd.borderRectScale();
    const s = r.s;
    const bar: dvui.Rect.Physical = .{ .x = r.r.x, .y = r.r.y, .w = r.r.w, .h = tab_strip_h * s };
    bar.fill(.{}, .{ .color = .{ .color = colors.titlebar } });
    (dvui.Rect.Physical{ .x = r.r.x, .y = r.r.y + (tab_strip_h - 1) * s, .w = r.r.w, .h = s }).fill(.{}, .{ .color = .{ .color = colors.edge.opacity(0.4) } });
}

/// Whether the right edge's column is laid out beside the canvas: either of
/// its panes is docked.
/// The tool palette's height for a right edge `h` tall, kept so both panes
/// keep some room.
fn toolsHeight(h: f32) f32 {
    return std.math.clamp(tools_height, min_pane_height, @max(min_pane_height, h - split_grip - min_pane_height));
}

/// The right edge's strip: the properties pane's tab. (The Tools pane is
/// retired, 2026-11-22: its tools are the ribbon's, its palettes its drop
/// panels.)
fn rightStrip(h: f32) void {
    var strip = dvui.box(@src(), .{ .dir = .vertical }, .{
        .min_size_content = .{ .w = tab_size },
        .max_size_content = .width(tab_size),
        .expand = .vertical,
        .background = true,
        .color_fill = .{ .color = colors.titlebar },
    });
    defer strip.deinit();
    barEnd(strip.data());
    const bh: f32 = tab_strip_h;
    applyTab(&props_pane, ghost_pane.tab(&props_pane, .{ .x = 0, .y = bh, .w = tab_size, .h = @max(0, h - bh) }, 4));
}

/// The grip between the right edge's tabs: dragged, it moves where the
/// tool palette ends and the properties begin.
fn splitGrip(strip: *dvui.WidgetData, at: f32) void {
    var grip = dvui.box(@src(), .{}, .{
        .rect = .{ .x = 0, .y = at, .w = tab_size, .h = split_grip },
        .background = true,
        .color_fill = .{ .color = colors.titlebar },
    });
    defer grip.deinit();
    const r = grip.data().contentRectScale().r;
    const ns = dvui.windowNaturalScale();
    // Three dots, to say it can be gripped.
    const mid: dvui.Point.Physical = .{ .x = r.x + r.w / 2, .y = r.y + r.h / 2 };
    for ([_]f32{ -4, 0, 4 }) |dx| {
        const d: dvui.Rect.Physical = .{ .x = mid.x + dx * ns - ns, .y = mid.y - ns, .w = 2 * ns, .h = 2 * ns };
        d.fill(.square, .{ .color = .{ .color = colors.panel_edge } });
    }
    const top = strip.contentRectScale().r.y;
    split_dragging = dvui.captured(grip.data().id);
    for (dvui.events()) |*e| {
        if (!dvui.eventMatchSimple(e, grip.data())) continue;
        if (e.evt != .mouse) continue;
        const me = e.evt.mouse;
        switch (me.action) {
            .press => if (me.button.pointer()) {
                e.handle(@src(), grip.data());
                dvui.captureMouse(grip.data(), e.num);
                dvui.dragPreStart(me.button, me.p, .{ .cursor = .arrow_n_s });
            },
            .release => if (dvui.captured(grip.data().id)) {
                e.handle(@src(), grip.data());
                dvui.captureMouse(null, e.num);
                dvui.dragEnd(me.button);
                split_dragging = false;
            },
            .motion => if (dvui.captured(grip.data().id)) {
                e.handle(@src(), grip.data());
                tools_height = (me.p.y - top) / ns - split_grip / 2;
                dvui.refresh(null, @src(), grip.data().id);
            },
            .position => dvui.cursorSet(.arrow_n_s),
            else => {},
        }
    }
}

/// What a tab asked for, done; the canvas takes the keyboard back from a
/// pane that stops taking events.
fn applyTab(p: *ghost_pane.Pane, r: ghost_pane.TabResult) void {
    if (r == .none) return;
    const had = p.interactive();
    ghost_pane.apply(&all_panes, p, r);
    if (had and !p.interactive()) if (canvas_id) |id| dvui.focusWidget(id, null, null);
    dvui.refresh(null, @src(), null);
}

/// How much of each canvas edge pinned panes cover, logical pixels, so
/// fitting a view keeps its subject clear of them.
fn overlayInsets() struct { left: f32, right: f32, bottom: f32 } {
    // Pinned panes stay over the canvas: a fitted view keeps clear of them.
    return .{
        .left = if (tree_pane.pinned and tree_pane.mode == .auto) tree_pane.size + overlay_gap else 0,
        .right = if (props_pane.pinned and props_pane.mode == .auto) props_pane.size + overlay_gap else 0,
        .bottom = if (bottom_pane.pinned and bottom_pane.mode == .auto) statusHeight() + overlay_gap else 0,
    };
}

fn overlayOptions(id: usize) dvui.Options {
    return .{
        .id_extra = id,
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill).opacity(overlay_alpha) },
        .border = .all(1),
        .color_border = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.12) },
        .corners = .all(8),
        .box_shadow = null,
    };
}

/// A pane mode by name, as a layout keeps it ("ghost" and "docked", gone,
/// are auto-hide and pinned).
fn modeByName(name: []const u8) ?layouts.Mode {
    return layouts.Mode.parse(name);
}

/// The panes over the canvas, attached to its edges, then the key
/// palette and any prompt.
/// The prompts the start screen can show: opening a file (and what it
/// asks), recovered work, a file changed elsewhere.
fn startPrompts() void {
    if (file_prompt) |kind| filePrompt(kind);
    if (leave_prompt) |p| leavePrompt(p);
    if (recovery != null) recoveryPrompt();
    if (contention != null) contentionPrompt();
}

fn overlays() !void {
    for (all_panes) |p| {
        if (!p.drawn()) {
            p.rect_px = .{};
            p.sub_id = null;
        }
    }
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const g: f32 = overlay_gap;
    // The side panes stop above the bottom bar while it is in.
    const bottom: f32 = if (bottom_pane.drawn()) statusHeight() else 0;
    if (tree_pane.drawn()) {
        var o = ghost_pane.begin(&tree_pane, tree_pane.slid(.{ .x = c.x, .y = c.y, .w = tree_pane.size, .h = @max(60, c.h - bottom) }), 1);
        defer o.end();
        treeContent();
    }
    {
        // The right edge's pane, over the canvas's right side.
        const x = c.x + c.w - props_pane.size;
        const h = @max(2 * min_pane_height, c.h - bottom);
        if (props_pane.drawn()) {
            var o = ghost_pane.begin(&props_pane, props_pane.slid(.{ .x = x, .y = c.y, .w = props_pane.size, .h = h }), 4);
            defer o.end();
            try propertiesBody();
        }
    }
    if (bottom_pane.drawn()) {
        var o = ghost_pane.begin(&bottom_pane, bottom_pane.slid(.{ .x = c.x, .y = c.y + c.h - statusHeight(), .w = c.w, .h = statusHeight() }), 3);
        defer o.end();
        try bottomContent();
    }
    // The content palette, at the top centre of the window, as wide as
    // what it offers: the insert palette while there is a flow cursor
    // (keys for a track of tiles; the flow's breaks and runs), the move
    // palette for a selected track.
    const moving_track = track_cursor == null and state.context == .row;
    // The insert palette is off for now (the owner, 2026-11-23: it
    // covered the work, and Graven is not a keycap program); the move
    // palette stays.
    if (moving_track) {
        // Sized to its content again when what it offers changes.
        const what: u64 = if (moving_track) 1 else if (paletteFor(track_cursor.?.parent, track_cursor.?.region)) |pal| (@as(u64, @backingInt(pal.prototype)) << 8) | (@as(u64, pal.tile_count) << 2) | @as(u64, @intFromBool(inTextTrack())) << 1 else 2;
        const S = struct {
            var rect: dvui.Rect = .{ .w = 400, .h = 64 };
            var shown: u64 = 0;
        };
        const win = dvui.windowRect();
        S.rect.x = @max(c.x, @min(win.w / 2 - S.rect.w / 2, c.x + c.w - S.rect.w));
        // Below the ruler, clear of the measures.
        S.rect.y = c.y + g + ruler_size;
        // Lighter than the panes: the tracks being filled show through.
        var fw = dvui.floatingWindow(@src(), .{ .rect = &S.rect, .resize = .none }, overlayOptions(4).override(.{
            .color_fill = .{ .color = dvui.themeGet().color(.window, .fill).opacity(palette_alpha) },
        }));
        defer fw.deinit();
        if (what != S.shown) {
            fw.autoSize();
            S.shown = what;
        }
        if (moving_track) movePalette() else trackPalette();
    }
    if (export_prompt) exportPrompt();
    if (layout_prompt) layoutPrompt();
    if (image_prompt) imagePrompt();
    if (file_prompt) |kind| filePrompt(kind);
    if (constrain_prompt != null) constrainPromptWindow();
    if (leave_prompt) |p| leavePrompt(p);
    if (recovery != null) recoveryPrompt();
    if (contention != null) contentionPrompt();
}

/// The bottom area: the expression line, then the status line.
fn bottomContent() !void {
    {
        var line = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .min_size_content = .{ .h = expressionHeight() - 2 } });
        defer line.deinit();
        try expressionLine();
    }
    _ = dvui.separator(@src(), .{ .expand = .horizontal });
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
    defer bar.deinit();
    statusContent();
}

// The expression line -----------------------------------------------------
//
// Shows and edits the selected label's markup as typed. Whatever is typed
// is stored, valid or not; the canvas draws it from glyphic's lenient
// parse (placeholders for what is still to come, unfinished commands
// faint), and the first problem shows at the line's end. Braces pair as in
// a code editor, so partial input stays renderable.

/// What the expression line edits.
const ExprTarget = union(enum) {
    /// A tile's content in one of its prototype's tracks, as text (a
    /// newline for each hard break).
    tile_track: struct { tile: TileId, track: layout.model.ObjectId },
    /// A run of markup (text, an equation) in a track's flow.
    run: struct { parent: Parent, region: usize, item: usize },

    fn content(t: ExprTarget) []const u8 {
        return switch (t) {
            .tile_track => |tt| state.model.tileTrackText(dvui.currentWindow().arena(), tt.tile, tt.track) catch "",
            .run => |r| state.model.flowItems(r.parent, r.region)[r.item].what.run.content,
        };
    }

    fn store(t: ExprTarget, text: []const u8) !void {
        switch (t) {
            .tile_track => |tt| try actM(mergeKey(.{ "tile track", tt.tile, tt.track }), .setTileTrackText, .{ tt.tile, tt.track, text }),
            .run => |r| try actM(mergeKey(.{ "run", r.parent, r.region, r.item }), .setRunContent, .{ r.parent, r.region, r.item, text }),
        }
    }

    /// Whether it is all math (an equation run), rather than a legend.
    fn isMath(t: ExprTarget) bool {
        return switch (t) {
            .tile_track => false,
            .run => |r| state.model.flowItems(r.parent, r.region)[r.item].what.run.equation,
        };
    }

    fn key(t: ExprTarget) u64 {
        var h: std.hash.Wyhash = .init(7);
        std.hash.autoHash(&h, t);
        return h.final();
    }
};

fn exprTarget() ?ExprTarget {
    // In a sheet view: the selected cell, through its key's slot.
    if (activeKind() == .sheet) return sheetCellTarget();
    if (canvas_eq) |q| if (eqContent(q) != null) return q.target;
    if (equationEdited()) |e| return .{ .run = .{ .parent = e.parent, .region = e.region, .item = e.item } };
    return switch (state.context) {
        .tile => |id| if (exprTrackOf(id)) |tr| .{ .tile_track = .{ .tile = id, .track = tr } } else null,
        .region => if (runAtCursor()) |r| .{ .run = .{ .parent = r.parent, .region = r.region, .item = r.item } } else null,
        else => null,
    };
}

/// The tile track the expression line edits, when the context is a tile
/// whose prototype has it; else its first track with text in it; else its
/// first track.
var expr_track: layout.model.ObjectId = .none;

fn exprTrackOf(id: TileId) ?layout.model.ObjectId {
    const tracks = state.model.prototypeOf(id).tracks;
    if (tracks.len == 0) return null;
    for (tracks) |tt| if (tt.id == expr_track) return tt.id;
    for (tracks) |tt| if (state.model.tileFlow(id, tt.id)) |f| if (f.items.items.len > 0) return tt.id;
    return tracks[0].id;
}

/// The line's text before this frame's edits, for the pairing rules.
var expr_prev: std.ArrayList(u8) = .empty;
var expr_prev_key: u64 = 0;

/// Command completion: the list shown while a command is being typed, the
/// highlighted entry, and a pending acceptance or dismissal.
var expr_entry_id: ?dvui.Id = null;
var comp: std.ArrayList(glyphic.symbols.Completion) = .empty;
var comp_index: usize = 0;
var comp_accept: ?usize = null;
/// The cursor position at which Esc dismissed the list, until it moves.
var comp_dismissed_at: ?usize = null;
const comp_max = 8;

/// Where the expression line's cursor last was, for the inspector, which
/// keeps showing the object there after the line loses focus.
var expr_inspect: ?struct { key: u64, offset: usize } = null;

/// While the expression line has focus: what it edits and where its cursor
/// is, so the canvas draws the cursor in the rendered label too.
var expr_caret: ?struct { target: ExprTarget, offset: usize } = null;

/// The command name being typed just before the cursor: the backslash's
/// offset and the letters after it.
fn partialCommand(text: []const u8, cur: usize) ?struct { at: usize, prefix: []const u8 } {
    var i = @min(cur, text.len);
    while (i > 0 and std.ascii.isAlphabetic(text[i - 1])) i -= 1;
    if (i == 0 or text[i - 1] != '\\') return null;
    // An escaped backslash (\\) is a line break, not a command.
    if (i >= 2 and text[i - 2] == '\\') return null;
    return .{ .at = i - 1, .prefix = text[i..@min(cur, text.len)] };
}

/// Replaces the partial command before the cursor with a completion, and
/// leaves the cursor inside its first argument, or after it.
fn acceptCompletion(te: *dvui.TextEntryWidget, c: glyphic.symbols.Completion) void {
    const cur = te.textLayout.selection.cursor;
    const part = partialCommand(te.textGet(), cur) orelse return;
    setCursor(te, part.at + 1);
    te.textLayout.selection.end = cur;
    var buf: [96]u8 = undefined;
    const insert = std.fmt.bufPrint(&buf, "{s}{s}", .{ c.name, c.args }) catch return;
    te.textTyped(insert, false);
    const after_name = part.at + 1 + c.name.len;
    setCursor(te, if (c.args.len > 0) after_name + 1 else after_name);
}

fn expressionLine() !void {
    const muted: dvui.Options = .{ .gravity_y = 0.5, .padding = .{ .x = 8, .w = 6 }, .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.65) } };
    dvui.labelNoFmt(@src(), "Expression", .{}, muted);
    const target = exprTarget() orelse {
        dvui.labelNoFmt(@src(), "Select a tile or put the cursor in a flow to edit its expression.", .{}, muted.override(.{ .expand = .horizontal, .font = dvui.Font.theme(.body).withStyle(.italic) }));
        return;
    };
    const key = target.key();
    const content = target.content();
    if (key != expr_prev_key) {
        expr_prev.clearRetainingCapacity();
        try expr_prev.appendSlice(state.gpa, content);
        expr_prev_key = key;
    }

    // While the completion list shows, its keys are taken before the entry
    // sees them: Up and Down move, Tab or Enter accepts, Esc dismisses.
    const was_focused = expr_entry_id != null and expr_entry_id.? == dvui.focusedWidgetId();
    if (was_focused and comp.items.len > 0) for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("expression-line.completion")) orelse continue;
        switch (inv.action) {
            kact("expression-line.completion.previous") => comp_index = if (comp_index == 0) comp.items.len - 1 else comp_index - 1,
            kact("expression-line.completion.next") => comp_index = (comp_index + 1) % comp.items.len,
            kact("expression-line.completion.accept") => comp_accept = comp_index,
            kact("expression-line.completion.dismiss") => comp_dismissed_at = std.math.maxInt(usize),
            else => continue,
        }
        e.handle(@src(), dvui.currentWindow().data());
    };

    // In a run of a track's flow, Enter or Esc ends the run, and Ctrl+\
    // ends equation mode: the keyboard goes back to the canvas and its
    // flow cursor (after the equation), where Enter is a hard break.
    var back_to_flow = false;
    if (was_focused and target == .run) for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("expression-line.run")) orelse continue;
        if (inv.action != kact("expression-line.run.leave")) continue;
        e.handle(@src(), dvui.currentWindow().data());
        back_to_flow = true;
    };
    if (back_to_flow) {
        leaveEquation(true);
        if (canvas_id) |id| dvui.focusWidget(id, null, null);
        dvui.refresh(null, @src(), null);
        return;
    }

    // Otherwise Tab moves to the next stop (Shift+Tab the one before), in
    // the expression's field order, taken before the entry sees it, as the
    // entry would move focus.
    var next_slot: ?bool = null;
    if (was_focused) for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("expression-line")) orelse continue;
        if (inv.action == kact("expression-line.tab")) {
            e.handle(@src(), dvui.currentWindow().data());
            next_slot = inv.arg == 1;
        }
    };
    var te = dvui.textEntry(@src(), .{ .text_initial = content }, .{
        .expand = .horizontal,
        .gravity_y = 0.5,
        .font = .theme(.mono),
        .id_extra = @truncate(key),
    });
    // A run just put in a track takes the keyboard at once.
    if (focus_expression) {
        focus_expression = false;
        // Its window first: the palette over the canvas may hold the
        // keyboard.
        dvui.focusSubwindow(null, null);
        dvui.focusWidget(te.data().id, null, null);
        // The new run takes the place in the flow of the item the cursor
        // was before, so the line may still hold that item's text: it
        // starts from the new run's own.
        if (!std.mem.eql(u8, te.textGet(), content)) te.textSet(content, false);
        expr_prev.clearRetainingCapacity();
        try expr_prev.appendSlice(state.gpa, content);
        if (focus_expression_at) |at| setCursor(te, @min(at, te.textGet().len));
        focus_expression_at = null;
    }
    const focused = te.data().id == dvui.focusedWidgetId();
    // Equation mode ends when the keyboard goes elsewhere (a click on the
    // canvas, another field).
    if (equation_edit) |*eq| {
        if (focused) eq.shown = true else if (eq.shown) {
            te.deinit();
            leaveEquation(false);
            return;
        }
    }
    if (next_slot) |back| nextSlot(te, target.isMath(), back);
    // Kept in step with edits made elsewhere (the Text property).
    if (!focused and !std.mem.eql(u8, te.textGet(), content)) te.textSet(content, false);
    expr_entry_id = te.data().id;
    if (te.text_changed and !std.mem.eql(u8, te.textGet(), expr_prev.items)) pairBraces(te, expr_prev.items);
    if (comp_accept) |i| {
        if (i < comp.items.len) acceptCompletion(te, comp.items[i]);
        comp_accept = null;
    }
    // The list for the command being typed, unless dismissed here.
    const cursor = te.textLayout.selection.cursor;
    if (comp_dismissed_at) |d| {
        if (d == std.math.maxInt(usize)) comp_dismissed_at = cursor else if (d != cursor) comp_dismissed_at = null;
    }
    comp.clearRetainingCapacity();
    if (focused and comp_dismissed_at == null) if (partialCommand(te.textGet(), cursor)) |part| {
        try glyphic.symbols.completions(state.gpa, part.prefix, &comp);
        if (comp.items.len > comp_max) comp.shrinkRetainingCapacity(comp_max);
        // Nothing to offer once the name is complete and alone.
        if (comp.items.len == 1 and std.mem.eql(u8, comp.items[0].name, part.prefix)) comp.clearRetainingCapacity();
    };
    if (comp_index >= comp.items.len) comp_index = 0;
    const entry_rect = te.data().borderRectScale().r;
    // The canvas caret follows; redraw when it moves.
    const caret: @TypeOf(expr_caret) = if (focused) .{ .target = target, .offset = te.textLayout.selection.cursor } else null;
    if (!std.meta.eql(caret, expr_caret)) dvui.refresh(null, @src(), null);
    expr_caret = caret;
    if (caret) |c| expr_inspect = .{ .key = c.target.key(), .offset = c.offset };
    const text = te.textGet();
    const changed = !std.mem.eql(u8, text, content);
    if (changed) try target.store(text);
    expr_prev.clearRetainingCapacity();
    try expr_prev.appendSlice(state.gpa, text);
    te.deinit();

    if (comp.items.len > 0) completionList(entry_rect);

    // The first problem, if any, at the line's end.
    if (firstSyntaxProblem(target)) |d| {
        var buf: [96]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "{s} (at {d})", .{ d.kind.message(), d.offset }) catch "";
        dvui.labelNoFmt(@src(), msg, .{}, .{ .gravity_y = 0.5, .padding = .{ .x = 8, .w = 8 }, .color_text = .{ .color = colors.overflow } });
    }
}

/// The completion list, floating just above the expression line.
fn completionList(entry: dvui.Rect.Physical) void {
    const ns = dvui.windowNaturalScale();
    const font = dvui.Font.theme(.mono);
    const row_pad: f32 = 3;
    const row_h: f32 = font.textHeight() + 2 * row_pad;
    const h = row_h * @as(f32, @floatFromInt(comp.items.len)) + 10;
    var fw: dvui.FloatingWidget = undefined;
    fw.init(@src(), .{}, .{
        .rect = .{ .x = entry.x / ns + 8, .y = entry.y / ns - h - 4, .w = 360, .h = h },
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) },
        .border = .all(1),
        .corners = .all(6),
        .padding = .all(4),
    });
    defer fw.deinit();
    for (comp.items, 0..) |c, i| {
        var buf: [96]u8 = undefined;
        var cp_buf: [4]u8 = undefined;
        // The character with its code point: the interface font may lack it.
        var code_buf: [16]u8 = undefined;
        const glyph = if (c.cp) |cp| cp_buf[0 .. std.unicode.utf8Encode(cp, &cp_buf) catch 0] else "";
        const code = if (c.cp) |cp| std.fmt.bufPrint(&code_buf, "  U+{X:0>4}", .{cp}) catch "" else "";
        const line = std.fmt.bufPrint(&buf, "\\{s}{s}    {s}{s}{s}", .{ c.name, c.args, glyph, code, c.note }) catch c.name;
        const selected = i == comp_index;
        if (dvui.labelClick(@src(), "{s}", .{line}, .{}, .{
            .id_extra = i,
            .expand = .horizontal,
            .font = font,
            .padding = .{ .x = 6, .w = 6, .y = row_pad, .h = row_pad },
            .background = selected,
            .color_fill = if (selected) .{ .color = dvui.themeGet().focus.opacity(0.3) } else null,
        })) {
            comp_index = i;
            comp_accept = i;
        }
    }
}

fn firstSyntaxProblem(target: ExprTarget) ?layout.render.Syntax {
    for (state.solved.items, 0..) |*p, pk| for (p.issues) |i| {
        const pi = state.model.parentAt(pk);
        if (i.kind != .markup_error) continue;
        const hit = switch (target) {
            .tile_track => |tt| i.tile == tt.tile and i.slot != null and if (state.model.tileTrackIndex(tt.tile, tt.track)) |k| i.slot.? == k else false,
            .run => |r| r.parent.eql(pi) and i.region == r.region and i.item == r.item,
        };
        if (hit) return i.syntax;
    };
    return null;
}

/// The pairing rules, applied after the entry has taken a keystroke:
/// typing '{' adds its '}' (after \frac, "{}{}"), with the cursor inside;
/// typing '}' where the text has one too many steps over the next '}';
/// deleting the '{' of an empty "{}" deletes both.
fn pairBraces(te: *dvui.TextEntryWidget, prev: []const u8) void {
    const text = te.textGet();
    const sel = te.textLayout.selection;
    const cur = sel.cursor;
    if (text.len == prev.len + 1 and cur > 0 and cur <= text.len) {
        const typed = text[cur - 1];
        if (typed == '{') {
            const two = std.mem.endsWith(u8, text[0 .. cur - 1], "\\frac") or std.mem.endsWith(u8, text[0 .. cur - 1], "\\dfrac") or std.mem.endsWith(u8, text[0 .. cur - 1], "\\tfrac");
            te.textTyped(if (two) "}{}" else "}", false);
            setCursor(te, cur);
        } else if (typed == '}' and cur < text.len and text[cur] == '}' and count(text, '}') > count(text, '{')) {
            // Remove the '}' just typed: the cursor steps over the next one.
            setCursor(te, cur - 1);
            te.textLayout.selection.end = cur;
            te.textTyped("", false);
            setCursor(te, cur);
        }
    } else if (text.len + 1 == prev.len and cur < prev.len and prev[cur] == '{' and cur + 1 < prev.len and prev[cur + 1] == '}' and
        std.mem.eql(u8, text[0..cur], prev[0..cur]) and std.mem.eql(u8, text[cur..], prev[cur + 1 ..]))
    {
        // The '{' of an empty pair was deleted: take its '}' too.
        setCursor(te, cur);
        te.textLayout.selection.end = cur + 1;
        te.textTyped("", false);
        setCursor(te, cur);
    }
}

fn count(text: []const u8, c: u8) usize {
    return std.mem.count(u8, text, &.{c});
}

fn setCursor(te: *dvui.TextEntryWidget, at: usize) void {
    te.textLayout.selection.cursor = at;
    te.textLayout.selection.start = at;
    te.textLayout.selection.end = at;
}

/// Tab: the cursor goes just inside the next '{' after it, or to the end.
/// Moves the cursor to the next stop of the expression (the one before
/// when `back`), in its field order: a structure's head, then its fields
/// (an empty one between its braces), as glyphic parses the line.
fn nextSlot(te: *dvui.TextEntryWidget, math: bool, back: bool) void {
    const gpa = state.gpa;
    const text = te.textGet();
    const cur = te.textLayout.selection.cursor;
    var e = glyphic.Expr.init(gpa) catch return;
    defer e.deinit();
    var spans: glyphic.entry.Spans = .{};
    defer spans.deinit(gpa);
    glyphic.latex.parse(&e, &spans, text, if (math) .math else .legend) catch return;
    var g = glyphic.Engine.init(gpa);
    defer g.deinit();
    const r = glyphic.Resolver.init(&g, &e, &.{});
    const to = glyphic.stops.tab(gpa, &r, spans, cur, back) catch return;
    if (to) |at| setCursor(te, @min(at, text.len));
}

// The title bar -----------------------------------------------------------
//
// Like a GTK header bar: the window has no native frame, and Graven draws
// one bar holding its menus, the title, and at the right end the window
// controls in a plain native style. SDL's hit test tells the window manager
// which parts of the bar drag the window and which window edges resize it.

/// The title bar's rectangle and the controls on it, in physical pixels,
/// from the last frame: the hit test reads them.
var frame_bar: dvui.Rect.Physical = .{};
var frame_holes: [16]dvui.Rect.Physical = undefined;
var frame_hole_count: usize = 0;
/// Physical pixels per window coordinate (SDL's hit test gives points).
var frame_density: f32 = 1;

const title_height = 34;
/// Width of the window edges that resize it, window coordinates.
const resize_edge = 6;

fn initWindowFrame(win: *dvui.Window) void {
    if (dvui.backend.kind != .sdl3) return;
    const c = dvui.backend.c;
    const window = win.backend.impl.window;
    _ = c.SDL_SetWindowTitle(window, "untitled — Graven");
    if (platform.env("GRAVEN_NATIVE_FRAME") != null) return;
    _ = c.SDL_SetWindowBordered(window, false);
    _ = c.SDL_SetWindowHitTest(window, hitTest, null);
}

/// Where a point in the window drags or resizes it: resize along the
/// edges (unless maximised), drag on the title bar away from its controls.
fn hitTest(win: ?*dvui.backend.c.SDL_Window, area: [*c]const dvui.backend.c.SDL_Point, _: ?*anyopaque) callconv(.c) dvui.backend.c.SDL_HitTestResult {
    const c = dvui.backend.c;
    const p = area.*;
    var w: c_int = 0;
    var h: c_int = 0;
    _ = c.SDL_GetWindowSize(win, &w, &h);
    const maximized = (c.SDL_GetWindowFlags(win) & c.SDL_WINDOW_MAXIMIZED) != 0;
    if (!maximized) {
        const l = p.x < resize_edge;
        const r = p.x >= w - resize_edge;
        const t = p.y < resize_edge;
        const b = p.y >= h - resize_edge;
        if (t and l) return c.SDL_HITTEST_RESIZE_TOPLEFT;
        if (t and r) return c.SDL_HITTEST_RESIZE_TOPRIGHT;
        if (b and l) return c.SDL_HITTEST_RESIZE_BOTTOMLEFT;
        if (b and r) return c.SDL_HITTEST_RESIZE_BOTTOMRIGHT;
        if (t) return c.SDL_HITTEST_RESIZE_TOP;
        if (b) return c.SDL_HITTEST_RESIZE_BOTTOM;
        if (l) return c.SDL_HITTEST_RESIZE_LEFT;
        if (r) return c.SDL_HITTEST_RESIZE_RIGHT;
    }
    const pp: dvui.Point.Physical = .{ .x = @as(f32, @floatFromInt(p.x)) * frame_density, .y = @as(f32, @floatFromInt(p.y)) * frame_density };
    if (!frame_bar.contains(pp)) return c.SDL_HITTEST_NORMAL;
    for (frame_holes[0..frame_hole_count]) |hole| if (hole.contains(pp)) return c.SDL_HITTEST_NORMAL;
    return c.SDL_HITTEST_DRAGGABLE;
}

/// Marks a control on the title bar, so pressing it is not a window drag.
fn frameHole(r: dvui.Rect.Physical) void {
    if (frame_hole_count < frame_holes.len) {
        frame_holes[frame_hole_count] = r;
        frame_hole_count += 1;
    }
}

const WindowButton = enum { minimize, maximize, close };

/// A window control: a round button showing only on hover, with a thin
/// glyph, as GTK and COSMIC draw them.
fn windowButton(kind: WindowButton) bool {
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{
        .id_extra = @backingInt(kind),
        .min_size_content = .{ .w = 18, .h = 18 },
        .padding = .all(5),
        .margin = .{ .x = 3, .w = 3 },
        .corners = .round(14),
        .gravity_y = 0.5,
        .background = false,
        .border = .all(0),
    });
    bw.processEvents();
    if (bw.hovered() or bw.pressed()) bw.data().borderRectScale().r.fill(.round(14 * dvui.windowNaturalScale()), .{ .color = .{ .color = dvui.themeGet().color(.control, .text).opacity(if (bw.pressed()) 0.2 else 0.1) } });
    const clicked = bw.clicked();
    const r = bw.data().contentRectScale().r;
    frameHole(bw.data().borderRectScale().r);
    const ns = dvui.windowNaturalScale();
    const ink: dvui.ColorOrGradient = .{ .color = dvui.themeGet().color(.control, .text) };
    const cx = r.x + r.w / 2;
    const cy = r.y + r.h / 2;
    const k = 4.5 * ns;
    switch (kind) {
        .minimize => dvui.Path.stroke(.{ .points = &.{ .{ .x = cx - k, .y = cy + k * 0.6 }, .{ .x = cx + k, .y = cy + k * 0.6 } } }, .{ .thickness = 1.3 * ns, .color = ink }),
        .maximize => (dvui.Rect.Physical{ .x = cx - k, .y = cy - k, .w = 2 * k, .h = 2 * k }).stroke(.square, .{ .thickness = 1.3 * ns, .color = ink }),
        .close => {
            dvui.Path.stroke(.{ .points = &.{ .{ .x = cx - k, .y = cy - k }, .{ .x = cx + k, .y = cy + k } } }, .{ .thickness = 1.3 * ns, .color = ink });
            dvui.Path.stroke(.{ .points = &.{ .{ .x = cx - k, .y = cy + k }, .{ .x = cx + k, .y = cy - k } } }, .{ .thickness = 1.3 * ns, .color = ink });
        },
    }
    bw.deinit();
    return clicked;
}

/// The title bar: menus at the left, the file and worksheet in the middle,
/// window controls at the right. Everything that is not a control drags
/// the window.
fn titleBar() ?dvui.App.Result {
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .background = true, .color_fill = .{ .color = colors.titlebar }, .min_size_content = .{ .h = title_height }, .border = .{ .h = 1 } });
    defer bar.deinit();
    frame_bar = bar.data().borderRectScale().r;
    frame_hole_count = 0;
    const win = dvui.currentWindow();
    const px = win.backend.pixelSize();
    const ws = win.backend.windowSize();
    frame_density = if (ws.w > 0) px.w / ws.w else 1;

    const native_frame = dvui.backend.kind != .sdl3 or platform.env("GRAVEN_NATIVE_FRAME") != null;
    // Window buttons on the left, when the desktop puts them there.
    if (!native_frame) if (windowButtons(desk.layout.leftSide())) |r| return r;

    if (menu()) |r| return r;

    // The title fills the middle and is part of the draggable bar.
    {
        // Each name italic while it is the app's choice.
        // Fills the bar's height too, so the title centres against the
        // menus and window buttons rather than sitting at the top.
        var middle = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .both });
        defer middle.deinit();
        var title = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 0.5, .gravity_y = 0.5 });
        defer title.deinit();
        // A bullet while there are unsaved changes.
        if (!canvas_prompt and hist.isDirty()) dvui.labelNoFmt(@src(), "• ", .{}, .{ .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
        // On the start screen there is no document to name.
        if (canvas_prompt) {
            dvui.labelNoFmt(@src(), "Graven", .{}, .{ .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
        } else {
            dvui.labelNoFmt(@src(), state.file_name, .{}, .{ .font = styled(.theme(.body), !state.file_name_set), .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
        }
        dvui.labelNoFmt(@src(), "  —  ", .{}, .{ .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
        if (openCanvas()) {
            var tb: [64]u8 = undefined;
            const t = if (canvas_prompt) "Start" else if (shown_space > 0 and shown_space < state.model.spaces.items.len) std.fmt.bufPrint(&tb, "{s}, {s}", .{ state.model.spaces.items[shown_space].name, state.model.units.symbol() }) catch "Frame" else std.fmt.bufPrint(&tb, "Canvas, {s}", .{state.model.units.symbol()}) catch "Canvas";
            dvui.labelNoFmt(@src(), t, .{}, .{ .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
        } else dvui.labelNoFmt(@src(), state.model.sheet.name, .{}, .{ .font = styled(.theme(.body), state.model.sheet.default_name), .padding = .{ .x = 0, .w = 0, .y = 4, .h = 4 } });
    }

    if (!native_frame) if (windowButtons(desk.layout.rightSide())) |r| return r;
    return null;
}

/// The window buttons in the desktop's order.
fn windowButtons(buttons: []const desktop.Button) ?dvui.App.Result {
    if (dvui.backend.kind != .sdl3) return null;
    const c = dvui.backend.c;
    const window = dvui.currentWindow().backend.impl.window;
    for (buttons) |b| {
        const kind: WindowButton = switch (b) {
            .minimize => .minimize,
            .maximize => .maximize,
            .close => .close,
        };
        if (!windowButton(kind)) continue;
        switch (kind) {
            .minimize => _ = c.SDL_MinimizeWindow(window),
            .maximize => {
                const maximized = (c.SDL_GetWindowFlags(window) & c.SDL_WINDOW_MAXIMIZED) != 0;
                _ = if (maximized) c.SDL_RestoreWindow(window) else c.SDL_MaximizeWindow(window);
            },
            .close => leave(.quit),
        }
    }
    return null;
}

/// A menu item that runs action `a` (with `arg`), its shortcut in mode
/// `mode_name` shown at its right from the keymap, so the two never
/// disagree; `faint` when there is nothing for it to do. Whether it was
/// chosen (and the action run).
fn menuAction(label: []const u8, comptime mode_name: []const u8, a: keymap.ActionId, arg: i32, faint: bool, id: usize) bool {
    // Its id is its action's name: menu.file.save.
    const tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "menu.{s}", .{keymap.R.actionName(a)}) catch "menu");
    var mi = dvui.menuItem(@src(), .{}, .{ .expand = .horizontal, .id_extra = id, .tag = tag });
    defer mi.deinit();
    const chosen = mi.activeRect() != null or pressedByScript(tag);
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
    defer row.deinit();
    const ink = dvui.themeGet().color(.window, .text);
    const base = mi.style().strip().override(.{ .label = .{ .for_id = mi.data().id } });
    dvui.labelNoFmt(@src(), label, .{}, base.override(.{ .expand = .horizontal, .color_text = if (faint) .{ .color = ink.opacity(0.4) } else null }));
    var kb: [48]u8 = undefined;
    if (keymap.shortcut(&kb, kmode(mode_name), a, arg)) |sc| {
        dvui.labelNoFmt(@src(), sc, .{}, mi.style().strip().override(.{ .padding = .{ .x = 28, .y = 0, .w = 0, .h = 0 }, .color_text = .{ .color = ink.opacity(0.55) } }));
    }
    if (chosen) _ = runAction(.{ .action = a, .arg = arg });
    return chosen;
}

fn menu() ?dvui.App.Result {
    var m = dvui.menu(@src(), .horizontal, .{ .gravity_y = 0.5 });
    frameHole(m.data().borderRectScale().r);
    defer m.deinit();
    if (tmenu(@src(), "File", .{ .submenu = true }, .{})) |r| {
        var fw = dvui.floatingMenu(@src(), .{ .from = r }, .{});
        defer fw.deinit();
        if (menuAction("New canvas…", "global", kact("file.new"), 0, false, 1)) m.close();
        if (menuAction("Open…", "global", kact("file.open"), 0, false, 2)) m.close();
        if (!canvas_prompt) {
            if (menuAction("Save", "global", kact("file.save"), 0, false, 3)) m.close();
            if (menuAction("Save As…", "global", kact("file.save-as"), 0, false, 4)) m.close();
        }
        if (!canvas_prompt) if (tmenu(@src(), "Import text…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            askForFile(.import_text);
        };
        if (!canvas_prompt) if (tmenu(@src(), "Import figure (SVG)…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            askForFile(.import_figure);
        };
        if (!canvas_prompt) if (tmenu(@src(), "Export legend sheet (CSV)…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            if (sheetToExport() == null) {
                state.status = "Show or choose a legend sheet first: it is what is exported. ";
            } else {
                askForFile(.export_sheet);
            }
        };
        if (!canvas_prompt) if (tmenu(@src(), "Export panel as 3MF…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            if (exportPart()) |pi| {
                if (state.model.panels.items[pi].fab.layers.len == 0) {
                    state.status = "This panel has no fabrication layers yet (its properties, Fabrication): there is nothing to make. ";
                } else {
                    askForFile(.export_3mf);
                }
            } else state.status = "Choose a panel first: it is what is exported. ";
        };
        if (!canvas_prompt) if (menuAction("Check fabrication", "view", kact("fab.check"), 0, false, 40)) {
            m.close();
            runChecks(checkTarget());
        };
        if (!canvas_prompt) if (tmenu(@src(), "Import legend sheet (CSV)…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            if (sheetImportTarget() == null) {
                state.status = "Choose a sheet, or a grid, track or panel of keys, first: the table goes into it. ";
            } else {
                askForFile(.import_sheet);
            }
        };
        if (tmenu(@src(), "Place image…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            if (!canvas_prompt and openCanvas()) {
                image_prompt = true;
                image_prompt_new = true;
                image_prompt_system = systemFileDialog();
            }
        }
        if (tmenu(@src(), "Export SVG…", .{}, .{ .expand = .horizontal }) != null) {
            m.close();
            exportSvg();
        }
        // The example documents (examples/, from where Graven was started),
        // each opened as an untitled copy.
        inline for (.{ .{ "Open example: PC keyboard", "examples/pc-keyboard.graven" }, .{ "Open example: HP-15C keypad", "examples/hp15c.graven" } }, 0..) |ex, k| {
            if (tmenu(@src(), ex[0], .{}, .{ .expand = .horizontal, .id_extra = k }) != null) {
                leave(.{ .example = ex[1] });
                m.close();
            }
        }
        if (tmenu(@src(), "Quit", .{}, .{ .expand = .horizontal }) != null) {
            leave(.quit);
            m.close();
        }
    }
    if (tmenu(@src(), "Edit", .{ .submenu = true }, .{})) |r| {
        var fw = dvui.floatingMenu(@src(), .{ .from = r }, .{});
        defer fw.deinit();
        if (menuAction("Undo", "global", kact("edit.undo"), 0, !hist.canUndo(), 1)) m.close();
        if (menuAction("Redo", "global", kact("edit.redo"), 0, !hist.canRedo(), 2)) {
            m.close();
        }
        // Text in a track, at the flow cursor.
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 90 });
        const no_sel = track_cursor == null or flowSelection() == null;
        if (menuAction("Cut", "canvas.flow", kact("canvas.flow.cut"), 0, no_sel, 3)) m.close();
        if (menuAction("Copy", "canvas.flow", kact("canvas.flow.copy"), 0, no_sel, 4)) m.close();
        if (menuAction("Paste", "canvas.flow", kact("canvas.flow.paste"), 0, track_cursor == null, 5)) m.close();
        if (menuAction("Select all", "canvas.flow", kact("canvas.flow.select.all"), 0, track_cursor == null, 6)) m.close();
    }
    if (tmenu(@src(), "Text", .{ .submenu = true }, .{})) |r| {
        var fw = dvui.floatingMenu(@src(), .{ .from = r }, .{});
        defer fw.deinit();
        if (tmenu(@src(), "Fonts…", .{}, .{ .expand = .horizontal }) != null) {
            fontwin.open = true;
            m.close();
        }
    }
    if (tmenu(@src(), "View", .{ .submenu = true }, .{})) |r| {
        var fw = dvui.floatingMenu(@src(), .{ .from = r }, .{});
        defer fw.deinit();
        if (menuAction("    Zoom to context", "view", kact("view.zoom-fit"), 0, false, 1)) m.close();
        if (menuAction("    Zoom to everything", "view", kact("view.zoom-all"), 0, false, 2)) m.close();
        if (menuAction("    Frame the edit", "view", kact("view.frame-edit"), 0, false, 7)) m.close();
        if (menuAction("    Reveal the context", "view", kact("view.reveal"), 0, false, 9)) m.close();
        if (menuAction("    Show or hide auto-hide panes", "global", kact("panes.toggle-auto"), 0, false, 8)) m.close();
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 92 });
        if (menuAction("    New view side by side", "global", kact("views.split-across"), 0, false, 20)) m.close();
        if (menuAction("    New view stacked", "global", kact("views.split-down"), 0, false, 21)) m.close();
        if (menuAction(if (vl.maximized != docviews.none) "•  Fill the window with this view" else "    Fill the window with this view", "global", kact("views.maximize"), 0, false, 22)) m.close();
        if (menuAction("    Next view", "global", kact("views.next"), 0, false, 23)) m.close();
        if (menuAction("    Close this view", "global", kact("views.close"), 0, vl.open[vl.active] and blk: {
            var c: usize = 0;
            for (vl.open) |o| {
                if (o) c += 1;
            }
            break :blk c <= 1;
        }, 24)) m.close();
        if (menuAction("    Actual size", "view", kact("view.zoom-to"), 100, false, 3)) m.close();
        if (menuAction("    200 %", "view", kact("view.zoom-to"), 200, false, 4)) m.close();
        if (menuAction("    Zoom in", "view", kact("view.zoom-in"), 0, false, 5)) m.close();
        if (menuAction("    Zoom out", "view", kact("view.zoom-out"), 0, false, 6)) m.close();
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 91 });
        // DVUI's interface font has no check mark; a bullet marks what is on.
        // The grid: whether this canvas or frame has one (the document's),
        // and how grids are drawn (a preference): lines, dots or pluses.
        {
            const on = ViewLayer.grid.shown();
            if (tmenu(@src(), if (on) "•  Grid" else "    Grid", .{}, .{ .expand = .horizontal, .id_extra = 3 }) != null) {
                ViewLayer.grid.toggle();
                m.close();
            }
        }
        for ([_]bg_grid.Mode{ .lines, .dots, .pluses }, [_][]const u8{ "Grids as lines", "Grids as dots", "Grids as pluses" }, 0..) |gm, label, gi| {
            var lb: [48]u8 = undefined;
            const text = std.fmt.bufPrint(&lb, "{s}{s}", .{ if (gridLook() == gm) "•  " else "    ", label }) catch label;
            if (tmenu(@src(), text, .{}, .{ .expand = .horizontal, .id_extra = gi }) != null) {
                grid_mode = gm;
                m.close();
            }
        }
        if (menuAction(if (snap_grid) "•  Snap to grid" else "    Snap to grid", "view", kact("view.snap-grid"), 0, false, 9)) m.close();
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 94 });
        inline for (canvas_theme.all, 0..) |t, ti| {
            const text = if (canvas_theme.current == t) "•  " ++ comptime t.label() else "    " ++ comptime t.label();
            if (menuAction(text, "view", kact("view.canvas-theme"), @intFromEnum(t), false, 40 + ti)) m.close();
        }
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 93 });
        if (menuAction(if (scroll_mode == .auto) "•  Scrolling: trackpad pans, wheel zooms" else "    Scrolling: trackpad pans, wheel zooms", "view", kact("view.scrolling"), 0, false, 30)) m.close();
        if (menuAction(if (scroll_mode == .zoom) "•  Scrolling zooms" else "    Scrolling zooms", "view", kact("view.scrolling"), 1, false, 31)) m.close();
        if (menuAction(if (scroll_mode == .pan) "•  Scrolling pans" else "    Scrolling pans", "view", kact("view.scrolling"), 2, false, 32)) m.close();
        if (tmenu(@src(), "    Display correction…", .{}, .{ .expand = .horizontal }) != null) {
            display_window = true;
            m.close();
        }
        if (tmenu(@src(), "    Calibrate screen size…", .{}, .{ .expand = .horizontal }) != null) {
            openSizeWindow();
            m.close();
        }
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 90 });
        if (tmenu(@src(), if (show_construction) "•  Show text construction" else "    Show text construction", .{}, .{ .expand = .horizontal }) != null) {
            show_construction = !show_construction;
            m.close();
        }
        // Pane layouts: which is in use, and saving or resetting it.
        if (tmenu(@src(), "    Pane layout", .{ .submenu = true }, .{ .expand = .horizontal })) |lr| {
            var lm = dvui.floatingMenu(@src(), .{ .from = lr }, .{});
            defer lm.deinit();
            for (layoutNames(), 0..) |n, li| {
                var lb: [64]u8 = undefined;
                const on = std.mem.eql(u8, n, layout_name);
                const text = std.fmt.bufPrint(&lb, "{s}{s}", .{ if (on) "•  " else "    ", n }) catch n;
                if (tmenu(@src(), text, .{}, .{ .expand = .horizontal, .id_extra = li }) != null) {
                    useLayout(n);
                    m.close();
                }
            }
            _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 92 });
            if (menuAction("    Next layout", "global", kact("panes.layout-next"), 0, false, 20)) m.close();
            if (menuAction("    Save layout as…", "global", kact("panes.layout-save-as"), 0, false, 21)) m.close();
            if (menuAction("    Reset this layout", "global", kact("panes.layout-reset"), 0, false, 22)) m.close();
        }
        // Each pane pinned in or auto-hide, as a click on its tab sets it.
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .id_extra = 9 });
        for (all_panes, 0..) |pane, pi| {
            var buf: [64]u8 = undefined;
            const on = pane.pinned;
            const text = std.fmt.bufPrint(&buf, "{s}{s}: pinned", .{ if (on) "•  " else "    ", pane.name }) catch pane.name;
            if (tmenu(@src(), text, .{}, .{ .expand = .horizontal, .id_extra = 40 + pi }) != null) {
                applyTab(pane, .toggle);
                m.close();
            }
        }
    }
    return null;
}

/// The tree itself, in whatever holds it; scrolls by wheel, with no bars.
fn treeContent() void {
    var scroll = dvui.scrollArea(@src(), .{ .vertical_bar = .hide, .horizontal_bar = .hide }, .{ .expand = .both, .background = false });
    defer scroll.deinit();
    // Nothing to show until the canvas is made.
    if (canvas_prompt) return;

    // The file holds everything: its worksheet, and the tile prototypes its
    // tiles are made from.
    if (!treeNode(.file, state.file_name, 0, true, !state.file_name_set)) return;
    worksheetTree();
    if (treeNode(.prototypes, "Tile prototypes", 1, state.model.prototypes.items.len > 0, false)) {
        for (state.model.prototypes.items) |p| _ = treeNode(.{ .prototype = p.id }, p.name, 2, false, false);
    }
    // Always listed: a document's styles are made here.
    if (treeNode(.styles, "Text styles", 1, state.model.styles.items.len > 0, false)) {
        for (state.model.styles.items) |st| _ = treeNode(.{ .style = st.id }, st.name, 2, false, false);
    }
    // What new flows' styles are copied from.
    if (state.model.templates.items.len > 0) if (treeNode(.templates, "Style templates", 1, true, false)) {
        for (state.model.templates.items) |t| _ = treeNode(.{ .template = t.id }, t.name, 2, false, false);
    };
    // Always listed: how panels are made is chosen here.
    if (treeNode(.processes, "Processes", 1, state.model.processes.items.len > 0, false)) {
        for (state.model.processes.items) |pr| _ = treeNode(.{ .process = pr.id }, pr.profile.name, 2, false, false);
    }
    // Always listed: how the document's products are made.
    if (treeNode(.plans, "Manufacturing plans", 1, state.model.plans.items.len > 0, false)) {
        for (state.model.plans.items) |pl| _ = treeNode(.{ .plan = pl.id }, pl.name, 2, false, false);
    }
    if (treeNode(.materials, "Materials", 1, state.model.materials.items.len > 0, false)) {
        for (state.model.materials.items) |mt| _ = treeNode(.{ .material = mt.id }, mt.material.name, 2, false, false);
    }
    if (state.model.sketches.items.len > 0) if (treeNode(.sketches, "Sketches", 1, true, false)) {
        for (state.model.sketches.items, 0..) |sk, i| _ = treeNode(.{ .sketch_def = i }, sk.name, 2, false, sk.default_name);
    };
    // Always listed: where figures are imported into.
    if (treeNode(.figures, "Figures", 1, state.model.figures.items.len > 0, false)) {
        for (state.model.figures.items, 0..) |f, i| _ = treeNode(.{ .figure_def = i }, f.name, 2, false, f.default_name);
    }
    // Every constraint, wherever it is and whether what it names is still
    // there (the owner, 2026-11-24): one place to choose any of them.
    if (state.model.constraints.items.len > 0) if (treeNode(.constraints, "Constraints", 1, true, false)) {
        for (state.model.constraints.items) |c| {
            var b: [300]u8 = undefined;
            _ = treeNode(.{ .constraint = c.id }, constraintText(&b, c), 2, false, false);
        }
    };
    sheetsTree();
    // The flows: each with its tracks in order; one with none is unplaced.
    if (state.model.flows.items.len > 0) if (treeNode(.flows, "Flows", 1, true, false)) {
        for (state.model.flows.items) |f| {
            var lb: [96]u8 = undefined;
            const label = if (f.tracks.items.len == 0) std.fmt.bufPrint(&lb, "{s} · unplaced", .{f.name}) catch f.name else f.name;
            if (!treeNodeSalted(.{ .flow = f.id }, label, 2, f.tracks.items.len > 0, false, 0)) continue;
            for (f.tracks.items) |tid| if (state.model.trackById(tid)) |t| {
                var tb: [160]u8 = undefined;
                const name = trackPlaceLabel(&tb, t);
                // Salted: the same track also has a row on its panel.
                _ = treeNodeSalted(.{ .region = .{ .parent = t.parent, .region = t.region } }, name, 3, false, false, 0x5f10);
            };
        }
    };
}

/// The legend sheets, in the Browser.
fn sheetsTree() void {
    if (state.model.sheets.items.len == 0) return;
    if (!treeNode(.sheets, "Legend sheets", 1, true, false)) return;
    for (state.model.sheets.items) |sh| _ = treeNode(.{ .sheet = sh.id }, sh.name, 2, false, false);
}

/// Whether tile `t` is a key a row of sheet `id` names, or beside one.
fn sheetCovers(id: layout.model.ObjectId, t: layout.model.TileId) bool {
    const m = &state.model;
    const si = m.sheetIndex(id) orelse return false;
    const a = dvui.currentWindow().arena();
    for (m.sheets.items[si].rows.items) |row| {
        const key = (m.keyInScope(a, m.sheets.items[si].scope, row.key) catch return false) orelse continue;
        var near: std.ArrayList(layout.model.TileId) = .empty;
        m.companions(a, key, &near) catch return false;
        if (std.mem.indexOfScalar(layout.model.TileId, near.items, t) != null) return true;
    }
    return false;
}

/// A legend sheet, for now in brief (its pane comes next): its name, what
/// it covers, its columns, its rows, what is wrong, and its removal.
fn sheetProperties(id: layout.model.ObjectId) void {
    const saved_group = pushGroup("sheet");
    defer popGroup(saved_group);
    const m = &state.model;
    const si = m.sheetIndex(id) orelse return;
    const sh = m.sheets.items[si];
    propText("Name", "{s}", .{sh.name}, 1);
    var cb: [200]u8 = undefined;
    var n: usize = 0;
    for (sh.columns.items, 0..) |c, k| {
        const piece = std.fmt.bufPrint(cb[n..], "{s}{s}", .{ if (k > 0) ", " else "", c }) catch break;
        n += piece.len;
    }
    propText("Columns", "name, {s}", .{cb[0..n]}, 2);
    propText("Rows", "{d}", .{sh.rows.items.len}, 3);
    const a = dvui.currentWindow().arena();
    var rows: std.ArrayList(usize) = .empty;
    var cols: std.ArrayList(usize) = .empty;
    m.sheetProblems(a, id, &rows, &cols) catch {};
    if (rows.items.len > 0) propText("Not found", "{d} row{s} name no key", .{ rows.items.len, if (rows.items.len == 1) "" else "s" }, 4);
    if (cols.items.len > 0) propText("Unused", "{d} column{s} match no slot", .{ cols.items.len, if (cols.items.len == 1) "" else "s" }, 5);
    propText("", "Its keys' legends come from it; editing one on its key edits its cell.", .{}, 6);
    keyButton(@src(), "Open it beside the canvas", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    keyButton(@src(), "Remove sheet", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// A track's name with where it is: its panel's name, unless it lies on
/// the canvas or a frame itself.
fn trackPlaceLabel(buf: []u8, t: layout.model.TrackRef) []const u8 {
    const name = state.model.regionsIn(t.parent)[t.region].name;
    const pi = t.parent.panelIndex() orelse return name;
    return std.fmt.bufPrint(buf, "{s} (on {s})", .{ name, state.model.panels.items[pi].name }) catch name;
}

/// The worksheet's branch: its panels, their labels, regions, rows and
/// tiles.
fn worksheetTree() void {
    // A canvas: each space (the canvas, then its frames) with its groups,
    // its loose objects and its panels.
    if (state.model.spaces.items.len > 0) {
        var tb: [64]u8 = undefined;
        for (state.model.spaces.items, 0..) |sp, si| {
            // A sketch's own space is the sketch's, under Sketches.
            if (sp.home != .none) continue;
            const title = if (si == 0) std.fmt.bufPrint(&tb, "Canvas, {s}", .{state.model.units.symbol()}) catch "Canvas" else sp.name;
            if (!treeNode(.{ .space = si }, title, 1, true, sp.default_name)) continue;
            for (sp.groups.items) |g| {
                if (state.model.parentGroup(g.id) == null) groupTree(g.id, 2);
            }
            for (sp.views.items, 0..) |sv, vi| _ = treeNode(.{ .view = .{ .space = si, .index = vi } }, sv.name, 2, false, false);
            for (sp.images.items, 0..) |im, ii| {
                var ib: [96]u8 = undefined;
                _ = treeNode(.{ .image = .{ .space = si, .index = ii } }, std.fmt.bufPrint(&ib, "Image {s}", .{im.name}) catch im.name, 2, false, false);
            }
            for (sp.figure_places.items, 0..) |fp, k| {
                var fb: [96]u8 = undefined;
                _ = treeNode(.{ .figure_place = .{ .space = si, .index = k } }, std.fmt.bufPrint(&fb, "Figure {s}", .{fp.name}) catch fp.name, 2, false, false);
            }
            parentChildren(.{ .space = si }, 2);
            for (state.model.panels.items, 0..) |panel, pi| {
                if (panel.space != sp.id) continue;
                if (!treeNode(.{ .panel = pi }, panel.name, 2, hasChildren(panel), panel.default_name)) continue;
                parentChildren(.{ .panel = pi }, 3);
            }
        }
        return;
    }
    const sheet = state.model.sheet;
    if (!treeNode(.worksheet, sheet.name, 1, state.model.panels.items.len > 0, sheet.default_name)) return;
    for (state.model.panels.items, 0..) |panel, pi| {
        if (!treeNode(.{ .panel = pi }, panel.name, 2, hasChildren(panel), panel.default_name)) continue;
        parentChildren(.{ .panel = pi }, 3);
    }
}

/// A group in the tree: its name and size, and the groups nested in it.
fn groupTree(id: layout.model.ObjectId, d: usize) void {
    const g = state.model.group(id) orelse return;
    var tb: [96]u8 = undefined;
    var nested = false;
    for (g.members.items) |mb| {
        if (state.model.group(mb) != null) nested = true;
    }
    const text = std.fmt.bufPrint(&tb, "Group “{s}” ({d})", .{ g.name, g.members.items.len }) catch g.name;
    if (!treeNode(.{ .group = id }, text, d, nested, false)) return;
    for (g.members.items) |mb| {
        if (state.model.group(mb) != null) groupTree(mb, d + 1);
    }
}

fn hasChildren(panel: layout.model.Panel) bool {
    return panel.regions.items.len > 0 or panel.art.items.len > 0 or panel.grids.items.len > 0;
}

/// A panel's art, or a workspace's or a panel's grids and content layouts
/// (with their rows and tiles), in the tree, from depth `d`.
fn parentChildren(pi: Parent, d: usize) void {
    var name_buf: [64]u8 = undefined;
    {
        if (pi.panelIndex()) |pn| for (state.model.panels.items[pn].art.items, 0..) |pa, ai| {
            _ = treeNode(.{ .art = .{ .panel = pn, .index = ai } }, pa.name, d, false, false);
        };
        for (state.model.gridsIn(pi), 0..) |g, gi| _ = treeNode(.{ .grid = .{ .parent = pi, .index = gi } }, g.name, d, false, g.default_name);
        for (state.model.regionsIn(pi), 0..) |region, ri| {
            // The rows lying in it; in a thread, numbered through the
            // thread's flow, and named by their place in this track.
            const here = tracksIn(pi, ri);
            // A track is one line: its keys straight under it, no row.
            const one = region.kind == .track;
            const has = if (one) for (here) |pt| {
                if (segmentFilled(pi, pt)) break true;
            } else false else here.len > 0;
            if (!treeNode(.{ .region = .{ .parent = pi, .region = ri } }, region.name, d, has, false)) continue;
            for (here) |pt| {
                const rowi = pt.track;
                const flow_ri = pt.region;
                const title = std.fmt.bufPrint(&name_buf, "{s} {d}", .{ trackWord(region.major()), pt.local + 1 }) catch "Row";
                // What the flow put in this segment, from the last solve.
                const placed_items: []const layout.place.PlacedItem = if (placedOf(pi)) |pl| pl.items else &.{};
                const filled = segmentFilled(pi, pt);
                if (!one) if (!treeNode(.{ .row = .{ .parent = pt.flow_parent, .region = flow_ri, .row = rowi } }, title, d + 1, filled, false)) continue;
                for (placed_items) |it| {
                    if (!it.flow_parent.eql(pt.flow_parent) or it.region != flow_ri or it.segment != rowi) continue;
                    // Blanks, runs and breaks are not things to select here.
                    const id = (modelItem(pi, it) orelse continue).tileOf() orelse continue;
                    if (state.model.proto(state.model.tileConst(id).prototype).spacer) continue;
                    const t = state.model.tileConst(id);
                    const tracks = state.model.prototypeOf(id).tracks;
                    const empty: []u8 = &.{};
                    const legend: []u8 = if (tracks.len > 0) (state.model.tileTrackText(dvui.currentWindow().arena(), id, tracks[0].id) catch empty) else empty;
                    // One line in the tree.
                    for (legend) |*ch| if (ch.* == '\n') {
                        ch.* = ' ';
                    };
                    const text = std.fmt.bufPrint(&name_buf, "{s}  {s}", .{ t.designator, legend }) catch t.designator;
                    _ = treeNode(.{ .tile = id }, text, if (one) d + 1 else d + 2, false, false);
                }
            }
        }
    }
}

/// Whether placed segment `pt` (on panel `pi`) holds anything but breaks,
/// from the last solve.
fn segmentFilled(pi: Parent, pt: layout.place.PlacedTrack) bool {
    const placed_items: []const layout.place.PlacedItem = if (placedOf(pi)) |pl_| pl_.items else &.{};
    for (placed_items) |it| {
        if (it.flow_parent.eql(pt.flow_parent) and it.region == pt.region and it.segment == pt.track and !isBreak(pi, it)) return true;
    }
    return false;
}

/// One tree row: an open/close arrow when it has children, and its name,
/// highlighted when it is the context and in italic when the app chose it.
/// Returns whether it is open.
fn treeNode(ctx: Context, text: []const u8, depth: usize, has_children: bool, default: bool) bool {
    return treeNodeSalted(ctx, text, depth, has_children, default, 0);
}

/// A tree row; `salt` tells apart two rows for one context (a track under
/// its panel and under its flow).
/// The Browser's path to the node being drawn, by depth, for its tag.
var tree_path: [12][]const u8 = @splat("");

fn treePathTag(depth: usize, text: []const u8, suffix: []const u8) []const u8 {
    const d = @min(depth, tree_path.len - 1);
    tree_path[d] = text;
    var w: std.Io.Writer.Allocating = .init(dvui.currentWindow().arena());
    w.writer.writeAll("tree") catch {};
    for (tree_path[0 .. d + 1]) |part| w.writer.print("/{s}", .{part}) catch {};
    w.writer.writeAll(suffix) catch {};
    return w.written();
}

fn treeNodeSalted(ctx: Context, text: []const u8, depth: usize, has_children: bool, default: bool, salt: u64) bool {
    const key = ctx.key();
    const node_tag = treePathTag(depth, text, "");
    const id: usize = @truncate(key ^ salt);
    const open = state.expanded.get(key) orelse switch (ctx) {
        .file, .worksheet, .space, .panel, .region, .prototypes, .flows => true,
        else => false,
    };
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = id, .margin = .{ .x = @floatFromInt(depth * 14) } });
    defer row.deinit();
    if (has_children) {
        if (tbuttonIcon(@src(), if (open) "Close" else "Open", if (open) dvui.entypo.chevron_small_down else dvui.entypo.chevron_small_right, .{}, .{}, .{
            .min_size_content = .{ .w = 12, .h = 12 },
            .padding = .all(1),
            .margin = .all(1),
            .gravity_y = 0.5,
            .background = false,
            .border = .all(0),
            .tag = std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}#open", .{node_tag}) catch null,
        })) {
            state.expanded.put(state.gpa, key, !open) catch {};
        }
    } else {
        _ = dvui.spacer(@src(), .{ .min_size_content = .{ .w = 16 } });
    }
    const selected = state.context.eql(ctx);
    const flagged = switch (ctx) {
        .panel => |pi| panelIssue(pi) != null,
        .constraint => |cid| if (constraintById(cid)) |c| constrain.abandoned(&state.model, c) or constraintIssue(cid) != null else false,
        else => false,
    };
    if (dvui.labelClick(@src(), "{s}", .{text}, .{}, .{
        .tag = node_tag,
        .color_text = if (flagged) .{ .color = colors.overflow } else null,
        .expand = .horizontal,
        .background = selected,
        .color_fill = if (selected) .{ .color = dvui.themeGet().focus.opacity(0.25) } else null,
        .font = styled(if (depth == 0) .theme(.heading) else .theme(.body), default),
    })) {
        // Twice on a canvas or a frame: its view fills the window (or the
        // splits come back).
        const now = std.Io.Clock.awake.now(dvui.io).toMilliseconds();
        if (tree_click.key == key and now - tree_click.ms < 400) {
            tree_click = .{};
            if (ctx == .space) showSpaceView(ctx.space);
            if (ctx == .sheet) showSheetView(ctx.sheet);
        } else tree_click = .{ .key = key, .ms = now };
        state.context = ctx;
        bringUpContext(ctx);
        // The keyboard goes to the canvas, where keys act on the context
        // (Delete, arrows moving a track).
        if (canvas_id) |cid| dvui.focusWidget(cid, null, null);
    }
    return open;
}

/// When and which Browser row was last clicked, for double-clicks.
var tree_click: struct { key: u64 = 0, ms: i64 = 0 } = .{};

/// Opens the tree down to `ctx`, so a context chosen on the canvas shows.
fn revealInTree(ctx: Context) void {
    const id = switch (ctx) {
        .tile => |t| t,
        else => return,
    };
    const f = findTile(id) orelse return;
    for ([_]Context{
        .worksheet,
        parentContext(f.parent),
        .{ .region = .{ .parent = f.parent, .region = f.tile.region } },
        .{ .row = .{ .parent = f.parent, .region = f.tile.region, .row = f.tile.row } },
    }) |c| state.expanded.put(state.gpa, c.key(), true) catch {};
    state.expanded.put(state.gpa, Context.key(.file), true) catch {};
}

/// Whether a placed tile on panel `pi` belongs to the context, for canvas
/// highlighting.
fn inContext(pi: Parent, t: layout.place.PlacedTile) bool {
    return switch (state.context) {
        .tile => |id| t.id == id,
        .row => |r| r.parent.eql(pi) and t.region == r.region and t.row == r.row,
        .region => |r| r.parent.eql(pi) and t.region == r.region,
        // Every tile made from the prototype.
        .prototype => |p| state.model.tileConst(t.id).prototype == p,
        // Every instance bound to the grid.
        .grid => |g| g.parent.eql(pi) and t.grid != null and if (state.model.gridInstanceOf(t.id)) |at| at.grid == g.index else false,
        // A flow's tiles: those in its tracks.
        .flow => |id| if (state.model.trackFlow(pi, t.region)) |f| f.id == id else false,
        // A sheet's keys: those of its rows.
        .sheet => |id| sheetCovers(id, t.id),
        .file, .worksheet, .space, .panel, .art, .group, .selection, .view, .layer, .image, .guide, .sketch, .sketches, .sketch_def, .prototypes, .flows, .sheets, .styles, .style, .templates, .template, .processes, .process, .plans, .plan, .materials, .material, .figures, .figure_def, .figure_place, .constraints, .constraint => false,
    };
}

/// The context's extents on the worksheet, mm.
fn contextExtents() geom.Box {
    switch (state.context) {
        .file, .worksheet, .prototypes => return if (openCanvas()) contentExtents() else state.model.sheet.box(),
        .space => return contentExtents(),
        .panel => |pi| return state.model.panels.items[pi].box(),
        .art => |l| return onSheet(.{ .panel = l.panel }, state.model.panels.items[l.panel].art.items[l.index].box()),
        .view => |v| if (viewAt(v.space, v.index)) |sv| {
            const b = viewBox(sv);
            if (!b.isEmpty()) return withNameRoom(b);
        },
        .image => |im| if (imageAt(im.space, im.index)) |image| return image.box(),
        // A flow: its tracks in the shown space.
        .flow => |id| if (state.model.flowIndex(id)) |fi| {
            var fb: geom.Box = .empty;
            for (state.model.flows.items[fi].tracks.items) |tid| if (state.model.trackById(tid)) |t| {
                if (state.model.spaceOfParent(t.parent) != shown_space) continue;
                for (trackOutline(t.parent, t.region)) |q| fb = fb.join(.{ .x0 = q.x, .y0 = q.y, .x1 = q.x, .y1 = q.y });
            };
            if (!fb.isEmpty()) return fb;
        },
        else => {},
    }
    var b: geom.Box = .empty;
    for (state.solved.items, 0..) |*p, k| for (p.tiles) |t| {
        const pi = state.model.parentAt(k);
        if (inContext(pi, t)) b = b.join(onSheet(pi, t.pitch_box));
    };
    return if (b.isEmpty()) state.model.sheet.box() else b;
}

/// What the canvas holds, on the worksheet frame: every panel's solved
/// content, or the canvas's first view when it holds nothing.
fn contentExtents() geom.Box {
    var b = spaceExtents();
    if (state.model.spaces.items.len > shown_space) if (state.model.spaces.items[shown_space].bound) |fb| {
        b = b.join(fb);
    };
    return if (b.isEmpty()) canvas_view else b;
}

/// The canvas area this frame, the part of it the overlays leave clear
/// (device pixels) and the rulers' width.
var canvas_free: ?struct { area: dvui.Rect.Physical, free: dvui.Rect.Physical, rw: f32 } = null;

/// The zoom (device pixels per mm) at which box `b` fills the clear part
/// of the canvas, room left for the rulers.
fn fitPpm(b: geom.Box) f64 {
    const cf = canvas_free orelse return state.view.ppm;
    // Where the overlays leave too little (a narrow window), into the
    // whole canvas instead.
    const w = @max(cf.free.w - 2.5 * cf.rw, 0.5 * cf.area.w);
    const h = @max(cf.free.h - 2.5 * cf.rw, 0.5 * cf.area.h);
    const z = 0.96 * @min(w / @max(b.width(), 1e-6), h / @max(b.height(), 1e-6));
    return if (std.math.isFinite(z) and z > 0) z else state.view.ppm;
}

/// Puts worksheet point `p` at the centre of the clear part of the canvas.
fn centreOn(p: geom.Point) void {
    const cf = canvas_free orelse return;
    const dx = (cf.free.x + cf.free.w / 2) - (cf.area.x + cf.area.w / 2);
    const dy = (cf.free.y + cf.free.h / 2) - (cf.area.y + cf.area.h / 2);
    state.view.cx = p.x - dx / state.view.ppm;
    state.view.cy = p.y + dy / state.view.ppm;
}

/// Text is legible on screen when its x-height there is at least this,
/// mm (about that of 10 pt text), measured with the screen's calibration.
const legible_x_height_mm = 1.5;
/// The x-height of text, from its cap height (the renders keep only
/// that): about seven tenths of it in most faces.
const x_per_cap = 0.7;

/// View › Frame the edit (Ctrl+9): what is being edited, legible, with as
/// much around it as the canvas can show legibly. Of the units round the
/// edit (the segment, its track, the panel, the page or canvas; or a tile,
/// its panel, the page), the largest that fits the clear part of the
/// canvas with the edited text legible is shown whole; when none does,
/// the view zooms to the legible size, centred on the edit. Measured
/// against the window as it is now. Without an edit, the context.
fn frameEdit() void {
    var units: [6]geom.Box = undefined;
    var n: usize = 0;
    var cap: ?f64 = null;
    var focus: ?geom.Point = null;
    var pi_edit: ?Parent = null;
    const add = struct {
        fn f(buf: *[6]geom.Box, len: *usize, b: geom.Box) void {
            if (b.isEmpty() or len.* >= buf.len) return;
            buf[len.*] = b;
            len.* += 1;
        }
    }.f;
    const tile_id: ?layout.model.TileId = if (canvas_eq) |q| switch (q.target) {
        .tile_track => |tt| tt.tile,
        else => null,
    } else if (track_cursor == null and state.context == .tile) state.context.tile else null;
    if (tile_id) |id| {
        for (state.solved.items, 0..) |*pl, k| for (pl.tiles) |t| if (t.id == id) {
            const pi = state.model.parentAt(k);
            const b = onSheet(pi, t.pitch_box);
            add(&units, &n, b);
            focus = .{ .x = (b.x0 + b.x1) / 2, .y = (b.y0 + b.y1) / 2 };
            pi_edit = pi;
            for (pl.labels) |l| if (l.tile != null and l.tile.? == id) {
                cap = @max(cap orelse 0, mainCap(l.render));
            };
        };
    } else if (track_cursor) |c| {
        const stops = flowStops(c.parent, c.region);
        const at: ?struct { parent: Parent, segment: usize, along: f64 } = if (stopAt(stops, c.index, c.offset)) |k|
            .{ .parent = stops[k].parent, .segment = stops[k].segment, .along = stops[k].along }
        else if (cursorPlace(c)) |cp| .{ .parent = c.parent, .segment = cp.segment, .along = cp.along } else null;
        if (at) |a| if (placedOf(a.parent)) |pl| {
            var track: geom.Box = .empty;
            for (pl.tracks) |t| {
                if (!t.flow_parent.eql(c.parent) or t.region != c.region) continue;
                const b = onSheet(a.parent, t.box);
                track = track.join(b);
                if (t.track == a.segment) {
                    add(&units, &n, b);
                    focus = if (t.major == .row) .{ .x = b.x0 + a.along, .y = (b.y0 + b.y1) / 2 } else .{ .x = (b.x0 + b.x1) / 2, .y = b.y1 - a.along };
                    // An empty track: its text will be about half its pitch.
                    if (cap == null) cap = 0.5 * @min(b.width(), b.height());
                }
            }
            add(&units, &n, track);
            pi_edit = a.parent;
            var found: ?f64 = null;
            for (pl.labels) |l| if (l.run) |r| if (r.parent.eql(c.parent) and r.region == c.region) {
                found = @max(found orelse 0, mainCap(l.render));
            };
            if (found) |f| if (f > 0) {
                cap = f;
            };
        };
    }
    const fc = focus orelse {
        zoomToContext();
        return;
    };
    if (pi_edit) |pi| if (pi.panelIndex()) |i| add(&units, &n, panelBox(i));
    add(&units, &n, if (openCanvas()) contentExtents() else state.model.sheet.box());
    const c = cap orelse 0;
    if (!(c > 0)) {
        zoomToContext();
        return;
    }
    // The zoom at which the edited text's x-height is legible.
    const legible = display.pxPerMm(dvui.windowNaturalScale()) * legible_x_height_mm / (x_per_cap * c);
    var k = n;
    while (k > 0) : (k -= 1) {
        const u = units[k - 1];
        const z = fitPpm(u);
        if (z < legible) continue;
        if (k == n) {
            // The page (or all of the canvas) fits: shown whole.
            state.view.fit = u;
            state.status = "Framed: all of it, legible. ";
        } else {
            // A smaller unit: shown whole, but zoomed in no further than a
            // little past legible, so what is round it shows too.
            state.view.fit = null;
            state.view.ppm = @min(z, 1.25 * legible);
            centreOn(.{ .x = (u.x0 + u.x1) / 2, .y = (u.y0 + u.y1) / 2 });
            state.status = "Framed: as much as shows legibly. ";
        }
        dvui.refresh(null, @src(), null);
        return;
    }
    state.view.fit = null;
    state.view.ppm = legible;
    centreOn(fc);
    state.status = "Framed: the text at a legible size (the window shows less than all of it). ";
    dvui.refresh(null, @src(), null);
}

/// The cap height of a render's own text, mm: of its level-0 elements,
/// else (a legend that is all one equation) of any; 0 when it has none.
fn mainCap(r: *const layout.Render) f64 {
    var own: f64 = 0;
    var any: f64 = 0;
    for (r.elements) |el| {
        if (el.level == 0) own = @max(own, el.cap_height);
        any = @max(any, el.cap_height);
    }
    return if (own > 0) own else any;
}

/// Centres the context in the canvas and zooms it to fill the canvas.
fn zoomToContext() void {
    state.view.fit = contextExtents();
}

// Reveal ----------------------------------------------------------------------
//
// View › Reveal the context (`view.reveal`, no key yet; the owner,
// 2026-11-22): the context brought into view without disturbing it. If it
// already lies inside the canvas's clear part (what pinned panes leave)
// less a margin, nothing moves. Otherwise the view pans the least that
// brings it inside; only if it cannot fit at this zoom does the view zoom
// out, just enough. Choosing an object in the Browser does this, after
// bringing up the context that shows it (`bringUpContext`).

/// A reveal waiting for its canvas to be drawn (a tab just opened has no
/// size yet): applied by `canvas`, to the canvas owner's view.
var reveal_pending: ?geom.Box = null;

/// The margin a revealed context keeps from the view's edges: this share
/// of the clear part's smaller side.
const reveal_margin = 0.08;

/// What the context occupies on the canvas, when it is a thing of its own
/// there (not the whole canvas or document, nor a thing without a place).
fn revealBox() ?geom.Box {
    switch (state.context) {
        .panel => |pi| {
            if (pi >= state.model.panels.items.len) return null;
            return state.model.panels.items[pi].box();
        },
        .art, .view, .image, .flow => {
            const b = contextExtents();
            return if (b.isEmpty()) null else b;
        },
        .region => |rg| {
            // A track: its outline.
            var b: geom.Box = .empty;
            for (trackOutline(rg.parent, rg.region)) |q| b = b.join(.{ .x0 = q.x, .y0 = q.y, .x1 = q.x, .y1 = q.y });
            return if (b.isEmpty()) null else b;
        },
        .row, .tile, .group => {
            var b: geom.Box = .empty;
            for (state.solved.items, 0..) |*p, k| for (p.tiles) |t| {
                const pi = state.model.parentAt(k);
                if (inContext(pi, t)) b = b.join(onSheet(pi, t.pitch_box));
            };
            return if (b.isEmpty()) null else b;
        },
        else => return null,
    }
}

// Stepping by keys ------------------------------------------------------------
//
// When a key (not a modifier alone) moves the context or the flow cursor,
// what it moved to is revealed in the active canvas: Tab hunting a
// selection, Ctrl+< and Ctrl+> through the levels, the flow cursor moved
// by the caret keys (through a flow's keys and tracks) or carried on by
// typing. A frame whose keys
// left both where they were reveals nothing, nor a context a key
// changed by changing the document (Delete); nor do undo and redo (the
// owner, 2026-11-22: the selection is not in the undo history). Pointing
// never reveals: what is pointed at is in view.

/// The context and the flow cursor, as one value to compare.
const StepSig = struct { ctx: u64, cursor: ?TrackCursor, steps: usize };

fn stepSignature() StepSig {
    return .{ .ctx = state.context.key(), .cursor = track_cursor, .steps = hist.stepCount() };
}

/// Set by undo and redo: this frame's moves are not steps.
var no_step_reveal = false;

/// Whether this frame had a key pressed (or repeating) that is not a
/// modifier alone.
fn keyThisFrame() bool {
    for (dvui.events()) |*e| {
        if (e.evt != .key) continue;
        const k = e.evt.key;
        if (k.action != .down and k.action != .repeat) continue;
        switch (k.code) {
            .left_shift, .right_shift, .left_control, .right_control, .left_alt, .right_alt, .left_command, .right_command, .menu, .caps_lock => {},
            else => return true,
        }
    }
    return false;
}

/// At the frame's end: a step by keys revealed.
fn revealStep(from: StepSig) void {
    defer no_step_reveal = false;
    if (no_step_reveal or canvas_prompt or !keyThisFrame()) return;
    const now = stepSignature();
    const moved_cursor = if (now.cursor) |c| if (from.cursor) |f| !std.meta.eql(c, f) else true else false;
    if (now.ctx == from.ctx and !moved_cursor) return;
    if (vl.views[vl.active].kind != .canvas) return;
    if (track_cursor) |c| {
        reveal_pending = cursorBox(c) orelse return;
        dvui.refresh(null, @src(), null);
    } else if (now.steps == from.steps) {
        // A key that changed the document (Delete) leaves the context
        // where it falls back to; only steps reveal.
        revealContext();
    }
}

/// The flow cursor's place on the worksheet: the bar across its segment,
/// with a little room either side, as drawn by `drawCursor`.
fn cursorBox(c: TrackCursor) ?geom.Box {
    const stops = flowStops(c.parent, c.region);
    var stop_panel: ?Parent = null;
    const at: struct { segment: usize, along: f64 } = if (stopAt(stops, c.index, c.offset)) |k| blk: {
        stop_panel = stops[k].parent;
        break :blk .{ .segment = stops[k].segment, .along = stops[k].along };
    } else blk: {
        const p = cursorPlace(c) orelse return null;
        break :blk .{ .segment = p.segment, .along = p.along };
    };
    for (state.solved.items, 0..) |*placed, k| {
        const pi = state.model.parentAt(k);
        if (stop_panel) |sp| if (!sp.eql(pi)) continue;
        for (placed.tracks) |t| {
            if (!t.flow_parent.eql(c.parent) or t.region != c.region or t.track != at.segment) continue;
            const b = onSheet(pi, t.box);
            // The bar, and a few mm of what follows it.
            const room = 3.0;
            return if (t.major == .row)
                .{ .x0 = b.x0 + at.along - room, .y0 = b.y0, .x1 = b.x0 + at.along + room, .y1 = b.y1 }
            else
                .{ .x0 = b.x0, .y0 = b.y1 - at.along - room, .x1 = b.x1, .y1 = b.y1 - at.along + room };
        }
    }
    return null;
}

/// `view.reveal`: the context into the active canvas view, at its next
/// frame.
fn revealContext() void {
    if (vl.views[vl.active].kind != .canvas) return;
    reveal_pending = revealBox() orelse return;
    dvui.refresh(null, @src(), null);
}

/// Box `b` (worksheet mm) into the canvas `area` now shows, as `reveal`
/// says.
fn revealNow(b: geom.Box, area: dvui.Rect.Physical) void {
    const cf = canvas_free orelse return;
    if (!(state.view.ppm > 0)) return;
    const free = cf.free;
    // The clear part less the rulers (top and left) and the margin.
    const m: f64 = reveal_margin * @min(free.w, free.h);
    const x0: f64 = free.x + cf.rw + m;
    const y0: f64 = free.y + cf.rw + m;
    const x1: f64 = free.x + free.w - m;
    const y1: f64 = free.y + free.h - m;
    if (x1 <= x0 or y1 <= y0) return;
    // Too big at this zoom: out just enough.
    const need = @min((x1 - x0) / @max(b.width(), 1e-9), (y1 - y0) / @max(b.height(), 1e-9));
    if (need < state.view.ppm) state.view.ppm = need;
    const r = state.view.rect(area, b);
    const rx0: f64 = r.x;
    const ry0: f64 = r.y;
    const rx1: f64 = r.x + r.w;
    const ry1: f64 = r.y + r.h;
    // The least shift, in pixels, that brings it inside.
    const sx: f64 = if (rx0 < x0) x0 - rx0 else if (rx1 > x1) x1 - rx1 else 0;
    const sy: f64 = if (ry0 < y0) y0 - ry0 else if (ry1 > y1) y1 - ry1 else 0;
    if (sx == 0 and sy == 0 and need >= state.view.ppm) return;
    // A fit still in force would undo it next frame.
    state.view.fit = null;
    state.view.cx -= sx / state.view.ppm;
    state.view.cy += sy / state.view.ppm;
    dvui.refresh(null, @src(), null);
}

/// The space a context lives in, when it lives in one.
fn spaceOfContext(ctx: Context) ?usize {
    if (state.model.spaces.items.len == 0) return null;
    const pi: ?Parent = switch (ctx) {
        .space => |si| .{ .space = si },
        .panel => |pi| .{ .panel = pi },
        .art => |l| .{ .panel = l.panel },
        .region => |r| r.parent,
        .row => |r| r.parent,
        .grid => |g| g.parent,
        .tile => |id| if (findTile(id)) |f| f.parent else null,
        .group => |g| return state.model.spaceOfId(g),
        .view => |v| return v.space,
        .layer => |l| return l.space,
        .image => |im| return im.space,
        .guide => |g| return g.space,
        .sketch => |sk| return sk.space,
        else => null,
    };
    const p = pi orelse return null;
    if (!state.model.hasParent(p)) return null;
    return state.model.spaceOfParent(p);
}

/// A context chosen in the Browser, brought up in the active window: the
/// view that shows it (a canvas of its space, its sheet, its plan) made
/// current there, its tab forwarded if the window has one, else opened as
/// a preview tab; then revealed in it. A context with no view of its own
/// (a flow, a style) is revealed in the active view if that is a canvas.
fn bringUpContext(ctx: Context) void {
    const leaf = vl.leafOf(vl.active) orelse return;
    const want: ?struct { view: docviews.View, space: usize } = switch (ctx) {
        .sheet => |id| .{ .view = .{ .kind = .sheet, .target = @intFromEnum(id) }, .space = 0 },
        .plan => |id| .{ .view = .{ .kind = .manufacture, .target = @intFromEnum(id) }, .space = 0 },
        else => if (spaceOfContext(ctx)) |sp| .{ .view = .{ .target = spaceTarget(sp) }, .space = sp } else if (state.model.spaces.items.len == 0 and revealBox() != null) .{ .view = .{}, .space = 0 } else null,
    };
    if (want) |w| {
        const cur = vl.views[vl.active];
        const here = cur.kind == w.view.kind and (if (w.view.kind == .canvas) viewSpace(vl.active) == w.space else cur.target == w.view.target);
        if (!here) _ = openInWindow(leaf, w.view, w.space, true);
    }
    revealContext();
}

/// Graven's own colours. The artwork (sheet, tiles, legends) keeps light
/// paper colours in either scheme, as drawing apps do; the chrome around it
/// (desk, rulers, title bar) follows the desktop's dark or light setting.
const Palette = struct {
    desk: dvui.Color,
    paper: dvui.Color = .{ .r = 0xfb, .g = 0xfa, .b = 0xf7 },
    panel_edge: dvui.Color = .{ .r = 0x5c, .g = 0x5a, .b = 0x55 },
    margin: dvui.Color = .{ .r = 0x9c, .g = 0x8a, .b = 0x6e },
    ruler: dvui.Color,
    titlebar: dvui.Color,
    ruler_ink: dvui.Color,
    body: dvui.Color = .{ .r = 0xe4, .g = 0xe2, .b = 0xdc },
    edge: dvui.Color = .{ .r = 0x9a, .g = 0x97, .b = 0x8f },
    face: dvui.Color = .{ .r = 0xf6, .g = 0xf5, .b = 0xf1 },
    ink: dvui.Color = .{ .r = 0x1d, .g = 0x1d, .b = 0x1b },
    /// Compliance flags take one hot hue, between red-hot and flame orange
    /// (OKLCH hue 38): no annotation or pane uses it. This is its light
    /// tint, behind a tile missing a glyph.
    missing: dvui.Color = .{ .r = 0xff, .g = 0xdd, .b = 0xd0 },
    /// Annotations that are not content: guides (margins, boundaries, view
    /// outlines, axes, track bands, break marks) and names, in one green
    /// hue (OKLCH 145), told apart by lightness, weight and line style.
    guide: dvui.Color = .{ .r = 0x2f, .g = 0x8a, .b = 0x4e },
    /// The active selection, the flow cursor and shapes being drawn: their
    /// own blue (OKLCH 255), and they move (marching dashes, a pulse).
    select: dvui.Color = .{ .r = 0x1f, .g = 0x6f, .b = 0xe0 },
    /// Construction lines: guides, never output.
    construction: dvui.Color = .{ .r = 0x8a, .g = 0x4f, .b = 0xd8 },
    /// What fails a check: overflow, past an edge, ink in a margin.
    overflow: dvui.Color = .{ .r = 0xf3, .g = 0x46, .b = 0x00 },
    /// The background grid's ink: a cool neutral, laid on at low opacity
    /// (grid.zig); its major lines at `grid_major`, minor ones fading.
    grid: dvui.Color = .{ .r = 0x3c, .g = 0x4a, .b = 0x5c },
    grid_major: f32 = 0.26,
};

const light_palette: Palette = .{
    .desk = .{ .r = 0xd9, .g = 0xd7, .b = 0xd2 },
    .ruler = .{ .r = 0xe9, .g = 0xe7, .b = 0xe2 },
    .titlebar = .{ .r = 0xeb, .g = 0xea, .b = 0xe7 },
    .ruler_ink = .{ .r = 0x4a, .g = 0x48, .b = 0x44 },
};

const dark_palette: Palette = .{
    .desk = .{ .r = 0x2b, .g = 0x2b, .b = 0x2d },
    .ruler = .{ .r = 0x38, .g = 0x38, .b = 0x3b },
    .titlebar = .{ .r = 0x30, .g = 0x30, .b = 0x33 },
    .ruler_ink = .{ .r = 0xc8, .g = 0xc6, .b = 0xc2 },
    .edge = .{ .r = 0x6a, .g = 0x68, .b = 0x64 },
    .grid = .{ .r = 0xb8, .g = 0xc4, .b = 0xd4 },
    .grid_major = 0.16,
};

var colors: Palette = light_palette;

/// The desktop settings in effect, for the title bar's button layout.
var desk: desktop.Settings = .{};

/// The interface's fonts: DejaVu Sans and DejaVu Sans Mono 2.37, built in
/// (uifont/README.md), in place of DVUI's Bitstream Vera. DejaVu is Vera
/// extended: the same shapes, with the characters legends use (Greek,
/// arrows, mathematical operators), so a key's name or a legend shows
/// wherever the interface writes it.
const ui_fonts: []const dvui.Font.Source = &.{
    .{ .family = dvui.Font.array("DejaVu Sans"), .bytes = @embedFile("uifont/DejaVuSans.ttf") },
    .{ .family = dvui.Font.array("DejaVu Sans"), .weight = .bold, .bytes = @embedFile("uifont/DejaVuSans-Bold.ttf") },
    .{ .family = dvui.Font.array("DejaVu Sans"), .style = .italic, .bytes = @embedFile("uifont/DejaVuSans-Oblique.ttf") },
    .{ .family = dvui.Font.array("DejaVu Sans"), .weight = .bold, .style = .italic, .bytes = @embedFile("uifont/DejaVuSans-BoldOblique.ttf") },
    .{ .family = dvui.Font.array("DejaVu Sans Mono"), .bytes = @embedFile("uifont/DejaVuSansMono.ttf") },
    .{ .family = dvui.Font.array("DejaVu Sans Mono"), .weight = .bold, .bytes = @embedFile("uifont/DejaVuSansMono-Bold.ttf") },
};

/// `theme` with the interface's fonts (`ui_fonts`), its sizes kept.
fn withUiFonts(theme: dvui.Theme) dvui.Theme {
    var t = theme;
    t.embedded_fonts = ui_fonts;
    t.font_body = t.font_body.withFamily("DejaVu Sans");
    t.font_heading = t.font_heading.withFamily("DejaVu Sans");
    t.font_title = t.font_title.withFamily("DejaVu Sans");
    t.font_mono = t.font_mono.withFamily("DejaVu Sans Mono");
    return t;
}

/// Matches the desktop: DVUI's Adwaita theme in the desktop's scheme with
/// its accent as the focus colour, and Graven's palette to suit; the
/// interface's own fonts.
fn applyDesktop(win: *dvui.Window, s: desktop.Settings) void {
    desk = s;
    const dark = s.scheme == .dark;
    var theme = withUiFonts(if (dark) dvui.Theme.builtin.adwaita_dark else dvui.Theme.builtin.adwaita_light);
    if (s.accent) |a| theme.focus = .{ .r = @intFromFloat(a[0] * 255), .g = @intFromFloat(a[1] * 255), .b = @intFromFloat(a[2] * 255) };
    // Every colour through the display correction (display.zig).
    display.fixAll(dvui.Color, &theme);
    win.themeSet(theme);
    setPalette();
}

/// Graven's palette for the desktop's scheme, its canvas colours as the
/// canvas theme lights them (canvas_theme.zig), through the display
/// correction.
fn setPalette() void {
    colors = if (desk.scheme == .dark) dark_palette else light_palette;
    if (canvas_theme.current == .black_light_table) {
        const ct = canvas_theme;
        colors.desk = .{ .r = ct.uv_dark.r, .g = ct.uv_dark.g, .b = ct.uv_dark.b };
        inline for (.{ "paper", "panel_edge", "margin", "body", "face", "ink", "grid" }) |f| @field(colors, f) = ct.uv(@field(colors, f));
        colors.grid_major = 0.4;
        colors.select = .{ .r = ct.fluor_select.r, .g = ct.fluor_select.g, .b = ct.fluor_select.b };
        colors.guide = .{ .r = ct.fluor_guide.r, .g = ct.fluor_guide.g, .b = ct.fluor_guide.b };
        colors.construction = .{ .r = ct.fluor_construction.r, .g = ct.fluor_construction.g, .b = ct.fluor_construction.b };
        colors.overflow = .{ .r = ct.fluor_overflow.r, .g = ct.fluor_overflow.g, .b = ct.fluor_overflow.b };
        colors.missing = .{ .r = ct.fluor_missing.r, .g = ct.fluor_missing.g, .b = ct.fluor_missing.b };
    }
    display.fixAll(dvui.Color, &colors);
}

/// Whether `c` is one of the fluorescent pigments the canvas theme draws
/// emphasis in (whatever its opacity), so it glows.
fn fluorescent(c: dvui.Color) bool {
    if (!canvas_theme.glows()) return false;
    for ([_]dvui.Color{ colors.select, colors.guide, colors.construction, colors.overflow }) |f| {
        if (c.r == f.r and c.g == f.g and c.b == f.b) return true;
    }
    return false;
}

/// The halo of a fluorescent stroke: wider, fainter strokes under it (the
/// pigment's glow), on the Black Light Table only.
fn glowUnder(pts: []const dvui.Point.Physical, closed: bool, width: f32, c: dvui.Color) void {
    if (!fluorescent(c)) return;
    const a: f32 = @as(f32, @floatFromInt(c.a)) / 255;
    const ns = dvui.windowNaturalScale();
    for ([_]f32{ 7, 4 }, [_]f32{ 0.10, 0.18 }) |grow, k| {
        dvui.Path.stroke(.{ .points = pts }, .{ .thickness = width + grow * ns, .color = .{ .color = c.opacity(a * k) }, .closed = closed });
    }
}

/// `glowUnder` for a rectangle's outline, its corners rounded by `radius`.
fn glowRect(r: dvui.Rect.Physical, radius: f32, width: f32, c: dvui.Color) void {
    if (!fluorescent(c)) return;
    const a: f32 = @as(f32, @floatFromInt(c.a)) / 255;
    const ns = dvui.windowNaturalScale();
    for ([_]f32{ 7, 4 }, [_]f32{ 0.10, 0.18 }) |grow, k| {
        r.stroke(.round(radius), .{ .thickness = width + grow * ns, .color = .{ .color = c.opacity(a * k) } });
    }
}

/// A document's own colour on the canvas: lit by the canvas theme, then
/// through the display correction.
fn docColor(c: dvui.Color) dvui.Color {
    return display.fix(canvas_theme.lit(c));
}

fn setCanvasTheme(t: canvas_theme.Theme) void {
    canvas_theme.current = t;
    setPalette();
    state.status = switch (t) {
        .light_table => "Canvas theme: Light Table (white light under the layers). ",
        .black_light_table => "Canvas theme: Black Light Table (near-UV light; emphasis fluoresces). ",
    };
}

var main_window: ?*dvui.Window = null;

fn wakeGui() void {
    if (main_window) |w| dvui.refresh(w, @src(), null);
}

// Views -----------------------------------------------------------------------
//
// The central region: the document's views (views.zig), split side by
// side or stacked, each split's views as tabs. The active view uses the
// canvas's state as it always has (the view, the shown space, the outline
// cache); each other canvas view keeps its own in a slot, swapped in only
// while it is drawn, and takes no input but a press, which makes it the
// active one. The layout goes with the file.

var vl: docviews.Layout = docviews.Layout.init(.{});

const ViewSlot = struct {
    view: View = .{},
    space: usize = 0,
    flat: ?Flat = null,
    rect: dvui.Rect = .{},
    free: @TypeOf(canvas_free) = null,
    px: ?dvui.Rect.Physical = null,
};

/// Each canvas view's state while the canvas's state is another's.
var view_slots: [docviews.max_views]ViewSlot = @splat(.{});

/// The canvas view whose state the canvas's is: the active view when it
/// is a canvas, else the last canvas view active (a sheet beside it shows
/// its edits there); none when no canvas view is open.
var canvas_owner: u8 = 0;

/// A press in an inactive view, taken at the end of the frame.
var view_to_activate: ?u8 = null;

fn activeKind() docviews.Kind {
    return vl.views[vl.active].kind;
}

/// Exchanges the canvas's state with view `i`'s slot (twice: as it was).
fn swapView(i: u8) void {
    const sl = &view_slots[i];
    if (sl.flat == null) sl.flat = .{ .arena = .init(state.gpa) };
    std.mem.swap(View, &state.view, &sl.view);
    std.mem.swap(usize, &shown_space, &sl.space);
    std.mem.swap(Flat, &state.flat, &sl.flat.?);
    std.mem.swap(dvui.Rect, &canvas_rect, &sl.rect);
    std.mem.swap(@TypeOf(canvas_free), &canvas_free, &sl.free);
    std.mem.swap(?dvui.Rect.Physical, &canvas_px, &sl.px);
}

/// Makes canvas view `to` the owner of the canvas's state; the one before
/// keeps its own in its slot.
fn takeCanvas(to: u8) void {
    const from = canvas_owner;
    if (to == from) return;
    if (from == docviews.none or !vl.open[from]) {
        // Nothing to keep: the canvas's state is the new owner's.
        swapView(to);
        if (view_slots[to].flat) |*f| f.arena.deinit();
        view_slots[to] = .{};
    } else {
        swapView(to);
        if (view_slots[from].flat) |*f| f.arena.deinit();
        view_slots[from] = view_slots[to];
        view_slots[to] = .{};
    }
    canvas_owner = to;
    if (shown_space >= @max(1, state.model.spaces.items.len)) shown_space = 0;
}

/// Makes view `to` the active one (a canvas view takes the canvas's
/// state too).
fn activateView(to: u8) void {
    if (vl.views[to].kind == .canvas) takeCanvas(to);
    vl.select(to);
    // Keys go to the view now active.
    if (vl.views[to].kind == .canvas) {
        if (canvas_id) |cid| dvui.focusWidget(cid, null, null);
    }
}

/// The views back to one canvas view, as a document starts.
fn resetViews() void {
    for (&view_slots) |*sl| {
        if (sl.flat) |*f| f.arena.deinit();
        sl.* = .{};
    }
    vl = docviews.Layout.init(.{});
    canvas_owner = 0;
    view_to_activate = null;
    view_preview = @splat(false);
}

/// Preview tabs: a tab opened from the Browser or elsewhere is a preview
/// (its label italic) until it is worked in (a change to the document
/// while it is the active view) or double-clicked; the next context opened
/// in its window takes its place. At most one a window.
var view_preview: [docviews.max_views]bool = @splat(false);
/// The history's step count when last looked at, to see work done.
var preview_steps: usize = 0;

/// The preview tab of window `leaf`, if it has one.
fn previewIn(leaf: u8) ?u8 {
    for (vl.nodes[leaf].tabList()) |t| if (view_preview[t]) return t;
    return null;
}

/// Work in the active view makes it permanent.
fn keepWorkedPreview() void {
    const n = hist.stepCount();
    if (n != preview_steps) {
        preview_steps = n;
        if (vl.active < docviews.max_views) view_preview[vl.active] = false;
    }
}

/// Shows `view` (a canvas's: of space `space`) in window `leaf`: its tab
/// there if it has one, else a new tab, made active. `preview`: the new
/// tab is a preview, in the place of the window's preview if it has one;
/// otherwise permanent (and a tab already there becomes permanent too).
fn openInWindow(leaf: u8, view: docviews.View, space: usize, preview: bool) ?u8 {
    for (vl.nodes[leaf].tabList()) |t| {
        if (vl.views[t].kind != view.kind) continue;
        if (if (view.kind == .canvas) viewSpace(t) == space else vl.views[t].target == view.target) {
            if (!preview) view_preview[t] = false;
            activateView(t);
            return t;
        }
    }
    const old = if (preview) previewIn(leaf) else null;
    const from = vl.active;
    const nv = vl.addTab(vl.currentOf(leaf), view) orelse {
        state.status = "No more views fit. ";
        return null;
    };
    vl.active = from;
    // A sketch's own space opens on its origin, 100 mm across.
    const home_fit: geom.Box = .{ .x0 = -50, .y0 = -35, .x1 = 50, .y1 = 35 };
    if (view.kind == .canvas) view_slots[nv] = .{ .view = .{ .fit = if (space == 0) canvas_view else if (state.model.isHome(space)) home_fit else null }, .space = space };
    view_preview[nv] = preview;
    // What was done to open it is not work in it.
    preview_steps = hist.stepCount();
    activateView(nv);
    if (old) |o| {
        vl.placeTab(nv, o);
        closeView(o);
    }
    return nv;
}

/// A space's ID as a view's target, and back.
fn spaceTarget(space: usize) u32 {
    if (space >= state.model.spaces.items.len) return 0;
    return @intFromEnum(state.model.spaces.items[space].id);
}

fn targetSpace(target: u32) usize {
    for (state.model.spaces.items, 0..) |sp, i| if (@intFromEnum(sp.id) == target) return i;
    return 0;
}

/// The space canvas view `i` shows.
fn viewSpace(i: u8) usize {
    return if (i == canvas_owner) shown_space else view_slots[i].space;
}

/// The layout with where each canvas view looks now, for writing.
fn syncViews() void {
    for (0..docviews.max_views) |k| {
        const i: u8 = @intCast(k);
        if (!vl.open[i] or vl.views[i].kind != .canvas) continue;
        const v: View = if (i == canvas_owner) state.view else view_slots[i].view;
        vl.views[i] = .{ .kind = .canvas, .target = spaceTarget(viewSpace(i)), .cx = v.cx, .cy = v.cy, .ppm = v.ppm };
    }
}

var views_bytes: []u8 = &.{};

/// The layout encoded, for the file (owned here until the next write).
fn encodeViews() []const u8 {
    syncViews();
    state.gpa.free(views_bytes);
    views_bytes = layout.native.encodeValue(state.gpa, docviews.Layout, vl) catch &.{};
    return views_bytes;
}

/// The layout a file kept, if it is sound: each view where it looked. A
/// sheet view whose sheet is gone shows the canvas instead.
fn loadViews(bytes: []const u8) void {
    resetViews();
    if (bytes.len == 0) return;
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const got = layout.native.decodeValue(arena.allocator(), docviews.Layout, bytes) catch return;
    if (!got.valid()) return;
    vl = got;
    canvas_owner = docviews.none;
    // The canvas's state goes to the active view if it is a canvas, else
    // the first canvas view.
    var owner: u8 = docviews.none;
    for (0..docviews.max_views) |k| {
        const i: u8 = @intCast(k);
        if (!vl.open[i]) continue;
        if (vl.views[i].kind == .sheet and state.model.sheetIndex(@enumFromInt(vl.views[i].target)) == null) vl.views[i] = .{};
        if (vl.views[i].kind == .manufacture and state.model.planIndex(@enumFromInt(vl.views[i].target)) == null) vl.views[i] = .{};
        if (vl.views[i].kind == .canvas and (owner == docviews.none or i == vl.active)) owner = i;
    }
    for (0..docviews.max_views) |k| {
        const i: u8 = @intCast(k);
        if (!vl.open[i] or vl.views[i].kind != .canvas) continue;
        const v = vl.views[i];
        const look: View = if (v.ppm > 0) .{ .cx = v.cx, .cy = v.cy, .ppm = v.ppm } else .{ .fit = canvas_view };
        if (i == owner) {
            state.view = look;
            shown_space = targetSpace(v.target);
        } else view_slots[i] = .{ .view = look, .space = targetSpace(v.target) };
    }
    canvas_owner = owner;
}

/// A view's tab label: its space's or sheet's name (numbered when two
/// show one).
fn viewLabel(buf: []u8, i: u8) []const u8 {
    if (vl.views[i].kind == .manufacture) {
        const pi = state.model.planIndex(@enumFromInt(vl.views[i].target)) orelse return "Plan";
        return std.fmt.bufPrint(buf, "Making: {s}", .{state.model.plans.items[pi].name}) catch "Plan";
    }
    if (vl.views[i].kind == .sheet) {
        const si = state.model.sheetIndex(@enumFromInt(vl.views[i].target)) orelse return "Sheet";
        return state.model.sheets.items[si].name;
    }
    const space = viewSpace(i);
    var name: []const u8 = "Canvas";
    if (space < state.model.spaces.items.len) name = if (space == 0) "Canvas" else state.model.spaces.items[space].name;
    // A sketch's own space: the sketch's name.
    if (space < state.model.spaces.items.len) if (state.model.sketchIndex(state.model.spaces.items[space].home)) |ski| {
        return std.fmt.bufPrint(buf, "Sketch: {s}", .{state.model.sketches.items[ski].name}) catch "Sketch";
    };
    if (state.model.spaces.items.len == 0) name = "Worksheet";
    // Its number among the views of the same space.
    var nth: usize = 0;
    var alike: usize = 0;
    for (0..docviews.max_views) |k| {
        const j: u8 = @intCast(k);
        if (!vl.open[j] or vl.views[j].kind != .canvas) continue;
        if (viewSpace(j) != space) continue;
        alike += 1;
        if (j == i) nth = alike;
    }
    if (alike <= 1) return name;
    return std.fmt.bufPrint(buf, "{s} ({d})", .{ name, nth }) catch name;
}

/// The panes the active view's kind wants: a sheet view no tools.
fn panesForView() void {
    const want_tools = activeKind() == .canvas;
    if (!want_tools) {
        if (tools_pane.view_hidden == null and tools_pane.mode != .hidden) {
            tools_pane.view_hidden = tools_pane.mode;
            tools_pane.mode = .hidden;
            ghost_pane.deactivate(&tools_pane);
        }
    } else if (tools_pane.view_hidden) |m| {
        tools_pane.mode = m;
        tools_pane.view_hidden = null;
    }
}

/// The central region: the views as laid out, or the one maximized.
fn viewArea() void {
    keepWorkedPreview();
    var box = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both });
    defer box.deinit();
    {
        const ns = dvui.windowNaturalScale();
        const r = box.data().contentRectScale().r;
        region_rect = .{ .x = r.x / ns, .y = r.y / ns + tab_strip_h, .w = r.w / ns, .h = @max(0, r.h / ns - tab_strip_h) };
    }
    if (vl.maximized != docviews.none) {
        if (vl.leafOf(vl.maximized)) |leaf| viewLeaf(leaf, vl.maximized);
    } else viewNode(vl.root);
    if (view_to_activate) |v| {
        view_to_activate = null;
        if (v < docviews.max_views and vl.open[v]) activateView(v);
    }
}

fn viewNode(n: u8) void {
    const node = vl.nodes[n];
    if (!node.split) return viewLeaf(n, vl.currentOf(n));
    var paned = dvui.paned(@src(), .{
        .direction = if (node.dir == .across) .horizontal else .vertical,
        .collapsed_size = 0,
        .split_ratio = &vl.nodes[n].ratio,
        .handle_size = 5,
    }, .{ .expand = .both, .id_extra = n });
    defer paned.deinit();
    // A press on the divider twice in a row: its parts evened out.
    // The divider pressed (dvui's paned takes the press, its handle 5
    // wide); let go without moving: the split's options (the grip lies
    // over the divider); pressed twice in a row: its parts evened out.
    {
        const rs = paned.data().contentRectScale();
        const across = node.dir == .across;
        const len = if (across) rs.r.w else rs.r.h;
        const line = (if (across) rs.r.x else rs.r.y) + (len - 5 * rs.s) * vl.nodes[n].ratio + 5 * rs.s;
        for (dvui.events()) |*e| {
            if (e.evt != .mouse or !e.evt.mouse.button.pointer()) continue;
            const m = e.evt.mouse;
            switch (m.action) {
                .press => {
                    const along = if (across) m.p.x else m.p.y;
                    if (!e.handled or !rs.r.contains(m.p) or @abs(along - line) > 2.5 * rs.s + 0.5) continue;
                    const now = std.Io.Clock.awake.now(dvui.io).toMilliseconds();
                    divider_held = n;
                    divider_ratio = vl.nodes[n].ratio;
                    // A press soon after a click (not a drag): a double-click.
                    if (divider_press.node == n and now - divider_press.ms < 400) {
                        vl.evenOut(n);
                        divider_press = .{};
                        divider_menu = null;
                        divider_twice = true;
                    } else divider_twice = false;
                },
                .release => if (divider_held == n) {
                    const clicked = vl.nodes[n].ratio == divider_ratio;
                    if (!divider_twice and clicked) {
                        openDividerMenu(n);
                        divider_press = .{ .node = n, .ms = std.Io.Clock.awake.now(dvui.io).toMilliseconds() };
                    } else divider_press = .{};
                    divider_twice = false;
                    divider_held = null;
                },
                else => {},
            }
        }
    }
    if (paned.showFirst()) viewNode(node.first);
    if (paned.showSecond()) viewNode(node.second);
    dividerGrip(n, paned.data().contentRect());
}

/// The divider a press holds (being dragged), and the last press on one,
/// for double-clicks.
var divider_held: ?u8 = null;
var divider_press: struct { node: u8 = docviews.none, ms: i64 = 0 } = .{};
/// The divider's share when pressed (unchanged at release: a click), and
/// whether the press was a double-click's second.
var divider_ratio: f32 = 0;
var divider_twice = false;
/// The split whose options are shown (the grip's pop-up), and where.
var divider_menu: ?u8 = null;
var divider_from: [docviews.max_nodes]dvui.Rect.Natural = @splat(.{});

/// Split `n`'s grip, on its divider: within the tab strips when side by
/// side, at the middle when stacked. A click shows the split's options;
/// the divider itself drags.
fn dividerGrip(n: u8, area: dvui.Rect) void {
    const nd = vl.nodes[n];
    // Where the divider takes a press (dvui's paned, handle 5: its gap
    // shared out by the ratio, then a little on).
    const at = (if (nd.dir == .across) area.w else area.h) - 5;
    const line = at * nd.ratio + 4;
    const r: dvui.Rect = if (nd.dir == .across)
        .{ .x = line - 8, .y = 3, .w = 16, .h = tab_strip_h - 7 }
    else
        .{ .x = area.w / 2 - 14, .y = line - 7, .w = 28, .h = 14 };
    const tag = uniqueTag("views.divider");
    recordDrawn(tag, @as(i32, n) + 1);
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{ .rect = r, .id_extra = n, .tag = tag, .background = true, .padding = .all(0), .margin = .all(0), .color_fill = .{ .color = colors.titlebar }, .border = .all(1), .color_border = .{ .color = colors.edge.opacity(0.5) } });
    bw.processEvents();
    bw.drawBackground();
    dvui.icon(@src(), "Split options", if (nd.dir == .across) dvui.entypo.dots_three_vertical else dvui.entypo.dots_three_horizontal, .{ .fill_color = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.7) } }, .{ .expand = .both, .gravity_x = 0.5, .gravity_y = 0.5, .padding = .all(2) });
    if (bw.clicked()) pushButtonEvent(tag, @as(i32, n) + 1);
    const rs = bw.data().borderRectScale().r;
    divider_from[n] = rs.toNatural();
    dvui.tooltip(@src(), .{ .active_rect = rs }, "Split: click for options; drag the divider to resize; double-click it to even out", .{}, .{ .id_extra = n });
    bw.deinit();
    // From the frame after it was asked for: the click that asked would
    // close it (a press outside a pop-up).
    if (divider_menu == n and divider_menu_frame != dvui.frameTimeNS()) dividerMenu(n);
}

/// Shows split `n`'s options (taking the keys: Esc closes them).
fn openDividerMenu(n: ?u8) void {
    divider_menu = n;
    divider_menu_new = n != null;
    divider_menu_frame = dvui.frameTimeNS();
    dvui.refresh(null, @src(), null);
}
var divider_menu_new = false;
var divider_menu_frame: i128 = 0;

fn dividerMenuClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    divider_menu = null;
}

/// Split `n`'s options: swap its sides, even it out, turn it.
fn dividerMenu(n: u8) void {
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&divider_menu), .close = dividerMenuClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    var fm = dvui.floatingMenu(@src(), .{ .from = divider_from[n], .style = .popup }, .{ .id_extra = n });
    defer fm.deinit();
    if (divider_menu_new) {
        dvui.focusSubwindow(fm.data().id, null);
        divider_menu_new = false;
    }
    const turn_label = if (vl.nodes[n].dir == .across) "Stacked" else "Side by side";
    inline for (.{ "views.swap", "views.even-out", "views.turn" }, 0..) |id, i| {
        const tag = uniqueTag(id);
        recordDrawn(tag, @as(i32, n) + 1);
        var bw: dvui.ButtonWidget = undefined;
        bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = i, .tag = tag, .margin = .all(1), .padding = .{ .x = 8, .w = 8, .y = 3, .h = 4 } });
        bw.processEvents();
        bw.drawBackground();
        dvui.labelNoFmt(@src(), if (i == 2) turn_label else comptime elements.get(id).label, .{}, .{ .padding = .all(0), .margin = .all(0) });
        if (bw.clicked()) pushButtonEvent(tag, @as(i32, n) + 1);
        bw.drawFocus();
        bw.deinit();
    }
}

/// The split a button's argument means: split `arg - 1`; 0, the one
/// holding the active view's window.
fn argSplit(arg: i32) ?u8 {
    if (arg > 0) {
        const n: u8 = @intCast(arg - 1);
        return if (n < docviews.max_nodes and vl.nodes[n].split) n else null;
    }
    return vl.splitOf(vl.active);
}

/// A tab strip's height, logical: fixed, so what lies over the views
/// knows it before the strips are drawn.
const tab_strip_h: f32 = 22;

/// Draws a window's shown tab joined to its view, in three sections: the
/// top, holding the tab's name; a wider middle band, a longer contact with
/// the view; then the view itself. Each meets the next with fillets (top
/// corners rounded, each step's inner corner and outer corner softened),
/// all filled with the colour the view's top has (the ruler's, for a
/// canvas) and outlined, so the tab and its view read as one piece.
/// `tab`: the tab's box; `strip`: the tab strip (its bottom is the view's
/// top). Drawn before the tab's label, over the strip's line.
fn folderTab(tab: dvui.Rect.Physical, strip: dvui.Rect.Physical, kind: docviews.Kind) void {
    const s = dvui.windowNaturalScale();
    const base = strip.y + strip.h;
    const top = strip.y + 3 * s;
    const band = base - 7 * s; // the middle band's top
    const widen = 8 * s; // how far the band reaches past the top each side
    const rt = 5 * s; // the top's corners
    const rs = 3 * s; // the step's inner corners
    const rc = 3 * s; // the band's outer corners
    const rb = 4 * s; // into the view
    const left = tab.x;
    const right = tab.x + tab.w;
    const fill = if (kind == .canvas) colors.ruler else dvui.themeGet().color(.content, .fill);
    const line = colors.edge.opacity(0.45);
    const n_arc = 6;
    var pts: [8 * (n_arc + 1)]dvui.Point.Physical = undefined;
    var n: usize = 0;
    const arc = struct {
        fn add(out: []dvui.Point.Physical, at: *usize, c: dvui.Point.Physical, r: f32, a0: f32, a1: f32) void {
            for (0..n_arc + 1) |i| {
                const t = a0 + (a1 - a0) * @as(f32, @floatFromInt(i)) / n_arc;
                out[at.*] = .{ .x = c.x + r * @cos(t), .y = c.y + r * @sin(t) };
                at.* += 1;
            }
        }
    }.add;
    const pi: f32 = std.math.pi;
    // Angles with y downward: 0 right, pi/2 down. Left side, from the
    // view's edge up; then the right side, down to it.
    const bl = left - widen;
    const br = right + widen;
    arc(&pts, &n, .{ .x = bl - rb, .y = base - rb }, rb, pi / 2, 0);
    arc(&pts, &n, .{ .x = bl + rc, .y = band + rc }, rc, pi, 1.5 * pi);
    arc(&pts, &n, .{ .x = left - rs, .y = band - rs }, rs, pi / 2, 0);
    arc(&pts, &n, .{ .x = left + rt, .y = top + rt }, rt, pi, 1.5 * pi);
    arc(&pts, &n, .{ .x = right - rt, .y = top + rt }, rt, 1.5 * pi, 2 * pi);
    arc(&pts, &n, .{ .x = right + rs, .y = band - rs }, rs, pi, pi / 2);
    arc(&pts, &n, .{ .x = br - rc, .y = band + rc }, rc, 1.5 * pi, 2 * pi);
    arc(&pts, &n, .{ .x = br + rb, .y = base - rb }, rb, pi, pi / 2);
    // Over the neighbours' room (the first tab's band reaches past the
    // views' left edge, over the bar beside).
    const prev_clip = dvui.clipGet();
    dvui.clipSet(dvui.windowRectPixels());
    defer dvui.clipSet(prev_clip);
    // Filled as a fan from the middle of its base: every point of the
    // outline is seen from there.
    const lifo = dvui.currentWindow().lifo();
    const col: dvui.Color.PMA = .fromColor(fill);
    const Index = dvui.Vertex.Index;
    var b = dvui.Triangles.Builder.init(lifo, n + 1, 3 * n) catch return;
    defer b.deinit(lifo);
    const c: dvui.Point.Physical = .{ .x = (left + right) / 2, .y = base };
    b.appendVertex(.{ .pos = c, .col = col });
    for (pts[0..n]) |p| b.appendVertex(.{ .pos = p, .col = col });
    for (0..n - 1) |i| {
        const k: Index = @intCast(i + 1);
        b.appendTriangles(&ccw(c, pts[i], pts[i + 1], 0, k, k + 1));
    }
    dvui.renderTriangles(b.build_unowned(), null) catch {};
    dvui.Path.stroke(.{ .points = pts[0..n] }, .{ .thickness = s, .color = .{ .color = line } });
}

/// Room each side of a tab for its band, logical (`folderTab`).
const folder_flare: f32 = 12;

/// When and which tab was last clicked, for double-clicks.
var tab_click: struct { view: u8 = docviews.none, ms: i64 = 0 } = .{};

/// A split: its tabs, then the view chosen, `shown`.
fn viewLeaf(leaf: u8, shown: u8) void {
    var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .id_extra = leaf });
    defer col.deinit();
    {
        var strip = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .min_size_content = .{ .h = tab_strip_h - 1 }, .max_size_content = .{ .w = dvui.max_float_safe, .h = tab_strip_h - 1 }, .background = true, .color_fill = .{ .color = colors.titlebar }, .border = .{ .h = 1 }, .color_border = .{ .color = colors.edge.opacity(0.4) } });
        defer strip.deinit();
        const n = vl.nodes[leaf];
        const at_left = strip.data().rect.x <= 0.5 and @abs(strip.data().borderRectScale().r.x / dvui.windowNaturalScale() - region_rect.x) < 1;
        const tab_font = dvui.Font.theme(.body).larger(-2);
        // The window's tab shown, a folder's tab joined to its view: its
        // name, then ▾ for the window's other tabs and the document's
        // contexts (Ctrl+E).
        {
            var tab = dvui.box(@src(), .{ .dir = .horizontal }, .{
                .margin = .{ .x = if (at_left) 0 else folder_flare, .w = folder_flare },
                .padding = .{ .x = 6, .w = 0, .y = 0, .h = 0 },
            });
            defer tab.deinit();
            if (vl.open[shown]) folderTab(tab.data().borderRectScale().r, strip.data().borderRectScale().r, vl.views[shown].kind);
            var lb: [96]u8 = undefined;
            const label = if (vl.open[shown]) viewLabel(&lb, shown) else "";
            // Room for descenders: no margin, a little padding below.
            if (dvui.labelClick(@src(), "{s}", .{label}, .{}, .{ .font = if (view_preview[shown]) tab_font.withStyle(.italic) else tab_font, .gravity_y = 0.5, .margin = .all(0), .padding = .{ .x = 2, .w = 2, .y = 1, .h = 3 } })) {
                const now = std.Io.Clock.awake.now(dvui.io).toMilliseconds();
                if (tab_click.view == shown and now - tab_click.ms < 400) {
                    // A preview's: kept; a kept tab's: the region filled.
                    if (view_preview[shown]) view_preview[shown] = false else vl.toggleMaximize(shown);
                    tab_click = .{};
                } else tab_click = .{ .view = shown, .ms = now };
                if (shown != vl.active) view_to_activate = shown else vl.select(shown);
            }
            stripIcon(@src(), .caret_down, "views.add", "This window's tabs, and the document's contexts", @as(i32, shown) + 1, leaf, &tab_add_from[leaf]);
        }
        // A paged context: its page, and flipping.
        if (vl.open[shown]) pageControl(shown, leaf);
        // The window's other tabs, faint, where there is room: a click shows one.
        for (n.tabList(), 0..) |v, k| {
            if (v == shown) continue;
            var lb: [96]u8 = undefined;
            const label = viewLabel(&lb, v);
            const f = if (view_preview[v]) tab_font.withStyle(.italic) else tab_font;
            if (dvui.labelClick(@src(), "{s}", .{label}, .{}, .{ .font = f, .id_extra = k, .gravity_y = 0.5, .margin = .{ .x = 6 }, .padding = .{ .x = 2, .w = 2, .y = 1, .h = 3 }, .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.55) } })) {
                if (v != vl.active) view_to_activate = v else vl.select(v);
            }
        }
        _ = dvui.spacer(@src(), .{ .expand = .horizontal });
        stripIcon(@src(), .square_split_horizontal, "views.split-across", "Split (Alt: stacked)", @as(i32, shown) + 1, leaf, null);
    }
    if (tab_add_leaf == leaf) tabAddPopup(leaf);
    if (!vl.open[shown]) return;
    switch (vl.views[shown].kind) {
        .canvas => canvasView(shown),
        .sheet => sheetView(shown),
        .manufacture => manufactureView(shown),
    }
}

/// Draws canvas view `v`: the owner of the canvas's state as the canvas
/// always was (taking input when it is active); another with its own
/// state swapped in for the drawing.
fn canvasView(v: u8) void {
    if (v == canvas_owner) return canvas(v == vl.active, v);
    swapView(v);
    if (shown_space >= @max(1, state.model.spaces.items.len)) shown_space = 0;
    canvas(false, v);
    swapView(v);
}

/// A window's strip button (`id`, an action of the registry), its tooltip
/// saying its key; `rect_out` takes where it was drawn.
fn stripIcon(src: std.builtin.SourceLocation, comptime i: icons.Icon, comptime id: []const u8, tip: []const u8, arg: i32, leaf: u8, rect_out: ?*dvui.Rect.Natural) void {
    _ = comptime elements.get(id);
    const tag = uniqueTag(id);
    recordDrawn(tag, arg);
    var tb: [96]u8 = undefined;
    var kb: [48]u8 = undefined;
    const full = if (keymap.shortcut(&kb, kmode("global"), comptime kact(id), 0)) |sc| std.fmt.bufPrint(&tb, "{s} ({s})", .{ tip, sc }) catch tip else tip;
    var alt = false;
    if (icons.button(src, i, full, .{ .size = 15, .id_extra = leaf, .rect_out = rect_out, .opts = .{ .gravity_y = 0.5, .padding = .all(3), .margin = .{ .x = 2, .w = 2 }, .tag = tag } })) {
        alt = dvui.currentWindow().modifiers.alt();
        // Alt: the other way (a split stacked).
        pushButtonEvent(tag, arg | if (alt) @as(i32, 0x100) else 0);
    }
}

/// How many pages view `v`'s context has: 0 or 1 for one without pages
/// (every context today; paged documents, frames as ordered pages, are to
/// come).
fn pageCount(v: u8) u32 {
    _ = v;
    return 0;
}

/// A paged context's page and its flipping, after the window's tab: ‹ n / m ›.
fn pageControl(v: u8, leaf: u8) void {
    const n_pages = pageCount(v);
    if (n_pages < 2) return;
    const p = @min(vl.views[v].page, n_pages - 1);
    stripIcon(@src(), .caret_down, "views.page-prev", "The page before (PgUp; Home: the first)", @as(i32, v) + 1, leaf, null);
    dvui.label(@src(), "{d} / {d}", .{ p + 1, n_pages }, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.body).larger(-2), .id_extra = leaf });
    stripIcon(@src(), .caret_down, "views.page-next", "The next page (PgDn; End: the last)", @as(i32, v) + 1, leaf, null);
}

/// View `v` flipped `by` pages (to the first or last when `ends`).
fn flipPage(v: u8, forward: bool, ends: bool) void {
    const n_pages = pageCount(v);
    if (n_pages < 2) return;
    const p = &vl.views[v].page;
    if (ends) {
        p.* = if (forward) n_pages - 1 else 0;
    } else if (forward) {
        p.* = @min(p.* + 1, n_pages - 1);
    } else if (p.* > 0) p.* -= 1;
    dvui.refresh(null, @src(), null);
}

/// The + pop-up: the window (a leaf of the split tree) it adds to, or
/// null when it is closed; its filter, typed.
var tab_add_leaf: ?u8 = null;
var tab_add_new = false;
var tab_add_filter: [64]u8 = @splat(0);
/// Where each window's + was last drawn: the pop-up hangs from it.
var tab_add_from: [docviews.max_nodes]dvui.Rect.Natural = @splat(.{});

/// A context a view can show: what, its name, and its group in the
/// pop-up (0 canvas and frames, 1 legend sheets, 2 manufacturing plans).
const ViewContext = struct { view: docviews.View, space: usize = 0, name: []const u8, group: u2 };

const context_groups = [_][]const u8{ "Canvas and frames", "Legend sheets", "Manufacturing plans", "Sketches" };

/// The document's contexts, in the pop-up's order.
fn viewContexts(out: []ViewContext) []ViewContext {
    var n: usize = 0;
    const spaces = state.model.spaces.items;
    if (spaces.len == 0) {
        out[0] = .{ .view = .{}, .name = "Worksheet", .group = 0 };
        n = 1;
    } else for (spaces, 0..) |sp, i| {
        if (n == out.len) break;
        if (sp.home != .none) continue;
        out[n] = .{ .view = .{ .target = @intFromEnum(sp.id) }, .space = i, .name = if (i == 0) "Canvas" else sp.name, .group = 0 };
        n += 1;
    }
    for (state.model.sheets.items) |sh| {
        if (n == out.len) break;
        out[n] = .{ .view = .{ .kind = .sheet, .target = @intFromEnum(sh.id) }, .name = sh.name, .group = 1 };
        n += 1;
    }
    for (state.model.plans.items) |pl| {
        if (n == out.len) break;
        out[n] = .{ .view = .{ .kind = .manufacture, .target = @intFromEnum(pl.id) }, .name = pl.name, .group = 2 };
        n += 1;
    }
    // Sketches' own spaces (`Space.home`).
    for (spaces, 0..) |sp, i| {
        if (n == out.len) break;
        const ski = state.model.sketchIndex(sp.home) orelse continue;
        const name = std.fmt.allocPrint(dvui.currentWindow().arena(), "Sketch: {s}", .{state.model.sketches.items[ski].name}) catch continue;
        out[n] = .{ .view = .{ .target = @intFromEnum(sp.id) }, .space = i, .name = name, .group = 3 };
        n += 1;
    }
    return out[0..n];
}

/// The tab of window `leaf` showing context `c`, if it has one.
fn tabShowing(leaf: u8, c: ViewContext) ?u8 {
    for (vl.nodes[leaf].tabList()) |t| {
        if (vl.views[t].kind != c.view.kind) continue;
        if (if (c.view.kind == .canvas) viewSpace(t) == c.space else vl.views[t].target == c.view.target) return t;
    }
    return null;
}

/// Shows context `c` in window `leaf`: its tab there, else a new one.
fn addToWindow(leaf: u8, c: ViewContext) void {
    _ = openInWindow(leaf, c.view, c.space, false);
}

fn tabAddClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    tab_add_leaf = null;
}

/// Whether `name` has `filter` in it, case aside.
fn filterMatches(name: []const u8, filter: []const u8) bool {
    return filter.len == 0 or std.ascii.findIgnoreCase(name, filter) != null;
}

/// The + pop-up of window `leaf`: a filter (Enter: the first match), then
/// the contexts by group, those already in its tabs marked.
fn tabAddPopup(leaf: u8) void {
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&tab_add_leaf), .close = tabAddClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    var fm = dvui.floatingMenu(@src(), .{ .from = tab_add_from[leaf], .style = .popup }, .{ .min_size_content = .{ .w = 240 } });
    defer fm.deinit();
    var buf: [128]ViewContext = undefined;
    const all = viewContexts(&buf);
    const filter_tag = uniqueTag("views.filter");
    checkElement(filter_tag, .field, "Find a context");
    var te = dvui.textEntry(@src(), .{ .text = .{ .buffer = &tab_add_filter }, .placeholder = "Find a context" }, .{ .expand = .horizontal, .tag = filter_tag });
    if (tab_add_new) {
        dvui.focusSubwindow(fm.data().id, null);
        dvui.focusWidget(te.data().id, fm.data().id, null);
        tab_add_new = false;
    }
    const filter = std.mem.trim(u8, te.textGet(), " ");
    const enter = te.enter_pressed;
    te.deinit();
    // This window's tabs: shown by a click, taken off by ×.
    var first_tab: ?u8 = null;
    {
        const tabs = vl.nodes[leaf].tabList();
        const cur = vl.currentOf(leaf);
        var any = false;
        for (tabs, 0..) |t, k| {
            var lb: [96]u8 = undefined;
            const name = viewLabel(&lb, t);
            if (!filterMatches(name, filter)) continue;
            if (!any) {
                dvui.labelNoFmt(@src(), "This window", .{}, .{ .id_extra = 2000, .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.6) }, .margin = .{ .x = 4, .y = 6 } });
                any = true;
            }
            if (first_tab == null and t != cur) first_tab = t;
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3000 + k });
            defer row.deinit();
            const tag = listTag("views.tabs", name);
            recordDrawn(tag, t);
            var bw: dvui.ButtonWidget = undefined;
            bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = k, .tag = tag, .margin = .all(1), .padding = .{ .x = 6, .w = 6, .y = 3, .h = 4 } });
            bw.processEvents();
            bw.drawBackground();
            var tb: [112]u8 = undefined;
            const text = std.fmt.bufPrint(&tb, "{s}{s}{s}", .{ if (t == cur) "•  " else "    ", name, if (view_preview[t]) "  (preview)" else "" }) catch name;
            dvui.labelNoFmt(@src(), text, .{}, .{ .gravity_y = 0.5, .padding = .all(0), .margin = .all(0), .font = if (view_preview[t]) dvui.Font.theme(.body).withStyle(.italic) else null });
            if (bw.clicked()) pushButtonEvent(tag, t);
            bw.drawFocus();
            bw.deinit();
            if (tabs.len > 1 or vl.views[t].kind != .canvas) keyIcon(@src(), "Remove from tabs", dvui.entypo.cross, @as(i32, t) + 1, .{ .min_size_content = .{ .w = 9, .h = 9 }, .padding = .all(3), .gravity_y = 0.5, .background = false, .border = .all(0), .id_extra = k, .tag = uniqueTag("views.close") });
        }
        if (any) _ = dvui.separator(@src(), .{ .expand = .horizontal, .margin = .{ .y = 4, .h = 2 }, .id_extra = 2001 });
    }
    var first: ?usize = null;
    var group: ?u2 = null;
    for (all, 0..) |c, i| {
        if (!filterMatches(c.name, filter)) continue;
        if (first == null) first = i;
        if (group != c.group) {
            group = c.group;
            dvui.labelNoFmt(@src(), context_groups[c.group], .{}, .{ .id_extra = 1000 + @as(usize, c.group), .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.6) }, .margin = .{ .x = 4, .y = 6 } });
        }
        var lb: [96]u8 = undefined;
        const label = std.fmt.bufPrint(&lb, "{s}{s}", .{ if (tabShowing(leaf, c) != null) "•  " else "    ", c.name }) catch c.name;
        // A row, its name from the left (a list, not a button's centre).
        const tag = listTag("views.contexts", c.name);
        recordDrawn(tag, @intCast(i));
        var bw: dvui.ButtonWidget = undefined;
        bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = i, .tag = tag, .margin = .all(1), .padding = .{ .x = 6, .w = 6, .y = 3, .h = 4 } });
        bw.processEvents();
        bw.drawBackground();
        dvui.labelNoFmt(@src(), label, .{}, .{ .gravity_y = 0.5, .padding = .all(0), .margin = .all(0) });
        if (bw.clicked()) pushButtonEvent(tag, @intCast(i));
        bw.drawFocus();
        bw.deinit();
    }
    if (first == null) dvui.labelNoFmt(@src(), "Nothing by that name", .{}, .{ .margin = .{ .x = 4, .y = 4 } });
    if (state.model.spaces.items.len > 0) {
        const saved_group = pushGroup("views");
        defer popGroup(saved_group);
        _ = dvui.separator(@src(), .{ .expand = .horizontal, .margin = .{ .y = 4, .h = 2 }, .id_extra = 2002 });
        keyButton(@src(), "New sketch, in its own space", 0, .{ .expand = .horizontal });
    }
    if (enter) {
        if (first_tab != null and filter.len > 0) {
            tab_add_leaf = null;
            activateView(first_tab.?);
        } else if (first) |i| {
            tab_add_leaf = null;
            addToWindow(leaf, all[i]);
        }
    }
}

/// A new canvas view beside the active view (`dir`), looking where the
/// canvas looks.
fn splitView(dir: docviews.Dir) void {
    const from = vl.active;
    const look = state.view;
    const space = shown_space;
    const kind = vl.views[from].kind;
    const target = vl.views[from].target;
    // A sheet's: another view of the sheet; a canvas's: of its space.
    const nv = vl.split(from, dir, if (kind == .sheet) .{ .kind = .sheet, .target = target } else .{ .target = spaceTarget(space) }) orelse {
        state.status = "No more views fit. ";
        return;
    };
    vl.active = from;
    if (kind == .canvas) {
        view_slots[nv] = .{ .view = look, .space = space };
        view_slots[nv].view.fit = null;
    }
    activateView(nv);
}

/// Opens `view` beside the active view, side by side, and makes it
/// active; or, when one already shows it, makes that one active.
fn openBeside(view: docviews.View) void {
    var buf: [docviews.max_views]u8 = undefined;
    const have = vl.viewsOf(view.kind, view.target, &buf);
    if (have.len > 0) {
        activateView(have[0]);
        return;
    }
    // Another window's preview gives way to it; else a new window.
    const here = vl.leafOf(vl.active);
    for (vl.nodes, 0..) |nd, k| {
        const leaf: u8 = @intCast(k);
        if (!nd.used or nd.split or leaf == here) continue;
        if (previewIn(leaf) != null) {
            _ = openInWindow(leaf, view, 0, true);
            return;
        }
    }
    const from = vl.active;
    const nv = vl.split(from, .across, view) orelse {
        state.status = "No more views fit. ";
        return;
    };
    vl.active = from;
    view_preview[nv] = true;
    preview_steps = hist.stepCount();
    activateView(nv);
}

fn closeView(v: u8) void {
    var open_n: usize = 0;
    for (vl.open) |o| {
        if (o) open_n += 1;
    }
    if (open_n <= 1) return;
    // The view taking its place where it was, else any other.
    var next: ?u8 = null;
    if (vl.leafOf(v)) |leaf| {
        for (vl.nodes[leaf].tabList()) |t| if (t != v) {
            next = t;
            break;
        };
    }
    if (next == null) for (0..docviews.max_views) |k| {
        const j: u8 = @intCast(k);
        if (vl.open[j] and j != v) {
            next = j;
            break;
        }
    };
    const to = next orelse return;
    if (v == canvas_owner) {
        // Its state goes to another canvas view, if there is one.
        var heir: u8 = docviews.none;
        if (vl.views[to].kind == .canvas) {
            heir = to;
        } else for (0..docviews.max_views) |k| {
            const j: u8 = @intCast(k);
            if (vl.open[j] and j != v and vl.views[j].kind == .canvas) {
                heir = j;
                break;
            }
        }
        if (heir != docviews.none) takeCanvas(heir) else canvas_owner = docviews.none;
    }
    if (view_slots[v].flat) |*f| f.arena.deinit();
    view_slots[v] = .{};
    view_preview[v] = false;
    const was_active = v == vl.active;
    _ = vl.close(v);
    if (was_active) activateView(to);
}

/// Shows space `space` in a view filling the region: one already showing
/// it, else a new tab beside the active view. Again: the splits back.
fn showSpaceView(space: usize) void {
    const target = spaceTarget(space);
    for (0..docviews.max_views) |k| {
        const j: u8 = @intCast(k);
        if (!vl.open[j] or vl.views[j].kind != .canvas) continue;
        if (viewSpace(j) == space) {
            activateView(j);
            vl.toggleMaximize(j);
            return;
        }
    }
    const leaf = vl.leafOf(vl.active) orelse return;
    const nv = openInWindow(leaf, .{ .target = target }, space, true) orelse return;
    vl.toggleMaximize(nv);
}

/// As `showSpaceView`, for sheet `id`.
fn showSheetView(id: layout.model.ObjectId) void {
    var buf: [docviews.max_views]u8 = undefined;
    const have = vl.viewsOf(.sheet, @intFromEnum(id), &buf);
    if (have.len > 0) {
        activateView(have[0]);
        vl.toggleMaximize(have[0]);
        return;
    }
    const leaf = vl.leafOf(vl.active) orelse return;
    const nv = openInWindow(leaf, .{ .kind = .sheet, .target = @intFromEnum(id) }, 0, true) orelse return;
    vl.toggleMaximize(nv);
}

// The sheet view -----------------------------------------------------------
//
// A legend sheet as a table: the name column, then a column per slot, a
// row per key. The selected cell is edited where it is: each change goes
// to the sheet as it is typed (one undo step a cell), so a canvas view
// beside it shows the keys change; the name column renames its key when
// the edit is done (Enter or leaving it). Arrows up and down, Tab and
// Shift+Tab, and Enter move between cells (mode `sheet`). The selected
// row's key is the context, so canvas views show it; a key chosen on the
// canvas selects its row. Rows naming no key and columns no key has are
// marked.

/// The cell selected, in which sheet.
var sheet_sel: struct { sheet: layout.model.ObjectId = .none, row: usize = 0, col: usize = 1 } = .{};
/// The context last seen, so a key chosen elsewhere selects its row once.
var sheet_seen_ctx: u64 = 0;
/// The cell whose editor last took the keyboard (sheet, row, column), so
/// it takes it only once; cleared when the sheet stops being active.
var sheet_focus_for: u64 = 0;
/// The selected cell's editor, as last drawn: the sheet's keys act while
/// it has the keyboard.
var sheet_editor_id: ?dvui.Id = null;
/// A name being typed, kept until done.
var sheet_name_edit: ?struct { sheet: layout.model.ObjectId, row: usize, text: [128]u8 = undefined, len: usize = 0 } = null;

const sheet_name_w: f32 = 90;
const sheet_col_w: f32 = 150;

/// The key of row `row` of sheet `si`, in its scope.
fn sheetRowKey(si: usize, row: usize) ?TileId {
    const sh = state.model.sheets.items[si];
    if (row >= sh.rows.items.len) return null;
    return state.model.keyInScope(dvui.currentWindow().arena(), sh.scope, sh.rows.items[row].key) catch null;
}

/// The tile and slot the selected cell drives (its key, or a legend
/// beside it with that slot), for the expression line.
fn sheetCellTarget() ?ExprTarget {
    if (activeKind() != .sheet) return null;
    const si = state.model.sheetIndex(sheet_sel.sheet) orelse return null;
    const sh = state.model.sheets.items[si];
    if (sheet_sel.col == 0 or sheet_sel.col > sh.columns.items.len) return null;
    const key = sheetRowKey(si, sheet_sel.row) orelse return null;
    const slot = sh.columns.items[sheet_sel.col - 1];
    var near: std.ArrayList(TileId) = .empty;
    state.model.companions(dvui.currentWindow().arena(), key, &near) catch return null;
    for (near.items) |t| if (state.model.tileTrackNamed(t, slot)) |track| return .{ .tile_track = .{ .tile = t, .track = track } };
    return null;
}

/// Moves the selected cell: 0 up, 1 down, 2 right (on to the next row),
/// 3 left (back to the row before).
fn sheetMove(dir: i32) void {
    const si = state.model.sheetIndex(sheet_sel.sheet) orelse return;
    const sh = state.model.sheets.items[si];
    const rows = sh.rows.items.len;
    const cols = sh.columns.items.len + 1;
    if (rows == 0) return;
    commitSheetName();
    switch (dir) {
        0 => if (sheet_sel.row > 0) {
            sheet_sel.row -= 1;
        },
        1 => if (sheet_sel.row + 1 < rows) {
            sheet_sel.row += 1;
        },
        2 => if (sheet_sel.col + 1 < cols) {
            sheet_sel.col += 1;
        } else if (sheet_sel.row + 1 < rows) {
            sheet_sel.row += 1;
            sheet_sel.col = 0;
        },
        else => if (sheet_sel.col > 0) {
            sheet_sel.col -= 1;
        } else if (sheet_sel.row > 0) {
            sheet_sel.row -= 1;
            sheet_sel.col = cols - 1;
        },
    }
    sheetSelectKey(si);
}

/// The selected row's key as the context, so canvas views show it.
fn sheetSelectKey(si: usize) void {
    if (sheetRowKey(si, sheet_sel.row)) |key| {
        state.context = .{ .tile = key };
        sheet_seen_ctx = state.context.key();
    }
}

/// A name typed into the name column, given to the row and its key.
fn commitSheetName() void {
    const ne = sheet_name_edit orelse return;
    sheet_name_edit = null;
    const si = state.model.sheetIndex(ne.sheet) orelse return;
    const text = std.mem.trim(u8, ne.text[0..ne.len], " ");
    if (ne.row >= state.model.sheets.items[si].rows.items.len or text.len == 0) return;
    if (std.mem.eql(u8, state.model.sheets.items[si].rows.items[ne.row].key, text)) return;
    act(.setSheetCell, .{ ne.sheet, ne.row, 0, text }) catch |err| {
        state.status = if (err == error.DuplicateDesignator) "That name is another key's: the row keeps its own. " else "The row was not renamed. ";
    };
}

fn sheetView(v: u8) void {
    const id: layout.model.ObjectId = @enumFromInt(vl.views[v].target);
    const si = state.model.sheetIndex(id) orelse return;
    const active = v == vl.active;
    if (!active) sheet_focus_for = 0;
    if (sheet_sel.sheet != id) sheet_sel = .{ .sheet = id };
    var box = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .color_fill = .{ .color = colors.paper }, .id_extra = v });
    defer box.deinit();
    // A press activates it (cells take their own clicks too).
    if (!active) for (dvui.events()) |*e| {
        if (!dvui.eventMatchSimple(e, box.data())) continue;
        if (e.evt == .mouse and e.evt.mouse.action == .press) view_to_activate = v;
    };
    const m = &state.model;
    const sh = m.sheets.items[si];
    const a = dvui.currentWindow().arena();
    // A key chosen elsewhere (on the canvas): its row.
    if (state.context.key() != sheet_seen_ctx) {
        sheet_seen_ctx = state.context.key();
        if (state.context == .tile) {
            const t = state.context.tile;
            for (sh.rows.items, 0..) |_, r| {
                const key = sheetRowKey(si, r) orelse continue;
                var near: std.ArrayList(TileId) = .empty;
                m.companions(a, key, &near) catch continue;
                if (std.mem.indexOfScalar(TileId, near.items, t) != null) {
                    commitSheetName();
                    sheet_sel.row = r;
                    break;
                }
            }
        }
    }
    // Its keys: the moves between cells, while its cell has the keyboard
    // (not a dialog's field, a menu or a pane's).
    const editing = if (sheet_editor_id) |eid| dvui.focusedWidgetId() == eid else false;
    if (active and editing) for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("sheet")) orelse continue;
        if (inv.action == kact("sheet.move")) {
            e.handle(@src(), box.data());
            sheetMove(inv.arg);
            dvui.refresh(null, @src(), box.data().id);
        }
    };
    var bad_rows: std.ArrayList(usize) = .empty;
    var bad_cols: std.ArrayList(usize) = .empty;
    m.sheetProblems(a, id, &bad_rows, &bad_cols) catch {};
    const head_font = dvui.Font.theme(.body).larger(-1).withWeight(.bold);
    const cell_font = ghost_pane.fieldFont();
    // The header.
    {
        var hdr = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .background = true, .color_fill = .{ .color = colors.titlebar }, .border = .{ .h = 1 }, .color_border = .{ .color = colors.edge.opacity(0.5) } });
        defer hdr.deinit();
        dvui.labelNoFmt(@src(), "name", .{}, .{ .min_size_content = .{ .w = sheet_name_w }, .max_size_content = .width(sheet_name_w), .font = head_font, .padding = .{ .x = 6, .y = 3, .h = 3 } });
        for (sh.columns.items, 0..) |c, ci| {
            const unused = std.mem.indexOfScalar(usize, bad_cols.items, ci) != null;
            dvui.labelNoFmt(@src(), c, .{}, .{ .min_size_content = .{ .w = sheet_col_w }, .max_size_content = .width(sheet_col_w), .font = head_font, .padding = .{ .x = 6, .y = 3, .h = 3 }, .color_text = if (unused) .{ .color = colors.overflow } else null, .border = .{ .x = 1 }, .color_border = .{ .color = colors.edge.opacity(0.3) }, .id_extra = ci });
        }
    }
    var scroll = dvui.scrollArea(@src(), .{ .horizontal = .auto }, .{ .expand = .both, .background = false });
    defer scroll.deinit();
    for (sh.rows.items, 0..) |row, r| {
        const sel_row = r == sheet_sel.row;
        const missing = std.mem.indexOfScalar(usize, bad_rows.items, r) != null;
        var line = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = r, .background = true, .color_fill = .{ .color = if (sel_row) colors.paper.lerp(dvui.themeGet().focus, if (active) 0.08 else 0.2) else colors.paper }, .border = .{ .h = 1 }, .color_border = .{ .color = colors.edge.opacity(0.15) } });
        defer line.deinit();
        for (0..sh.columns.items.len + 1) |c| {
            const w = if (c == 0) sheet_name_w else sheet_col_w;
            const text = if (c == 0) row.key else if (c - 1 < row.cells.items.len) row.cells.items[c - 1] else "";
            const selected = active and sel_row and c == sheet_sel.col;
            if (selected) {
                // Edited where it is.
                var te = dvui.textEntry(@src(), .{ .text_initial = if (c == 0 and sheet_name_edit != null) sheet_name_edit.?.text[0..sheet_name_edit.?.len] else text }, .{ .min_size_content = .{ .w = w - 8 }, .max_size_content = .width(w - 8), .font = cell_font, .id_extra = (r << 8) + c, .margin = .all(1) });
                defer te.deinit();
                sheet_editor_id = te.data().id;
                // The keyboard, once: when the cell is newly selected or
                // the sheet becomes active (not every frame, which would
                // take it from a menu or a field elsewhere).
                const here = (@as(u64, r) << 16) | c | (@as(u64, @intFromEnum(id)) << 32);
                if (sheet_focus_for != here) {
                    sheet_focus_for = here;
                    dvui.focusWidget(te.data().id, null, null);
                }
                const now = te.textGet();
                if (c == 0) {
                    if (!std.mem.eql(u8, now, row.key) or sheet_name_edit != null) {
                        var ne = sheet_name_edit orelse @TypeOf(sheet_name_edit.?){ .sheet = id, .row = r };
                        ne.len = @min(now.len, ne.text.len);
                        @memcpy(ne.text[0..ne.len], now[0..ne.len]);
                        sheet_name_edit = ne;
                    }
                    if (te.enter_pressed) commitSheetName();
                } else if (te.text_changed) {
                    // Typed here: the cell takes it.
                    if (!std.mem.eql(u8, now, text)) _ = actM(mergeKey(.{ "sheet cell", @intFromEnum(id), r, c }), .setSheetCell, .{ id, r, c, now }) catch {};
                } else if (!std.mem.eql(u8, now, text)) {
                    // The cell changed elsewhere (an import, an undo, its
                    // key's legend typed on the canvas): the editor shows
                    // it, rather than writing its old text back over it.
                    te.textSet(text, false);
                }
            } else {
                const ink: ?dvui.Color = if (c == 0 and missing) colors.overflow else null;
                if (dvui.labelClick(@src(), "{s}", .{text}, .{}, .{
                    .min_size_content = .{ .w = w },
                    .max_size_content = .width(w),
                    .font = cell_font,
                    .padding = .{ .x = 6, .y = 4, .h = 4 },
                    .color_text = if (ink) |k| .{ .color = k } else null,
                    // The row's highlight shows through; the name column
                    // a shade apart.
                    .background = true,
                    .color_fill = .{ .color = if (c == 0) colors.titlebar.opacity(0.5) else colors.paper.opacity(0) },
                    .border = .{ .x = if (c == 0) 0 else 1 },
                    .color_border = .{ .color = colors.edge.opacity(0.15) },
                    .id_extra = (r << 8) + c,
                })) {
                    commitSheetName();
                    sheet_sel = .{ .sheet = id, .row = r, .col = c };
                    sheetSelectKey(si);
                    view_to_activate = v;
                }
            }
        }
    }
}

/// The properties while a sheet view is active: the sheet, the selected
/// cell's row and key, and the naming helpers.
fn sheetViewProperties() void {
    const saved_group = pushGroup("sheet.cell");
    defer popGroup(saved_group);
    const id = sheet_sel.sheet;
    const m = &state.model;
    const si = m.sheetIndex(id) orelse return;
    const sh = m.sheets.items[si];
    headingAs("sheet.cell", "{s}", .{sh.name}, 9700);
    if (sheet_sel.row < sh.rows.items.len) {
        const row = sh.rows.items[sheet_sel.row];
        propText("Row", "{d} of {d}", .{ sheet_sel.row + 1, sh.rows.items.len }, 9701);
        if (sheetRowKey(si, sheet_sel.row)) |key| {
            const t = m.tileConst(key);
            propText("Tile", "{s} ({s})", .{ t.designator, m.prototypeOf(key).name }, 9702);
        } else propText("Tile", "none named {s} here", .{row.key}, 9702);
        if (sheet_sel.col > 0 and sheet_sel.col <= sh.columns.items.len) {
            const slot = sh.columns.items[sheet_sel.col - 1];
            propText("Slot", "{s}{s}", .{ slot, if (sheetCellTarget() == null) " (not on this key)" else "" }, 9703);
        }
    }
    keyButton(@src(), "Name tiles by grid position (R1C1…)", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    keyButton(@src(), "Name tiles by their first legend", 0, .{ .expand = .horizontal });
    keyButton(@src(), "Add a row", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    if (sh.rows.items.len > 0) keyButton(@src(), "Remove this row", 0, .{ .expand = .horizontal });
}

/// Names every key of sheet `si`: by its grid place (R1C1, from row 1,
/// column 1), or by its first legend where that is an identifier (a
/// letter, then letters and digits); a name taken gets a number (Enter1).
/// One undo step.
fn nameSheetKeys(si: usize, how: enum { position, legend }) void {
    const m = &state.model;
    const id = m.sheets.items[si].id;
    import_count += 1;
    const key = mergeKey(.{ "name keys", import_count });
    var named: usize = 0;
    for (0..m.sheets.items[si].rows.items.len) |r| {
        const tile = sheetRowKey(si, r) orelse continue;
        var nb: [64]u8 = undefined;
        var want: []const u8 = "";
        switch (how) {
            .position => {
                const at = m.gridInstanceOf(tile) orelse continue;
                const inst = m.gridsIn(at.parent)[at.grid].instances.items[at.index];
                want = std.fmt.bufPrint(&nb, "R{d}C{d}", .{ inst.row + 1, inst.col + 1 }) catch continue;
            },
            .legend => {
                const row = m.sheets.items[si].rows.items[r];
                for (row.cells.items) |cell| {
                    const t = std.mem.trim(u8, cell, " ");
                    if (t.len == 0) continue;
                    if (layout.names.isIdentifier(t)) want = t;
                    break;
                }
                if (want.len == 0) continue;
            },
        }
        // Taken by another key: numbered.
        var nb2: [72]u8 = undefined;
        const name = if (m.findTile(want)) |other| (if (other == tile) want else m.freshName(&nb2, .keys, want)) else want;
        if (std.mem.eql(u8, m.sheets.items[si].rows.items[r].key, name)) continue;
        _ = actM(key, .setSheetCell, .{ id, r, 0, name }) catch continue;
        named += 1;
    }
    var sb: [64]u8 = undefined;
    state.status = std.fmt.bufPrint(&status_name_buf, "{d} key{s} named. ", .{ named, if (named == 1) "" else "s" }) catch "Keys named. ";
    _ = &sb;
}

var status_name_buf: [64]u8 = undefined;

/// The canvas: the worksheet at true proportions, with every panel on it.
/// Wheel zooms about the pointer and dragging pans. With the select tool a
/// click makes a tile, panel or the worksheet the context; with the add
/// panel tool a drag draws out a new panel. The context is outlined.
/// `GRAVEN_SAMPLE=sketch-space`: a new sketch in its own space, made on
/// the first frame (once the views are set up).
var sample_sketch_space = false;

fn canvas(active: bool, view: u8) void {
    if (active) followHome();
    var box = dvui.box(@src(), .{}, .{ .expand = .both, .background = true, .color_fill = .{ .color = colors.desk }, .id_extra = view });
    defer box.deinit();
    const area = box.data().contentRectScale().r;
    const rw: f32 = ruler_size * dvui.windowNaturalScale();
    if (area.w <= 3 * rw or area.h <= 3 * rw) return;
    const sheet = state.model.sheet;
    const open = openCanvas();

    // The first frame fits the worksheet, leaving room for its rulers; a
    // canvas shows the space around its origin.
    if (state.view.ppm == 0 and state.view.fit == null) state.view.fit = if (open) canvas_view else sheet.box();
    const ns = dvui.windowNaturalScale();
    canvas_rect = .{ .x = area.x / ns, .y = area.y / ns, .w = area.w / ns, .h = area.h / ns };
    {
        // The part of the canvas overlays leave clear, for fitting.
        const ins = overlayInsets();
        canvas_free = .{
            .area = area,
            .free = .{ .x = area.x + ins.left * ns, .y = area.y, .w = @max(1, area.w - (ins.left + ins.right) * ns), .h = @max(1, area.h - ins.bottom * ns) },
            .rw = rw,
        };
    }
    if (state.view.fit) |b| {
        state.view.ppm = fitPpm(b);
        centreOn(.{ .x = (b.x0 + b.x1) / 2, .y = (b.y0 + b.y1) / 2 });
    }
    if (view == canvas_owner) if (reveal_pending) |b| {
        reveal_pending = null;
        revealNow(b, area);
    };
    // Drawn last, over everything.
    defer drawRulers(area);
    const clip = dvui.clip(area);
    defer dvui.clipSet(clip);

    // With a panel or the canvas as the context, typed text makes a
    // label, at the flow cursor it goes into the flow, and in an equation
    // or a tile's text edited on the canvas, into that: ask for text
    // input, which the backend sends only on request.
    if (active and ((state.context == .panel and track_cursor == null) or track_cursor != null or canvas_eq != null) and !canvas_prompt and cursorKeysReach()) {
        const ns_ = dvui.windowNaturalScale();
        dvui.wantTextInput(.{ .x = area.x / ns_, .y = area.y / ns_, .w = area.w / ns_, .h = area.h / ns_ });
    }
    // An inactive view only shows: a press in it makes it the active one.
    if (active) canvasEvents(box, area) else for (dvui.events()) |*e| {
        if (!dvui.eventMatchSimple(e, box.data())) continue;
        if (e.evt == .mouse and e.evt.mouse.action == .press) {
            e.handle(@src(), box.data());
            view_to_activate = view;
            dvui.refresh(null, @src(), box.data().id);
        }
    }
    const px = dvui.windowNaturalScale();
    if (open) {
        // An open canvas: drafting surface everywhere, and its axes
        // through the origin.
        area.fill(.square, .{ .color = .{ .color = colors.paper } });
    } else {
        // Work happens on the worksheet: the view's centre stays on the sheet.
        state.view.cx = std.math.clamp(state.view.cx, 0, sheet.w);
        state.view.cy = std.math.clamp(state.view.cy, 0, sheet.h);
        const sheet_rect = state.view.rect(area, sheet.box());
        sheet_rect.fill(.square, .{ .color = .{ .color = colors.paper } });
        // The grid across the whole canvas, desk and sheet alike.
        drawGrid(area);
        drawMargins(area, sheet);
        sheet_rect.stroke(.square, .{ .thickness = px, .color = .{ .color = colors.edge } });
    }

    // Re-flatten label outlines when the zoom has moved more than 2x.
    const tol = 0.2 / state.view.ppm;
    if (state.flat.tol == 0 or tol < state.flat.tol / 2 or tol > state.flat.tol * 2) state.flat.reset(tol);

    // An open canvas: the document's layers and the view's own (grid,
    // axes, check results, construction lines) in their stacking order;
    // then a frame's bound, over them.
    if (open) drawStack(area, shown_space, active) else {
        drawSpacePanels(area, null, null);
        drawChecks(area, null, null);
    }
    if (open) drawFrameBound(area);
    if (open) drawSketches(area);
    // What only the active view shows: modes and the pointer's marks.
    if (!active) {
        drawPicked(area);
        drawConstraintMarks(area);
        return;
    }
    if (sketch_edit != null) {
        drawSketchMode(area);
        return;
    }
    if (panel_edit != null) {
        drawPanelEdit(area);
        return;
    }

    drawPicked(area);
    drawSelection(area);
    drawPolygonDraft(area);
    drawTrackPath(area);
    drawConstraintMarks(area);
    drawPointerMark();
    drawConstructionPreview(area);
    drawHover(area);
    drawEngagement(area);
    drawSnapGuides(area);

    // Tracks being drawn out: the region they snap to, divided into them,
    // and their count and length.
    if (state.drag) |d| if (state.tool == .add_tracks) {
        if (planTracks(d.start, d.at)) |plan| drawTrackPlan(area, plan);
    } else if (state.tool == .add_array) {
        if (array_tool.polar) drawPolarPlan(area, d.start, d.at) else drawArrayPlan(area, dragBox(d.start, d.at));
    } else if (state.tool == .insert_figure) {
        drawInsertPreview(area, d.start, d.at);
    } else {
        const r = state.view.rect(area, dragBox(d.start, d.at));
        r.fill(.square, .{ .color = .{ .color = colors.select.opacity(0.12) } });
        r.stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } });
    };
    if (state.tool == .add_panel and state.model.panels.items.len == 0 and state.drag == null) {
        dvui.labelNoFmt(@src(), "Drag out the new panel on the sheet. Esc cancels.", .{}, .{
            .gravity_x = 0.5,
            .gravity_y = 0.05,
            .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.6) },
        });
    }
}

/// The margins as translucent bands inside the sheet's edge, and the ink
/// area's boundary as a thin line.
fn drawMargins(area: dvui.Rect.Physical, sheet: layout.model.Sheet) void {
    const px = dvui.windowNaturalScale();
    const s = sheet.box();
    const ink = sheet.inkArea();
    const band: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.10) };
    for ([_]geom.Box{
        .{ .x0 = s.x0, .y0 = s.y0, .x1 = ink.x0, .y1 = s.y1 },
        .{ .x0 = ink.x1, .y0 = s.y0, .x1 = s.x1, .y1 = s.y1 },
        .{ .x0 = ink.x0, .y0 = ink.y1, .x1 = ink.x1, .y1 = s.y1 },
        .{ .x0 = ink.x0, .y0 = s.y0, .x1 = ink.x1, .y1 = ink.y0 },
    }) |b| {
        if (b.width() > 0 and b.height() > 0) state.view.rect(area, b).fill(.square, .{ .color = band });
    }
    state.view.rect(area, ink).stroke(.square, .{ .thickness = px, .color = .{ .color = colors.guide.opacity(0.7) } });
}

/// Panel `pi`'s compliance issue, if it has one.
fn panelIssue(pi: usize) ?layout.drc.PanelIssue {
    for (state.panel_issues) |i| if (i.panel == pi) return i;
    return null;
}

/// A panel's margins as a light translucent band inside its outline, and
/// its ink area's boundary as a thin line.
fn drawPanelMargins(area: dvui.Rect.Physical, pi: usize) void {
    const px = dvui.windowNaturalScale();
    const p = state.model.panels.items[pi];
    const b = panelBox(pi);
    const ink = p.margins.inset(b);
    const band: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.07) };
    for ([_]geom.Box{
        .{ .x0 = b.x0, .y0 = b.y0, .x1 = ink.x0, .y1 = b.y1 },
        .{ .x0 = ink.x1, .y0 = b.y0, .x1 = b.x1, .y1 = b.y1 },
        .{ .x0 = ink.x0, .y0 = ink.y1, .x1 = ink.x1, .y1 = b.y1 },
        .{ .x0 = ink.x0, .y0 = b.y0, .x1 = ink.x1, .y1 = ink.y0 },
    }) |r| {
        if (r.width() > 0 and r.height() > 0) state.view.rect(area, r).fill(.square, .{ .color = band });
    }
    if (ink.width() > 0 and ink.height() > 0) state.view.rect(area, ink).stroke(.square, .{ .thickness = px, .color = .{ .color = colors.guide.opacity(0.45) } });
}

fn inMargin(pi: Parent, tile: ?TileId, slot: usize, run_region: ?usize) bool {
    for (state.intrusions) |i| if (i.parent.eql(pi) and i.tile == tile and i.slot == slot and i.run_region == run_region) return true;
    return false;
}

/// The style for text put in a track that has none: "Label", 3 mm cap
/// height in the legend font, made the first time it is needed.
fn labelStyle() !layout.model.StyleId {
    return labelStyleIn(null);
}

/// As `labelStyle`, making the style (when it has to) as part of the step
/// merged under `key`.
fn labelStyleIn(key: ?u64) !layout.model.StyleId {
    if (state.label_style) |s| return s;
    const s = if (key) |k| try actM(k, .addStyle, .{ "Label", .{ .cap_height = 3 } }) else try act(.addStyle, .{ "Label", .{ .cap_height = 3 } });
    state.label_style = s;
    return s;
}

/// A frame's properties: its name, its boundary (fitted to what it holds),
/// and what it holds.
fn frameProperties(space: usize) !void {
    const saved_group = pushGroup("frame");
    defer popGroup(saved_group);
    const sp = state.model.spaces.items[space];
    propText("Name", "{s}", .{sp.name}, 1);
    if (sp.bound) |b| propText("Boundary", "{d:.1} × {d:.1} mm", .{ b.width(), b.height() }, 2) else propText("Boundary", "{s}", .{"none yet"}, 2);
    propText("Groups", "{d}", .{sp.groups.items.len}, 3);
    var panels: usize = 0;
    for (state.model.panels.items) |p| {
        if (p.space == spaceId(space)) panels += 1;
    }
    propText("Panels", "{d}", .{panels}, 4);
    keyButton(@src(), "Fit frame to its contents", 0, .{ .margin = .{ .y = 8 } });
    layersList(space);
    placeViewButtons(space);
}

/// A group's properties: what it holds, and how to move or dissolve it.
fn groupProperties(id: layout.model.ObjectId) !void {
    const saved_group = pushGroup("group");
    defer popGroup(saved_group);
    const g = state.model.group(id) orelse return;
    propText("Name", "{s}", .{g.name}, 1);
    propText("Members", "{d}", .{g.members.items.len}, 2);
    if (state.model.parentGroup(id)) |p| if (state.model.group(p)) |pg| propText("In group", "{s}", .{pg.name}, 3);
    propText("Moves", "{s}", .{"arrow keys, 1 mm, all together"}, 4);
    keyButton(@src(), "Ungroup", 0, .{ .margin = .{ .y = 8 } });
}

/// Objects picked with Select area: how many, and what can be done with
/// them: group them in place, or move or copy them to another space.
fn selectionProperties() !void {
    const saved_group = pushGroup("selection");
    defer popGroup(saved_group);
    propText("Objects", "{d}", .{selection.items.len}, 1);
    if (selection.items.len == 0) return;
    if (selection.items.len == 1) propText("Object", "{s}", .{objectName(selection.items[0])}, 2);
    // Grouping and moving to a frame are for what is directly in a space.
    const in_space = for (selection.items) |id| {
        if (state.model.group(id) != null) continue;
        const parent = constrain.parentOf(&state.model, id) orelse break false;
        if (parent != .space) break false;
    } else true;
    if (!in_space) return;
    keyButton(@src(), "Group", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
    keyButton(@src(), "Move to a new frame", 0, .{ .expand = .horizontal });
    keyButton(@src(), "Copy to a new frame", 0, .{ .expand = .horizontal });
    for (state.model.spaces.items, 0..) |sp, si| {
        if (si == shown_space or sp.home != .none) continue;
        var buf: [96]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "Move to {s}", .{if (si == 0) "the canvas" else sp.name}) catch "Move";
        keyButton(@src(), text, @intCast(si), .{ .expand = .horizontal, .id_extra = si });
    }
}

/// Groups the selection where it is, and makes the group the context.
fn groupSelection() void {
    if (selection.items.len == 0) return;
    var nb: [32]u8 = undefined;
    var n: usize = 1;
    for (state.model.spaces.items) |sp| n += sp.groups.items.len;
    _ = &n;
    const name = state.model.freshName(&nb, .{ .space = state.model.spaces.items[shown_space].id }, "Group");
    const g = act(.makeGroup, .{selection.items, name}) catch {
        state.status = "They could not be grouped. ";
        return;
    };
    selection.clearRetainingCapacity();
    state.context = .{ .group = g };
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
}

/// Moves (or copies) the selection to space `dest` (a new frame, fitted
/// around it, when null), shows that space, and makes the group the
/// objects arrived as the context, so the next move places them all.
fn transferSelection(dest: ?usize, copy: bool) void {
    const items = selection.items;
    if (items.len == 0) return;
    const target = dest orelse blk: {
        var nb: [32]u8 = undefined;
        const name = state.model.nextFrameName(&nb, "Frame");
        const e = selectionExtents();
        const margin = 10.0;
        const edge: ?geom.Box = if (e.isEmpty()) null else .{ .x0 = e.x0 - margin, .y0 = e.y0 - margin, .x1 = e.x1 + margin, .y1 = e.y1 + margin };
        const f = act(.addFrame, .{name, edge}) catch return;
        state.model.spaces.items[f].default_name = true;
        break :blk f;
    };
    const constraints_before = state.model.constraints.items.len;
    var group_size: usize = 0;
    for (items) |id| group_size += idLeafCount(id);
    const g = (if (copy) act(.copyToSpace, .{items, target}) else act(.moveToSpace, .{items, target})) catch {
        state.status = "They could not be moved there. ";
        return;
    };
    var arrived_size: usize = 0;
    if (state.model.findGroup(g)) |at| for (state.model.spaces.items[at.space].groups.items[at.index].members.items) |id| {
        arrived_size += idLeafCount(id);
    };
    const dropped = if (copy) 0 else constraints_before -| state.model.constraints.items.len;
    selection.clearRetainingCapacity();
    track_cursor = null;
    shown_space = target;
    state.context = .{ .group = g };
    // The keyboard goes to the canvas, for the arrow keys.
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
    const brought = arrived_size -| group_size;
    state.status = std.fmt.bufPrint(&transfer_status_buf, "Arrived as one group{s}{s}: arrow keys move it into place.{s} ", .{
        if (brought > 0) ", with what is constrained to it" else "",
        if (brought > 0) (std.fmt.bufPrint(&transfer_brought_buf, " ({d} more)", .{brought}) catch "") else "",
        if (dropped > 0) (std.fmt.bufPrint(&transfer_dropped_buf, " {d} constraint{s} on what stayed behind dropped (undo brings them back).", .{ dropped, if (dropped == 1) "" else "s" }) catch "") else "",
    }) catch "Arrived as one group. ";
}

var transfer_status_buf: [256]u8 = undefined;
var transfer_brought_buf: [32]u8 = undefined;
var transfer_dropped_buf: [96]u8 = undefined;

/// How many objects `id` is: 1, or a group's, nested.
fn idLeafCount(id: layout.model.ObjectId) usize {
    if (state.model.findGroup(id)) |at| {
        var n: usize = 0;
        for (state.model.spaces.items[at.space].groups.items[at.index].members.items) |mb| n += idLeafCount(mb);
        return n;
    }
    return 1;
}

/// The selection's extents in its space, from the last solve.
fn selectionExtents() geom.Box {
    var b: geom.Box = .empty;
    for (selection.items) |id| b = b.join(idBox(id));
    return b;
}

/// An object's or a group's extents in its space, from the last solve.
fn idBox(id: layout.model.ObjectId) geom.Box {
    if (state.model.group(id)) |g| {
        var b: geom.Box = .empty;
        for (g.members.items) |mb| b = b.join(idBox(mb));
        return b;
    }
    const loc = state.model.locate(id) orelse return .empty;
    return memberBox(loc);
}

/// A member's extents in its space: a panel's outline, line art's shapes,
/// a track's segments.
fn memberBox(mb: layout.model.Member) geom.Box {
    switch (mb) {
        .panel => |pi| return state.model.panels.items[pi].box(),
        .art => |l| return onSheet(.{ .panel = l.panel }, state.model.panels.items[l.panel].art.items[l.index].box()),
        .region => |l| {
            var b: geom.Box = .empty;
            if (placedOf(l.parent)) |pl| for (pl.tracks) |t| {
                if (t.region == l.index) b = b.join(onSheet(l.parent, t.box));
            };
            return b;
        },
    }
}

/// Select area: what lies wholly inside box `b` in the shown space. A
/// grouped object is picked only with its whole outermost group.
fn selectArea(b: geom.Box) void {
    defer state.tool = .select;
    selection.clearRetainingCapacity();
    var inside: std.ArrayList(layout.model.ObjectId) = .empty;
    defer inside.deinit(state.gpa);
    for (state.model.panels.items, 0..) |p, pi| {
        if (!shownPanel(pi)) continue;
        if (layout.model.within(p.box(), b)) inside.append(state.gpa, p.id) catch {};
    }
    // The content layouts set straight on the shown workspace.
    if (shownParent()) |sp| for (0..state.model.regionsIn(sp).len) |i| {
        const loc: layout.model.Member = .{ .region = .{ .parent = sp, .index = i } };
        const mb = memberBox(loc);
        if (!mb.isEmpty() and layout.model.within(mb, b)) inside.append(state.gpa, state.model.idAt(loc)) catch {};
    };
    for (inside.items) |id| {
        const top = state.model.topLevel(id);
        if (std.mem.indexOfScalar(layout.model.ObjectId, selection.items, top) != null) continue;
        if (top != id and !layout.model.within(idBox(top), b)) continue;
        selection.append(state.gpa, top) catch {};
    }
    state.context = if (selection.items.len > 0) .selection else if (shownParent() != null) .{ .space = shown_space } else .worksheet;
    track_cursor = null;
    if (selection.items.len == 0) state.status = "Nothing lies wholly inside that area. ";
}

/// The outermost group holding what context `c` names, if it is grouped.
fn groupOf(c: Context) ?layout.model.ObjectId {
    const loc: layout.model.Member = switch (c) {
        .panel => |pi| .{ .panel = pi },
        .art => |l| .{ .art = .{ .panel = l.panel, .index = l.index } },
        .region => |r| .{ .region = .{ .parent = r.parent, .index = r.region } },
        else => return null,
    };
    const id = state.model.idAt(loc);
    const top = state.model.topLevel(id);
    return if (top == id) null else top;
}

/// Moves the selected group 1 mm the way an arrow points.
fn moveGroupKey(code: dvui.enums.Key) bool {
    const g = switch (state.context) {
        .group => |g| g,
        else => return false,
    };
    const d: geom.Point = switch (code) {
        .up => .{ .x = 0, .y = nudge_mm },
        .down => .{ .x = 0, .y = -nudge_mm },
        .left => .{ .x = -nudge_mm, .y = 0 },
        .right => .{ .x = nudge_mm, .y = 0 },
        else => return false,
    };
    actM(mergeKey(.{ "moveGroupKey", state.context }), .moveGroup, .{g, d.x, d.y}) catch return false;
    return true;
}

/// Outlines what the selection or the selected group holds.
fn drawPicked(area: dvui.Rect.Physical) void {
    const px = dvui.windowNaturalScale();
    const focus = colors.select;
    switch (state.context) {
        // Drawn whatever the context (see drawSelection).
        .selection => {},
        .group => |g| {
            const grp = state.model.group(g) orelse return;
            for (grp.members.items) |mb| {
                const b = idBox(mb);
                if (!b.isEmpty()) state.view.rect(area, b).stroke(.square, .{ .thickness = px, .color = .{ .color = focus.opacity(0.6) } });
            }
            const all = idBox(g);
            if (!all.isEmpty()) marchingBox(area, .{ .x0 = all.x0 - 2, .y0 = all.y0 - 2, .x1 = all.x1 + 2, .y1 = all.y1 + 2 }, focus, 1.5 * px);
        },
        else => {},
    }
}

/// The canvas's properties: its units (a conversion: nothing moves), and
/// what it holds.
fn canvasProperties() !void {
    const saved_group = pushGroup("canvas");
    defer popGroup(saved_group);
    const sp = state.model.spaces.items[0];
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 1 });
        defer row.deinit();
        propName("Units");
        const names = [_][]const u8{ "Millimetres", "Inches", "Mils" };
        var choice: usize = @intFromEnum(state.model.units);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 1 })) actV(.setCanvasUnits, .{@enumFromInt(choice)});
    }
    propText("Tracks", "{d}", .{sp.regions.items.len}, 3);
    var on_canvas: usize = 0;
    for (state.model.panels.items) |p| {
        if (p.space == spaceId(0)) on_canvas += 1;
    }
    propText("Panels", "{d}", .{on_canvas}, 5);
    {
        var buf: [96]u8 = undefined;
        var tb: [16]u8 = undefined;
        const lang = if (languages.len > 0) languages[0].tag(&tb) else "not given";
        propText("Language", "{s}", .{std.fmt.bufPrint(&buf, "{s}{s}", .{ lang, if (languages.len > 1) " and others" else "" }) catch lang}, 8);
        const from = switch (measurement_source) {
            .config => "your settings",
            .system => "the system",
            .country => "your language's country",
            .default => "no locale given",
        };
        propText("Measures", "{s}, from {s}", .{ @tagName(measurement), from }, 9);
    }
    try propFont("Legend font", 7);
    layersList(0);
    placeViewButtons(0);
}

/// Makes line art from a finished drag: the chosen shape filling the box
/// (a circle in its shorter side), on its panel, made the context.
fn addArtFromDrag(b: geom.Box) void {
    defer state.tool = .select;
    const pi = switch (state.context) {
        .panel => |pi| pi,
        else => return,
    };
    if (!(b.width() >= 1 and b.height() >= 1)) return;
    const prim: layout.art.Primitive = switch (shape_kind) {
        .rect => .{ .rect = .{ .w = b.width(), .h = b.height() } },
        .rounded => .{ .rounded = .{ .w = b.width(), .h = b.height(), .r = @min(3.0, @min(b.width(), b.height()) / 4) } },
        .circle => .{ .circle = @min(b.width(), b.height()) },
        .ellipse => .{ .ellipse = .{ .w = b.width(), .h = b.height() } },
        .slot => .{ .slot = .{ .w = b.width(), .h = b.height() } },
        .polygon => return,
    };
    addPrimitive(pi, prim, .{ .x = b.x0, .y = b.y0 });
}

/// Adds primitive `prim` as line art on panel `pi`, its box's corner at
/// worksheet point `at`, and makes it the context. Drawn as an outline:
/// these are paths to cut or to make panels from.
fn addPrimitive(pi: usize, prim: layout.art.Primitive, at: geom.Point) void {
    const o = state.model.panels.items[pi].origin;
    var name_buf: [48]u8 = undefined;
    var ib: [48]u8 = undefined;
    const name = state.model.freshName(&name_buf, .{ .panel = pi }, layout.names.identifier(&ib, prim.label(), "Shape"));
    const shapes = layout.art.primitive(dvui.currentWindow().arena(), name, prim, .{
        .edge = .{ .r = 0x2b, .g = 0x2b, .b = 0x2b },
        .edge_width = 0.25,
    }) catch return;
    // An outline lies over what is drawn inside it; a cutout keeps it away.
    const ai = act(.addArt, .{pi, .{ .name = name, .at = .{ .x = at.x - o.x, .y = at.y - o.y }, .shapes = shapes, .prim = prim, .wrap = .none }}) catch return;
    state.context = .{ .art = .{ .panel = pi, .index = ai } };
}

/// A click while drawing a polygon: a new corner, or, on the first
/// corner again, the polygon closed.
fn polygonClick(pi: usize, at: geom.Point) void {
    if (polygon_pts.items.len > 0 and polygon_panel != pi) polygon_pts.clearRetainingCapacity();
    polygon_panel = pi;
    if (polygon_pts.items.len >= 3) {
        const first = polygon_pts.items[0];
        const near = 6 / state.view.ppm;
        if (@abs(at.x - first.x) <= near and @abs(at.y - first.y) <= near) {
            finishPolygon();
            return;
        }
    }
    polygon_pts.append(state.gpa, at) catch {};
}

/// Closes the polygon being drawn (three corners at least) as line art.
fn finishPolygon() void {
    defer polygon_pts.clearRetainingCapacity();
    if (polygon_pts.items.len < 3) {
        state.status = "A polygon needs three corners at least. ";
        return;
    }
    var box: geom.Box = .empty;
    for (polygon_pts.items) |q| box = box.join(.{ .x0 = q.x, .y0 = q.y, .x1 = q.x, .y1 = q.y });
    const pts = dvui.currentWindow().arena().alloc(geom.Point, polygon_pts.items.len) catch return;
    for (polygon_pts.items, pts) |q, *r| r.* = .{ .x = q.x - box.x0, .y = q.y - box.y0 };
    state.tool = .select;
    addPrimitive(polygon_panel, .{ .polygon = pts }, .{ .x = box.x0, .y = box.y0 });
}

/// The polygon being drawn: its corners joined, and on to the pointer.
fn drawPolygonDraft(area: dvui.Rect.Physical) void {
    if (state.tool != .add_art or shape_kind != .polygon or polygon_pts.items.len == 0) return;
    const px = dvui.windowNaturalScale();
    const focus = colors.select;
    const n = polygon_pts.items.len + @as(usize, if (state.mouse != null) 1 else 0);
    const pts = dvui.currentWindow().arena().alloc(dvui.Point.Physical, n) catch return;
    for (polygon_pts.items, 0..) |q, i| pts[i] = state.view.toPx(area, q);
    if (state.mouse) |m| pts[n - 1] = state.view.toPx(area, m);
    if (pts.len >= 2) dvui.Path.stroke(.{ .points = pts }, .{ .thickness = 1.5 * px, .color = .{ .color = focus } });
    for (polygon_pts.items) |q| {
        const c = state.view.toPx(area, q);
        const r: dvui.Rect.Physical = .{ .x = c.x - 3 * px, .y = c.y - 3 * px, .w = 6 * px, .h = 6 * px };
        r.fill(.square, .{ .color = .{ .color = focus } });
    }
}

/// Moves the selected line art 1 mm the way an arrow points.
fn moveArtKey(code: dvui.enums.Key) bool {
    const l = switch (state.context) {
        .art => |l| l,
        else => return false,
    };
    const d: geom.Point = switch (code) {
        .up => .{ .x = 0, .y = nudge_mm },
        .down => .{ .x = 0, .y = -nudge_mm },
        .left => .{ .x = -nudge_mm, .y = 0 },
        .right => .{ .x = nudge_mm, .y = 0 },
        else => return false,
    };
    const at = state.model.panels.items[l.panel].art.items[l.index].at;
    actM(mergeKey(.{ "moveArtKey", state.context }), .moveArt, .{l.panel, l.index, .{ .x = at.x + d.x, .y = at.y + d.y }}) catch return false;
    return true;
}

/// Line art's properties: where it is, and how tracks under it flow.
fn artProperties(pi: usize, index: usize) !void {
    const saved_group = pushGroup("art");
    defer popGroup(saved_group);
    const pa = state.model.panels.items[pi].art.items[index];
    propText("Name", "{s}", .{pa.name}, 1);
    // A figure's placement: its figure, and its width (its height follows).
    if (pa.figure != .none) {
        const fname = if (state.model.figureIndex(pa.figure)) |fi| state.model.figures.items[fi].name else "(removed)";
        propText("Figure", "{s}", .{fname}, 20);
        var wb: [32]u8 = undefined;
        if (sizesProp("Width, mm", std.fmt.bufPrint(&wb, "{d:.2}", .{pa.box().width()}) catch "", 21)) |list| if (list.len == 1) {
            act(.setFigureArtWidth, .{ pi, index, list[0] }) catch {
                state.status = "A width must be more than 0. ";
            };
        };
        keyButton(@src(), "Show figure", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        borderProps(pa.id, pa.border, 22);
    }
    const b = pa.box();
    propText("Box", "({d:.1}, {d:.1}) to ({d:.1}, {d:.1}) mm", .{ b.x0, b.y0, b.x1, b.y1 }, 2);
    propText("Moves", "{s}", .{"arrow keys, 1 mm"}, 3);
    var wrap = pa.wrap;
    var clearance = pa.clearance;
    var changed = false;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 4 });
        defer row.deinit();
        propName("Tracks under it");
        const names = [_][]const u8{ "Run straight under", "Flow around its box", "Flow around its ink" };
        // (What flows: the tracks' tiles and runs, unless tiles stay under
        // it below.)
        var choice: usize = @intFromEnum(wrap);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 4 })) {
            wrap = @enumFromInt(choice);
            changed = true;
        }
    }
    var buf: [32]u8 = undefined;
    if (sizesProp("Clearance, mm", if (clearance > 0) std.fmt.bufPrint(&buf, "{d}", .{clearance}) catch "" else "any", 5)) |list| if (list.len <= 1) {
        clearance = if (list.len == 1) list[0] else 0;
        changed = true;
    };
    if (changed) try act(.setArtWrap, .{pi, index, wrap, clearance});
    {
        // Off, tracks lie under it (a mark printed over keys): their tiles
        // stay, and only runs on them wrap around it.
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 6 });
        defer row.deinit();
        propName("Tiles");
        var on = pa.wrap_tracks;
        if (tcheckbox(@src(), &on, "Move out from under it", .{ .id_extra = 6 })) try act(.setArtWrapsTracks, .{pi, index, on});
    }
    try shapeProperties(pi, index);
}

/// Line art's shape: what it was drawn as, a rounded rectangle's corner
/// radius, whether it is a cutout.
fn shapeProperties(pi: usize, index: usize) !void {
    const saved_group = pushGroup("art.shape");
    defer popGroup(saved_group);
    const pa = state.model.panels.items[pi].art.items[index];
    propText("Shape", "{s}", .{pa.prim.label()}, 10);
    switch (pa.prim) {
        .rounded => |r| {
            var buf: [32]u8 = undefined;
            if (sizesProp("Corner radius, mm", std.fmt.bufPrint(&buf, "{d}", .{r.r}) catch "", 11)) |list| if (list.len == 1) {
                act(.setArtCorner, .{pi, index, list[0]}) catch {
                    state.status = "That radius could not be used. ";
                };
            };
        },
        .circle => |d| propText("Diameter", "{d:.2} mm", .{d}, 11),
        else => {},
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 12 });
        defer row.deinit();
        propName("Cutout");
        var on = pa.cutout;
        if (tcheckbox(@src(), &on, "Cut through the panel", .{ .id_extra = 12 })) try act(.setArtCutout, .{pi, index, on});
    }
}

/// Tiles and legends of panel `pi`, moved onto the worksheet.
fn drawPanel(area: dvui.Rect.Physical, pi: Parent, placed: *const layout.place.Placed) void {
    const px = dvui.windowNaturalScale();
    const radius: f32 = @floatCast(1.0 * state.view.ppm);
    const o = parentOrigin(pi);
    // While text is typed, the scaffolding steps back (the owner,
    // 2026-11-23): each content layout is a soft band around where its
    // content may go, with no outlines; holding Ctrl shows them again.
    const quiet = quietText();
    // Every track's band, faintly, so empty tracks show where tiles go.
    for (placed.tracks) |t| {
        if (quiet) break;
        // Past the panel's edge: in the warning colour.
        const outside = for (placed.issues) |i| {
            if (i.kind == .region_outside and i.region == t.region) break true;
        } else false;
        // Past its track's soft area: in the warning colour, lighter.
        const past_soft = for (placed.issues) |i| {
            if (i.kind == .past_soft_area and i.region == t.region and i.row == t.track) break true;
        } else false;
        const colour = if (outside) colors.overflow else if (past_soft) colors.overflow.opacity(0.5) else colors.guide.opacity(0.35);
        state.view.rect(area, onSheet(pi, t.box)).stroke(.square, .{ .thickness = if (outside) 1.5 * px else px, .color = .{ .color = colour } });
    }
    // Every track's full extent, which its rows or columns expand into,
    // as a thin outline (a segment's length centred on its path, as far
    // across as the space it was drawn out for): faint, and stronger for
    // the context's track.
    const soft_region: ?usize = switch (state.context) {
        .region => |r| if (r.parent.eql(pi)) r.region else null,
        .row => |r| if (placedTrack(r.parent, r.region, r.row)) |pt| (if (pt.parent.eql(pi)) pt.member else null) else (if (r.parent.eql(pi)) r.region else null),
        else => null,
    };
    for (0..state.model.regionsIn(pi).len) |ri| {
        const on = soft_region != null and soft_region.? == ri;
        if (quiet) {
            contentBand(area, pi, ri, on);
            continue;
        }
        guideOutline(area, trackOutline(pi, ri), colors.guide.opacity(if (on) 0.6 else 0.3), px);
    }
    // Flow marks are a view layer of their own; a document without spaces
    // (no layer stack) draws them with its panels.
    if (state.model.spaces.items.len == 0) drawThreads(area, pi, placed);
    drawGrids(area, pi);
    for (placed.tiles) |t| {
        const in_context = inContext(pi, t);
        // Bound to a grid: a hole is outlined in the panel's edge colour;
        // a legend's box shows faintly while editing (its label is drawn
        // with the others).
        if (t.grid) |role| if (role != .part) {
            const sel = in_context and state.context == .tile;
            if (role == .hole) {
                // Drawn as part of the panel's body; its own outline only
                // while it is in context (or when there is no body).
                if (in_context or placed.body == null) {
                    const pieces = flatTile(&state.flat, t.shapes) catch &.{};
                    for (pieces) |piece| for (piece.lines) |line| strokeLoop(area, line, o, 1.5 * px, if (in_context) colors.select else colors.panel_edge);
                }
            } else {
                guideBox(area, onSheet(pi, t.pitch_box), if (in_context) colors.select else colors.guide.opacity(0.35), px);
            }
            if (sel) marchingBox(area, onSheet(pi, t.pitch_box), colors.select, 1.5 * px);
            continue;
        };
        // A blank (a spacer tile): a faint outline while editing, nothing in
        // output.
        if (t.spacer) {
            const box = state.view.rect(area, onSheet(pi, t.pitch_box));
            const sel = in_context and state.context == .tile;
            box.stroke(.square, .{ .thickness = (if (sel) @as(f32, 2) else 1) * px, .color = .{ .color = if (sel) colors.select else colors.guide.opacity(0.3) } });
            continue;
        }
        const flagged = tileFlag(placed, t.id);
        const body = state.view.rect(area, onSheet(pi, t.body));
        const face = state.view.rect(area, onSheet(pi, t.face));
        // The tile's art, as placement stretched it: fills, then edges.
        const pieces = flatTile(&state.flat, t.shapes) catch &.{};
        for (pieces) |piece| {
            if (piece.shape.paint.fill != .none) fillRegion(area, piece.region, o, .{ .art = piece.shape.paint.fill });
            const edge = piece.shape.paint.edge orelse continue;
            const width: f32 = @max(px, @as(f32, @floatCast(piece.shape.paint.edge_width * state.view.ppm)));
            for (piece.lines) |line| strokeLoop(area, line, o, width, docColor(.{ .r = edge.r, .g = edge.g, .b = edge.b, .a = edge.a }));
        }
        if (flagged.missing) face.fill(.round(radius), .{ .color = .{ .color = colors.missing } });
        if (flagged.overflow) face.stroke(.round(radius), .{ .thickness = 1.5 * px, .color = .{ .color = colors.overflow } });
        // A size its prototype does not allow: the body outlined in warning.
        if (flagged.size and !in_context) body.stroke(.round(radius), .{ .thickness = 1.5 * px, .color = .{ .color = colors.overflow } });
        if (in_context) {
            const w = (if (state.context == .tile) @as(f32, 3) else 2) * px;
            glowRect(body, radius, w, colors.select);
            body.stroke(.round(radius), .{ .thickness = w, .color = .{ .color = colors.select } });
        }
        if (in_context and state.context == .tile) drawTileTracks(area, pi, t);
    }
    // Line art, over the tracks; the selected piece outlined.
    for (placed.art) |pa| {
        const pieces = flatTile(&state.flat, pa.shapes) catch &.{};
        if (pa.cutout) {
            // A hole: part of the panel's body, which draws it; on a
            // canvas (no body), its outline, a little heavier than line art.
            if (placed.body == null) for (pieces) |piece| for (piece.lines) |line| strokeLoop(area, line, o, 1.5 * px, colors.panel_edge);
        } else for (pieces) |piece| {
            if (piece.shape.paint.fill != .none) fillRegion(area, piece.region, o, .{ .art = piece.shape.paint.fill });
            const edge = piece.shape.paint.edge orelse continue;
            const width: f32 = @max(px, @as(f32, @floatCast(piece.shape.paint.edge_width * state.view.ppm)));
            for (piece.lines) |line| strokeLoop(area, line, o, width, docColor(.{ .r = edge.r, .g = edge.g, .b = edge.b, .a = edge.a }));
        }
        const sel = switch (state.context) {
            .art => |l| pi.eql(.{ .panel = l.panel }) and l.index == pa.index,
            else => false,
        };
        if (sel) marchingBox(area, onSheet(pi, pa.box), colors.select, 1.5 * px);
    }
    const lifo = dvui.currentWindow().lifo();
    for (placed.labels) |l| {
        // Ink in the sheet's margins is drawn in the warning colour.
        const ink = if (inMargin(pi, l.tile, l.slot, if (l.run) |r| r.region else null)) colors.overflow else colors.ink;
        const at: geom.Point = .{ .x = l.origin.x + o.x, .y = l.origin.y + o.y };
        // Glyphs from the atlas, rules and marks from their outlines;
        // exact outlines throughout when construction is shown or a glyph
        // is too large to raster.
        if (dump_path != null) for (l.render.items) |item| switch (item) {
            .glyph => |g| if (g.face < faceTable().len) dumpGlyph(area, faceTable()[g.face], g, at),
            .path => {},
        };
        const from_atlas = !show_construction and !exact_text and drawLabelGlyphs(area, l.render, at, ink);
        const pieces = state.flat.getWith(l.render, faceTable(), from_atlas) catch continue;
        for (pieces) |piece| {
            const color: dvui.Color = switch (piece.kind) {
                .ink => ink,
                .faint => ink.opacity(0.35),
                .placeholder => colors.select.opacity(0.7),
            };
            if (show_construction and piece.kind == .ink) {
                // Outlines over a translucent fill, so the lines show through.
                fillRegion(area, piece.region, at, .{ .flat = color.opacity(0.18) });
                for (piece.region.loops) |loop| {
                    const pts = lifo.alloc(dvui.Point.Physical, loop.len) catch break;
                    defer lifo.free(pts);
                    for (loop, pts) |q, *out| out.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
                    dvui.Path.stroke(.{ .points = pts }, .{ .thickness = px, .color = .{ .color = color }, .closed = true });
                }
            } else {
                fillRegion(area, piece.region, at, .{ .flat = color });
            }
        }
        if (show_construction) drawConstruction(area, l, o);
        drawCanvasEq(area, pi, l, o);
        if (caretIn(pi, l)) |c| {
            const x = l.origin.x + o.x + c.x;
            const y = l.origin.y + o.y;
            const a = state.view.toPx(area, .{ .x = x, .y = y + c.y0 });
            const b = state.view.toPx(area, .{ .x = x, .y = y + c.y1 });
            dvui.Path.stroke(.{ .points = &.{ a, b } }, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } });
        }
    }
    if (state.model.spaces.items.len == 0) drawFlowMarks(area, pi, placed);
    // On whichever panel its segment lies: a thread runs across panels.
    if (track_cursor) |c| if (canvas_eq == null) drawCursor(area, pi, placed, c);
}

/// Draws the glyphs of render `r`, placed at worksheet point `at`, from the
/// glyph atlas. False (nothing drawn) when one is too large to raster, so
/// the caller draws the label from its outlines.
fn drawLabelGlyphs(area: dvui.Rect.Physical, r: *const layout.Render, at: geom.Point, ink: dvui.Color) bool {
    const faces = faceTable();
    const lifo = dvui.currentWindow().lifo();
    const ga = glyphAtlas();
    var quads: std.ArrayList(glyphs.Quad) = .empty;
    defer quads.deinit(lifo);
    const ppm: f64 = state.view.ppm;
    const Map = struct {
        m: geom.Affine,
        at: geom.Point,
        area: dvui.Rect.Physical,
        pub fn map(self: @This(), q: geom.Point) dvui.Point.Physical {
            const p = self.m.apply(q);
            return state.view.toPx(self.area, .{ .x = p.x + self.at.x, .y = p.y + self.at.y });
        }
    };
    for (r.items) |item| {
        const g = switch (item) {
            .glyph => |g| g,
            .path => continue,
        };
        if (g.face >= faces.len) return false;
        const face = faces[g.face];
        const m = g.transform;
        // mm per font unit (the transform's scale, rotation aside).
        const mm = @sqrt(@abs(m.a * m.d - m.b * m.c));
        if (!(mm > 0)) continue;
        const map: Map = .{ .m = m, .at = at, .area = area };
        // Off the canvas: nothing to draw, and no field or raster made for it.
        {
            const ob = (face.outline(g.gid) catch return false).bounds();
            if (ob.isEmpty()) continue;
            var lo: dvui.Point.Physical = .{ .x = std.math.inf(f32), .y = std.math.inf(f32) };
            var hi: dvui.Point.Physical = .{ .x = -std.math.inf(f32), .y = -std.math.inf(f32) };
            const pad = g.grow / mm;
            for ([_]geom.Point{ .{ .x = ob.x0 - pad, .y = ob.y0 - pad }, .{ .x = ob.x1 + pad, .y = ob.y0 - pad }, .{ .x = ob.x1 + pad, .y = ob.y1 + pad }, .{ .x = ob.x0 - pad, .y = ob.y1 + pad } }) |c| {
                const q = map.map(c);
                lo = .{ .x = @min(lo.x, q.x), .y = @min(lo.y, q.y) };
                hi = .{ .x = @max(hi.x, q.x), .y = @max(hi.y, q.y) };
            }
            if (hi.x < area.x - 2 or lo.x > area.x + area.w + 2 or hi.y < area.y - 2 or lo.y > area.y + area.h + 2) continue;
        }
        // Upright (no rotation, mirror or slant): on the pixel grid.
        const upright = m.b == 0 and m.c == 0 and m.a > 0 and m.d > 0;
        const color: dvui.Color.PMA = .fromColor(if (g.faint) ink.opacity(0.35) else ink);
        if (upright) {
            const o0 = map.map(.{ .x = 0, .y = 0 });
            // The origin's pixel, its horizontal phase in quarters, the
            // baseline on the nearest pixel row.
            const fx = @floor(o0.x);
            var phase: f32 = @round((o0.x - fx) * 4);
            var px = fx;
            if (phase >= 4) {
                phase = 0;
                px += 1;
            }
            const py = @round(o0.y);
            if (ga.alignedSlot(face, g.gid, mm * ppm, g.grow / mm, @intFromFloat(phase)) catch return false) |sl| {
                quads.append(lifo, glyphs.alignedQuad(sl, px, py, color)) catch return false;
                continue;
            }
        } else if (ga.slot(face, g.gid, mm * ppm, g.grow / mm) catch return false) |sl| {
            quads.append(lifo, glyphs.quad(sl, map, color)) catch return false;
            continue;
        }
        // Blank, or too large: only the latter needs outlines.
        const o = face.outline(g.gid) catch return false;
        if (o.contours.len == 0) continue;
        return false;
    }
    glyphs.drawQuads(ga, lifo, quads.items);
    return true;
}

/// Fills a resolved region placed at worksheet point `at`: its triangles as
/// they are, then a band one pixel wide fading out past each loop, for
/// antialiasing.
fn fillRegion(area: dvui.Rect.Physical, region: geom.fill.Region, at: geom.Point, paint: Paint) void {
    const lifo = dvui.currentWindow().lifo();
    const Index = dvui.Vertex.Index;
    // Vertex indices may be 16-bit: the triangles go in batches.
    const batch = 20000;
    var from: usize = 0;
    while (from < region.triangles.len) : (from += batch) {
        const tris = region.triangles[from..@min(from + batch, region.triangles.len)];
        var b = dvui.Triangles.Builder.init(lifo, 3 * tris.len, 3 * tris.len) catch return;
        defer b.deinit(lifo);
        for (tris, 0..) |t, k| {
            var v: [3]dvui.Point.Physical = undefined;
            for (t, &v) |q, *out| out.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
            for (v, t) |pos, q| b.appendVertex(.{ .pos = pos, .col = paint.at(q) });
            const i: Index = @intCast(3 * k);
            b.appendTriangles(&ccw(v[0], v[1], v[2], i, i + 1, i + 2));
        }
        dvui.renderTriangles(b.build_unowned(), null) catch {};
    }
    for (region.loops) |loop| {
        if (loop.len < 3 or loop.len > 30000) continue;
        const n = loop.len;
        var b = dvui.Triangles.Builder.init(lifo, 2 * n, 6 * n) catch return;
        defer b.deinit(lifo);
        const pts = lifo.alloc(dvui.Point.Physical, n) catch return;
        defer lifo.free(pts);
        for (loop, pts) |q, *out| out.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
        for (pts, 0..) |p, i| {
            // Loops keep the filled side on their left, so outward is to
            // the right of each edge.
            const out_in = outward(pts[(i + n - 1) % n], p);
            const out_next = outward(p, pts[(i + 1) % n]);
            var nx = (out_in.x + out_next.x) / 2;
            var ny = (out_in.y + out_next.y) / 2;
            // Mitred, within reason.
            const d2 = nx * nx + ny * ny;
            if (d2 > 1e-6) {
                nx /= d2;
                ny /= d2;
            }
            const len = @sqrt(nx * nx + ny * ny);
            if (len > 2) {
                nx *= 2 / len;
                ny *= 2 / len;
            }
            b.appendVertex(.{ .pos = p, .col = paint.at(loop[i]) });
            b.appendVertex(.{ .pos = .{ .x = p.x + nx, .y = p.y + ny }, .col = .transparent });
        }
        for (0..n) |i| {
            const j = (i + 1) % n;
            const ii: Index = @intCast(2 * i);
            const jj: Index = @intCast(2 * j);
            const v = b.vertexes.items;
            b.appendTriangles(&ccw(v[ii].pos, v[ii + 1].pos, v[jj].pos, ii, ii + 1, jj));
            b.appendTriangles(&ccw(v[ii + 1].pos, v[jj + 1].pos, v[jj].pos, ii + 1, jj + 1, jj));
        }
        dvui.renderTriangles(b.build_unowned(), null) catch {};
    }
}

/// What fills a region: one colour, or a tile art fill, whose gradient is
/// in the region's own frame (before `at` moves it).
const Paint = union(enum) {
    flat: dvui.Color,
    art: layout.art.Fill,

    /// The premultiplied colour at `q`, in the region's frame.
    fn at(p: Paint, q: geom.Point) dvui.Color.PMA {
        const c: dvui.Color = switch (p) {
            .flat => |c| c,
            .art => |f| if (f.at(q)) |ac| docColor(.{ .r = ac.r, .g = ac.g, .b = ac.b, .a = ac.a }) else .transparent,
        };
        return .fromColor(c.opacity(dvui.currentWindow().alpha));
    }
};

/// The unit normal to the right of the edge from `p` to `q`, on screen.
fn outward(p: dvui.Point.Physical, q: dvui.Point.Physical) dvui.Point.Physical {
    const dx = q.x - p.x;
    const dy = q.y - p.y;
    const len = @sqrt(dx * dx + dy * dy);
    if (len == 0) return .{ .x = 0, .y = 0 };
    return .{ .x = -dy / len, .y = dx / len };
}

/// A triangle's indices in the order DVUI draws (counter-clockwise, y down).
fn ccw(p0: dvui.Point.Physical, p1: dvui.Point.Physical, p2: dvui.Point.Physical, a: dvui.Vertex.Index, b: dvui.Vertex.Index, c: dvui.Vertex.Index) [3]dvui.Vertex.Index {
    const cross = (p1.x - p0.x) * (p2.y - p0.y) - (p1.y - p0.y) * (p2.x - p0.x);
    return if (cross <= 0) .{ a, b, c } else .{ a, c, b };
}

/// The expression line's cursor in placed label `l` of panel `pi`, if it
/// is the one being edited.
fn caretIn(pi: Parent, l: layout.place.PlacedLabel) ?layout.render.Caret {
    const c = expr_caret orelse return null;
    const mine = switch (c.target) {
        // A tile track's text is set piece by piece with no offsets kept:
        // no caret in it yet.
        .tile_track => false,
        .run => |t| t.parent.eql(pi) and l.run != null and l.run.?.region == t.region and l.run.?.item == t.item,
    };
    if (!mine) return null;
    // A run set piece by piece: the piece the caret is in (or just after)
    // draws it. Pieces keep the run's source offsets.
    if (l.run) |run| if (run.len > 0) {
        const off: u32 = @intCast(c.offset);
        if (off < run.from or off > run.from + run.len) return null;
    };
    return l.render.caret(@intCast(c.offset));
}

/// View › Show text construction: text as outlines over a translucent fill,
/// with every element's frame lines, the anchor and the ink box.
var show_construction = false;

const construction = struct {
    const ascender: dvui.Color = .{ .r = 0x7a, .g = 0x5c, .b = 0xc4 };
    const cap: dvui.Color = .{ .r = 0x2e, .g = 0x7d, .b = 0xc2 };
    const x_height: dvui.Color = .{ .r = 0x2a, .g = 0x9d, .b = 0x8f };
    const baseline: dvui.Color = .{ .r = 0xd1, .g = 0x4b, .b = 0x2a };
    const descender: dvui.Color = .{ .r = 0xb0, .g = 0x7a, .b = 0x2c };
    const box: dvui.Color = .{ .r = 0x88, .g = 0x88, .b = 0x88 };
};

/// One label's construction: for each element (a run in one face and size,
/// scripts included), its ascender, cap height, x-height, baseline and
/// descender across its advance; the label's ink box; and its anchor, the
/// label frame's origin, as a small cross. `at` is where the label frame's
/// panel sits on the worksheet.
fn drawConstruction(area: dvui.Rect.Physical, l: layout.place.PlacedLabel, at: geom.Point) void {
    const px = dvui.windowNaturalScale();
    const ox = at.x + l.origin.x;
    const oy = at.y + l.origin.y;
    for (l.render.elements) |e| {
        const face = faceTable()[e.face orelse 0];
        const cap_units = (face.capHeight() catch null) orelse continue;
        const k = e.cap_height / cap_units;
        const ext = face.extents();
        const x0 = ox + e.origin.x;
        const x1 = x0 + e.advance;
        const base = oy + e.origin.y;
        const xh = face.xHeight() catch null;
        const lines = [_]struct { y: ?f64, color: dvui.Color }{
            .{ .y = base + ext.ascender * k, .color = construction.ascender },
            .{ .y = base + e.cap_height, .color = construction.cap },
            .{ .y = if (xh) |v| base + v * k else null, .color = construction.x_height },
            .{ .y = base, .color = construction.baseline },
            .{ .y = base + ext.descender * k, .color = construction.descender },
        };
        for (lines) |line| {
            const y = line.y orelse continue;
            const a = state.view.toPx(area, .{ .x = x0, .y = y });
            const b = state.view.toPx(area, .{ .x = x1, .y = y });
            dvui.Path.stroke(.{ .points = &.{ a, b } }, .{ .thickness = px, .color = .{ .color = line.color.opacity(0.8) } });
        }
    }
    if (!l.render.ink.isEmpty()) {
        const ink = l.render.ink;
        state.view.rect(area, .{ .x0 = ox + ink.x0, .y0 = oy + ink.y0, .x1 = ox + ink.x1, .y1 = oy + ink.y1 }).stroke(.square, .{ .thickness = px, .color = .{ .color = construction.box.opacity(0.7) } });
    }
    const c = state.view.toPx(area, .{ .x = ox, .y = oy });
    const r: f32 = 4 * px;
    const mark: dvui.ColorOrGradient = .{ .color = construction.baseline };
    dvui.Path.stroke(.{ .points = &.{ .{ .x = c.x - r, .y = c.y }, .{ .x = c.x + r, .y = c.y } } }, .{ .thickness = 1.5 * px, .color = mark });
    dvui.Path.stroke(.{ .points = &.{ .{ .x = c.x, .y = c.y - r }, .{ .x = c.x, .y = c.y + r } } }, .{ .thickness = 1.5 * px, .color = mark });
}

/// Ruler depth, logical pixels.
const ruler_size = 24;

/// One kind of ruler tick: every `step` mm, `len` of the ruler's depth
/// long, numbered or not.
const Tick = struct { step: f64, len: f32, label: bool };

/// The ticks for the worksheet's units at the current zoom. Metric: numbered
/// centimetres (thinned out to 2, 5, 10 cm … when crowded), then 5 mm and
/// 1 mm ticks where they fit. Imperial: numbered inches (thinned the same
/// way), then halves, quarters, eighths … to the finest that fits.
fn ticks(buf: []Tick) []Tick {
    const ns = dvui.windowNaturalScale();
    const ppm = state.view.ppm;
    const min_tick = 4 * ns;
    const min_label = 44 * ns;
    var n: usize = 0;
    switch (docUnits()) {
        .mil => {
            // Labels at round numbers of mils, ticks at a half and a tenth.
            const mil = 0.0254;
            var label: f64 = 10;
            for ([_]f64{ 10, 20, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000, 50000 }) |st| {
                label = st;
                if (st * mil * ppm >= min_label) break;
            }
            buf[n] = .{ .step = label * mil, .len = 0.7, .label = true };
            n += 1;
            for ([_]Tick{ .{ .step = label * mil / 2, .len = 0.45, .label = false }, .{ .step = label * mil / 10, .len = 0.25, .label = false } }) |t| {
                if (t.step * ppm >= min_tick and n < buf.len) {
                    buf[n] = t;
                    n += 1;
                }
            }
        },
        .mm => {
            var label: f64 = 10;
            for ([_]f64{ 10, 20, 50, 100, 200, 500, 1000, 2000 }) |st| {
                label = st;
                if (st * ppm >= min_label) break;
            }
            buf[n] = .{ .step = label, .len = 0.7, .label = true };
            n += 1;
            for ([_]Tick{ .{ .step = 10, .len = 0.5, .label = false }, .{ .step = 5, .len = 0.35, .label = false }, .{ .step = 1, .len = 0.2, .label = false } }) |t| {
                if (t.step < label and t.step * ppm >= min_tick and n < buf.len) {
                    buf[n] = t;
                    n += 1;
                }
            }
        },
        .inch => {
            var label: f64 = 1;
            for ([_]f64{ 1, 2, 5, 10, 20, 50, 100 }) |st| {
                label = st;
                if (st * 25.4 * ppm >= min_label) break;
            }
            buf[n] = .{ .step = label * 25.4, .len = 0.7, .label = true };
            n += 1;
            if (label > 1 and 25.4 * ppm >= min_tick) {
                buf[n] = .{ .step = 25.4, .len = 0.5, .label = false };
                n += 1;
            }
            var k: u6 = 1;
            while (n < buf.len) : (k += 1) {
                const step = 25.4 / @as(f64, @floatFromInt(@as(u64, 1) << k));
                if (step * ppm < min_tick) break;
                buf[n] = .{ .step = step, .len = @max(0.14, 0.45 - 0.07 * @as(f32, @floatFromInt(k))), .label = false };
                n += 1;
            }
        },
    }
    return buf[0..n];
}

/// The rulers, fixed to the sheet's edges and spanning only the sheet: the
/// horizontal one on its top edge, the vertical one on the side the ruler
/// origin is on. When an edge scrolls out of view its ruler stays pinned
/// to the canvas edge. Numbers count from the ruler origin in the
/// worksheet's units; the pointer is marked on both.
fn drawRulers(area: dvui.Rect.Physical) void {
    const ns = dvui.windowNaturalScale();
    const rw: f32 = ruler_size * ns;
    const prev = dvui.clip(area);
    defer dvui.clipSet(prev);
    const sheet = state.model.sheet;
    const open = openCanvas();
    const right = !open and sheet.ruler_origin.fromRight();
    // A canvas has no edges: its rulers run along the canvas's own.
    const tl = if (open) dvui.Point.Physical{ .x = area.x + rw, .y = area.y + rw } else state.view.toPx(area, .{ .x = 0, .y = sheet.h });
    const br = if (open) dvui.Point.Physical{ .x = area.x + area.w, .y = area.y + area.h } else state.view.toPx(area, .{ .x = sheet.w, .y = 0 });

    const hy = std.math.clamp(tl.y - rw, area.y, area.y + area.h - rw);
    const hx0 = @max(tl.x, area.x);
    const hx1 = @min(br.x, area.x + area.w);
    const vx = std.math.clamp(if (right) br.x else tl.x - rw, area.x, area.x + area.w - rw);
    const vy0 = @max(tl.y, area.y);
    const vy1 = @min(br.y, area.y + area.h);
    const top: dvui.Rect.Physical = .{ .x = hx0, .y = hy, .w = @max(0, hx1 - hx0), .h = rw };
    const side: dvui.Rect.Physical = .{ .x = vx, .y = vy0, .w = rw, .h = @max(0, vy1 - vy0) };
    const corner: dvui.Rect.Physical = .{ .x = vx, .y = hy, .w = rw, .h = rw };

    for ([_]dvui.Rect.Physical{ top, side, corner }) |r| r.fill(.square, .{ .color = .{ .color = colors.ruler } });

    var buf: [12]Tick = undefined;
    const list = ticks(&buf);
    rulerAxis(top, area, list, true);
    rulerAxis(side, area, list, false);

    // Each ruler's edge against the sheet.
    const line: dvui.ColorOrGradient = .{ .color = colors.edge };
    for ([_]dvui.Rect.Physical{ top, side, corner }) |r| r.stroke(.square, .{ .thickness = ns, .color = line });

    if (state.mouse) |m| {
        const p = state.view.toPx(area, m);
        const mark: dvui.ColorOrGradient = .{ .color = colors.select };
        dvui.Path.stroke(.{ .points = &.{ .{ .x = p.x, .y = top.y }, .{ .x = p.x, .y = top.y + top.h } } }, .{ .thickness = ns, .color = mark });
        dvui.Path.stroke(.{ .points = &.{ .{ .x = side.x, .y = p.y }, .{ .x = side.x + side.w, .y = p.y } } }, .{ .thickness = ns, .color = mark });
    }
}

/// The panels of `space` (or, when null, of the shown space), with their
/// outlines and content, as the view maps them.
fn drawSpacePanels(area: dvui.Rect.Physical, space: ?usize, layer: ?layout.model.ObjectId) void {
    const px = dvui.windowNaturalScale();
    // The workspace's own content layouts and grids, on its base layer.
    if (space orelse if (shownParent()) |_| shown_space else null) |si| if (si < state.model.spaces.items.len) {
        const on_base = if (layer) |l| l == state.model.spaces.items[si].base_layer else true;
        if (on_base) if (placedOf(.{ .space = si })) |pl| drawPanel(area, .{ .space = si }, pl);
    };
    for (0..state.model.panels.items.len) |pi| {
        if (space) |sp| {
            if (state.model.spaceOf(pi) != sp) continue;
        } else if (!shownPanel(pi)) continue;
        if (layer) |l| if (panelLayer(pi) != l) continue;
        const outline = state.view.rect(area, panelBox(pi));
        const is_context = switch (state.context) {
            .panel => |c| c == pi,
            else => false,
        };
        // While dragged, compliance is shown live for the preview position.
        const off = if (state.moving != null and state.moving.?.panel == pi) !state.model.compliantAt(pi, panelOrigin(pi)) else panelIssue(pi) != null;
        // A panel past the sheet's edge is outlined in the warning colour.
        const edge = if (is_context) colors.select else if (off) colors.overflow else colors.panel_edge;
        const thickness = if (is_context or off) 2 * px else px;
        // A panel made from a closed path is drawn as that path; its
        // margins (still a band inside its box) are not shown.
        const pl = placedOf(.{ .panel = pi });
        const shaped = pl != null and state.model.panels.items[pi].edge != null and pl.?.edge != null;
        // Its body: the edge with its holes and cutouts cut out (notches
        // where they cross it).
        const body: ?geom.Outline = if (pl) |q| q.body else null;
        if (shaped) {
            strokeOutline(area, body orelse pl.?.edge.?, panelOrigin(pi), thickness, edge);
        } else {
            drawPanelMargins(area, pi);
            // The selected panel's outline marches; others are content edges.
            if (body) |b| {
                strokeOutline(area, b, panelOrigin(pi), thickness, edge);
                if (is_context and !off) marchingBox(area, panelBox(pi), edge, thickness);
            } else if (is_context and !off) marchingBox(area, panelBox(pi), edge, thickness) else outline.stroke(.square, .{ .thickness = thickness, .color = .{ .color = edge } });
        }
        // A sketch's panel's drawing is its art (`sketch_ink`), drawn with it.
        if (pl) |q| drawPanel(area, .{ .panel = pi }, q);
    }
}

// Grids ---------------------------------------------------------------------
//
// A grid's points are where its construction lines cross; instances of its
// stamps (a prototype as a part, a hole or a legend, at a size and offset)
// are tiles bound to the points. Changing the grid's counts, spacing or
// stretch moves them all; on a part whose grid follows another, too.

/// What becomes of instances on points a grid no longer has.
var grid_dropped: layout.model.Model.Dropped = .leave;

/// A grid's construction lines on panel `pi`: faint, through its points,
/// reaching half a step past the outer ones; the context grid's stronger.
fn drawGrids(area: dvui.Rect.Physical, pi: Parent) void {
    const px = dvui.windowNaturalScale();
    for (state.model.gridsIn(pi), 0..) |grid, gi| {
        // An array's borders are its sketch's geometry, drawn as the
        // sketch.
        if (grid.array != null) continue;
        const sh = state.model.gridShape(pi, gi);
        const sel = switch (state.context) {
            .grid => |g| g.parent.eql(pi) and g.index == gi,
            else => false,
        };
        const colour = if (sel) colors.select.opacity(0.35) else colors.guide.opacity(0.15);
        const cols: f64 = @floatFromInt(sh.cols);
        const rows: f64 = @floatFromInt(sh.rows);
        // Its cells: the borders halfway between points, the outer ones
        // half a step past the last points; stronger than the lines
        // through the points (an array reads as its cells).
        const cell = if (sel) colors.select.opacity(0.75) else colors.guide.opacity(0.4);
        for (0..sh.cols + 1) |c| {
            const cf: f64 = @as(f64, @floatFromInt(c)) - 0.5;
            gridLine(area, pi, gi, cf, -0.5, cf, rows - 0.5, cell, px);
        }
        for (0..sh.rows + 1) |r| {
            const rf: f64 = @as(f64, @floatFromInt(r)) - 0.5;
            gridLine(area, pi, gi, -0.5, rf, cols - 0.5, rf, cell, px);
        }
        for (0..sh.cols) |c| {
            const cf: f64 = @floatFromInt(c);
            gridLine(area, pi, gi, cf, -0.5, cf, rows - 0.5, colour, px);
        }
        for (0..sh.rows) |r| {
            const rf: f64 = @floatFromInt(r);
            gridLine(area, pi, gi, -0.5, rf, cols - 0.5, rf, colour, px);
        }
    }
}

/// A line of grid `gi` from point (`c0`, `r0`) to (`c1`, `r1`) (fractions
/// allowed): straight on a Cartesian grid; on a polar one an arc or a ray,
/// drawn in short pieces.
fn gridLine(area: dvui.Rect.Physical, pi: Parent, gi: usize, c0: f64, r0: f64, c1: f64, r1: f64, colour: dvui.Color, px: f32) void {
    const n: usize = if (state.model.gridShape(pi, gi).polar != null) 64 else 1;
    var prev = onSheet(pi, pointBox(state.model.gridPoint(pi, gi, c0, r0)));
    for (1..n + 1) |k| {
        const t = @as(f64, @floatFromInt(k)) / @as(f64, @floatFromInt(n));
        const q = onSheet(pi, pointBox(state.model.gridPoint(pi, gi, c0 + (c1 - c0) * t, r0 + (r1 - r0) * t)));
        strokeLine(area, .{ .x = prev.x0, .y = prev.y0 }, .{ .x = q.x0, .y = q.y0 }, colour, px);
        prev = q;
    }
}

fn pointBox(p: geom.Point) geom.Box {
    return .{ .x0 = p.x, .x1 = p.x, .y0 = p.y, .y1 = p.y };
}

/// A straight line between two sheet points.
fn strokeLine(area: dvui.Rect.Physical, a: geom.Point, b: geom.Point, colour: dvui.Color, px: f32) void {
    const pts = [_]dvui.Point.Physical{ state.view.toPx(area, a), state.view.toPx(area, b) };
    dvui.Path.stroke(.{ .points = &pts }, .{ .thickness = px, .color = .{ .color = colour } });
}

/// A number property row; returns the new value when it was changed.
fn numberProp(name: []const u8, value: f64, min: f64, max: f64, n: usize) ?f64 {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(name);
    return accepted.numberField(@src(), f64, value, min, max, .{ .expand = .horizontal, .id_extra = n });
}

/// A panel's fabrication: the base's thickness and the process's layer
/// height and limits, then its layers in order, each made from part of
/// the panel (its outline, holes, grid parts or a slot's text) by adding,
/// cutting away or inlaying, from a surface of the base, up or down, to a
/// depth or through. Every change is one step (merged while typing).
fn panelFab(pi: usize) !void {
    const saved_group = pushGroup("panel.fab");
    defer popGroup(saved_group);
    const Fab = layout.model.Fab;
    const FabLayer = layout.model.FabLayer;
    const fab: Fab = state.model.panels.items[pi].fab;
    const ar = dvui.currentWindow().arena();
    var next = fab;
    const layers = try ar.dupe(FabLayer, fab.layers);
    var changed = false;
    // A structural change (a layer added, removed or moved) is a step of
    // its own; typing in a field merges with the field's last change.
    var key: u64 = 0;
    heading("Fabrication", .{}, 400);
    panelProcessChoice(pi);
    panelChecks(pi);
    inline for (.{
        .{ "Thickness, mm", "thickness", 0.01, 1000.0 },
    }, 0..) |f, k| {
        if (numberProp(f[0], @field(fab, f[1]), f[2], f[3], 401 + k)) |v| {
            @field(next, f[1]) = v;
            changed = true;
            key = mergeKey(.{ "fab", pi, f[1] });
        }
    }
    // The slots text may come from: every prototype's track names.
    var slots: std.ArrayList([]const u8) = .empty;
    try slots.append(ar, "every label");
    for (state.model.prototypes.items) |pr| for (pr.tracks) |tt| {
        for (slots.items[1..]) |sn| {
            if (std.mem.eql(u8, sn, tt.name)) break;
        } else try slots.append(ar, tt.name);
    };
    for (layers, 0..) |*l, li| {
        const n = 420 + li * 40;
        setTagScope("fabLayer.{d}", .{li + 1});
        setGroup("panel.fab.layer.{d}", .{li + 1});
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n, .margin = .{ .y = 6 } });
            defer row.deinit();
            dvui.label(@src(), "{d}. {s}", .{ li + 1, l.name }, .{ .font = dvui.Font.theme(.heading), .gravity_y = 0.5 });
            if (li + 1 < layers.len) keyIcon(@src(), "Later", dvui.entypo.arrow_down, @intCast(li), .{ .gravity_x = 1, .id_extra = 1 });
            if (li > 0) keyIcon(@src(), "Earlier", dvui.entypo.arrow_up, @intCast(li), .{ .gravity_x = 1, .id_extra = 2 });
            keyIcon(@src(), "Remove layer", dvui.entypo.cross, @intCast(li), .{ .gravity_x = 1, .id_extra = 3 });
        }
        if (textProp("Name", l.name, n + 1)) |v| {
            l.name = v;
            changed = true;
            key = mergeKey(.{ "fab", pi, li, "name" });
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 2 });
            defer row.deinit();
            propName("From");
            const kinds = [_][]const u8{ "the outline", "holes and cutouts", "grid parts", "text" };
            var choice: usize = @intFromEnum(std.meta.activeTag(l.source));
            if (tdropdown(@src(), &kinds, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != @intFromEnum(std.meta.activeTag(l.source))) {
                l.source = switch (choice) {
                    0 => .edge,
                    1 => .cutouts,
                    2 => .parts,
                    else => .{ .text = "" },
                };
                changed = true;
            }
        }
        if (l.source == .text) {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 3 });
            defer row.deinit();
            propName("Slot");
            var choice: usize = 0;
            for (slots.items[1..], 1..) |sn, k| {
                if (std.mem.eql(u8, sn, l.source.text)) choice = k;
            }
            // A slot no prototype has now (renamed or gone) is listed as it is.
            if (l.source.text.len > 0 and choice == 0) {
                try slots.append(ar, l.source.text);
                choice = slots.items.len - 1;
            }
            if (tdropdown(@src(), slots.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal })) {
                l.source = .{ .text = if (choice == 0) "" else slots.items[choice] };
                changed = true;
            }
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 4 });
            defer row.deinit();
            propName("Makes");
            const ops = [_][]const u8{ "solid, added", "a cut, away", "an inlay, cut and filled" };
            var choice: usize = @intFromEnum(std.meta.activeTag(l.op));
            if (tdropdown(@src(), &ops, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != @intFromEnum(std.meta.activeTag(l.op))) {
                const colour: layout.model.FabColour = switch (l.op) {
                    .add, .inlay => |c| c,
                    .subtract => .{ .name = "white", .color = .hex("#f2f2f2") },
                };
                l.op = switch (choice) {
                    0 => .{ .add = colour },
                    1 => .subtract,
                    else => .{ .inlay = colour },
                };
                changed = true;
            }
        }
        switch (l.op) {
            .add, .inlay => |c| {
                var col = c;
                var col_changed = false;
                if (textProp("Colour name", c.name, n + 5)) |v| {
                    col.name = v;
                    col_changed = true;
                }
                if (colourEntry("Colour", c.color, false, n + 6)) |v| {
                    col.color = v.?;
                    col_changed = true;
                }
                if (col_changed) {
                    l.op = if (l.op == .add) .{ .add = col } else .{ .inlay = col };
                    changed = true;
                    key = mergeKey(.{ "fab", pi, li, "colour" });
                }
            },
            .subtract => {},
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 7 });
            defer row.deinit();
            propName("Starts at");
            const surfaces = [_][]const u8{ "the base's bottom", "the base's top" };
            var choice: usize = @intFromEnum(l.surface);
            if (tdropdown(@src(), &surfaces, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != @intFromEnum(l.surface)) {
                l.surface = @enumFromInt(choice);
                changed = true;
            }
        }
        if (numberProp("Offset, mm", l.offset, -1000, 1000, n + 8)) |v| {
            l.offset = v;
            changed = true;
            key = mergeKey(.{ "fab", pi, li, "offset" });
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 9 });
            defer row.deinit();
            propName("Goes");
            const dirs = [_][]const u8{ "up", "down" };
            var choice: usize = @intFromEnum(l.dir);
            if (tdropdown(@src(), &dirs, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != @intFromEnum(l.dir)) {
                l.dir = @enumFromInt(choice);
                changed = true;
            }
        }
        {
            var through = l.depth == null;
            if (tcheckbox(@src(), &through, "Through the whole part", .{ .id_extra = n + 10 })) {
                l.depth = if (through) null else @min(fab.thickness, 0.6);
                changed = true;
            }
        }
        if (l.depth) |d| if (numberProp("Depth, mm", d, 0.001, 1000, n + 11)) |v| {
            l.depth = v;
            changed = true;
            key = mergeKey(.{ "fab", pi, li, "depth" });
        };
    }
    setTagScope("{s}", .{"fabrication"});
    // After its layers, the fabrication's own.
    setGroup("{s}", .{base_group});
    keyButton(@src(), "Add layer", 0, .{ .expand = .horizontal, .id_extra = 398, .margin = .{ .y = 6 } });
    if (!changed) return;
    next.layers = layers;
    const done = if (key != 0) actM(key, .setPanelFab, .{ pi, next }) else act(.setPanelFab, .{ pi, next });
    done catch {
        state.status = "That is not a size fabrication can use. ";
    };
}

/// A panel's grids, each opened by its name, and Add grid.
fn panelGrids(pi: usize) !void {
    const saved_group = pushGroup("panel.grids");
    defer popGroup(saved_group);
    const panel = state.model.panels.items[pi];
    heading("Grids", .{}, 300);
    for (panel.grids.items, 0..) |g, gi| {
        keyButton(@src(), g.name, @intCast(gi), .{ .expand = .horizontal, .id_extra = 301 + gi, .tag = listTag("panel.grids", g.name) });
    }
    keyButton(@src(), "Add grid", 0, .{ .expand = .horizontal, .id_extra = 299 });
}

/// A grid: its shape (counts, spacing, stretch), where it starts, what it
/// follows, and its stamps.
/// A stamp's shape: its prototype's, a ready-made sketch (made in the
/// document's sketches when first chosen), or one of the document's
/// sketches; and the sketch's parameters other than its size, for this
/// stamp.
fn stampShape(pi: Parent, gi: usize, si: usize, st: layout.model.Stamp, n: usize) !void {
    const Shape = layout.model.ShapeSketch;
    const kinds = std.enums.values(Shape);
    const ready = [_][]const u8{ "Circle", "Rectangle", "Rounded rectangle", "Slot" };
    const ar = dvui.currentWindow().arena();
    const sketches = state.model.sketches.items;
    var names: std.ArrayList([]const u8) = .empty;
    // What each entry after the ready-made ones is: a sketch's index.
    var others: std.ArrayList(usize) = .empty;
    try names.append(ar, "The prototype's");
    for (ready) |r| try names.append(ar, r);
    for (sketches, 0..) |item, i| if (item.shape == null) {
        try names.append(ar, try std.fmt.allocPrint(ar, "Sketch: {s}", .{item.name}));
        try others.append(ar, i);
    };
    var choice: usize = 0;
    const cur = if (st.sketch != .none) state.model.sketchIndex(st.sketch) else null;
    if (cur) |ci| {
        if (sketches[ci].shape) |k| choice = 1 + @intFromEnum(k) else for (others.items, 0..) |o, k| {
            if (o == ci) choice = 1 + ready.len + k;
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
        defer row.deinit();
        propName("Shape");
        if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n })) {
            var next = st;
            next.sketch = if (choice == 0) .none else if (choice <= ready.len)
                state.model.sketches.items[try act(.addShapeSketch, .{kinds[choice - 1]})].id
            else
                sketches[others.items[choice - 1 - ready.len]].id;
            act(.setStamp, .{ pi, gi, si, next }) catch {
                state.status = "That shape cannot be used. ";
            };
            return;
        }
    }
    const ci = cur orelse return;
    // Its parameters other than the size: the stamp's value, else the
    // sketch's.
    const sk = &state.model.sketches.items[ci].sketch;
    for (sk.params.items, 0..) |p, k| {
        if (std.mem.eql(u8, p.name, "w") or std.mem.eql(u8, p.name, "h")) continue;
        var value = sk.paramValue(p.name) catch 0;
        for (st.params) |sp| if (std.mem.eql(u8, sp.name, p.name)) {
            value = sp.value;
        };
        const label = try std.fmt.allocPrint(ar, "{s}, mm", .{p.name});
        if (numberProp(label, value, -1000, 1000, n + 1 + k)) |v| {
            var params: std.ArrayList(layout.model.TileParam) = .empty;
            for (st.params) |sp| if (!std.mem.eql(u8, sp.name, p.name)) try params.append(ar, sp);
            try params.append(ar, .{ .name = p.name, .value = v });
            var next = st;
            next.params = params.items;
            actM(mergeKey(.{ "stampparam", pi, gi, si, k }), .setStamp, .{ pi, gi, si, next }) catch {
                state.status = "That value cannot be used. ";
            };
        }
    }
}

fn gridProperties(pi: Parent, gi: usize) !void {
    const saved_group = pushGroup("grid");
    defer popGroup(saved_group);
    const g = state.model.gridsIn(pi)[gi];
    var sh = state.model.gridShape(pi, gi);
    propValue("Name", g.default_name, "{s}", .{g.name}, 1);
    propText("On", "{s}", .{state.model.parentName(pi)}, 2);
    // Its keys' legends as a sheet (theirs and those beside them).
    if (g.instances.items.len > 0) keyButton(@src(), "Make a legend sheet", 0, .{ .expand = .horizontal, .id_extra = 6 });
    if (state.model.findGrid(g.link)) |src| {
        const sg = state.model.gridsIn(src.parent)[src.index];
        propText("Follows", "{s} on {s}", .{ sg.name, state.model.parentName(src.parent) }, 3);
        keyButton(@src(), "Show the grid it follows", 0, .{ .expand = .horizontal, .id_extra = 4 });
        propText("", "Changing its shape here stops it following.", .{}, 5);
    } else {
        var followers: usize = 0;
        for (0..state.model.parentCount()) |k| for (state.model.gridsIn(state.model.parentAt(k))) |o| {
            if (o.link == g.id) followers += 1;
        };
        if (followers > 0) propText("Followed by", "{d} grids", .{followers}, 3);
    }
    heading("Points", .{}, 10);
    var changed = false;
    const polar = sh.polar != null;
    if (numberProp(if (polar) "Around" else "Columns", @floatFromInt(sh.cols), 1, 200, 11)) |v| {
        sh.cols = @intFromFloat(@round(v));
        changed = true;
    }
    if (numberProp(if (polar) "Rings" else "Rows", @floatFromInt(sh.rows), 1, 200, 12)) |v| {
        sh.rows = @intFromFloat(@round(v));
        changed = true;
    }
    if (numberProp(if (polar) "Angle between, °" else "Spacing across, mm", sh.pitch_x, 0.1, 1000, 13)) |v| {
        sh.pitch_x = v;
        changed = true;
    }
    if (numberProp(if (polar) "Ring spacing, mm" else "Spacing down, mm", sh.pitch_y, 0.1, 1000, 14)) |v| {
        sh.pitch_y = v;
        changed = true;
    }
    if (sh.polar) |*pol| {
        if (numberProp("First ring radius, mm", pol.radius, 0, 10000, 31)) |v| {
            pol.radius = v;
            changed = true;
        }
        if (numberProp("Start angle, °", pol.start, -360, 360, 32)) |v| {
            pol.start = v;
            changed = true;
        }
    }
    if (numberProp("Stretch across", sh.stretch_x, 0.01, 100, 15)) |v| {
        sh.stretch_x = v;
        changed = true;
    }
    if (numberProp("Stretch down", sh.stretch_y, 0.01, 100, 16)) |v| {
        sh.stretch_y = v;
        changed = true;
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 17 });
        defer row.deinit();
        propName("Points removed");
        const names = [_][]const u8{ "remove what is on them", "leave it in place" };
        var choice: usize = if (grid_dropped == .remove) 0 else 1;
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 17 })) grid_dropped = if (choice == 0) .remove else .leave;
    }
    if (changed) actM(mergeKey(.{ "grid", pi, gi }), .setGridShape, .{ pi, gi, sh, grid_dropped }) catch {
        state.status = "That shape cannot be used. ";
    };
    if (numberProp("First point across, mm", g.origin.x, -10000, 10000, 18)) |v| try actM(mergeKey(.{ "gridat", pi, gi }), .moveGrid, .{ pi, gi, geom.Point{ .x = v, .y = g.origin.y } });
    if (numberProp("First point up, mm", g.origin.y, -10000, 10000, 19)) |v| try actM(mergeKey(.{ "gridat", pi, gi }), .moveGrid, .{ pi, gi, geom.Point{ .x = g.origin.x, .y = v } });

    // Its stamps.
    const lifo = dvui.currentWindow().lifo();
    const proto_names = try lifo.alloc([]const u8, state.model.prototypes.items.len);
    defer lifo.free(proto_names);
    for (state.model.prototypes.items, proto_names) |p, *nm| nm.* = p.name;
    const stamps = state.model.gridsIn(pi)[gi].stamps.items;
    for (stamps, 0..) |st, si| {
        const n = 100 + si * 20;
        headingAs(scopeId("grid.stamp", st.name), "Stamp: {s}", .{st.name}, n);
        var next = st;
        var st_changed = false;
        var used: usize = 0;
        for (g.instances.items) |inst| {
            if (inst.stamp == st.id) used += 1;
        }
        propText("Instances", "{d}", .{used}, n + 1);
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 2 });
            defer row.deinit();
            propName("Made as");
            const roles = [_][]const u8{ "part", "hole (cut through)", "legend (labels only)" };
            var choice: usize = @intFromEnum(st.role);
            if (tdropdown(@src(), &roles, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n + 2 })) {
                next.role = @enumFromInt(choice);
                st_changed = true;
            }
        }
        if (proto_names.len > 0) {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 3 });
            defer row.deinit();
            propName("Prototype");
            var choice: usize = protoPos(st.prototype);
            if (tdropdown(@src(), proto_names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n + 3 })) {
                next.prototype = state.model.prototypes.items[choice].id;
                st_changed = true;
            }
        }
        if (st.role != .legend) try stampShape(pi, gi, si, st, n + 10);
        if (numberProp("Width, mm", st.w, 0.1, 1000, n + 4)) |v| {
            next.w = v;
            st_changed = true;
        }
        if (numberProp("Height, mm", st.h, 0.1, 1000, n + 5)) |v| {
            next.h = v;
            st_changed = true;
        }
        if (numberProp("Offset across, mm", st.offset.x, -1000, 1000, n + 6)) |v| {
            next.offset.x = v;
            st_changed = true;
        }
        if (numberProp("Offset up, mm", st.offset.y, -1000, 1000, n + 7)) |v| {
            next.offset.y = v;
            st_changed = true;
        }
        if (st_changed) actM(mergeKey(.{ "stamp", pi, gi, si }), .setStamp, .{ pi, gi, si, next }) catch {
            state.status = "That stamp cannot be used. ";
        };
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 8 });
            defer row.deinit();
            keyButton(@src(), "Fill empty points", @intCast(si), .{ .id_extra = n + 8 });
            keyButton(@src(), "Remove stamp", @intCast(si), .{ .id_extra = n + 9 });
        }
    }
    heading("Add a stamp", .{}, 90);
    setGroup("grid.add-stamp", .{});
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 91 });
        defer row.deinit();
        inline for (.{ .{ "Parts", layout.model.GridRole.part, 0.75, 0.75, 0.0 }, .{ "Holes", layout.model.GridRole.hole, 0.85, 0.85, 0.0 }, .{ "Legends", layout.model.GridRole.legend, 0.8, 0.25, 0.6 } }, 0..) |kind, k| {
            keyButton(@src(), kind[0], 0, .{ .id_extra = 92 + k });
        }
    }
    // A grid on another part following this one: the keys over a plate's
    // holes.
    {
        var others: std.ArrayList([]const u8) = .empty;
        var which: std.ArrayList(usize) = .empty;
        const arena = dvui.currentWindow().arena();
        for (state.model.panels.items, 0..) |p, qi| {
            if (pi.eql(.{ .panel = qi })) continue;
            others.append(arena, p.name) catch {};
            which.append(arena, qi) catch {};
        }
        if (others.items.len > 0) {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 96 });
            defer row.deinit();
            propName("Follow it on");
            var choice: usize = others.items.len;
            others.append(arena, "choose a part…") catch {};
            if (tdropdown(@src(), others.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 96 }) and choice < which.items.len) {
                const qi = which.items[choice];
                const ngi = try act(.addLinkedGrid, .{ Parent{ .panel = qi }, g.origin, g.id });
                state.context = .{ .grid = .{ .parent = .{ .panel = qi }, .index = ngi } };
                return;
            }
        }
    }
    // The grid's own, after its stamps.
    setGroup("{s}", .{base_group});
    keyButton(@src(), "Remove grid", 0, .{ .expand = .horizontal, .id_extra = 98, .margin = .{ .y = 8 } });
}

/// A tile bound to a grid: its point, how many points it spans, and
/// removing it; unbound, binding it again at the nearest point.
fn instanceProperties(pi: Parent, gi: usize, ii: usize) !void {
    const saved_group = pushGroup("instance");
    defer popGroup(saved_group);
    const g = state.model.gridsIn(pi)[gi];
    const inst = g.instances.items[ii];
    const sh = state.model.gridShape(pi, gi);
    _ = sh;
    next_element = "instance.grid";
    keyButton(@src(), g.name, 0, .{ .expand = .horizontal, .id_extra = 40 });
    if (state.model.stampIndex(pi, gi, inst.stamp)) |si| propText("Stamp", "{s}", .{g.stamps.items[si].name}, 41);
    if (inst.loose) |c| {
        propText("Point", "none: left at ({d:.2}, {d:.2}) mm", .{ c.x, c.y }, 42);
        keyButton(@src(), "Bind to the nearest point", 0, .{ .expand = .horizontal, .id_extra = 43 });
    } else {
        propText("Point", "column {d}, row {d}", .{ inst.col + 1, inst.row + 1 }, 42);
        if (numberProp("Spans columns", @floatFromInt(inst.cols), 1, 200, 44)) |v| act(.setInstanceSpan, .{ pi, gi, ii, @as(u32, @intFromFloat(@round(v))), inst.rows }) catch {
            state.status = "It would reach past the grid. ";
        };
        if (numberProp("Spans rows", @floatFromInt(inst.rows), 1, 200, 45)) |v| act(.setInstanceSpan, .{ pi, gi, ii, inst.cols, @as(u32, @intFromFloat(@round(v))) }) catch {
            state.status = "It would reach past the grid. ";
        };
    }
    if (state.model.instanceBox(pi, gi, ii)) |b| propText("Box", "{d:.2} × {d:.2} mm", .{ b.width(), b.height() }, 46);
    keyButton(@src(), "Remove from the grid", 0, .{ .expand = .horizontal, .id_extra = 47 });
}

// Panel editing ---------------------------------------------------------------
//
// A mode focused on one panel: the canvas shows it filling the view, and
// clicks go to its grids. A click on a point puts an instance of the
// chosen stamp there (or picks the one there); a drag across points puts
// one instance spanning them. Esc lets go of a drag or the picked
// instance, Delete removes the picked instance; the mode is left with its
// button, not a key.

const PanelEdit = struct {
    panel: usize,
    grid: usize = 0,
    stamp: usize = 0,
};

var panel_edit: ?PanelEdit = null;
/// The grid point under the pointer, and where a press began.
const GridAt = struct { col: u32, row: u32 };
var pe_hover: ?GridAt = null;
var pe_press: ?GridAt = null;

fn enterPanelEdit(pi: usize) void {
    panel_edit = .{ .panel = pi };
    pe_hover = null;
    pe_press = null;
    shown_space = state.model.spaceOf(pi);
    state.tool = .select;
    selection.clearRetainingCapacity();
    track_cursor = null;
    state.view.fit = panelBox(pi);
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
    state.status = "Panel editing: click a grid point to place the stamp there, drag across points to span them. ";
}

fn leavePanelEdit() void {
    if (panel_edit) |pe| state.context = .{ .panel = pe.panel };
    panel_edit = null;
    pe_hover = null;
    pe_press = null;
    state.status = "";
}

/// The panel editing mode's grid and stamp, when both exist.
fn peTarget() ?struct { parent: Parent, grid: usize, stamp: usize } {
    const pe = panel_edit orelse return null;
    if (pe.panel >= state.model.panels.items.len) return null;
    const grids = state.model.gridsIn(.{ .panel = pe.panel });
    if (pe.grid >= grids.len) return null;
    if (pe.stamp >= grids[pe.grid].stamps.items.len) return null;
    return .{ .parent = .{ .panel = pe.panel }, .grid = pe.grid, .stamp = pe.stamp };
}

/// The point of the mode's grid nearest `at` (space mm), when `at` lies
/// within half a step of the grid's points.
fn peGridAt(at: geom.Point) ?GridAt {
    const pe = panel_edit orelse return null;
    if (pe.panel >= state.model.panels.items.len or pe.grid >= state.model.gridsIn(.{ .panel = pe.panel }).len) return null;
    const o = onSheetPoint(.{ .panel = pe.panel }, state.model.gridPoint(.{ .panel = pe.panel }, pe.grid, 0, 0));
    const sh = state.model.gridShape(.{ .panel = pe.panel }, pe.grid);
    const c = @round((at.x - o.x) / sh.stepX());
    const r = @round((o.y - at.y) / sh.stepY());
    if (c < 0 or r < 0 or c >= @as(f64, @floatFromInt(sh.cols)) or r >= @as(f64, @floatFromInt(sh.rows))) return null;
    return .{ .col = @intFromFloat(c), .row = @intFromFloat(r) };
}

/// The panel being edited, outlined, and the stamp's box at the pointer,
/// or over the points a drag spans.
fn drawPanelEdit(area: dvui.Rect.Physical) void {
    const px = dvui.windowNaturalScale();
    const pe = panel_edit orelse return;
    if (pe.panel >= state.model.panels.items.len) return;
    marchingBox(area, panelBox(pe.panel), colors.select, 1.5 * px);
    const t = peTarget() orelse return;
    const hover = pe_hover orelse return;
    const from = pe_press orelse hover;
    const c0 = @min(from.col, hover.col);
    const r0 = @min(from.row, hover.row);
    const cols = @max(from.col, hover.col) - c0 + 1;
    const rows = @max(from.row, hover.row) - r0 + 1;
    const st = state.model.gridsIn(t.parent)[t.grid].stamps.items[t.stamp];
    const sh = state.model.gridShape(t.parent, t.grid);
    const w = st.w + @as(f64, @floatFromInt(cols - 1)) * sh.stepX();
    const h = st.h + @as(f64, @floatFromInt(rows - 1)) * sh.stepY();
    const p = state.model.gridPoint(t.parent, t.grid, @as(f64, @floatFromInt(c0)) + @as(f64, @floatFromInt(cols - 1)) / 2, @as(f64, @floatFromInt(r0)) + @as(f64, @floatFromInt(rows - 1)) / 2);
    const cx = p.x + st.offset.x;
    const cy = p.y + st.offset.y;
    guideBox(area, onSheet(t.parent, .{ .x0 = cx - w / 2, .x1 = cx + w / 2, .y0 = cy - h / 2, .y1 = cy + h / 2 }), colors.select, 1.5 * px);
}

fn panelEditEvent(e: *dvui.Event, box: *dvui.BoxWidget, area: dvui.Rect.Physical) void {
    const pe = panel_edit orelse return;
    if (pe.panel >= state.model.panels.items.len) {
        leavePanelEdit();
        return;
    }
    if (e.handled) return;
    if (e.evt == .key) {
        if (!cursorKeysReach()) return;
        const inv = keymap.match1(e, kmode("panel-edit")) orelse return;
        switch (inv.action) {
            kact("panel-edit.cancel") => {
                if (pe_press != null) {
                    pe_press = null;
                } else state.context = .{ .panel = pe.panel };
            },
            kact("panel-edit.remove-tile") => {
                const id = switch (state.context) {
                    .tile => |id| id,
                    else => return,
                };
                const at = state.model.gridInstanceOf(id) orelse return;
                act(.removeInstance, .{ at.parent, at.grid, at.index }) catch {};
                state.context = .{ .panel = pe.panel };
            },
            else => return,
        }
        e.handle(@src(), box.data());
        dvui.refresh(null, @src(), box.data().id);
        return;
    }
    if (e.evt != .mouse) return;
    if (!dvui.eventMatchSimple(e, box.data())) return;
    const me = e.evt.mouse;
    const at = state.view.toMm(area, me.p);
    switch (me.action) {
        .focus => {
            e.handle(@src(), box.data());
            dvui.focusWidget(box.data().id, null, e.num);
        },
        .position => {
            state.mouse = at;
            pe_hover = peGridAt(at);
            dvui.refresh(null, @src(), box.data().id);
        },
        .press => if (area.contains(me.p)) {
            e.handle(@src(), box.data());
            dvui.captureMouse(box.data(), e.num);
            if (me.button == .middle) {
                dvui.dragPreStart(me.button, me.p, .{});
                return;
            }
            if (!me.button.pointer()) return;
            pe_press = peGridAt(at);
            if (pe_press == null) pickInPanel(pe.panel, at);
        },
        .motion => if (dvui.captured(box.data().id)) {
            e.handle(@src(), box.data());
            pe_hover = peGridAt(at);
            if (pe_press == null) if (dvui.dragging(me, null)) |d| {
                state.view.fit = null;
                state.view.cx -= d.x / state.view.ppm;
                state.view.cy += d.y / state.view.ppm;
            };
            dvui.refresh(null, @src(), box.data().id);
        },
        .release => if (dvui.captured(box.data().id)) {
            e.handle(@src(), box.data());
            if (pe_press) |from| if (peGridAt(at)) |to| peRelease(from, to);
            pe_press = null;
            dvui.captureMouse(null, e.num);
            dvui.dragEnd(me.button);
            dvui.refresh(null, @src(), box.data().id);
        },
        else => {},
    }
}

/// A click off the grid: picks what of the panel is there (an instance of
/// another grid or stamp, the panel itself).
fn pickInPanel(pi: usize, at: geom.Point) void {
    state.context = .{ .panel = pi };
    const pl = placedOf(.{ .panel = pi }) orelse return;
    for (pl.tiles) |t| {
        if (contains(onSheet(.{ .panel = pi }, t.pitch_box), at)) state.context = .{ .tile = t.id };
    }
}

/// A press on `from` let go on `to`: on one point, picks what of the stamp
/// is there or places one; across points, one instance spans them.
fn peRelease(from: GridAt, to: GridAt) void {
    const t = peTarget() orelse {
        state.status = "Choose a grid and a stamp to place. ";
        return;
    };
    const sid = state.model.gridsIn(t.parent)[t.grid].stamps.items[t.stamp].id;
    if (from.col == to.col and from.row == to.row) {
        if (state.model.instanceAt(t.parent, t.grid, sid, from.col, from.row)) |ii| {
            state.context = .{ .tile = state.model.gridsIn(t.parent)[t.grid].instances.items[ii].tile };
            return;
        }
    }
    const c0 = @min(from.col, to.col);
    const r0 = @min(from.row, to.row);
    const id = act(.placeInstance, .{ t.parent, t.grid, t.stamp, c0, r0, @max(from.col, to.col) - c0 + 1, @max(from.row, to.row) - r0 + 1 }) catch {
        state.status = "It could not be placed there. ";
        return;
    };
    state.context = .{ .tile = id };
}

/// The mode's own properties, above the context's: the grid and stamp to
/// place, and leaving the mode.
fn panelEditHeader() void {
    const saved_group = pushGroup("panel.editing");
    defer popGroup(saved_group);
    if (panel_edit == null) return;
    const p = &panel_edit.?;
    if (p.panel >= state.model.panels.items.len) {
        leavePanelEdit();
        return;
    }
    const panel = state.model.panels.items[p.panel];
    headingAs("panel.editing", "Editing {s}", .{panel.name}, 7000);
    const arena = dvui.currentWindow().arena();
    if (panel.grids.items.len == 0) {
        propText("Grids", "none yet: add one below", .{}, 7001);
    } else {
        var names: std.ArrayList([]const u8) = .empty;
        for (panel.grids.items) |g| names.append(arena, g.name) catch {};
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 7002 });
        defer row.deinit();
        propName("Grid");
        var choice: usize = @min(p.grid, names.items.len - 1);
        if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 7002 })) {
            p.grid = choice;
            p.stamp = 0;
        }
    }
    if (p.grid < panel.grids.items.len) {
        const stamps = panel.grids.items[p.grid].stamps.items;
        if (stamps.len == 0) {
            propText("Stamps", "none yet: add one in the grid's properties", .{}, 7003);
        } else {
            var names: std.ArrayList([]const u8) = .empty;
            for (stamps) |st| names.append(arena, st.name) catch {};
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 7004 });
            defer row.deinit();
            propName("Places");
            var choice: usize = @min(p.stamp, names.items.len - 1);
            if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 7004 })) p.stamp = choice;
        }
        keyButton(@src(), "Grid settings", 0, .{ .expand = .horizontal, .id_extra = 7005 });
    }
    inline for (.{ "Click a point: place or pick.", "Drag across points: span them.", "Delete removes the picked one." }, 0..) |line, k| {
        dvui.labelNoFmt(@src(), line, .{}, .{ .id_extra = 7010 + k, .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.65) } });
    }
    keyButton(@src(), "Leave panel editing", 0, .{ .expand = .horizontal, .id_extra = 7007, .margin = .{ .y = 6, .h = 10 } });
}

// Layers and images ---------------------------------------------------------
//
// Each space draws its layers bottom first: a hidden layer is skipped; the
// rest are drawn at their opacity, images with their blend mode (vector
// content of a blended layer is drawn normally for now). Locked and hidden
// layers' objects cannot be picked. New panels and images go on the active
// layer: the last one chosen in the space, else its base layer.

/// The layer last chosen; new objects in its space go on it.
var active_layer: layout.model.ObjectId = .none;

/// The layer a panel is on, resolved (one on none is on its space's base
/// layer).
fn panelLayer(pi: usize) layout.model.ObjectId {
    const p = state.model.panels.items[pi];
    if (state.model.spaces.items.len == 0) return .none;
    const sp = state.model.spaces.items[state.model.spaceOf(pi)];
    return if (p.layer == .none) sp.base_layer else p.layer;
}

/// Whether what is on layer `id` of space `space` can be picked: the layer
/// is shown and not locked.
fn layerOpen(space: usize, id: layout.model.ObjectId) bool {
    if (space >= state.model.spaces.items.len) return true;
    const sp = state.model.spaces.items[space];
    const li = sp.layerIndex(id) orelse return true;
    const l = sp.layers.items[li];
    return l.visible and !l.locked;
}

/// The layer new objects in the shown space go on.
fn newObjectLayer() layout.model.ObjectId {
    if (shown_space >= state.model.spaces.items.len) return .none;
    const sp = state.model.spaces.items[shown_space];
    return if (sp.layerIndex(active_layer) != null and active_layer != .none) active_layer else sp.base_layer;
}

fn imageAt(space: usize, index: usize) ?layout.model.Image {
    if (space >= state.model.spaces.items.len) return null;
    const list = state.model.spaces.items[space].images.items;
    return if (index < list.len) list[index] else null;
}

fn figurePlaceAt(space: usize, index: usize) ?layout.model.FigurePlace {
    if (space >= state.model.spaces.items.len) return null;
    const list = state.model.spaces.items[space].figure_places.items;
    return if (index < list.len) list[index] else null;
}

/// The placement with id `id`, if it is one.
fn figurePlaceOf(id: layout.model.ObjectId) ?layout.model.FigurePlace {
    for (state.model.spaces.items) |sp| for (sp.figure_places.items) |fp| if (fp.id == id) return fp;
    return null;
}

/// A figure's ink as triangles in its own coordinates, worked out once
/// per figure (its paths' identity) and kept.
const FigureTris = struct { paths: [*]const layout.figure.Path, bounds: geom.Box, colors: []layout.art.Color, tris: [][]const [3]geom.Point };
var figure_tris: std.AutoHashMapUnmanaged(layout.model.ObjectId, FigureTris) = .empty;
var figure_tris_arena: ?std.heap.ArenaAllocator = null;

fn figureTris(fi: usize) ?FigureTris {
    const f = state.model.figures.items[fi];
    if (figure_tris.get(f.id)) |t| if (t.paths == f.paths.ptr) return t;
    const out = trisOfFigure(f) orelse return null;
    figure_tris.put(state.gpa, f.id, out) catch {};
    return out;
}

/// `figureTris` for a figure's draft paths (its sketch being edited).
var figure_draft_tris: std.AutoHashMapUnmanaged(layout.model.ObjectId, FigureTris) = .empty;
fn figureDraftTris(fi: usize) ?FigureTris {
    var f = state.model.figures.items[fi];
    if (figure_draft_tris.get(f.id)) |t| if (t.paths == f.draft.ptr) return t;
    f.paths = f.draft;
    const out = trisOfFigure(f) orelse return null;
    figure_draft_tris.put(state.gpa, f.id, out) catch {};
    return out;
}

fn trisOfFigure(f: layout.figure.Figure) ?FigureTris {
    if (figure_tris_arena == null) figure_tris_arena = .init(state.gpa);
    const a = figure_tris_arena.?.allocator();
    const shapes = layout.figure.ink(a, f, figure_tol) catch return null;
    const colors_ = a.alloc(layout.art.Color, shapes.len) catch return null;
    const tris = a.alloc([]const [3]geom.Point, shapes.len) catch return null;
    for (shapes, colors_, tris) |sh, *c, *t| {
        c.* = switch (sh.paint.fill) {
            .solid => |col| col,
            else => .{ .r = 0, .g = 0, .b = 0, .a = 255 },
        };
        const lines = a.alloc([]const geom.Point, sh.outline.contours.len) catch return null;
        for (sh.outline.contours, lines) |ct, *l| {
            var pts: std.ArrayList(geom.Point) = .empty;
            for (ct.segments) |seg| flatten(a, &pts, seg, figure_tol) catch {};
            l.* = pts.items;
        }
        const region = geom.fill.nonzero(a, lines, figure_tol * 0.1) catch {
            t.* = &.{};
            continue;
        };
        t.* = region.triangles;
    }
    return .{ .paths = f.paths.ptr, .bounds = layout.figure.inkBounds(shapes), .colors = colors_, .tris = tris };
}

/// Figure `fi`'s ink drawn into `ink` (mm in the shown space), at `alpha`.
fn drawFigureInk(area: dvui.Rect.Physical, fi: usize, ink: geom.Box, alpha: f32) void {
    drawFigureTris(area, figureTris(fi) orelse return, ink, alpha);
}

fn drawFigureTris(area: dvui.Rect.Physical, ft: FigureTris, ink: geom.Box, alpha: f32) void {
    const fb = ft.bounds;
    if (fb.isEmpty() or !(fb.width() > 0) or !(fb.height() > 0)) return;
    const sx = ink.width() / fb.width();
    const sy = ink.height() / fb.height();
    const lifo = dvui.currentWindow().lifo();
    const Index = dvui.Vertex.Index;
    for (ft.tris, ft.colors) |tris, col| {
        const pma: dvui.Color.PMA = .fromColor(docColor(.{ .r = col.r, .g = col.g, .b = col.b, .a = col.a }).opacity(alpha * dvui.currentWindow().alpha));
        const batch = 20000;
        var from: usize = 0;
        while (from < tris.len) : (from += batch) {
            const part = tris[from..@min(from + batch, tris.len)];
            var tb = dvui.Triangles.Builder.init(lifo, 3 * part.len, 3 * part.len) catch return;
            defer tb.deinit(lifo);
            for (part, 0..) |t, j| {
                var v: [3]dvui.Point.Physical = undefined;
                for (t, &v) |q, *o| o.* = state.view.toPx(area, .{ .x = ink.x0 + (q.x - fb.x0) * sx, .y = ink.y0 + (q.y - fb.y0) * sy });
                for (v) |pos| tb.appendVertex(.{ .pos = pos, .col = pma });
                const i: Index = @intCast(3 * j);
                tb.appendTriangles(&ccw(v[0], v[1], v[2], i, i + 1, i + 2));
            }
            dvui.renderTriangles(tb.build_unowned(), null) catch {};
        }
    }
}

/// The figures placed in space `space` on layer `layer`: their ink; the
/// chosen one's boundary.
fn drawFigurePlaces(area: dvui.Rect.Physical, space: usize, layer: layout.model.ObjectId) void {
    const sp = state.model.spaces.items[space];
    const px = dvui.windowNaturalScale();
    for (sp.figure_places.items, 0..) |fp, k| {
        if ((if (fp.layer == .none) sp.base_layer else fp.layer) != layer) continue;
        if (state.model.figureIndex(fp.figure)) |fi| {
            drawFigureInk(area, fi, fp.inkBox(), 1);
        } else {
            // Its figure removed: where it was.
            state.view.rect(area, fp.inkBox()).stroke(.square, .{ .thickness = px, .color = .{ .color = colors.overflow } });
        }
        const sel = switch (state.context) {
            .figure_place => |c| c.space == space and c.index == k,
            else => false,
        };
        if (!sel) continue;
        if (fp.border.fractions() != null) {
            const a = dvui.currentWindow().arena();
            const ol = fp.border.outline(a, fp.inkBox(), fp.margin) catch continue;
            const bd = Boundary.outline(a, ol, 0.1 / state.view.ppm, .{ .x = 0, .y = 0 }) catch continue;
            haloBoundary(area, bd, colors.select);
        } else marchingBox(area, fp.box(), colors.select, 2 * px);
    }
}

/// The top-most placed figure of the shown space whose boundary holds `at`.
fn figurePlaceUnder(at: geom.Point) ?Context {
    if (shown_space >= state.model.spaces.items.len) return null;
    const sp = state.model.spaces.items[shown_space];
    var hit: ?Context = null;
    var hit_layer: usize = 0;
    for (sp.figure_places.items, 0..) |fp, k| {
        if (!contains(fp.box(), at) or !layerOpen(shown_space, fp.layer)) continue;
        const li = sp.layerIndex(fp.layer) orelse 0;
        if (hit == null or li >= hit_layer) {
            hit = .{ .figure_place = .{ .space = shown_space, .index = k } };
            hit_layer = li;
        }
    }
    return hit;
}

/// Insert figure's ink box for a drag from `start` to `at`: the figure's
/// proportions, as large as the drag reaches on either axis, from
/// `start` the way the drag goes. Null for a drag too short to size it.
fn insertBox(from: geom.Point, at: geom.Point) ?geom.Box {
    const fi = state.model.figureIndex(insert_figure) orelse return null;
    const fb = state.model.figures.items[fi].bounds();
    if (fb.isEmpty() or !(fb.width() > 0) or !(fb.height() > 0)) return null;
    const aspect = fb.width() / fb.height();
    const dx = at.x - from.x;
    const dy = at.y - from.y;
    if (@max(@abs(dx), @abs(dy)) * state.view.ppm < 4 * dvui.windowNaturalScale()) return null;
    var w = @abs(dx);
    var h = @abs(dy);
    if (w < h * aspect) w = h * aspect else h = w / aspect;
    const x0 = if (dx < 0) from.x - w else from.x;
    const y0 = if (dy < 0) from.y - h else from.y;
    return .{ .x0 = x0, .y0 = y0, .x1 = x0 + w, .y1 = y0 + h };
}

/// While Insert figure is dragged: the ink in the box it will fill, and
/// the boundary round it.
fn drawInsertPreview(area: dvui.Rect.Physical, from: geom.Point, at: geom.Point) void {
    const px = dvui.windowNaturalScale();
    const b = insertBox(from, at) orelse return;
    if (state.model.figureIndex(insert_figure)) |fi| drawFigureInk(area, fi, b, 0.6);
    const g = layout.model.default_figure_margin;
    const outer: geom.Box = .{ .x0 = b.x0 - g, .y0 = b.y0 - g, .x1 = b.x1 + g, .y1 = b.y1 + g };
    state.view.rect(area, outer).stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } });
}

/// Insert figure let go: the figure placed in the box dragged (its ink
/// that size), or at its own size centred where clicked; it is then the
/// selection, and the tool done.
fn insertFigureFromDrag(from: geom.Point, at: geom.Point) void {
    state.tool = .select;
    const fi = state.model.figureIndex(insert_figure) orelse return;
    const b = insertBox(from, at) orelse blk: {
        const fb = state.model.figures.items[fi].bounds();
        const w = fb.width();
        const h = fb.height();
        break :blk geom.Box{ .x0 = from.x - w / 2, .y0 = from.y - h / 2, .x1 = from.x + w / 2, .y1 = from.y + h / 2 };
    };
    // Started on a panel: line art on it, made with it.
    if (panelUnderForFigure(from)) |pi| {
        const o = state.model.panels.items[pi].origin;
        const ai = act(.placeFigureOnPanel, .{ pi, fi, geom.Point{ .x = b.x0 - o.x, .y = b.y0 - o.y }, b.width() }) catch {
            state.status = "The figure was not placed. ";
            return;
        };
        state.context = .{ .art = .{ .panel = pi, .index = ai } };
        selection.clearRetainingCapacity();
        if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
        return;
    }
    const k = act(.placeFigure, .{ shown_space, fi, geom.Point{ .x = b.x0, .y = b.y0 }, b.width(), newObjectLayer() }) catch {
        state.status = "The figure was not placed. ";
        return;
    };
    state.context = .{ .figure_place = .{ .space = shown_space, .index = k } };
    selection.clearRetainingCapacity();
    if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
}

/// The smallest bounded panel shown whose box holds `at`: where Insert
/// figure puts the figure on the panel.
fn panelUnderForFigure(at: geom.Point) ?usize {
    var best: ?usize = null;
    var best_area: f64 = std.math.inf(f64);
    for (state.model.panels.items, 0..) |p, pi| {
        _ = p;
        if (!shownPanel(pi)) continue;
        const b = panelBox(pi);
        if (!contains(b, at)) continue;
        const ar = b.width() * b.height();
        if (ar < best_area) {
            best_area = ar;
            best = pi;
        }
    }
    return best;
}

/// What keeps its proportions when resized: a placed figure (its ink's,
/// inside its margin), or line art that is a figure's placement (its box's).
const Proportions = struct { aspect: f64, margin: f64 };
fn figureProportions(id: layout.model.ObjectId) ?Proportions {
    if (figurePlaceOf(id)) |fp| return if (fp.h > 0) .{ .aspect = fp.w / fp.h, .margin = fp.margin } else null;
    for (state.model.panels.items) |p| for (p.art.items) |x| if (x.id == id and x.figure != .none) {
        const b = x.box();
        return if (b.height() > 0) .{ .aspect = b.width() / b.height(), .margin = 0 } else null;
    };
    return null;
}

/// A placement's boundary `b`, resized from `was` by `edges`, made to keep
/// its ink's proportions: the edge moved most decides; the edges not
/// moved stay (a side's middle handle: the other axis about its middle).
fn keepFigureProportions(pr: Proportions, was: geom.Box, b: geom.Box, edges: Edges) geom.Box {
    const aspect = pr.aspect;
    const g = pr.margin;
    const horiz = edges.left or edges.right;
    const vert = edges.bottom or edges.top;
    var w = @max(b.width() - 2 * g, 1e-3);
    var h = @max(b.height() - 2 * g, 1e-3);
    if (horiz and vert) {
        if (@abs(b.width() - was.width()) / @max(was.width(), 1e-9) >= @abs(b.height() - was.height()) / @max(was.height(), 1e-9)) h = w / aspect else w = h * aspect;
    } else if (horiz) h = w / aspect else w = h * aspect;
    var o = b;
    const W = w + 2 * g;
    const H = h + 2 * g;
    if (edges.left) o.x0 = o.x1 - W else if (edges.right) o.x1 = o.x0 + W else {
        const mx = (was.x0 + was.x1) / 2;
        o.x0 = mx - W / 2;
        o.x1 = mx + W / 2;
    }
    if (edges.bottom) o.y0 = o.y1 - H else if (edges.top) o.y1 = o.y0 + H else {
        const my = (was.y0 + was.y1) / 2;
        o.y0 = my - H / 2;
        o.y1 = my + H / 2;
    }
    return o;
}

/// A placed figure's properties: its figure, place, size (its
/// proportions kept), margin, layer; Remove.
/// The border being set in Properties for a figure's placement, until
/// Apply: its kind and least radius (an object's own until changed).
var border_pending: struct { obj: layout.model.ObjectId = .none, kind: layout.model.BorderKind = .box, radius: f64 = 3 } = .{};

/// Border (Box or Dubins), its least radius, and Apply, for the
/// placement `obj` bordered by `b`, in the current group.
fn borderProps(obj: layout.model.ObjectId, b: layout.model.FigureBorder, n: usize) void {
    if (border_pending.obj != obj) border_pending = .{ .obj = obj, .kind = b.kind, .radius = b.radius };
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
        defer row.deinit();
        propName("Border");
        const names = [_][]const u8{ "Box", "Dubins" };
        var choice: usize = @intFromEnum(border_pending.kind);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n })) border_pending.kind = @enumFromInt(choice);
    }
    if (border_pending.kind == .dubins) {
        var rb: [32]u8 = undefined;
        if (sizesProp("Min radius, mm", std.fmt.bufPrint(&rb, "{d:.2}", .{border_pending.radius}) catch "", n + 1)) |list| if (list.len == 1) {
            if (list[0] >= 0) border_pending.radius = list[0] else state.status = "A radius cannot be negative. ";
        };
    }
    keyButton(@src(), "Apply border", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
}

fn figurePlaceProperties(space: usize, index: usize) void {
    const saved_group = pushGroup("figure-place");
    defer popGroup(saved_group);
    const fp = figurePlaceAt(space, index) orelse return;
    const fname = if (state.model.figureIndex(fp.figure)) |fi| state.model.figures.items[fi].name else "(removed)";
    propText("Figure", "{s}", .{fname}, 1);
    if (layerChoice(space, fp.layer, 2)) |l| act(.setFigurePlace, .{ space, index, fp.at, fp.w, fp.margin, l }) catch {};
    propText("Place", "({d:.2}, {d:.2}) mm", .{ fp.at.x, fp.at.y }, 3);
    var buf: [32]u8 = undefined;
    if (sizesProp("Width, mm", std.fmt.bufPrint(&buf, "{d:.2}", .{fp.w}) catch "", 4)) |list| if (list.len == 1) {
        act(.setFigurePlace, .{ space, index, fp.at, list[0], fp.margin, fp.layer }) catch {
            state.status = "A width must be more than 0. ";
        };
    };
    propText("Height", "{d:.2} mm (keeps its proportions)", .{fp.h}, 5);
    keyButton(@src(), "Show figure", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
    var mb: [32]u8 = undefined;
    if (sizesProp("Margin, mm", std.fmt.bufPrint(&mb, "{d:.2}", .{fp.margin}) catch "", 6)) |list| if (list.len == 1) {
        act(.setFigurePlace, .{ space, index, fp.at, fp.w, list[0], fp.layer }) catch {
            state.status = "A margin cannot be negative. ";
        };
    };
    borderProps(fp.id, fp.border, 7);
    keyButton(@src(), "Remove figure", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// Space `space`'s layers, bottom first, each at its opacity: its images,
/// views and panels on that layer.
fn drawSpace(area: dvui.Rect.Physical, space: usize, depth: usize) void {
    if (space >= state.model.spaces.items.len) return;
    for (0..state.model.spaces.items[space].layers.items.len) |li| drawSpaceLayer(area, space, depth, li);
}

/// Layer `li` of space `space`, at its opacity (nothing when hidden).
fn drawSpaceLayer(area: dvui.Rect.Physical, space: usize, depth: usize, li: usize) void {
    const l = state.model.spaces.items[space].layers.items[li];
    if (!l.visible) return;
    const prev = dvui.alpha(@floatCast(l.opacity));
    defer dvui.alphaSet(prev);
    drawImages(area, space, l.id, l.blend);
    drawFigurePlaces(area, space, l.id);
    drawViews(area, space, depth, l.id);
    drawSpacePanels(area, space, l.id);
}

// The view's own layers --------------------------------------------------------
//
// What the canvas draws besides the document's layers is in the same stack:
// the grid (usually rearmost), the axes, the check results, the
// construction lines, the flow marks. Each can be shown or hidden and moved among the
// document's layers in the Layers palette. They are the view's, not the
// document's: kept for the session, not saved with the file.

const ViewLayer = enum {
    grid,
    axes,
    check_strokes,
    check_gaps,
    check_other,
    simulation,
    guides,
    /// What a flow holds that output leaves out (breaks, paragraph marks,
    /// empty runs, forced wraps) and the routes from each track into the
    /// next (the owner, 2026-11-22: one layer, moved and shown or hidden in
    /// the Layers palette).
    flow_marks,
    /// Layout constraints: their dimensions and equal marks.
    constraints,

    fn label(v: ViewLayer) []const u8 {
        return switch (v) {
            .grid => "Grid",
            .axes => "Axes",
            .guides => "Construction lines",
            .flow_marks => "Flow marks",
            .constraints => "Constraints",
            else => v.check().?.label(),
        };
    }

    fn check(v: ViewLayer) ?CheckLayer {
        return switch (v) {
            .check_strokes => .strokes,
            .check_gaps => .gaps,
            .check_other => .other,
            .simulation => .simulation,
            else => null,
        };
    }

    /// Whether it has anything to show now (check results only once run).
    fn present(v: ViewLayer) bool {
        return if (v.check() != null) checksCurrent() else true;
    }

    /// Shown in the shown space (the document's).
    fn shown(v: ViewLayer) bool {
        return overlayOf(shown_space, v).shown;
    }

    /// Shown or hidden in the shown space: a step of the document's.
    fn toggle(v: ViewLayer) void {
        var st = overlayOf(shown_space, v);
        st.shown = !st.shown;
        setOverlay(shown_space, v, st);
    }

    /// The document's name for it.
    fn overlay(v: ViewLayer) layout.model.Overlay {
        return @enumFromInt(@intFromEnum(v));
    }

    comptime {
        // The same layers, in the same order, as the document's.
        for (@typeInfo(ViewLayer).@"enum".field_names, @typeInfo(layout.model.Overlay).@"enum".field_names) |a_, b_| {
            if (!std.mem.eql(u8, a_, b_)) @compileError("ViewLayer and model.Overlay differ: " ++ a_);
        }
    }
};

/// How many of the document's layers each view layer lies above: 0, below
/// them all; `top`, above them all.
const view_top: u16 = std.math.maxInt(u16);
/// View layer `v`'s state in space `space`: the document's (defaults
/// where there is no such space).
fn overlayOf(space: usize, v: ViewLayer) layout.model.OverlayState {
    if (space >= state.model.spaces.items.len) return (layout.model.Overlays{}).get(v.overlay());
    return state.model.spaces.items[space].overlays.get(v.overlay());
}

/// View layer `v`'s state in space `space` set: one step of the document's.
fn setOverlay(space: usize, v: ViewLayer, st: layout.model.OverlayState) void {
    if (space >= state.model.spaces.items.len) return;
    act(.setOverlay, .{ space, v.overlay(), st.shown, st.below }) catch {};
}

/// Check layer `l` shown in space `space`.
fn checkShown(space: usize, l: CheckLayer) bool {
    const v: ViewLayer = switch (l) {
        .strokes => .check_strokes,
        .gaps => .check_gaps,
        .other => .check_other,
        .simulation => .simulation,
    };
    return overlayOf(space, v).shown;
}

/// Space `space`'s layers and the view's own, bottom first.
fn drawStack(area: dvui.Rect.Physical, space: usize, active: bool) void {
    if (space >= state.model.spaces.items.len) return;
    const n = state.model.spaces.items[space].layers.items.len;
    for (0..n + 1) |i| {
        inline for (comptime std.enums.values(ViewLayer)) |v| if (@min(overlayOf(space, v).below, n) == i) drawViewLayer(area, space, v, active);
        if (i < n) drawSpaceLayer(area, space, 0, i);
    }
}

fn drawViewLayer(area: dvui.Rect.Physical, space: usize, v: ViewLayer, active: bool) void {
    if (!v.shown()) return;
    switch (v) {
        .grid => drawGrid(area),
        .axes => drawAxes(area),
        // Construction lines: the view being worked in.
        .guides => if (active) drawGuides(area),
        .flow_marks => drawFlowMarksLayer(area, space),
        .constraints => drawConstraintsLayer(area, space),
        else => drawChecks(area, space, v.check().?),
    }
}

/// The flow marks of space `space`'s panels: those whose own layer is
/// shown.
fn drawFlowMarksLayer(area: dvui.Rect.Physical, space: usize) void {
    const sp = state.model.spaces.items[space];
    for (0..@min(state.model.parentCount(), state.solved.items.len)) |k| {
        const pi = state.model.parentAt(k);
        if (state.model.spaceOfParent(pi) != space) continue;
        const lid = if (pi.panelIndex()) |i| panelLayer(i) else sp.base_layer;
        const visible = for (sp.layers.items) |l| {
            if (l.id == lid) break l.visible;
        } else true;
        if (!visible) continue;
        drawThreads(area, pi, &state.solved.items[k]);
        drawFlowMarks(area, pi, &state.solved.items[k]);
    }
}

/// One entry of the Layers palette's stack: a document layer (its index,
/// bottom first) or one of the view's own.
const StackEntry = union(enum) { doc: usize, view: ViewLayer };

/// Space `space`'s stack as the palette shows it, bottom first (view
/// layers with nothing to show left out).
fn stackEntries(space: usize, out: []StackEntry) []StackEntry {
    const n = state.model.spaces.items[space].layers.items.len;
    var k: usize = 0;
    for (0..n + 1) |i| {
        for (std.enums.values(ViewLayer)) |v| if (@min(overlayOf(space, v).below, n) == i and v.present() and k < out.len) {
            out[k] = .{ .view = v };
            k += 1;
        };
        if (i < n and k < out.len) {
            out[k] = .{ .doc = i };
            k += 1;
        }
    }
    return out[0..k];
}

/// The SDL blend mode for a layer's blend, on premultiplied colour.
fn sdlBlend(b: layout.model.Blend) dvui.backend.c.SDL_BlendMode {
    const c = dvui.backend.c;
    return switch (b) {
        .normal => c.SDL_ComposeCustomBlendMode(c.SDL_BLENDFACTOR_ONE, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_ALPHA, c.SDL_BLENDOPERATION_ADD, c.SDL_BLENDFACTOR_ONE, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_ALPHA, c.SDL_BLENDOPERATION_ADD),
        // src·dst + dst·(1 − src alpha)
        .multiply => c.SDL_ComposeCustomBlendMode(c.SDL_BLENDFACTOR_DST_COLOR, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_ALPHA, c.SDL_BLENDOPERATION_ADD, c.SDL_BLENDFACTOR_ONE, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_ALPHA, c.SDL_BLENDOPERATION_ADD),
        // src + dst·(1 − src)
        .screen => c.SDL_ComposeCustomBlendMode(c.SDL_BLENDFACTOR_ONE, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_COLOR, c.SDL_BLENDOPERATION_ADD, c.SDL_BLENDFACTOR_ONE, c.SDL_BLENDFACTOR_ONE_MINUS_SRC_ALPHA, c.SDL_BLENDOPERATION_ADD),
    };
}

/// The images of space `space` on layer `layer`, at their physical size,
/// blended as the layer says.
fn drawImages(area: dvui.Rect.Physical, space: usize, layer: layout.model.ObjectId, blend: layout.model.Blend) void {
    const sp = state.model.spaces.items[space];
    const px = dvui.windowNaturalScale();
    for (sp.images.items, 0..) |im, ii| {
        if ((if (im.layer == .none) sp.base_layer else im.layer) != layer) continue;
        const r = state.view.rect(area, im.box());
        const src: dvui.ImageSource = .{ .imageFile = .{ .bytes = im.data, .name = im.name } };
        const tex = src.getTexture() catch {
            r.stroke(.square, .{ .thickness = px, .color = .{ .color = colors.overflow } });
            continue;
        };
        if (dvui.backend.kind == .sdl3) _ = dvui.backend.c.SDL_SetTextureBlendMode(@ptrCast(@alignCast(tex.ptr)), sdlBlend(blend));
        // The layer's opacity in the image's own colour: drawing may be
        // replayed after the current alpha is back to 1.
        const a = dvui.currentWindow().alpha;
        dvui.alphaSet(1);
        // The display's white level dims it; its gamma cannot reach pixels.
        dvui.renderTexture(tex, .{ .r = r, .s = px }, .{ .colormod = docColor(.{ .r = 255, .g = 255, .b = 255 }).opacity(a) }) catch {};
        dvui.alphaSet(a);
        const sel = switch (state.context) {
            .image => |c| c.space == space and c.index == ii,
            else => false,
        };
        if (sel) marchingBox(area, im.box(), colors.select, 2 * px);
    }
}

/// The top-most image of the shown space under `at` on an open layer.
fn imageUnder(at: geom.Point) ?Context {
    if (shown_space >= state.model.spaces.items.len) return null;
    const sp = state.model.spaces.items[shown_space];
    var hit: ?Context = null;
    var hit_layer: usize = 0;
    for (sp.images.items, 0..) |im, ii| {
        if (!contains(im.box(), at) or !layerOpen(shown_space, im.layer)) continue;
        const li = sp.layerIndex(im.layer) orelse 0;
        if (hit == null or li >= hit_layer) {
            hit = .{ .image = .{ .space = shown_space, .index = ii } };
            hit_layer = li;
        }
    }
    return hit;
}

/// The layer flags of layer `li` of space `space`, as text lines.
fn layerFlags(space: usize, li: usize, n: usize) void {
    for (state.layer_issues) |iss| {
        if (iss.space != space or iss.layer != li) continue;
        const sp = state.model.spaces.items[space];
        const l = sp.layers.items[li];
        var buf: [160]u8 = undefined;
        const text = switch (iss.kind) {
            .blend_ignored => std.fmt.bufPrint(&buf, "Opacity and blending mean nothing to {s}: what is made ignores them.", .{@tagName(l.output)}) catch "",
            .low_resolution => std.fmt.bufPrint(&buf, "{s} prints at {d:.0} dpi, under {d:.0}.", .{ sp.images.items[iss.image.?].name, sp.images.items[iss.image.?].dpi(), layout.model.min_print_dpi }) catch "",
        };
        // Wrapped: a flag is read in full.
        var tl = dvui.textLayout(@src(), .{}, .{ .id_extra = n + 100 * @as(usize, @intFromEnum(iss.kind)) + (iss.image orelse 0), .expand = .horizontal, .background = false, .margin = .{ .y = 4 } });
        tl.addText(text, .{ .color_text = .{ .color = colors.overflow } });
        tl.deinit();
    }
}

// Manufacturing plans and the manufacturing view ---------------------------------
//
// A plan (layout's manufacture.zig) says what a product's parts are made of
// and the operations that make them. Its properties are the plan's editor:
// its parts, each with a material; its operations in order, each a process
// over stackup layers of the parts, with the colour it gives on each (from
// what that process can give on that material); the warnings. A
// manufacturing view shows the parts as the plan makes them, from above,
// each operation a layer shown or hidden; a 3D view through OCCT is to
// follow (blueprint "Manufacturing visualization through OCCT").

const manufacture = layout.model.manufacture;
const ObjectId = layout.model.ObjectId;

/// Operations hidden in manufacturing views, by plan and index; for the
/// session.
var op_hidden: std.AutoHashMapUnmanaged(u64, void) = .empty;

fn opKey(plan: ObjectId, i: usize) u64 {
    return mergeKey(.{ "operation shown", plan, i });
}

fn opShown(plan: ObjectId, i: usize) bool {
    return !op_hidden.contains(opKey(plan, i));
}

/// The plans: how many, the active one, a new one.
fn plansProperties() void {
    const saved_group = pushGroup("plans");
    defer popGroup(saved_group);
    const m = &state.model;
    propText("Plans", "{d}", .{m.plans.items.len}, 1);
    if (m.activePlan()) |p| propText("Exported", "{s}", .{p.name}, 2);
    keyButton(@src(), "Add a plan", 0, .{ .expand = .horizontal, .id_extra = 3, .margin = .{ .y = 6 } });
}

/// A plan in the Browser: opened in a manufacturing view, and edited.
fn planProperties(id: ObjectId) void {
    const saved_group = pushGroup("plan");
    defer popGroup(saved_group);
    keyButton(@src(), "Open in a manufacturing view", 0, .{ .expand = .horizontal, .id_extra = 90 });
    planEditor(id);
}

/// Opens (or shows) a manufacturing view of plan `id`, as a tab.
fn showManufactureView(id: ObjectId) void {
    var buf: [docviews.max_views]u8 = undefined;
    const have = vl.viewsOf(.manufacture, @intFromEnum(id), &buf);
    if (have.len > 0) {
        activateView(have[0]);
        return;
    }
    const leaf = vl.leafOf(vl.active) orelse return;
    _ = openInWindow(leaf, .{ .kind = .manufacture, .target = @intFromEnum(id) }, 0, true);
}

/// A copy of plan `p` whose lists can be changed (the frame's arena).
fn planCopy(p: manufacture.Plan) manufacture.Plan {
    const ar = dvui.currentWindow().arena();
    var c = p;
    c.parts = ar.dupe(manufacture.Part, p.parts) catch p.parts;
    const ops = ar.alloc(manufacture.Operation, p.operations.len) catch return c;
    for (p.operations, ops) |op, *d| {
        d.* = op;
        d.targets = ar.dupe(manufacture.Target, op.targets) catch op.targets;
    }
    c.operations = ops;
    return c;
}

/// A dropdown row: `label`, then `names`; the entry chosen when it
/// changes.
fn choiceRow(label: []const u8, names: []const []const u8, current: usize, n: usize) ?usize {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(label);
    var choice = current;
    if (!tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n }) or choice == current) return null;
    return choice;
}

fn panelNameOf(id: ObjectId) []const u8 {
    const pi = state.model.panelIndex(id) orelse return "(a panel no longer there)";
    return state.model.panels.items[pi].name;
}

/// A material choice: none, the document's, then the library's it has not
/// (chosen, one is added to the document). Returns the material's ID, or
/// null when unchanged.
fn materialChoice(label: []const u8, current: ObjectId, key: u64, n: usize) ?ObjectId {
    const m = &state.model;
    const ar = dvui.currentWindow().arena();
    var names: std.ArrayList([]const u8) = .empty;
    var ids: std.ArrayList(?ObjectId) = .empty;
    var lib: std.ArrayList(?usize) = .empty;
    names.append(ar, "none") catch return null;
    ids.append(ar, .none) catch return null;
    lib.append(ar, null) catch return null;
    for (m.materials.items) |mt| {
        names.append(ar, mt.material.name) catch return null;
        ids.append(ar, mt.id) catch return null;
        lib.append(ar, null) catch return null;
    }
    for (manufacture.library, 0..) |lm, k| {
        const have = for (m.materials.items) |mt| {
            if (std.mem.eql(u8, mt.material.name, lm.name)) break true;
        } else false;
        if (have) continue;
        names.append(ar, std.fmt.allocPrint(ar, "{s} (library)", .{lm.name}) catch return null) catch return null;
        ids.append(ar, null) catch return null;
        lib.append(ar, k) catch return null;
    }
    var cur: usize = 0;
    for (ids.items, 0..) |x, k| if (x != null and x.? == current) {
        cur = k;
    };
    const chosen = choiceRow(label, names.items, cur, n) orelse return null;
    if (lib.items[chosen]) |k| return actM(key, .addMaterial, .{manufacture.library[k]}) catch null;
    return ids.items[chosen].?;
}

/// A process choice, as `materialChoice`, from the document's profiles and
/// the built-ins.
fn processChoiceRow(current: ObjectId, key: u64, n: usize) ?ObjectId {
    const m = &state.model;
    const prc = layout.model.process;
    const ar = dvui.currentWindow().arena();
    var names: std.ArrayList([]const u8) = .empty;
    var ids: std.ArrayList(?ObjectId) = .empty;
    var adds: std.ArrayList(?usize) = .empty;
    names.append(ar, "none") catch return null;
    ids.append(ar, .none) catch return null;
    adds.append(ar, null) catch return null;
    for (m.processes.items) |pr| {
        names.append(ar, pr.profile.name) catch return null;
        ids.append(ar, pr.id) catch return null;
        adds.append(ar, null) catch return null;
    }
    for (prc.builtins, 0..) |b, k| {
        const have = for (m.processes.items) |pr| {
            if (std.mem.eql(u8, pr.profile.name, b.name)) break true;
        } else false;
        if (have) continue;
        names.append(ar, std.fmt.allocPrint(ar, "{s} (built in)", .{b.name}) catch return null) catch return null;
        ids.append(ar, null) catch return null;
        adds.append(ar, k) catch return null;
    }
    var cur: usize = 0;
    for (ids.items, 0..) |x, k| if (x != null and x.? == current) {
        cur = k;
    };
    const chosen = choiceRow("Process", names.items, cur, n) orelse return null;
    if (adds.items[chosen]) |k| return actM(key, .addProcess, .{prc.builtins[k]}) catch null;
    return ids.items[chosen].?;
}

/// What a warning says.
fn warningText(buf: []u8, w: manufacture.Warning) []const u8 {
    const panel = panelNameOf(w.panel);
    const op = (w.operation orelse 0) + 1;
    return switch (w.kind) {
        .no_material => std.fmt.bufPrint(buf, "{s} has no material.", .{panel}),
        .unsuited => std.fmt.bufPrint(buf, "Operation {d} on {s}: {s}.", .{ op, panel, if (w.why.len > 0) w.why else "its process does not suit the material" }),
        .colour_unavailable => std.fmt.bufPrint(buf, "Operation {d}: {s} cannot be given that colour on {s}'s material.", .{ op, w.layer, panel }),
        .mark_after_cut => std.fmt.bufPrint(buf, "Operation {d} marks {s} after it was cut free: it may have moved (mark first).", .{ op, panel }),
        .no_such_target => std.fmt.bufPrint(buf, "Operation {d} names {s}{s}{s}, which is not one of the plan's parts' layers.", .{ op, panel, if (w.layer.len > 0) " · " else "", w.layer }),
        .unmade_layer => std.fmt.bufPrint(buf, "{s} · {s}: no operation makes it.", .{ panel, w.layer }),
        .too_thick => std.fmt.bufPrint(buf, "Operation {d}: {s} is thicker than its process cuts.", .{ op, panel }),
        .no_process => std.fmt.bufPrint(buf, "Operation {d} has no process.", .{op}),
    } catch "";
}

/// Plan `id`'s editor: its name and whether it is the one exported; its
/// parts and their materials; its operations, each with its process,
/// passes, the layers it makes and their colours; the warnings.
fn planEditor(id: ObjectId) void {
    const saved_group = pushGroup("plan");
    defer popGroup(saved_group);
    const m = &state.model;
    const pi = m.planIndex(id) orelse return;
    const p = m.plans.items[pi];
    const ar = dvui.currentWindow().arena();
    heading("Plan", .{}, 100);
    if (textProp("Name", p.name, 101)) |v| {
        var n = planCopy(p);
        n.name = v;
        actM(mergeKey(.{ "plan name", id }), .setPlan, .{ id, n }) catch {};
    }
    if (m.active_plan == id) {
        propText("Exported", "{s}", .{"this plan"}, 102);
    } else keyButton(@src(), "Export this plan (make it active)", 0, .{ .expand = .horizontal, .id_extra = 102 });

    // How the plan's view shows it, when one is active.
    if (activeKind() == .manufacture and vl.views[vl.active].target == @intFromEnum(id)) {
        const cam = &cams[vl.active];
        const names = [_][]const u8{ "From above", if (occt3d.available) "3D, through OCCT" else "3D, through OCCT (not in this build)" };
        if (choiceRow("Shown as", &names, if (cam.on) 1 else 0, 103)) |k| {
            cam.on = k == 1;
            cam.set = false;
            if (cam.on and !occt3d.available) state.status = "This build has no OCCT: build the GUI with -Docct-prebuilt for 3D views. ";
        }
    }
    if (numberProp("Max error, mm", p.tolerance, 0.001, 1, 104)) |v| {
        var n = planCopy(p);
        n.tolerance = v;
        actM(mergeKey(.{ "plan tolerance", id }), .setPlan, .{ id, n }) catch {};
    }
    planChecksSection(id);

    // Parts, each with its material.
    heading("Parts", .{}, 110);
    for (p.parts, 0..) |pt, k| {
        const key = mergeKey(.{ "part material", id, k, m.materials.items.len });
        listItem("plan.part", panelNameOf(pt.panel));
        if (materialChoice(panelNameOf(pt.panel), pt.material, key, 111 + k)) |mid| {
            const n = planCopy(p);
            @constCast(n.parts)[k].material = mid;
            actM(key, .setPlan, .{ id, n }) catch {};
        }
    }
    {
        var names: std.ArrayList([]const u8) = .empty;
        var pids: std.ArrayList(ObjectId) = .empty;
        names.append(ar, "choose a panel") catch return;
        pids.append(ar, .none) catch return;
        for (m.panels.items) |pn| {
            if (pn.id == .none or p.part(pn.id) != null) continue;
            names.append(ar, pn.name) catch return;
            pids.append(ar, pn.id) catch return;
        }
        if (names.items.len > 1) if (choiceRow("Add a part", names.items, 0, 180)) |k| {
            var n = planCopy(p);
            var parts: std.ArrayList(manufacture.Part) = .empty;
            parts.appendSlice(ar, n.parts) catch return;
            parts.append(ar, .{ .panel = pids.items[k] }) catch return;
            n.parts = parts.items;
            act(.setPlan, .{ id, n }) catch {};
        };
    }

    // Operations, in order (a new one goes last).
    heading("Operations", .{}, 189);
    keyButton(@src(), "Add an operation", 0, .{ .expand = .horizontal, .id_extra = 190 });
    for (0..p.operations.len) |k| operationEditor(id, p, k, 200 + 100 * k) catch {};

    // What is worth a second look.
    const ws = manufacture.warnings(ar, m, p) catch &.{};
    headingAs("plan.warnings", "{s}", .{if (ws.len == 0) "No warnings" else "Warnings"}, 95);
    for (ws, 0..) |w, k| {
        var buf: [256]u8 = undefined;
        var tl = dvui.textLayout(@src(), .{}, .{ .id_extra = 96 + 1000 * k, .expand = .horizontal, .background = false, .margin = .{ .y = 2 } });
        tl.addText(warningText(&buf, w), .{ .color_text = .{ .color = colors.overflow } });
        tl.deinit();
    }
    endSection();
    keyButton(@src(), "Remove this plan", 0, .{ .expand = .horizontal, .id_extra = 98, .margin = .{ .y = 10 } });
}

/// Operation `k` of plan `p`: shown in the view, moved, removed; its name,
/// process and passes; the stackup layers it makes, each with a colour.
fn operationEditor(id: ObjectId, p: manufacture.Plan, k: usize, n0: usize) !void {
    const saved_group = pushGroup("plan.operation");
    defer popGroup(saved_group);
    const m = &state.model;
    const ar = dvui.currentWindow().arena();
    const op = p.operations[k];
    headingAs(scopeIdN("plan.operation", k + 1), "{d}. {s}", .{ k + 1, op.name }, n0);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n0 });
        defer row.deinit();
        var shown = opShown(id, k);
        if (tcheckbox(@src(), &shown, "Shown", .{ .id_extra = n0 })) {
            if (shown) _ = op_hidden.remove(opKey(id, k)) else op_hidden.put(state.gpa, opKey(id, k), {}) catch {};
        }
        if (k > 0) keyButton(@src(), "Earlier", @intCast(k), .{ .id_extra = n0 + 1 });
        if (k + 1 < p.operations.len) keyButton(@src(), "Later", @intCast(k), .{ .id_extra = n0 + 2 });
        keyButton(@src(), "Remove", @intCast(k), .{ .id_extra = n0 + 3 });
    }
    if (textProp("Name", op.name, n0 + 4)) |v| {
        const n = planCopy(p);
        @constCast(n.operations)[k].name = v;
        actM(mergeKey(.{ "operation name", id, k }), .setPlan, .{ id, n }) catch {};
    }
    const pkey = mergeKey(.{ "operation process", id, k, m.processes.items.len });
    if (processChoiceRow(op.process, pkey, n0 + 5)) |pid| {
        const n = planCopy(p);
        @constCast(n.operations)[k].process = pid;
        actM(pkey, .setPlan, .{ id, n }) catch {};
    }
    if (numberProp("Passes", @floatFromInt(op.passes), 1, 100, n0 + 6)) |v| {
        const n = planCopy(p);
        @constCast(n.operations)[k].passes = @intFromFloat(@round(v));
        actM(mergeKey(.{ "operation passes", id, k }), .setPlan, .{ id, n }) catch {};
    }
    if (opCheckCounts(id, k)) |cc| propText("Checked", "{d} failing, {d} marginal · {d} paths", .{ cc.fails, cc.marginal, cc.paths }, n0 + 7);
    const prof = m.profileById(op.process);
    // Each part's stackup layers: made by it or not, and in what colour.
    var j: usize = 0;
    for (p.parts) |pt| {
        const pidx = m.panelIndex(pt.panel) orelse continue;
        const pn = m.panels.items[pidx];
        const mat: ?manufacture.Material = if (m.materialIndex(pt.material)) |mi| m.materials.items[mi].material else null;
        const palette: []const manufacture.Finish = if (prof != null and mat != null) try manufacture.results(ar, prof.?.kind(), mat.?) else &.{};
        for (pn.fab.layers) |l| {
            defer j += 1;
            const ti: ?usize = for (op.targets, 0..) |t, x| {
                if (t.panel == pt.panel and std.mem.eql(u8, t.layer, l.name)) break x;
            } else null;
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n0 + 10 + j });
            defer row.deinit();
            var on = ti != null;
            const label = try std.fmt.allocPrint(ar, "{s} · {s}", .{ pn.name, l.name });
            if (tcheckbox(@src(), &on, label, .{ .id_extra = n0 + 10 + j })) {
                const n = planCopy(p);
                var ts: std.ArrayList(manufacture.Target) = .empty;
                for (op.targets) |t| if (!(t.panel == pt.panel and std.mem.eql(u8, t.layer, l.name))) try ts.append(ar, t);
                if (on) {
                    // Its own colour, where the process can give it.
                    const own: ?manufacture.Finish = switch (l.op) {
                        .add, .inlay => |c| c,
                        .subtract => null,
                    };
                    // Its own colour where the process gives it; else the
                    // first the process gives (a laser's mark), if any.
                    const same = if (own) |c| for (palette) |f| {
                        if (std.mem.eql(u8, f.name, c.name)) break f;
                    } else null else null;
                    const first: ?manufacture.Finish = if (palette.len > 0 and l.op != .subtract) palette[0] else null;
                    const keep = same orelse first;
                    try ts.append(ar, .{ .panel = pt.panel, .layer = l.name, .colour = keep });
                }
                @constCast(n.operations)[k].targets = ts.items;
                act(.setPlan, .{ id, n }) catch {};
                return;
            }
            const x = ti orelse continue;
            // Its colour: none, or one the process gives on this material.
            const cur = op.targets[x].colour;
            var names: std.ArrayList([]const u8) = .empty;
            try names.append(ar, "no colour of its own");
            for (palette) |f| try names.append(ar, f.name);
            var at: usize = 0;
            if (cur) |c| {
                for (palette, 1..) |f, q| if (std.mem.eql(u8, f.name, c.name)) {
                    at = q;
                };
                if (at == 0) {
                    try names.append(ar, try std.fmt.allocPrint(ar, "{s} (not available)", .{c.name}));
                    at = names.items.len - 1;
                }
            }
            var choice = at;
            if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n0 + 10 + j }) and choice != at and choice <= palette.len) {
                const n = planCopy(p);
                const ts = @constCast(@constCast(n.operations)[k].targets);
                ts[x].colour = if (choice == 0) null else palette[choice - 1];
                act(.setPlan, .{ id, n }) catch {};
            }
        }
    }
}

/// The materials: how many, and new ones from the library.
fn materialsProperties() void {
    const saved_group = pushGroup("materials");
    defer popGroup(saved_group);
    propText("Materials", "{d}", .{state.model.materials.items.len}, 1);
    heading("Add from the library", .{}, 10);
    for (manufacture.library, 0..) |lm, i| {
        keyButton(@src(), lm.name, @intCast(i), .{ .expand = .horizontal, .id_extra = 11 + i, .tag = listTag("materials.library", lm.name) });
    }
}

/// A material: its name; what it is, how it comes, its surface and
/// colours; the plans' parts made of it; its removal while unused.
fn materialProperties(id: ObjectId) void {
    const saved_group = pushGroup("material");
    defer popGroup(saved_group);
    const m = &state.model;
    const i = m.materialIndex(id) orelse return;
    const x = m.materials.items[i].material;
    if (textProp("Name", x.name, 1)) |v| {
        var n = x;
        n.name = v;
        actM(mergeKey(.{ "material name", id }), .setMaterial, .{ id, n }) catch {};
    }
    propText("Kind", "{s}", .{x.kind.label()}, 2);
    propText("Comes as", "{s}", .{x.form.label()}, 3);
    propText("Surface", "{s}", .{x.surface.label()}, 4);
    var buf: [256]u8 = undefined;
    var w: std.Io.Writer = .fixed(&buf);
    for (x.finishes, 0..) |f, k| w.print("{s}{s}", .{ if (k > 0) ", " else "", f.name }) catch break;
    propText("Colours", "{s}", .{w.buffered()}, 5);
    if (x.core) |c| propText("Under it", "{s}", .{c.name}, 6);
    if (x.thicknesses.len > 0) {
        var tb: [128]u8 = undefined;
        var tw: std.Io.Writer = .fixed(&tb);
        for (x.thicknesses, 0..) |t, k| tw.print("{s}{d}", .{ if (k > 0) ", " else "", t }) catch break;
        propText("Thicknesses, mm", "{s}", .{tw.buffered()}, 7);
    }
    heading("Used by", .{}, 20);
    var used: usize = 0;
    for (m.plans.items, 0..) |pl, k| for (pl.parts) |pt| if (pt.material == id) {
        var lb: [160]u8 = undefined;
        const text = std.fmt.bufPrint(&lb, "{s}: {s}", .{ pl.name, panelNameOf(pt.panel) }) catch pl.name;
        keyButton(@src(), text, idArg(pl.id), .{ .expand = .horizontal, .id_extra = 21 + 50 * k + used, .tag = listTag("material.plan", text) });
        used += 1;
    };
    if (used == 0) {
        propText("Parts", "none", .{}, 19);
        keyButton(@src(), "Remove this material", 0, .{ .expand = .horizontal, .id_extra = 18, .margin = .{ .y = 8 } });
    }
}

/// A plan's parts as made, from above, for drawing: per part, each stackup
/// layer's geometry resolved; rebuilt when the document changes.
const MfgLayer = struct { name: []const u8, cut: bool, own: ?layout.model.FabColour, region: geom.fill.Region };
const MfgPart = struct { panel: usize, layers: []const MfgLayer };
var mfg_arena: ?std.heap.ArenaAllocator = null;
var mfg_parts: []const MfgPart = &.{};
var mfg_rev: u64 = std.math.maxInt(u64);
var mfg_gen: u64 = 0;
var mfg_plan: ObjectId = .none;

fn mfgGeometry(plan: manufacture.Plan) []const MfgPart {
    const m = &state.model;
    if (mfg_rev == m.revision and mfg_gen == doc_generation and mfg_plan == plan.id) return mfg_parts;
    if (state.placed_rev != m.revision) return mfg_parts;
    if (mfg_arena) |*ar| ar.deinit();
    mfg_arena = .init(state.gpa);
    const a = mfg_arena.?.allocator();
    var parts: std.ArrayList(MfgPart) = .empty;
    for (plan.parts) |pt| {
        const pi = m.panelIndex(pt.panel) orelse continue;
        const fp = layout.fab.plan(a, m, pi, placedOf(.{ .panel = pi }) orelse continue, faceTable()) catch continue;
        var layers: std.ArrayList(MfgLayer) = .empty;
        for (fp.steps) |st| {
            const l = m.panels.items[pi].fab.layers[st.layer];
            var loops: std.ArrayList([]const geom.Point) = .empty;
            for (st.pieces) |pc| for (pc.contours) |cn| {
                const pts = geom.grow.flatten(a, cn, plan.tolerance) catch continue;
                if (pts.len >= 3) loops.append(a, pts) catch continue;
            };
            const region = geom.fill.nonzero(a, loops.items, 1e-5) catch continue;
            layers.append(a, .{ .name = l.name, .cut = st.op == .subtract, .own = switch (l.op) {
                .add, .inlay => |c| c,
                .subtract => null,
            }, .region = region }) catch continue;
        }
        parts.append(a, .{ .panel = pi, .layers = layers.items }) catch continue;
    }
    mfg_parts = parts.items;
    mfg_rev = m.revision;
    mfg_gen = doc_generation;
    mfg_plan = plan.id;
    return mfg_parts;
}

fn finishColor(f: layout.model.FabColour) dvui.Color {
    return display.fix(dvui.Color{ .r = f.color.r, .g = f.color.g, .b = f.color.b });
}

/// A plan's checks, last run (by hand: C in its view, or Check this plan):
/// each operation's, per part it works on, against its own process, with
/// its simulation; drawn in the plan's view under the operation's layer.
const OpChecked = struct {
    op: usize,
    panel: usize,
    report: layout.check.Report,
    areas: []const ?geom.fill.Region,
};
var plan_checks_arena: ?std.heap.ArenaAllocator = null;
var plan_checks: []const OpChecked = &.{};
var plan_checks_plan: ObjectId = .none;
var plan_checks_rev: u64 = 0;
var plan_checks_gen: u64 = 0;
var plan_findings_shown = true;
var plan_simulation_shown = true;

fn planChecksFor(id: ObjectId) bool {
    return plan_checks_plan == id and plan_checks_gen == doc_generation and plan_checks_arena != null;
}

fn clearPlanChecks() void {
    if (plan_checks_arena) |*ar| ar.deinit();
    plan_checks_arena = null;
    plan_checks = &.{};
    plan_checks_plan = .none;
}

/// Checks plan `id`: every operation, on each part it works on.
fn runPlanChecks(id: ObjectId) void {
    const m = &state.model;
    const pi = m.planIndex(id) orelse return;
    const plan = m.plans.items[pi];
    if (state.placed_rev != m.revision) {
        state.status = "The panels are still being laid out: check again in a moment. ";
        return;
    }
    if (check_cache != null and check_cache_gen != doc_generation) {
        check_cache.?.deinit();
        check_cache = null;
    }
    if (check_cache == null) {
        check_cache = .init(state.gpa);
        check_cache_gen = doc_generation;
    }
    clearPlanChecks();
    plan_checks_arena = .init(state.gpa);
    const a = plan_checks_arena.?.allocator();
    var list: std.ArrayList(OpChecked) = .empty;
    const t0 = std.Io.Clock.awake.now(dvui.io);
    var fails: usize = 0;
    var marginal: usize = 0;
    for (plan.operations, 0..) |op, k| {
        const prof = m.profileById(op.process) orelse continue;
        for (plan.parts) |pt| {
            const panel = m.panelIndex(pt.panel) orelse continue;
            const placed = placedOf(.{ .panel = panel }) orelse continue;
            const any = for (op.targets) |t| {
                if (t.panel == pt.panel) break true;
            } else false;
            if (!any) continue;
            const report = layout.check.runWith(a, m, panel, placed, faceTable(), &check_cache.?, .{ .profile = prof.*, .targets = op.targets, .tolerance = plan.tolerance }) catch continue;
            const areas = a.alloc(?geom.fill.Region, report.findings.len) catch return;
            for (report.findings, areas) |f, *r| {
                r.* = null;
                switch (f.verdict) {
                    .fail => fails += 1,
                    .marginal => marginal += 1,
                    .pass => {},
                }
                const o = f.area orelse continue;
                var loops: std.ArrayList([]const geom.Point) = .empty;
                for (o.contours) |cn| {
                    const pts = geom.grow.flatten(a, cn, report.tolerance) catch continue;
                    loops.append(a, pts) catch continue;
                }
                r.* = geom.fill.nonzero(a, loops.items, report.tolerance * 1e-3) catch null;
            }
            list.append(a, .{ .op = k, .panel = panel, .report = report, .areas = areas }) catch return;
        }
    }
    plan_checks = list.items;
    plan_checks_plan = id;
    plan_checks_rev = m.revision;
    plan_checks_gen = doc_generation;
    const ms = @as(f64, @floatFromInt(t0.durationTo(std.Io.Clock.awake.now(dvui.io)).nanoseconds)) / 1e6;
    state.status = std.fmt.bufPrint(&check_status_buf, "Checked {s}'s {d} operation{s} in {d:.0} ms: {d} failing, {d} marginal. ", .{ plan.name, plan.operations.len, if (plan.operations.len == 1) "" else "s", ms, fails, marginal }) catch "Checked. ";
    dvui.refresh(null, @src(), null);
}

/// Operation `k`'s last results, summed over its parts.
fn opCheckCounts(id: ObjectId, k: usize) ?struct { fails: usize, marginal: usize, paths: usize } {
    if (!planChecksFor(id)) return null;
    var fails: usize = 0;
    var marginal: usize = 0;
    var paths: usize = 0;
    var any = false;
    for (plan_checks) |oc| if (oc.op == k) {
        any = true;
        fails += oc.report.count(.stroke, .fail) + oc.report.count(.gap, .fail) + oc.report.count(.cap, .fail) + oc.report.count(.depth, .fail) + oc.report.count(.colours, .fail) + oc.report.count(.size, .fail);
        marginal += oc.report.count(.stroke, .marginal) + oc.report.count(.gap, .marginal) + oc.report.count(.cap, .marginal) + oc.report.count(.depth, .marginal);
        paths += oc.report.paths.len;
    };
    return if (any) .{ .fails = fails, .marginal = marginal, .paths = paths } else null;
}

/// The plan's checks in its editor: run, and the two result layers shown
/// or hidden.
fn planChecksSection(id: ObjectId) void {
    const saved_group = pushGroup("plan.checks");
    defer popGroup(saved_group);
    const stale = planChecksFor(id) and plan_checks_rev != state.model.revision;
    headingAs("plan.checks", "{s}", .{if (stale) "Checks (out of date)" else "Checks"}, 140);
    keyButton(@src(), "Check this plan", 0, .{ .expand = .horizontal, .id_extra = 141 });
    if (!planChecksFor(id)) return;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 142 });
        defer row.deinit();
        _ = tcheckbox(@src(), &plan_findings_shown, "Findings", .{ .id_extra = 143 });
        _ = tcheckbox(@src(), &plan_simulation_shown, "Simulation", .{ .id_extra = 144 });
    }
    keyButton(@src(), "Clear results", 0, .{ .expand = .horizontal, .id_extra = 145 });
}

/// A plan's check results over its view: per operation shown, its
/// simulated paths, then its findings.
fn drawPlanChecks(area: dvui.Rect.Physical, id: ObjectId) void {
    if (!planChecksFor(id)) return;
    const px = dvui.windowNaturalScale();
    const marginal = display.fix(dvui.Color{ .r = 0xe0, .g = 0x00, .b = 0xd0 });
    const failing = display.fix(dvui.Color{ .r = 0xe0, .g = 0x20, .b = 0x1b });
    const lifo = dvui.currentWindow().lifo();
    for (plan_checks) |oc| {
        if (!opShown(id, oc.op) or oc.panel >= state.model.panels.items.len) continue;
        const at = panelOrigin(oc.panel);
        if (plan_simulation_shown) for (oc.report.paths) |path| {
            if (path.points.len < 2) continue;
            const pts = lifo.alloc(dvui.Point.Physical, path.points.len) catch continue;
            defer lifo.free(pts);
            for (path.points, pts) |q, *o| o.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
            const c = path.colour.color;
            const w: f32 = @max(px, @as(f32, @floatCast(path.width * 0.8 * state.view.ppm)) * px);
            dvui.Path.stroke(.{ .points = pts }, .{ .thickness = w, .color = .{ .color = display.fix(dvui.Color{ .r = c.r, .g = c.g, .b = c.b }).opacity(0.75) }, .closed = true });
        };
        if (plan_findings_shown) for (oc.report.findings, oc.areas) |f, region| {
            const colour = if (f.verdict == .fail) failing else marginal;
            if (region) |r| {
                fillRegion(area, r, at, .{ .flat = colour.opacity(0.8) });
            } else state.view.rect(area, onSheet(.{ .panel = oc.panel }, f.box)).stroke(.square, .{ .thickness = 2 * px, .color = .{ .color = colour } });
        };
    }
}

// The manufacturing view in 3D, through OCCT -------------------------------------
//
// A plan's parts built as solids and meshed by OCCT (bridge/occt/view3d.zig;
// a stub, saying so, when the GUI is built without OCCT), drawn here:
// triangles back to front, shaded by their facing. A drag orbits, Shift and
// a drag pans, the wheel zooms.

const occt3d = @import("graven_occt3d");

const Cam3d = struct {
    on: bool = false,
    set: bool = false,
    yaw: f64 = -0.5,
    pitch: f64 = 0.85,
    ppm: f64 = 1,
    target: [3]f64 = .{ 0, 0, 0 },
};
var cams: [docviews.max_views]Cam3d = @splat(.{});

var mesh_arena: ?std.heap.ArenaAllocator = null;
var mesh: occt3d.Mesh = .{};
var mesh_plan: ObjectId = .none;
var mesh_rev: u64 = std.math.maxInt(u64);
var mesh_gen: u64 = 0;
var mesh_ms: f64 = 0;
var mesh_failed: ?[]const u8 = null;

/// Part `pi`'s fabrication steps as plan `plan` makes them: only the
/// stackup layers its operations work on, each added one in the colour the
/// plan gives it, else the part's material's, else its own.
fn planSteps(a: std.mem.Allocator, plan: manufacture.Plan, pi: usize) ![]const layout.fab.Step {
    const m = &state.model;
    const pn = m.panels.items[pi];
    const part = plan.part(pn.id) orelse return &.{};
    const mat_colour: ?layout.model.FabColour = if (m.materialIndex(part.material)) |mi| (if (m.materials.items[mi].material.finishes.len > 0) m.materials.items[mi].material.finishes[0] else null) else null;
    const fp = try layout.fab.plan(a, m, pi, placedOf(.{ .panel = pi }) orelse return &.{}, faceTable());
    var out: std.ArrayList(layout.fab.Step) = .empty;
    for (fp.steps) |st| {
        const name = pn.fab.layers[st.layer].name;
        var made = false;
        var given: ?layout.model.FabColour = null;
        for (plan.operations) |op| for (op.targets) |t| {
            if (t.panel != pn.id or !std.mem.eql(u8, t.layer, name)) continue;
            made = true;
            if (t.colour) |c| given = c;
        };
        if (!made) continue;
        var s2 = st;
        switch (st.op) {
            .add => |own| s2.op = .{ .add = given orelse mat_colour orelse own },
            .subtract => {},
        }
        try out.append(a, s2);
    }
    return out.items;
}

/// A 3D build in the background: the slabs made here, OCCT's sweeping and
/// meshing in a worker (they take seconds), the result taken up when done.
const MeshJob = struct {
    arena: std.heap.ArenaAllocator,
    plan: ObjectId,
    rev: u64,
    gen: u64,
    /// The plan's tolerance: OCCT's mesh deflection.
    tolerance: f64,
    parts: []const struct { slabs: []const layout.fab.Slab, offset: [2]f64 },
    result: occt3d.Mesh = .{},
    failed: ?[]const u8 = null,
    ms: f64 = 0,
    done: std.atomic.Value(bool) = .init(false),
    thread: ?std.Thread = null,

    fn run(job: *MeshJob) void {
        const a = job.arena.allocator();
        var clock = Clock.start();
        for (job.parts) |pt| {
            occt3d.meshSlabs(std.heap.c_allocator, a, pt.slabs, pt.offset, job.tolerance, &job.result) catch {
                job.failed = a.dupe(u8, occt3d.lastError()) catch "OCCT failed";
                break;
            };
        }
        job.ms = clock.lap();
        job.done.store(true, .release);
    }
};
var mesh_job: ?*MeshJob = null;

const Clock = struct {
    last: i128,
    fn now() i128 {
        return platform.monotonicNs();
    }
    fn start() Clock {
        return .{ .last = now() };
    }
    fn lap(cl: *Clock) f64 {
        const t = now();
        defer cl.last = t;
        return @as(f64, @floatFromInt(t - cl.last)) / 1e6;
    }
};

/// Takes up a finished build, if there is one.
fn meshJobCollect() void {
    const job = mesh_job orelse return;
    if (!job.done.load(.acquire)) return;
    if (job.thread) |t| t.join();
    if (mesh_arena) |*ar| ar.deinit();
    mesh_arena = job.arena;
    mesh = job.result;
    mesh_failed = job.failed;
    mesh_ms = job.ms;
    mesh_plan = job.plan;
    mesh_rev = job.rev;
    mesh_gen = job.gen;
    state.gpa.destroy(job);
    mesh_job = null;
}

/// Waits for a build under way (at shutdown).
fn meshJobWait() void {
    const job = mesh_job orelse return;
    if (job.thread) |t| t.join();
    job.arena.deinit();
    state.gpa.destroy(job);
    mesh_job = null;
}

/// Plan `plan`'s parts meshed through OCCT, when built: built again, in
/// the background, when the document changes. Null while building (see
/// `mesh_job`) or when it failed (`mesh_failed`).
fn planMesh(plan: manufacture.Plan) ?occt3d.Mesh {
    const m = &state.model;
    meshJobCollect();
    const current = mesh_plan == plan.id and mesh_rev == m.revision and mesh_gen == doc_generation;
    if (current) return if (mesh_failed == null) mesh else null;
    if (!occt3d.available) {
        mesh_failed = occt3d.lastError();
        mesh_plan = plan.id;
        mesh_rev = m.revision;
        mesh_gen = doc_generation;
        return null;
    }
    // One build at a time: a newer one starts when it is done.
    if (mesh_job != null) {
        dvui.refresh(null, @src(), null);
        return null;
    }
    if (state.placed_rev != m.revision) return null;
    const job = state.gpa.create(MeshJob) catch return null;
    job.* = .{ .arena = .init(std.heap.c_allocator), .plan = plan.id, .rev = m.revision, .gen = doc_generation, .tolerance = plan.tolerance, .parts = &.{} };
    const a = job.arena.allocator();
    var clock = Clock.start();
    var parts: std.ArrayList(@typeInfo(@TypeOf(job.parts)).pointer.child) = .empty;
    for (plan.parts) |pt| {
        const pi = m.panelIndex(pt.panel) orelse continue;
        if (placedOf(.{ .panel = pi }) == null) continue;
        const steps = planSteps(a, plan, pi) catch continue;
        const exact = layout.fab.slabs(a, steps) catch continue;
        // For viewing: each region simplified to the plan's tolerance,
        // shared edges alike (geom.simplify); OCCT then sweeps and meshes
        // far fewer edges.
        const slabs = a.alloc(layout.fab.Slab, exact.len) catch continue;
        for (exact, slabs) |sl, *d| {
            const regs = a.alloc(layout.fab.Region, sl.regions.len) catch continue;
            for (sl.regions, regs) |r, *dr| dr.* = .{ .colour = r.colour, .outline = geom.simplify.outline(a, r.outline, plan.tolerance) catch r.outline };
            d.* = .{ .z0 = sl.z0, .z1 = sl.z1, .regions = regs };
        }
        const o = panelOrigin(pi);
        parts.append(a, .{ .slabs = slabs, .offset = .{ o.x, o.y } }) catch continue;
    }
    job.parts = parts.items;
    _ = clock.lap();
    job.thread = std.Thread.spawn(.{}, MeshJob.run, .{job}) catch {
        job.run();
        mesh_job = job;
        meshJobCollect();
        return if (mesh_failed == null) mesh else null;
    };
    mesh_job = job;
    dvui.refresh(null, @src(), null);
    return null;
}

fn vsub(p: [3]f64, q: [3]f64) [3]f64 {
    return .{ p[0] - q[0], p[1] - q[1], p[2] - q[2] };
}
fn vdot(p: [3]f64, q: [3]f64) f64 {
    return p[0] * q[0] + p[1] * q[1] + p[2] * q[2];
}
fn vcross(p: [3]f64, q: [3]f64) [3]f64 {
    return .{ p[1] * q[2] - p[2] * q[1], p[2] * q[0] - p[0] * q[2], p[0] * q[1] - p[1] * q[0] };
}
fn vunit(p: [3]f64) [3]f64 {
    const l = @sqrt(vdot(p, p));
    return if (l > 0) .{ p[0] / l, p[1] / l, p[2] / l } else p;
}
fn v64(p: [3]f32) [3]f64 {
    return .{ p[0], p[1], p[2] };
}

/// The camera's axes: right, up and forward (into the scene). Pitch 0
/// looks straight down; yaw turns about the vertical.
fn camAxes(c: Cam3d) [3][3]f64 {
    const cy = @cos(c.yaw);
    const sy = @sin(c.yaw);
    const cp = @cos(c.pitch);
    const sp = @sin(c.pitch);
    return .{ .{ cy, sy, 0 }, .{ -sy * cp, cy * cp, sp }, .{ -sy * sp, cy * sp, -cp } };
}

/// The mesh drawn as camera `c` sees it, within `area`: triangles facing
/// it, in an order exact for prisms seen from above (see below), each
/// shaded by how it faces a light over the viewer's left shoulder.
fn drawMesh(area: dvui.Rect.Physical, c: Cam3d, ms: occt3d.Mesh) void {
    const ar = dvui.currentWindow().arena();
    const ax = camAxes(c);
    const light = vunit(.{ -ax[2][0] * 0.7 + ax[1][0] * 0.5 - ax[0][0] * 0.3, -ax[2][1] * 0.7 + ax[1][1] * 0.5 - ax[0][1] * 0.3, -ax[2][2] * 0.7 + ax[1][2] * 0.5 - ax[0][2] * 0.3 });
    const cx = area.x + area.w / 2;
    const cy = area.y + area.h / 2;
    // The parts are prisms (flat tops, upright walls) seen from above, so
    // an exact order: up through the heights, at each one the walls
    // reaching up to it (farthest first), then the tops at it. A top hides
    // what is below it in its footprint and nothing below covers it.
    const Item = struct { t: u32, level: f32, top: bool, depth: f32 };
    var items: std.ArrayList(Item) = .empty;
    for (ms.tris, 0..) |t, k| {
        const p0 = v64(ms.pos[t[0]]);
        const p1 = v64(ms.pos[t[1]]);
        const p2 = v64(ms.pos[t[2]]);
        const n = vcross(vsub(p1, p0), vsub(p2, p0));
        if (vdot(n, ax[2]) >= 0) continue;
        const mid: [3]f64 = .{ (p0[0] + p1[0] + p2[0]) / 3, (p0[1] + p1[1] + p2[1]) / 3, (p0[2] + p1[2] + p2[2]) / 3 };
        const nz = @abs(vunit(n)[2]);
        const top = nz > 0.99;
        const level = if (top) mid[2] else @max(p0[2], @max(p1[2], p2[2]));
        items.append(ar, .{ .t = @intCast(k), .level = @floatCast(@round(level * 1e4) / 1e4), .top = top, .depth = @floatCast(vdot(vsub(mid, c.target), ax[2])) }) catch return;
    }
    std.mem.sort(Item, items.items, {}, struct {
        fn far(_: void, x: Item, y: Item) bool {
            if (x.level != y.level) return x.level < y.level;
            if (x.top != y.top) return !x.top;
            return x.depth > y.depth;
        }
    }.far);
    const batch = 6000;
    var from: usize = 0;
    while (from < items.items.len) : (from += batch) {
        const part = items.items[from..@min(from + batch, items.items.len)];
        var b = dvui.Triangles.Builder.init(ar, 3 * part.len, 3 * part.len) catch |e| {
            std.debug.print("3D view: no room for triangles: {s}\n", .{@errorName(e)});
            return;
        };
        for (part, 0..) |it, k| {
            const t = ms.tris[it.t];
            const p0 = v64(ms.pos[t[0]]);
            const n = vunit(vcross(vsub(v64(ms.pos[t[1]]), p0), vsub(v64(ms.pos[t[2]]), p0)));
            const shade: f32 = @floatCast(0.45 + 0.55 * @max(0, vdot(n, light)));
            const col = ms.colour[it.t].color;
            const base = display.fix(dvui.Color{ .r = col.r, .g = col.g, .b = col.b });
            const lit: dvui.Color = .{ .r = @intFromFloat(@as(f32, @floatFromInt(base.r)) * shade), .g = @intFromFloat(@as(f32, @floatFromInt(base.g)) * shade), .b = @intFromFloat(@as(f32, @floatFromInt(base.b)) * shade) };
            var v: [3]dvui.Point.Physical = undefined;
            for (t, &v) |vi, *o| {
                const q = vsub(v64(ms.pos[vi]), c.target);
                o.* = .{ .x = @floatCast(cx + vdot(q, ax[0]) * c.ppm), .y = @floatCast(cy - vdot(q, ax[1]) * c.ppm) };
                b.appendVertex(.{ .pos = o.*, .col = .fromColor(lit) });
            }
            const i: dvui.Vertex.Index = @intCast(3 * k);
            b.appendTriangles(&ccw(v[0], v[1], v[2], i, i + 1, i + 2));
        }
        dvui.renderTriangles(b.build_unowned(), null) catch |e| std.debug.print("3D view: not drawn: {s}\n", .{@errorName(e)});
    }
}

/// Camera `c` fitted to the mesh within `area`.
fn fitCam(c: *Cam3d, area: dvui.Rect.Physical, ms: occt3d.Mesh) void {
    var lo: [3]f64 = .{ std.math.inf(f64), std.math.inf(f64), std.math.inf(f64) };
    var hi: [3]f64 = .{ -std.math.inf(f64), -std.math.inf(f64), -std.math.inf(f64) };
    for (ms.pos) |p| for (0..3) |k| {
        lo[k] = @min(lo[k], p[k]);
        hi[k] = @max(hi[k], p[k]);
    };
    if (!(hi[0] >= lo[0])) return;
    c.target = .{ (lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, (lo[2] + hi[2]) / 2 };
    const span = @max(hi[0] - lo[0], hi[1] - lo[1]);
    c.ppm = 0.85 * @min(area.w, area.h) / @max(span, 1);
    c.set = true;
}

/// Manufacturing view `v`: its plan's parts where they sit on the canvas,
/// each operation a layer (shown or hidden in the plan's properties): what
/// it adds in the colour the plan gives (else the part's material's), what
/// it cuts away showing the backdrop, its edge drawn. Cutting is drawn
/// first, as the stock it shapes; the rest in the plan's order.
/// The wheel zooms, a drag pans; it opens fitted to the parts.
fn manufactureView(v: u8) void {
    const m = &state.model;
    const id: ObjectId = @enumFromInt(vl.views[v].target);
    const pidx = m.planIndex(id) orelse return;
    const plan = m.plans.items[pidx];
    const active = v == vl.active;
    const backdrop = colors.desk;
    var box = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .background = true, .color_fill = .{ .color = backdrop }, .id_extra = v });
    defer box.deinit();
    const area = box.data().contentRectScale().r;
    const parts = mfgGeometry(plan);
    // Where it looks: kept in the view; fitted when not yet set.
    var look: View = .{ .cx = vl.views[v].cx, .cy = vl.views[v].cy, .ppm = vl.views[v].ppm };
    if (!(look.ppm > 0)) {
        var b = geom.Box.empty;
        for (parts) |pt| b = b.join(panelBox(pt.panel));
        if (b.isEmpty()) b = .{ .x0 = 0, .y0 = 0, .x1 = 100, .y1 = 100 };
        look.cx = (b.x0 + b.x1) / 2;
        look.cy = (b.y0 + b.y1) / 2;
        look.ppm = 0.9 * @min(area.w / @max(b.width(), 1), area.h / @max(b.height(), 1));
    }
    const cam = &cams[v];
    for (dvui.events()) |*e| {
        if (e.evt != .mouse) continue;
        const me = e.evt.mouse;
        if (cam.on) {
            // 3D: a drag orbits, with Shift pans; the wheel zooms.
            switch (me.action) {
                .press => if (dvui.eventMatchSimple(e, box.data())) {
                    e.handle(@src(), box.data());
                    if (!active) view_to_activate = v;
                    dvui.captureMouse(box.data(), e.num);
                    mfg_drag = me.p;
                },
                .release => if (dvui.captured(box.data().id)) {
                    e.handle(@src(), box.data());
                    dvui.captureMouse(null, e.num);
                },
                .motion => if (dvui.captured(box.data().id)) {
                    e.handle(@src(), box.data());
                    const dx: f64 = me.p.x - mfg_drag.x;
                    const dy: f64 = me.p.y - mfg_drag.y;
                    if (me.mod.shift()) {
                        const ax = camAxes(cam.*);
                        for (0..3) |k| cam.target[k] += (-dx * ax[0][k] + dy * ax[1][k]) / cam.ppm;
                    } else {
                        cam.yaw -= dx * 0.008;
                        cam.pitch = std.math.clamp(cam.pitch - dy * 0.008, 0, 1.55);
                    }
                    mfg_drag = me.p;
                    dvui.refresh(null, @src(), null);
                },
                .wheel_y => |dy| if (dvui.eventMatchSimple(e, box.data())) {
                    e.handle(@src(), box.data());
                    // About the pointer: what is under it stays there.
                    const z = @exp(@log(1.003) * @as(f64, dy));
                    const ox: f64 = me.p.x - (area.x + area.w / 2);
                    const oy: f64 = me.p.y - (area.y + area.h / 2);
                    const k = (1 - 1 / z) / cam.ppm;
                    const ax = camAxes(cam.*);
                    for (0..3) |q| cam.target[q] += ox * k * ax[0][q] - oy * k * ax[1][q];
                    cam.ppm *= z;
                },
                else => {},
            }
            continue;
        }
        switch (me.action) {
            .press => if (dvui.eventMatchSimple(e, box.data())) {
                e.handle(@src(), box.data());
                if (!active) view_to_activate = v;
                dvui.captureMouse(box.data(), e.num);
                mfg_drag = me.p;
            },
            .release => if (dvui.captured(box.data().id)) {
                e.handle(@src(), box.data());
                text_drag = false;

                dvui.captureMouse(null, e.num);
            },
            .motion => if (dvui.captured(box.data().id)) {
                e.handle(@src(), box.data());
                look.cx -= (me.p.x - mfg_drag.x) / look.ppm;
                look.cy += (me.p.y - mfg_drag.y) / look.ppm;
                mfg_drag = me.p;
                dvui.refresh(null, @src(), null);
            },
            .wheel_y => |dy| if (dvui.eventMatchSimple(e, box.data())) {
                e.handle(@src(), box.data());
                const z = @exp(@log(1.003) * @as(f64, dy));
                const at = look.toMm(area, me.p);
                look.ppm *= z;
                look.cx = at.x - (at.x - look.cx) / z;
                look.cy = at.y - (at.y - look.cy) / z;
            },
            else => {},
        }
    }
    vl.views[v].cx = look.cx;
    vl.views[v].cy = look.cy;
    vl.views[v].ppm = look.ppm;
    // Drawn with the canvas's own drawing, its look swapped in, within
    // the view.
    const prev_clip = dvui.clip(area);
    defer dvui.clipSet(prev_clip);
    if (cam.on) {
        // The parts first: a widget made before them would clip them to
        // itself.
        const got = planMesh(plan);
        if (got) |ms| {
            if (!cam.set) fitCam(cam, area, ms);
            drawMesh(area, cam.*, ms);
        }
        var cap3 = dvui.textLayout(@src(), .{}, .{ .background = true, .color_fill = .{ .color = backdrop.opacity(0.85) }, .gravity_x = 0, .gravity_y = 0, .margin = .all(8), .padding = .all(4), .id_extra = v + 100 });
        var cb3: [200]u8 = undefined;
        if (got) |ms| {
            cap3.addText(std.fmt.bufPrint(&cb3, "{s}, 3D (OCCT, {d} mm): {d} triangles, {d:.0} ms{s}. Drag turns, Shift-drag moves, wheel zooms.", .{ plan.name, plan.tolerance, ms.tris.len, mesh_ms, if (ms.skipped > 0) "; faces too thin for it left out" else "" }) catch "", .{ .color_text = .{ .color = colors.guide } });
        } else if (mesh_job != null) {
            cap3.addText(std.fmt.bufPrint(&cb3, "{s}: building it through OCCT…", .{plan.name}) catch "", .{ .color_text = .{ .color = colors.guide } });
        } else cap3.addText(std.fmt.bufPrint(&cb3, "{s}: no 3D view: {s}.", .{ plan.name, mesh_failed orelse "the panels are still being laid out" }) catch "", .{ .color_text = .{ .color = colors.overflow } });
        cap3.deinit();
        return;
    }
    const saved = state.view;
    state.view = look;
    defer state.view = saved;
    const px = dvui.windowNaturalScale();
    for (parts) |pt| {
        const at = panelOrigin(pt.panel);
        const part = plan.part(m.panels.items[pt.panel].id) orelse continue;
        const mat: ?manufacture.Material = if (m.materialIndex(part.material)) |mi| m.materials.items[mi].material else null;
        const mat_colour: ?layout.model.FabColour = if (mat) |x| (if (x.finishes.len > 0) x.finishes[0] else null) else null;
        // Cutting first, whenever it comes: it shapes the stock without
        // changing its surface; then the rest in the plan's order.
        for ([_]bool{ true, false }) |cutting| for (plan.operations, 0..) |op, k| {
            if (!opShown(plan.id, k)) continue;
            const cuts = if (m.profileById(op.process)) |pr| pr.kind().cuts() else false;
            if (cuts != cutting) continue;
            for (op.targets) |t| {
                if (t.panel != m.panels.items[pt.panel].id) continue;
                for (pt.layers) |l| {
                    if (!std.mem.eql(u8, l.name, t.layer)) continue;
                    if (l.cut) {
                        fillRegion(area, l.region, at, .{ .flat = backdrop });
                        for (l.region.loops) |loop| strokeLoop(area, loop, at, px, colors.guide);
                    } else {
                        const c = t.colour orelse mat_colour orelse l.own orelse continue;
                        fillRegion(area, l.region, at, .{ .flat = finishColor(c) });
                    }
                }
            }
        };
        state.view.rect(area, panelBox(pt.panel)).stroke(.square, .{ .thickness = px, .color = .{ .color = colors.panel_edge.opacity(0.6) } });
    }
    drawPlanChecks(area, id);
    // What it is: the plan, and that a 3D view is to come.
    var cap = dvui.textLayout(@src(), .{}, .{ .background = true, .color_fill = .{ .color = backdrop.opacity(0.85) }, .gravity_x = 0, .gravity_y = 0, .margin = .all(8), .padding = .all(4), .id_extra = v });
    var cb: [160]u8 = undefined;
    cap.addText(std.fmt.bufPrint(&cb, "{s}: from above, operations in order (the plan's properties show or hide each)", .{plan.name}) catch "", .{ .color_text = .{ .color = colors.guide } });
    cap.deinit();
}
var mfg_drag: dvui.Point.Physical = .{};

// Fabrication checks (DRC) and the process's simulation --------------------------
//
// Run only when asked (C, View or File menu, or Check this panel in a
// panel's Fabrication), never as the document changes: the results stand
// as of their run, marked out of date once it has changed. They show as
// result layers above the document's own, each shown or hidden: stroke
// findings, gap findings, the rest (cap height, depths, colours, size),
// and the process simulated (FDM: the walls a slicer would lay). Kept for
// the session, not saved, not undone.

const CheckLayer = enum {
    strokes,
    gaps,
    other,
    simulation,

    fn label(l: CheckLayer) []const u8 {
        return switch (l) {
            .strokes => "Check: strokes",
            .gaps => "Check: gaps",
            .other => "Check: cap height, depths, colours, size",
            .simulation => "Simulation: FDM walls",
        };
    }
};

const Checked = struct {
    panel: usize,
    report: layout.check.Report,
    /// Each finding's area, triangulated for drawing (null: none).
    areas: []const ?geom.fill.Region,
};

var checks_arena: ?std.heap.ArenaAllocator = null;
var checks: []const Checked = &.{};
/// The revision and document they were run on.
var checks_rev: u64 = 0;
var checks_gen: u64 = 0;
var checks_ms: f64 = 0;
/// Shapes measured, kept for the session: a check again is quick.
var check_cache: ?layout.check.Cache = null;
var check_cache_gen: u64 = 0;

fn checksCurrent() bool {
    return checks.len > 0 and checks_gen == doc_generation;
}

fn checksStale() bool {
    return checksCurrent() and checks_rev != state.model.revision;
}

/// Drops the results (another document, or shutdown).
fn clearChecks() void {
    if (checks_arena) |*ar| ar.deinit();
    checks_arena = null;
    checks = &.{};
    if (check_cache) |*c| c.deinit();
    check_cache = null;
}

/// What C checks: the context's panel when it has something to check (a
/// process profile and fabrication layers), else every panel that has.
fn checkTarget() ?usize {
    const pi = switch (state.context) {
        .panel => |p| p,
        else => return null,
    };
    if (pi >= state.model.panels.items.len) return null;
    const p = state.model.panels.items[pi];
    if (state.model.processOf(pi) == null or p.fab.layers.len == 0) return null;
    return pi;
}

/// Runs the checks on panel `only`, else on every panel with a process
/// profile and fabrication layers.
fn runChecks(only: ?usize) void {
    if (state.placed_rev != state.model.revision) {
        state.status = "The panels are still being laid out: check again in a moment. ";
        return;
    }
    if (check_cache != null and check_cache_gen != doc_generation) {
        check_cache.?.deinit();
        check_cache = null;
    }
    if (check_cache == null) {
        check_cache = .init(state.gpa);
        check_cache_gen = doc_generation;
    }
    if (checks_arena) |*ar| ar.deinit();
    checks_arena = .init(state.gpa);
    const a = checks_arena.?.allocator();
    checks = &.{};
    var list: std.ArrayList(Checked) = .empty;
    const t0 = std.Io.Clock.awake.now(dvui.io);
    var skipped: usize = 0;
    for (state.model.panels.items, 0..) |p, pi| {
        if (only) |o| if (o != pi) continue;
        const placed = placedOf(.{ .panel = pi }) orelse continue;
        if (state.model.processOf(pi) == null or p.fab.layers.len == 0) {
            skipped += 1;
            continue;
        }
        const report = layout.check.run(a, &state.model, pi, placed, faceTable(), &check_cache.?) catch {
            state.status = "The checks could not be run. ";
            return;
        };
        const areas = a.alloc(?geom.fill.Region, report.findings.len) catch return;
        for (report.findings, areas) |f, *r| {
            r.* = null;
            const o = f.area orelse continue;
            var loops: std.ArrayList([]const geom.Point) = .empty;
            for (o.contours) |cn| {
                const pts = geom.grow.flatten(a, cn, report.tolerance) catch continue;
                loops.append(a, pts) catch continue;
            }
            r.* = geom.fill.nonzero(a, loops.items, report.tolerance * 1e-3) catch null;
        }
        list.append(a, .{ .panel = pi, .report = report, .areas = areas }) catch return;
    }
    checks = list.items;
    checks_rev = state.model.revision;
    checks_gen = doc_generation;
    checks_ms = @as(f64, @floatFromInt(t0.durationTo(std.Io.Clock.awake.now(dvui.io)).nanoseconds)) / 1e6;
    if (checks.len == 0) {
        state.status = if (only != null)
            "This panel has no process profile or no fabrication layers (its Fabrication): nothing to check. "
        else
            "No panel has a process profile and fabrication layers (a panel's Fabrication): nothing to check. ";
        return;
    }
    var fails: usize = 0;
    var marginal: usize = 0;
    for (checks) |ck| for (ck.report.findings) |f| switch (f.verdict) {
        .fail => fails += 1,
        .marginal => marginal += 1,
        .pass => {},
    };
    state.status = std.fmt.bufPrint(&check_status_buf, "Checked {d} panel{s} in {d:.0} ms: {d} failing, {d} marginal. The results are layers (Layers). ", .{ checks.len, if (checks.len == 1) "" else "s", checks_ms, fails, marginal }) catch "Checked. ";
    dvui.refresh(null, @src(), null);
}
var check_status_buf: [160]u8 = undefined;

/// The result layers over the panels of `space` (null: the shown ones).
fn drawChecks(area: dvui.Rect.Physical, space: ?usize, only: ?CheckLayer) void {
    if (!checksCurrent()) return;
    const px = dvui.windowNaturalScale();
    const marginal = display.fix(dvui.Color{ .r = 0xe0, .g = 0x00, .b = 0xd0 });
    const failing = display.fix(dvui.Color{ .r = 0xe0, .g = 0x20, .b = 0x1b });
    for (checks) |ck| {
        const pi = ck.panel;
        if (pi >= state.model.panels.items.len) continue;
        if (space) |sp| {
            if (state.model.spaceOf(pi) != sp) continue;
        } else if (!shownPanel(pi)) continue;
        const at = panelOrigin(pi);
        if (checkShown(state.model.spaceOf(pi), .simulation) and (only == null or only.? == .simulation)) {
            const lifo = dvui.currentWindow().lifo();
            for (ck.report.paths) |path| {
                if (path.points.len < 2) continue;
                const pts = lifo.alloc(dvui.Point.Physical, path.points.len) catch continue;
                defer lifo.free(pts);
                for (path.points, pts) |q, *o| o.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
                const c = path.colour.color;
                // A bead a little narrower than laid, so neighbours part.
                const w: f32 = @max(px, @as(f32, @floatCast(path.width * 0.8 * state.view.ppm)) * px);
                dvui.Path.stroke(.{ .points = pts }, .{ .thickness = w, .color = .{ .color = display.fix(dvui.Color{ .r = c.r, .g = c.g, .b = c.b }).opacity(0.75) }, .closed = true });
            }
        }
        for (ck.report.findings, ck.areas) |f, region| {
            const layer: CheckLayer = switch (f.kind) {
                .stroke => .strokes,
                .gap => .gaps,
                else => .other,
            };
            if (!checkShown(state.model.spaceOf(pi), layer)) continue;
            if (only) |o| if (o != layer) continue;
            const colour = if (f.verdict == .fail) failing else marginal;
            if (region) |r| {
                fillRegion(area, r, at, .{ .flat = colour.opacity(0.8) });
            } else {
                state.view.rect(area, onSheet(.{ .panel = pi }, f.box)).stroke(.square, .{ .thickness = 2 * px, .color = .{ .color = colour } });
            }
        }
    }
}

/// How many findings of `layer` the results hold (for `space`), and how
/// many fail.
fn checkCounts(space: usize, layer: CheckLayer) struct { n: usize, fails: usize } {
    var n: usize = 0;
    var fails: usize = 0;
    for (checks) |ck| {
        if (ck.panel >= state.model.panels.items.len or state.model.spaceOf(ck.panel) != space) continue;
        if (layer == .simulation) {
            n += ck.report.paths.len;
            continue;
        }
        for (ck.report.findings) |f| {
            const l: CheckLayer = switch (f.kind) {
                .stroke => .strokes,
                .gap => .gaps,
                else => .other,
            };
            if (l != layer) continue;
            n += 1;
            if (f.verdict == .fail) fails += 1;
        }
    }
    return .{ .n = n, .fails = fails };
}

/// The result layers in a space's Layers: each shown or hidden, with what
/// it holds; Check again, Clear.
fn checkLayersList(space: usize) void {
    const saved_group = pushGroup("checks");
    defer popGroup(saved_group);
    if (!checksCurrent()) return;
    const any = for (checks) |ck| {
        if (ck.panel < state.model.panels.items.len and state.model.spaceOf(ck.panel) == space) break true;
    } else false;
    if (!any) return;
    headingAs("checks.results", "{s}", .{if (checksStale()) "Results (out of date)" else "Results"}, 690);
    for (std.enums.values(CheckLayer), 0..) |l, k| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 600 + k });
        defer row.deinit();
        var vis = checkShown(space, l);
        if (tcheckbox(@src(), &vis, null, .{ .id_extra = 600 + k })) {
            const v: ViewLayer = switch (l) {
                .strokes => .check_strokes,
                .gaps => .check_gaps,
                .other => .check_other,
                .simulation => .simulation,
            };
            var st = overlayOf(space, v);
            st.shown = vis;
            setOverlay(space, v, st);
        }
        const c = checkCounts(space, l);
        var buf: [128]u8 = undefined;
        const text = if (l == .simulation)
            std.fmt.bufPrint(&buf, "{s} · {d} paths", .{ l.label(), c.n }) catch l.label()
        else if (c.n == 0)
            std.fmt.bufPrint(&buf, "{s} · pass", .{l.label()}) catch l.label()
        else
            std.fmt.bufPrint(&buf, "{s} · {d} failing, {d} marginal", .{ l.label(), c.fails, c.n - c.fails }) catch l.label();
        dvui.labelNoFmt(@src(), text, .{}, .{ .id_extra = 600 + k, .expand = .horizontal, .gravity_y = 0.5 });
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 610 });
        defer row.deinit();
        keyButton(@src(), "Check again", 0, .{ .expand = .horizontal, .id_extra = 611 });
        keyButton(@src(), "Clear results", 0, .{ .expand = .horizontal, .id_extra = 612 });
    }
}

/// A panel's checks in its Fabrication: Check this panel, and its last
/// results, check by check.
fn panelChecks(pi: usize) void {
    const saved_group = pushGroup("panel.checks");
    defer popGroup(saved_group);
    keyButton(@src(), "Check this panel", 0, .{ .expand = .horizontal, .id_extra = 420, .margin = .{ .y = 6 } });
    if (!checksCurrent()) return;
    const ck = for (checks) |c| {
        if (c.panel == pi) break c;
    } else return;
    const r = ck.report;
    const pr = r.profile orelse return;
    var buf: [128]u8 = undefined;
    propValue("Checked", checksStale(), "{s}{s}", .{ pr.name, if (checksStale()) " (out of date)" else "" }, 421);
    for (std.enums.values(layout.check.Kind), 0..) |k, i| {
        const fl = r.count(k, .fail);
        const mg = r.count(k, .marginal);
        const v = r.worst.get(k);
        const text = if (fl + mg == 0) "pass" else std.fmt.bufPrint(&buf, "{s}: {d} failing, {d} marginal", .{ @tagName(v), fl, mg }) catch @tagName(v);
        listItem("panel.checks.limit", k.label());
        propText(k.label(), "{s}", .{text}, 422 + i);
    }
    propText("Part", "{d:.1} × {d:.1} × {d:.1} mm, {d} colour{s}", .{ r.extent[0], r.extent[1], r.extent[2], r.colours, if (r.colours == 1) "" else "s" }, 430);
}

/// A space's layers, top first, for its properties: each one shown or
/// hidden, locked or not, and opened by its name; then Add layer.
fn layersList(space: usize) void {
    const saved_group = pushGroup("layers");
    defer popGroup(saved_group);
    checkLayersList(space);
    heading("{s}", .{"Layers"}, 700);
    const sp = state.model.spaces.items[space];
    const n = sp.layers.items.len;
    for (0..n) |k| {
        const li = n - 1 - k;
        const l = sp.layers.items[li];
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = li });
        defer row.deinit();
        var vis = l.visible;
        if (tcheckbox(@src(), &vis, null, .{ .id_extra = li })) {
            var nl = l;
            nl.visible = vis;
            act(.setLayer, .{space, li, nl}) catch {};
        }
        var flagged = false;
        for (state.layer_issues) |iss| {
            if (iss.space == space and iss.layer == li) flagged = true;
        }
        var buf: [96]u8 = undefined;
        const active = l.id == newObjectLayer();
        const text = std.fmt.bufPrint(&buf, "{s}{s}{s}{s}", .{ l.name, if (l.locked) " (locked)" else "", if (active) " · new objects" else "", if (flagged) " · flagged" else "" }) catch l.name;
        keyButton(@src(), text, @intCast(li), .{ .id_extra = li, .expand = .horizontal, .color_text = if (flagged) .{ .color = colors.overflow } else null });
    }
    keyButton(@src(), "Add layer", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
}

/// A layer's properties: shown, locked, opacity, blend, output, its place
/// in the stack, and its flags.
fn layerProperties(space: usize, li: usize) !void {
    const saved_group = pushGroup("layer");
    defer popGroup(saved_group);
    const sp = state.model.spaces.items[space];
    if (li >= sp.layers.items.len) return;
    var l = sp.layers.items[li];
    var changed = false;
    propText("Name", "{s}", .{l.name}, 1);
    propText("Place", "{d} of {d}, from the bottom", .{ li + 1, sp.layers.items.len }, 2);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3 });
        defer row.deinit();
        propName("Shown");
        if (tcheckbox(@src(), &l.visible, "Visible", .{ .id_extra = 3 })) changed = true;
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 4 });
        defer row.deinit();
        propName("Lock");
        if (tcheckbox(@src(), &l.locked, "Locked: nothing on it can be picked", .{ .id_extra = 4 })) changed = true;
    }
    var buf: [32]u8 = undefined;
    if (sizesProp("Opacity, %", std.fmt.bufPrint(&buf, "{d}", .{@round(l.opacity * 100)}) catch "", 5)) |list| if (list.len == 1) {
        l.opacity = std.math.clamp(list[0] / 100, 0, 1);
        changed = true;
    };
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 6 });
        defer row.deinit();
        propName("Blend");
        const names = [_][]const u8{ "Normal", "Multiply", "Screen" };
        var choice: usize = @intFromEnum(l.blend);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 6 })) {
            l.blend = @enumFromInt(choice);
            changed = true;
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 7 });
        defer row.deinit();
        propName("Output");
        const names = [_][]const u8{ "None (guide)", "Print", "Engrave", "Cut", "Mill" };
        var choice: usize = @intFromEnum(l.output);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 7 })) {
            l.output = @enumFromInt(choice);
            changed = true;
        }
    }
    if (changed) try act(.setLayer, .{space, li, l});
    propText("New objects", "{s}", .{if (l.id == newObjectLayer()) "go on this layer" else "go elsewhere"}, 8);
    layerFlags(space, li, 9);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Move up", 0, .{});
        keyButton(@src(), "Move down", 0, .{});
        keyButton(@src(), "Remove", 0, .{});
    }
}

/// A dropdown of space `space`'s layers; returns the chosen layer when it
/// changes.
fn layerChoice(space: usize, current: layout.model.ObjectId, n: usize) ?layout.model.ObjectId {
    const sp = state.model.spaces.items[space];
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName("Layer");
    var names_buf: [16][]const u8 = undefined;
    const n_layers = @min(sp.layers.items.len, names_buf.len);
    for (0..n_layers) |i| names_buf[i] = sp.layers.items[i].name;
    var choice: usize = sp.layerIndex(current) orelse 0;
    if (tdropdown(@src(), names_buf[0..n_layers], .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n })) return sp.layers.items[choice].id;
    return null;
}

/// An image's properties: its layer, place, physical size, pixels and
/// effective resolution.
fn imageProperties(space: usize, index: usize) !void {
    const saved_group = pushGroup("image");
    defer popGroup(saved_group);
    const im = imageAt(space, index) orelse return;
    propText("Name", "{s}", .{im.name}, 1);
    if (layerChoice(space, im.layer, 2)) |l| try act(.setImage, .{space, index, im.at, im.w, l});
    propText("Place", "({d:.1}, {d:.1}) mm", .{ im.at.x, im.at.y }, 3);
    var buf: [32]u8 = undefined;
    if (sizesProp("Width, mm", std.fmt.bufPrint(&buf, "{d:.2}", .{im.w}) catch "", 4)) |list| if (list.len == 1) {
        act(.setImage, .{space, index, im.at, list[0], im.layer}) catch {
            state.status = "A width must be more than 0. ";
        };
    };
    propText("Height", "{d:.2} mm (keeps its proportions)", .{im.h}, 5);
    propText("Pixels", "{d} × {d}", .{ im.px_w, im.px_h }, 6);
    propText("Resolution", "{d:.0} dpi at this size", .{im.dpi()}, 7);
    propText("Moves", "{s}", .{"arrow keys, 1 mm"}, 8);
    if (state.model.spaces.items[space].layerIndex(im.layer)) |li| layerFlags(space, li, 9);
    keyButton(@src(), "Remove image", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// Moves the selected image 1 mm the way an arrow points.
fn moveImageKey(code: dvui.enums.Key) bool {
    const c = switch (state.context) {
        .image => |c| c,
        else => return false,
    };
    const im = imageAt(c.space, c.index) orelse return false;
    const d: geom.Point = switch (code) {
        .up => .{ .x = 0, .y = nudge_mm },
        .down => .{ .x = 0, .y = -nudge_mm },
        .left => .{ .x = -nudge_mm, .y = 0 },
        .right => .{ .x = nudge_mm, .y = 0 },
        else => return false,
    };
    actM(mergeKey(.{ "moveImageKey", state.context }), .setImage, .{c.space, c.index, .{ .x = im.at.x + d.x, .y = im.at.y + d.y }, im.w, im.layer}) catch return false;
    return true;
}

/// File › Place image is asking for the file.
var image_prompt = false;
/// Whether the image prompt is the system's file dialog (see `askForFile`).
var image_prompt_system = false;
/// The prompt has just opened: its file field takes the keyboard.
var image_prompt_new = false;

/// The Place image prompt: a PNG or JPEG file, placed in the shown space
/// at 150 dpi on the active layer.
fn imagePrompt() void {
    if (image_prompt_system) {
        if (image_prompt_new) {
            image_prompt_new = false;
            system_dialog_wait = 3;
        }
        if (system_dialog_wait > 0) {
            system_dialog_wait -= 1;
            dvui.refresh(null, @src(), null);
            return;
        }
        image_prompt_system = false;
        image_prompt = false;
        dvui.refresh(null, @src(), null);
        if (dvui.dialogNativeFileOpen(dvui.currentWindow().arena(), .{ .title = "Place an image", .filters = &.{ "*.png", "*.jpg", "*.jpeg" }, .filter_description = "PNG or JPEG images" }) catch null) |path| placeImage(path);
        return;
    }
    const saved_group = pushGroup("dialog.image");
    defer popGroup(saved_group);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 460;
    const h: f32 = 185;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + (c.h - h) / 2, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(11));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), "Place image (PNG or JPEG)", .{}, .{ .font = dvui.Font.theme(.heading) });
    var go = false;
    var cancel = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => go = true,
            kact("dialog.cancel") => cancel = true,
            else => continue,
        }
        e.handle(@src(), fw.data());
    }
    var path: []const u8 = "";
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        defer row.deinit();
        propName("File");
        var te = dvui.textEntry(@src(), .{}, .{ .expand = .horizontal });
        defer te.deinit();
        if (image_prompt_new) {
            // The prompt's window takes the keys, so Enter and Esc reach it.
            dvui.focusSubwindow(fw.data().id, null);
            dvui.focusWidget(te.data().id, fw.data().id, null);
            image_prompt_new = false;
        }
        if (te.enter_pressed) go = true;
        path = dvui.currentWindow().arena().dupe(u8, std.mem.trim(u8, te.textGet(), " ")) catch "";
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), "Place", 0, .{});
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) go = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (cancel) {
        image_prompt = false;
        dvui.refresh(null, @src(), null);
        return;
    }
    if (!go or path.len == 0) return;
    image_prompt = false;
    placeImage(path);
}

/// Reads image file `path` and places it in the shown space.
fn placeImage(path: []const u8) void {
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, state.gpa, .limited(256 << 20)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    defer state.gpa.free(bytes);
    var pw: c_int = 0;
    var ph: c_int = 0;
    var channels: c_int = 0;
    if (dvui.c.stbi_info_from_memory(bytes.ptr, @intCast(bytes.len), &pw, &ph, &channels) == 0 or pw <= 0 or ph <= 0) {
        state.status = "That is not a PNG or JPEG image. ";
        return;
    }
    // At 150 dpi, centred in the view.
    const w = @as(f64, @floatFromInt(pw)) / 150.0 * 25.4;
    const hgt = w * @as(f64, @floatFromInt(ph)) / @as(f64, @floatFromInt(pw));
    const at: geom.Point = .{ .x = state.view.cx - w / 2, .y = state.view.cy - hgt / 2 };
    const ii = act(.addImage, .{shown_space, std.fs.path.basename(path), bytes, @intCast(pw), @intCast(ph), at, w, newObjectLayer()}) catch {
        state.status = "The image could not be placed. ";
        return;
    };
    state.context = .{ .image = .{ .space = shown_space, .index = ii } };
    state.status = "Placed at 150 dpi: set its width in its properties. ";
}

// Views ---------------------------------------------------------------------
//
// A view is a live, read-only window onto another space, placed at a scale:
// the source's panels are drawn through it from the same solve, so an edit
// to the source shows in every view at once. Nothing in it is picked; the
// view itself is, by its box.

/// Views nest at most this deep (cycles are refused; this only bounds the
/// drawing).
const view_depth = 6;

fn viewAt(space: usize, index: usize) ?layout.model.SpaceView {
    if (space >= state.model.spaces.items.len) return null;
    const list = state.model.spaces.items[space].views.items;
    return if (index < list.len) list[index] else null;
}

/// What a view shows, in its source's coordinates: its window, else the
/// source frame's boundary, else all the source holds.
fn viewWindow(sv: layout.model.SpaceView) geom.Box {
    if (sv.window) |w| return w;
    if (state.model.spaceIndex(sv.source)) |src| if (state.model.spaces.items[src].bound) |b| return b;
    return extentsOf(state.model.spaceIndex(sv.source) orelse return .empty, 1);
}

/// Where a view lies in its host, mm.
fn viewBox(sv: layout.model.SpaceView) geom.Box {
    const w = viewWindow(sv);
    if (w.isEmpty()) return .{ .x0 = sv.at.x, .y0 = sv.at.y, .x1 = sv.at.x + 20, .y1 = sv.at.y + 10 };
    const c: geom.Point = .{ .x = w.x0, .y = w.y0 };
    const lo = sv.toHost(c, c);
    const hi = sv.toHost(c, .{ .x = w.x1, .y = w.y1 });
    return .{ .x0 = lo.x, .y0 = lo.y, .x1 = hi.x, .y1 = hi.y };
}

/// A view's box with room above it for its name, for fitting.
fn withNameRoom(b: geom.Box) geom.Box {
    var r = b;
    r.y1 += 0.08 * b.height();
    return r;
}

/// What space `space` holds, in its coordinates: its panels' outlines and
/// solved content, and its views.
fn extentsOf(space: usize, depth: usize) geom.Box {
    var b: geom.Box = .empty;
    for (state.model.panels.items, 0..) |p, pi| {
        if (state.model.spaces.items.len > 0 and p.space != spaceId(space)) continue;
        if (placedOf(.{ .panel = pi })) |pl| if (!pl.bounds.isEmpty()) {
            b = b.join(onSheet(.{ .panel = pi }, pl.bounds));
        };
        b = b.join(p.box());
    }
    if (space < state.model.spaces.items.len) if (placedOf(.{ .space = space })) |pl| if (!pl.bounds.isEmpty()) {
        b = b.join(pl.bounds);
    };
    if (space < state.model.spaces.items.len) for (state.model.spaces.items[space].images.items) |im| {
        b = b.join(im.box());
    };
    if (space < state.model.spaces.items.len) for (state.model.spaces.items[space].figure_places.items) |fp| {
        b = b.join(fp.box());
    };
    if (depth < view_depth and space < state.model.spaces.items.len) for (state.model.spaces.items[space].views.items) |sv| {
        const src = state.model.spaceIndex(sv.source) orelse continue;
        if (sv.window == null and state.model.spaces.items[src].bound == null and extentsOf(src, depth + 1).isEmpty()) continue;
        b = b.join(withNameRoom(viewBox(sv)));
    };
    return b;
}

/// The views placed in space `host`: each its source drawn through the
/// view's scale, clipped to the view's box, on a faint ground; the selected
/// one outlined. Views in the source are drawn inside, as deep as
/// `view_depth`.
fn drawViews(area: dvui.Rect.Physical, host: usize, depth: usize, layer: layout.model.ObjectId) void {
    if (depth >= view_depth or host >= state.model.spaces.items.len) return;
    const px = dvui.windowNaturalScale();
    const base = state.model.spaces.items[host].base_layer;
    for (state.model.spaces.items[host].views.items, 0..) |sv, vi| {
        if ((if (sv.layer == .none) base else sv.layer) != layer) continue;
        const hb = viewBox(sv);
        const r = state.view.rect(area, hb);
        r.fill(.square, .{ .color = .{ .color = colors.paper.opacity(0.7) } });
        const w = viewWindow(sv);
        if (!w.isEmpty()) {
            const prev = state.view;
            const prev_clip = dvui.clip(r);
            state.view.ppm = prev.ppm * sv.scale;
            state.view.cx = w.x0 + (prev.cx - sv.at.x) / sv.scale;
            state.view.cy = w.y0 + (prev.cy - sv.at.y) / sv.scale;
            if (state.model.spaceIndex(sv.source)) |src| drawSpace(area, src, depth + 1);
            state.view = prev;
            dvui.clipSet(prev_clip);
        }
        const sel = depth == 0 and switch (state.context) {
            .view => |v| v.space == host and v.index == vi,
            else => false,
        };
        if (sel) {
            marchingBox(area, hb, colors.select, 2 * px);
        } else {
            guideBox(area, hb, colors.guide.opacity(0.8), px);
        }
        if (depth > 0) continue;
        // Its name above its corner, with the scale.
        var buf: [128]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "{s} · {s}", .{ sv.name, scaleText(sv.scale) }) catch sv.name;
        const corner = state.view.toPx(area, .{ .x = hb.x0, .y = hb.y1 });
        const font = dvui.Font.theme(.body).larger(-2);
        dvui.labelNoFmt(@src(), text, .{}, .{
            .id_extra = vi,
            .rect = annotationRect(area, corner, font, 320),
            .padding = .{ .x = 0, .w = 0, .y = annotation_pad, .h = annotation_pad },
            .color_text = .{ .color = if (sel) colors.select else colors.guide },
            .font = font,
        });
    }
}

/// A one-line annotation's rectangle just above canvas point `corner`
/// (physical pixels), in the canvas's own logical coordinates: as tall as
/// the font's line with its padding, so no part of the text is clipped.
fn annotationRect(area: dvui.Rect.Physical, corner: dvui.Point.Physical, font: dvui.Font, w: f32) dvui.Rect {
    const ns = dvui.windowNaturalScale();
    const h = font.lineHeight() + 2 * annotation_pad;
    return .{ .x = (corner.x - area.x) / ns, .y = (corner.y - area.y) / ns - h - 2, .w = w, .h = h };
}

const annotation_pad = 2;

/// A scale as a ratio: 1:1, 1:2 (smaller), 2:1 (larger).
fn scaleText(scale: f64) []const u8 {
    const buf = dvui.currentWindow().arena().alloc(u8, 32) catch return "";
    if (scale >= 1) return std.fmt.bufPrint(buf, "{d}:1", .{@round(scale * 100) / 100}) catch "";
    return std.fmt.bufPrint(buf, "1:{d}", .{@round(100 / scale) / 100}) catch "";
}

/// The top-most view of the shown space under `at`, if any.
fn viewUnder(at: geom.Point) ?Context {
    if (shown_space >= state.model.spaces.items.len) return null;
    var hit: ?Context = null;
    for (state.model.spaces.items[shown_space].views.items, 0..) |sv, vi| {
        if (contains(viewBox(sv), at) and layerOpen(shown_space, sv.layer)) hit = .{ .view = .{ .space = shown_space, .index = vi } };
    }
    return hit;
}

/// A view's properties: what it shows and at what scale, where it lies,
/// and the way to its source.
fn viewProperties(host: usize, index: usize) !void {
    const saved_group = pushGroup("view");
    defer popGroup(saved_group);
    const sv = viewAt(host, index) orelse return;
    propText("Name", "{s}", .{sv.name}, 1);
    const src_i = state.model.spaceIndex(sv.source) orelse return;
    const src = state.model.spaces.items[src_i];
    propText("Shows", "{s}", .{if (src_i == 0) "the canvas" else src.name}, 2);
    const hb = viewBox(sv);
    propText("Place", "({d:.1}, {d:.1}) mm", .{ hb.x0, hb.y0 }, 3);
    propText("Size", "{d:.1} × {d:.1} mm", .{ hb.width(), hb.height() }, 4);
    var buf: [32]u8 = undefined;
    if (sizesProp("Scale", std.fmt.bufPrint(&buf, "{d}", .{sv.scale}) catch "", 5)) |list| if (list.len == 1) {
        act(.setViewScale, .{host, index, list[0]}) catch {
            state.status = "A scale must be more than 0. ";
        };
    };
    propText("Reads as", "{s}", .{scaleText(sv.scale)}, 6);
    propText("Moves", "{s}", .{"arrow keys, 1 mm"}, 7);
    propText("Edits", "{s}", .{"in its source: it shows them at once"}, 8);
    keyButton(@src(), "Show its source", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    keyButton(@src(), "Remove view", 0, .{ .expand = .horizontal });
}

/// Buttons placing a view of space `space` in each other space it may
/// show in (one that would show itself is left out).
fn placeViewButtons(space: usize) void {
    const saved_group = pushGroup("view.place-in");
    defer popGroup(saved_group);
    var any = false;
    for (state.model.spaces.items, 0..) |sp, host| {
        if (state.model.viewWouldCycle(host, space)) continue;
        if (!any) {
            dvui.labelNoFmt(@src(), "Views of it", .{}, .{ .font = dvui.Font.theme(.heading), .margin = .{ .y = 8 } });
            any = true;
        }
        var buf: [96]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "Place a view in {s}", .{if (host == 0) "the canvas" else sp.name}) catch "Place a view";
        keyButton(@src(), text, @intCast(host), .{ .expand = .horizontal, .id_extra = host });
    }
}

/// Places a view of `source` in `host` at 1:1, just right of what the host
/// holds, and shows it there.
fn placeView(source: usize, host: usize) void {
    const e = extentsOf(host, 0);
    const at: geom.Point = if (e.isEmpty()) .{ .x = 0, .y = 0 } else .{ .x = e.x1 + 20, .y = e.y0 };
    const vi = act(.addView, .{host, source, at, 1}) catch {
        state.status = "That view would show itself. ";
        return;
    };
    shown_space = host;
    state.context = .{ .view = .{ .space = host, .index = vi } };
    state.view.fit = contentExtents();
    state.status = "Placed a view: edits to its source show in it at once. ";
}

/// Moves the selected view 1 mm the way an arrow points.
fn moveViewKey(code: dvui.enums.Key) bool {
    const v = switch (state.context) {
        .view => |v| v,
        else => return false,
    };
    const sv = viewAt(v.space, v.index) orelse return false;
    const d: geom.Point = switch (code) {
        .up => .{ .x = 0, .y = nudge_mm },
        .down => .{ .x = 0, .y = -nudge_mm },
        .left => .{ .x = -nudge_mm, .y = 0 },
        .right => .{ .x = nudge_mm, .y = 0 },
        else => return false,
    };
    actM(mergeKey(.{ "moveViewKey", state.context }), .moveView, .{v.space, v.index, .{ .x = sv.at.x + d.x, .y = sv.at.y + d.y }}) catch return false;
    return true;
}

/// The shown frame's boundary, with its name above it: in the warning colour
/// when content reaches past it.
fn drawFrameBound(area: dvui.Rect.Physical) void {
    if (shown_space == 0 or shown_space >= state.model.spaces.items.len) return;
    const sp = state.model.spaces.items[shown_space];
    const b = sp.bound orelse return;
    const px = dvui.windowNaturalScale();
    const past = !layout.model.within(spaceExtents(), b);
    const colour = if (past) colors.overflow else colors.guide;
    state.view.rect(area, b).stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colour } });
    const corner = state.view.toPx(area, .{ .x = b.x0, .y = b.y1 });
    const font = dvui.Font.theme(.body).larger(-1);
    dvui.labelNoFmt(@src(), sp.name, .{}, .{
        .rect = annotationRect(area, corner, font, 240),
        .padding = .{ .x = 0, .w = 0, .y = annotation_pad, .h = annotation_pad },
        .color_text = .{ .color = colour },
        .font = font,
    });
}

/// What the shown space holds, in its coordinates: its panels' outlines
/// and every solved bound of its panels.
fn spaceExtents() geom.Box {
    return extentsOf(shown_space, 0);
}

/// The canvas's axes through its origin, faint, with a mark at the origin.
/// View › Grid: graph paper behind the canvas (grid.zig).
/// How grids are drawn (a preference, kept in the settings): lines, dots
/// or pluses. Whether a canvas or frame has a grid, and its spacing, are
/// the document's (`Space.overlays`, `Space.grid_spacing`).
var grid_mode: bg_grid.Mode = .lines;

fn gridLook() bg_grid.Mode {
    return if (grid_mode == .none) .lines else grid_mode;
}

/// The grid's levels in the shown space, document units: adaptive
/// decades, or the space's own spacing (lines at it, stronger every ten).
fn gridLevels(lo: f64, buf: []bg_grid.Level) []bg_grid.Level {
    const unit_mm = 1 / docUnits().perMm();
    const px_per_unit = state.view.ppm * unit_mm;
    const spacing = if (shown_space < state.model.spaces.items.len) state.model.spaces.items[shown_space].grid_spacing else 0;
    if (spacing > 0) return bg_grid.fixed(spacing / unit_mm, px_per_unit, lo, buf);
    return bg_grid.levels(px_per_unit, lo, gridScale(), buf);
}

/// One rectangle of the grid, device pixels, and its colour.
const GridQuad = struct { r: dvui.Rect.Physical, col: dvui.Color.PMA };

/// The background grid across `area`, under everything drawn on it: in the
/// document's units, each line one device pixel wide on the pixel grid
/// (or a dot at each crossing), all of it in a few batched draws.
fn drawGrid(area: dvui.Rect.Physical) void {
    if (!(state.view.ppm > 0)) return;
    const look = gridLook();
    const unit_mm = 1 / docUnits().perMm();
    const lo = if (look == .lines) bg_grid.fade_lo else bg_grid.dots_lo;
    var buf: [8]bg_grid.Level = undefined;
    const lv = gridLevels(lo, &buf);
    if (lv.len == 0) return;
    const a = dvui.currentWindow().arena();
    var quads: std.ArrayList(GridQuad) = .empty;
    // The visible span, document units.
    const tl = state.view.toMm(area, .{ .x = area.x, .y = area.y });
    const br = state.view.toMm(area, .{ .x = area.x + area.w, .y = area.y + area.h });
    const x0 = tl.x / unit_mm;
    const x1 = br.x / unit_mm;
    const y0 = br.y / unit_mm;
    const y1 = tl.y / unit_mm;
    const t: f32 = @max(1, @round(dvui.windowNaturalScale()));
    const Ctx = struct {
        a: std.mem.Allocator,
        quads: *std.ArrayList(GridQuad),
        area: dvui.Rect.Physical,
        unit_mm: f64,
        t: f32,
        vertical: bool,

        fn col(s: f32) dvui.Color.PMA {
            return .fromColor(colors.grid.opacity(colors.grid_major * s));
        }

        fn line(c: @This(), at: f64, s: f32) void {
            const p = state.view.toPx(c.area, if (c.vertical) .{ .x = at * c.unit_mm, .y = 0 } else .{ .x = 0, .y = at * c.unit_mm });
            // On the pixel grid: crisp at any pan.
            const r: dvui.Rect.Physical = if (c.vertical)
                .{ .x = @floor(p.x), .y = c.area.y, .w = c.t, .h = c.area.h }
            else
                .{ .x = c.area.x, .y = @floor(p.y), .w = c.area.w, .h = c.t };
            c.quads.append(c.a, .{ .r = r, .col = col(s) }) catch {};
        }
    };
    if (look == .lines) {
        const base: Ctx = .{ .a = a, .quads = &quads, .area = area, .unit_mm = unit_mm, .t = t, .vertical = true };
        bg_grid.lines(lv, x0, x1, base, Ctx.line);
        var h = base;
        h.vertical = false;
        bg_grid.lines(lv, y0, y1, h, Ctx.line);
    } else {
        // Dots at the crossings, each at the strength of the coarsest
        // decade both its lines are on.
        const d: f32 = @max(2, @round(2 * dvui.windowNaturalScale()));
        for (lv, 0..) |l, k| {
            if (l.strength <= 0) continue;
            // Never more dots than a screen could show (a view gone wrong).
            if (!((x1 - x0) / l.step <= bg_grid.max_lines and (y1 - y0) / l.step <= bg_grid.max_lines)) continue;
            const coarser = k + 1 < lv.len;
            var i: i64 = @intFromFloat(@ceil(x0 / l.step));
            while (@as(f64, @floatFromInt(i)) * l.step <= x1) : (i += 1) {
                var j: i64 = @intFromFloat(@ceil(y0 / l.step));
                while (@as(f64, @floatFromInt(j)) * l.step <= y1) : (j += 1) {
                    if (coarser and @mod(i, l.ratio) == 0 and @mod(j, l.ratio) == 0) continue;
                    const p = state.view.toPx(area, .{ .x = @as(f64, @floatFromInt(i)) * l.step * unit_mm, .y = @as(f64, @floatFromInt(j)) * l.step * unit_mm });
                    // A dot is a few pixels where a line is a long run of them:
                    // it needs more contrast to read.
                    const dot: dvui.Color.PMA = .fromColor(colors.grid.opacity(@min(0.85, 3 * colors.grid_major * @sqrt(l.strength))));
                    if (look == .pluses) {
                        // A plus: two short bars a line's width, crossing.
                        const arm = 3 * d;
                        quads.append(a, .{ .r = .{ .x = @floor(p.x - arm / 2), .y = @floor(p.y), .w = arm, .h = t }, .col = dot }) catch {};
                        quads.append(a, .{ .r = .{ .x = @floor(p.x), .y = @floor(p.y - arm / 2), .w = t, .h = arm }, .col = dot }) catch {};
                    } else quads.append(a, .{ .r = .{ .x = @floor(p.x - d / 2), .y = @floor(p.y - d / 2), .w = d, .h = d }, .col = dot }) catch {};
                }
            }
        }
    }
    // Vertex indices may be 16-bit: in batches.
    const Index = dvui.Vertex.Index;
    const batch = 12000;
    const lifo = dvui.currentWindow().lifo();
    var from: usize = 0;
    while (from < quads.items.len) : (from += batch) {
        const part = quads.items[from..@min(from + batch, quads.items.len)];
        var b = dvui.Triangles.Builder.init(lifo, 4 * part.len, 6 * part.len) catch return;
        defer b.deinit(lifo);
        for (part, 0..) |q, k| {
            const r = q.r;
            b.appendVertex(.{ .pos = .{ .x = r.x, .y = r.y }, .col = q.col });
            b.appendVertex(.{ .pos = .{ .x = r.x, .y = r.y + r.h }, .col = q.col });
            b.appendVertex(.{ .pos = .{ .x = r.x + r.w, .y = r.y + r.h }, .col = q.col });
            b.appendVertex(.{ .pos = .{ .x = r.x + r.w, .y = r.y }, .col = q.col });
            const i: Index = @intCast(4 * k);
            b.appendTriangles(&.{ i, i + 1, i + 2, i, i + 2, i + 3 });
        }
        dvui.renderTriangles(b.build_unowned(), null) catch {};
    }
}

fn drawAxes(area: dvui.Rect.Physical) void {
    const px = dvui.windowNaturalScale();
    const o = state.view.toPx(area, .{ .x = 0, .y = 0 });
    const axis: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.3) };
    if (o.y >= area.y and o.y <= area.y + area.h) dvui.Path.stroke(.{ .points = &.{ .{ .x = area.x, .y = o.y }, .{ .x = area.x + area.w, .y = o.y } } }, .{ .thickness = px, .color = axis });
    if (o.x >= area.x and o.x <= area.x + area.w) dvui.Path.stroke(.{ .points = &.{ .{ .x = o.x, .y = area.y }, .{ .x = o.x, .y = area.y + area.h } } }, .{ .thickness = px, .color = axis });
    const r: f32 = 4 * px;
    const mark: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.7) };
    dvui.Path.stroke(.{ .points = &.{ .{ .x = o.x - r, .y = o.y }, .{ .x = o.x + r, .y = o.y } } }, .{ .thickness = 1.5 * px, .color = mark });
    dvui.Path.stroke(.{ .points = &.{ .{ .x = o.x, .y = o.y - r }, .{ .x = o.x, .y = o.y + r } } }, .{ .thickness = 1.5 * px, .color = mark });
}

/// One ruler's ticks and numbers, counted from the ruler origin. Ticks grow
/// from the ruler's edge against the sheet.
fn rulerAxis(r: dvui.Rect.Physical, area: dvui.Rect.Physical, list: []const Tick, horizontal: bool) void {
    if (r.w <= 0 or r.h <= 0) return;
    const ns = dvui.windowNaturalScale();
    const sheet = state.model.sheet;
    const open = openCanvas();
    const from_far = !open and (if (horizontal) sheet.ruler_origin.fromRight() else sheet.ruler_origin.fromTop());
    const length = if (horizontal) sheet.w else sheet.h;
    // The ruler's ends in the worksheet frame, then as the ruler counts.
    const e0 = if (horizontal) state.view.toMm(area, .{ .x = r.x, .y = 0 }).x else state.view.toMm(area, .{ .x = 0, .y = r.y + r.h }).y;
    const e1 = if (horizontal) state.view.toMm(area, .{ .x = r.x + r.w, .y = 0 }).x else state.view.toMm(area, .{ .x = 0, .y = r.y }).y;
    const c0 = if (from_far) length - e0 else e0;
    const c1 = if (from_far) length - e1 else e1;
    // A millimetre of slack each way, so pixel rounding at a sheet edge
    // does not drop the 0 or end tick; still clamped to the sheet.
    const lo = if (open) @min(c0, c1) - 1 else @max(0, @min(c0, c1) - 1);
    const hi = if (open) @max(c0, c1) + 1 else @min(length, @max(c0, c1) + 1);
    if (lo > hi) return;

    // Ticks grow from the edge against the sheet: the horizontal ruler's
    // bottom; the vertical ruler's right side on the left, left side on
    // the right.
    const right_side = !horizontal and !open and sheet.ruler_origin.fromRight();
    const ink: dvui.ColorOrGradient = .{ .color = colors.ruler_ink };
    const font = dvui.Font.theme(.body).withSize(7);
    const depth = if (horizontal) r.h else r.w;
    for (list) |t| {
        var i: f64 = @ceil(lo / t.step - 1e-9);
        while (i * t.step <= hi + 1e-9) : (i += 1) {
            const v = i * t.step;
            const along = if (from_far) length - v else v;
            const p = state.view.toPx(area, if (horizontal) .{ .x = along, .y = 0 } else .{ .x = 0, .y = along });
            const len = depth * t.len;
            const pts: [2]dvui.Point.Physical = if (horizontal)
                .{ .{ .x = p.x, .y = r.y + r.h }, .{ .x = p.x, .y = r.y + r.h - len } }
            else if (right_side)
                .{ .{ .x = r.x, .y = p.y }, .{ .x = r.x + len, .y = p.y } }
            else
                .{ .{ .x = r.x + r.w, .y = p.y }, .{ .x = r.x + r.w - len, .y = p.y } };
            dvui.Path.stroke(.{ .points = &pts }, .{ .thickness = ns, .color = ink });
            if (!t.label) continue;

            var text_buf: [16]u8 = undefined;
            // @round(-0.0) prints as "-0".
            const rounded = @round(v * docUnits().perMm());
            const text = std.fmt.bufPrint(&text_buf, "{d}", .{if (rounded == 0) 0 else rounded}) catch continue;
            const size = font.textSize(text);
            const tw: f32 = size.w * ns;
            const th: f32 = size.h * ns;
            // Bounds for culling: the canvas, since rotated text is culled by
            // its unrotated extent.
            const rs: dvui.RectScale = .{ .r = area, .s = ns };
            if (horizontal) {
                // Numbers sit on the side of the tick they count toward.
                const x = if (from_far) p.x - 2 * ns - tw else p.x + 2 * ns;
                dvui.renderText(.{ .font = font, .text = text, .rs = rs, .p = .{ .x = x, .y = r.y + ns }, .color = colors.ruler_ink }) catch {};
            } else {
                // Rotated to read bottom to top; on the far side from the sheet.
                const x = if (right_side) r.x + r.w - th - ns else r.x + ns;
                const y = if (from_far) p.y + 2 * ns + tw else p.y - 2 * ns;
                dvui.renderText(.{ .font = font, .text = text, .rs = rs, .p = .{ .x = x, .y = y }, .color = colors.ruler_ink, .rotation = -std.math.pi / 2.0 }) catch {};
            }
        }
    }
}

/// Snaps a worksheet point to the 1 mm grid the add panel tool uses. A
/// panel starts on the sheet but may be drawn past its edge, flagged.
// Snapping to the grid ------------------------------------------------------
//
// A drag puts what it moves on the grid: the engaged point (or a resize
// handle's edges, a moved selection's or panel's origin, a new panel's,
// track's or line art's corners) goes to the nearest line of the finest
// units the grid shows at the zoom (the nudge's minor unit), so the step
// follows the zoom and the document's units (inches by ruler fractions).
// Guides mark the lines it is on while it is dragged. Alt held lets go
// (the drag is free while it is held); View › Snap to grid (%) turns it
// off; no grid shown, no snapping.

/// Whether drags snap to the grid.
var snap_grid: bool = true;
/// Select boundaries (a persistent mode, toggled by its button or B, kept
/// in the settings): with the select tool, the boundary nearest the
/// pointer is highlighted and a click selects its container, never its
/// content; the selection's drag points are haloed.
var boundary_mode = false;

/// The grid lines the drag in hand is on (canvas mm), for its guides;
/// cleared when the drag ends.
var snap_guide: struct { x: ?f64 = null, y: ?f64 = null } = .{};

fn altHeld() bool {
    if (dvui.backend.kind != .sdl3) return false;
    const c = dvui.backend.c;
    return (c.SDL_GetModState() & c.SDL_KMOD_ALT) != 0;
}

/// The grid step drags snap to now (canvas mm), or null when they do not.
fn snapStep() ?f64 {
    if (!snap_grid or !ViewLayer.grid.shown() or !(state.view.ppm > 0) or altHeld()) return null;
    const st = nudgeStep(false);
    return if (st > 0 and std.math.isFinite(st)) st else null;
}

/// Canvas coordinate `v` on the nearest grid line, the guide `g` set.
fn snapAxis(v: f64, st: f64, g: *?f64) f64 {
    const out = @round(v / st) * st;
    g.* = out;
    return out;
}

/// Point `p` (canvas mm) on the grid along the axes given.
fn snapPoint(p: geom.Point, along_x: bool, along_y: bool) geom.Point {
    const st = snapStep() orelse {
        snap_guide = .{};
        return p;
    };
    var out = p;
    snap_guide = .{};
    if (along_x) out.x = snapAxis(p.x, st, &snap_guide.x);
    if (along_y) out.y = snapAxis(p.y, st, &snap_guide.y);
    return out;
}

/// A shift (canvas mm, along one axis) changed so that `ref` + it is on
/// the grid.
fn snapShift(ref: f64, shift: f64, st: f64, g: *?f64) f64 {
    return snapAxis(ref + shift, st, g) - ref;
}

/// A point drawn on the canvas (a new panel's corner): on the grid when
/// snapping.
fn snap(p: geom.Point) geom.Point {
    return snapPoint(p, true, true);
}

/// The guides of the drag in hand: a line across the canvas at each grid
/// line it is on.
fn drawSnapGuides(area: dvui.Rect.Physical) void {
    const dragging = engage_drag != null or resize_drag != null or (sel_press != null and sel_press.?.moved) or state.moving != null or (state.drag != null and !band_drag);
    if (!dragging) {
        snap_guide = .{};
        return;
    }
    const ink: dvui.ColorOrGradient = .{ .color = colors.select.opacity(0.55) };
    const t = dvui.windowNaturalScale();
    if (snap_guide.x) |x| {
        const q = state.view.toPx(area, .{ .x = x, .y = 0 });
        dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x, .y = area.y }, .{ .x = q.x, .y = area.y + area.h } } }, .{ .thickness = t, .color = ink });
    }
    if (snap_guide.y) |y| {
        const q = state.view.toPx(area, .{ .x = 0, .y = y });
        dvui.Path.stroke(.{ .points = &.{ .{ .x = area.x, .y = q.y }, .{ .x = area.x + area.w, .y = q.y } } }, .{ .thickness = t, .color = ink });
    }
}

fn dragBox(a: geom.Point, b: geom.Point) geom.Box {
    return .{ .x0 = @min(a.x, b.x), .y0 = @min(a.y, b.y), .x1 = @max(a.x, b.x), .y1 = @max(a.y, b.y) };
}

/// The key modes active now, outermost first, from the interface's state
/// (keymap.zig): the major mode, what is nested in it, and a dialog over
/// it. A mode that takes typed text keeps the unchorded printable keys of
/// those it sits in.
fn updateModeStack() void {
    var st: [8]keymap.ModeId = undefined;
    var n: usize = 0;
    const push = struct {
        fn f(buf: *[8]keymap.ModeId, len: *usize, m: keymap.ModeId) void {
            if (len.* < buf.len) {
                buf[len.*] = m;
                len.* += 1;
            }
        }
    }.f;
    push(&st, &n, kmode("global"));
    if (canvas_prompt) {
        push(&st, &n, kmode("start"));
    } else if (activeKind() == .sheet) {
        push(&st, &n, kmode("sheet"));
    } else if (sketch_edit != null) {
        push(&st, &n, kmode("sketch"));
        push(&st, &n, kmode("view"));
        if (sk_summary) push(&st, &n, kmode("sketch.summary"));
    } else if (panel_edit != null) {
        push(&st, &n, kmode("panel-edit"));
        push(&st, &n, kmode("view"));
    } else {
        push(&st, &n, kmode("canvas"));
        push(&st, &n, kmode("view"));
        if ((engage_n > 0 or engage_lock != null) and engaging()) push(&st, &n, kmode("canvas.engage"));
        if (selection.items.len > 0 and track_cursor == null) push(&st, &n, kmode("canvas.selection"));
        if (constrain_menu != null) push(&st, &n, kmode("canvas.constrain-menu"));
        if (constrain_objects_menu) push(&st, &n, kmode("canvas.constrain-objects"));
        if (track_cursor != null) push(&st, &n, kmode("canvas.flow"));
        if (track_cursor != null and case_picker) push(&st, &n, kmode("canvas.flow.case-picker"));
        if (canvas_eq) |q| {
            push(&st, &n, kmode("canvas.equation"));
            if (q.head != null) push(&st, &n, kmode("canvas.equation.head"));
        }
        if (expr_entry_id != null and expr_entry_id.? == dvui.focusedWidgetId()) {
            push(&st, &n, kmode("expression-line"));
            if (comp.items.len > 0) push(&st, &n, kmode("expression-line.completion"));
            if (equation_edit != null) push(&st, &n, kmode("expression-line.run"));
        }
    }
    if (filePromptOpen() or export_prompt or layout_prompt or image_prompt or constrain_prompt != null or display_window) {
        push(&st, &n, kmode("dialog"));
    } else if (size_window) push(&st, &n, kmode("dialog.calibrate-size"));
    if (text_wanted != null or dg_entry.active()) push(&st, &n, kmode("text-entry"));
    if (dg_entry.active()) push(&st, &n, kmode("digraph"));
    keymap.setStack(st[0..n]);
}

// Digraphs ----------------------------------------------------------------
//
// Ctrl+K, then two characters, types the character they stand for
// (digraphs.zig): in canvas text and the toolkit's fields alike, because
// the typed text is changed before anything reads it. Text is being typed
// where the last frame asked for text input (`text_wanted`, its place).

var dg_table: digraphs.Table = .{};
var dg_entry: digraphs.Entry = .{};
/// Where text input was asked for last frame (natural pixels), if it was.
var text_wanted: ?dvui.Rect.Natural = null;
/// Where the digraph's hint shows: the text's place when Ctrl+K was typed.
var dg_rect: dvui.Rect.Natural = .{};
/// The canvas's caret this frame (its bar's box, physical pixels), when it
/// is drawn: the digraph's hint goes by it.
var caret_mark: ?dvui.Rect.Physical = null;

fn markCaret(a: dvui.Point.Physical, b: dvui.Point.Physical) void {
    caret_mark = .{ .x = @min(a.x, b.x), .y = @min(a.y, b.y), .w = @abs(a.x - b.x), .h = @abs(a.y - b.y) };
}
/// A pair that stood for nothing, shown in the hint for a moment.
var dg_miss: ?digraphs.Pair = null;
var dg_miss_until: i128 = 0;

/// The user's digraphs, from the config's `[digraphs]` table: each key two
/// characters, each value what they stand for ("" takes a built-in away).
fn loadDigraphs(ps: *const settings_file.Store) void {
    dg_table.user.clearRetainingCapacity();
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const keys = ps.keys(arena.allocator()) catch return;
    var bad: usize = 0;
    for (keys) |k| {
        if (!std.mem.startsWith(u8, k, "digraphs.")) continue;
        const v = ps.get(k) orelse continue;
        const pair = digraphs.parseKey(k["digraphs.".len..]) orelse {
            bad += 1;
            continue;
        };
        if (v != .string or !(dg_table.put(state.gpa, pair, v.string) catch false)) bad += 1;
    }
    if (bad > 0) state.status = "A [digraphs] entry is not two characters standing for some text: it is left out. ";
}

/// Before any widget reads the frame's events: Ctrl+K where text is typed
/// starts a digraph; the characters typed after it are taken, and the
/// second one's text event carries what the pair stands for instead, so
/// whatever has the keyboard types that.
fn digraphEvents() void {
    for (dvui.events()) |*e| {
        if (e.handled) continue;
        if (!dg_entry.active()) {
            if (text_wanted == null) continue;
            if (keymap.takenByEditor(e, kmode("text-entry"))) continue;
            const inv = keymap.match1(e, kmode("text-entry")) orelse continue;
            if (inv.action != kact("text.digraph")) continue;
            e.handled = true;
            dg_entry.start();
            dg_rect = text_wanted.?;
            dg_miss = null;
            continue;
        }
        switch (e.evt) {
            .key => |k| {
                if (keymap.match1(e, kmode("digraph"))) |inv| {
                    if (inv.action == kact("digraph.cancel")) dg_entry.cancel();
                    if (inv.action == kact("digraph.back")) dg_entry.back();
                    e.handled = true;
                    continue;
                }
                if (k.action == .up or k.code.isModifier()) continue;
                // A key that types: its text follows, taken below. Any other
                // key (an arrow, Enter, a chord) ends the digraph and acts.
                const m = k.mod;
                if (keymap.printable(k.code) and !m.control() and !m.alt() and !m.command()) {
                    e.handled = true;
                } else dg_entry.cancel();
            },
            .text => |*t| switch (t.action) {
                .value => |*v| {
                    var it = (std.unicode.Utf8View.init(v.txt) catch {
                        dg_entry.cancel();
                        continue;
                    }).iterator();
                    var out: ?[]const u8 = null;
                    while (dg_entry.active()) {
                        const cp = it.nextCodepoint() orelse break;
                        switch (dg_entry.feed(&dg_table, cp)) {
                            .more => {},
                            .done => |s| out = s,
                            .none => |pair| {
                                dg_miss = pair;
                                dg_miss_until = std.Io.Timestamp.now(dvui.io, .awake).nanoseconds + 2 * std.time.ns_per_s;
                            },
                        }
                    }
                    // What the pair stands for, and anything typed after it.
                    const rest = v.txt[it.i..];
                    const a = dvui.currentWindow().arena();
                    if (std.mem.concat(a, u8, &.{ out orelse "", rest })) |txt| {
                        if (txt.len == 0) e.handled = true else v.txt = txt;
                    } else |_| e.handled = true;
                },
                else => {},
            },
            else => {},
        }
    }
}

/// While a digraph is typed: the pairs the first character starts, by
/// the text being typed; a moment after a pair that stood for nothing,
/// that.
fn digraphHint() void {
    const S = struct {
        var shown: [3]u32 = .{ 0, 0, 0 };
    };
    const now = std.Io.Timestamp.now(dvui.io, .awake).nanoseconds;
    const miss = if (dg_miss != null and now < dg_miss_until) dg_miss else null;
    // A new hint is laid out over two frames: ask for the second.
    const key: [3]u32 = .{ @intFromEnum(dg_entry.state), dg_entry.first, if (miss) |p| p[0] +% p[1] *% 31 +% 1 else 0 };
    if (!std.mem.eql(u32, &key, &S.shown)) dvui.refresh(null, @src(), null);
    S.shown = key;
    if (!dg_entry.active() and miss == null) return;
    if (miss != null) dvui.refresh(null, @src(), null);
    var buf: [160]digraphs.Candidate = undefined;
    const cands: []const digraphs.Candidate = if (dg_entry.state == .second) dg_table.candidates(dg_entry.first, &buf) else &.{};
    const per_row: usize = 8;
    const rows = (cands.len + per_row - 1) / per_row;
    const font = ghost_pane.fieldFont();
    const line_h = font.textHeight() + 6;
    const w: f32 = if (cands.len > 0) 8 + @as(f32, @floatFromInt(@min(cands.len, per_row))) * 58 else 340;
    const h: f32 = 12 + line_h * @as(f32, @floatFromInt(1 + rows));
    // By the canvas's caret, below it (above when there is no room); over
    // a field, above it; else inside the place's top left corner.
    const ns = dvui.windowNaturalScale();
    const win = dvui.windowRect();
    const at: dvui.Rect.Natural = if (caret_mark) |c| blk: {
        const below = (c.y + c.h) / ns + 8;
        const y = if (below + h > win.h) @max(0, c.y / ns - h - 8) else below;
        break :blk .{ .x = @min(@max(0, c.x / ns - 16), @max(0, win.w - w)), .y = y, .w = w, .h = h };
    } else if (dg_rect.h > 120)
        .{ .x = dg_rect.x + 12, .y = dg_rect.y + 12, .w = w, .h = h }
    else
        .{ .x = dg_rect.x, .y = if (dg_rect.y - h - 4 >= 0) dg_rect.y - h - 4 else dg_rect.y + dg_rect.h + 4, .w = w, .h = h };
    var fw: dvui.FloatingWidget = undefined;
    // Over everything, the panes too; the pointer goes through it.
    fw.init(@src(), .{ .stay_above_parent = false, .mouse_events = false }, .{
        .rect = .{ .x = at.x, .y = at.y, .w = at.w, .h = at.h },
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) },
        .border = .all(1),
        .corners = .all(6),
        .padding = .all(4),
    });
    defer fw.deinit();
    dvui.raiseSubwindow(fw.data().id);
    var tb: [96]u8 = undefined;
    var a8: [4]u8 = undefined;
    var b8: [4]u8 = undefined;
    const title = if (miss) |p|
        std.fmt.bufPrint(&tb, "No digraph for {s}{s}", .{ a8[0 .. std.unicode.utf8Encode(p[0], &a8) catch 0], b8[0 .. std.unicode.utf8Encode(p[1], &b8) catch 0] }) catch ""
    else if (dg_entry.state == .first)
        "Digraph: type two characters  (Esc: cancel)"
    else if (cands.len == 0)
        std.fmt.bufPrint(&tb, "Digraph {s}…  (no pairs start so)", .{a8[0 .. std.unicode.utf8Encode(dg_entry.first, &a8) catch 0]}) catch ""
    else
        std.fmt.bufPrint(&tb, "Digraph {s}…", .{a8[0 .. std.unicode.utf8Encode(dg_entry.first, &a8) catch 0]}) catch "";
    dvui.labelNoFmt(@src(), title, .{}, .{ .font = font, .padding = .{ .x = 4, .y = 2, .w = 4, .h = 2 } });
    for (0..rows) |row| {
        var hb = dvui.box(@src(), .{ .dir = .horizontal }, .{ .id_extra = row });
        defer hb.deinit();
        for (cands[row * per_row .. @min(cands.len, (row + 1) * per_row)], 0..) |c, i| {
            var lb: [48]u8 = undefined;
            const second = b8[0 .. std.unicode.utf8Encode(c.second, &b8) catch 0];
            const txt = std.fmt.bufPrint(&lb, "{s} {s}", .{ second, c.out }) catch "";
            dvui.labelNoFmt(@src(), txt, .{}, .{ .id_extra = i, .font = font, .min_size_content = .{ .w = 50 }, .padding = .{ .x = 4, .y = 2, .w = 4, .h = 2 } });
        }
    }
}

/// The direction of `canvas.object.nudge` (or `…-far`) if event `e` asks
/// for it, with `nudge_mm` set to the step. A selection takes the arrows
/// itself (`selectionAction`).
fn canvasNudge(e: *const dvui.Event) ?keymap.Direction {
    if (selection.items.len > 0) return null;
    const inv = keymap.match1(e, kmode("canvas")) orelse return null;
    const far = inv.action == kact("canvas.object.nudge-far");
    if (inv.action != kact("canvas.object.nudge") and !far) return null;
    nudge_mm = nudgeStep(far);
    nudge_far = far;
    return inv.dir();
}

/// The step of the nudge being made, mm, and whether it is the far one.
var nudge_mm: f64 = 1;
var nudge_far = false;

/// How the document's unit divides on the grid and in nudges: inches in
/// fractions as a ruler has them, the rest in tenths.
fn gridScale() bg_grid.Scale {
    return if (docUnits() == .inch) .imperial else .decimal;
}

/// A nudge's step, mm: the grid's minor unit at this zoom (its finest
/// lines that show: 0.1, 1, 10 mm …, or 1/16, 1/8 … in), or with Shift
/// its major one (its strongest lines), so a nudge moves by what the paper
/// shows.
fn nudgeStep(major: bool) f64 {
    const unit_mm = 1 / docUnits().perMm();
    var buf: [8]bg_grid.Level = undefined;
    const lv = gridLevels(bg_grid.fade_lo, &buf);
    const u = bg_grid.units(lv) orelse return unit_mm;
    return (if (major) u.major else u.minor) * unit_mm;
}

/// A length `mm` in the document's units as a person reads it: inches as
/// a fraction (3/16 in) where it is one, else a decimal.
fn lengthText(buf: []u8, mm: f64) []const u8 {
    const u = docUnits();
    const v = mm * u.perMm();
    if (u == .inch) {
        var fb: [24]u8 = undefined;
        if (bg_grid.fraction(&fb, v)) |f| return std.fmt.bufPrint(buf, "{s} in", .{f}) catch "";
    }
    return std.fmt.bufPrint(buf, "{d} {s}", .{ @round(v * 1000) / 1000, u.symbol() }) catch "";
}

/// An arrow key's code for direction `d` (what the move functions take).
fn arrowCode(d: keymap.Direction) dvui.enums.Key {
    return switch (d) {
        .left => .left,
        .right => .right,
        .up => .up,
        .down => .down,
    };
}

fn canvasEvents(box: *dvui.BoxWidget, area: dvui.Rect.Physical) void {
    // A tool waiting for the canvas: Add panel (a drag) or Add label (a click).
    const drawing = state.tool != .select;
    canvas_id = box.data().id;
    validateCursor();
    followLeading();
    for (dvui.events()) |*e| {
        // While a new canvas's units are asked for, the canvas takes no
        // input but Enter, which makes it (unless an open or save prompt
        // is on top, which takes the Enter).
        if (canvas_prompt) {
            if (!filePromptOpen() and if (keymap.match1(e, kmode("start"))) |inv| inv.action == kact("start.new-canvas-last") else false) {
                e.handle(@src(), box.data());
                createCanvas(last_units);
                dvui.refresh(null, @src(), box.data().id);
            }
            continue;
        }
        // The view's keys (zoom), in any mode the canvas is in; an
        // unchorded one only while no text field has the keyboard. The
        // sketch editor's own keys come first (C, U).
        const sketch_key = sketch_edit != null and keymap.match1(e, kmode("sketch")) != null;
        if (!sketch_key) if (keymap.match1(e, kmode("view"))) |inv| {
            if (inv.action == kact("view.pan-hold")) {
                if (cursorKeysReach()) {
                    space_pan = true;
                    pan_axis = null;
                    dvui.cursorSet(.hand);
                    e.handle(@src(), box.data());
                    continue;
                }
            } else if (inv.action == kact("view.zoom-hold")) {
                if (cursorKeysReach()) {
                    zoom_hold = .{ .out = inv.arg == 1 };
                    e.handle(@src(), box.data());
                    continue;
                }
            } else if ((inv.chorded or cursorKeysReach()) and runAction(inv)) {
                e.handle(@src(), box.data());
                continue;
            }
        };
        if (space_pan and keymap.released(e, kmode("view")) == kact("view.pan-hold")) {
            space_pan = false;
            e.handle(@src(), box.data());
            continue;
        }
        if (key_hold) |h| if (keymap.released(e, kmode("canvas")) == h.inv.action) {
            // Tapped: its action; held: the drop stays while the pointer is
            // in it.
            key_hold = null;
            e.handle(@src(), box.data());
            if (!h.opened) {
                _ = runAction(h.inv);
            } else if (!drop_entered) drop_open = null;
            dvui.refresh(null, @src(), box.data().id);
            continue;
        };
        if (zoom_hold != null and keymap.released(e, kmode("view")) == kact("view.zoom-hold")) {
            // Tapped, no drag: a step about the pointer.
            const zh = zoom_hold.?;
            zoom_hold = null;
            if (!zh.used) {
                const pct = zoomPercent();
                const to = display.nextZoom(pct, !zh.out);
                if (pct > 0) zoomAbout(area, dvui.currentWindow().mouse_pt, to / pct);
            }
            e.handle(@src(), box.data());
            dvui.refresh(null, @src(), box.data().id);
            continue;
        }
        // Scrolling, pinching and Z-drags, whatever mode the canvas is in.
        if (viewNavEvent(e, box, area)) continue;
        // The constraint pop-up's keys (H, V, D, Escape) while it is open.
        if (constrain_menu != null) if (keymap.match1(e, kmode("canvas.constrain-menu"))) |inv| {
            e.handle(@src(), box.data());
            _ = runAction(inv);
            dvui.refresh(null, @src(), box.data().id);
            continue;
        };
        if (constrain_objects_menu) if (keymap.match1(e, kmode("canvas.constrain-objects"))) |inv| {
            e.handle(@src(), box.data());
            _ = runAction(inv);
            dvui.refresh(null, @src(), box.data().id);
            continue;
        };
        // Ctrl+< and Ctrl+>: a level out or in, whatever is being edited.
        if (!canvas_prompt and sketch_edit == null and cursorKeysReach()) if (keymap.match1(e, kmode("canvas"))) |inv| {
            // The ribbon's tools, each by its key; one with a drop runs on
            // release, its drop opening if the key is held.
            const an = keymap.R.actionName(inv.action);
            if (std.mem.startsWith(u8, an, "tool.") or std.mem.startsWith(u8, an, "ribbon.")) {
                e.handle(@src(), box.data());
                if (Drop.heldBy(inv.action) != null) {
                    if (key_hold == null) key_hold = .{ .inv = inv, .t0 = std.Io.Clock.awake.now(dvui.io).toMilliseconds() };
                } else _ = runAction(inv);
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
            if (inv.action == kact("level.up") or inv.action == kact("level.down")) {
                e.handle(@src(), box.data());
                const moved = if (inv.action == kact("level.up")) levelUp() else levelDown();
                state.status = if (moved) levelStatus() else if (inv.action == kact("level.up")) "Nothing further out. " else "Nothing further in. ";
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        };
        // Sketch mode takes the canvas's events.
        if (sketch_edit != null) {
            sketchEvent(e, box, area);
            continue;
        }
        if (panel_edit != null) {
            panelEditEvent(e, box, area);
            continue;
        }
        // A selected track's arrow keys move it, while the canvas or the
        // palette has the keyboard.
        if (track_cursor == null and state.context == .row and cursorKeysReach()) {
            if (canvasNudge(e)) |d| {
                // A track's segment moves by its own step (Shift: four,
                // a whole unit of a quarter-step track).
                for (0..@as(usize, if (nudge_far) 4 else 1)) |_| moveTrackArrow(switch (d) {
                    .left => .left,
                    .right => .right,
                    .up => .up,
                    .down => .down,
                });
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // A tile's text edited on the canvas ends when the tile is no
        // longer the one selected.
        if (canvas_eq) |q| if (q.target == .tile_track) {
            const still = switch (state.context) {
                .tile => |id| id == q.target.tile_track.tile,
                else => false,
            };
            if (!still) canvas_eq = null;
        };
        // Ctrl+\ on a selected tile: its text edited on the canvas.
        if (canvas_eq == null and !canvas_prompt and cursorKeysReach() and state.context == .tile) {
            if (if (keymap.match1(e, kmode("canvas"))) |inv| inv.action == kact("canvas.tile.edit-text") else false) {
                e.handle(@src(), box.data());
                enterTileTrack(state.context.tile);
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // Editing an equation on the canvas: its keys and its typing first.
        if (canvas_eq != null and !e.handled and !canvas_prompt and cursorKeysReach()) {
            // The head's keys first (when the caret is on a head), then
            // the equation's.
            const head_modes = [_]keymap.ModeId{ kmode("canvas.equation.head"), kmode("canvas.equation") };
            const in: []const keymap.ModeId = if (canvas_eq.?.head != null) &head_modes else head_modes[1..];
            if (keymap.match(e, in)) |inv| {
                if (eqAction(inv)) {
                    e.handle(@src(), box.data());
                    dvui.refresh(null, @src(), box.data().id);
                    continue;
                }
            }
            if (e.evt == .text) {
                const txt = switch (e.evt.text.action) {
                    .value => |v| v.txt,
                    else => "",
                };
                if (txt.len > 0 and txt[0] >= ' ') {
                    e.handle(@src(), box.data());
                    eqType(txt);
                    dvui.refresh(null, @src(), box.data().id);
                    continue;
                }
            }
        }
        // Typing at the flow cursor goes into the flow.
        // The text of a key taken by its place (a case picked by digit).
        if (swallow_text) switch (e.evt) {
            .text => {
                swallow_text = false;
                e.handle(@src(), box.data());
                continue;
            },
            .key => |k| if (k.action == .down and !isModifierKey(k.code)) {
                swallow_text = false;
            },
            else => {},
        };
        if (e.evt == .text and !e.handled and track_cursor != null and !case_picker and !canvas_prompt and cursorKeysReach()) {
            const txt = switch (e.evt.text.action) {
                .value => |v| v.txt,
                else => "",
            };
            if (txt.len > 0 and txt[0] >= ' ') {
                e.handle(@src(), box.data());
                if (caseSort(txt)) |sort| insertSort(sort) else typeIntoFlow(txt);
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // A selected group: arrow keys move all of it 1 mm.
        if (state.context == .group and cursorKeysReach()) {
            if (if (canvasNudge(e)) |d| moveGroupKey(arrowCode(d)) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // A selected image: arrow keys move it 1 mm.
        if (state.context == .image and cursorKeysReach()) {
            if (if (canvasNudge(e)) |d| moveImageKey(arrowCode(d)) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // A selected view: arrow keys move it 1 mm.
        if (state.context == .view and cursorKeysReach()) {
            if (if (canvasNudge(e)) |d| moveViewKey(arrowCode(d)) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // Selected line art: arrow keys move it 1 mm, and the tracks under
        // it reflow.
        if (state.context == .art and cursorKeysReach()) {
            if (if (canvasNudge(e)) |d| moveArtKey(arrowCode(d)) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // The selection's keys: Tab hunts on to the next-nearest container
        // of the last Ctrl-click (Shift+Tab back), Esc empties it, and the
        // arrows move it.
        // Engagement: Tab locks onto the point the pointer engages.
        if ((engage_n > 0 or engage_lock != null) and engaging() and cursorKeysReach()) {
            if (if (keymap.match1(e, kmode("canvas.engage"))) |inv| engageAction(inv) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        if (selection.items.len > 0 and track_cursor == null and cursorKeysReach()) {
            if (if (keymap.match1(e, kmode("canvas.selection"))) |inv| selectionAction(inv) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        // The flow cursor's keys, while the canvas or the palette has the
        // keyboard: never from a text entry.
        if (track_cursor != null and cursorKeysReach()) {
            // Choosing a case: its keys first; any other key ends it.
            const picker = [_]keymap.ModeId{ kmode("canvas.flow.case-picker"), kmode("canvas.flow") };
            const in: []const keymap.ModeId = if (case_picker) &picker else picker[1..];
            const inv = keymap.match(e, in);
            // (A printable key's own key-down is left: its text follows;
            // so are the modifiers.)
            const ends = switch (e.evt) {
                .text => true,
                .key => |k| k.action == .down and !keymap.printable(k.code) and !isModifierKey(k.code),
                else => false,
            };
            if (case_picker and !e.handled and ends and (inv == null or !keymap.actionUnder(inv.?.action, "canvas.flow.case-picker"))) {
                // Typed characters search the cases' names.
                if (e.evt == .text and inv == null) {
                    if (e.evt.text.action == .value) caseQueryAdd(e.evt.text.action.value.txt);
                    e.handle(@src(), box.data());
                    dvui.refresh(null, @src(), box.data().id);
                    continue;
                }
                case_picker = false;
            }
            if (if (inv) |v| flowAction(v) else false) {
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
        }
        if (e.evt == .key and state.moving != null) {
            if (if (keymap.match1(e, kmode("canvas"))) |inv| inv.action == kact("canvas.tool.cancel") else false) {
                e.handle(@src(), box.data());
                state.moving = null;
                dvui.refresh(null, @src(), box.data().id);
            }
            continue;
        }
        if (e.evt == .key and drawing) {
            const inv = keymap.match1(e, kmode("canvas"));
            const is = struct {
                fn f(i: ?keymap.Invocation, a: keymap.ActionId) bool {
                    return if (i) |x| x.action == a else false;
                }
            }.f;
            if (is(inv, kact("canvas.tool.cancel"))) {
                e.handle(@src(), box.data());
                // A construction line half made: dropped, the tool kept.
                if (state.tool == .construction and guide_start != null) {
                    guide_start = null;
                    guide_pending = false;
                    dvui.refresh(null, @src(), box.data().id);
                    continue;
                }
                state.tool = .select;
                state.drag = null;
                constrain_first = null;
                constrain_hover = null;
                polygon_pts.clearRetainingCapacity();
                dvui.refresh(null, @src(), box.data().id);
            } else if (is(inv, kact("canvas.tool.finish")) and state.tool == .add_art and polygon_pts.items.len > 0) {
                e.handle(@src(), box.data());
                finishPolygon();
                dvui.refresh(null, @src(), box.data().id);
            }
            continue;
        }
        if (!dvui.eventMatchSimple(e, box.data())) continue;
        if (e.evt == .key) {
            // Keys reach the canvas only while it has focus.
            const del = if (keymap.match1(e, kmode("canvas"))) |inv| inv.action == kact("canvas.object.delete") else false;
            if (del and picked_constraint != null) {
                act(.removeConstraint, .{picked_constraint.?}) catch {};
                picked_constraint = null;
                e.handle(@src(), box.data());
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
            if (del and path_selected != null and pathRegion() != null) {
                act(.removeControlPoint, .{path_selected.?}) catch {};
                path_selected = null;
                e.handle(@src(), box.data());
                continue;
            }
            if (del and state.context == .guide) {
                e.handle(@src(), box.data());
                _ = runButtonAction(.{ .action = kact("guide.remove"), .arg = 0 });
                dvui.refresh(null, @src(), box.data().id);
                continue;
            }
            if (del and state.moving == null) {
                switch (state.context) {
                    .panel => |pi| {
                        e.handle(@src(), box.data());
                        actV(.removePanel, .{pi});
                        state.context = workspaceContext();
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    // The same action as its Remove button.
                    .region => {
                        e.handle(@src(), box.data());
                        _ = runButtonAction(.{ .action = kact("track.remove"), .arg = 0 });
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    .art => |l| {
                        e.handle(@src(), box.data());
                        actV(.removeArt, .{l.panel, l.index});
                        state.context = .{ .panel = l.panel };
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    .sketch => |sc| {
                        e.handle(@src(), box.data());
                        actV(.removeSketchView, .{ sc.space, sc.index });
                        state.context = .{ .space = sc.space };
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    .figure_place => |c| {
                        e.handle(@src(), box.data());
                        actV(.removeFigurePlace, .{ c.space, c.index });
                        selection.clearRetainingCapacity();
                        state.context = .{ .space = c.space };
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    .image => |im| {
                        e.handle(@src(), box.data());
                        actV(.removeImage, .{im.space, im.index});
                        state.context = .{ .space = im.space };
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    .view => |v| {
                        e.handle(@src(), box.data());
                        actV(.removeView, .{v.space, v.index});
                        state.context = .{ .space = v.space };
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    // A tile leaves its track, which closes up behind it.
                    .tile => |id| {
                        e.handle(@src(), box.data());
                        const found = findTile(id);
                        actV(.removeTile, .{id});
                        // Its track, while that still exists (a grid's tile
                        // may leave none behind), else its panel.
                        state.context = if (found) |f| blk: {
                            if (!state.model.hasParent(f.parent)) break :blk .worksheet;
                            if (f.tile.region >= state.model.regionsIn(f.parent).len) break :blk parentContext(f.parent);
                            break :blk .{ .row = .{ .parent = f.parent, .region = f.tile.region, .row = f.tile.row } };
                        } else .worksheet;
                        dvui.refresh(null, @src(), box.data().id);
                    },
                    else => {},
                }
            }
            continue;
        }
        if (e.evt != .mouse) continue;
        const me = e.evt.mouse;
        switch (me.action) {
            // A press first sends a focus event; taking it gives the canvas
            // keyboard focus, for Delete and the like.
            .focus => {
                e.handle(@src(), box.data());
                dvui.focusWidget(box.data().id, null, e.num);
            },
            .position => {
                // The pointer's worksheet position, for the rulers and readout.
                const at = state.view.toMm(area, me.p);
                state.mouse = if (area.contains(me.p) and (openCanvas() or contains(state.model.sheet.box(), at))) at else null;
                // Engagement points near the pointer; a lock lets go when
                // the pointer goes well away.
                if (engage_drag == null) {
                    // Redrawn only when what is engaged changes (a
                    // position event comes every frame).
                    const before = engageKey();
                    if (area.contains(me.p)) findEngagements(area, at) else engage_n = 0;
                    if (engage_lock != null) {
                        const lx = me.p.x - engage_lock_px.x;
                        const ly = me.p.y - engage_lock_px.y;
                        const ns_ = dvui.windowNaturalScale();
                        if (lx * lx + ly * ly > 60 * 60 * ns_ * ns_) engage_lock = null;
                    }
                    // Locked, the spark's offset from the pointer changes as
                    // it moves.
                    const moved = me.p.x != engage_last_px.x or me.p.y != engage_last_px.y;
                    engage_last_px = me.p;
                    if (engageKey() != before or (engage_lock != null and moved)) dvui.refresh(null, @src(), box.data().id);
                }
                if (state.tool == .constrain) {
                    const was = constrain_hover;
                    constrain_hover = if (area.contains(me.p)) featureHit(at) else null;
                    if (!std.meta.eql(was, constrain_hover)) dvui.refresh(null, @src(), box.data().id);
                }
                pointer_mark = null;
                if (state.tool == .select and area.contains(me.p)) if (selectionPointer(at)) |c| {
                    // Over the selection: a hand to grab it, a lock where
                    // it cannot move, arrows on a resize handle. The hand
                    // and the lock are drawn here (no system cursor has
                    // them).
                    switch (c) {
                        .cursor => |sys| dvui.cursorSet(sys),
                        else => {
                            dvui.cursorSet(.hidden);
                            pointer_mark = .{ .mark = c, .p = me.p };
                        },
                    }
                    dvui.refresh(null, @src(), box.data().id);
                };
                if (pointer_mark != null or resize_drag != null) {
                    // Set above.
                } else if (drawing) {
                    dvui.cursorSet(.crosshair);
                } else if (state.moving != null) {
                    dvui.cursorSet(.arrow_all);
                } else if (panelToMove(state.view.toMm(area, me.p)) != null) {
                    // Over a panel a drag would move, show that it can be.
                    dvui.cursorSet(.arrow_all);
                }
            },
            .press => if ((me.button.pointer() or me.button == .middle) and area.contains(me.p)) {
                e.handle(@src(), box.data());
                dvui.captureMouse(box.data(), e.num);
                if (state.tool == .construction and me.button.pointer()) {
                    // Construction line: a drag from its first point, or a
                    // click there and a click at its second.
                    const at = snap(state.view.toMm(area, me.p));
                    if (guide_pending) {
                        if (guide_start) |p0| addGuideThrough(p0, at, me.mod.shift());
                        guide_start = null;
                        guide_pending = false;
                    } else {
                        guide_start = at;
                        guide_press_px = me.p;
                    }
                    state.press_consumed = true;
                } else if (state.tool == .select_area and me.button.pointer()) {
                    const at = state.view.toMm(area, me.p);
                    state.drag = .{ .start = at, .at = at };
                } else if (state.tool == .add_art and me.button.pointer()) {
                    // Line art is drawn from a point on its panel; a polygon
                    // takes a click per corner.
                    const at = state.view.toMm(area, me.p);
                    if (state.context == .panel and panelHolds(state.context.panel, at)) {
                        const p = snap(at);
                        if (shape_kind == .polygon) {
                            polygonClick(state.context.panel, p);
                            state.press_consumed = true;
                        } else state.drag = .{ .start = p, .at = p };
                    }
                } else if (state.tool == .add_array and me.button.pointer()) {
                    // An array is a container: on the workspace, or on the
                    // panel chosen.
                    const at = state.view.toMm(area, me.p);
                    if ((state.context == .panel and panelHolds(state.context.panel, at)) or state.context == .space) {
                        const p = snap(at);
                        state.drag = .{ .start = p, .at = p };
                    }
                } else if (state.tool == .add_tracks and me.button.pointer()) {
                    // Tracks are drawn from a point on the panel chosen for them.
                    const at = state.view.toMm(area, me.p);
                    // Or anywhere on the workspace: a content layout is a
                    // container of its own there.
                    if ((state.context == .panel and panelHolds(state.context.panel, at)) or state.context == .space) {
                        const p = snap(at);
                        state.drag = .{ .start = p, .at = p };
                    }
                } else if (state.tool == .new_sketch and me.button.pointer()) {
                    state.tool = .select;
                    state.press_consumed = true;
                    newSketchAt(state.view.toMm(area, me.p));
                } else if (state.tool == .constrain and me.button.pointer()) {
                    constrainClick();
                    state.press_consumed = true;
                } else if (state.tool == .join and me.button.pointer()) {
                    joinClick(state.view.toMm(area, me.p));
                    state.press_consumed = true;
                } else if (space_pan and me.button.pointer()) {
                    // Space held: a drag pans, whatever is under it.
                    state.press_at = null;
                    dvui.dragPreStart(me.button, me.p, .{ .cursor = .hand });
                } else if (state.tool == .select and me.button.pointer() and !primaryMod(me.mod) and !engagingPoint() and !selectionHandleAt(state.view.toMm(area, me.p)) and textPress(state.view.toMm(area, me.p), me.mod.shift())) {
                    // Well inside a used segment of a text track: the text
                    // cursor there, typing (see "Clicking into text").
                    state.press_consumed = true;
                    dvui.refresh(null, @src(), box.data().id);
                } else if (state.tool == .select and boundary_mode and me.button.pointer() and !me.mod.shift() and !primaryMod(me.mod) and !engagingPoint() and !selectionHandleAt(state.view.toMm(area, me.p)) and nearestBoundary(state.view.toMm(area, me.p)) != null) {
                    // Select boundaries: the nearest boundary's container,
                    // made the selection (its drag points shown). With no
                    // boundary in reach, the press is a plain one: a click
                    // on the canvas or frame chooses it.
                    _ = hoverPress(state.view.toMm(area, me.p));
                    state.press_consumed = true;
                    last_click = null;
                    dvui.refresh(null, @src(), box.data().id);
                } else if (state.tool == .select and me.button.pointer() and !me.mod.shift() and !primaryMod(me.mod) and !engagingPoint() and hoverPress(state.view.toMm(area, me.p))) {
                    // Pointing: a container by its outline, content from
                    // inside (see "Pointing").
                    state.press_consumed = true;
                    last_click = null;
                    dvui.refresh(null, @src(), box.data().id);
                } else if (state.tool == .select and me.button.pointer() and (me.mod.shift() or primaryMod(me.mod))) {
                    // Shift-click (or Ctrl-click): the container there in
                    // or out of the selection.
                    shiftClick(state.view.toMm(area, me.p));
                    state.press_consumed = true;
                } else if (state.tool == .select and me.button.pointer() and engaging() and engagePress(state.view.toMm(area, me.p))) {
                    hunt_clear();
                } else if (state.tool == .select and me.button.pointer() and selectionPress(state.view.toMm(area, me.p))) {
                    hunt_clear();
                } else if (state.tool == .select and me.button.pointer() and pathHit(state.view.toMm(area, me.p)) != null) {
                    const at = state.view.toMm(area, me.p);
                    const hit = pathHit(at).?;
                    const t = pathRegion().?;
                    path_drag = .{ .parent = t.parent, .region = t.region, .id = hit.id, .from_across = hit.across, .start = at, .at = at };
                } else if (drawing and me.button.pointer()) {
                    // A panel is drawn from a point on the sheet.
                    const at = snap(state.view.toMm(area, me.p));
                    if (openCanvas() or contains(state.model.sheet.box(), at)) state.drag = .{ .start = at, .at = at };
                } else {
                    state.press_at = if (me.button.pointer()) state.view.toMm(area, me.p) else null;
                    dvui.dragPreStart(me.button, me.p, .{});
                }
            },
            .motion => if (dvui.captured(box.data().id)) {
                if (text_drag) {
                    e.handle(@src(), box.data());
                    textDragTo(state.view.toMm(area, me.p));
                    dvui.refresh(null, @src(), box.data().id);
                } else if (dim_drag != null) {
                    e.handle(@src(), box.data());
                    dimMotion(state.view.toMm(area, me.p));
                    dvui.refresh(null, @src(), box.data().id);
                } else if (engage_drag != null) {
                    e.handle(@src(), box.data());
                    engageMotion(state.view.toMm(area, me.p));
                    dvui.refresh(null, @src(), box.data().id);
                } else if (resize_drag != null or sel_press != null) {
                    e.handle(@src(), box.data());
                    selectionDrag(state.view.toMm(area, me.p));
                    dvui.refresh(null, @src(), box.data().id);
                } else if (state.drag) |*d| {
                    e.handle(@src(), box.data());
                    d.at = if (band_drag or state.tool == .select_area) state.view.toMm(area, me.p) else snap(state.view.toMm(area, me.p));
                    dvui.refresh(null, @src(), box.data().id);
                } else if (state.moving) |*mv| {
                    e.handle(@src(), box.data());
                    mv.at = state.view.toMm(area, me.p);
                    dvui.refresh(null, @src(), box.data().id);
                } else if (path_drag) |*pd| {
                    e.handle(@src(), box.data());
                    pd.at = state.view.toMm(area, me.p);
                    dvui.refresh(null, @src(), box.data().id);
                } else if (dvui.dragging(me, null)) |d| {
                    e.handle(@src(), box.data());
                    // A drag from a panel moves it; from line art, an
                    // image or a group, selects and moves it; from empty
                    // canvas, draws out an area. Space held (or the middle
                    // button) pans.
                    const from = state.press_at;
                    if (from == null or space_pan or state.tool != .select) {
                        state.view.fit = null;
                        // Shift: along the axis the drag first went.
                        var dx = d.x;
                        var dy = d.y;
                        if (me.mod.shift()) {
                            if (pan_axis == null and (@abs(dx) > 0 or @abs(dy) > 0)) pan_axis = if (@abs(dx) >= @abs(dy)) .x else .y;
                            if (pan_axis) |ax| switch (ax) {
                                .x => dy = 0,
                                .y => dx = 0,
                            };
                        } else pan_axis = null;
                        state.view.cx -= dx / state.view.ppm;
                        state.view.cy += dy / state.view.ppm;
                    } else if (grabbedPanel() != null or (dragTakes(from.?) != null and isPanelId(dragTakes(from.?).?))) {
                        if (grabbedPanel() == null) clickAt(from.?, me.p);
                        if (grabbedPanel()) |pi| state.moving = .{ .panel = pi, .start = from.?, .at = state.view.toMm(area, me.p) };
                    } else if (dragTakes(from.?)) |id| {
                        if (selectedAt(id) == null) {
                            pick(from.?);
                            selection.clearRetainingCapacity();
                            selection.append(state.gpa, id) catch {};
                        }
                        if (selectionPress(from.?)) selectionDrag(state.view.toMm(area, me.p));
                    } else if (track_cursor == null) {
                        band_drag = true;
                        state.drag = .{ .start = from.?, .at = state.view.toMm(area, me.p) };
                    }
                    dvui.refresh(null, @src(), box.data().id);
                }
            },
            .release => if (dvui.captured(box.data().id)) {
                e.handle(@src(), box.data());
                if (state.tool == .construction and guide_start != null and !guide_pending) {
                    // Released where pressed (a few pixels allowed): the
                    // second point is a click; else the drag made the line.
                    const moved = @abs(me.p.x - guide_press_px.x) > 3 * dvui.windowNaturalScale() or @abs(me.p.y - guide_press_px.y) > 3 * dvui.windowNaturalScale();
                    if (moved) {
                        addGuideThrough(guide_start.?, snap(state.view.toMm(area, me.p)), me.mod.shift());
                        guide_start = null;
                    } else guide_pending = true;
                }
                if (dim_drag != null) {
                    _ = dimRelease();
                } else if (engage_drag != null) {
                    // A press on an engagement point that did not drag is
                    // a click.
                    if (!engageRelease()) clickAt(state.view.toMm(area, me.p), me.p);
                } else if (resize_drag != null or sel_press != null) {
                    // A click on a selected box that did not drag keeps
                    // its plain meaning.
                    const clicked = sel_press != null and !sel_press.?.moved;
                    selectionDragEnd();
                    if (clicked) clickAt(state.view.toMm(area, me.p), me.p);
                } else if (state.drag != null and band_drag) {
                    const d = state.drag.?;
                    state.drag = null;
                    band_drag = false;
                    selectArea(dragBox(d.start, d.at));
                    last_click = null;
                } else if (state.drag) |d| {
                    state.drag = null;
                    switch (state.tool) {
                        .add_tracks => addTracksFromDrag(d.start, d.at),
                        .add_array => if (array_tool.polar) addPolarFromDrag(d.start, d.at) else addArrayFromDrag(dragBox(d.start, d.at)),
                        .add_art => addArtFromDrag(dragBox(d.start, d.at)),
                        .select_area => selectArea(dragBox(d.start, d.at)),
                        .insert_figure => insertFigureFromDrag(d.start, d.at),
                        else => addPanelFromDrag(dragBox(d.start, d.at)),
                    }
                } else if (state.moving) |mv| {
                    finishMove(mv.panel);
                } else if (path_drag != null) {
                    finishPathDrag();
                } else if (state.press_consumed) {
                    state.press_consumed = false;
                } else if (dvui.dragging(me, null) == null) {
                    clickAt(state.view.toMm(area, me.p), me.p);
                }
                state.press_at = null;
                dvui.captureMouse(null, e.num);
                dvui.dragEnd(me.button);
                dvui.refresh(null, @src(), box.data().id);
            },
            else => {},
        }
    }
}


// One selection -------------------------------------------------------------
//
// A click selects: the context (what the properties show) is what lies
// under the pointer, as `pick` finds it, and the container it is (a panel,
// a track, line art, an image, a group) is the selection, with its box
// and the handles its constraints leave. Another click at the same place
// selects the container it sits in, and so on out, then back in. Shift
// (or Ctrl) and a click add the container there to the selection or take
// it out. A drag on a selected container moves the selection; on an
// unselected panel, line art, image or group it selects it and moves it;
// on empty canvas it draws out an area, selecting what lies wholly inside.
// Panning: Space held and a drag, a middle-button drag, or the wheel.
// A click that sets the flow cursor in a text track selects nothing (its
// text is being typed into).

/// Where and what the last plain click selected, to step out from.
var last_click: ?struct { px: dvui.Point.Physical, depth: usize } = null;

/// Space is held: a drag pans.
var space_pan = false;

// View navigation -------------------------------------------------------------
//
// Scrolling, pinching, and Z held for a zoom drag, the same on the canvas,
// in a sketch and in panel editing. Scrolling pans or zooms (View ›
// Scrolling): automatically, a trackpad's smooth scrolling pans and a
// mouse wheel's notches zoom (DVUI's guess from the scroll amounts, made
// at each scroll); Ctrl (or Cmd) and scrolling always zooms; with a wheel,
// Shift and scrolling pans across. A pinch zooms. Held keys stand in for
// mouse buttons a trackpad makes awkward: Space and a drag pans (Shift:
// along one axis), Z and a drag zooms; Z tapped zooms in a step at the
// pointer, Shift+Z out.

pub const ScrollMode = enum { auto, zoom, pan };
var scroll_mode: ScrollMode = .auto;

/// Z held: zooming out when tapped, and whether a drag has used it.
var zoom_hold: ?struct { out: bool = false, used: bool = false } = null;
/// A Z-drag: where it zooms about.
var zoom_drag: ?dvui.Point.Physical = null;
/// A Shift+Space pan's axis, once the drag has chosen it.
var pan_axis: ?enum { x, y } = null;

fn scrollPans() bool {
    return switch (scroll_mode) {
        .pan => true,
        .zoom => false,
        .auto => dvui.currentWindow().mouse_type == .trackpad,
    };
}

/// Zooms by `z` keeping point `p` (device pixels in `area`) where it is.
fn zoomAbout(area: dvui.Rect.Physical, p: dvui.Point.Physical, z: f64) void {
    if (!(z > 0) or !std.math.isFinite(z)) return;
    const at = state.view.toMm(area, p);
    state.view.ppm *= z;
    state.view.fit = null;
    state.view.cx = at.x - (at.x - state.view.cx) / z;
    state.view.cy = at.y - (at.y - state.view.cy) / z;
}

/// Whether event `e` was scrolling, a pinch or a Z-drag, done.
fn viewNavEvent(e: *dvui.Event, box: *dvui.BoxWidget, area: dvui.Rect.Physical) bool {
    if (e.evt != .mouse) return false;
    const me = e.evt.mouse;
    const ppm = state.view.ppm;
    if (!(ppm > 0)) return false;
    switch (me.action) {
        .wheel_y => |dy| {
            if (!dvui.eventMatchSimple(e, box.data())) return false;
            e.handle(@src(), box.data());
            if (primaryMod(me.mod) or (!scrollPans() and !me.mod.shift())) {
                zoomAbout(area, me.p, @exp(@log(1.003) * @as(f64, dy)));
            } else if (!scrollPans()) {
                // A wheel with Shift: across.
                state.view.cx -= dy / ppm;
                state.view.fit = null;
            } else {
                state.view.cy += dy / ppm;
                state.view.fit = null;
            }
        },
        .wheel_x => |dx| {
            if (!dvui.eventMatchSimple(e, box.data())) return false;
            e.handle(@src(), box.data());
            state.view.cx -= dx / ppm;
            state.view.fit = null;
        },
        .pinch_begin, .pinch_end => {
            if (!dvui.eventMatchSimple(e, box.data())) return false;
            e.handle(@src(), box.data());
        },
        .pinch_update => |scale| {
            if (!dvui.eventMatchSimple(e, box.data())) return false;
            e.handle(@src(), box.data());
            zoomAbout(area, me.p, scale);
        },
        .press => {
            if (zoom_hold == null or !me.button.pointer() or !area.contains(me.p)) return false;
            e.handle(@src(), box.data());
            dvui.captureMouse(box.data(), e.num);
            zoom_drag = me.p;
            zoom_hold.?.used = true;
        },
        .motion => |d| {
            const anchor = zoom_drag orelse return false;
            e.handle(@src(), box.data());
            // Up zooms in: doubling every 120 px.
            zoomAbout(area, anchor, std.math.pow(f64, 2, -d.y / (120 * dvui.windowNaturalScale())));
        },
        .release => {
            if (zoom_drag == null) return false;
            e.handle(@src(), box.data());
            zoom_drag = null;
            dvui.captureMouse(null, e.num);
        },
        else => return false,
    }
    dvui.refresh(null, @src(), box.data().id);
    return true;
}

/// A drag on empty canvas drawing out an area to select (in `state.drag`).
var band_drag = false;

/// The container context `c` is, if it is one.
fn objectOfContext(c: Context) ?layout.model.ObjectId {
    const id = switch (c) {
        .panel => |pi| if (pi < state.model.panels.items.len) state.model.panels.items[pi].id else return null,
        .region => |r| state.model.idAt(.{ .region = .{ .parent = r.parent, .index = r.region } }),
        .row => |r| state.model.idAt(.{ .region = .{ .parent = r.parent, .index = r.region } }),
        .art => |l| state.model.idAt(.{ .art = .{ .panel = l.panel, .index = l.index } }),
        .group => |g| g,
        .image => |im| if (imageAt(im.space, im.index)) |image| image.id else return null,
        .figure_place => |fc| if (figurePlaceAt(fc.space, fc.index)) |fp| fp.id else return null,
        else => return null,
    };
    return if (id == .none) null else id;
}

/// The context that shows container `id`: the panel holding it, for a
/// panel; else the selection.
fn contextOfObject(id: layout.model.ObjectId) Context {
    for (state.model.panels.items, 0..) |p, pi| if (p.id == id) return .{ .panel = pi };
    for (state.model.spaces.items, 0..) |sp, si| for (sp.figure_places.items, 0..) |fp, k| if (fp.id == id) return .{ .figure_place = .{ .space = si, .index = k } };
    return .selection;
}

/// The container `id` sits in (a track's or line art's panel), if any.
fn parentObject(id: layout.model.ObjectId) ?layout.model.ObjectId {
    if (state.model.group(id) != null) return null;
    const pr = constrain.parentOf(&state.model, id) orelse return null;
    return switch (pr) {
        .panel => |pi| if (pi < state.model.panels.items.len) state.model.panels.items[pi].id else null,
        .space => null,
    };
}

// Levels (decided 2026-11-20): Ctrl+< goes one level out, Ctrl+> one in
// (the keys < and > are on, Shift or not: Ctrl+, and Ctrl+. on a US
// layout). Out from in: an object chosen in an expression; the expression
// typed in (a tile's slot, a run); a track's content (the flow cursor);
// the container itself, a tile, a track, a grid, line art (its size and
// place in the properties); the panel holding it; the canvas. In goes back
// the way it came out, else to the first thing inside.

/// What Ctrl+> goes back into: what each Ctrl+< came out of, the last on
/// top. An entry that no longer fits where one is (something else was
/// chosen since) empties the trail.
const LevelBack = union(enum) {
    context: Context,
    cursor: TrackCursor,
    eq: CanvasEq,
};
var level_trail: [16]LevelBack = undefined;
var level_trail_n: usize = 0;
var level_back: ?LevelBack = null;

fn levelPush(b: LevelBack) void {
    if (level_trail_n == level_trail.len) {
        std.mem.copyForwards(LevelBack, level_trail[0 .. level_trail.len - 1], level_trail[1..]);
        level_trail_n -= 1;
    }
    level_trail[level_trail_n] = b;
    level_trail_n += 1;
}

/// The container holding context `c`'s, one level out; null at the top.
fn levelParent(c: Context) ?Context {
    return switch (c) {
        .tile => |id| blk: {
            if (state.model.gridInstanceOf(id)) |g| break :blk .{ .grid = .{ .parent = g.parent, .index = g.grid } };
            const f = findTile(id) orelse break :blk null;
            if (!state.model.hasParent(f.parent)) break :blk null;
            // The track it lies in: the segment of its flow that placed it,
            // which may be a later track of the thread than the flow's first.
            if (placedOf(f.parent)) |pl| for (pl.tracks) |tr| {
                if (tr.region == f.tile.region and tr.track == f.tile.row and tr.flow_parent.eql(f.parent)) break :blk .{ .region = .{ .parent = tr.parent, .region = tr.member } };
            };
            if (f.tile.region < state.model.regionsIn(f.parent).len) break :blk .{ .region = .{ .parent = f.parent, .region = f.tile.region } };
            break :blk parentContext(f.parent);
        },
        .region => |r| parentContext(r.parent),
        .row => |r| .{ .region = .{ .parent = r.parent, .region = r.region } },
        .art => |l| .{ .panel = l.panel },
        .grid => |g| parentContext(g.parent),
        .panel => |pi| blk: {
            if (pi >= state.model.panels.items.len or state.model.spaces.items.len == 0) break :blk null;
            break :blk .{ .space = state.model.spaceOf(pi) };
        },
        .space => null,
        .group, .selection, .image, .view, .sketch => blk: {
            const sp: usize = switch (c) {
                .image => |im| im.space,
                .view => |v| v.space,
                .sketch => |k| k.space,
                else => shown_space,
            };
            break :blk if (sp < state.model.spaces.items.len) .{ .space = sp } else null;
        },
        .worksheet => null,
        else => null,
    };
}

/// The first thing inside context `c`, one level in: a canvas's first
/// panel, a panel's first track (else grid, else line art), a grid's first
/// tile; null when there is none (a track goes in to its content, not
/// here).
fn levelFirstChild(c: Context) ?Context {
    switch (c) {
        .worksheet, .file => {
            if (state.model.panels.items.len > 0) return .{ .panel = 0 };
            return null;
        },
        .space => |si| {
            if (si >= state.model.spaces.items.len) return null;
            for (0..state.model.panels.items.len) |qi| if (state.model.spaceOf(qi) == si) return .{ .panel = qi };
            // Content layouts straight on the workspace.
            const sp = state.model.spaces.items[si];
            if (sp.regions.items.len > 0) return .{ .region = .{ .parent = .{ .space = si }, .region = 0 } };
            if (sp.grids.items.len > 0) return .{ .grid = .{ .parent = .{ .space = si }, .index = 0 } };
            return null;
        },
        .panel => |pi| {
            if (pi >= state.model.panels.items.len) return null;
            const p = state.model.panels.items[pi];
            if (p.regions.items.len > 0) return .{ .region = .{ .parent = .{ .panel = pi }, .region = 0 } };
            if (p.grids.items.len > 0) return .{ .grid = .{ .parent = .{ .panel = pi }, .index = 0 } };
            if (p.art.items.len > 0) return .{ .art = .{ .panel = pi, .index = 0 } };
            return null;
        },
        .grid => |g| {
            if (!state.model.hasParent(g.parent) or g.index >= state.model.gridsIn(g.parent).len) return null;
            for (state.model.gridsIn(g.parent)[g.index].instances.items) |inst| return .{ .tile = inst.tile };
            return null;
        },
        else => return null,
    }
}

fn levelSet(c: Context) void {
    state.context = c;
    selection.clearRetainingCapacity();
    hunt_clear();
    last_click = null;
    dvui.refresh(null, @src(), null);
}

/// The status after a level change: where one is now.
fn levelStatus() []const u8 {
    if (canvas_eq) |q| return if (q.head != null) "An object chosen: arrows nudge it, Tab the next; ⌃< out, ⌃> in. " else "Its text: type into it; ⌃< out to its container, ⌃> in to an object. ";
    if (track_cursor != null) return "The track's content: the flow cursor; ⌃< out to the track, ⌃> in to the item after the cursor. ";
    return std.fmt.bufPrint(&status_hunt_buf, "{s}: its size and place in the properties; ⌃< out, ⌃> in. ", .{state.context.kindName()}) catch "";
}

/// Ctrl+<: one level out. Whether there was one.
fn levelUp() bool {
    if (panel_edit != null) {
        leavePanelEdit();
        return true;
    }
    if (canvas_eq) |q| {
        if (q.head != null) {
            // An object chosen: what holds it, else back to typing.
            if (!eqOut()) eqRelease();
            return true;
        }
        // Typing: out of the expression, to the tile (or the flow cursor).
        levelPush(.{ .eq = q });
        leaveCanvasEquation();
        if (q.target == .tile_track) levelSet(.{ .tile = q.target.tile_track.tile });
        return true;
    }
    if (track_cursor) |c| {
        // In a track's content: the track itself.
        levelPush(.{ .cursor = c });
        track_cursor = null;
        flow_anchor = null;
        const ctx: Context = switch (state.context) {
            .region, .row => state.context,
            else => .{ .region = .{ .parent = c.parent, .region = c.region } },
        };
        levelSet(ctx);
        return true;
    }
    const up = levelParent(state.context) orelse return false;
    levelPush(.{ .context = state.context });
    levelSet(up);
    return true;
}

/// Ctrl+>: one level in. Whether there was one.
fn levelDown() bool {
    if (panel_edit != null) return false;
    level_back = if (level_trail_n > 0) level_trail[level_trail_n - 1] else null;
    const taken = levelDownInner();
    // The trail's top used, or no longer fitting: off it (all of it when
    // it did not fit: the way back is lost).
    if (level_trail_n > 0) {
        if (level_back == null) level_trail_n -= 1 else level_trail_n = 0;
    }
    level_back = null;
    return taken;
}

fn levelDownInner() bool {
    if (canvas_eq) |q| {
        // Typing: the object at the caret chosen; chosen: its first part.
        if (q.head == null) return eqChooseAtCaret();
        return eqIn();
    }
    if (track_cursor) |c| {
        // In a track's content: the item after the cursor, a tile chosen
        // or a run's text edited; back where Ctrl+< left, if it left one.
        if (level_back) |b| if (b == .eq) if (b.eq.target == .run) if (b.eq.target.run.parent.eql(c.parent) and b.eq.target.run.region == c.region and eqContent(b.eq) != null) {
            canvas_eq = b.eq;
            canvas_eq_seq += 1;
            level_back = null;
            return true;
        };
        const items = state.model.flowItems(c.parent, c.region);
        if (c.index >= items.len) return false;
        switch (items[c.index].what) {
            .run => |r| {
                flow_anchor = null;
                canvas_eq = .{ .target = .{ .run = .{ .parent = c.parent, .region = c.region, .item = c.index } }, .math = r.equation, .offset = 0 };
                canvas_eq_seq += 1;
                eqMove(@min(c.offset, @as(u32, @intCast(r.content.len))), null);
                return true;
            },
            else => {
                const t = items[c.index].tileOf() orelse return false;
                track_cursor = null;
                levelSet(.{ .tile = t });
                return true;
            },
        }
    }
    // Back the way Ctrl+< came out.
    if (level_back) |b| switch (b) {
        .context => |ctx| if (levelParent(ctx)) |par| if (std.meta.eql(par, state.context)) {
            level_back = null;
            levelSet(ctx);
            return true;
        },
        .cursor => |c| switch (state.context) {
            .region, .row => {
                level_back = null;
                track_cursor = c;
                dvui.refresh(null, @src(), null);
                return true;
            },
            else => {},
        },
        .eq => |q| if (q.target == .tile_track and state.context == .tile and state.context.tile == q.target.tile_track.tile and eqContent(q) != null) {
            level_back = null;
            canvas_eq = q;
            canvas_eq_seq += 1;
            return true;
        },
    };
    switch (state.context) {
        // A tile: its slot's text edited.
        .tile => |id| {
            enterTileTrack(id);
            return canvas_eq != null;
        },
        // A track: its content, the flow cursor at its start.
        .region, .row => {
            const pr: struct { parent: Parent, region: usize } = switch (state.context) {
                .region => |r| .{ .parent = r.parent, .region = r.region },
                .row => |r| .{ .parent = r.parent, .region = r.region },
                else => unreachable,
            };
            const head = state.model.threadHead(pr.parent, pr.region);
            state.context = .{ .region = .{ .parent = pr.parent, .region = pr.region } };
            track_cursor = .{ .parent = head.parent, .region = head.region, .index = 0 };
            dvui.refresh(null, @src(), null);
            return true;
        },
        else => {},
    }
    const down = levelFirstChild(state.context) orelse return false;
    levelSet(down);
    return true;
}

/// A plain click at canvas point `at` (device point `p`): picks, and
/// selects the container picked, or (clicked again in the same place) the
/// one it sits in.
fn clickAt(at: geom.Point, p: dvui.Point.Physical) void {
    picked_constraint = null;
    const ns = dvui.windowNaturalScale();
    const again = if (last_click) |lc| @abs(lc.px.x - p.x) <= 4 * ns and @abs(lc.px.y - p.y) <= 4 * ns else false;
    pick(at);
    if (track_cursor != null or sketch_edit != null) {
        last_click = null;
        return;
    }
    // A tile is no container: clicked again, its track is the first one out.
    const tile_track: ?layout.model.ObjectId = switch (state.context) {
        // A grid's tile sits in no track: its panel, then.
        // The track it lies in (as Ctrl+< finds it), else its panel.
        .tile => if (levelParent(state.context)) |up| switch (up) {
            .region => |r| state.model.regionsIn(r.parent)[r.region].id,
            .grid => |g| state.model.parentId(g.parent),
            .panel => |pi| state.model.panels.items[pi].id,
            else => null,
        } else null,
        else => null,
    };
    const inner = objectOfContext(state.context) orelse tile_track orelse {
        last_click = .{ .px = p, .depth = 0 };
        return;
    };
    var depth: usize = if (again) last_click.?.depth + 1 else 0;
    if (tile_track != null and !again) {
        // The tile itself, first: nothing selected.
        last_click = .{ .px = p, .depth = 0 };
        return;
    }
    if (tile_track != null) depth -= 1;
    var cur = inner;
    var k: usize = 0;
    while (k < depth) : (k += 1) {
        cur = parentObject(cur) orelse {
            // Past the outermost: back in.
            depth = 0;
            cur = inner;
            break;
        };
    }
    if (cur != inner or tile_track != null) state.context = contextOfObject(cur);
    selection.clearRetainingCapacity();
    selection.append(state.gpa, cur) catch {};
    hunt_clear();
    last_click = .{ .px = p, .depth = if (tile_track != null) depth + 1 else depth };
    if (cur != inner or tile_track != null) {
        state.status = std.fmt.bufPrint(&status_hunt_buf, "Selected {s}, which holds it (click again: further out). ", .{objectName(cur)}) catch "";
    }
}

fn isPanelId(id: layout.model.ObjectId) bool {
    for (state.model.panels.items) |p| if (p.id == id) return true;
    return false;
}

/// The innermost container whose box holds canvas point `at`: the
/// smallest of them.
fn containerAt(at: geom.Point) ?layout.model.ObjectId {
    const a = dvui.currentWindow().arena();
    var best: ?layout.model.ObjectId = null;
    var best_area: f64 = std.math.inf(f64);
    for (constrainables(a)) |id| {
        if (isControlPoint(id)) continue;
        const b = containerBox(id) orelse continue;
        if (!contains(b, at)) continue;
        const ar = b.width() * b.height();
        if (ar < best_area) {
            best_area = ar;
            best = id;
        }
    }
    // Grouped, it is taken as its group.
    if (best) |id| {
        const top = state.model.topLevel(id);
        if (top != id) return top;
    }
    return best;
}

/// Shift-click (or Ctrl-click) at `at`: the container there in or out of
/// the selection.
fn shiftClick(at: geom.Point) void {
    const id = containerAt(at) orelse {
        state.status = "No container there. ";
        return;
    };
    hunt_clear();
    track_cursor = null;
    toggleSelected(id);
    state.context = if (selection.items.len == 0) workspaceContext() else if (selection.items.len == 1) contextOfObject(selection.items[0]) else .selection;
}

/// Whether a drag from `at` should take what is there along: an
/// unselected panel, line art, image or group (a track is selected by a
/// click first: a drag in its text is the text's).
fn dragTakes(at: geom.Point) ?layout.model.ObjectId {
    const id = containerAt(at) orelse return null;
    if (selectedAt(id) != null) return id;
    if (state.model.group(id) != null) return id;
    for (state.model.panels.items) |pnl| {
        if (pnl.id == id) return id;
        for (pnl.art.items) |x| if (x.id == id) return id;
    }
    if (shown_space < state.model.spaces.items.len) for (state.model.spaces.items[shown_space].images.items) |im| if (im.id == id) return id;
    if (shown_space < state.model.spaces.items.len) for (state.model.spaces.items[shown_space].figure_places.items) |fp| if (fp.id == id) return id;
    return null;
}

/// The selected panel, when the pointer went down on it: a drag then moves it.
fn grabbedPanel() ?usize {
    return panelToMove(state.press_at orelse return null);
}

/// Whether worksheet point `at` lies on panel `pi`.
fn panelHolds(pi: usize, at: geom.Point) bool {
    return contains(state.model.panels.items[pi].box(), at);
}

/// The panel a drag from worksheet point `at` would move: the selected
/// panel when `at` is on it; from the worksheet context, the one panel
/// under `at`, if exactly one is (where panels overlap, select one first).
/// The context does not change.
fn panelToMove(at: geom.Point) ?usize {
    switch (state.context) {
        // The canvas itself never moves.
        .panel => |pi| return if (contains(state.model.panels.items[pi].box(), at)) pi else null,
        .worksheet => {
            var found: ?usize = null;
            for (state.model.panels.items, 0..) |p, pi| {
                if (!contains(p.box(), at)) continue;
                if (found != null) return null;
                found = pi;
            }
            return found;
        },
        else => return null,
    }
}

fn contains(b: geom.Box, p: geom.Point) bool {
    return p.x >= b.x0 and p.x <= b.x1 and p.y >= b.y0 and p.y <= b.y1;
}

/// Commits a panel drag. A panel that started compliant ends compliant,
/// stopped where it would stop complying; one that was not may end anywhere.
fn finishMove(pi: usize) void {
    const target = panelOrigin(pi);
    state.moving = null;
    act(.movePanel, .{pi, target}) catch |err| dvui.log.err("moving a panel: {s}", .{@errorName(err)});
}

/// Makes what is under worksheet point `at` the context: a tile, else a
/// panel, else the worksheet.
fn pick(at: geom.Point) void {
    // A click in a text track makes it the context and puts the flow
    // cursor there at once; in the context's tracks, the cursor too;
    // anywhere else picks as usual.
    if (textTrackAt(at)) |t| state.context = .{ .region = .{ .parent = t.parent, .region = t.region } };
    if (cursorAt(at)) |c| {
        track_cursor = c;
        return;
    }
    track_cursor = null;
    // Empty space is the worksheet, or on a canvas the shown space itself.
    state.context = workspaceContext();
    selection.clearRetainingCapacity();
    // An image, then a view, by their boxes; anything over them wins.
    if (imageUnder(at)) |im| state.context = im;
    if (figurePlaceUnder(at)) |fc| {
        state.context = fc;
        // The container is the selection: its drag points show.
        if (objectOfContext(fc)) |id| selection.append(state.gpa, id) catch {};
    }
    if (viewUnder(at)) |v| state.context = v;
    // A sketch, by its box; a second click on it soon after enters it.
    if (sketchUnder(at)) |sr| {
        pickSketch(sr);
        if (sketch_edit != null) return;
    }
    for (0..state.model.parentCount()) |k| {
        const pi = state.model.parentAt(k);
        if (!shownIn(pi)) continue;
        if (pi.panelIndex()) |i| {
            if (state.model.spaces.items.len > 0 and !layerOpen(state.model.spaceOf(i), panelLayer(i))) continue;
            const b = state.model.panels.items[i].box();
            if (at.x >= b.x0 and at.x <= b.x1 and at.y >= b.y0 and at.y <= b.y1) state.context = .{ .panel = i };
        } else if (!layerOpen(shown_space, state.model.spaces.items[shown_space].base_layer)) continue;
        const pl = placedOf(pi) orelse continue;
        for (pl.tiles) |t| {
            const body = onSheet(pi, t.body);
            if (at.x >= body.x0 and at.x <= body.x1 and at.y >= body.y0 and at.y <= body.y1) state.context = .{ .tile = t.id };
        }
        // Line art, by its box: drawn over the tracks, it is picked over
        // what is under it.
        if (pi.panelIndex()) |i| for (pl.art) |pa| {
            if (contains(onSheet(pi, pa.box), at)) state.context = .{ .art = .{ .panel = i, .index = pa.index } };
        };
        for (pl.labels) |l| {
            if (l.tile != null) continue;
            // A run of text or an equation in a track: the track becomes
            // the context, with the cursor just after the run.
            if (l.run) |run| {
                if (contains(onSheet(pi, l.box), at)) {
                    state.context = .{ .region = .{ .parent = pi, .region = run.region } };
                    track_cursor = .{ .parent = pi, .region = run.region, .index = run.item + 1 };
                }
                continue;
            }
        }
    }
    // A grouped object is picked as its group: one move places them all.
    if (groupOf(state.context)) |g| state.context = .{ .group = g };
    revealInTree(state.context);
}

/// Adds the panel drawn out with the add panel tool. A drag under 1 mm on
/// either side is taken as a slip and ignored, leaving the tool ready.
fn addPanelFromDrag(b: geom.Box) void {
    if (b.width() < 1 or b.height() < 1) return;
    var buf: [32]u8 = undefined;
    const name = state.model.nextPanelName(&buf, state.model.spaces.items[shown_space].id, "Panel");
    const pi = act(.placePanel, .{.{
        .name = name,
        .default_name = true,
        .space = spaceId(shown_space),
        .origin = .{ .x = b.x0, .y = b.y0 },
        .w = b.width(),
        .h = b.height(),
    }}) catch |err| {
        state.status = if (err == error.OffSheet) "Too little of it is on the sheet: start further in. " else "The panel was not added. ";
        return;
    };
    // On the layer last chosen in its space.
    if (state.model.spaces.items.len > 0) hist.join(&state.model, .setPanelLayer, .{ pi, newObjectLayer() }) catch {};
    // Tools are not modes: a use ends the tool, and the context it was
    // chosen in stays, so the next panel is one press away.
    state.tool = .select;
    state.expanded.put(state.gpa, Context.key(.file), true) catch {};
    state.expanded.put(state.gpa, Context.key(.worksheet), true) catch {};
}

const Flags = struct { missing: bool = false, overflow: bool = false, size: bool = false };

fn tileFlag(placed: *const layout.place.Placed, id: TileId) Flags {
    var f: Flags = .{};
    for (placed.issues) |i| {
        if (i.tile != id) continue;
        switch (i.kind) {
            // A face lacking a character, or a weight or slant: both
            // the font's to fix.
            .missing_glyph, .variant_missing => f.missing = true,
            .label_overflow => f.overflow = true,
            // Reaching back into rows already filled: outlined as a size
            // problem is, in the warning colour.
            .tile_size, .tall_item => f.size = true,
            else => {},
        }
    }
    return f;
}

// The Layers palette ---------------------------------------------------------
//
// The active view's space's layers, top of the stack first: each shown or
// hidden by its eye, chosen by its name (new objects go on the layer
// chosen), and dragged by its grip to another place in the stack (the
// compositing order: what is higher is drawn over what is lower). A drag
// is one undo step.

fn layersPalette() void {
    const saved_group = pushGroup("layers-palette");
    defer popGroup(saved_group);
    if (shown_space >= state.model.spaces.items.len) return;
    const space = shown_space;
    const sp = state.model.spaces.items[space];
    var ebuf: [64]StackEntry = undefined;
    const entries = stackEntries(space, &ebuf);
    const m = entries.len;
    var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal, .padding = .all(6) });
    defer col.deinit();
    dvui.labelNoFmt(@src(), "Layers, top first", .{}, .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) }, .margin = .{ .x = 2, .h = 4 } });
    var removed: ?usize = null;
    var before: ?usize = null;
    {
        var reorder = dvui.reorder(@src(), .{}, .{ .expand = .horizontal });
        defer reorder.deinit();
        var list = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal });
        defer list.deinit();
        for (0..m) |k| {
            // Shown top first: row k is entry m-1-k.
            const e = entries[m - 1 - k];
            const id_extra: usize = switch (e) {
                .doc => |li| @intCast(@intFromEnum(sp.layers.items[li].id)),
                .view => |v| 0x7000_0000 + @as(usize, @intFromEnum(v)),
            };
            var item = reorder.reorderable(@src(), .{}, .{ .id_extra = id_extra, .expand = .horizontal });
            defer item.deinit();
            if (item.removed()) {
                removed = k;
            } else if (item.insertBefore()) {
                before = k;
            }
            const name, const visible, const chosen, const arg: i32 = switch (e) {
                .doc => |li| .{ sp.layers.items[li].name, sp.layers.items[li].visible, chosen_view_layer == null and sp.layers.items[li].id == newObjectLayer(), @intCast(li) },
                .view => |v| .{ v.label(), v.shown(), chosen_view_layer == v, -1 - @as(i32, @intFromEnum(v)) },
            };
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .background = true, .color_fill = .{ .color = if (chosen) dvui.themeGet().color(.highlight, .fill) else dvui.themeGet().color(.window, .fill) }, .corners = .all(3), .margin = .{ .y = 1, .h = 1 } });
            defer row.deinit();
            listItem("layers-palette", name);
            const base = next_element orelse "layers-palette";
            next_element = null;
            // The eye: shown or hidden.
            {
                const tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.shown", .{base}) catch base);
                checkElement(tag, .button, "Show or hide this layer");
                recordDrawn(tag, arg);
                const eye_opts: icons.ButtonOptions = .{ .size = 16, .id_extra = id_extra, .opts = .{ .tag = tag, .padding = .all(3), .gravity_y = 0.5 } };
                const pressed = if (visible) icons.button(@src(), .eye, "Shown: click to hide", eye_opts) else icons.button(@src(), .eye_slash, "Hidden: click to show", eye_opts);
                if (pressed) pushButtonEvent(tag, arg);
            }
            // Its name chooses it, its settings shown beside the list; the
            // view's own are set in italic.
            const dim: ?dvui.ColorOrGradient = if (visible) null else .{ .color = dvui.themeGet().color(.window, .text).opacity(0.5) };
            switch (e) {
                .doc => |li| {
                    const tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.choose", .{base}) catch base);
                    checkElement(tag, .button, name);
                    recordDrawn(tag, arg);
                    var bw: dvui.ButtonWidget = undefined;
                    bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = id_extra, .tag = tag, .padding = .{ .x = 4, .w = 4, .y = 3, .h = 4 }, .margin = .all(0), .background = false, .gravity_y = 0.5 });
                    bw.processEvents();
                    var buf: [96]u8 = undefined;
                    const text = std.fmt.bufPrint(&buf, "{s}{s}", .{ name, if (sp.layers.items[li].locked) " (locked)" else "" }) catch name;
                    dvui.labelNoFmt(@src(), text, .{}, .{ .padding = .all(0), .margin = .all(0), .color_text = dim });
                    if (bw.clicked()) pushButtonEvent(tag, arg);
                    bw.deinit();
                },
                .view => {
                    const tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.choose", .{base}) catch base);
                    checkElement(tag, .button, name);
                    recordDrawn(tag, arg);
                    var bw: dvui.ButtonWidget = undefined;
                    bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = id_extra, .tag = tag, .padding = .{ .x = 4, .w = 4, .y = 3, .h = 4 }, .margin = .all(0), .background = false, .gravity_y = 0.5 });
                    bw.processEvents();
                    dvui.labelNoFmt(@src(), name, .{}, .{ .padding = .all(0), .margin = .all(0), .font = dvui.Font.theme(.body).withStyle(.italic), .color_text = dim });
                    if (bw.clicked()) pushButtonEvent(tag, arg);
                    bw.deinit();
                },
            }
            // The grip: drag to another place.
            _ = dvui.ReorderWidget.draggable(@src(), .{ .reorderable = item }, .{ .expand = .vertical, .gravity_x = 1, .gravity_y = 0.5, .min_size_content = .{ .w = 14, .h = 18 }, .tag = std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.grip", .{base}) catch null });
        }
        if (reorder.finalSlot()) before = m;
    }
    if (removed) |r| if (before) |b| moveInStack(space, entries, r, b);
    keyButton(@src(), "Add layer", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 }, .tag = uniqueTag("layers-palette.add-layer") });
}

/// The entry shown at row `r` (top first) of `entries`, dropped before row
/// `b` (`entries.len`: at the bottom): the stack in its new order. A
/// document layer moves among the document's (one undo step); the view's
/// own layers keep their places among them, counted afresh.
fn moveInStack(space: usize, entries: []const StackEntry, r: usize, b: usize) void {
    const m = entries.len;
    const to_row = if (b > r) b - 1 else b;
    if (to_row == r) return;
    // The new order, bottom first.
    var order: [64]StackEntry = undefined;
    var k: usize = 0;
    const from = m - 1 - r;
    const to = m - 1 - to_row;
    for (entries, 0..) |e, i| if (i != from) {
        order[k] = e;
        k += 1;
    };
    std.mem.copyBackwards(StackEntry, order[to + 1 .. m], order[to .. m - 1]);
    order[to] = entries[from];
    // A document layer: its new index among the document's.
    switch (entries[from]) {
        .doc => |li| {
            var new_li: usize = 0;
            for (order[0..to]) |e| if (e == .doc) {
                new_li += 1;
            };
            moveLayerTo(space, li, new_li);
        },
        .view => {},
    }
    // Each view layer: how many document layers now lie below it.
    var docs: u16 = 0;
    const n = state.model.spaces.items[space].layers.items.len;
    for (order[0..m]) |e| switch (e) {
        .doc => docs += 1,
        .view => |v| {
            var st = overlayOf(space, v);
            const below: u16 = if (docs >= n) view_top else docs;
            if (st.below != below) {
                st.below = below;
                setOverlay(space, v, st);
            }
        },
    };
}

/// Document layer `li` of space `space` moved to index `to` (bottom
/// first), one undo step.
fn moveLayerTo(space: usize, li_from: usize, to: usize) void {
    if (li_from == to) return;
    var li = li_from;
    const key = mergeKey(.{ "layer-drag", space, hist.log.items.len });
    while (li != to) {
        li = actM(key, .moveLayer, .{ space, li, to > li }) catch return;
    }
    if (state.context == .layer and state.context.layer.space == space and state.context.layer.index == li_from) state.context = .{ .layer = .{ .space = space, .index = to } };
}

/// The context's properties (and the active tool's choices), in whatever
/// holds them.
fn propertiesBody() !void {
    if (canvas_prompt) return;
    var scroll = dvui.scrollArea(@src(), .{ .vertical_bar = .hide, .horizontal_bar = .hide }, .{ .expand = .both, .background = false });
    defer scroll.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal, .padding = .all(8) });
    defer body.deinit();
    setTagScope("{s}", .{"properties"});
    if (state.tool == .add_tracks) try tracksToolOptions();
    try properties();
}

/// Keeps the Add tracks tool's "size to" valid as prototypes and styles
/// come and go: one gone (or never chosen) becomes the document's first
/// prototype, else the default style. Called when the tool is picked and
/// when a drag is planned, so it holds with the Properties pane hidden
/// (the owner, 2026-11-22: rows could not be laid out on the canvas while
/// the pane, which alone did this, was auto-hidden).
fn validTracksSizeTo() void {
    const protos = state.model.prototypes.items;
    switch (tracks_tool.size_to) {
        .prototype => |pid| if (state.model.protoIndex(pid) == null) {
            // Text first (the owner, 2026-11-23): a text style chosen in
            // the Text style panel, else the default one. Tiles only when
            // a prototype is chosen in the tool's options.
            _ = protos;
            tracks_tool.size_to = if (text_style != null and state.model.styleIndex(text_style.?) != null)
                .{ .style = text_style }
            else .{ .style = null };
        },
        .style => |sid| if (sid != null and state.model.styleIndex(sid.?) == null) {
            tracks_tool.size_to = .{ .style = null };
        },
    }
}

/// The Add tracks tool's choices, above the context's properties while it
/// is active.
fn tracksToolOptions() !void {
    const saved_group = pushGroup("tool.add-tracks");
    defer popGroup(saved_group);
    headingAs("tool.add-tracks", "{s}", .{if (tracks_tool.kind == .track) "Layout: single track" else if (tracks_tool.major == .row) "Layout: column of rows" else "Layout: row of columns"}, 9000);
    const protos = state.model.prototypes.items;
    const styles = state.model.styles.items;
    validTracksSizeTo();
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 9001 });
        defer row.deinit();
        propName("Size to");
        // Tile prototypes, then text styles (the default one offered while
        // there is none).
        const lifo = dvui.currentWindow().lifo();
        const n_styles = @max(1, styles.len);
        const names = try lifo.alloc([]const u8, protos.len + n_styles);
        defer lifo.free(names);
        const arena = dvui.currentWindow().arena();
        for (protos, 0..) |p, i| names[i] = try std.fmt.allocPrint(arena, "Tile: {s}", .{p.name});
        if (styles.len == 0) names[protos.len] = "Text: Label";
        for (styles, 0..) |st, i| names[protos.len + i] = try std.fmt.allocPrint(arena, "Text: {s}", .{st.name});
        var choice: usize = switch (tracks_tool.size_to) {
            .prototype => |pid| protoPos(pid),
            .style => |sid| protos.len + (if (sid) |x| state.model.styleIndex(x) orelse 0 else 0),
        };
        if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal })) {
            tracks_tool.size_to = if (choice < protos.len)
                .{ .prototype = protos[choice].id }
            else if (styles.len == 0) .{ .style = null } else .{ .style = styles[choice - protos.len].id };
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 9002 });
        defer row.deinit();
        propName(if (tracks_tool.kind == .track) "Runs" else "Tracks");
        if (tracks_tool.kind == .track) {
            dvui.labelNoFmt(@src(), "the way it is drawn: right or down", .{}, .{ .expand = .horizontal });
        } else {
            const names = [_][]const u8{ "Rows (column of rows)", "Columns (row of columns)" };
            var choice: usize = @backingInt(tracks_tool.major);
            if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal })) tracks_tool.major = @fromBackingInt(@intCast(choice));
        }
    }
    var buf: [96]u8 = undefined;
    switch (tracks_tool.size_to) {
        .prototype => |pid| if (state.model.protoIndex(pid)) |pidx| {
            const p = protos[pidx];
            const along = p.smallest(tracks_tool.major, .along);
            const step_ = p.step(tracks_tool.major, .along);
            const across = p.smallest(tracks_tool.major, .across);
            propText("Snaps to", "{s}", .{std.fmt.bufPrint(&buf, "{d} u thick; {d} u long or more, in {d} u steps", .{ across, along, step_ }) catch ""}, 9003);
        },
        .style => |sid| if (styleLinePitch(sid)) |lp| {
            propText("Snaps to", "{s}", .{std.fmt.bufPrint(&buf, "one line ({d:.2} mm) thick; {d} mm steps along", .{ lp, text_track_step }) catch ""}, 9003);
        },
    }
    _ = dvui.separator(@src(), .{ .expand = .horizontal, .margin = .{ .y = 6, .h = 6 } });
}

/// Text tracks snap along to this, mm.
const text_track_step = 0.5;

/// A text style's baseline-to-baseline distance, mm, in the current font;
/// for no style, what the default Label style's would be (3 mm caps).
fn styleLinePitch(style: ?layout.model.StyleId) ?f64 {
    const labels = if (state.labels) |*l| l else return null;
    if (style) |sid| {
        const st = labels.context(sid) orelse return null;
        return st.line_pitch;
    }
    if (state.faces.len == 0) return null;
    const f = state.faces[0];
    const ext = f.extents();
    return (ext.ascender - ext.descender) * 3 / layout.legend.capUnits(f);
}

/// Sets a track's or region's orientation, saying why when it cannot be.
fn setOrientationOf(pi: Parent, ri: usize, direction: f64, rotation: f64) void {
    actM(mergeKey(.{ "track orientation", pi, ri }), .setOrientation, .{ pi, ri, direction, rotation }) catch |err| {
        state.status = if (err == error.BadJoin) "A flow's tracks all run one way: take this one out of its flow to turn it. " else "The orientation was not set. ";
    };
}

/// Removes a track or region; its flow goes on in its other tracks (the
/// last one's text kept, unplaced). Its panel becomes the context.
fn removeRegionOf(pi: Parent, ri: usize) void {
    actV(.removeRegion, .{ pi, ri });
    track_cursor = null;
    path_selected = null;
    state.context = parentContext(pi);
}

/// "Row" or "Column".
fn trackWord(major: layout.model.Major) []const u8 {
    return if (major == .row) "Row" else "Column";
}

/// A prototype to draw tracks of: the first, made as a plain keycap when
/// there is none.
fn ensurePrototype() !void {
    if (state.model.prototypes.items.len > 0) return;
    var p: layout.model.TilePrototype = .{
        .name = "Key",
        .unit = 19.05,
        .body_inset = .all(0.5),
        .face_inset = .all(2),
        // In the document's first style; the default Label style only when
        // it has none (made for it, it would stay behind unused once the
        // slot is given the style meant).
        .tracks = &.{.{ .name = "top", .style = if (state.model.styles.items.len > 0) state.model.styles.items[0].id else try labelStyle(), .place = .{ .inset = .all(0.8) } }},
    };
    p.art = try layout.art.redrawKeycap(dvui.currentWindow().arena(), p, 19.05);
    _ = try act(.addPrototype, .{p});
}

/// Tracks a drag from `start` to `at` (worksheet, mm) would make on the
/// context panel: the region snapped to whole tracks across, as thick as
/// the prototype's smallest tile, and along to its size step, no shorter
/// than its smallest tile; set out from `start` the way the drag went.
const TrackPlan = struct {
    parent: Parent,
    count: usize,
    length: f64,
    pitch: f64,
    major: layout.model.Major,
    /// On the worksheet, mm.
    box: geom.Box,
};

fn planTracks(from: geom.Point, at: geom.Point) ?TrackPlan {
    validTracksSizeTo();
    const pi: Parent = switch (state.context) {
        .panel => |pi| .{ .panel = pi },
        .space => |si| .{ .space = si },
        else => return null,
    };
    // A track runs the way it is drawn; a region the way the tool says.
    const major: layout.model.Major = if (tracks_tool.kind == .track)
        (if (@abs(at.x - from.x) >= @abs(at.y - from.y)) .row else .column)
    else
        tracks_tool.major;
    // The unit (mm per u), and in it: the thickness of one track, the
    // shortest length and the step along.
    var pitch: f64 = undefined;
    var along_min: f64 = undefined;
    var step_: f64 = undefined;
    var across: f64 = 1;
    switch (tracks_tool.size_to) {
        .prototype => |pid| {
            if (state.model.protoIndex(pid) == null) return null;
            const p = state.model.proto(pid).*;
            // Its own unit: a 1 u key is 19.05 mm in any track.
            pitch = p.unit orelse if (p.art) |art| art.pitch else 19.05;
            along_min = p.smallest(major, .along);
            step_ = p.step(major, .along);
            across = p.smallest(major, .across);
        },
        .style => |sid| {
            // One line thick: the unit is the style's line pitch.
            pitch = styleLinePitch(sid) orelse return null;
            step_ = text_track_step / pitch;
            along_min = step_;
        },
    }
    const dx = at.x - from.x;
    const dy = at.y - from.y;
    const d_along = @abs(if (major == .row) dx else dy) / pitch;
    const d_across = @abs(if (major == .row) dy else dx) / pitch;
    const length = @max(along_min, @round(d_along / step_) * step_);
    const tracks: usize = if (tracks_tool.kind == .track) 1 else @max(1, @as(usize, @intFromFloat(@round(d_across / across))));
    const thickness = @as(f64, @floatFromInt(tracks)) * across;
    const w = (if (major == .row) length else thickness) * pitch;
    const h = (if (major == .row) thickness else length) * pitch;
    const x0 = if (dx >= 0) from.x else from.x - w;
    const y0 = if (dy >= 0) from.y else from.y - h;
    return .{ .parent = pi, .count = tracks, .length = length, .pitch = pitch, .major = major, .box = .{ .x0 = x0, .y0 = y0, .x1 = x0 + w, .y1 = y0 + h } };
}

fn drawTrackPlan(area: dvui.Rect.Physical, plan: TrackPlan) void {
    const px = dvui.windowNaturalScale();
    const fits = if (plan.parent.panelIndex()) |i| layout.model.within(plan.box, state.model.panels.items[i].box()) else true;
    const colour = if (fits) colors.select else colors.overflow;
    const r = state.view.rect(area, plan.box);
    r.fill(.square, .{ .color = .{ .color = colour.opacity(0.12) } });
    r.stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colour } });
    // The lines between tracks.
    const n = plan.count;
    for (1..n) |i| {
        const f = @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(n));
        const b = plan.box;
        const a_pt: geom.Point = if (plan.major == .row) .{ .x = b.x0, .y = b.y1 - f * b.height() } else .{ .x = b.x0 + f * b.width(), .y = b.y1 };
        const b_pt: geom.Point = if (plan.major == .row) .{ .x = b.x1, .y = a_pt.y } else .{ .x = a_pt.x, .y = b.y0 };
        dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, a_pt), state.view.toPx(area, b_pt) } }, .{ .thickness = px, .color = .{ .color = colour.opacity(0.6) } });
    }
    var buf: [64]u8 = undefined;
    const word = if (tracks_tool.kind == .track) (if (plan.major == .row) "track, right" else "track, down") else if (plan.major == .row) "row" else "column";
    const plural = if (n == 1) "" else "s";
    // Text tracks in mm: a unit of one line pitch means little to anyone.
    const text = if (tracks_tool.size_to == .style)
        std.fmt.bufPrint(&buf, "{d} {s}{s} × {d:.1} mm", .{ n, word, plural, plan.length * plan.pitch }) catch ""
    else
        std.fmt.bufPrint(&buf, "{d} {s}{s} × {d} u", .{ n, word, plural, plan.length }) catch "";
    const corner = state.view.toPx(area, .{ .x = plan.box.x0, .y = plan.box.y1 });
    const font = dvui.themeGet().font_body;
    dvui.labelNoFmt(@src(), text, .{}, .{
        // In the canvas's own coordinates, just above the region.
        .rect = annotationRect(area, corner, font, 220),
        .padding = .{ .x = 4, .w = 4, .y = annotation_pad, .h = annotation_pad },
        .font = font,
        .color_text = .{ .color = colour },
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill).opacity(0.85) },
    });
}

/// Makes the empty tracks a finished drag planned, makes their region the
/// context and puts the flow cursor at the start of the first, ready for
/// tiles. One use ends the tool.
/// The array being dragged out: its outline and its cells' borders.
fn drawArrayPlan(area: dvui.Rect.Physical, b: geom.Box) void {
    const px = dvui.windowNaturalScale();
    const r = state.view.rect(area, b);
    r.fill(.square, .{ .color = .{ .color = colors.select.opacity(0.08) } });
    r.stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } });
    const cols: f64 = @floatFromInt(array_tool.cols);
    const rows: f64 = @floatFromInt(array_tool.rows);
    for (1..array_tool.cols) |c| {
        const x = b.x0 + (b.x1 - b.x0) * @as(f64, @floatFromInt(c)) / cols;
        strokeLine(area, .{ .x = x, .y = b.y0 }, .{ .x = x, .y = b.y1 }, colors.select.opacity(0.7), px);
    }
    for (1..array_tool.rows) |k| {
        const y = b.y0 + (b.y1 - b.y0) * @as(f64, @floatFromInt(k)) / rows;
        strokeLine(area, .{ .x = b.x0, .y = y }, .{ .x = b.x1, .y = y }, colors.select.opacity(0.7), px);
    }
}

/// A polar array being dragged out from its centre `c` to its outer edge
/// at `at`: its rings and the borders between its cells.
fn drawPolarPlan(area: dvui.Rect.Physical, c: geom.Point, at: geom.Point) void {
    const px = dvui.windowNaturalScale();
    const R = @sqrt((at.x - c.x) * (at.x - c.x) + (at.y - c.y) * (at.y - c.y));
    if (R <= 0) return;
    const n = array_tool.around;
    const sweep = @min(360, @max(1, array_tool.sweep));
    const full = sweep >= 360;
    const step = sweep / @as(f64, @floatFromInt(n));
    const first = 90 + if (full) step / 2 else sweep / 2;
    const rings: f64 = @floatFromInt(array_tool.rings);
    // Rings (arcs over the sweep): the outer edge, and the borders
    // between rings.
    for (1..array_tool.rings + 1) |k| {
        const r = R * @as(f64, @floatFromInt(k)) / rings;
        const outer = k == array_tool.rings;
        var prev: ?geom.Point = null;
        for (0..97) |j| {
            const a = std.math.degreesToRadians(first - sweep * @as(f64, @floatFromInt(j)) / 96);
            const q: geom.Point = .{ .x = c.x + r * @cos(a), .y = c.y + r * @sin(a) };
            if (prev) |p0| strokeLine(area, p0, q, if (outer) colors.select else colors.select.opacity(0.7), if (outer) 1.5 * px else px);
            prev = q;
        }
    }
    // Radial borders.
    const lines = if (full) n else n + 1;
    for (0..lines) |i| {
        const a = std.math.degreesToRadians(first - @as(f64, @floatFromInt(i)) * step);
        strokeLine(area, c, .{ .x = c.x + R * @cos(a), .y = c.y + R * @sin(a) }, colors.select.opacity(0.7), px);
    }
}

/// Add array, polar: its sketch (a centre point, radial borders a fixed
/// angle apart, equally spaced rings) centred at `c`, out to `at`'s
/// distance, and a grid whose points are its cells' middles (column 0
/// straight up, then clockwise).
fn addPolarFromDrag(c: geom.Point, at: geom.Point) void {
    defer state.tool = .select;
    const parent = arrayParent() orelse return;
    const R = @sqrt((at.x - c.x) * (at.x - c.x) + (at.y - c.y) * (at.y - c.y));
    if (!(R > 0.5)) {
        state.status = "The array was too small: drag from its centre out to its edge. ";
        return;
    }
    // Its first border: column 0 straight up, the sweep either side.
    const sweep = @min(360, @max(1, array_tool.sweep));
    const first = 90 + if (sweep >= 360) 180.0 / @as(f64, @floatFromInt(array_tool.around)) else sweep / 2;
    addArrayGrid(parent, c, true, array_tool.around, array_tool.rings, .{ .x = R, .y = first }, sweep);
}

/// Where a new array goes: the workspace shown, or the panel chosen.
fn arrayParent() ?Parent {
    return switch (state.context) {
        .panel => |pi| .{ .panel = pi },
        .space => |si| .{ .space = si },
        else => null,
    };
}

/// An array made (its sketch and its grid), and chosen.
fn addArrayGrid(parent: Parent, at: geom.Point, polar: bool, cols: u32, rows: u32, size: geom.Point, sweep: f64) void {
    const gi = act(.addArray, .{ parent, at, polar, cols, rows, size, sweep }) catch {
        state.status = "The array was not added. ";
        return;
    };
    state.context = .{ .grid = .{ .parent = parent, .index = gi } };
    state.expanded.put(state.gpa, Context.key(parentContext(parent)), true) catch {};
}

/// Add array: a rectangular array over box `b` (sheet mm): its sketch's
/// borders, equally spaced, and a grid whose points are its cells'
/// middles. On the workspace (canvas or frame) or the panel chosen.
fn addArrayFromDrag(b: geom.Box) void {
    defer state.tool = .select;
    const parent = arrayParent() orelse return;
    const w = b.x1 - b.x0;
    const h = b.y1 - b.y0;
    if (!(w > 0.5 and h > 0.5)) {
        state.status = "The array was too small: drag out its area. ";
        return;
    }
    addArrayGrid(parent, .{ .x = b.x0, .y = b.y1 }, false, array_tool.cols, array_tool.rows, .{ .x = w, .y = h }, 0);
}

fn addTracksFromDrag(from: geom.Point, at: geom.Point) void {
    defer state.tool = .select;
    const plan = planTracks(from, at) orelse return;
    const o = parentOrigin(plan.parent);
    // Tracks may run past the panel: flagged, to be fitted or the panel
    // resized once their tiles show what is needed.
    var name_buf: [32]u8 = undefined;
    // Generated names are identifiers, numbered within the panel (or the
    // workspace).
    const name = state.model.freshName(&name_buf, state.model.containerOf(plan.parent), if (tracks_tool.kind == .track) "Track" else if (plan.major == .row) "Column" else "Row");
    const r = act(.addTracks, .{plan.parent, .{
        .name = name,
        .origin = .{ .x = plan.box.x0 - o.x, .y = plan.box.y1 - o.y },
        .major = plan.major,
        .kind = tracks_tool.kind,
        .prototype = switch (tracks_tool.size_to) {
            .prototype => |pid| pid,
            .style => null,
        },
        .style = switch (tracks_tool.size_to) {
            .prototype => null,
            .style => |sid| sid orelse (labelStyle() catch return),
        },
        .count = plan.count,
        .length = plan.length,
        .pitch = plan.pitch,
    }}) catch {
        state.status = "The tracks were not added. ";
        return;
    };
    // A text layout's new flow: its style copied from the Default
    // template, in the same undo step.
    if (tracks_tool.size_to == .style) styleNewFlow(plan.parent, r) catch {};
    // Empty tracks, the user fills them: the cursor waits at the start.
    state.context = .{ .region = .{ .parent = plan.parent, .region = r } };
    track_cursor = .{ .parent = plan.parent, .region = r, .index = 0 };
    state.expanded.put(state.gpa, Context.key(parentContext(plan.parent)), true) catch {};
}

/// Tools for the current context, as icon buttons; with Add shape on,
/// which shape it draws.
fn toolPalette() void {
    const saved_group = pushGroup("tool");
    defer popGroup(saved_group);
    if (sketch_edit != null) return sketchPalette();
    var col = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_y = 0.5 });
    defer col.deinit();
    toolBar();
    if (state.tool != .add_art) return;
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .min_size_content = .{ .w = 260 }, .padding = .{ .x = 8, .w = 8 }, .gravity_y = 0.5 });
    defer row.deinit();
    propName("Shape");
    const names = [_][]const u8{ "Rectangle", "Rounded rectangle", "Circle", "Ellipse", "Slot", "Polygon" };
    var choice: usize = @intFromEnum(shape_kind);
    if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal })) {
        shape_kind = @enumFromInt(choice);
        polygon_pts.clearRetainingCapacity();
        state.drag = null;
    }
}

fn toolBar() void {
    const saved_group = pushGroup("tool");
    defer popGroup(saved_group);
    // In the ribbon, the keys fill its height: no padding above or below.
    const pad_y: f32 = if (in_ribbon) 0 else 3;
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .padding = .{ .x = 2, .w = 2, .y = pad_y, .h = pad_y }, .gravity_y = 0.5 });
    defer bar.deinit();
    var wd: dvui.WidgetData = undefined;
    keyIcon(@src(), "Zoom to context", icons.graven(.zoom_to_context) orelse dvui.entypo.resize_full_screen, 0, .{ .data_out = &wd });
    dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "Zoom to fit the {s}", .{lowerKind()}, .{});
    {
        const on = state.tool == .constrain;
        var cwd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Constrain", icons.graven(.constrain) orelse dvui.entypo.ruler, 0, .{
            .data_out = &cwd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = cwd.borderRectScale().r }, "Constrain: pick a feature of what is to move, then what it keeps to; set the distance or size", .{}, .{});
    }

    switch (state.context) {
        .prototypes => {
            var pwd: dvui.WidgetData = undefined;
            keyIcon(@src(), "Add prototype", dvui.entypo.squared_plus, 0, .{ .data_out = &pwd });
            dvui.tooltip(@src(), .{ .active_rect = pwd.borderRectScale().r }, "Add a tile prototype", .{}, .{});
        },
        .prototype => {
            var dwd: dvui.WidgetData = undefined;
            keyIcon(@src(), "Duplicate prototype", dvui.entypo.copy, 0, .{ .data_out = &dwd });
            dvui.tooltip(@src(), .{ .active_rect = dwd.borderRectScale().r }, "Duplicate: a copy to make a variant of", .{}, .{});
            var rwd: dvui.WidgetData = undefined;
            keyIcon(@src(), "Delete prototype", dvui.entypo.trash, 0, .{ .data_out = &rwd });
            dvui.tooltip(@src(), .{ .active_rect = rwd.borderRectScale().r }, "Delete: only while no tile is made from it", .{}, .{});
        },
        else => {},
    }

    const on_canvas = state.context == .space;
    // In the ribbon every tool shows, faint where it does not apply to
    // the context yet; elsewhere only those that apply.
    // On a canvas or in a frame: start a sketch where the next click lands.
    // Nothing is drawn directly on a canvas or in a frame, only inside a
    // container (the owner, 2026-11-22). A sketch is one: what is drawn in
    // it stays in it. New sketch: one where the next click lands.
    if (showTool(on_canvas)) {
        const prev_a = faintUnless(on_canvas);
        defer dvui.alphaSet(prev_a);
        const on = state.tool == .new_sketch;
        var swd: dvui.WidgetData = undefined;
        keyIcon(@src(), "New sketch", icons.graven(.new_sketch) orelse dvui.entypo.pencil, 0, .{
            .data_out = &swd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = swd.borderRectScale().r }, "New sketch: click where its origin goes, then draw and constrain it", .{}, .{});
    }

    // Line art only inside a panel: on the canvas's own panel (or a
    // frame's) it would be drawn directly on the canvas.
    if (inDrawingContainer()) {
        const art_on = state.tool == .add_art;
        var awd: dvui.WidgetData = undefined;
        ribbon_next_drop = .shape;
        keyIcon(@src(), "Add shape", icons.graven(.add_shape) orelse dvui.entypo.circle, 0, .{
            .data_out = &awd,
            .color_fill = if (art_on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = awd.borderRectScale().r }, "Add shape: drag out line art on the panel; tracks under it flow around its ink", .{}, .{});
    }
    // Containers: tracks, on a panel or on the canvas (or a frame).
    if (showTool(state.context == .panel or state.context == .space)) {
        const prev_a = faintUnless(state.context == .panel or state.context == .space);
        defer dvui.alphaSet(prev_a);
        // Two track modes, one button each: rows (tiles flow left to right)
        // and columns (top to bottom).
        // And a third: one track, laid out where it is drawn, running the
        // way the drag goes.
        inline for (.{
            .{ layout.model.Major.row, "Layout: column of rows", dvui.entypo.menu, "Layout: column of rows, a content layout drawn out on the panel; content flows through its rows in order, a row added as it needs one", layout.model.TileRegion.Kind.region },
            .{ layout.model.Major.column, "Layout: row of columns", dvui.entypo.bar_graph, "Layout: row of columns, a content layout drawn out on the panel; content flows through its columns in order, a column added as it needs one", layout.model.TileRegion.Kind.region },
            .{ layout.model.Major.row, "Layout: single track", dvui.entypo.flow_line, "Layout: single track, one line where it is drawn, running right or down as dragged; its own flow, or continuing another's", layout.model.TileRegion.Kind.track },
        }, 0..) |mode, mi| {
            const mode_on = state.tool == .add_tracks and tracks_tool.kind == mode[4] and (mode[4] == .track or tracks_tool.major == mode[0]);
            var twd: dvui.WidgetData = undefined;
            if (mi == 0) ribbon_next_drop = .tracks;
            const own: ?[]const u8 = switch (mi) {
                0 => icons.graven(.add_rows),
                1 => icons.graven(.add_columns),
                else => icons.graven(.add_track),
            };
            keyIcon(@src(), mode[1], own orelse mode[2], 0, .{
                .id_extra = mi,
                .data_out = &twd,
                .color_fill = if (mode_on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
            });
            dvui.tooltip(@src(), .{ .active_rect = twd.borderRectScale().r }, mode[3], .{}, .{ .id_extra = mi });
        }
    }
    // Array: a grid of cells, its counts chosen in its drop, then dragged
    // out on the canvas, a frame or a panel.
    if (showTool(state.context == .panel or state.context == .space)) {
        const prev_a = faintUnless(state.context == .panel or state.context == .space);
        defer dvui.alphaSet(prev_a);
        const on = state.tool == .add_array;
        var awd: dvui.WidgetData = undefined;
        ribbon_next_drop = .array;
        keyIcon(@src(), "Add array", dvui.entypo.grid, 0, .{
            .data_out = &awd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = awd.borderRectScale().r }, "Add array: choose its columns and rows, Apply, then drag out its cells", .{}, .{});
    }
    if (showTool(state.context == .region)) {
        const prev_a = faintUnless(state.context == .region);
        defer dvui.alphaSet(prev_a);
        // Fit to tiles: the tracks shrink to what has been put in them.
        var fwd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Fit to tiles", icons.graven(.fit_to_tiles) orelse dvui.entypo.crop, 0, .{ .data_out = &fwd });
        dvui.tooltip(@src(), .{ .active_rect = fwd.borderRectScale().r }, "Fit to tiles: make the rows or columns as long as the longest paragraph", .{}, .{});
    }
    {
        // Select boundaries: a mode, kept until toggled.
        const on = boundary_mode;
        var bwd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Select boundaries", icons.graven(.select_boundaries) orelse dvui.entypo.resize_full_screen, 0, .{
            .data_out = &bwd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = bwd.borderRectScale().r }, "Select boundaries (B): while on, the boundary nearest the pointer is highlighted and a click selects its container, its drag points haloed", .{}, .{});
    }
    if (state.model.spaces.items.len > 0) {
        // Construction line: a mode tool on a canvas or in a frame.
        const on = state.tool == .construction;
        var gwd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Construction line", icons.graven(.construction_line) orelse dvui.entypo.flow_line, 0, .{
            .data_out = &gwd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = gwd.borderRectScale().r }, "Construction line: an infinite guide line, from two points (a drag, or two clicks)", .{}, .{});
    }
    if (showTool(on_canvas or state.context == .selection or state.context == .group)) {
        const prev_a = faintUnless(on_canvas or state.context == .selection or state.context == .group);
        defer dvui.alphaSet(prev_a);
        const sel_on = state.tool == .select_area;
        var swd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Select area", icons.graven(.select_area) orelse dvui.entypo.select_arrows, 0, .{
            .data_out = &swd,
            .color_fill = if (sel_on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = swd.borderRectScale().r }, "Select area: drag around objects to pick them together, to move or copy into a frame", .{}, .{});
    }
    if (showTool(state.context == .worksheet or on_canvas)) {
        const prev_a = faintUnless(state.context == .worksheet or on_canvas);
        defer dvui.alphaSet(prev_a);
        // A mode tool: shown pressed while active; pressing again cancels.
        const on = state.tool == .add_panel;
        var awd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Add panel", icons.graven(.add_panel) orelse dvui.entypo.squared_plus, 0, .{
            .data_out = &awd,
            .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
        });
        dvui.tooltip(@src(), .{ .active_rect = awd.borderRectScale().r }, "Add panel: drag out its outline on the sheet", .{}, .{});
    }
    // Insert figure: the figure chosen in the Browser, dragged out on the
    // canvas or frame shown.
    {
        const applies = state.context == .figure_def or state.tool == .insert_figure;
        if (showTool(applies)) {
            const prev_a = faintUnless(applies);
            defer dvui.alphaSet(prev_a);
            const on = state.tool == .insert_figure;
            var fwd: dvui.WidgetData = undefined;
            keyIcon(@src(), "Insert figure", dvui.entypo.flower, 0, .{
                .data_out = &fwd,
                .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null,
            });
            dvui.tooltip(@src(), .{ .active_rect = fwd.borderRectScale().r }, "Insert figure: drag out where the figure chosen in the Browser goes, or click for its own size", .{}, .{});
        }
    }
}

/// Whether the context is a panel that takes line art: not the canvas's
/// own nor a frame's (nothing is drawn directly on a canvas or in a
/// frame; only inside a container: a panel, a sketch).
fn inDrawingContainer() bool {
    return switch (state.context) {
        .panel => |pi| pi < state.model.panels.items.len,
        else => false,
    };
}

/// Whether a tool that `applies` (or not) is shown: always in the ribbon.
fn showTool(applies: bool) bool {
    return applies or in_ribbon;
}

/// Faint while drawn, unless it applies; the alpha before, to restore.
fn faintUnless(applies: bool) f32 {
    return dvui.alpha(if (applies) 1 else 0.4);
}

fn lowerKind() []const u8 {
    return switch (state.context) {
        .file => "file",
        .worksheet => "worksheet",
        .space => |si| if (si == 0) "canvas" else "frame",
        .panel => "panel",
        .region => "region",
        .row => "row",
        .tile => "tile",
        .art => "line art",
        .group => "group",
        .selection => "selection",
        .view => "view",
        .layer => "layer",
        .image => "image",
        .guide => "construction line",
        .sketch => "sketch view",
        .sketches => "sketches",
        .sketch_def => "sketch",
        .grid => "grid",
        .prototypes => "tile prototypes",
        .prototype => "tiles of the prototype",
        .flows => "flows",
        .flow => "the flow's tracks",
        .sheets => "legend sheets",
        .sheet => "the sheet's keys",
        .styles => "text styles",
        .style => "text style",
        .templates => "style templates",
        .template => "style template",
        .processes => "process profiles",
        .process => "process profile",
        .plans => "manufacturing plans",
        .plan => "manufacturing plan",
        .materials => "materials",
        .constraints => "constraints",
        .constraint => "constraint",
        .material => "material",
        .figures => "figures",
        .figure_def => "figure",
        .figure_place => "placed figure",
    };
}

/// Property rows lay out as name and value. `n` numbers rows within a pane
/// so each has its own widget id.
const label_width = 104;

// Element ids ------------------------------------------------------------------
//
// UI elements have ids (decided 2026-11-20), so tests and scripts act on them
// by name, not by place or wording: "<section>.<key>". A section is a
// properties heading's id, given where its text varies (the context's kind,
// "region", whether it reads Region or Track; a slot "slot.top"; an
// operation "operation.2"), else its text as a lower-camel identifier
// (Fabrication: "fabrication"). A key is given where a label varies
// ("makeTracks"), else the label as one ("Origin across, mm":
// "originAcrossMm"). Menu items are "menu.<label>", tools "tool.<name>",
// Browser nodes "tree/<its path>", content palette buttons "palette/<kind>".
// A repeat in one frame is numbered "#2". Scripts set a field, press a
// button or choose an entry by id (`testing_api`), through the same paths a
// person's input takes. Tags cost a map entry each a frame.

var tag_scope_buf: [96]u8 = undefined;
var tag_scope: []const u8 = "";

fn setTagScope(comptime fmt: []const u8, args: anytype) void {
    tag_scope = std.fmt.bufPrint(&tag_scope_buf, fmt, args) catch "";
}

/// `text` as a lower-camel identifier, in the frame's arena ("Origin
/// across, mm": originAcrossMm).
fn lowerCamel(text: []const u8) []const u8 {
    var buf: [128]u8 = undefined;
    const id = layout.names.identifier(&buf, text, "x");
    const out = dvui.currentWindow().arena().dupe(u8, id) catch return "x";
    // A leading capital, or a leading acronym, lowered (FDM: fdm;
    // PCKeyboard: pcKeyboard).
    var k: usize = 0;
    while (k < out.len and std.ascii.isUpper(out[k])) : (k += 1) {}
    const upto = if (k > 1 and k < out.len and std.ascii.isLower(out[k])) k - 1 else @max(k, 1);
    for (out[0..@min(upto, out.len)]) |*c| c.* = std.ascii.toLower(c.*);
    return out;
}

/// A section whose id is its heading's text as an identifier.
fn setTagScopeText(text: []const u8) void {
    const id = lowerCamel(text);
    tag_scope = std.fmt.bufPrint(&tag_scope_buf, "{s}", .{id}) catch "";
}

/// The id of key `key` in the current section, for an element whose label
/// varies: pass it as the element's `.tag`.
fn elementTag(key: []const u8) []const u8 {
    return uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.{s}", .{ tag_scope, key }) catch key);
}

/// A button, menu item or checkbox a script presses (by id), next drawn.
var scripted_press: ?[]const u8 = null;
var scripted_press_buf: [128]u8 = undefined;

// Buttons as virtual keys (decided 2026-11-20): an action button's press is
// an event, named by its id, which is its action's name (elements.zig);
// the actions run at the next
// frame's start, on the context the press was made in, through one
// dispatch (`runButtonAction`), as a key's or a menu item's would.

const ButtonEvent = struct {
    id: [128]u8 = undefined,
    id_len: usize = 0,
    arg: i32 = 0,
    context: Context,
};
var button_events: [16]ButtonEvent = undefined;
var button_events_n: usize = 0;

/// The action buttons drawn last frame and this one, by id, with their
/// arguments: a script presses only what is shown.
const DrawnButton = struct { id: []const u8, arg: i32 };
var drawn_buttons: std.ArrayList(DrawnButton) = .empty;
var drawn_buttons_prev: std.ArrayList(DrawnButton) = .empty;
var drawn_frame: i128 = -1;

fn pushButtonEvent(id: []const u8, arg: i32) void {
    if (button_events_n == button_events.len) return;
    var e: ButtonEvent = .{ .arg = arg, .context = state.context };
    e.id_len = @min(id.len, e.id.len);
    @memcpy(e.id[0..e.id_len], id[0..e.id_len]);
    button_events[button_events_n] = e;
    button_events_n += 1;
    dvui.refresh(null, @src(), null);
}

/// A button that is a virtual key: drawn, a click is an event for its
/// action, run next frame. `id` is the element's (elements.zig), its
/// action's name; `label` says more than the registry's when given ("Make
/// tracks of its 6 rows"); `arg` is the action's argument (which of
/// several things it stands for).
fn actionButton(src: std.builtin.SourceLocation, comptime id: []const u8, label: ?[]const u8, arg: i32, opts: dvui.Options) void {
    const e = comptime elements.get(id);
    comptime if (e.kind != .button) @compileError(id ++ " is not a button");
    var o = opts;
    const tag = uniqueTag(id);
    o.tag = tag;
    var bw: dvui.WidgetData = undefined;
    o.data_out = &bw;
    if (dvui.button(src, label orelse e.label, .{}, o)) pushButtonEvent(tag, arg);
    // Its key, from the keymap, as a menu item shows its own.
    if (buttonActionId(tag)) |a| {
        var kb: [48]u8 = undefined;
        if (keymap.shortcut(&kb, kmode("canvas"), a, arg)) |sc| dvui.tooltip(src, .{ .active_rect = bw.borderRectScale().r }, "{s}", .{sc}, .{ .id_extra = o.id_extra orelse 0 });
    }
    recordDrawn(tag, arg);
}

/// An action button drawn this frame, with its argument: a script may
/// press it.
fn recordDrawn(tag: []const u8, arg: i32) void {
    const now = dvui.frameTimeNS();
    if (now != drawn_frame) {
        for (drawn_buttons_prev.items) |b| state.gpa.free(b.id);
        drawn_buttons_prev.clearRetainingCapacity();
        std.mem.swap(std.ArrayList(DrawnButton), &drawn_buttons, &drawn_buttons_prev);
        drawn_frame = now;
    }
    if (buttonActionId(tag) == null) return;
    const keep = state.gpa.dupe(u8, tag) catch return;
    drawn_buttons.append(state.gpa, .{ .id = keep, .arg = arg }) catch {};
}

/// The action button `id` stands for (elements.zig; the keymap has every
/// button's).
fn buttonActionId(id: []const u8) ?keymap.ActionId {
    const name = elements.actionName(id) orelse return null;
    for (0..keymap.R.action_count) |k| {
        const a: keymap.ActionId = @intCast(k);
        if (std.mem.eql(u8, keymap.R.actionName(a), name)) return a;
    }
    return null;
}

/// At the frame's start: a script's press of a shown action button joins
/// the events; then each event runs its action.
fn dispatchButtons() void {
    if (scripted_press) |want| found: {
        // Once, though it may be in both frames' lists.
        for ([_][]const DrawnButton{ drawn_buttons.items, drawn_buttons_prev.items }) |list| for (list) |b| {
            if (!std.mem.eql(u8, b.id, want)) continue;
            pushButtonEvent(b.id, b.arg);
            scripted_press = null;
            break :found;
        };
    }
    const n = button_events_n;
    button_events_n = 0;
    for (button_events[0..n]) |e| {
        const id = e.id[0..e.id_len];
        const a = buttonActionId(id) orelse continue;
        state.context = e.context;
        if (!runButtonAction(.{ .action = a, .arg = e.arg })) dvui.log.err("button {s} has no handler", .{id});
    }
}

/// The button actions `runButtonAction` handles in its own switch.
const switch_handled = [_][]const u8{ "track.make-tracks", "track.remove", "track.name-tiles", "panel.name-tiles", "track.flow.show", "track.flow.join-after", "track.flow.take-out", "flows.new", "flow.remove", "panel.edit", "panel.release", "dialog.confirm", "dialog.cancel", "flow-style.update-style-for-all-flows", "flow-style.clear-overrides", "flow-style.save-as-template" };

/// Whether a button's action has a handler (every one should: a test
/// checks).
fn buttonHandled(name: []const u8) bool {
    for (switch_handled) |n| if (std.mem.eql(u8, n, name)) return true;
    for (button_handlers) |h| if (std.mem.eql(u8, keymap.R.actionName(h.action), name)) return true;
    return false;
}

/// The actions buttons stand for, on the context. Whether it was one.
fn runButtonAction(inv: keymap.Invocation) bool {
    switch (inv.action) {
        kact("track.make-tracks") => regionMakeTracks(),
        kact("track.remove") => switch (state.context) {
            .region => |r| removeRegionOf(r.parent, r.region),
            else => return false,
        },
        kact("track.name-tiles") => regionNameKeys(),
        kact("panel.name-tiles") => panelNameKeys(),
        kact("track.flow.show") => switch (state.context) {
            .region => |r| if (state.model.trackFlow(r.parent, r.region)) |f| {
                state.context = .{ .flow = f.id };
            },
            else => return false,
        },
        kact("track.flow.join-after") => switch (state.context) {
            .region => |r| {
                join_from = .{ .parent = r.parent, .region = r.region };
                state.tool = .join;
            },
            else => return false,
        },
        kact("track.flow.take-out") => trackTakeOut(),
        kact("flows.new") => {
            var nb: [32]u8 = undefined;
            const name = state.model.freshName(&nb, .flows, "Flow");
            if (act(.addFlow, .{name})) |id| {
                state.context = .{ .flow = id };
            } else |_| state.status = "The flow was not made. ";
        },
        kact("flow.remove") => flowRemove(),
        kact("panel.edit") => switch (state.context) {
            .panel => |pi| if (panel_edit == null) enterPanelEdit(pi),
            else => return false,
        },
        kact("panel.release") => panelRelease(),
        kact("flow-style.update-style-for-all-flows") => flowStyleUpdateAll(),
        kact("flow-style.clear-overrides") => flowStyleClear(),
        kact("flow-style.save-as-template") => flowStyleSaveTemplate(),
        kact("dialog.confirm"), kact("dialog.cancel") => dialog_answer = inv.action,
        else => {
            for (button_handlers) |h| if (h.action == inv.action) {
                h.run(inv.arg);
                return true;
            };
            // A button's action without a handler (a test sees there is
            // none) is not run; the app's own actions run as their keys do.
            if (std.mem.indexOfScalar(u8, keymap.R.actionName(inv.action), '.')) |_| {
                for (elements.button_actions) |name| if (std.mem.eql(u8, name, keymap.R.actionName(inv.action))) return false;
            }
            return runAction(inv);
        },
    }
    return true;
}

/// The context region's rows (or columns) made tracks, where they lie.
fn regionMakeTracks() void {
    const r = switch (state.context) {
        .region => |r| r,
        else => return,
    };
    const placed_rows = tracksIn(r.parent, r.region);
    if (placed_rows.len == 0) return;
    const a = dvui.currentWindow().arena();
    const origins = a.alloc(geom.Point, placed_rows.len) catch return;
    for (placed_rows, origins) |t, *o| o.* = .{ .x = t.box.x0, .y = t.box.y1 };
    if (act(.splitIntoTracks, .{ r.parent, r.region, origins })) |n| {
        track_cursor = null;
        state.status = std.fmt.bufPrint(&import_status_buf, "{d} tracks, its flow running through them. ", .{n}) catch "Made tracks. ";
    } else |_| state.status = "The tracks were not made. ";
}

/// The prefix keys are named with, in flow order (K1, K2 …).
var key_name_prefix: [16]u8 = .{'K'} ++ @as([15]u8, @splat(0));
var key_name_prefix_len: usize = 1;

/// The context track's flow's keys named in order.
fn regionNameKeys() void {
    const r = switch (state.context) {
        .region => |r| r,
        else => return,
    };
    const prefix = key_name_prefix[0..key_name_prefix_len];
    if (act(.nameKeysInOrder, .{ r.parent, r.region, prefix })) |n| {
        state.status = std.fmt.bufPrint(&import_status_buf, "{d} keys named. ", .{n}) catch "Named. ";
    } else |err| state.status = if (err == error.DuplicateDesignator) "A name is another key's elsewhere: none renamed. " else "The keys were not named. ";
}

/// The context panel's keys named in order (its tracks in turn, each
/// flow's keys): a keyboard of one flow a row named K1 … through all rows.
fn panelNameKeys() void {
    const pi = switch (state.context) {
        .panel => |pi| pi,
        else => return,
    };
    const prefix = key_name_prefix[0..key_name_prefix_len];
    if (act(.nameKeysInPanel, .{ Parent{ .panel = pi }, prefix })) |n| {
        state.status = std.fmt.bufPrint(&import_status_buf, "{d} keys named. ", .{n}) catch "Named. ";
    } else |err| state.status = if (err == error.DuplicateDesignator) "A name is another key's elsewhere: none renamed. " else "The keys were not named. ";
}

/// The context track taken out of its flow.
fn trackTakeOut() void {
    const r = switch (state.context) {
        .region => |r| r,
        else => return,
    };
    const f = state.model.trackFlow(r.parent, r.region) orelse return;
    const alone = f.tracks.items.len == 1;
    if (act(.detachTrack, .{ r.parent, r.region })) {
        state.status = if (alone) "Taken out: its text is kept in the flow, now unplaced (under Flows in the Browser). " else "Taken out: the flow keeps all its text, on its other tracks. ";
    } else |_| state.status = "The track was not taken out. ";
}

/// The context flow removed; one holding anything takes a second press.
fn flowRemove() void {
    const id = switch (state.context) {
        .flow => |id| id,
        else => return,
    };
    const fi = state.model.flowIndex(id) orelse return;
    const empty = state.model.flows.items[fi].items.items.len == 0;
    const armed = if (flow_remove_armed) |x| x == id else false;
    if (!(empty or armed)) {
        flow_remove_armed = id;
        return;
    }
    flow_remove_armed = null;
    if (act(.removeFlow, .{id})) {
        state.context = .flows;
        state.status = "Flow removed; its tracks have empty flows of their own. ";
    } else |_| state.status = "The flow was not removed. ";
}

/// The context panel released: its outline and contents loose again.
fn panelRelease() void {
    const pi = switch (state.context) {
        .panel => |pi| pi,
        else => return,
    };
    const id = act(.releasePanel, .{pi}) catch {
        state.status = "The panel could not be released. ";
        return;
    };
    state.context = if (state.model.locate(id)) |loc| switch (loc) {
        .art => |l| .{ .art = .{ .panel = l.panel, .index = l.index } },
        else => .worksheet,
    } else .worksheet;
    state.status = "Released: its outline and contents are loose again. ";
}

fn pressedByScript(tag: ?[]const u8) bool {
    const want = scripted_press orelse return false;
    const t = tag orelse return false;
    if (!std.mem.eql(u8, want, t)) return false;
    scripted_press = null;
    dvui.refresh(null, @src(), null);
    return true;
}

/// The tags given this frame, so a repeat is numbered ("…#2") rather than
/// a duplicate (which DVUI outlines in red).
var tags_given: std.StringHashMapUnmanaged(u16) = .empty;
var tags_frame: i128 = -1;

/// `base`, or `base#n` when this frame already has it.
fn uniqueTag(base: []const u8) []const u8 {
    const now = dvui.frameTimeNS();
    if (now != tags_frame) {
        tags_given.clearRetainingCapacity();
        tags_frame = now;
    }
    const e = tags_given.getOrPut(state.gpa, base) catch return base;
    if (!e.found_existing) {
        // The key must outlive the frame's arena entry only for this frame.
        e.value_ptr.* = 1;
        return base;
    }
    e.value_ptr.* += 1;
    return std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}#{d}", .{ base, e.value_ptr.* }) catch base;
}

/// The element (elements.zig) the next row or button drawn is: its id is
/// its tag, whatever section it is in.
var next_element: ?[]const u8 = null;

/// The logical group the elements drawn now belong to (elements.zig): set
/// by what they are about (the context's kind; a function drawing one
/// aspect of it), never by the headings or panes around them.
var group_buf: [160]u8 = undefined;
var elem_group: []const u8 = "";
/// The group of the function drawing now (`pushGroup`): a plain heading
/// returns to it, so a section after a loop of named ones (a prototype's
/// slots) is not taken for the last of them.
var base_buf: [160]u8 = undefined;
var base_group: []const u8 = "";

const SavedGroup = struct { buf: [160]u8, len: usize, base: [160]u8, base_len: usize };

/// Elements from here on are in group `name` (absolute), until `popGroup`.
fn pushGroup(name: []const u8) SavedGroup {
    var saved: SavedGroup = .{ .buf = undefined, .len = elem_group.len, .base = undefined, .base_len = base_group.len };
    @memcpy(saved.buf[0..elem_group.len], elem_group);
    @memcpy(saved.base[0..base_group.len], base_group);
    setGroup("{s}", .{name});
    setBase();
    return saved;
}

fn popGroup(saved: SavedGroup) void {
    @memcpy(group_buf[0..saved.len], saved.buf[0..saved.len]);
    elem_group = group_buf[0..saved.len];
    @memcpy(base_buf[0..saved.base_len], saved.base[0..saved.base_len]);
    base_group = base_buf[0..saved.base_len];
}

/// The group now is the function's own.
fn setBase() void {
    @memcpy(base_buf[0..elem_group.len], elem_group);
    base_group = base_buf[0..elem_group.len];
}

fn setGroup(comptime fmt: []const u8, args: anytype) void {
    elem_group = std.fmt.bufPrint(&group_buf, fmt, args) catch "";
}

/// `text` as an id part: lower case, words joined by "-", what follows a
/// comma (a unit) left out ("Origin across, mm": origin-across).
fn kebab(text: []const u8) []const u8 {
    const head = if (std.mem.indexOfScalar(u8, text, ',')) |k| text[0..k] else text;
    var out: std.ArrayList(u8) = .empty;
    const a = dvui.currentWindow().arena();
    var dash = false;
    for (head) |c| {
        if (std.ascii.isAlphanumeric(c)) {
            if (dash and out.items.len > 0) out.append(a, '-') catch {};
            dash = false;
            out.append(a, std.ascii.toLower(c)) catch {};
        } else dash = true;
    }
    if (out.items.len == 0 or !std.ascii.isLower(out.items[0])) out.insert(a, 0, 'x') catch {};
    return out.items;
}

/// A name as an id part, all of it (a list item: "Generic FDM, 0.4 mm
/// nozzle": generic-fdm-0-4-mm-nozzle), unlike a label's unit.
fn nameKey(name: []const u8) []const u8 {
    var out: std.ArrayList(u8) = .empty;
    const a = dvui.currentWindow().arena();
    var dash = false;
    for (name) |c| {
        if (std.ascii.isAlphanumeric(c)) {
            if (dash and out.items.len > 0) out.append(a, '-') catch {};
            dash = false;
            out.append(a, std.ascii.toLower(c)) catch {};
        } else dash = true;
    }
    if (out.items.len == 0 or !std.ascii.isLower(out.items[0])) out.insert(a, 0, 'x') catch {};
    return out.items;
}

/// The next element drawn is the item named `name` of list `list` (a
/// group; the registry has `<list>.*`).
fn listItem(list: []const u8, name: []const u8) void {
    next_element = std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.{s}", .{ list, nameKey(name) }) catch null;
}

/// A face's row (its role), as an item of `list`; its label.
fn faceItem(list: []const u8, role: []const u8) []const u8 {
    listItem(list, role);
    return role;
}

/// The id of item `name` of list `list`, for a button's `.tag`.
fn listTag(list: []const u8, name: []const u8) []const u8 {
    listItem(list, name);
    const id = next_element orelse return list;
    next_element = null;
    checkElement(id, .button, name);
    return uniqueTag(id);
}

/// The kind of the next element tagged, for the registry's check.
var next_kind: elements.Kind = .field;

/// GRAVEN_ELEMENTS_LOG: each element drawn that the registry lacks,
/// appended there ("id kind label"), to fill the registry from.
var elements_log: ?std.Io.File = null;

/// Checks a grouped element's id against the registry; logs one it lacks.
fn checkElement(id: []const u8, kind: elements.Kind, label: []const u8) void {
    if (elements.find(id) != null) return;
    dvui.log.err("element {s} ({s}) is not in the registry", .{ id, @tagName(kind) });
    if (elements_log) |f| {
        var buf: [512]u8 = undefined;
        const line = std.fmt.bufPrint(&buf, "{s} {s} {s}\n", .{ id, @tagName(kind), label }) catch return;
        var w = f.writerStreaming(dvui.io, &.{});
        w.interface.writeAll(line) catch {};
    }
}

/// The next row is element `id`, labelled `label` when it says more than
/// the registry's ("Depth, columns").
fn elementLabel(comptime id: []const u8, label: ?[]const u8) []const u8 {
    const l = asElement(id);
    return label orelse l;
}

/// The next row or button is element `id`; its label, from the registry.
fn asElement(comptime id: []const u8) []const u8 {
    next_element = id;
    return comptime elements.get(id).label;
}

/// "<section>.<label as an identifier>", for this frame; the element's id
/// when one was named (`asElement`).
fn tagFor(name: []const u8) []const u8 {
    const kind = next_kind;
    next_kind = .field;
    if (next_element) |id| {
        next_element = null;
        checkElement(id, kind, std.mem.trim(u8, name, " "));
        return uniqueTag(id);
    }
    if (elem_group.len > 0) {
        const id = std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.{s}", .{ elem_group, kebab(std.mem.trim(u8, name, " ")) }) catch return name;
        checkElement(id, kind, std.mem.trim(u8, name, " "));
        return uniqueTag(id);
    }
    return elementTag(lowerCamel(std.mem.trim(u8, name, " ")));
}

/// Tags the widget being laid out around this point (a property's row)
/// as `name` in the current scope.
fn tagParent(name: []const u8) void {
    if (std.mem.trim(u8, name, " ").len == 0) return;
    const wd = dvui.parentGet().data();
    const t = tagFor(name);
    last_row_tag = t;
    accepted.current_id = t;
    dvui.tag(t, .{ .id = wd.id, .rect = wd.rectScale().r, .visible = wd.visible() });
}

/// The last property row tagged: a dropdown in it answers to its tag.
var last_row_tag: []const u8 = "";

/// A choice the GUI's tests ask for: the dropdown in the row tagged `tag`
/// takes the entry `label` as if it had been picked from its list.
var test_choice: ?struct { tag: []const u8, label: []const u8 } = null;

/// `dvui.dropdown`, which the tests can make choose (`test_choice`).
fn tdropdown(src: std.builtin.SourceLocation, entries: []const []const u8, choice: dvui.DropdownChoice(usize), init_opts: dvui.DropdownInitOptions, opts: dvui.Options) bool {
    const picked = dvui.dropdown(src, entries, choice, init_opts, opts);
    if (test_choice) |want| if (choice == .choice and std.mem.eql(u8, want.tag, last_row_tag)) {
        for (entries, 0..) |e, i| if (std.mem.eql(u8, e, want.label)) {
            test_choice = null;
            if (choice.choice.* == i) return false;
            choice.choice.* = i;
            return true;
        };
    };
    return picked;
}

/// `dvui.checkbox`, tagged by its label in the current scope.
fn tcheckbox(src: std.builtin.SourceLocation, target: *bool, label: ?[]const u8, opts: dvui.Options) bool {
    var o = opts;
    if (o.tag == null) if (label) |l| {
        next_kind = .toggle;
        o.tag = tagFor(l);
    };
    const clicked = dvui.checkbox(src, target, label, o);
    if (!clicked and pressedByScript(o.tag)) {
        target.* = !target.*;
        return true;
    }
    return clicked;
}

/// `dvui.button`, tagged by its label in the current scope.
fn tbutton(src: std.builtin.SourceLocation, label: []const u8, init_opts: dvui.ButtonWidget.InitOptions, opts: dvui.Options) bool {
    var o = opts;
    if (o.tag == null) {
        next_kind = .button;
        o.tag = tagFor(label);
    }
    return virtualKey(dvui.button(src, label, init_opts, o), o.tag.?);
}

/// A button as a virtual key: a click is an event for its action, run at
/// the next frame's start by its handler. A button the registry lacks
/// (interface chrome: a Browser node's chevron, a view tab's close) acts
/// at once, where it is drawn.
fn virtualKey(clicked: bool, tag: []const u8) bool {
    recordDrawn(tag, 0);
    if (clicked) {
        if (buttonActionId(tag) == null) return true;
        pushButtonEvent(tag, 0);
        return false;
    }
    // A script's press of a button not in the registry (interface chrome).
    return pressedByScript(tag);
}

/// A button as a virtual key whose effect is a handler
/// (`button_handlers`): drawn, a click is an event for its action, with
/// `arg` (which of several things it stands for).
fn keyButton(src: std.builtin.SourceLocation, label: []const u8, arg: i32, opts: dvui.Options) void {
    var o = opts;
    if (o.tag == null) {
        next_kind = .button;
        o.tag = tagFor(label);
    }
    const tag = o.tag.?;
    recordDrawn(tag, arg);
    if (dvui.button(src, label, .{}, o)) pushButtonEvent(tag, arg);
}

/// An icon button as a virtual key (see `keyButton`).
fn keyIcon(src: std.builtin.SourceLocation, name: []const u8, tvg: []const u8, arg: i32, opts: dvui.Options) void {
    var o = opts;
    if (o.tag == null) {
        next_kind = .button;
        o.tag = if (elem_group.len > 0) tagFor(name) else uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "tool.{s}", .{lowerCamel(name)}) catch "tool");
    }
    const tag = o.tag.?;
    recordDrawn(tag, arg);
    var wd: dvui.WidgetData = undefined;
    const out = o.data_out;
    o.data_out = &wd;
    // In the ribbon: a larger button, its icon in the upper part, its key
    // in a fade across the bottom.
    var kb: [48]u8 = undefined;
    const badge = if (in_ribbon) (ribbon_next_badge orelse badgeText(&kb, tag, arg)) else null;
    ribbon_next_badge = null;
    const drop = if (in_ribbon) ribbon_next_drop else null;
    ribbon_next_drop = null;
    if (in_ribbon) {
        if (ribbonKey(src, name, tvg, o, drop, &wd)) pushButtonEvent(tag, arg);
    } else if (dvui.buttonIcon(src, name, tvg, .{}, .{}, o)) pushButtonEvent(tag, arg);
    if (out) |d| d.* = wd;
    if (badge) |b| keyFade(wd.borderRectScale().r, b);
}

/// The ribbon's keys: square, side by side at this pitch, logical (64
/// device pixels at 200 %; the owner, 2026-11-22). An icon from an icon
/// file covers the whole key (its drawing inset in it); any other icon is
/// drawn at `ribbon_icon`, centred in the key's upper part.
/// The ribbon's key size (right-click the ribbon to choose; this machine's
/// setting, `ribbon.size`): the pitch in logical pixels. Medium is 64
/// device pixels at 200 % (the owner, 2026-11-22).
const RibbonSize = enum {
    small,
    medium,
    large,
    extra_large,

    fn pitch(z: RibbonSize) f32 {
        return switch (z) {
            .small => 24,
            .medium => 32,
            .large => 40,
            .extra_large => 48,
        };
    }

    fn label(z: RibbonSize) []const u8 {
        return switch (z) {
            .small => "Small keys",
            .medium => "Medium keys",
            .large => "Large keys",
            .extra_large => "Extra large keys",
        };
    }

    fn tag(z: RibbonSize) []const u8 {
        return switch (z) {
            .small => "ribbon-size.small",
            .medium => "ribbon-size.medium",
            .large => "ribbon-size.large",
            .extra_large => "ribbon-size.extra-large",
        };
    }
};
var ribbon_size: RibbonSize = .medium;

/// The constraint pop-up for a chosen construction line (K with it
/// chosen): which line, where it opened, the frame it was asked in.
var constrain_menu: ?struct { space: usize, index: usize } = null;
var constrain_menu_from: dvui.Rect.Natural = .{};
var constrain_menu_frame: i128 = 0;

fn openConstrainMenu(space: usize, index: usize) void {
    constrain_menu = .{ .space = space, .index = index };
    const m = dvui.currentWindow().mouse_pt;
    const ns = dvui.windowNaturalScale();
    constrain_menu_from = .{ .x = m.x / ns, .y = m.y / ns, .w = 1, .h = 1 };
    constrain_menu_frame = dvui.frameTimeNS();
    dvui.refresh(null, @src(), null);
}

fn constrainMenuClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    closeConstrainMenu();
}

/// The pop-up closed, the keyboard back on the canvas (the menu's
/// subwindow had it).
fn closeConstrainMenu() void {
    constrain_menu = null;
    const main_sw = dvui.currentWindow().data().id;
    dvui.focusSubwindow(main_sw, null);
    if (canvas_id) |id| dvui.focusWidget(id, main_sw, null);
}

/// The pop-up: Horizontal, Vertical, and Distance from… (a line already
/// horizontal or vertical), each with its key.
fn constrainMenu() void {
    const cm = constrain_menu orelse return;
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&constrain_menu), .close = constrainMenuClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    var fm = dvui.floatingMenu(@src(), .{ .from = constrain_menu_from, .style = .popup }, .{});
    defer fm.deinit();
    const straight = guideFeature(cm.space, cm.index) != null;
    inline for (.{ "constrain-menu.horizontal", "constrain-menu.vertical", "constrain-menu.distance" }, 0..) |id, i| {
        const tag = uniqueTag(id);
        recordDrawn(tag, 0);
        const off = i == 2 and !straight;
        var bw: dvui.ButtonWidget = undefined;
        bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = i, .tag = tag, .margin = .all(1), .padding = .{ .x = 8, .w = 8, .y = 3, .h = 4 } });
        bw.processEvents();
        bw.drawBackground();
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
            defer row.deinit();
            const ink = dvui.themeGet().color(.window, .text);
            dvui.labelNoFmt(@src(), comptime elements.get(id).label, .{}, .{ .padding = .all(0), .margin = .all(0), .expand = .horizontal, .color_text = if (off) .{ .color = ink.opacity(0.4) } else null });
            var kb: [24]u8 = undefined;
            if (keymap.shortcut(&kb, kmode("canvas.constrain-menu"), kact(id), 0)) |sc| dvui.labelNoFmt(@src(), sc, .{}, .{ .padding = .{ .x = 16 }, .margin = .all(0), .color_text = .{ .color = ink.opacity(0.55) } });
        }
        if (bw.clicked()) pushButtonEvent(tag, 0);
        bw.drawFocus();
        bw.deinit();
    }
}

/// The construction line the pop-up is for, held horizontal or vertical
/// (turned about its point): one step.
fn holdGuide(lock: layout.model.GuideLock) void {
    const cm = constrain_menu orelse return;
    closeConstrainMenu();
    if (cm.space >= state.model.spaces.items.len) return;
    const list = state.model.spaces.items[cm.space].guides.items;
    if (cm.index >= list.len) return;
    const g = list[cm.index];
    const angle: f64 = if (lock == .horizontal) 0 else 90;
    act(.setGuide, .{ cm.space, cm.index, g.at, angle, lock }) catch return;
    state.status = if (lock == .horizontal) "Held horizontal. " else "Held vertical. ";
}

/// A horizontal or vertical construction line as the Constrain tool's
/// first pick (its height or place across, along it); null for a line at
/// another angle.
fn guideFeature(space: usize, index: usize) ?FeatureHit {
    if (space >= state.model.spaces.items.len) return null;
    const list = state.model.spaces.items[space].guides.items;
    if (index >= list.len) return null;
    const g = list[index];
    const r = g.angle * std.math.pi / 180;
    const horizontal = @abs(@sin(r)) < 1e-9;
    if (!horizontal and @abs(@cos(r)) >= 1e-9) return null;
    const far = 1e5;
    const clip: geom.Box = if (canvas_free) |cf| guideClipBox(cf.area, space) else .{ .x0 = -far, .x1 = far, .y0 = -far, .y1 = far };
    const seg = g.clip(clip) orelse return null;
    return .{ .end = .{ .object = g.id, .feature = if (horizontal) .origin_y else .origin_x }, .parent = .{ .space = space }, .p0 = seg[0], .p1 = seg[1] };
}

/// The key-size pop-up (a right-click on the ribbon): open, where, and
/// the frame it was asked for in (it is drawn from the next).
var ribbon_size_menu = false;
var ribbon_size_from: dvui.Rect.Natural = .{};
var ribbon_size_frame: i128 = 0;

fn ribbonSizeMenuClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    ribbon_size_menu = false;
}

/// The ribbon's key sizes, the one in use marked; a choice is kept in this
/// machine's settings.
fn ribbonSizeMenu() void {
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&ribbon_size_menu), .close = ribbonSizeMenuClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    var fm = dvui.floatingMenu(@src(), .{ .from = ribbon_size_from, .style = .popup }, .{});
    defer fm.deinit();
    inline for (comptime std.enums.values(RibbonSize), 0..) |z, i| {
        const tag = uniqueTag(z.tag());
        recordDrawn(tag, i);
        var bw: dvui.ButtonWidget = undefined;
        bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = i, .tag = tag, .margin = .all(1), .padding = .{ .x = 8, .w = 8, .y = 3, .h = 4 } });
        bw.processEvents();
        bw.drawBackground();
        var lb: [48]u8 = undefined;
        const text = std.fmt.bufPrint(&lb, "{s}{s}", .{ if (ribbon_size == z) "•  " else "    ", z.label() }) catch z.label();
        dvui.labelNoFmt(@src(), text, .{}, .{ .padding = .all(0), .margin = .all(0) });
        if (bw.clicked()) pushButtonEvent(tag, i);
        bw.drawFocus();
        bw.deinit();
    }
}

/// The ribbon keys' pitch, logical; what was drawn for 32 scales by
/// `ribbonScale`.
fn ribbonPitch() f32 {
    return ribbon_size.pitch();
}
fn ribbonScale() f32 {
    return ribbonPitch() / 32;
}
/// A borrowed (vector) icon's size in a key.
fn ribbonIcon() f32 {
    return 26 * ribbonScale();
}
/// The key's letters: their foot this far above the key's bottom, logical
/// (the owner, 2026-11-22).
fn ribbonKeyMargin() f32 {
    return 3 * ribbonScale();
}

/// A ribbon button, drawn as a key in a row of keys (the owner's choice,
/// 2026-11-22: "A3"): neighbours touching, corners 2 px, each shaded
/// slightly from top to bottom like a raised key, a dark line (22 %) at
/// its right and a light one at its left between it and the next; the
/// icon large in the upper part. `o.color_fill`, when given, tints it (a
/// tool on). Whether it was clicked.
fn ribbonKey(src: std.builtin.SourceLocation, name: []const u8, tvg: []const u8, o: dvui.Options, drop: ?Drop, wd: *dvui.WidgetData) bool {
    var bw: dvui.ButtonWidget = undefined;
    bw.init(src, .{}, .{ .id_extra = o.id_extra, .tag = o.tag, .margin = .all(0), .padding = .all(0), .min_size_content = .{ .w = ribbonPitch(), .h = ribbonPitch() }, .max_size_content = .{ .w = ribbonPitch(), .h = ribbonPitch() }, .gravity_y = 0.5, .background = false, .label = .{ .text = name } });
    // A key with a drop: its top right corner is the drop's ▾, taking its
    // presses before the key does (the owner, 2026-11-22: inside the key,
    // keeping the pitch).
    const corner: ?dvui.Rect.Physical = if (drop != null) blk: {
        const r0 = bw.data().borderRectScale().r;
        const s0 = dvui.windowNaturalScale();
        break :blk .{ .x = r0.x + r0.w - dropCorner_() * s0, .y = r0.y, .w = dropCorner_() * s0, .h = dropCorner_() * s0 };
    } else null;
    if (drop) |d| for (dvui.events()) |*e| {
        if (e.handled or e.evt != .mouse) continue;
        const me = e.evt.mouse;
        if (!me.button.pointer() or !corner.?.contains(me.p)) continue;
        switch (me.action) {
            .press => e.handle(@src(), bw.data()),
            .release => {
                e.handle(@src(), bw.data());
                pushButtonEvent(uniqueTag(d.id()), 0);
            },
            else => {},
        }
    };
    // A press would take the keyboard focus to the key (and draw its focus
    // ring there); a ribbon key gives it straight back to where it was
    // (the owner, 2026-11-22). Its click still comes: that needs the
    // pointer's capture, not the focus.
    const focus_had = dvui.focusedWidgetId();
    const focus_sub = dvui.focusedSubwindowId();
    bw.processEvents();
    if (dvui.focusedWidgetId() == bw.data().id and focus_had != bw.data().id) {
        dvui.focusWidget(focus_had, focus_sub, null);
    }
    const r = bw.data().borderRectScale().r;
    const s = dvui.windowNaturalScale();
    // The key: a shade from top to bottom.
    {
        const top_c: dvui.Color = .{ .r = 0xfb, .g = 0xfa, .b = 0xf8 };
        const bot_c: dvui.Color = .{ .r = 0xe6, .g = 0xe4, .b = 0xdf };
        const lifo = dvui.currentWindow().lifo();
        var b = dvui.Triangles.Builder.init(lifo, 4, 6) catch return false;
        defer b.deinit(lifo);
        const p = [4]dvui.Point.Physical{ .{ .x = r.x, .y = r.y }, .{ .x = r.x + r.w, .y = r.y }, .{ .x = r.x + r.w, .y = r.y + r.h }, .{ .x = r.x, .y = r.y + r.h } };
        const ct: dvui.Color.PMA = .fromColor(display.fix(top_c));
        const cb: dvui.Color.PMA = .fromColor(display.fix(bot_c));
        b.appendVertex(.{ .pos = p[0], .col = ct });
        b.appendVertex(.{ .pos = p[1], .col = ct });
        b.appendVertex(.{ .pos = p[2], .col = cb });
        b.appendVertex(.{ .pos = p[3], .col = cb });
        b.appendTriangles(&ccw(p[0], p[1], p[2], 0, 1, 2));
        b.appendTriangles(&ccw(p[0], p[2], p[3], 0, 2, 3));
        dvui.renderTriangles(b.build_unowned(), null) catch {};
    }
    // On, hovered, pressed: tints over the shade.
    if (o.color_fill) |cf| r.fill(.all(2 * s), .{ .color = cf });
    if (bw.pressed()) {
        r.fill(.all(2 * s), .{ .color = .{ .color = dvui.Color.black.opacity(0.10) } });
    } else if (bw.hovered()) r.fill(.all(2 * s), .{ .color = .{ .color = dvui.themeGet().focus.opacity(0.12) } });
    // Between neighbours: a light line at the left, a dark one at the right.
    (dvui.Rect.Physical{ .x = r.x, .y = r.y, .w = s, .h = r.h }).fill(.{}, .{ .color = .{ .color = dvui.Color.white } });
    (dvui.Rect.Physical{ .x = r.x + r.w - s, .y = r.y, .w = s, .h = r.h }).fill(.{}, .{ .color = .{ .color = dvui.Color.black.opacity(0.22) } });
    const ink = dvui.themeGet().color(.control, .text);
    // Graven's own icons from the icon files (the user's first), the
    // whole key; failing that, as vectors: Graven's in their own colours,
    // others in the ink.
    const file_name = icons.gravenNameOf(tvg);
    const drawn = if (file_name) |fname| blk: {
        const cell = iconfile.get(fname) orelse break :blk false;
        break :blk iconfile.draw(fname, r, iconfile.inkOf(cell), display.fix(dvui.Color.white));
    } else false;
    if (!drawn) {
        const own = file_name != null;
        const side = (ribbonPitch() - ribbonIcon()) / 2;
        dvui.icon(@src(), name, tvg, if (own) .{ .fill_color = null, .stroke_color = null } else .{ .fill_color = .{ .color = ink }, .stroke_color = .{ .color = ink } }, .{ .expand = .both, .role = .none, .padding = .{ .x = side, .w = side, .y = 1, .h = 2 * side - 1 } });
    }
    if (drop) |d| dropCorner(d, corner.?, r, o.id_extra orelse 0);
    const clicked = bw.clicked();
    bw.drawFocus();
    wd.* = bw.data().*;
    bw.deinit();
    return clicked;
}

/// Key text `text` in a fade across the bottom of button `r`: the
/// button's lower edge darkening into a band the key sits in (the owner's
/// choice, 2026-11-22, over badges); stronger while Alt is held.
fn keyFade(r: dvui.Rect.Physical, text: []const u8) void {
    const s = dvui.windowNaturalScale();
    const held = dvui.currentWindow().modifiers.alt();
    const band = 16 * ribbonScale() * s;
    const inset = 1 * s;
    const top = r.y + r.h - band - inset;
    const x0 = r.x + inset;
    const x1 = r.x + r.w - inset;
    const y1 = r.y + r.h - inset;
    const ink = ghost_pane.oklch(0.26, 0.07, ghost_pane.pane_hue, 1);
    const lifo = dvui.currentWindow().lifo();
    var b = dvui.Triangles.Builder.init(lifo, 4, 6) catch return;
    defer b.deinit(lifo);
    const clear: dvui.Color.PMA = .fromColor(ink.opacity(0));
    const deep: dvui.Color.PMA = .fromColor(ink.opacity(if (held) 0.92 else 0.55));
    const p = [4]dvui.Point.Physical{ .{ .x = x0, .y = top }, .{ .x = x1, .y = top }, .{ .x = x1, .y = y1 }, .{ .x = x0, .y = y1 } };
    b.appendVertex(.{ .pos = p[0], .col = clear });
    b.appendVertex(.{ .pos = p[1], .col = clear });
    b.appendVertex(.{ .pos = p[2], .col = deep });
    b.appendVertex(.{ .pos = p[3], .col = deep });
    b.appendTriangles(&ccw(p[0], p[1], p[2], 0, 1, 2));
    b.appendTriangles(&ccw(p[0], p[2], p[3], 0, 2, 3));
    dvui.renderTriangles(b.build_unowned(), null) catch {};
    const font = dvui.Font.theme(.body).withSize(10 * ribbonScale()).withWeight(.bold);
    var ascent: f32 = 0;
    const size = font.textSizeEx(text, .{ .ascent_out = &ascent });
    // The letters' foot (the baseline: keys have no descenders) a little
    // above the key's bottom.
    dvui.renderText(.{ .font = font, .text = text, .rs = .{ .r = r, .s = s }, .p = .{ .x = r.x + (r.w - size.w * s) / 2, .y = r.y + r.h - (ribbonKeyMargin() + ascent) * s }, .color = dvui.Color.white }) catch {};
}

// The ribbon's drops ------------------------------------------------------------
//
// A ribbon button with more behind it has a ▾ after it: a pull-down (a
// few choices) or a drop panel (a palette, the window's width, under the
// ribbon, over the views). The ▾ opens it, as does holding the button's
// key (a tap still runs the button). Nothing modal, no OK or Cancel: each
// change applies as made (undo takes it back); it goes on Esc, a click
// elsewhere, or once the pointer has been in it and leaves.

const Drop = enum {
    /// The Layers panel.
    layers,
    /// Add shape's kinds.
    shape,
    /// Add rows' kinds: rows, columns, one track.
    tracks,
    /// The Text style panel.
    styles,
    /// Add array's kind and cell counts.
    array,

    fn panel(d: Drop) bool {
        return d == .layers or d == .styles;
    }

    fn id(d: Drop) []const u8 {
        return switch (d) {
            .layers => "ribbon.layers",
            .shape => "ribbon.drop.shape",
            .tracks => "ribbon.drop.tracks",
            .styles => "ribbon.styles",
            .array => "ribbon.drop.array",
        };
    }

    /// The tool action whose key, held, opens it.
    fn heldBy(a: keymap.ActionId) ?Drop {
        if (a == kact("tool.add-shape")) return .shape;
        if (a == kact("tool.layout-column-of-rows") or a == kact("tool.layout-row-of-columns") or a == kact("tool.layout-single-track")) return .tracks;
        if (a == kact("ribbon.layers")) return .layers;
        if (a == kact("ribbon.styles")) return .styles;
        if (a == kact("tool.add-array")) return .array;
        return null;
    }
};

/// The next ribbon button's drop (set just before drawing it).
var ribbon_next_drop: ?Drop = null;
/// The next ribbon key's key text, when it is not found from its action
/// (a mode's own keys, as the sketch editor's).
var ribbon_next_badge: ?[]const u8 = null;
/// The drop open, where it hangs from (natural), and when it was opened
/// (its first frame is the next: the click that opened it would close it).
var drop_open: ?Drop = null;
var drop_from: dvui.Rect.Natural = .{};
var drop_frame: i128 = 0;
var drop_focus = false;
/// Whether the pointer has been in it (it goes once it leaves).
var drop_entered = false;
var drop_rect: dvui.Rect.Physical = .{};
/// Each drop's ▾ (or button), where last drawn, natural.
var drop_anchor: std.EnumArray(Drop, dvui.Rect.Natural) = .initFill(.{});
/// A key held that opens a drop when held long enough (else, released,
/// it runs its action).
var key_hold: ?struct { inv: keymap.Invocation, t0: i64, opened: bool = false } = null;
const hold_ms = 300;

fn openDrop(d: ?Drop) void {
    if (d != null and drop_open == d) {
        drop_open = null;
        return;
    }
    drop_open = d;
    drop_frame = dvui.frameTimeNS();
    drop_focus = true;
    drop_entered = false;
    if (d) |x| drop_from = drop_anchor.get(x);
    dvui.refresh(null, @src(), null);
}

fn dropClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    drop_open = null;
}

/// The ▾ after a ribbon button: its drop's button. Returns its rect.
/// A ribbon key's drop: a ▾ in its top right corner `cz`, on a small tab
/// of the key's own colour so it reads over the icon; tinted while hovered
/// and while its drop is open. (The press is taken in `ribbonKey`.)
fn dropCorner(d: Drop, cz: dvui.Rect.Physical, key: dvui.Rect.Physical, id_extra: usize) void {
    const tag = uniqueTag(d.id());
    recordDrawn(tag, 0);
    const s = dvui.windowNaturalScale();
    const corners: dvui.CornerRect.Physical = .{ .bl = .theme(3 * s) };
    cz.fill(corners, .{ .color = .{ .color = display.fix(dvui.Color{ .r = 0xe9, .g = 0xe7, .b = 0xe2 }) } });
    if (drop_open == d) {
        cz.fill(corners, .{ .color = .{ .color = dvui.themeGet().focus.opacity(0.35) } });
    } else if (cz.contains(dvui.currentWindow().mouse_pt)) cz.fill(corners, .{ .color = .{ .color = dvui.themeGet().focus.opacity(0.18) } });
    // Its element, for finding it by name.
    var zb = dvui.box(@src(), .{}, .{ .rect = .{ .x = ribbonPitch() - dropCorner_(), .y = 0, .w = dropCorner_(), .h = dropCorner_() }, .tag = tag, .id_extra = 7000 + 100 * @as(usize, @intFromEnum(d)) + id_extra });
    zb.deinit();
    // The ▾: a solid triangle in the ink.
    const ink = dvui.themeGet().color(.control, .text);
    const cx = cz.x + cz.w / 2 + 0.5 * s;
    const cy = cz.y + cz.h / 2 - 0.5 * s;
    const hw = 3.2 * ribbonScale() * s;
    const hh = 1.9 * ribbonScale() * s;
    const lifo = dvui.currentWindow().lifo();
    var tb = dvui.Triangles.Builder.init(lifo, 3, 3) catch return;
    defer tb.deinit(lifo);
    const col: dvui.Color.PMA = .fromColor(ink);
    const p = [3]dvui.Point.Physical{ .{ .x = cx - hw, .y = cy - hh }, .{ .x = cx + hw, .y = cy - hh }, .{ .x = cx, .y = cy + hh } };
    for (p) |q| tb.appendVertex(.{ .pos = q, .col = col });
    tb.appendTriangles(&ccw(p[0], p[1], p[2], 0, 1, 2));
    dvui.renderTriangles(tb.build_unowned(), null) catch {};
    // The drop hangs below the key (a pop-up opens at its anchor's top).
    drop_anchor.set(d, (dvui.Rect.Physical{ .x = key.x, .y = key.y + key.h, .w = key.w, .h = 0 }).toNatural());
}

/// A ribbon key's drop corner's side, logical.
fn dropCorner_() f32 {
    return 12 * ribbonScale();
}

/// Each frame: a key held long enough opens its drop; the drop open drawn.
fn ribbonDrops() void {
    if (key_hold) |*h| if (!h.opened) {
        const now = std.Io.Clock.awake.now(dvui.io).toMilliseconds();
        if (now - h.t0 >= hold_ms) {
            h.opened = true;
            if (Drop.heldBy(h.inv.action)) |d| if (drop_open != d) openDrop(d);
        } else dvui.timer(dvui.currentWindow().data().id, @intCast((hold_ms - (now - h.t0)) * 1000));
    };
    const d = drop_open orelse return;
    if (d.panel() and activeKind() != .canvas) {
        drop_open = null;
        return;
    }
    // From the frame after it was asked for.
    if (drop_frame == dvui.frameTimeNS()) {
        dvui.refresh(null, @src(), null);
        return;
    }
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&drop_open), .close = dropClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    if (d.panel()) {
        // The window's width, under the ribbon, dark as the panes. A plain
        // floating window, not a pop-up: a row dragged in it floats in a
        // window of its own, which would close a pop-up. It closes itself:
        // Esc, a press outside it, the pointer leaving.
        const win = dvui.windowRect();
        const prev = dvui.themeGet();
        dvui.themeSet(ghost_pane.darkTheme(prev));
        defer dvui.themeSet(prev);
        const S = struct {
            var rect: dvui.Rect = .{};
        };
        const first = drop_focus;
        S.rect.x = 0;
        S.rect.y = ribbon_bottom;
        // Its key joined to it (drawn here, over the strips under the
        // ribbon; the panel covers the bridge's foot).
        dropBridge(drop_anchor.get(d).scale(dvui.windowNaturalScale(), dvui.Rect.Physical), dvui.themeGet().color(.window, .fill).opacity(0.97));
        S.rect.w = win.w;
        var fw = dvui.floatingWindow(@src(), .{ .rect = &S.rect, .resize = .none }, .{ .id_extra = @intFromEnum(d), .min_size_content = .{ .w = win.w - 2 }, .background = true, .color_fill = .{ .color = dvui.themeGet().color(.window, .fill).opacity(0.97) }, .border = .{ .h = 1 }, .corners = .all(0), .box_shadow = null });
        defer fw.deinit();
        // Its height follows its content (layers added while it is open).
        _ = first;
        fw.autoSize();
        dropFocus(fw.data().id);
        const r = fw.data().borderRectScale().r;
        drop_rect = r;
        for (dvui.events()) |*e| switch (e.evt) {
            .key => |k| if (k.action == .down and k.code == .escape and !e.handled) {
                e.handle(@src(), fw.data());
                drop_open = null;
            },
            .mouse => |m| if (m.action == .press and !r.contains(m.p) and !drop_from.scale(dvui.windowNaturalScale(), dvui.Rect.Physical).contains(m.p)) {
                drop_open = null;
            },
            else => {},
        };
        dropLeave(r);
        switch (d) {
            .layers => layersPanel(),
            .styles => stylesPanel(),
            else => {},
        }
    } else {
        var fm = dvui.floatingMenu(@src(), .{ .from = drop_from, .style = .popup }, .{ .id_extra = @intFromEnum(d) });
        defer fm.deinit();
        dropFocus(fm.data().id);
        dropLeave(fm.data().borderRectScale().r);
        switch (d) {
            .shape => shapeMenu(),
            .tracks => tracksMenu(),
            .array => arrayMenu(),
            else => {},
        }
    }
}

fn dropFocus(id: dvui.Id) void {
    if (!drop_focus) return;
    drop_focus = false;
    dvui.focusSubwindow(id, null);
}

/// Once the pointer has been in the drop (`r`) and is away from it and
/// its button, the drop goes; not while a key held is still down.
fn dropLeave(r: dvui.Rect.Physical) void {
    const m = dvui.currentWindow().mouse_pt;
    const s = dvui.windowNaturalScale();
    const near = r.outset(.all(12 * s));
    const anchor = drop_from.scale(s, dvui.Rect.Physical).outset(.all(6 * s));
    if (near.contains(m)) {
        drop_entered = true;
        return;
    }
    if (drop_entered and !anchor.contains(m) and key_hold == null) {
        drop_open = null;
        dvui.refresh(null, @src(), null);
    }
}

/// A row of a drop's list, its label from the left; pressed: its action.
fn dropItem(comptime list: []const u8, name: []const u8, arg: i32, on: bool, id_extra: usize) void {
    const tag = listTag(list, name);
    recordDrawn(tag, arg);
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = id_extra, .tag = tag, .margin = .all(1), .padding = .{ .x = 10, .w = 14, .y = 4, .h = 5 }, .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.3) } else null, .background = on });
    bw.processEvents();
    bw.drawBackground();
    dvui.labelNoFmt(@src(), name, .{}, .{ .padding = .all(0), .margin = .all(0) });
    if (bw.clicked()) pushButtonEvent(tag, arg);
    bw.drawFocus();
    bw.deinit();
}

const shape_names = [_][]const u8{ "Rectangle", "Rounded rectangle", "Circle", "Ellipse", "Slot", "Polygon" };

fn shapeMenu() void {
    for (shape_names, 0..) |n, i| dropItem("ribbon.shape", n, @intCast(i), state.tool == .add_art and @intFromEnum(shape_kind) == i, i);
}

const array_names = [_][]const u8{ "Rectangular array", "Polar array" };

/// Add array's drop: its kind, its counts, and Apply (which arms the tool:
/// the next drag lays out the cells).
fn arrayMenu() void {
    for (array_names, 0..) |n, i| dropItem("ribbon.array", n, @intCast(i), (i == 1) == array_tool.polar, i);
    const saved = pushGroup("array");
    defer popGroup(saved);
    var box = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal, .min_size_content = .{ .w = 200 }, .padding = .{ .x = 10, .w = 10, .y = 4, .h = 6 } });
    defer box.deinit();
    const labels: [2][]const u8 = if (array_tool.polar) .{ "Around", "Rings" } else .{ "Columns", "Rows" };
    inline for (0..2) |i| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = i });
        defer row.deinit();
        propName(labels[i]);
        const cur: *u32 = if (array_tool.polar) (if (i == 0) &array_tool.around else &array_tool.rings) else (if (i == 0) &array_tool.cols else &array_tool.rows);
        if (accepted.numberField(@src(), f64, @floatFromInt(cur.*), 1, 999, .{ .id_extra = i, .expand = .horizontal })) |v| cur.* = @intFromFloat(@round(v));
    }
    if (array_tool.polar) {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3 });
        defer row.deinit();
        propName("Sweep, °");
        if (accepted.numberField(@src(), f64, array_tool.sweep, 1, 360, .{ .id_extra = 3, .expand = .horizontal })) |v| array_tool.sweep = v;
    }
    keyButton(@src(), "Apply", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
}

const track_names = [_][]const u8{ "Layout: column of rows", "Layout: row of columns", "Layout: single track" };

fn tracksMenu() void {
    for (track_names, 0..) |n, i| {
        const on = state.tool == .add_tracks and switch (i) {
            0 => tracks_tool.kind == .region and tracks_tool.major == .row,
            1 => tracks_tool.kind == .region and tracks_tool.major == .column,
            else => tracks_tool.kind == .track,
        };
        dropItem("ribbon.tracks", n, @intCast(i), on, i);
    }
}

/// The text style chosen in the Text style panel: new text rows (Add rows,
/// columns, a track) are set in it. Null: none chosen yet (the document's
/// first style shows as chosen, or the default Label while it has none).
var text_style: ?layout.model.StyleId = null;

/// The style the Text style panel shows as chosen.
fn chosenTextStyle() ?layout.model.StyleId {
    if (text_style) |s| if (state.model.styleIndex(s) != null) return s;
    if (state.model.styles.items.len > 0) return state.model.styles.items[0].id;
    return null;
}

/// The Text style panel: the document's text styles (the default Label
/// offered while it has none), Add a style, and beside them the chosen
/// style's settings. Choosing one sets new text rows in it.
fn stylesPanel() void {
    const saved_group = pushGroup("styles-palette");
    defer popGroup(saved_group);
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .padding = .{ .x = 8, .w = 8, .y = 4, .h = 6 } });
    defer row.deinit();
    const chosen = chosenTextStyle();
    {
        var left = dvui.box(@src(), .{ .dir = .vertical }, .{ .min_size_content = .{ .w = 300 }, .max_size_content = .width(300), .padding = .all(6) });
        defer left.deinit();
        dvui.labelNoFmt(@src(), "Text styles", .{}, .{ .font = dvui.Font.theme(.body).larger(-1), .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) }, .margin = .{ .x = 2, .h = 4 } });
        const styles = state.model.styles.items;
        const n = @max(styles.len, 1);
        for (0..n) |k| {
            const name = if (styles.len == 0) "Label (default)" else styles[k].name;
            const arg: i32 = if (styles.len == 0) -1 else @intCast(k);
            const on = if (styles.len == 0) true else chosen != null and styles[k].id == chosen.?;
            var r = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .background = true, .color_fill = .{ .color = if (on) dvui.themeGet().color(.highlight, .fill) else dvui.themeGet().color(.window, .fill) }, .corners = .all(3), .margin = .{ .y = 1, .h = 1 }, .id_extra = k });
            defer r.deinit();
            listItem("styles-palette", name);
            const base = next_element orelse "styles-palette";
            next_element = null;
            const tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.choose", .{base}) catch base);
            checkElement(tag, .button, name);
            recordDrawn(tag, arg);
            var bw: dvui.ButtonWidget = undefined;
            bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = k, .tag = tag, .padding = .{ .x = 6, .w = 4, .y = 4, .h = 5 }, .margin = .all(0), .background = false });
            bw.processEvents();
            dvui.labelNoFmt(@src(), name, .{}, .{ .padding = .all(0), .margin = .all(0) });
            if (bw.clicked()) pushButtonEvent(tag, arg);
            bw.deinit();
        }
        keyButton(@src(), "Add a style", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 }, .tag = uniqueTag("styles-palette.add-style") });
    }
    var right = dvui.box(@src(), .{ .dir = .vertical }, .{ .min_size_content = .{ .w = 380 }, .max_size_content = .width(380), .padding = .{ .x = 16, .y = 6 } });
    defer right.deinit();
    const sid = chosen orelse {
        dvui.labelNoFmt(@src(), "Label: made when chosen, or when text is first set", .{}, .{ .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) } });
        return;
    };
    const si = state.model.styleIndex(sid) orelse return;
    dvui.labelNoFmt(@src(), state.model.styles.items[si].name, .{}, .{ .font = dvui.Font.theme(.heading), .margin = .{ .h = 4 } });
    styleProperties(sid) catch {};
}

/// The Layers panel: the stack (as the palette), and beside it the chosen
/// layer's settings.
fn layersPanel() void {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .padding = .{ .x = 8, .w = 8, .y = 4, .h = 6 } });
    defer row.deinit();
    {
        var left = dvui.box(@src(), .{ .dir = .vertical }, .{ .min_size_content = .{ .w = 300 }, .max_size_content = .width(300) });
        defer left.deinit();
        layersPalette();
    }
    if (shown_space >= state.model.spaces.items.len) return;
    const sp = state.model.spaces.items[shown_space];
    var right = dvui.box(@src(), .{ .dir = .vertical }, .{ .min_size_content = .{ .w = 340 }, .max_size_content = .width(340), .padding = .{ .x = 16, .y = 6 } });
    defer right.deinit();
    if (chosen_view_layer) |v| {
        dvui.labelNoFmt(@src(), v.label(), .{}, .{ .font = dvui.Font.theme(.heading), .margin = .{ .h = 4 } });
        viewLayerProperties(shown_space, v);
        return;
    }
    const li = sp.layerIndex(newObjectLayer()) orelse return;
    dvui.labelNoFmt(@src(), sp.layers.items[li].name, .{}, .{ .font = dvui.Font.theme(.heading), .margin = .{ .h = 4 } });
    layerProperties(shown_space, li) catch {};
}

/// The view's own layer chosen in the Layers panel, its settings shown
/// beside the list; null: the document layer new objects go on.
var chosen_view_layer: ?ViewLayer = null;

/// A view layer's settings: what it is, shown or not, its place in the
/// stack, and the grid's look for the grid. The view's, kept for the
/// session, not saved with the document.
fn viewLayerProperties(space: usize, v: ViewLayer) void {
    const saved_group = pushGroup("view-layer");
    defer popGroup(saved_group);
    propText(asElement("view-layer.kind"), "{s}", .{"Drawn by the editor, in this canvas's or frame's stack"}, 1);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 2 });
        defer row.deinit();
        propName(asElement("view-layer.shown"));
        var on = v.shown();
        if (tcheckbox(@src(), &on, "Visible", .{ .id_extra = 2 })) v.toggle();
    }
    var ebuf: [64]StackEntry = undefined;
    const entries = stackEntries(space, &ebuf);
    const at = for (entries, 0..) |e, k| {
        if (e == .view and e.view == v) break k;
    } else 0;
    propText(asElement("view-layer.place"), "{d} of {d}, from the bottom", .{ at + 1, entries.len }, 3);
    if (v == .grid and space < state.model.spaces.items.len) {
        // Its spacing (the document's), in the document's units; empty:
        // adaptive.
        const u = docUnits();
        const spacing = state.model.spaces.items[space].grid_spacing;
        var sb: [32]u8 = undefined;
        const shown_text = if (spacing > 0) std.fmt.bufPrint(&sb, "{d}", .{@round(spacing * u.perMm() * 10000) / 10000}) catch "" else "";
        var lb: [32]u8 = undefined;
        const label = std.fmt.bufPrint(&lb, "Spacing, {s}", .{u.symbol()}) catch "Spacing";
        if (sizesProp(elementLabel("view-layer.spacing", label), shown_text, 5)) |list| {
            if (list.len == 0) {
                act(.setGridSpacing, .{ space, 0 }) catch {};
            } else if (list.len == 1 and list[0] > 0) act(.setGridSpacing, .{ space, list[0] / u.perMm() }) catch {};
        }
        propText(asElement("view-layer.spacing-note"), "{s}", .{if (spacing > 0) "lines at it, stronger every ten" else "empty: adaptive, following the zoom"}, 6);
        // How grids are drawn: a preference, every document alike.
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 4 });
        defer row.deinit();
        propName(asElement("view-layer.look"));
        const names = [_][]const u8{ "Lines", "Dots", "Pluses" };
        var choice: usize = switch (gridLook()) {
            .dots => 1,
            .pluses => 2,
            else => 0,
        };
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 4 })) {
            grid_mode = switch (choice) {
                1 => .dots,
                2 => .pluses,
                else => .lines,
            };
        }
    }
}

/// While the ribbon is drawn: its buttons carry key badges.
var in_ribbon = false;

/// The key that runs button `tag`'s action (in canvas mode, else
/// globally), short: Shift as ⇧. Null when it has no key.
fn badgeText(buf: *[48]u8, tag: []const u8, arg: i32) ?[]const u8 {
    const a = buttonActionId(tag) orelse return null;
    var kb: [48]u8 = undefined;
    // The canvas's keys, then the view's (0 zooms to the context); a
    // single key over a chorded one.
    const sc = keymap.shortcutPreferring(&kb, kmode("canvas"), a, arg, false) orelse keymap.shortcutPreferring(&kb, kmode("view"), a, arg, false) orelse return null;
    // Modifiers come as symbols already (⇧R).
    @memcpy(buf[0..sc.len], sc);
    return buf[0..sc.len];
}

fn badgeFont(held: bool) dvui.Font {
    return dvui.Font.theme(.body).withSize(if (held) 10 else 8.5);
}

/// Key text `text` as a small badge at the lower right of button `r`, in
/// the room left after it: faint, full strength while Alt is held.
fn keyBadge(r: dvui.Rect.Physical, text: []const u8) void {
    const s = dvui.windowNaturalScale();
    const held = dvui.currentWindow().modifiers.alt();
    const font = badgeFont(held);
    const size = font.textSize(text);
    const pad = 1.5 * s;
    const box: dvui.Rect.Physical = .{ .x = r.x + r.w - 3 * s, .y = r.y + r.h - size.h * s + 1 * s, .w = size.w * s + 2 * pad, .h = size.h * s };
    const prev_clip = dvui.clipGet();
    dvui.clipSet(dvui.windowRectPixels());
    defer dvui.clipSet(prev_clip);
    const ink = dvui.themeGet().color(.window, .text);
    box.fill(.all(2 * s), .{ .color = .{ .color = if (held) ghost_pane.oklch(0.28, 0.08, ghost_pane.pane_hue, 1) else colors.titlebar.lighten(-6) } });
    dvui.renderText(.{ .font = font, .text = text, .rs = .{ .r = box, .s = s }, .p = .{ .x = box.x + pad, .y = box.y }, .color = if (held) dvui.Color.white else ink.opacity(0.6) }) catch {};
}

/// The ribbon: under the menu bar, the window's width, the active view's
/// tools (a canvas view's today), each with its key.
fn ribbon() void {
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .min_size_content = .{ .h = ribbonH() }, .background = true, .color_fill = .{ .color = colors.titlebar }, .border = .{ .h = 1 }, .color_border = .{ .color = colors.edge.opacity(0.4) }, .padding = .{ .x = 6, .w = 6 } });
    defer bar.deinit();
    {
        const br = bar.data().borderRectScale();
        ribbon_bottom = (br.r.y + br.r.h) / dvui.windowNaturalScale();
        // A right-click anywhere on it: the key sizes.
        for (dvui.events()) |*e| {
            if (e.evt != .mouse or e.handled) continue;
            const me = e.evt.mouse;
            if (me.action != .press or me.button != .right or !br.r.contains(me.p)) continue;
            e.handle(@src(), bar.data());
            const ns = dvui.windowNaturalScale();
            ribbon_size_from = .{ .x = me.p.x / ns, .y = me.p.y / ns, .w = 1, .h = 1 };
            ribbon_size_menu = true;
            ribbon_size_frame = dvui.frameTimeNS();
            dvui.refresh(null, @src(), null);
        }
    }
    defer if (ribbon_size_menu and ribbon_size_frame != dvui.frameTimeNS()) ribbonSizeMenu();
    defer if (constrain_menu != null and constrain_menu_frame != dvui.frameTimeNS()) constrainMenu();
    defer if (constrain_objects_menu and constrain_menu_frame != dvui.frameTimeNS()) objectsMenu();
    in_ribbon = true;
    defer in_ribbon = false;
    switch (activeKind()) {
        .sheet => return sheetRibbon(),
        .manufacture => return planRibbon(),
        .canvas => {},
    }
    toolPalette();
    // The palettes, as drop panels.
    if (state.model.spaces.items.len > 0) {
        _ = dvui.separator(@src(), .{ .expand = .vertical, .margin = .{ .x = 6, .w = 6, .y = 4, .h = 4 } });
        var lwd: dvui.WidgetData = undefined;
        const r = keyIconData(@src(), "Layers", icons.graven(.layers) orelse dvui.entypo.layers, &lwd, "ribbon.layers");
        drop_anchor.set(.layers, r.toNatural());
        dvui.tooltip(@src(), .{ .active_rect = r }, "Layers: show or hide each, drag to reorder the stack, the chosen layer's settings (L; held, or clicked)", .{}, .{});
    }
    {
        var swd: dvui.WidgetData = undefined;
        const r = keyIconData(@src(), "Text style", icons.graven(.text_style) orelse dvui.entypo.text, &swd, "ribbon.styles");
        drop_anchor.set(.styles, r.toNatural());
        dvui.tooltip(@src(), .{ .active_rect = r }, "Text style: the one new text and text rows are set in, and its settings (Y)", .{}, .{});
    }
}

/// While a drop panel is open: the key that opened it carried on down
/// across the gap the panel is inset by, its shading (as the key's foot
/// shows it, in the key's fade) running into the panel's `colour`, and
/// flaring into the panel with concave fillets at the sides, so the key and
/// its panel read as one (a folder tab's join; the owner, 2026-11-22).
fn dropBridge(key: dvui.Rect.Physical, colour: dvui.Color) void {
    const s = dvui.windowNaturalScale();
    // The key's foot: its lower shade tinted as an open key is, under the
    // fade's ink at its strength there.
    const base = display.fix(dvui.Color{ .r = 0xe6, .g = 0xe4, .b = 0xdf });
    const tinted = mix(base, colour, 0.3);
    const fade_ink = ghost_pane.oklch(0.26, 0.07, ghost_pane.pane_hue, 1);
    const held = dvui.currentWindow().modifiers.alt();
    const foot = mix(tinted, fade_ink, if (held) 0.92 else 0.55);
    const x0 = key.x + 1 * s;
    const x1 = key.x + key.w - 1 * s;
    const top = key.y + key.h - 1 * s;
    // Across the panel's 2 logical inset below the ribbon, a hair into it.
    const bottom = ribbon_bottom * s + 2.5 * s;
    if (bottom <= top) return;
    const f = @max(1, @min(4 * s, bottom - top));
    const at = struct {
        fn c(y: f32, y0: f32, y1: f32, c0: dvui.Color, c1: dvui.Color) dvui.Color.PMA {
            const t = std.math.clamp((y - y0) / @max(y1 - y0, 1e-3), 0, 1);
            return .fromColor(mix(c0, c1, t));
        }
    }.c;
    const lifo = dvui.currentWindow().lifo();
    const n_arc = 8;
    var b = dvui.Triangles.Builder.init(lifo, 4 + 2 * (n_arc + 2), 6 + 2 * 3 * n_arc) catch return;
    defer b.deinit(lifo);
    // The stem: the key's foot down to the panel's colour.
    const p = [4]dvui.Point.Physical{ .{ .x = x0, .y = top }, .{ .x = x1, .y = top }, .{ .x = x1, .y = bottom }, .{ .x = x0, .y = bottom } };
    for (p) |q| b.appendVertex(.{ .pos = q, .col = at(q.y, top, bottom, foot, colour) });
    b.appendTriangles(&ccw(p[0], p[1], p[2], 0, 1, 2));
    b.appendTriangles(&ccw(p[0], p[2], p[3], 0, 2, 3));
    // Each fillet: a fan from the stem's foot corner over a quarter arc
    // centred out and up from it, coloured as the stem is at each height.
    var vi: dvui.Vertex.Index = 4;
    for ([_]f32{ -1, 1 }) |side| {
        const corner: dvui.Point.Physical = .{ .x = if (side < 0) x0 else x1, .y = bottom };
        const c: dvui.Point.Physical = .{ .x = corner.x + side * f, .y = bottom - f };
        const first = vi;
        b.appendVertex(.{ .pos = corner, .col = at(corner.y, top, bottom, foot, colour) });
        vi += 1;
        var arc: [n_arc + 1]dvui.Point.Physical = undefined;
        for (0..n_arc + 1) |i| {
            const t = @as(f32, @floatFromInt(i)) / n_arc * (std.math.pi / 2.0);
            arc[i] = .{ .x = c.x - side * f * @cos(t), .y = c.y + f * @sin(t) };
            b.appendVertex(.{ .pos = arc[i], .col = at(arc[i].y, top, bottom, foot, colour) });
            vi += 1;
        }
        for (0..n_arc) |i| {
            const k: dvui.Vertex.Index = @intCast(i);
            b.appendTriangles(&ccw(corner, arc[i], arc[i + 1], first, first + 1 + k, first + 2 + k));
        }
    }
    // Past the ribbon's own clip, down to the panel.
    const prev_clip = dvui.clipGet();
    dvui.clipSet(dvui.windowRectPixels());
    defer dvui.clipSet(prev_clip);
    dvui.renderTriangles(b.build_unowned(), null) catch {};
}

/// Colour `a` moved `t` (0..1) of the way to `b`, alpha too.
fn mix(a: dvui.Color, b: dvui.Color, t: f32) dvui.Color {
    const m = struct {
        fn f(x: u8, y: u8, tt: f32) u8 {
            return @intFromFloat(@round(@as(f32, @floatFromInt(x)) * (1 - tt) + @as(f32, @floatFromInt(y)) * tt));
        }
    }.f;
    return .{ .r = m(a.r, b.r, t), .g = m(a.g, b.g, t), .b = m(a.b, b.b, t), .a = m(a.a, b.a, t) };
}

/// A ribbon button for action `id` (a registry button), its tooltip the
/// registry's label.
fn ribbonButton(src: std.builtin.SourceLocation, comptime id: []const u8, tvg: []const u8, id_extra: usize) void {
    const e = comptime elements.get(id);
    var wd: dvui.WidgetData = undefined;
    keyIcon(src, e.label, tvg, 0, .{ .data_out = &wd, .tag = uniqueTag(id), .id_extra = id_extra });
    dvui.tooltip(src, .{ .active_rect = wd.borderRectScale().r }, "{s}", .{e.label}, .{ .id_extra = id_extra });
}

fn ribbonGap(id_extra: usize) void {
    _ = dvui.separator(@src(), .{ .expand = .vertical, .margin = .{ .x = 6, .w = 6, .y = 4, .h = 4 }, .id_extra = id_extra });
}

/// A legend sheet view's ribbon: its rows, its keys' names, and the canvas
/// beside it. (No single keys: letters type into the cells.)
fn sheetRibbon() void {
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .padding = .{ .x = 2, .w = 2, .y = 3, .h = 3 }, .gravity_y = 0.5 });
    defer bar.deinit();
    ribbonButton(@src(), "sheet.cell.add-a-row", dvui.entypo.add_to_list, 1);
    ribbonButton(@src(), "sheet.cell.remove-this-row", dvui.entypo.circle_with_minus, 2);
    ribbonGap(3);
    ribbonButton(@src(), "sheet.cell.name-tiles-by-grid-position-r1c1", dvui.entypo.grid, 4);
    ribbonButton(@src(), "sheet.cell.name-tiles-by-their-first-legend", dvui.entypo.text, 5);
    ribbonGap(6);
    // The canvas beside it, to see its keys change.
    const prev = state.context;
    defer state.context = prev;
    state.context = .{ .sheet = sheet_sel.sheet };
    ribbonButton(@src(), "sheet.open-it-beside-the-canvas", dvui.entypo.browser, 7);
}

/// A manufacturing view's ribbon: its plan's operations, checks and export.
/// The buttons act on the view's plan (pressed with it as the context).
fn planRibbon() void {
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .padding = .{ .x = 2, .w = 2, .y = 3, .h = 3 }, .gravity_y = 0.5 });
    defer bar.deinit();
    const prev = state.context;
    defer state.context = prev;
    state.context = .{ .plan = @enumFromInt(vl.views[vl.active].target) };
    ribbonButton(@src(), "plan.add-an-operation", dvui.entypo.add_to_list, 1);
    ribbonGap(2);
    ribbonButton(@src(), "plan.checks.check-this-plan", dvui.entypo.check, 3);
    ribbonButton(@src(), "plan.checks.clear-results", dvui.entypo.erase, 4);
    ribbonGap(5);
    ribbonButton(@src(), "plan.export-this-plan-make-it-active", dvui.entypo.text_document, 6);
}

/// A ribbon icon button tagged `id` (its badge after it); its rect.
fn keyIconData(src: std.builtin.SourceLocation, name: []const u8, tvg: []const u8, wd: *dvui.WidgetData, comptime id: []const u8) dvui.Rect.Physical {
    _ = comptime elements.get(id);
    // Open: tinted with its panel's colour, which the bridge carries down.
    const open = if (drop_open) |d| std.mem.eql(u8, d.id(), id) else false;
    keyIcon(src, name, tvg, 0, .{ .data_out = wd, .tag = uniqueTag(id), .color_fill = if (open) .{ .color = ghost_pane.darkTheme(dvui.themeGet()).color(.window, .fill).opacity(0.3) } else null });
    return wd.borderRectScale().r;
}

/// The ribbon's height, logical: its keys' and no more (the owner,
/// 2026-11-22: no margin above and below them).
fn ribbonH() f32 {
    return ribbonPitch();
}
/// Where the ribbon ends, logical (window coordinates): drop panels hang
/// from it.
var ribbon_bottom: f32 = 64;

/// A button's effect, by its action (elements.zig: the button's id),
/// working on the context it was pressed in and its argument.
const ButtonHandler = struct { action: keymap.ActionId, run: *const fn (arg: i32) void };

fn handler(comptime name: []const u8, f: *const fn (arg: i32) void) ButtonHandler {
    return .{ .action = comptime kact(name), .run = f };
}

/// The buttons' effects (an unknown action fails the build).
const button_handlers = [_]ButtonHandler{
    // The windows' tabs: an argument is a view's index + 1 (0: the active
    // view), meaning that view's window.
    handler("views.add", struct {
        fn f(arg: i32) void {
            const v: u8 = if (arg > 0) @intCast((arg & 0xff) - 1) else vl.active;
            const leaf = vl.leafOf(v) orelse return;
            tab_add_leaf = leaf;
            tab_add_new = true;
            tab_add_filter = @splat(0);
        }
    }.f),
    handler("views.divider", struct {
        fn f(arg: i32) void {
            openDividerMenu(argSplit(arg));
        }
    }.f),
    handler("views.swap", struct {
        fn f(arg: i32) void {
            divider_menu = null;
            vl.swap(argSplit(arg) orelse return);
        }
    }.f),
    handler("views.even-out", struct {
        fn f(arg: i32) void {
            divider_menu = null;
            vl.evenOut(argSplit(arg) orelse return);
        }
    }.f),
    handler("views.turn", struct {
        fn f(arg: i32) void {
            divider_menu = null;
            vl.turn(argSplit(arg) orelse return);
        }
    }.f),
    handler("views.tabs.*", struct {
        fn f(arg: i32) void {
            tab_add_leaf = null;
            if (arg < 0 or arg >= docviews.max_views) return;
            const v: u8 = @intCast(arg);
            if (vl.open[v]) activateView(v);
        }
    }.f),
    handler("views.page-prev", struct {
        fn f(arg: i32) void {
            flipPage(if (arg > 1) @intCast(arg - 1) else vl.active, false, arg == 1);
        }
    }.f),
    handler("views.page-next", struct {
        fn f(arg: i32) void {
            flipPage(if (arg > 1) @intCast(arg - 1) else vl.active, true, arg == 1);
        }
    }.f),
    handler("views.contexts.*", struct {
        fn f(arg: i32) void {
            const leaf = tab_add_leaf orelse vl.leafOf(vl.active) orelse return;
            tab_add_leaf = null;
            var buf: [128]ViewContext = undefined;
            const all = viewContexts(&buf);
            if (arg < 0 or arg >= all.len) return;
            addToWindow(leaf, all[@intCast(arg)]);
        }
    }.f),
    handler("views.close", struct {
        fn f(arg: i32) void {
            const v: u8 = if (arg > 0) @intCast(arg - 1) else vl.active;
            if (v < docviews.max_views and vl.open[v]) closeView(v);
        }
    }.f),
    handler("views.split-across", struct {
        fn f(arg: i32) void {
            if (canvas_prompt) return;
            if (arg & 0xff > 0) {
                const v: u8 = @intCast((arg & 0xff) - 1);
                if (v < docviews.max_views and vl.open[v] and v != vl.active) activateView(v);
            }
            splitView(if (arg & 0x100 != 0) .down else .across);
        }
    }.f),
    // The tools.
    // The ribbon's Zoom to context: the view action its key (0) runs.
    handler("view.zoom-fit", struct {
        fn f(_: i32) void {
            zoomToContext();
        }
    }.f),
    handler("tool.constrain", struct {
        fn f(_: i32) void {
            state.drag = null;
            constrain_first = null;
            // A construction line chosen: the tool is applied to it, its
            // constraints offered (the owner, 2026-11-23).
            if (state.tool != .constrain) if (state.context == .guide) {
                openConstrainMenu(state.context.guide.space, state.context.guide.index);
                return;
            };
            // Objects chosen: their constraints offered (W, H, G, T, B, L, R).
            if (state.tool != .constrain) if (openObjectsMenu()) return;
            constrain_batch = null;
            constrain_measure = false;
            state.tool = if (state.tool == .constrain) .select else .constrain;
        }
    }.f),
    handler("constrain-menu.horizontal", struct {
        fn f(_: i32) void {
            holdGuide(.horizontal);
        }
    }.f),
    handler("constrain-menu.vertical", struct {
        fn f(_: i32) void {
            holdGuide(.vertical);
        }
    }.f),
    handler("constrain-menu.distance", struct {
        fn f(_: i32) void {
            const cm = constrain_menu orelse return;
            closeConstrainMenu();
            const hit = guideFeature(cm.space, cm.index) orelse {
                state.status = "A distance needs the line horizontal or vertical first (H or V). ";
                return;
            };
            state.tool = .constrain;
            constrain_first = hit;
            state.status = "Distance: click what the line keeps to. ";
        }
    }.f),
    handler("constrain-menu.close", struct {
        fn f(_: i32) void {
            closeConstrainMenu();
        }
    }.f),
    handler("constrain-objects.equal-width", struct {
        fn f(_: i32) void {
            equalSizes(false);
        }
    }.f),
    handler("constrain-objects.equal-height", struct {
        fn f(_: i32) void {
            equalSizes(true);
        }
    }.f),
    handler("constrain-objects.gap", struct {
        fn f(_: i32) void {
            gapsPrompt();
        }
    }.f),
    handler("constrain-objects.top", struct {
        fn f(_: i32) void {
            edgesPick(.top);
        }
    }.f),
    handler("constrain-objects.bottom", struct {
        fn f(_: i32) void {
            edgesPick(.bottom);
        }
    }.f),
    handler("constrain-objects.left", struct {
        fn f(_: i32) void {
            edgesPick(.left);
        }
    }.f),
    handler("constrain-objects.right", struct {
        fn f(_: i32) void {
            edgesPick(.right);
        }
    }.f),
    handler("constrain-objects.measure", struct {
        fn f(_: i32) void {
            closeObjectsMenu();
            constrain_batch = null;
            state.tool = .constrain;
            constrain_first = null;
            constrain_measure = true;
            state.status = "Measure: pick a feature, then another. The dimension follows them and moves nothing. ";
        }
    }.f),
    handler("constraint.driving-or-reference", struct {
        fn f(_: i32) void {
            const id = picked_constraint orelse return;
            toggleDriving(id);
        }
    }.f),
    handler("constrain-objects.close", struct {
        fn f(_: i32) void {
            closeObjectsMenu();
            constrain_batch = null;
        }
    }.f),
    handler("tool.add-prototype", struct {
        fn f(_: i32) void {
            addPrototype() catch {
                state.status = "The prototype was not added. ";
            };
        }
    }.f),
    handler("tool.duplicate-prototype", struct {
        fn f(_: i32) void {
            const id = switch (state.context) {
                .prototype => |id| id,
                else => return,
            };
            duplicatePrototype(id) catch {
                state.status = "The prototype was not duplicated. ";
            };
        }
    }.f),
    handler("tool.delete-prototype", struct {
        fn f(_: i32) void {
            const id = switch (state.context) {
                .prototype => |id| id,
                else => return,
            };
            if (act(.removePrototype, .{id})) {
                state.context = .prototypes;
            } else |err| state.status = if (err == error.PrototypeInUse) "Tiles are still made from this prototype: switch them first. " else "The prototype was not deleted. ";
        }
    }.f),
    handler("tool.new-sketch", struct {
        fn f(_: i32) void {
            state.drag = null;
            state.tool = if (state.tool == .new_sketch) .select else .new_sketch;
        }
    }.f),
    handler("tool.add-shape", struct {
        fn f(_: i32) void {
            if (!inDrawingContainer() and state.tool != .add_art) {
                state.status = "Shapes are drawn inside a panel: choose one first (nothing is drawn directly on the canvas). ";
                return;
            }
            state.drag = null;
            state.tool = if (state.tool == .add_art) .select else .add_art;
        }
    }.f),
    handler("tool.layout-column-of-rows", struct {
        fn f(_: i32) void {
            tracksMode(.row, .region);
        }
    }.f),
    handler("tool.layout-row-of-columns", struct {
        fn f(_: i32) void {
            tracksMode(.column, .region);
        }
    }.f),
    handler("tool.layout-single-track", struct {
        fn f(_: i32) void {
            tracksMode(.row, .track);
        }
    }.f),
    handler("tool.fit-to-tiles", struct {
        fn f(_: i32) void {
            const r = switch (state.context) {
                .region => |r| r,
                else => return,
            };
            state.status = if (fitRegion(r.parent, r.region)) "" else "The tracks already fit their content (or hold none). ";
        }
    }.f),
    handler("tool.construction-line", struct {
        fn f(_: i32) void {
            state.drag = null;
            guide_start = null;
            guide_pending = false;
            state.tool = if (state.tool == .construction) .select else .construction;
        }
    }.f),
    handler("guide.remove", struct {
        fn f(_: i32) void {
            switch (state.context) {
                .guide => |g| {
                    act(.removeGuide, .{ g.space, g.index }) catch return;
                    state.context = workspaceContext();
                },
                else => {},
            }
        }
    }.f),
    handler("tool.select-boundaries", struct {
        fn f(_: i32) void {
            if (canvas_eq != null) leaveCanvasEquation();
            boundary_mode = !boundary_mode;
            state.status = if (boundary_mode) "Select boundaries on: the nearest boundary is highlighted; a click selects its container (B turns it off). " else "Select boundaries off. ";
        }
    }.f),
    handler("tool.select-area", struct {
        fn f(_: i32) void {
            state.drag = null;
            state.tool = if (state.tool == .select_area) .select else .select_area;
        }
    }.f),
    // A panel's fabrication: its layers moved, removed, added.
    handler("panel.fab.layer.*.later", struct {
        fn f(arg: i32) void {
            fabEdit(struct {
                fn e(l: *std.ArrayList(layout.model.FabLayer), _: usize, a: i32) bool {
                    const i: usize = @intCast(a);
                    if (i + 1 >= l.items.len) return false;
                    std.mem.swap(layout.model.FabLayer, &l.items[i], &l.items[i + 1]);
                    return true;
                }
            }.e, arg);
        }
    }.f),
    handler("panel.fab.layer.*.earlier", struct {
        fn f(arg: i32) void {
            fabEdit(struct {
                fn e(l: *std.ArrayList(layout.model.FabLayer), _: usize, a: i32) bool {
                    const i: usize = @intCast(a);
                    if (i == 0 or i >= l.items.len) return false;
                    std.mem.swap(layout.model.FabLayer, &l.items[i], &l.items[i - 1]);
                    return true;
                }
            }.e, arg);
        }
    }.f),
    handler("panel.fab.layer.*.remove-layer", struct {
        fn f(arg: i32) void {
            fabEdit(struct {
                fn e(l: *std.ArrayList(layout.model.FabLayer), _: usize, a: i32) bool {
                    const i: usize = @intCast(a);
                    if (i >= l.items.len) return false;
                    _ = l.orderedRemove(i);
                    return true;
                }
            }.e, arg);
        }
    }.f),
    handler("panel.fab.add-layer", struct {
        fn f(arg: i32) void {
            fabEdit(struct {
                fn e(l: *std.ArrayList(layout.model.FabLayer), pi: usize, _: i32) bool {
                    const ar = dvui.currentWindow().arena();
                    var nb: [32]u8 = undefined;
                    // The first: the base itself, solid from the bottom up.
                    // After it: every label inlaid, 0.6 mm from the top down.
                    const layer: layout.model.FabLayer = if (l.items.len == 0)
                        .{ .name = "Base", .source = .edge, .surface = .base_bottom, .dir = .up, .depth = state.model.panels.items[pi].fab.thickness, .op = .{ .add = .{ .name = "black", .color = .hex("#1e1e1e") } } }
                    else
                        .{ .name = ar.dupe(u8, state.model.freshName(&nb, .{ .fab = pi }, "Layer")) catch return false, .source = .{ .text = "" }, .surface = .base_top, .dir = .down, .depth = 0.6, .op = .{ .inlay = .{ .name = "white", .color = .hex("#f2f2f2") } } };
                    l.append(ar, layer) catch return false;
                    return true;
                }
            }.e, arg);
        }
    }.f),
    // A panel's grids.
    handler("panel.grids.*", struct {
        fn f(arg: i32) void {
            const pi = contextPanel() orelse return;
            state.context = .{ .grid = .{ .parent = .{ .panel = pi }, .index = @intCast(arg) } };
        }
    }.f),
    handler("panel.grids.add-grid", struct {
        fn f(_: i32) void {
            const pi = contextPanel() orelse return;
            const panel = state.model.panels.items[pi];
            // Points 13 mm apart filling the ink area, from its top-left.
            const step: f64 = 13.0;
            const inner_w = panel.w - panel.margins.left - panel.margins.right;
            const inner_h = panel.h - panel.margins.top - panel.margins.bottom;
            const cols: u32 = @intFromFloat(@max(1, @floor(inner_w / step)));
            const rows: u32 = @intFromFloat(@max(1, @floor(inner_h / step)));
            const origin: geom.Point = .{ .x = panel.margins.left + step / 2, .y = panel.h - panel.margins.top - step / 2 };
            const gi = act(.addGrid, .{ Parent{ .panel = pi }, origin, layout.model.GridShape{ .cols = cols, .rows = rows, .pitch_x = step, .pitch_y = step } }) catch {
                state.status = "The grid could not be added. ";
                return;
            };
            state.context = .{ .grid = .{ .parent = .{ .panel = pi }, .index = gi } };
        }
    }.f),
    // A grid.
    handler("grid.make-a-legend-sheet", struct {
        fn f(_: i32) void {
            const g = contextGrid() orelse return;
            var nb: [96]u8 = undefined;
            const name = state.model.freshName(&nb, .sheets, "Legends");
            if (act(.makeSheet, .{ name, state.model.gridsIn(g.parent)[g.index].id })) |id| {
                state.context = .{ .sheet = id };
                // Beside the canvas, to see its edits.
                openBeside(.{ .kind = .sheet, .target = @intFromEnum(id) });
                state.status = "Sheet made, open beside the canvas: the keys' legends now come from it. ";
            } else |_| state.status = "The sheet was not made. ";
        }
    }.f),
    handler("grid.show-the-grid-it-follows", struct {
        fn f(_: i32) void {
            const g = contextGrid() orelse return;
            const link = state.model.gridsIn(g.parent)[g.index].link;
            if (state.model.findGrid(link)) |src| state.context = .{ .grid = .{ .parent = src.parent, .index = src.index } };
        }
    }.f),
    handler("grid.stamp.*.fill-empty-points", struct {
        fn f(arg: i32) void {
            const g = contextGrid() orelse return;
            const made = act(.fillGrid, .{ g.parent, g.index, @as(usize, @intCast(arg)) }) catch 0;
            var buf: [64]u8 = undefined;
            state.status = dvui.currentWindow().arena().dupe(u8, std.fmt.bufPrint(&buf, "{d} placed. ", .{made}) catch "") catch "";
        }
    }.f),
    handler("grid.stamp.*.remove-stamp", struct {
        fn f(arg: i32) void {
            const g = contextGrid() orelse return;
            act(.removeStamp, .{ g.parent, g.index, @as(usize, @intCast(arg)) }) catch {};
        }
    }.f),
    handler("grid.add-stamp.parts", struct {
        fn f(_: i32) void {
            addStampKind("Parts", .part, 0.75, 0.75, 0);
        }
    }.f),
    handler("grid.add-stamp.holes", struct {
        fn f(_: i32) void {
            addStampKind("Holes", .hole, 0.85, 0.85, 0);
        }
    }.f),
    handler("grid.add-stamp.legends", struct {
        fn f(_: i32) void {
            addStampKind("Legends", .legend, 0.8, 0.25, 0.6);
        }
    }.f),
    handler("grid.remove-grid", struct {
        fn f(_: i32) void {
            const g = contextGrid() orelse return;
            act(.removeGrid, .{ g.parent, g.index }) catch return;
            state.context = parentContext(g.parent);
        }
    }.f),
    // A tile on a grid.
    handler("instance.grid", struct {
        fn f(_: i32) void {
            const at = contextInstance() orelse return;
            state.context = .{ .grid = .{ .parent = at.parent, .index = at.grid } };
        }
    }.f),
    handler("instance.bind-to-the-nearest-point", struct {
        fn f(_: i32) void {
            const at = contextInstance() orelse return;
            const inst = state.model.gridsIn(at.parent)[at.grid].instances.items[at.index];
            const c = inst.loose orelse return;
            const sh = state.model.gridShape(at.parent, at.grid);
            const o = state.model.gridPoint(at.parent, at.grid, 0, 0);
            const col = @min(@as(f64, @floatFromInt(sh.cols - inst.cols)), @max(0, @round((c.x - o.x) / sh.stepX())));
            const row = @min(@as(f64, @floatFromInt(sh.rows - inst.rows)), @max(0, @round((o.y - c.y) / sh.stepY())));
            act(.bindInstance, .{ at.parent, at.grid, at.index, @as(u32, @intFromFloat(col)), @as(u32, @intFromFloat(row)) }) catch {
                state.status = "It does not fit on the grid. ";
            };
        }
    }.f),
    handler("instance.remove-from-the-grid", struct {
        fn f(_: i32) void {
            const at = contextInstance() orelse return;
            act(.removeInstance, .{ at.parent, at.grid, at.index }) catch return;
            state.context = .{ .grid = .{ .parent = at.parent, .index = at.grid } };
        }
    }.f),
    // Panel editing.
    handler("panel.editing.grid-settings", struct {
        fn f(_: i32) void {
            const p = panel_edit orelse return;
            state.context = .{ .grid = .{ .parent = .{ .panel = p.panel }, .index = p.grid } };
        }
    }.f),
    handler("panel.editing.leave-panel-editing", struct {
        fn f(_: i32) void {
            leavePanelEdit();
        }
    }.f),
    // The selection.
    handler("selection.group", struct {
        fn f(_: i32) void {
            groupSelection();
        }
    }.f),
    handler("selection.move-to-a-new-frame", struct {
        fn f(_: i32) void {
            transferSelection(null, false);
        }
    }.f),
    handler("selection.copy-to-a-new-frame", struct {
        fn f(_: i32) void {
            transferSelection(null, true);
        }
    }.f),
    handler("selection.*", struct {
        fn f(arg: i32) void {
            transferSelection(@intCast(arg), false);
        }
    }.f),
    // A plan and its operations.
    handler("plan.export-this-plan-make-it-active", struct {
        fn f(_: i32) void {
            const c = contextPlan() orelse return;
            act(.setActivePlan, .{c.id}) catch {};
        }
    }.f),
    handler("plan.add-an-operation", struct {
        fn f(_: i32) void {
            var c = contextPlan() orelse return;
            const ar = dvui.currentWindow().arena();
            var ops: std.ArrayList(manufacture.Operation) = .empty;
            ops.appendSlice(ar, c.plan.operations) catch return;
            var ob: [32]u8 = undefined;
            const op_name = ar.dupe(u8, state.model.freshName(&ob, .{ .plan = c.id }, "Operation")) catch return;
            ops.append(ar, .{ .name = op_name, .process = .none }) catch return;
            c.plan.operations = ops.items;
            act(.setPlan, .{ c.id, c.plan }) catch {};
        }
    }.f),
    handler("plan.remove-this-plan", struct {
        fn f(_: i32) void {
            const c = contextPlan() orelse return;
            act(.removePlan, .{c.id}) catch {};
            state.context = .plans;
        }
    }.f),
    handler("plan.operation.*.earlier", struct {
        fn f(arg: i32) void {
            moveOperation(@intCast(arg), false);
        }
    }.f),
    handler("plan.operation.*.later", struct {
        fn f(arg: i32) void {
            moveOperation(@intCast(arg), true);
        }
    }.f),
    handler("plan.operation.*.remove", struct {
        fn f(arg: i32) void {
            var c = contextPlan() orelse return;
            const k: usize = @intCast(arg);
            if (k >= c.plan.operations.len) return;
            const ar = dvui.currentWindow().arena();
            var ops: std.ArrayList(manufacture.Operation) = .empty;
            ops.appendSlice(ar, c.plan.operations[0..k]) catch return;
            ops.appendSlice(ar, c.plan.operations[k + 1 ..]) catch return;
            c.plan.operations = ops.items;
            act(.setPlan, .{ c.id, c.plan }) catch {};
        }
    }.f),
