    handler("tool.add-array", struct {
        fn f(_: i32) void {
            // On: off. Off: its drop, to choose the counts and Apply.
            if (state.tool == .add_array) {
                state.tool = .select;
                state.drag = null;
                return;
            }
            openDrop(.array);
