    handler("array.apply", struct {
        fn f(_: i32) void {
            drop_open = null;
            if (!(state.context == .space or state.context == .panel)) {
                state.status = "An array goes on a canvas, a frame or a panel: choose one first. ";
                return;
            }
            state.drag = null;
            state.tool = .add_array;
            focusCanvas();
        }
