    handler("ribbon.drop.tracks", struct {
        fn f(_: i32) void {
            openDrop(.tracks);
        }
    }.f),
    handler("ribbon.shape.*", struct {
        fn f(arg: i32) void {
            if (arg < 0 or arg >= shape_names.len) return;
            drop_open = null;
            if (!inDrawingContainer()) {
                state.status = "Shapes are drawn inside a panel: choose one first (nothing is drawn directly on the canvas). ";
                return;
            }
            shape_kind = @enumFromInt(arg);
            polygon_pts.clearRetainingCapacity();
            state.drag = null;
            state.tool = .add_art;
            drop_open = null;
        }
    }.f),
    handler("ribbon.tracks.*", struct {
        fn f(arg: i32) void {
            drop_open = null;
            switch (arg) {
                0 => tracksMode(.row, .region),
                1 => tracksMode(.column, .region),
                2 => tracksMode(.row, .track),
                else => {},
            }
        }
    }.f),
    handler("layers-palette.*.shown", struct {
        fn f(arg: i32) void {
            // The view's own: -1 - its number.
            if (arg < 0) {
                const k: usize = @intCast(-1 - arg);
                if (k < std.enums.values(ViewLayer).len) std.enums.values(ViewLayer)[k].toggle();
                return;
            }
            if (shown_space >= state.model.spaces.items.len) return;
            const li: usize = @intCast(arg);
            const list = state.model.spaces.items[shown_space].layers.items;
            if (li >= list.len) return;
            var l = list[li];
            l.visible = !l.visible;
            act(.setLayer, .{ shown_space, li, l }) catch {};
        }
    }.f),
    handler("layers-palette.*.choose", struct {
        fn f(arg: i32) void {
            // The view's own (-1 - its number): its settings shown; new
            // objects still go on the document layer chosen before.
            if (arg < 0) {
                const k: usize = @intCast(-1 - arg);
                if (k < std.enums.values(ViewLayer).len) chosen_view_layer = std.enums.values(ViewLayer)[k];
                return;
            }
            chosen_view_layer = null;
            if (shown_space >= state.model.spaces.items.len) return;
            const li: usize = @intCast(arg);
            const list = state.model.spaces.items[shown_space].layers.items;
            if (li >= list.len) return;
            state.context = .{ .layer = .{ .space = shown_space, .index = li } };
            active_layer = list[li].id;
        }
    }.f),
    handler("layers-palette.add-layer", struct {
        fn f(_: i32) void {
            if (shown_space >= state.model.spaces.items.len) return;
            var buf: [32]u8 = undefined;
            const li = act(.addLayer, .{ shown_space, state.model.nextLayerName(shown_space, &buf) }) catch return;
            state.context = .{ .layer = .{ .space = shown_space, .index = li } };
            active_layer = state.model.spaces.items[shown_space].layers.items[li].id;
        }
    }.f),
    // A space's layers.
    handler("layers.*", struct {
