        fn f(_: i32) void {
            state.tool = if (state.tool == .add_panel) .select else .add_panel;
            state.drag = null;
        }
    }.f),
};

/// The context panel (a grid's or an instance's too), if any.
fn contextPanel() ?usize {
    return switch (state.context) {
        .panel => |pi| pi,
        .grid => |g| g.parent.panelIndex(),
        .region => |r| r.parent.panelIndex(),
        else => null,
    };
}

/// The context grid.
fn contextGrid() ?struct { parent: Parent, index: usize } {
    return switch (state.context) {
        .grid => |g| .{ .parent = g.parent, .index = g.index },
        else => null,
    };
}

/// The grid instance the context tile is.
fn contextInstance() ?struct { parent: Parent, grid: usize, index: usize } {
    return switch (state.context) {
        .tile => |id| if (state.model.gridInstanceOf(id)) |at| .{ .parent = at.parent, .grid = at.grid, .index = at.index } else null,
        else => null,
    };
}

/// The context panel's fabrication with its layers changed by `edit`, as
/// one step.
fn fabEdit(edit: *const fn (layers: *std.ArrayList(layout.model.FabLayer), pi: usize, arg: i32) bool, arg: i32) void {
    const pi = contextPanel() orelse return;
    const ar = dvui.currentWindow().arena();
    var next = state.model.panels.items[pi].fab;
    var layers: std.ArrayList(layout.model.FabLayer) = .empty;
    layers.appendSlice(ar, next.layers) catch return;
    if (!edit(&layers, pi, arg)) return;
    next.layers = layers.items;
    act(.setPanelFab, .{ pi, next }) catch {
        state.status = "That is not a size fabrication can use. ";
    };
}

/// A stamp of the context grid added: `kind` its name and role, sized in
/// grid steps.
fn addStampKind(name: []const u8, role: layout.model.GridRole, w: f64, h: f64, dy: f64) void {
    const g = contextGrid() orelse return;
    const sh = state.model.gridShape(g.parent, g.index);
    const proto_id = if (state.model.prototypes.items.len == 0) (act(.addPrototype, .{layout.model.TilePrototype{ .name = "Key", .tracks = &.{.{ .name = "top", .alignment = .centre }} }}) catch return) else state.model.prototypes.items[0].id;
    _ = act(.addStamp, .{ g.parent, g.index, layout.model.Stamp{ .name = name, .prototype = proto_id, .role = role, .w = sh.stepX() * w, .h = sh.stepY() * h, .offset = .{ .x = 0, .y = sh.stepY() * dy } } }) catch {
        state.status = "The stamp could not be added. ";
    };
}

/// The context plan's id and a copy of it to change.
fn contextPlan() ?struct { id: ObjectId, plan: manufacture.Plan } {
    const id = switch (state.context) {
        .plan => |id| id,
        else => return null,
    };
    const i = state.model.planIndex(id) orelse return null;
    return .{ .id = id, .plan = planCopy(state.model.plans.items[i]) };
}

/// An operation of the context plan moved by `by` (-1 earlier, +1 later).
fn moveOperation(k: usize, later: bool) void {
    const c = contextPlan() orelse return;
    const ops = @constCast(c.plan.operations);
    if (later and k + 1 >= ops.len) return;
    if (!later and (k == 0 or k >= ops.len)) return;
    std.mem.swap(manufacture.Operation, &ops[k], &ops[if (later) k + 1 else k - 1]);
    act(.setPlan, .{ c.id, c.plan }) catch {};
}

/// The context prototype's art redrawn as a keycap from its insets.
fn redrawPrototypeArt() void {
    const id = switch (state.context) {
        .prototype => |id| id,
        else => return,
    };
    const p = state.model.proto(id).*;
    const art = layout.art.redrawKeycap(dvui.currentWindow().arena(), p, protoUnit(p)) catch return;
    act(.setPrototypeArt, .{ id, art }) catch {};
}

/// The context layer moved up or down among its space's.
fn moveLayerOf(up: bool) void {
    const l = switch (state.context) {
        .layer => |l| l,
        else => return,
    };
    state.context = .{ .layer = .{ .space = l.space, .index = act(.moveLayer, .{ l.space, l.index, up }) catch l.index } };
}

/// The legend font stepped to the next or the one before.
fn stepFont(next: bool) void {
    if (state.fonts.len == 0) return;
    state.font_choice = if (next) (state.font_choice + 1) % state.fonts.len else (state.font_choice + state.fonts.len - 1) % state.fonts.len;
    state.font_set = true;
}

/// An object id as a button's argument, and back.
fn idArg(id: ObjectId) i32 {
    return @bitCast(@intFromEnum(id));
}

fn argId(arg: i32) ObjectId {
    return @enumFromInt(@as(u32, @bitCast(arg)));
}

/// The space whose layers the context shows: a frame's, else the canvas.
fn contextSpace() usize {
    return switch (state.context) {
        .panel => |pi| state.model.spaceOf(pi),
        else => 0,
    };
}

/// The parameter that turns the selected construction curve's output on
/// set from its field (Enter there, or its Set button).
fn skSetPhysicalWhen() void {
    const g = sk_pw_for orelse return;
    const name = std.mem.trim(u8, std.mem.sliceTo(&sk_pw_text, 0), " ");
    if (name.len > 0 and !skl.expr.validName(name)) {
        state.status = "Not a parameter name. ";
        return;
    }
    _ = skEdit(.{ .physical_when = .{ .g = g, .param = name } });
}

/// A sketch parameter set from its field, "name = expression" (Enter
/// there, or its Set button).
fn skSetParam() void {
    const line = std.mem.sliceTo(&sk_param_text, 0);
    const eq = std.mem.indexOfScalar(u8, line, '=') orelse {
        state.status = "Write a parameter as name = expression. ";
        return;
    };
    const name = std.mem.trim(u8, line[0..eq], " ");
    const text = std.mem.trim(u8, line[eq + 1 ..], " ");
    if (!skl.expr.validName(name)) {
        state.status = "A parameter's name is a letter or _, then letters, digits or _ (not a function's name). ";
        return;
    }
    _ = skEdit(.{ .param = .{ .name = name, .expr = text } });
    @memset(&sk_param_text, 0);
}

/// The context prototype.
fn contextPrototype() ?layout.model.PrototypeId {
    return switch (state.context) {
        .prototype => |id| id,
        else => null,
    };
}

/// The keyboard back to the canvas (after a palette button).
fn focusCanvas() void {
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
}

/// The palette's tile (or blank) `arg` inserted at the flow cursor.
fn paletteInsert(tile: bool, arg: i32) void {
    const c = track_cursor orelse return;
    const pal = paletteFor(c.parent, c.region) orelse return;
    const i: usize = @intCast(arg);
    const sizes: []const f64 = if (tile) pal.tiles[0..pal.tile_count] else &pal.blanks;
    if (i >= sizes.len) return;
    insertAtCursor(if (tile) .tile else .blank, sizes[i]);
    focusCanvas();
}

/// The Add rows, Add columns or Add track tool, on or off.
fn tracksMode(major: layout.model.Major, kind: layout.model.TileRegion.Kind) void {
    state.drag = null;
    const on = state.tool == .add_tracks and tracks_tool.kind == kind and (kind == .track or tracks_tool.major == major);
    if (on) {
        state.tool = .select;
    } else {
        state.tool = .add_tracks;
        tracks_tool.major = major;
        tracks_tool.kind = kind;
        // No keycap prototype made: tracks are of text unless a prototype
        // is chosen.
        validTracksSizeTo();
    }
}

/// A dialog's Confirm or Cancel button pressed (dialog.confirm,
/// dialog.cancel, as Enter and Esc ask): taken by the dialog drawn this
/// frame, as it takes those keys.
var dialog_answer: ?keymap.ActionId = null;

/// Whether the dialog's answer is `a` (taken once).
fn dialogAnswered(a: keymap.ActionId) bool {
    if (dialog_answer) |d| if (d == a) {
        dialog_answer = null;
        return true;
    };
    return false;
}

/// `dvui.buttonIcon`, tagged "icon/<name>" unless it has a tag.
fn tbuttonIcon(src: std.builtin.SourceLocation, name: []const u8, tvg: []const u8, init_opts: dvui.ButtonWidget.InitOptions, icon_opts: dvui.IconRenderOptions, opts: dvui.Options) bool {
    var o = opts;
    if (o.tag == null) {
        next_kind = .button;
        o.tag = if (elem_group.len > 0) tagFor(name) else uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "tool.{s}", .{lowerCamel(name)}) catch "tool");
    }
    return virtualKey(dvui.buttonIcon(src, name, tvg, init_opts, icon_opts, o), o.tag.?);
}

/// `dvui.menuItemLabel`, tagged "menu/<label>" (without its mark).
fn tmenu(src: std.builtin.SourceLocation, label: []const u8, init_opts: dvui.MenuItemWidget.InitOptions, opts: dvui.Options) ?dvui.Rect.Natural {
    var o = opts;
    if (o.tag == null) {
        var name = std.mem.trim(u8, label, " ");
        if (std.mem.startsWith(u8, name, "•")) name = std.mem.trim(u8, name["•".len..], " ");
        o.tag = uniqueTag(std.fmt.allocPrint(dvui.currentWindow().arena(), "menu.{s}", .{lowerCamel(name)}) catch "menu");
    }
    const r = dvui.menuItemLabel(src, label, init_opts, o);
    if (r == null and pressedByScript(o.tag)) return dvui.Rect.Natural{};
    return r;
}

/// A properties section's heading: its id is its text as an identifier
/// (see `headingAs` where the text varies).
fn heading(comptime fmt: []const u8, args: anytype, n: usize) void {
    dvui.label(@src(), fmt, args, .{ .font = .theme(.heading), .id_extra = n, .padding = .{ .y = 8, .h = 4 } });
    var buf: [160]u8 = undefined;
    setTagScopeText(std.fmt.bufPrint(&buf, fmt, args) catch "");
    // A heading names nothing: its elements are the function's group's.
    if (elem_group.len > 0) setGroup("{s}", .{base_group});
}

/// "<group>.<name as an id part>", for a section about a named thing.
fn scopeId(kind: []const u8, name: []const u8) []const u8 {
    return std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.{s}", .{ kind, kebab(name) }) catch kind;
}

/// "<kind>.<n>", for a numbered section.
fn scopeIdN(kind: []const u8, n: usize) []const u8 {
    return std.fmt.allocPrint(dvui.currentWindow().arena(), "{s}.{d}", .{ kind, n }) catch kind;
}

/// The section about one item of a loop (a slot, a layer) ends: elements
/// after it are the function's own again.
fn endSection() void {
    if (elem_group.len > 0) setGroup("{s}", .{base_group});
}

/// A section heading whose elements are in logical group `id`, whatever
/// its text says (`plan.operation.2`, `tile.slot.top`).
fn headingAs(id: []const u8, comptime fmt: []const u8, args: anytype, n: usize) void {
    dvui.label(@src(), fmt, args, .{ .font = .theme(.heading), .id_extra = n, .padding = .{ .y = 8, .h = 4 } });
    tag_scope = std.fmt.bufPrint(&tag_scope_buf, "{s}", .{id}) catch "";
    setGroup("{s}", .{id});
}

/// UI style rule: a value the app chose, and the user has not, is italic.
fn styled(font: dvui.Font, default: bool) dvui.Font {
    return if (default) font.withStyle(.italic) else font;
}

fn propText(name: []const u8, comptime fmt: []const u8, args: anytype, n: usize) void {
    propValue(name, false, fmt, args, n);
}

/// A read-only property; `default` marks a value the app chose.
fn propValue(name: []const u8, default: bool, comptime fmt: []const u8, args: anytype, n: usize) void {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    next_kind = .value;
    tagParent(name);
    dvui.labelNoFmt(@src(), name, .{}, .{ .min_size_content = .{ .w = label_width }, .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.65) } });
    dvui.label(@src(), fmt, args, .{ .expand = .horizontal, .font = styled(.theme(.body), default) });
}

/// The left-hand name of a property row.
fn propName(name: []const u8) void {
    tagParent(name);
    // The unit its label names, if any: the field drawn next takes any
    // unit of that kind (see `units`, the one path for typed units).
    accepted.label_unit = layout.units.ofLabel(name);
    // Marked as an override (FrameMaker's asterisk): its value differs
    // from the style it overrides.
    const marked = prop_marked;
    prop_marked = false;
    const shown = if (marked) std.fmt.allocPrint(dvui.currentWindow().arena(), "{s} *", .{name}) catch name else name;
    const col = if (marked) dvui.Color{ .r = 0xff, .g = 0xc0, .b = 0x60 } else dvui.themeGet().color(.control, .text).opacity(0.65);
    dvui.labelNoFmt(@src(), shown, .{}, .{ .min_size_content = .{ .w = label_width }, .gravity_y = 0.5, .color_text = .{ .color = col } });
}

/// The next `propName` is marked as an override.
var prop_marked = false;

/// The worksheet's editable properties: its name (a short description for
/// reference, separate from the file name), and its sheet as a
/// standard paper and orientation or a custom size.
fn worksheetProperties() !void {
    const saved_group = pushGroup("worksheet");
    defer popGroup(saved_group);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        propName("Name");
        if (accepted.textField(@src(), state.model.sheet.name, .{ .expand = .horizontal, .font = styled(.theme(.body), state.model.sheet.default_name) }, .{}, accepted.nonEmpty)) |text| try act(.nameWorksheet, .{text});
    }

    const sheet = state.model.sheet;
    const papers = layout.model.papers;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        propName("Sheet");
        var names: [papers.len + 1][]const u8 = undefined;
        for (papers, 0..) |p, i| names[i] = p.name;
        names[papers.len] = "Custom";
        var choice: usize = sheet.paper orelse papers.len;
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .font = styled(.theme(.body), sheet.default_size) })) {
            try act(.setSheet, .{if (choice < papers.len) .standard(choice, sheet.orientation) else .custom(sheet.w, sheet.h)});
            zoomToContext();
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        propName("Orientation");
        const names = [_][]const u8{ "Landscape", "Portrait" };
        var choice: usize = @backingInt(sheet.orientation);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .font = styled(.theme(.body), sheet.default_size) })) {
            const o: layout.model.Orientation = @fromBackingInt(@intCast(choice));
            if (o != sheet.orientation) {
                try act(.setSheet, .{if (sheet.paper) |p| .standard(p, o) else .custom(sheet.h, sheet.w)});
                zoomToContext();
            }
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        propName("Units");
        const names = [_][]const u8{ "Millimetres", "Inches" };
        var choice: usize = @backingInt(sheet.units);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .font = styled(.theme(.body), sheet.default_units) })) {
            actV(.setUnits, .{@fromBackingInt(@intCast(choice))});
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
        defer row.deinit();
        propName("Ruler origin");
        const names = [_][]const u8{ "Bottom left", "Top left", "Bottom right", "Top right" };
        var choice: usize = @backingInt(sheet.ruler_origin);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .font = styled(.theme(.body), sheet.default_ruler_origin) })) {
            actV(.setRulerOrigin, .{@fromBackingInt(@intCast(choice))});
        }
    }
    if (sheet.paper == null) {
        // A custom sheet takes its size as typed.
        var w = sheet.w;
        var h = sheet.h;
        var changed = false;
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
            defer row.deinit();
            propName("Width, mm");
            if (accepted.numberField(@src(), f64, w, 1, 10000, .{ .expand = .horizontal })) |v| {
                w = v;
                changed = true;
            }
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
            defer row.deinit();
            propName("Height, mm");
            if (accepted.numberField(@src(), f64, h, 1, 10000, .{ .expand = .horizontal })) |v| {
                h = v;
                changed = true;
            }
        }
        if (changed) {
            try act(.setSheet, .{.custom(w, h)});
            zoomToContext();
        }
    } else {
        propValue("Size", sheet.default_size, "{d} × {d} mm", .{ sheet.w, sheet.h }, 50);
    }

    // Margins: ink keep-out bands. Panels may reach into them; their ink
    // may not.
    heading("Margins", .{}, 60);
    setGroup("worksheet.margins", .{});
    var m = sheet.margins;
    var changed = false;
    inline for (.{ .{ "Left, mm", "left" }, .{ "Right, mm", "right" }, .{ "Top, mm", "top" }, .{ "Bottom, mm", "bottom" } }, 0..) |side, i| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 61 + i });
        defer row.deinit();
        propName(side[0]);
        if (accepted.numberField(@src(), f64, @field(m, side[1]), 0, 1000, .{
            .expand = .horizontal,
            .font = styled(.theme(.body), sheet.default_margins),
        })) |v| {
            @field(m, side[1]) = v;
            changed = true;
        }
    }
    if (changed) act(.setMargins, .{m}) catch {};
    if (state.intrusions.len > 0) {
        propValue("Ink in margins", false, "{d} text pieces", .{state.intrusions.len}, 70);
    }
    if (state.panel_issues.len > 0) {
        propValue("Out of compliance", false, "{d} panels", .{state.panel_issues.len}, 71);
    }
}

/// A panel's margins: the ink keep-out bands inside its edges.
fn panelMargins(pi: usize) !void {
    const saved_group = pushGroup("panel.margins");
    defer popGroup(saved_group);
    const panel = state.model.panels.items[pi];
    heading("Margins", .{}, 10);
    var m = panel.margins;
    var changed = false;
    inline for (.{ .{ "Left, mm", "left" }, .{ "Right, mm", "right" }, .{ "Top, mm", "top" }, .{ "Bottom, mm", "bottom" } }, 0..) |side, i| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 11 + i });
        defer row.deinit();
        propName(side[0]);
        if (accepted.numberField(@src(), f64, @field(m, side[1]), 0, 1000, .{
            .expand = .horizontal,
            .font = styled(.theme(.body), panel.default_margins),
            .id_extra = pi,
        })) |v| {
            @field(m, side[1]) = v;
            changed = true;
        }
    }
    if (changed) act(.setPanelMargins, .{pi, m}) catch {};
}

/// The font property: a list of installed fonts, with arrows to step
/// through them. All labels share one face for now; per-style fonts come
/// with the style editor.
fn propFont(name: []const u8, n: usize) !void {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    dvui.labelNoFmt(@src(), name, .{}, .{ .min_size_content = .{ .w = label_width }, .gravity_y = 0.5, .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.65) } });
    if (state.fonts.len == 0) {
        dvui.labelNoFmt(@src(), "none found (fc-list)", .{}, .{});
        return;
    }
    const lifo = dvui.currentWindow().lifo();
    const names = try lifo.alloc([]const u8, state.fonts.len);
    defer lifo.free(names);
    for (state.fonts, 0..) |f, i| names[i] = f.name;
    if (tdropdown(@src(), names, .{ .choice = &state.font_choice }, .{}, .{ .expand = .horizontal, .max_size_content = .width(120), .font = styled(.theme(.body), !state.font_set) })) state.font_set = true;
    keyIcon(@src(), "Previous font", dvui.entypo.chevron_left, 0, .{});
    keyIcon(@src(), "Next font", dvui.entypo.chevron_right, 0, .{});
}

fn properties() !void {
    if (activeKind() == .sheet) return sheetViewProperties();
    // A manufacturing view: its plan, unless the plans or materials are
    // what was chosen in the Browser.
    if (activeKind() == .manufacture) switch (state.context) {
        .plans, .plan, .materials, .material => {},
        else => return planEditor(@enumFromInt(vl.views[vl.active].target)),
    };
    if (sketch_edit != null) return sketchModeProperties();
    // A constraint chosen in the Browser is the picked one.
    if (state.context == .constraint) picked_constraint = state.context.constraint;
    if (pickedConstraintProperties()) return;
    if (panel_edit != null) {
        panelEditHeader();
        if (panel_edit == null) return;
    }
    defer constraintProperties();
    const on_canvas = state.context == .space;
    const frame_root = switch (state.context) {
        .space => |si| si != 0,
        else => false,
    };
    // An expression edited on the canvas, a tile's slot or a run of a
    // flow: its section first, the same either way; what holds it after.
    const expr_first = canvas_eq != null and exprTarget() != null;
    if (expr_first) try expressionProperties();
    // Its id is the context's kind, whatever the heading reads (a region
    // reads Track when it is one).
    headingAs(if (frame_root) "frame" else if (on_canvas) "canvas" else @tagName(state.context), "{s}", .{if (frame_root) "Frame" else if (on_canvas) "Canvas" else state.context.kindName()}, 0);
    // What the elements below are about: the context's kind.
    setGroup("{s}", .{if (frame_root) "frame" else if (on_canvas) "canvas" else contextGroup(state.context)});
    setBase();
    switch (state.context) {
        .file => {
            // The file's name is its path, set by saving; it is not a property.
            propValue("Saved", true, "not yet", .{}, 1);
            propText("Engine", "{s}", .{layout.version}, 2);
        },
        .worksheet => {
            try worksheetProperties();
            propText("Panels", "{d}", .{state.model.panels.items.len}, 3);
            propText("Tiles", "{d}", .{state.model.tiles.items.len}, 4);
            try propFont("Legend font", 5);
        },
        .space => |si| if (si < state.model.spaces.items.len) {
            if (si == 0) try canvasProperties() else try frameProperties(si);
        },
        .panel => |pi| {
            const panel = state.model.panels.items[pi];
            if (textProp("Name", panel.name, 1)) |name| actM(mergeKey(.{ "panel name", pi }), .renamePanel, .{ pi, name }) catch {};
            // Typed exactly: where it sits (bottom left, mm) and, for a
            // rectangle, how big it is.
            if (numberProp("Origin across, mm", panel.origin.x, -100000, 100000, 2)) |v| actM(mergeKey(.{ "panel at", pi }), .movePanel, .{ pi, geom.Point{ .x = v, .y = panel.origin.y } }) catch {
                state.status = "The panel cannot go there. ";
            };
            if (numberProp("Origin up, mm", panel.origin.y, -100000, 100000, 11)) |v| actM(mergeKey(.{ "panel at", pi }), .movePanel, .{ pi, geom.Point{ .x = panel.origin.x, .y = v } }) catch {
                state.status = "The panel cannot go there. ";
            };
            if (panel.edge == null and panel.sketch == .none) {
                if (numberProp("Width, mm", panel.w, 0.01, 100000, 3)) |v| actM(mergeKey(.{ "panel size", pi }), .setPanelSize, .{ pi, v, panel.h }) catch {};
                if (numberProp("Height, mm", panel.h, 0.01, 100000, 12)) |v| actM(mergeKey(.{ "panel size", pi }), .setPanelSize, .{ pi, panel.w, v }) catch {};
            } else propText("Size", "{d:.2} × {d:.2} mm", .{ panel.w, panel.h }, 3);
            propText("Content layouts", "{d}", .{panel.regions.items.len}, 4);
            if (panel.regions.items.len > 0) {
                // Its keys named in order: its tracks in turn, each flow's
                // keys (one flow a row named as one).
                const prefix = key_name_prefix[0..key_name_prefix_len];
                if (textProp(asElement("panel.key-prefix"), prefix, 30)) |v| {
                    key_name_prefix_len = @min(v.len, key_name_prefix.len);
                    @memcpy(key_name_prefix[0..key_name_prefix_len], v[0..key_name_prefix_len]);
                }
                var lb: [64]u8 = undefined;
                actionButton(@src(), "panel.name-tiles", std.fmt.bufPrint(&lb, "Name tiles in order: {s}1, {s}2 …", .{ prefix, prefix }) catch "Name tiles in order", 0, .{ .expand = .horizontal, .id_extra = 31 });
            }
            if (panel.sketch != .none) sketchPanelProperties(pi) else propText("Outline", "{s}", .{if (panel.edge) |e| e.prim.label() else "Rectangle"}, 8);
            if (state.model.spaces.items.len > 0) if (layerChoice(state.model.spaceOf(pi), panelLayer(pi), 10)) |l| try act(.setPanelLayer, .{pi, l});
            var cutouts: usize = 0;
            for (panel.art.items) |pa| {
                if (pa.cutout) cutouts += 1;
            }
            propText("Cutouts", "{d}", .{cutouts}, 9);
            try panelMargins(pi);
            if (panelIssue(pi)) |i| {
                if (i.off_sheet > 0) propText("Issue", "{d:.2} mm off the sheet", .{i.off_sheet}, 20);
                if (i.ink_outside > 0) propText("Issue", "ink area {d:.2} mm in margin", .{i.ink_outside}, 21);
            }
            try propFont("Legend font", 5);
            if (panel_edit == null) actionButton(@src(), "panel.edit", null, 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
            try panelGrids(pi);
            try panelFab(pi);
            if (state.model.has_sheet) return;
            actionButton(@src(), "panel.release", null, 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        },
        .region => |r| {
            const region = state.model.regionsIn(r.parent)[r.region];
            if (textProp(asElement("track.name"), region.name, 1)) |name| actM(mergeKey(.{ "track name", r.parent, r.region }), .renameRegion, .{ r.parent, r.region, name }) catch {};
            // Typed exactly: where it starts (panel mm) and its extent in
            // its pitch (u), along its tracks and across them.
            if (numberProp(asElement("track.origin.across"), region.origin.x, -100000, 100000, 2)) |v| actM(mergeKey(.{ "track at", r.parent, r.region }), .moveRegion, .{ r.parent, r.region, geom.Point{ .x = v, .y = region.origin.y } }) catch {};
            if (numberProp(asElement("track.origin.up"), region.origin.y, -100000, 100000, 21)) |v| actM(mergeKey(.{ "track at", r.parent, r.region }), .moveRegion, .{ r.parent, r.region, geom.Point{ .x = region.origin.x, .y = v } }) catch {};
            const is_track = region.kind == .track;
            propText(asElement("track.kind"), "{s}", .{if (is_track) "single track, laid out in advance" else if (region.major() == .row) "column of rows, added as content needs them" else "row of columns, added as content needs them"}, 130);
            // Which way its baselines run and how content stands on them:
            // rows and columns are two settings of these.
            if (numberProp(asElement("track.direction"), region.direction, -360, 360, 131)) |v| setOrientationOf(r.parent, r.region, v, region.rotation);
            if (numberProp(asElement("track.rotation"), region.rotation, -360, 360, 132)) |v| setOrientationOf(r.parent, r.region, region.direction, v);
            if (!region.supported()) propText(asElement("track.orientation-issue"), "{s}", .{"set as the nearest of rows or columns for now"}, 133);
            {
                const rows = region.major() == .row;
                const along = if (rows) region.w else region.h;
                const across = if (rows) region.h else region.w;
                // Text is measured in mm (the owner, 2026-11-23: text
                // first); tiles in their unit.
                if (region.style != null) {
                    if (numberProp(elementLabel("track.length", "Length, mm"), @round(along * region.pitch * 1000) / 1000, 0.01, 100000, 3)) |v| actM(mergeKey(.{ "track size", r.parent, r.region }), .setRegionSize, .{ r.parent, r.region, v / region.pitch, across }) catch {};
                } else if (numberProp(asElement("track.length"), along, 0.01, 100000, 3)) |v| actM(mergeKey(.{ "track size", r.parent, r.region }), .setRegionSize, .{ r.parent, r.region, v, across }) catch {};
                if (!is_track) if (region.style != null) {
                    if (numberProp(elementLabel("track.depth", "Depth, mm"), @round(across * region.pitch * 1000) / 1000, 0.01, 100000, 22)) |v| actM(mergeKey(.{ "track size", r.parent, r.region }), .setRegionSize, .{ r.parent, r.region, along, v / region.pitch }) catch {};
                } else if (numberProp(elementLabel("track.depth", if (rows) null else "Depth, columns"), across, 0.01, 100000, 22)) |v| actM(mergeKey(.{ "track size", r.parent, r.region }), .setRegionSize, .{ r.parent, r.region, along, v }) catch {};
                if (region.style != null) propText(asElement("track.size"), "{d:.1} × {d:.1} mm", .{ region.w * region.pitch, region.h * region.pitch }, 23);
            }
            if (region.style != null) {
                if (flowStyled(r.parent, r.region) == null) leadingProps(r.parent, r.region);
            } else propText(asElement("track.pitch"), "{d:.2} mm", .{region.pitch}, 4);
            if (!is_track) propText(elementLabel("track.rows", if (region.major() == .row) null else "Columns"), "{d}", .{tracksIn(r.parent, r.region).len}, 5);
            const head = state.model.threadHead(r.parent, r.region);
            const is_head = head.parent.eql(r.parent) and head.region == r.region;
            propText(asElement("track.items"), "{d}{s}", .{ state.model.flowItems(head.parent, head.region).len, if (!is_head) " in its flow" else "" }, 8);
            if (region.style == null) {
                // Its keys named in flow order: the prefix, then 1, 2 …
                const prefix = key_name_prefix[0..key_name_prefix_len];
                if (textProp(asElement("track.key-prefix"), prefix, 24)) |v| {
                    key_name_prefix_len = @min(v.len, key_name_prefix.len);
                    @memcpy(key_name_prefix[0..key_name_prefix_len], v[0..key_name_prefix_len]);
                }
                var lb: [64]u8 = undefined;
                actionButton(@src(), "track.name-tiles", std.fmt.bufPrint(&lb, "Name tiles in order: {s}1, {s}2 …", .{ prefix, prefix }) catch "Name tiles in order", 0, .{ .expand = .horizontal, .id_extra = 25 });
            }
            if (placedOf(r.parent)) |pl| for (pl.issues) |i| {
                if (i.kind == .region_outside and i.region == r.region) propText(asElement("track.outside-issue"), "{d:.2} mm past the panel", .{i.amount}, 7);
            };
            if (region.prototype) |pid| if (state.model.protoIndex(pid) != null) propText(asElement("track.prototype"), "{s}", .{state.model.proto(pid).name}, 6);
            if (region.style) |sid| if (state.model.styleIndex(sid) != null) propText(asElement("track.style"), "{s}, one line ({d:.2} mm)", .{ state.model.textStyle(sid).name, region.pitch }, 9);
            // A region's rows (or columns) as tracks of their own, where
            // they are now, its flow running on through them.
            if (!is_track) {
                const placed_rows = tracksIn(r.parent, r.region);
                var lb: [48]u8 = undefined;
                const label = std.fmt.bufPrint(&lb, "Make tracks of its {d} {s}", .{ placed_rows.len, if (region.major() == .row) "rows" else "columns" }) catch "Make tracks";
                if (placed_rows.len > 0) actionButton(@src(), "track.make-tracks", label, 0, .{ .expand = .horizontal, .id_extra = 134, .margin = .{ .y = 6 } });
            }
            actionButton(@src(), "track.remove", "Remove content layout", 0, .{ .expand = .horizontal, .id_extra = 135, .margin = .{ .y = 6 } });
            try trackFlowProperties(r.parent, r.region);
            try flowStyleProperties(head.parent, head.region);
            // The flow's paragraphs are its thread's.
            try paragraphProperties(head.parent, head.region);
            threadProperties(r.parent, r.region);
            if (!expr_first) try expressionProperties();
        },
        .row => |r| {
            const pt = placedTrack(r.parent, r.region, r.row);
            const member = if (pt) |x| x.member else r.region;
            const on = if (pt) |x| x.parent else r.parent;
            // A track that no longer exists shows nothing.
            if (!state.model.hasParent(on) or member >= state.model.regionsIn(on).len) return;
            const region = state.model.regionsIn(on)[member];
            propText(trackWord(region.major()), "{d} of {d} in {s}", .{ (if (pt) |x| x.local else r.row) + 1, tracksIn(on, member).len, region.name }, 1);
            var where_buf: [96]u8 = undefined;
            propText("Placed", "{s}", .{trackWhere(&where_buf, r.parent, r.region, r.row)}, 2);
            var held: usize = 0;
            for (flowItems(r.parent, r.region)) |it| {
                if (it.segment == r.row and !isBreak(r.parent, it)) held += 1;
            }
            propText("Items", "{d}", .{held}, 3);
        },
        .tile => |id| {
            try tileProperties(id);
            tileSketchParams(id);
            if (!expr_first) try expressionProperties();
        },
        .art => |l| try artProperties(l.panel, l.index),
        .group => |g| try groupProperties(g),
        .selection => try selectionProperties(),
        .view => |v| try viewProperties(v.space, v.index),
        .layer => |l| try layerProperties(l.space, l.index),
        .image => |im| try imageProperties(im.space, im.index),
        .figure_place => |c| figurePlaceProperties(c.space, c.index),
        .guide => |g| guideProperties(g.space, g.index),
        .sketch => |sc| sketchProperties(sc.space, sc.index),
        .sketches => sketchesProperties(),
        .sketch_def => |i| sketchDefProperties(i),
        .figures => figuresProperties(),
        .figure_def => |i| figureProperties(i),
        .grid => |g| try gridProperties(g.parent, g.index),
        .prototypes => propText("Prototypes", "{d}", .{state.model.prototypes.items.len}, 1),
        .prototype => |id| {
            try prototypeProperties(id);
            prototypeSketch(id);
        },
        .flows => flowsProperties(),
        .flow => |id| flowProperties(id),
        .sheets => propText("Legend sheets", "{d}", .{state.model.sheets.items.len}, 1),
        .styles => try stylesProperties(),
        .style => |sid| try styleProperties(sid),
        .templates => propText("Style templates", "{d}", .{state.model.templates.items.len}, 1),
        .template => |id| try templateProperties(id),
        .processes => processesProperties(),
        .process => |id| processProperties(id),
        .plans => plansProperties(),
        .plan => |id| planProperties(id),
        .materials => materialsProperties(),
        .material => |id| materialProperties(id),
        .sheet => |id| sheetProperties(id),
        .constraints => constraintsProperties(),
        // Shown as the picked constraint (`pickedConstraintProperties`).
        .constraint => {},
    }
}

fn tileProperties(id: TileId) !void {
    const saved_group = pushGroup("tile");
    defer popGroup(saved_group);
    const t = state.model.tileConst(id);
    propText("Designator", "{s}", .{t.designator}, 1);
    const on_grid = state.model.gridInstanceOf(id);
    if (on_grid) |at| try instanceProperties(at.parent, at.grid, at.index);
    if (on_grid == null) {
        try sizeProperty(id, .horizontal);
        try sizeProperty(id, .vertical);
    }
    const found = if (on_grid == null) findTile(id) else null;
    if (found) |f| {
        const pt = f.tile;
        propText("Body", "{d:.2} × {d:.2} mm", .{ pt.body.width(), pt.body.height() }, 3);
        propText("Position", "({d:.2}, {d:.2}) mm in panel", .{ pt.body.x0, pt.body.y0 }, 4);
        propText("Row", "{d}", .{pt.row + 1}, 5);
    }
    if (on_grid == null) if (flowPosOf(id)) |at| {
        const gap = state.model.flowItems(at.parent, at.region)[at.index].gap;
        if (numberProp("Gap before, u", gap, 0, 1000, 8)) |v| actM(mergeKey(.{ "tile gap", id }), .setItemGap, .{ at.parent, at.region, at.index, v }) catch {};
    };

    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 6 });
        defer row.deinit();
        propName("Prototype");
        const lifo = dvui.currentWindow().lifo();
        const names = try lifo.alloc([]const u8, state.model.prototypes.items.len);
        defer lifo.free(names);
        for (state.model.prototypes.items, names) |p, *nm| nm.* = p.name;
        var choice: usize = protoPos(t.prototype);
        if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and state.model.prototypes.items[choice].id != t.prototype) {
            try act(.setTilePrototype, .{ id, state.model.prototypes.items[choice].id });
        }
    }

    for (state.model.prototypeOf(id).tracks, 0..) |tt, k| {
        const n = 3000 + k * 10;
        headingAs(scopeId("tile.slot", tt.name), "Track {s}", .{tt.name}, n);
        const arena = dvui.currentWindow().arena();
        const text = state.model.tileTrackText(arena, id, tt.id) catch "";
        var te = dvui.textEntry(@src(), .{ .text_initial = text, .multiline = true }, .{
            .expand = .horizontal,
            .min_size_content = .{ .h = 40 },
            .id_extra = @as(usize, @backingInt(id)) * 64 + k,
        });
        // Taken when the field is left (Enter is a line break here).
        const offered = accepted.accept(te, text);
        const focused = te.data().id == dvui.focusedWidgetId();
        te.deinit();
        if (focused) expr_track = tt.id;
        if (offered) |now| try act(.setTileTrackText, .{ id, tt.id, now });
        propText("Runs", "{s}, {s}", .{ if (tt.major == .row) "in rows" else "down columns, a character at a time", @tagName(tt.alignment) }, n + 1);
        if (found) |f| {
            if (placedOf(f.parent)) |pl| for (pl.issues, 0..) |i, q| if (i.tile == id and i.slot == k) {
                propText("Issue", "{s}", .{@tagName(i.kind)}, n + 2 + @min(q, 5));
            };
            for (state.intrusions) |i| if (i.tile == id and i.slot == k) {
                propText("Issue", "ink {d:.2} mm into the sheet margin", .{i.amount}, n + 8);
            };
        }
    }
}

/// Where tile `id` is in a flow: the flow's first track and its index.
fn flowPosOf(id: TileId) ?struct { parent: Parent, region: usize, index: usize } {
    for (0..state.model.parentCount()) |pk| for (0..state.model.regionsIn(state.model.parentAt(pk)).len) |ri| {
        const pi = state.model.parentAt(pk);
        const head = state.model.threadHead(pi, ri);
        if (!head.parent.eql(pi) or head.region != ri) continue;
        for (state.model.flowItems(pi, ri), 0..) |item, k| if (item.tileOf()) |t| {
            if (t == id) return .{ .parent = pi, .region = ri, .index = k };
        };
    };
    return null;
}

/// A tile prototype: what its tiles share, and the parts of it that can be
/// changed here: where its labels go and how its art is painted. Its art's
/// outlines are left as drawn. Every tile made from it is outlined on the
/// canvas.
fn prototypeProperties(id: layout.model.PrototypeId) !void {
    const saved_group = pushGroup("prototype");
    defer popGroup(saved_group);
    const p = state.model.proto(id).*;
    // Whole-prototype changes go through one copy, set once at the end.
    var next_proto = p;
    var proto_changed = false;
    if (textProp("Name", p.name, 1)) |name| {
        next_proto.name = name;
        proto_changed = true;
    }
    propText("Used by", "{d} tiles", .{state.model.prototypeUses(id)}, 2);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3 });
        defer row.deinit();
        propName("Grows");
        if (tcheckbox(@src(), &next_proto.expand.horizontal, "Wider", .{ .id_extra = 3 })) proto_changed = true;
        if (tcheckbox(@src(), &next_proto.expand.vertical, "Taller", .{ .id_extra = 4 })) proto_changed = true;
    }
    {
        // How its tiles flow: a spacer (a blank, not in output), and
        // whether one is dropped where a soft break leaves it at a row's
        // start (a space between words) or kept (a keyboard's gap).
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 7 });
        defer row.deinit();
        propName("In the flow");
        if (tcheckbox(@src(), &next_proto.spacer, "Spacer", .{ .id_extra = 5 })) proto_changed = true;
        var drop = next_proto.at_soft_break == .drop;
        if (tcheckbox(@src(), &drop, "Dropped at a wrap", .{ .id_extra = 6 })) {
            next_proto.at_soft_break = if (drop) .drop else .keep;
            proto_changed = true;
        }
    }
    {
        // A letter binds to what follows it (an illuminated initial with
        // its word); with a baseline, it sits on the row's text baseline.
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8 });
        defer row.deinit();
        propName("As a letter");
        if (tcheckbox(@src(), &next_proto.letter, "Binds to its word", .{ .id_extra = 8 })) proto_changed = true;
    }
    {
        var bbuf: [32]u8 = undefined;
        const shown = if (p.baseline) |b| std.fmt.bufPrint(&bbuf, "{d}", .{b}) catch "" else "any";
        if (sizesProp("Baseline, u up", shown, 9)) |list| if (list.len <= 1) {
            next_proto.baseline = if (list.len == 1) list[0] else null;
            proto_changed = true;
        };
    }
    var buf: [160]u8 = undefined;
    {
        // Its u in mm; empty follows the pitch of the track a tile is in.
        var ubuf: [32]u8 = undefined;
        const shown = if (p.unit) |u| std.fmt.bufPrint(&ubuf, "{d}", .{u}) catch "" else "any";
        if (sizesProp("Unit, mm per u", shown, 6)) |list| if (list.len <= 1) {
            next_proto.unit = if (list.len == 1) list[0] else null;
            proto_changed = true;
        };
    }
    if (p.expand.horizontal) if (sizesProp("Widths, u", sizeList(&buf, p.widths), 4)) |list| {
        next_proto.widths = list;
        proto_changed = true;
    };
    if (p.expand.vertical) if (sizesProp("Heights, u", sizeList(&buf, p.heights), 5)) |list| {
        next_proto.heights = list;
        proto_changed = true;
    };
    var insets_changed = false;
    if (sidesEditor("Body inset", p.body_inset, 10)) |s| {
        next_proto.body_inset = s;
        insets_changed = true;
    }
    if (sidesEditor("Face inset", p.face_inset, 20)) |s| {
        next_proto.face_inset = s;
        insets_changed = true;
    }
    if (insets_changed) {
        // A keycap's shape follows its insets; other art keeps its outlines
        // until redrawn.
        if (isKeycap(p.art)) next_proto.art = try layout.art.redrawKeycap(dvui.currentWindow().arena(), next_proto, protoUnit(next_proto));
        proto_changed = true;
    }
    if (proto_changed) {
        try act(.setPrototype, .{id, next_proto});
        return;
    }

    for (p.tracks, 0..) |tt, k| {
        const n = 800 + k * 20;
        headingAs(scopeId("prototype.slot", tt.name), "Track {s}", .{tt.name}, n);
        var next = tt;
        var changed = false;
        if (textProp("Name", tt.name, n * 8 + 7)) |name| {
            next.name = name;
            changed = true;
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 1 });
            defer row.deinit();
            propName("Runs");
            const names = [_][]const u8{ "in rows", "down columns" };
            var choice: usize = if (tt.major == .row) 0 else 1;
            if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n + 1 })) {
                next.major = if (choice == 0) .row else .column;
                changed = true;
            }
        }
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 2 });
            defer row.deinit();
            propName("Set from");
            const names = [_][]const u8{ "start", "centre", "end" };
            var choice: usize = @intFromEnum(tt.alignment);
            if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n + 2 })) {
                next.alignment = @enumFromInt(choice);
                changed = true;
            }
        }
        if (styleChoice(tt.style, null, n + 3)) |c| {
            next.style = c.?;
            changed = true;
        }
        inline for (.{ .{ "Inset left, mm", "left" }, .{ "Inset right, mm", "right" }, .{ "Inset top, mm", "top" }, .{ "Inset bottom, mm", "bottom" } }, 0..) |side, i| {
            if (numberProp(side[0], @field(tt.place.inset, side[1]), 0, 1000, n + 4 + i)) |v| {
                @field(next.place.inset, side[1]) = v;
                changed = true;
            }
        }
        if (changed) actM(mergeKey(.{ "proto track", id, tt.id }), .setPrototypeTrack, .{ id, tt.id, next }) catch {
            state.status = "That track cannot be set so. ";
        };
        keyButton(@src(), "Remove track", @intCast(k), .{ .id_extra = n + 9, .gravity_x = 1 });
    }
    endSection();
    keyButton(@src(), "Add track", 0, .{ .id_extra = 799, .gravity_x = 1, .margin = .{ .y = 8 } });

    heading("Art", .{}, 600);
    const art = p.art orelse {
        propText("Look", "plain, from the insets", .{}, 601);
        keyButton(@src(), "Add keycap art", 0, .{ .id_extra = 602, .gravity_x = 1 });
        return;
    };
    for (art.layers, 0..) |layer, li| {
        const n = 700 + li * 20;
        headingAs(scopeId("prototype.art-layer", layer.name), "Layer {s}", .{layer.name}, n);
        if (paintEditor(layer.paint, n + 1)) |paint| try act(.setLayerPaint, .{id, li, paint});
    }
    endSection();
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .gravity_x = 1, .id_extra = 690, .margin = .{ .y = 8 } });
        defer row.deinit();
        if (!isKeycap(p.art)) keyButton(@src(), "Redraw from insets", 0, .{ .id_extra = 691 });
        keyButton(@src(), "Remove art", 0, .{ .id_extra = 692 });
    }
}

/// Whether `art` is a keycap's two layers, body and face, so it can be
/// redrawn from the insets without losing anything.
fn isKeycap(art: ?layout.art.Art) bool {
    const a = art orelse return false;
    return a.layers.len == 2 and std.mem.eql(u8, a.layers[0].name, "body") and std.mem.eql(u8, a.layers[1].name, "face");
}

/// A prototype's unit, mm per u, which its art is drawn for: 19.05 mm (a
/// keyboard's u) when it follows its tracks' pitch.
fn protoUnit(p: layout.model.TilePrototype) f64 {
    return p.unit orelse 19.05;
}

/// How a track holds its content: alignment in each row or column, the
/// indent after hard breaks, and the gap between rows the path makes.
fn trackFlowProperties(pi: Parent, ri: usize) !void {
    const region = state.model.regionsIn(pi)[ri];
    var alignment = region.alignment;
    var indent = state.model.trackIndent(pi, ri);
    var gap = region.gap;
    var changed = false;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 20 });
        defer row.deinit();
        propName(asElement("track.content"));
        const names = [_][]const u8{ "From the start", "Centred", "Back from the end" };
        var choice: usize = @intFromEnum(alignment);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 20 })) {
            alignment = @enumFromInt(choice);
            changed = true;
        }
    }
    var buf: [32]u8 = undefined;
    // Empty is none; one length each.
    if (sizesProp(asElement("track.indent"), if (indent > 0) std.fmt.bufPrint(&buf, "{d}", .{indent}) catch "" else "any", 21)) |list| if (list.len <= 1) {
        indent = if (list.len == 1) list[0] else 0;
        changed = true;
    };
    if (region.kind != .track) if (sizesProp(elementLabel("track.gap", if (region.major() == .row) null else "Column gap, u"), if (gap > 0) std.fmt.bufPrint(&buf, "{d}", .{gap}) catch "" else "any", 22)) |list| if (list.len <= 1) {
        gap = if (list.len == 1) list[0] else 0;
        changed = true;
    };
    if (changed) try act(.setTrackFlow, .{pi, ri, alignment, indent, gap});
}

/// A paragraph style's settings as fields (alignment, indents, first
/// line, space before and after, extra between lines), into `ps`; whether
/// one changed. `n` sets them apart from another set in the same pane.
fn paragraphFields(ps: *layout.model.ParagraphStyle, n: usize, ref: ?*const layout.model.ParagraphStyle) bool {
    var changed = false;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 904 + n });
        defer row.deinit();
        prop_marked = if (ref) |r| r.alignment != ps.alignment else false;
        propName("Lines");
        const names = [_][]const u8{ "From the start", "Centred", "Back from the end", "Justified" };
        var choice: usize = @intFromEnum(ps.alignment);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 904 + n })) {
            ps.alignment = @enumFromInt(choice);
            changed = true;
        }
    }
    const pt_per_mm = 72.0 / 25.4;
    const fields = [_]struct { name: []const u8, field: []const u8, min: f64 }{
        .{ .name = "Indent at start, pt", .field = "indent_start", .min = 0 },
        .{ .name = "Indent at end, pt", .field = "indent_end", .min = 0 },
        .{ .name = "First line, pt", .field = "first", .min = -1000 },
        .{ .name = "Space before, pt", .field = "space_before", .min = 0 },
        .{ .name = "Space after, pt", .field = "space_after", .min = 0 },
        .{ .name = "Extra between lines, pt", .field = "line_gap", .min = 0 },
    };
    inline for (fields, 0..) |f, k| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 910 + k + n });
        defer row.deinit();
        prop_marked = if (ref) |r| @abs(@field(r, f.field) - @field(ps, f.field)) > 1e-9 else false;
        propName(f.name);
        const v: f64 = @round(@field(ps, f.field) * pt_per_mm * 100) / 100;
        if (accepted.numberField(@src(), f64, v, f.min, 1000, .{ .expand = .horizontal, .id_extra = 910 + k + n })) |nv| {
            @field(ps, f.field) = nv / pt_per_mm;
            changed = true;
        }
    }
    // What a line does about something taller than its font (a
    // display-style formula): the lines around break around it, it moves
    // down, or the spacing is fixed.
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 919 + n });
        defer row.deinit();
        prop_marked = if (ref) |r| r.tall != ps.tall else false;
        propName("Tall content");
        const names = [_][]const u8{ "Lines flow around it", "Its line moves down", "Fixed spacing (may overlap)" };
        var choice: usize = @intFromEnum(ps.tall);
        if (tdropdown(@src(), &names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 919 + n })) {
            ps.tall = @enumFromInt(choice);
            changed = true;
        }
    }
    // The style Enter gives the paragraph after (FrameMaker's Next ¶ Tag).
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 920 + n });
        defer row.deinit();
        prop_marked = if (ref) |r| r.next != ps.next else false;
        propName("Next paragraph");
        const styles = state.model.paragraph_styles.items;
        const a = dvui.currentWindow().arena();
        const names = a.alloc([]const u8, styles.len + 1) catch return changed;
        names[0] = "The same";
        var choice: usize = 0;
        for (styles, names[1..], 1..) |st, *nm, k| {
            nm.* = st.name;
            if (ps.next == st.id) choice = k;
        }
        if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 920 + n })) {
            ps.next = if (choice == 0) null else styles[choice - 1].id;
            changed = true;
        }
    }
    return changed;
}

/// The paragraph at the flow cursor (else the track's first): which
/// paragraph style it takes, and that style's settings, which every
/// paragraph in it shares. Lengths in points, as type is measured.
fn paragraphProperties(pi: Parent, ri: usize) !void {
    const saved_group = pushGroup("paragraph");
    defer popGroup(saved_group);
    const m = &state.model;
    const at: usize = if (track_cursor) |c| (if (c.parent.eql(pi) and c.region == ri) c.index else 0) else 0;
    heading("Paragraph", .{}, 900);
    const current = m.paragraphStyleAt(pi, ri, at);
    const a = dvui.currentWindow().arena();
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 901 });
        defer row.deinit();
        propName("Style");
        const names = try a.alloc([]const u8, m.paragraph_styles.items.len + 1);
        const flow_def = if (m.trackFlow(pi, ri)) |fl| fl.paragraph_default else null;
        names[0] = if (flow_def != null) "The flow style's" else "None (the track's alignment)";
        for (m.paragraph_styles.items, names[1..]) |ps, *n| n.* = ps.name;
        var choice: usize = if (current) |id| (if (m.paraIndex(id)) |x| x + 1 else 0) else 0;
        if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 901 })) {
            try act(.setParagraphAt, .{ pi, ri, at, if (choice == 0) null else m.paragraph_styles.items[choice - 1].id });
        }
    }
    // A new style from this paragraph's settings: its own button, below
    // (beside the dropdown it was pushed out of the pane).
    if (icons.button(@src(), .plus_circle, "New paragraph style, for this paragraph", .{ .id_extra = 902, .opts = .{ .gravity_x = 1, .tag = tagFor("New paragraph style") } })) {
        var buf: [32]u8 = undefined;
        var base: layout.model.ParagraphStyle = if (current) |cid| (if (m.paraStyle(cid)) |ps| ps.* else .{ .name = "" }) else .{ .name = "" };
        base.name = m.nextParagraphStyleName(&buf);
        const nid = try act(.addParagraphStyle, .{base});
        _ = try hist.join(m, .setParagraphAt, .{ pi, ri, at, nid });
    }
    // The settings show for any paragraph (the owner, 2026-11-23: space
    // before and after paragraphs are to be found here): one in no style
    // that is changed gets a style of its own, made with the change.
    const flow_default = if (m.trackFlow(pi, ri)) |fl| fl.paragraph_default else null;
    var ps: layout.model.ParagraphStyle = if (current orelse flow_default) |cid| (if (m.paraStyle(cid)) |p| p.* else .{ .name = "" }) else .{ .name = "" };
    if (current) |cid| if (textProp("Name", ps.name, 903)) |name| {
        ps.name = name;
        _ = try actM(mergeKey(.{ "paragraph style", cid }), .setParagraphStyle, .{ cid, ps });
        return;
    };
    const changed = paragraphFields(&ps, 0, null);
    if (changed) {
        if (current) |cid| {
            _ = try actM(mergeKey(.{ "paragraph style", cid }), .setParagraphStyle, .{ cid, ps });
        } else {
            var buf: [32]u8 = undefined;
            ps.name = m.nextParagraphStyleName(&buf);
            const nid = try act(.addParagraphStyle, .{ps});
            _ = try hist.join(m, .setParagraphAt, .{ pi, ri, at, nid });
        }
    }
}

// The expression and its style ---------------------------------------------
//
// The object at the expression line's cursor, as glyphic parses the line:
// the parameters an element may override, each its override or (italic)
// what it takes from its style; a change rewrites that object's source in
// Graven's call form, `\set(scale: 1.2){x}`. Then the text style it is
// set in: its base and faces, and its rules, which can be edited.

const element_params = blk: {
    var n: usize = 0;
    for (std.enums.values(glyphic.Param)) |p| {
        if (glyphic.param.def(p).element) n += 1;
    }
    var out: [n]glyphic.Param = undefined;
    var k: usize = 0;
    for (std.enums.values(glyphic.Param)) |p| if (glyphic.param.def(p).element) {
        out[k] = p;
        k += 1;
    };
    break :blk out;
};

/// A parameter's name as the inspector shows it: "shift_x" as "Shift x".
fn paramLabel(buf: []u8, p: glyphic.Param) []const u8 {
    const name = @tagName(p);
    const n = @min(name.len, buf.len);
    for (name[0..n], buf[0..n], 0..) |c, *o, i| o.* = if (c == '_') ' ' else if (i == 0) std.ascii.toUpper(c) else c;
    return buf[0..n];
}

/// Edits a parameter value in place; true when it changed. Numbers in an
/// entry, choices in a dropdown, flags as a checkbox. `default` shows it
/// in italic (a value not set here).
fn valueEditor(p: glyphic.Param, v: *glyphic.Value, default: bool, n: usize) bool {
    const d = glyphic.param.def(p);
    switch (d.type) {
        .number => {
            if (accepted.numberField(@src(), f32, v.number, d.min, d.max, .{ .expand = .horizontal, .id_extra = n, .font = styled(.theme(.body), default) })) |x| {
                v.* = .{ .number = x };
                return true;
            }
        },
        .choice => {
            var c: usize = v.choice;
            if (tdropdown(@src(), d.choices, .{ .choice = &c }, .{}, .{ .expand = .horizontal, .id_extra = n, .font = styled(.theme(.body), default) }) and c != v.choice) {
                v.* = .{ .choice = @intCast(c) };
                return true;
            }
        },
        .flag => {
            var f = v.flag;
            if (tcheckbox(@src(), &f, null, .{ .id_extra = n })) {
                v.* = .{ .flag = f };
                return true;
            }
        },
        .name => dvui.labelNoFmt(@src(), v.name, .{}, .{ .id_extra = n }),
    }
    return false;
}

/// The text style the expression line's target is set in.
fn exprStyle(target: ExprTarget) ?layout.model.StyleId {
    return switch (target) {
        .run => |r| state.model.flowItems(r.parent, r.region)[r.item].what.run.style,
        .tile_track => |tt| for (state.model.prototypeOf(tt.tile).tracks) |t| {
            if (t.id == tt.track) break t.style;
        } else null,
    };
}

fn expressionProperties() !void {
    const saved_group = pushGroup("expression");
    defer popGroup(saved_group);
    const target = exprTarget() orelse return;
    const a = dvui.currentWindow().arena();
    const src = target.content();
    const at: usize = if (expr_inspect) |ei| (if (ei.key == target.key()) @min(ei.offset, src.len) else src.len) else src.len;
    var e = try glyphic.Expr.init(a);
    var spans: glyphic.entry.Spans = .{};
    try glyphic.latex.parse(&e, &spans, src, if (target.isMath()) .math else .legend);
    heading("Expression object", .{}, 4000);
    if (canvas_eq) |q| if (q.target.key() == target.key()) {
        // What is edited, named the same way for a tile's slot and a run.
        var wb: [160]u8 = undefined;
        propText("Editing", "{s}", .{eqTargetName(&wb, q)}, 3990);
        // The chosen object's place among its neighbours, as drawn.
        if (eq_measure) |m| if (m.of.offset == q.offset and std.meta.eql(m.of.head, q.head) and std.meta.eql(m.of.head_end, q.head_end)) {
            const cap = if (m.cap > 0) m.cap else 1;
            if (m.gap_before) |g| propText("Gap before", "{d:.3} mm ({d:.3} cap)", .{ g, g / cap }, 3991) else propText("Gap before", "{s}", .{"first in its row"}, 3991);
            if (m.gap_after) |g| propText("Gap after", "{d:.3} mm ({d:.3} cap)", .{ g, g / cap }, 3992) else propText("Gap after", "{s}", .{"last in its row"}, 3992);
            propText("Baseline", "{d:.3} mm above the slot's", .{m.raised}, 3993);
            propText("Box", "{d:.3} wide, {d:.3} up, {d:.3} down, mm", .{ m.width, m.height, m.depth }, 3994);
        };
    };
    const head_id: ?glyphic.Id = if (canvas_eq) |q| (if (q.target.key() == target.key()) pickAt(&.{ .e = e, .spans = spans }, q) else null) else null;
    if (head_id orelse glyphic.entry.objectAt(&e, spans, at)) |id| {
        const n = e.node(id);
        propText("At the cursor", "{s} {s}", .{ @tagName(n.kind), n.text }, 4001);
        if (n.kind == .space or n.kind == .soft_hyphen) {
            propText("Overrides", "a space takes its style's", .{}, 4002);
        } else for (element_params, 0..) |p, k| {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 4010 + k });
            defer row.deinit();
            var lb: [32]u8 = undefined;
            listItem("expression.param", @tagName(p));
            propName(paramLabel(&lb, p));
            const own = e.override(id, p);
            var v = own orelse glyphic.param.def(p).default;
            const changed = valueEditor(p, &v, own == null, 4100 + k);
            var cleared = false;
            if (own != null and icons.button(@src(), .x, "Back to its style's", .{ .id_extra = 4200 + k, .size = 14 })) cleared = true;
            if (!changed and !cleared) continue;
            if (cleared) e.clear(id, p) else e.set(id, p, v) catch continue;
            target.store(try glyphic.entry.rewriteCall(a, src, spans.get(id), &e, id)) catch {
                state.status = "The override could not be set. ";
            };
        }
    } else propText("At the cursor", "nothing: put the cursor in the expression line", .{}, 4001);
    if (exprStyle(target)) |sid| if (state.model.styleIndex(sid) != null) try styleRuleProperties(sid);
}
const kind_names = blk: {
    const fields = @typeInfo(glyphic.Kind).@"enum".field_names;
    var out: [fields.len + 1][]const u8 = undefined;
    out[0] = "every object";
    for (fields, 1..) |f, i| out[i] = f;
    break :blk out;
};

const param_names = @typeInfo(glyphic.Param).@"enum".field_names;

/// A text style: what it is based on, its faces (set in the Fonts
/// window), and its rules, each a parameter for every object or one kind:
/// edited, removed, added.
fn styleRuleProperties(sid: layout.model.StyleId) !void {
    const saved_group = pushGroup("expression.rule");
    defer popGroup(saved_group);
    const st = state.model.textStyle(sid).*;
    headingAs("expression.style", "Text style {s}", .{st.name}, 4500);
    try styleSizeProps(sid, false);
    if (st.base != .none) if (state.model.styleIndex(st.base)) |bi| propText("Based on", "{s}", .{state.model.styles.items[bi].name}, 4501);
    if (st.faces.items.len == 0) propValue("Faces", true, "{s}", .{if (st.base != .none) "its base's" else "the default face"}, 4502);
    for (st.faces.items, 0..) |f, k| propText(faceItem("expression.style.face", f.role), "{s} {s}", .{ f.font.family, f.font.style }, @as(usize, 4503) + @min(k, 30));
    try styleRules(sid);
}

/// A style's rules, each editable, and Add a rule.
fn styleRules(sid: layout.model.StyleId) !void {
    const saved_group = pushGroup("style.rules");
    defer popGroup(saved_group);
    const st = state.model.textStyle(sid).*;
    propValue("Rules", st.rules.items.len == 0, "{s}", .{if (st.rules.items.len == 0) "none: its base's and glyphic's defaults" else ""}, 4590);
    for (st.rules.items, 0..) |r, k| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 4600 + k });
        defer row.deinit();
        const key = mergeKey(.{ "style rule", sid, k });
        var tb: [32]u8 = undefined;
        next_element = std.fmt.allocPrint(dvui.currentWindow().arena(), "style.rules.{d}.kind", .{k + 1}) catch null;
        tagParent(std.fmt.bufPrint(&tb, "rule {d} kind", .{k + 1}) catch "rule");
        var kind_choice: usize = if (r.kind) |kd| @as(usize, @intFromEnum(kd)) + 1 else 0;
        if (tdropdown(@src(), &kind_names, .{ .choice = &kind_choice }, .{}, .{ .id_extra = 4700 + k, .min_size_content = .{ .w = 90 } })) {
            const kind: ?glyphic.Kind = if (kind_choice == 0) null else @enumFromInt(kind_choice - 1);
            _ = actM(key, .setStyleRule, .{ sid, r.kind, r.param, null }) catch {};
            _ = actM(key, .setStyleRule, .{ sid, kind, r.param, @as(?glyphic.Value, r.value) }) catch {};
            return;
        }
        next_element = std.fmt.allocPrint(dvui.currentWindow().arena(), "style.rules.{d}.parameter", .{k + 1}) catch null;
        tagParent(std.fmt.bufPrint(&tb, "rule {d} parameter", .{k + 1}) catch "rule");
        var param_choice: usize = @intFromEnum(r.param);
        if (tdropdown(@src(), param_names, .{ .choice = &param_choice }, .{}, .{ .id_extra = 4800 + k, .min_size_content = .{ .w = 110 } })) {
            const p: glyphic.Param = @enumFromInt(param_choice);
            _ = actM(key, .setStyleRule, .{ sid, r.kind, r.param, null }) catch {};
            _ = actM(key, .setStyleRule, .{ sid, r.kind, p, @as(?glyphic.Value, glyphic.param.def(p).default) }) catch {};
            return;
        }
        var v = r.value;
        {
            // Its own box, tagged, so the value is found apart from the row.
            var vb = dvui.box(@src(), .{ .dir = .horizontal }, .{ .id_extra = 4950 + k, .gravity_y = 0.5 });
            defer vb.deinit();
            next_element = std.fmt.allocPrint(dvui.currentWindow().arena(), "style.rules.{d}.value", .{k + 1}) catch null;
        tagParent(std.fmt.bufPrint(&tb, "rule {d} value", .{k + 1}) catch "rule");
            if (valueEditor(r.param, &v, false, 4900 + k)) {
                _ = actM(key, .setStyleRule, .{ sid, r.kind, r.param, @as(?glyphic.Value, v) }) catch {};
            }
        }
        if (icons.button(@src(), .trash, "Remove this rule", .{ .id_extra = 5000 + k, .size = 14 })) {
            _ = act(.setStyleRule, .{ sid, r.kind, r.param, null }) catch {};
            return;
        }
    }
    keyButton(@src(), "Add a rule", idArg(sid), .{ .id_extra = 5100, .margin = .{ .y = 4 } });
}

/// A style's em (its font size), mm, as its font resolves it.
fn styleEmMm(sid: layout.model.StyleId) f64 {
    const style = state.model.textStyle(sid).*;
    const ctx = if (state.labels) |*l| l.context(sid) else null;
    const cap = if (ctx) |c| c.cap_height else style.cap_height;
    return style.em_size orelse if (ctx) |c| cap * @as(f64, @floatFromInt(c.text.upem)) / layout.legend.capUnits(c.text) else cap / layout.model.cap_per_em;
}

/// Leading is kept as typed, with its unit (the owner, 2026-11-23: values
/// keep their units and are converted when needed, not once on entry): a
/// layout whose style's size has changed since gets its baselines re-spaced,
/// joined to the change that moved them, so one undo takes both back.
fn followLeading() void {
    // Only once the styles are resolved: until then sizes are guesses.
    if (state.labels == null) return;
    for (0..state.model.parentCount()) |k| for (state.model.regionsIn(state.model.parentAt(k)), 0..) |rg, ri| {
        const pi = state.model.parentAt(k);
        const sid = rg.style orelse continue;
        if (state.model.styleIndex(sid) == null) continue;
        const fl = state.model.trackFlow(pi, ri);
        const flow_styled = if (fl) |f| f.style != .none else false;
        const flow_lead = if (fl) |f| state.model.flowLeading(f) else null;
        if (flow_styled and flow_lead == null) {
            // The flow style's leading is its font's own: auto.
            if (styleLinePitch(sid)) |lp| if (rg.leading != null or @abs(lp - rg.pitch) > 1e-6) {
                _ = hist.join(&state.model, .setLeading, .{ pi, ri, null, lp }) catch {};
            };
            continue;
        }
        const lead = if (flow_styled) flow_lead else rg.leading;
        const want = if (lead) |l| (l.resolve(styleEmMm(sid)) orelse continue) else continue;
        if (!(want > 0.01) or @abs(want - rg.pitch) < 1e-9) continue;
        _ = hist.join(&state.model, .setLeading, .{ pi, ri, lead, want }) catch {};
    };
}

// Style templates and flow styles (decided 2026-11-23, the owner; shared
// styles with overrides, after FrameMaker's catalogs, the same evening) --
//
// A document has style templates, Default first. A template holds a text
// style, a paragraph style and a leading: the document's own, shared by
// every flow made from it, so changing them changes all those flows. A
// flow may override them (Properties, Flow style: fields marked *): a text
// style of its own based on the template's, a copy of its paragraph style,
// a leading of its own. "Update style for all flows" puts a flow's
// overrides into its template; "Clear overrides" drops them.

/// The Default style template, made (in the step under way) when the
/// document has none: the label style, a paragraph style of plain
/// settings, the font's own leading.
fn defaultTemplate() !layout.model.ObjectId {
    if (state.model.templates.items.len > 0) return state.model.templates.items[0].id;
    const text = try labelStyle();
    const para = try hist.join(&state.model, .addParagraphStyle, .{layout.model.ParagraphStyle{ .name = "Default paragraph" }});
    return try hist.join(&state.model, .addStyleTemplate, .{ "Default", text, @as(?layout.model.ParaId, para), @as(?layout.model.Leading, null) });
}

/// Gives the flow of text layout `ri` of panel `pi` the styles of
/// template `tid` (null: the Default), with no overrides, joined to the
/// step under way.
fn styleFlowFrom(pi: Parent, ri: usize, tid: ?layout.model.ObjectId) !void {
    const m = &state.model;
    const fid = (m.trackFlow(pi, ri) orelse return).id;
    const id = tid orelse try defaultTemplate();
    const t = (m.styleTemplate(id) orelse return).*;
    _ = try hist.join(m, .setFlowStyle, .{ fid, t.text, t.paragraph, @as(?layout.model.Leading, null), id });
}

fn styleNewFlow(pi: Parent, ri: usize) !void {
    try styleFlowFrom(pi, ri, null);
}

/// The flow of track `ri` of panel `pi`, when it has a flow style.
fn flowStyled(pi: Parent, ri: usize) ?*const layout.model.Flow {
    const head = state.model.threadHead(pi, ri);
    const fl = state.model.trackFlow(head.parent, head.region) orelse return null;
    if (fl.style == .none or state.model.styleIndex(fl.style) == null) return null;
    return fl;
}

/// The template flow `fl` takes its styles from, if it has one.
fn flowTemplate(fl: *const layout.model.Flow) ?layout.model.StyleTemplate {
    return if (state.model.styleTemplate(fl.template)) |t| t.* else null;
}

/// What a flow overrides of its template.
const Overrides = struct {
    size: bool = false,
    paragraph: bool = false,
    leading: bool = false,

    fn any(o: Overrides) bool {
        return o.size or o.paragraph or o.leading;
    }
};

fn flowOverrides(fl: *const layout.model.Flow) Overrides {
    const m = &state.model;
    const t = flowTemplate(fl) orelse return .{};
    const para = if (fl.paragraph_default == t.paragraph) false else if (fl.paragraph_default) |own| (if (t.paragraph) |tp| (if (m.paraStyle(own)) |a| (if (m.paraStyle(tp)) |b| !paraSame(a.*, b.*) else true) else false) else true) else true;
    return .{
        .size = fl.style != t.text and m.styleIndex(t.text) != null and @abs(styleEmMm(fl.style) - styleEmMm(t.text)) > 1e-6,
        .paragraph = para,
        .leading = fl.leading != null,
    };
}

/// Whether two paragraph styles set the same (their names aside).
fn paraSame(a: layout.model.ParagraphStyle, b: layout.model.ParagraphStyle) bool {
    var x = a;
    const y = b;
    x.name = y.name;
    x.id = y.id;
    return std.meta.eql(x, y);
}

/// Flow `fid`'s own text style: made (based on its template's, joined to
/// the step under way) when it takes the template's.
fn flowOwnText(fid: layout.model.ObjectId) !layout.model.StyleId {
    const m = &state.model;
    const fl = &m.flows.items[m.flowIndex(fid) orelse return error.NoSuchObject];
    const t = flowTemplate(fl) orelse return fl.style;
    if (fl.style != t.text) return fl.style;
    var nb: [128]u8 = undefined;
    const name = std.fmt.bufPrint(&nb, "{s} text", .{fl.name}) catch "Flow text";
    // One made for it before and since let go, else a new one.
    const own = blk: {
        for (m.styles.items) |st| if (st.base == t.text and std.mem.eql(u8, st.name, name)) break :blk st.id;
        break :blk try hist.join(m, .deriveStyle, .{ t.text, name });
    };
    const f2 = m.flows.items[m.flowIndex(fid).?];
    _ = try hist.join(m, .setFlowStyle, .{ fid, own, f2.paragraph_default, f2.leading, f2.template });
    return own;
}

/// Flow `fid`'s own paragraph style: a copy of its template's, made
/// (joined to the step under way) when it takes the template's.
fn flowOwnParagraph(fid: layout.model.ObjectId) !?layout.model.ParaId {
    const m = &state.model;
    const fl = &m.flows.items[m.flowIndex(fid) orelse return error.NoSuchObject];
    const t = flowTemplate(fl) orelse return fl.paragraph_default;
    if (fl.paragraph_default != t.paragraph) return fl.paragraph_default;
    const src = t.paragraph orelse return null;
    var nb: [128]u8 = undefined;
    const name = std.fmt.bufPrint(&nb, "{s} paragraph", .{fl.name}) catch "Flow paragraph";
    const own = blk: {
        for (m.paragraph_styles.items) |ps| if (std.mem.eql(u8, ps.name, name)) break :blk ps.id;
        break :blk try hist.join(m, .copyParagraphStyle, .{ src, name });
    };
    const f2 = m.flows.items[m.flowIndex(fid).?];
    _ = try hist.join(m, .setFlowStyle, .{ fid, f2.style, @as(?layout.model.ParaId, own), f2.leading, f2.template });
    return own;
}

/// A style template: its name, its text size, its leading and its
/// paragraph settings, shared by every flow made from it (those that
/// override one keep their own).
fn templateProperties(id: layout.model.ObjectId) !void {
    const m = &state.model;
    const t = (m.styleTemplate(id) orelse return).*;
    if (textProp("Name", t.name, 1)) |name| _ = try act(.renameStyleTemplate, .{ id, name });
    if (m.styleIndex(t.text)) |si| propText("Text style", "{s}", .{m.styles.items[si].name}, 2);
    if (m.styleIndex(t.text) != null) try styleSizeProps(t.text, false);
    {
        var buf: [48]u8 = undefined;
        const shown = if (t.leading) |l| l.format(&buf) else "auto";
        if (textProp("Leading", shown, 4)) |typed| {
            if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, typed, " "), "auto")) {
                _ = try act(.setTemplateLeading, .{ id, @as(?layout.model.Leading, null) });
            } else if (layout.units.Quantity.parse(typed, .pt)) |l| {
                if ((l.resolve(styleEmMm(t.text)) orelse 0) > 0.01) {
                    _ = try act(.setTemplateLeading, .{ id, @as(?layout.model.Leading, l) });
                } else state.status = "That leading is too small: baselines must be apart. ";
            } else state.status = "Leading reads as 12pt, 5mm, +2pt, +3mm, +10% or 120% (auto: the font's own). ";
        }
    }
    if (t.paragraph) |pid| if (m.paraStyle(pid)) |p| {
        var ps = p.*;
        if (paragraphFields(&ps, 2000, null)) _ = try actM(mergeKey(.{ "paragraph style", pid }), .setParagraphStyle, .{ pid, ps });
    };
    var n: usize = 0;
    var own: usize = 0;
    for (m.flows.items) |*f| {
        if (f.template != id) continue;
        n += 1;
        if (flowOverrides(f).any()) own += 1;
    }
    propText("Flows made from it", "{d}", .{n}, 5);
    propText("Flows overriding it", "{d}", .{own}, 6);
}

/// The track the flow-style buttons act on: the context's, else the
/// flow cursor's.
fn flowStyleTrack() ?struct { Parent, usize } {
    return switch (state.context) {
        .region => |r| .{ r.parent, r.region },
        else => if (track_cursor) |c| .{ c.parent, c.region } else null,
    };
}

/// Drops the flow's overrides: it takes its template's styles again.
fn flowStyleClear() void {
    const tr = flowStyleTrack() orelse return;
    const fl = flowStyled(tr[0], tr[1]) orelse return;
    const t = flowTemplate(fl) orelse {
        state.status = "This flow has no template: Save as template makes one. ";
        return;
    };
    if (!flowOverrides(fl).any() and fl.style == t.text and fl.paragraph_default == t.paragraph) {
        state.status = "This flow overrides nothing of its template. ";
        return;
    }
    act(.setFlowStyle, .{ fl.id, t.text, t.paragraph, @as(?layout.model.Leading, null), t.id }) catch {
        state.status = "The overrides were not cleared. ";
        return;
    };
    state.status = "Overrides cleared: the flow takes its template's styles. ";
}

/// Puts the flow's overrides into its template (FrameMaker's Update All):
/// every flow made from it that does not override them follows.
fn flowStyleUpdateAll() void {
    const tr = flowStyleTrack() orelse return;
    const fl = flowStyled(tr[0], tr[1]) orelse return;
    const t = flowTemplate(fl) orelse {
        state.status = "This flow has no template: Save as template makes one. ";
        return;
    };
    if (!flowOverrides(fl).any()) {
        state.status = "This flow overrides nothing of its template. ";
        return;
    }
    updateTemplate(fl.id, t) catch {
        state.status = "The template was not updated. ";
        return;
    };
    state.status = "Template updated: every flow made from it follows. ";
}

fn updateTemplate(fid: layout.model.ObjectId, t: layout.model.StyleTemplate) !void {
    const m = &state.model;
    const f = m.flows.items[m.flowIndex(fid) orelse return];
    hist.beginStep();
    if (f.style != t.text) {
        const own = m.textStyle(f.style).*;
        if (own.em_size) |em| try hist.join(m, .setEmSize, .{ t.text, em }) else try hist.join(m, .setCapHeight, .{ t.text, own.cap_height });
    }
    if (f.paragraph_default) |pid| if (t.paragraph) |tp| if (pid != tp) {
        if (m.paraStyle(pid)) |own| if (m.paraStyle(tp)) |shared| {
            var ps = own.*;
            ps.name = shared.name;
            _ = try hist.join(m, .setParagraphStyle, .{ tp, ps });
        };
    };
    if (f.leading) |l| _ = try hist.join(m, .setTemplateLeading, .{ t.id, @as(?layout.model.Leading, l) });
    _ = try hist.join(m, .setFlowStyle, .{ fid, t.text, t.paragraph, @as(?layout.model.Leading, null), t.id });
}

/// A new style template from the flow's style; the flow then takes it.
fn flowStyleSaveTemplate() void {
    const tr = flowStyleTrack() orelse return;
    const fl = flowStyled(tr[0], tr[1]) orelse return;
    saveTemplate(fl.id) catch {
        state.status = "The style template was not made. ";
        return;
    };
    state.status = "Saved as a style template: new flows can be made from it. ";
}

fn saveTemplate(fid: layout.model.ObjectId) !void {
    const m = &state.model;
    const f = m.flows.items[m.flowIndex(fid) orelse return];
    const lead = m.flowLeading(&f);
    var nb: [32]u8 = undefined;
    const tname = m.freshName(&nb, .flows, "Template");
    var b1: [64]u8 = undefined;
    const text = try act(.copyStyle, .{ f.style, std.fmt.bufPrint(&b1, "{s} text", .{tname}) catch "Template text" });
    var b2: [64]u8 = undefined;
    const para: ?layout.model.ParaId = if (f.paragraph_default) |p| try hist.join(m, .copyParagraphStyle, .{ p, std.fmt.bufPrint(&b2, "{s} paragraph", .{tname}) catch "Template paragraph" }) else null;
    const tid = try hist.join(m, .addStyleTemplate, .{ tname, text, para, lead });
    _ = try hist.join(m, .setFlowStyle, .{ fid, text, para, @as(?layout.model.Leading, null), tid });
}

/// The flow style: its template (choosing another takes that one's
/// styles), and its text size, leading and paragraph settings, each the
/// template's unless the flow overrides it (marked *); Update style for
/// all flows, Clear overrides, Save as template.
fn flowStyleProperties(pi: Parent, ri: usize) !void {
    const fl = flowStyled(pi, ri) orelse return;
    const saved_group = pushGroup("flow-style");
    defer popGroup(saved_group);
    const m = &state.model;
    heading("Flow style", .{}, 3000);
    // Its own box: the fields it shares with Text style and Paragraph
    // keep ids apart from theirs.
    var box = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal, .id_extra = 3000 });
    defer box.deinit();
    const fid = fl.id;
    const t = flowTemplate(fl);
    const o = flowOverrides(fl);
    if (m.templates.items.len > 0) {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3001 });
        defer row.deinit();
        prop_marked = o.any();
        propName("From template");
        const a = dvui.currentWindow().arena();
        const names = try a.alloc([]const u8, m.templates.items.len);
        var choice: usize = 0;
        for (m.templates.items, names, 0..) |tt, *n, k| {
            n.* = tt.name;
            if (tt.id == fl.template) choice = k;
        }
        if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 3001 })) {
            const tt = m.templates.items[choice];
            _ = try act(.setFlowStyle, .{ fid, tt.text, tt.paragraph, @as(?layout.model.Leading, null), tt.id });
            return;
        }
    }
    if (t != null and o.any()) {
        actionButton(@src(), "flow-style.update-style-for-all-flows", null, 0, .{ .expand = .horizontal, .id_extra = 3002 });
        actionButton(@src(), "flow-style.clear-overrides", null, 0, .{ .expand = .horizontal, .id_extra = 3003 });
    }
    actionButton(@src(), "flow-style.save-as-template", null, 0, .{ .expand = .horizontal, .id_extra = 3006 });
    // Its text size: an override makes it a text style of its own.
    if (styleSizeFields(fl.style, false, o.size)) |e| {
        hist.beginStep();
        const own = try flowOwnText(fid);
        try joinSize(own, e);
        return;
    }
    // Its leading, kept as typed; "auto" takes the template's.
    {
        const em = styleEmMm(fl.style);
        var buf: [48]u8 = undefined;
        const shown = if (m.flowLeading(fl)) |l| l.format(&buf) else "auto";
        prop_marked = o.leading;
        if (textProp(asElement("track.leading"), shown, 3004)) |typed| {
            if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, typed, " "), "auto")) {
                _ = try act(.setFlowStyle, .{ fid, fl.style, fl.paragraph_default, @as(?layout.model.Leading, null), fl.template });
            } else if (layout.units.Quantity.parse(typed, .pt)) |l| {
                if ((l.resolve(em) orelse 0) > 0.01) {
                    _ = try act(.setFlowStyle, .{ fid, fl.style, fl.paragraph_default, @as(?layout.model.Leading, l), fl.template });
                } else state.status = "That leading is too small: baselines must be apart. ";
            } else state.status = "Leading reads as 12pt, 5mm, +2pt, +3mm, +10% or 120% (auto: the template's). ";
            return;
        }
        const region = m.regionsIn(pi)[ri];
        const pt = region.pitch / layout.model.mm_per_pt;
        const em_pt = em / layout.model.mm_per_pt;
        const extra = pt - em_pt;
        propText(asElement("track.baselines"), "{d:.2} mm ({d:.1} pt; size {d:.1} pt {s} {d:.1})", .{ region.pitch, pt, em_pt, if (extra >= 0) "+" else "−", @abs(extra) }, 3005);
    }
    // The paragraph settings its paragraphs take (each may have its own
    // style instead: Paragraph, below); an override makes them a copy.
    if (fl.paragraph_default) |pid| if (m.paraStyle(pid)) |p| {
        var ps = p.*;
        const ref: ?*const layout.model.ParagraphStyle = if (t) |tt| (if (tt.paragraph) |tp| m.paraStyle(tp) else null) else null;
        if (paragraphFields(&ps, 2000, ref)) {
            hist.beginStep();
            const own = (try flowOwnParagraph(fid)) orelse return;
            ps.name = (m.paraStyle(own) orelse return).name;
            _ = try hist.join(m, .setParagraphStyle, .{ own, ps });
        }
    };
}

/// A text layout's leading: typed fixed ("12pt", "5mm") or relative to
/// its style's font size ("+2pt", "+3mm", "+10%", "120%"); "auto" for the
/// style's own line spacing. Below it, what it comes to.
fn leadingProps(pi: Parent, ri: usize) void {
    const region = state.model.regionsIn(pi)[ri];
    const sid = region.style orelse return;
    if (state.model.styleIndex(sid) == null) return;
    const em = styleEmMm(sid);
    var buf: [48]u8 = undefined;
    const shown = if (region.leading) |l| l.format(&buf) else "auto";
    if (textProp(asElement("track.leading"), shown, 4)) |typed| {
        if (std.ascii.eqlIgnoreCase(std.mem.trim(u8, typed, " "), "auto")) {
            if (styleLinePitch(sid)) |p| act(.setLeading, .{ pi, ri, null, p }) catch {};
        } else if (layout.units.Quantity.parse(typed, .pt)) |l| {
            act(.setLeading, .{ pi, ri, l, l.resolve(em) orelse 0 }) catch {
                state.status = "That leading is too small: baselines must be apart. ";
            };
        } else state.status = "Leading reads as 12pt, 5mm, +2pt, +3mm, +10% or 120% (auto: the style's own). ";
    }
    const pt = region.pitch / layout.model.mm_per_pt;
    const em_pt = em / layout.model.mm_per_pt;
    const extra = pt - em_pt;
    propText(asElement("track.baselines"), "{d:.2} mm ({d:.1} pt; size {d:.1} pt {s} {d:.1})", .{ region.pitch, pt, em_pt, if (extra >= 0) "+" else "−", @abs(extra) }, 4000);
}

/// A style's size, two ways: as a point size (its em, as other software
/// gives it) and as cap height (Graven's own), each shown as its font
/// resolves it. Typing either sets the style by that one; the one that
/// sets it is shown plain, the other muted.
fn styleSizeProps(sid: layout.model.StyleId, default: bool) !void {
    if (styleSizeFields(sid, default, null)) |e| applySize(sid, e);
}

/// A size typed into `styleSizeFields`.
const SizeEdit = union(enum) { em: f64, cap: f64 };

fn applySize(sid: layout.model.StyleId, e: SizeEdit) void {
    switch (e) {
        .em => |em| act(.setEmSize, .{ sid, em }) catch {},
        .cap => |c| act(.setCapHeight, .{ sid, c }) catch {},
    }
    if (state.label_style == sid) state.label_style_set = true;
}

/// As `applySize`, joined to the step under way.
fn joinSize(sid: layout.model.StyleId, e: SizeEdit) !void {
    switch (e) {
        .em => |em| try hist.join(&state.model, .setEmSize, .{ sid, em }),
        .cap => |c| try hist.join(&state.model, .setCapHeight, .{ sid, c }),
    }
}

/// The size fields of `styleSizeProps`; what was typed, not applied.
/// `marked`: both shown as overrides.
fn styleSizeFields(sid: layout.model.StyleId, default: bool, marked: ?bool) ?SizeEdit {
    var edit: ?SizeEdit = null;
    const style = state.model.textStyle(sid).*;
    const ctx = if (state.labels) |*l| l.context(sid) else null;
    const cap = if (ctx) |c| c.cap_height else style.cap_height;
    const em_mm = style.em_size orelse if (ctx) |c| cap * @as(f64, @floatFromInt(c.text.upem)) / layout.legend.capUnits(c.text) else cap / layout.model.cap_per_em;
    const by_em = style.em_size != null;
    const muted: dvui.Options = .{ .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.6) } };
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 1 });
        defer row.deinit();
        prop_marked = marked orelse false;
        propName("Size, pt");
        const pt0 = @round(em_mm / layout.model.mm_per_pt * 100) / 100;
        const opts: dvui.Options = .{ .expand = .horizontal, .font = styled(.theme(.body), default), .id_extra = 1 };
        if (accepted.numberField(@src(), f64, pt0, 0.5, 2000, if (by_em) opts else opts.override(muted))) |pt| edit = .{ .em = pt * layout.model.mm_per_pt };
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 2 });
        defer row.deinit();
        prop_marked = marked orelse false;
        propName("Cap height, mm");
        const c0 = @round(cap * 1000) / 1000;
        const opts: dvui.Options = .{ .expand = .horizontal, .font = styled(.theme(.body), default), .id_extra = 2 };
        if (accepted.numberField(@src(), f64, c0, 0.1, 200, if (by_em) opts.override(muted) else opts)) |c| edit = .{ .cap = c };
    }
    return edit;
}

/// A new plain prototype with one track and keycap art, made the context.
fn addPrototype() !void {
    var name_buf: [32]u8 = undefined;
    const name = state.model.freshName(&name_buf, .prototypes, "Prototype");
    var p: layout.model.TilePrototype = .{
        .name = name,
        .unit = 19.05,
        .body_inset = .all(0.5),
        .face_inset = .all(2),
        // In the document's first style, as `ensurePrototype` makes one.
        .tracks = &.{.{ .name = "top", .style = if (state.model.styles.items.len > 0) state.model.styles.items[0].id else try labelStyle(), .place = .{ .inset = .all(0.8) } }},
    };
    p.art = try layout.art.redrawKeycap(dvui.currentWindow().arena(), p, protoUnit(p));
    const id = try act(.addPrototype, .{p});
    state.context = .{ .prototype = id };
}

fn duplicatePrototype(id: layout.model.PrototypeId) !void {
    var name_buf: [64]u8 = undefined;
    var ib: [96]u8 = undefined;
    var cb: [100]u8 = undefined;
    const stem = std.fmt.bufPrint(&cb, "{s}Copy", .{layout.names.identifier(&ib, state.model.proto(id).name, "Prototype")}) catch "PrototypeCopy";
    const name = state.model.freshOrSame(&name_buf, .prototypes, stem, "PrototypeCopy");
    state.context = .{ .prototype = try act(.duplicatePrototype, .{id, name}) };
}

/// An editable text property. Returns the new text once accepted (Enter,
/// or leaving the field), not empty; the model copies it.
fn textProp(name: []const u8, value: []const u8, n: usize) ?[]const u8 {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(name);
    return accepted.textField(@src(), value, .{ .expand = .horizontal, .id_extra = n }, .{}, accepted.nonEmpty);
}

/// A list of sizes typed as "1, 1.25, 2"; empty allows any. Returns the new
/// list once what is typed reads as one.
fn sizesProp(name: []const u8, shown: []const u8, n: usize) ?[]const f64 {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(name);
    // Shown without the unit, as typed.
    const value = if (std.mem.eql(u8, shown, "any")) "" else std.mem.trimEnd(u8, shown, " u");
    var te = dvui.textEntry(@src(), .{ .text_initial = value }, .{ .expand = .horizontal, .id_extra = n });
    defer te.deinit();
    const typed = accepted.accept(te, value) orelse return null;
    var list: std.ArrayList(f64) = .empty;
    var it = std.mem.tokenizeAny(u8, typed, ", ");
    while (it.next()) |tok| {
        const v = std.fmt.parseFloat(f64, tok) catch {
            accepted.reject(te);
            return null;
        };
        if (!(v > 0)) {
            accepted.reject(te);
            return null;
        }
        list.append(dvui.currentWindow().arena(), v) catch return null;
    }
    return list.items;
}

/// Four insets, left, right, top and bottom, mm. Returns them when one
/// changes.
fn sidesEditor(name: []const u8, sides: layout.model.Sides, n: usize) ?layout.model.Sides {
    var s = sides;
    var changed = false;
    var label_buf: [4][48]u8 = undefined;
    inline for (.{ "left", "right", "top", "bottom" }, 0..) |side, i| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n * 8 + i });
        defer row.deinit();
        propName(std.fmt.bufPrint(&label_buf[i], "{s} {s}, mm", .{ name, side }) catch name);
        if (accepted.numberField(@src(), f64, @field(s, side), 0, 100, .{ .expand = .horizontal, .id_extra = n * 8 + i })) |v| {
            @field(s, side) = v;
            changed = true;
        }
    }
    return if (changed) s else null;
}

/// "1, 1.25, 2 u", or "any" for an empty list.
fn sizeList(buf: []u8, sizes: []const f64) []const u8 {
    if (sizes.len == 0) return "any";
    var w: std.Io.Writer = .fixed(buf);
    for (sizes, 0..) |s, i| w.print("{s}{d}", .{ if (i > 0) ", " else "", s }) catch break;
    w.writeAll(" u") catch {};
    return w.buffered();
}

/// A style choice. With `inherited` (a tile's slot), the first entry takes
/// the prototype's style and `own` is the tile's, if any; without, `own` is
/// the style itself. Returns the choice when it changes: a style, or null
/// for the prototype's.
fn styleChoice(own: ?layout.model.StyleId, inherited: ?layout.model.StyleId, n: usize) ??layout.model.StyleId {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName("Style");
    const styles = state.model.styles.items;
    if (styles.len == 0 or styles.len > 31) {
        dvui.labelNoFmt(@src(), "none", .{}, .{});
        return null;
    }
    var bufs: [32][64]u8 = undefined;
    var names: [32][]const u8 = undefined;
    const first: usize = if (inherited != null) 1 else 0;
    if (inherited) |s| names[0] = std.fmt.bufPrint(&bufs[0], "Prototype's: {s}", .{if (state.model.styleIndex(s)) |x| styles[x].name else "?"}) catch "Prototype's";
    for (styles, 0..) |s, i| names[first + i] = std.fmt.bufPrint(&bufs[first + i], "{s}", .{s.name}) catch "?";
    var choice: usize = if (own) |s| first + (state.model.styleIndex(s) orelse 0) else 0;
    const before = choice;
    if (!tdropdown(@src(), names[0 .. first + styles.len], .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = n }) or choice == before) return null;
    if (choice < first) return @as(?layout.model.StyleId, null);
    return @as(?layout.model.StyleId, styles[choice - first].id);
}

// Process profiles --------------------------------------------------------------
//
// How panels are made (see layout's process.zig): the document's profiles in
// the Browser, each with its class, its process's parameters and its limits
// (from the parameters, or overridden), and a panel's choice of one in its
// Fabrication.

const process = layout.model.process;

/// The document's profiles: how many, and new ones from the built-ins.
fn processesProperties() void {
    const saved_group = pushGroup("processes");
    defer popGroup(saved_group);
    propText("Profiles", "{d}", .{state.model.processes.items.len}, 1);
    heading("Add a profile", .{}, 10);
    for (process.builtins, 0..) |b, i| {
        keyButton(@src(), b.name, @intCast(i), .{ .expand = .horizontal, .id_extra = 11 + i, .tag = listTag("processes.builtin", b.name) });
    }
}

/// `name` with a number after it when the document has a profile so named.
fn uniqueProcessName(buf: []u8, name: []const u8) []const u8 {
    var n: usize = 1;
    var candidate = name;
    while (for (state.model.processes.items) |pr| {
        if (std.mem.eql(u8, pr.profile.name, candidate)) break true;
    } else false) : (n += 1) candidate = std.fmt.bufPrint(buf, "{s} ({d})", .{ name, n + 1 }) catch return name;
    return candidate;
}

/// A band's two ends, typed: an override once either is changed.
fn bandProps(what: []const u8, own: ?process.Band, derived: process.Band, n: usize) ??process.Band {
    var b = own orelse derived;
    var changed = false;
    var lb: [64]u8 = undefined;
    if (numberProp(std.fmt.bufPrint(&lb, "{s} passes at, mm", .{what}) catch what, b.pass, 0, 1000, n)) |v| {
        b.pass = v;
        changed = true;
    }
    if (numberProp(std.fmt.bufPrint(&lb, "{s} fails below, mm", .{what}) catch what, b.fail, 0, 1000, n + 1)) |v| {
        b.fail = v;
        changed = true;
    }
    return if (changed) @as(?process.Band, b) else null;
}

/// A profile: its name, class and process, the process's parameters, its
/// limits (each from the parameters unless overridden), the panels made
/// with it, and its removal.
fn processProperties(id: layout.model.ObjectId) void {
    const saved_group = pushGroup("process");
    defer popGroup(saved_group);
    const i = state.model.processIndex(id) orelse return;
    const p = state.model.processes.items[i].profile;
    var next = p;
    var changed = false;
    var key: u64 = mergeKey(.{ "process", id });
    if (textProp("Name", p.name, 1)) |v| {
        next.name = v;
        changed = true;
        key = mergeKey(.{ "process name", id });
    }
    propText("Class", "{s}", .{p.class().label()}, 2);
    propText("Process", "{s}", .{p.kind().label()}, 3);
    switch (p.params) {
        .fdm => |f| {
            heading("FDM", .{}, 10);
            var fdm = f;
            inline for (.{
                .{ "Nozzle, mm", "nozzle", 0.05, 5.0 },
                .{ "Line width, mm", "line_width", 0.05, 5.0 },
                .{ "Layer height, mm", "layer_height", 0.01, 2.0 },
                .{ "First layer, mm", "first_layer", 0.01, 2.0 },
            }, 0..) |fld, k| {
                if (numberProp(fld[0], @field(f, fld[1]), fld[2], fld[3], 11 + k)) |v| {
                    @field(fdm, fld[1]) = v;
                    changed = true;
                    key = mergeKey(.{ "process", id, fld[1] });
                }
            }
            if (numberProp("Filament slots", @floatFromInt(f.slots), 1, 64, 16)) |v| {
                fdm.slots = @intFromFloat(@round(v));
                changed = true;
                key = mergeKey(.{ "process", id, "slots" });
            }
            inline for (.{ "across", "deep", "high" }, 0..) |axis, k| {
                if (numberProp("Build volume " ++ axis ++ ", mm", f.build[k], 1, 10000, 17 + k)) |v| {
                    fdm.build[k] = v;
                    changed = true;
                    key = mergeKey(.{ "process", id, "build", k });
                }
            }
            next.params = .{ .fdm = fdm };
        },
        inline .laser_cut, .laser_engrave, .waterjet => |x, tag| {
            heading("{s}", .{p.kind().label()}, 10);
            var nx = x;
            const fields = switch (tag) {
                .laser_cut => .{ .{ "Kerf, mm", "kerf" }, .{ "Spot, mm", "spot" }, .{ "Thickest sheet, mm", "max_thickness" } },
                .laser_engrave => .{ .{ "Spot, mm", "spot" }, .{ "Depth a pass, mm", "depth_per_pass" } },
                .waterjet => .{ .{ "Kerf, mm", "kerf" }, .{ "Thickest plate, mm", "max_thickness" } },
                else => unreachable,
            };
            inline for (fields, 0..) |fld, k| {
                if (numberProp(fld[0], @field(x, fld[1]), 0.001, 1000, 11 + k)) |v| {
                    @field(nx, fld[1]) = v;
                    changed = true;
                    key = mergeKey(.{ "process", id, fld[1] });
                }
            }
            inline for (.{ "across", "deep" }, 0..) |axis, k| {
                if (numberProp("Bed " ++ axis ++ ", mm", x.bed[k], 1, 10000, 17 + k)) |v| {
                    nx.bed[k] = v;
                    changed = true;
                    key = mergeKey(.{ "process", id, "bed", k });
                }
            }
            next.params = @unionInit(layout.model.process.Params, @tagName(tag), nx);
        },
    }
    heading("Limits", .{}, 30);
    const own = p.stroke != null or p.gap != null or p.cap != null;
    propValue("Set by", !own, "{s}", .{if (own) "this profile, in part" else "the process's settings"}, 31);
    const d = process.derived(p.params);
    inline for (.{ .{ "Stroke", "stroke" }, .{ "Gap", "gap" }, .{ "Cap height", "cap" } }, 0..) |lim, k| {
        if (bandProps(lim[0], @field(p, lim[1]), @field(d, lim[1]), 32 + 2 * k)) |b| {
            @field(next, lim[1]) = b;
            changed = true;
            key = mergeKey(.{ "process", id, lim[1] });
        }
    }
    const l = p.limits();
    if (l.layer) |lh| propText("Depths", "whole layers of {d} mm, {d} at least", .{ lh, l.min_layers }, 40);
    propText("Colours", "{d} at most in a part", .{l.colours}, 41);
    if (own) keyButton(@src(), "Use the limits its settings give", 0, .{ .expand = .horizontal, .id_extra = 42 });
    if (changed) {
        const done = if (key != 0) actM(key, .setProcess, .{ id, next }) else act(.setProcess, .{ id, next });
        done catch {
            state.status = "Those settings cannot be made with (a size not above 0, or a limit failing above where it passes). ";
        };
    }
    heading("Used by", .{}, 50);
    var used: usize = 0;
    for (state.model.panels.items, 0..) |pn, pi| if (pn.fab.process == id) {
        keyButton(@src(), pn.name, @intCast(pi), .{ .expand = .horizontal, .id_extra = 51 + pi, .tag = listTag("process.panel", pn.name) });
        used += 1;
    };
    if (used == 0) {
        propText("Panels", "none", .{}, 49);
        keyButton(@src(), "Remove this profile", 0, .{ .expand = .horizontal, .id_extra = 48, .margin = .{ .y = 8 } });
    }
}

/// A panel's process: the document's profiles, then the built-ins it has
/// not yet (chosen, one is added to the document and used, one step).
fn panelProcessChoice(pi: usize) void {
    const ar = dvui.currentWindow().arena();
    var names: std.ArrayList([]const u8) = .empty;
    var ids: std.ArrayList(?layout.model.ObjectId) = .empty;
    var adds: std.ArrayList(?usize) = .empty;
    names.append(ar, "none") catch return;
    ids.append(ar, .none) catch return;
    adds.append(ar, null) catch return;
    for (state.model.processes.items) |pr| {
        names.append(ar, pr.profile.name) catch return;
        ids.append(ar, pr.id) catch return;
        adds.append(ar, null) catch return;
    }
    for (process.builtins, 0..) |b, k| {
        const have = for (state.model.processes.items) |pr| {
            if (std.mem.eql(u8, pr.profile.name, b.name)) break true;
        } else false;
        if (have) continue;
        names.append(ar, std.fmt.allocPrint(ar, "{s} (built in)", .{b.name}) catch return) catch return;
        ids.append(ar, null) catch return;
        adds.append(ar, k) catch return;
    }
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 398 });
    defer row.deinit();
    propName("Process");
    const current = state.model.panels.items[pi].fab.process;
    var choice: usize = 0;
    for (ids.items, 0..) |x, k| {
        if (x != null and x.? == current) choice = k;
    }
    const before = choice;
    if (!tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) or choice == before) return;
    if (adds.items[choice]) |k| {
        const key = mergeKey(.{ "panel process", pi, k, state.model.processes.items.len });
        const id = actM(key, .addProcess, .{process.builtins[k]}) catch return;
        actM(key, .setPanelProcess, .{ pi, id }) catch {};
    } else act(.setPanelProcess, .{ pi, ids.items[choice].? }) catch {};
}

/// The document's text styles: how many, and new ones: a plain style, or
/// one from a math font package (its faces and rules), to base others on.
fn stylesProperties() !void {
    const saved_group = pushGroup("styles");
    defer popGroup(saved_group);
    propText("Text styles", "{d}", .{state.model.styles.items.len}, 1);
    keyButton(@src(), "Add a style", 0, .{ .expand = .horizontal, .id_extra = 2, .margin = .{ .y = 6 } });
    heading("From a math package", .{}, 10);
    for (layout.fonts.packages, 0..) |pkg, i| {
        var lb: [64]u8 = undefined;
        keyButton(@src(), std.fmt.bufPrint(&lb, "Add a {s} style", .{pkg.name}) catch pkg.name, @intCast(i), .{ .expand = .horizontal, .id_extra = 11 + i , .tag = listTag("styles.package", pkg.name)});
    }
}

fn styleNamed(name: []const u8) ?layout.model.StyleId {
    for (state.model.styles.items) |st| if (std.mem.eql(u8, st.name, name)) return st.id;
    return null;
}

/// A text style: its name, what it is based on, its size and line pitch,
/// its text face (by family and style, as the document names it), its
/// other faces, and its rules.
fn styleProperties(sid: layout.model.StyleId) !void {
    const saved_group = pushGroup("style");
    defer popGroup(saved_group);
    const si = state.model.styleIndex(sid) orelse return;
    const st = state.model.styles.items[si];
    if (textProp("Name", st.name, 1)) |name| actM(mergeKey(.{ "style name", sid }), .renameStyle, .{ sid, name }) catch {};
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 2 });
        defer row.deinit();
        propName("Based on");
        const ar = dvui.currentWindow().arena();
        var names: std.ArrayList([]const u8) = .empty;
        var ids: std.ArrayList(layout.model.StyleId) = .empty;
        try names.append(ar, "nothing");
        try ids.append(ar, .none);
        for (state.model.styles.items) |o| if (o.id != sid) {
            try names.append(ar, o.name);
            try ids.append(ar, o.id);
        };
        var choice: usize = std.mem.indexOfScalar(layout.model.StyleId, ids.items, st.base) orelse 0;
        if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and ids.items[choice] != st.base) {
            act(.setStyleBase, .{ sid, ids.items[choice] }) catch {
                state.status = "That would base the style on itself. ";
            };
        }
    }
    try styleSizeProps(sid, false);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 3 });
        defer row.deinit();
        propName("Line pitch, cap heights");
        // Empty: from its text face.
        var buf: [32]u8 = undefined;
        const shown: []const u8 = if (st.line_pitch) |lp| std.fmt.bufPrint(&buf, "{d}", .{lp}) catch "" else "";
        var te = dvui.textEntry(@src(), .{ .text_initial = shown, .placeholder = "from its face" }, .{ .expand = .horizontal, .id_extra = 3 });
        defer te.deinit();
        if (accepted.accept(te, shown)) |offered| {
            const typed = std.mem.trim(u8, offered, " ");
            if (typed.len == 0) {
                act(.setLinePitch, .{ sid, @as(?f64, null) }) catch {};
            } else if (std.fmt.parseFloat(f64, typed)) |v| {
                if (v > 0) act(.setLinePitch, .{ sid, @as(?f64, v) }) catch {} else accepted.reject(te);
            } else |_| accepted.reject(te);
        }
    }
    heading("Faces", .{}, 20);
    const text_face = st.face("text");
    if (textProp("Text face family", if (text_face) |f| f.family else "", 21)) |fam| {
        actM(mergeKey(.{ "text face", sid }), .setStyleFace, .{ sid, "text", @as(?layout.model.FontName, .{ .family = fam, .style = if (text_face) |f| f.style else "Regular" }) }) catch {};
    }
    if (text_face) |tf| if (textProp("Text face style", tf.style, 22)) |sty| {
        actM(mergeKey(.{ "text face", sid }), .setStyleFace, .{ sid, "text", @as(?layout.model.FontName, .{ .family = tf.family, .style = sty }) }) catch {};
    };
    for (st.faces.items, 0..) |f, k| {
        if (std.mem.eql(u8, f.role, "text")) continue;
        propText(faceItem("style.face", f.role), "{s} {s}", .{ f.font.family, f.font.style }, 30 + k);
    }
    keyButton(@src(), "Fonts… (every face, and searching the installed fonts)", 0, .{ .expand = .horizontal, .id_extra = 29, .margin = .{ .y = 4 } });
    try styleRules(sid);
}

/// Edits how an art layer is painted: its fill's colours (one, or a
/// gradient's two ends) and its edge's colour and width. Returns the new
/// paint when it changes.
fn paintEditor(paint: layout.art.Paint, n: usize) ?layout.art.Paint {
    var p = paint;
    var changed = false;
    // The kind of fill: none, one colour, or a gradient between two; a
    // change keeps the colours it has.
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 10 });
        defer row.deinit();
        propName("Fill kind");
        const kinds = [_][]const u8{ "none", "one colour", "a gradient" };
        var choice: usize = @intFromEnum(std.meta.activeTag(p.fill));
        if (tdropdown(@src(), &kinds, .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != @intFromEnum(std.meta.activeTag(p.fill))) {
            const first: layout.art.Color = switch (p.fill) {
                .none => .hex("#ffffff"),
                .solid => |c| c,
                .linear => |l| l.start,
            };
            const last: layout.art.Color = switch (p.fill) {
                .linear => |l| l.end,
                else => first,
            };
            p.fill = switch (choice) {
                0 => .none,
                1 => .{ .solid = first },
                else => .{ .linear = .{ .from = .{ .x = 0.5, .y = 1 }, .to = .{ .x = 0.5, .y = 0 }, .start = first, .end = last } },
            };
            changed = true;
        }
    }
    if (p.fill == .linear) {
        // Its direction across the shape's box (0 to 1 each way, y up).
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 11 });
        defer row.deinit();
        propName("Gradient runs");
        const Dir = struct { name: []const u8, from: [2]f64, to: [2]f64 };
        const dirs = [_]Dir{
            .{ .name = "top to bottom (back to front)", .from = .{ 0.5, 1 }, .to = .{ 0.5, 0 } },
            .{ .name = "bottom to top", .from = .{ 0.5, 0 }, .to = .{ 0.5, 1 } },
            .{ .name = "left to right", .from = .{ 0, 0.5 }, .to = .{ 1, 0.5 } },
            .{ .name = "right to left", .from = .{ 1, 0.5 }, .to = .{ 0, 0.5 } },
        };
        var names: [dirs.len + 1][]const u8 = undefined;
        for (dirs, 0..) |d, k| names[k] = d.name;
        names[dirs.len] = "as drawn";
        const l = p.fill.linear;
        var choice: usize = dirs.len;
        for (dirs, 0..) |d, k| {
            if (l.from.x == d.from[0] and l.from.y == d.from[1] and l.to.x == d.to[0] and l.to.y == d.to[1]) choice = k;
        }
        const shown = choice;
        if (tdropdown(@src(), names[0 .. dirs.len + @intFromBool(shown == dirs.len)], .{ .choice = &choice }, .{}, .{ .expand = .horizontal }) and choice != shown and choice < dirs.len) {
            p.fill.linear.from = .{ .x = dirs[choice].from[0], .y = dirs[choice].from[1] };
            p.fill.linear.to = .{ .x = dirs[choice].to[0], .y = dirs[choice].to[1] };
            changed = true;
        }
    }
    switch (p.fill) {
        .none => propText("Fill", "none", .{}, n),
        .solid => |c| if (colourEntry("Fill", c, false, n)) |v| {
            p.fill = .{ .solid = v.? };
            changed = true;
        },
        .linear => |l| {
            if (colourEntry("Gradient from", l.start, false, n)) |v| {
                p.fill.linear.start = v.?;
                changed = true;
            }
            if (colourEntry("Gradient to", l.end, false, n + 1)) |v| {
                p.fill.linear.end = v.?;
                changed = true;
            }
        },
    }
    if (colourEntry("Edge", p.edge, true, n + 2)) |v| {
        p.edge = v;
        changed = true;
    }
    if (p.edge != null) {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n + 3 });
        defer row.deinit();
        propName("Edge width, mm");
        if (accepted.numberField(@src(), f64, p.edge_width, 0, 5, .{ .expand = .horizontal, .id_extra = n + 3 })) |v| {
            p.edge_width = v;
            changed = true;
        }
    }
    return if (changed) p else null;
}

/// A colour as "#rrggbb", with a swatch. Returns a new colour once what is
/// typed is one, or null (`allow_none`, emptied) for no colour.
fn colourEntry(name: []const u8, colour: ?layout.art.Color, allow_none: bool, n: usize) ??layout.art.Color {
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(name);
    var swatch = dvui.box(@src(), .{}, .{
        .min_size_content = .{ .w = 16, .h = 16 },
        .gravity_y = 0.5,
        .margin = .{ .w = 6 },
        .border = .all(1),
        .background = colour != null,
        .color_fill = if (colour) |c| .{ .color = .{ .r = c.r, .g = c.g, .b = c.b, .a = c.a } } else null,
    });
    swatch.deinit();
    var buf: [7]u8 = undefined;
    const text: []const u8 = if (colour) |c| c.format(&buf) else "";
    var te = dvui.textEntry(@src(), .{ .text_initial = text }, .{ .expand = .horizontal, .font = .theme(.mono), .id_extra = n });
    defer te.deinit();
    const offered = accepted.accept(te, text) orelse return null;
    const typed = std.mem.trim(u8, offered, " ");
    if (typed.len == 0) {
        if (allow_none and colour != null) return @as(?layout.art.Color, null);
        accepted.reject(te);
        return null;
    }
    const c = layout.art.Color.parse(typed) orelse {
        accepted.reject(te);
        return null;
    };
    if (colour != null and std.meta.eql(c, colour.?)) return null;
    return @as(?layout.art.Color, c);
}

/// A tile's width or height: a choice of the sizes its prototype allows
/// along that axis, a fixed 1 u where it may not grow, or the value alone
/// where any size goes. A size outside the rules stays listed, marked.
fn sizeProperty(id: TileId, axis: enum { horizontal, vertical }) !void {
    const t = state.model.tileConst(id);
    const proto = state.model.prototypeOf(id);
    const horizontal = axis == .horizontal;
    const name = if (horizontal) "Width" else "Height";
    const size = if (horizontal) t.w else t.h;
    const grows = if (horizontal) proto.expand.horizontal else proto.expand.vertical;
    const sizes = if (horizontal) proto.widths else proto.heights;
    const n: usize = if (horizontal) 2 else 7;
    if (grows and sizes.len == 0) {
        // Any size goes: typed.
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
        defer row.deinit();
        propName(if (horizontal) "Width, u" else "Height, u");
        if (accepted.numberField(@src(), f64, size, 0.25, 100, .{ .expand = .horizontal, .id_extra = n })) |v| {
            if (horizontal) try act(.setTileSize, .{id, v, t.h}) else try act(.setTileSize, .{id, t.w, v});
        }
        return;
    }
    if (!grows or sizes.len > 15) {
        const ok = proto.allows(if (horizontal) size else 1, if (horizontal) 1 else size);
        propText(name, "{d} u{s}", .{ size, if (!grows and ok) " (fixed)" else if (!ok) " (not allowed)" else "" }, n);
        return;
    }
    var bufs: [16][32]u8 = undefined;
    var names: [16][]const u8 = undefined;
    var choice: ?usize = null;
    for (sizes, 0..) |s, i| {
        names[i] = std.fmt.bufPrint(&bufs[i], "{d} u", .{s}) catch "?";
        if (@abs(s - size) <= 1e-9) choice = i;
    }
    var listed = sizes.len;
    if (choice == null) {
        names[listed] = std.fmt.bufPrint(&bufs[listed], "{d} u (not allowed)", .{size}) catch "?";
        choice = listed;
        listed += 1;
    }
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = n });
    defer row.deinit();
    propName(name);
    var picked = choice.?;
    if (tdropdown(@src(), names[0..listed], .{ .choice = &picked }, .{}, .{ .expand = .horizontal }) and picked < sizes.len) {
        if (horizontal) try act(.setTileSize, .{id, sizes[picked], t.h}) else try act(.setTileSize, .{id, t.w, sizes[picked]});
    }
}

/// The status line's fields, each always in the same place so nothing
/// jumps as values come and go: the pointer position (a dash off the
/// sheet), the counts, any tool hint or message, then the font and zoom.
fn statusContent() void {
    const saved_group = pushGroup("status");
    defer popGroup(saved_group);
    var tiles: usize = 0;
    var labels: usize = 0;
    var missing: usize = 0;
    var lacking: usize = 0;
    var overflow: usize = 0;
    for (state.solved.items) |*p| {
        tiles += p.tiles.len;
        labels += p.labels.len;
        for (p.issues) |i| switch (i.kind) {
            .missing_glyph => missing += 1,
            .variant_missing => lacking += 1,
            .label_overflow, .row_overflow, .region_outside => overflow += 1,
            else => {},
        };
    }
    const field: dvui.Options = .{ .gravity_y = 0.5, .padding = .{ .x = 8, .w = 8, .y = 2, .h = 2 } };
    const muted: dvui.Options = .{ .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.65) } };

    var pos_buf: [64]u8 = undefined;
    const u = docUnits();
    const pos = if (state.mouse) |m_sheet| blk: {
        // Shown as the rulers count: from the ruler origin (a canvas's own).
        const m = if (openCanvas()) m_sheet else state.model.sheet.toRuler(m_sheet);
        const k = u.perMm();
        break :blk switch (u) {
            .mm => std.fmt.bufPrint(&pos_buf, "x {d:.2}   y {d:.2} mm", .{ m.x * k, m.y * k }),
            .inch => std.fmt.bufPrint(&pos_buf, "x {d:.3}   y {d:.3} in", .{ m.x * k, m.y * k }),
            .mil => std.fmt.bufPrint(&pos_buf, "x {d:.0}   y {d:.0} mil", .{ m.x * k, m.y * k }),
        } catch "";
    } else std.fmt.bufPrint(&pos_buf, "x –   y – {s}", .{u.symbol()}) catch "";
    dvui.labelNoFmt(@src(), pos, .{}, field.override(.{ .min_size_content = .{ .w = 190 }, .font = .theme(.mono) }));
    {
        // The zoom against actual size; a click goes to actual size.
        var zb: [24]u8 = undefined;
        const pct = zoomPercent();
        const zt = std.fmt.bufPrint(&zb, "{d:.0} %{s}", .{ pct, if (display.measuredPxPerMm() == null) "*" else "" }) catch "";
        var zwd: dvui.WidgetData = undefined;
        keyButton(@src(), zt, 0, .{ .gravity_y = 0.5, .padding = .{ .x = 6, .w = 6, .y = 1, .h = 1 }, .margin = .{}, .font = .theme(.mono), .data_out = &zwd });
        dvui.tooltip(@src(), .{ .active_rect = zwd.borderRectScale().r }, "{s}", .{if (display.measuredPxPerMm() == null) "Zoom against actual size, estimated (View › Calibrate screen size…). Click: actual size." else "Zoom against actual size. Click: actual size."}, .{});
    }

    var counts_buf: [260]u8 = undefined;
    var flags_buf: [40]u8 = undefined;
    const layer_flags = if (state.layer_issues.len > 0) std.fmt.bufPrint(&flags_buf, " · {d} layer flag{s}", .{ state.layer_issues.len, if (state.layer_issues.len == 1) "" else "s" }) catch "" else "";
    // Only when there are any: bold or italic the font lacks.
    var lack_buf: [48]u8 = undefined;
    const lack = if (lacking > 0) std.fmt.bufPrint(&lack_buf, " · {d} lacking bold/italic", .{lacking}) catch "" else "";
    const counts = std.fmt.bufPrint(&counts_buf, "{d} panels ({d} out of compliance) · {d} tiles · {d} text pieces · {d} missing glyphs{s} · {d} overflows · {d} in margins{s}{s}", .{
        state.model.panels.items.len, state.panel_issues.len, tiles, labels, missing, lack, overflow, state.intrusions.len, layer_flags,
        if (catching_up) " · reflowing flows…" else "",
    }) catch "";
    dvui.labelNoFmt(@src(), counts, .{}, field);

    const hint = switch (state.tool) {
        .select => state.status,
        .add_panel => "Add panel: drag out its outline · Esc cancels",
        .add_art => if (shape_kind == .polygon) "Add polygon: click each corner; click the first again, or Enter, to close · Esc cancels" else "Add shape: drag out its box · Esc cancels",
        .select_area => "Select area: drag around the objects to pick · Esc cancels",
        .construction => if (guide_pending) "Construction line: click its second point (Shift: 15° steps) · Esc cancels" else "Construction line: drag from a point to another, or click both (Shift: 15° steps) · Esc ends",
        .add_tracks => if (tracks_tool.kind == .track) "Layout: single track: drag it out, right or down; content runs the way it is drawn · Esc cancels" else if (tracks_tool.major == .row) "Layout: column of rows: drag it out; content flows through its rows in order · Esc cancels" else "Layout: row of columns: drag it out; content flows through its columns in order · Esc cancels",
        .join => "Join: click the track the flow goes on into · Esc cancels",
        .add_array => (if (array_tool.polar)
            std.fmt.allocPrint(dvui.currentWindow().arena(), "Add polar array: drag from its centre out to its edge; {d} around, {d} rings · Esc cancels", .{ array_tool.around, array_tool.rings })
        else
            std.fmt.allocPrint(dvui.currentWindow().arena(), "Add array: drag out its {d} × {d} cells · Esc cancels", .{ array_tool.cols, array_tool.rows })) catch "Add array: drag out its cells · Esc cancels",
        .new_sketch => "New sketch: click where its origin goes · Esc cancels",
        .insert_figure => "Insert figure: drag out its size (its proportions kept), or click for its own size · Esc cancels",
        .constrain => if (constrain_first == null) "Constrain: click an edge, centre line or origin line of what is to move · Esc cancels" else "Constrain: click what it keeps to (its own, a peer's, or the parent's) · Esc cancels",
    };
    dvui.labelNoFmt(@src(), hint, .{}, field.override(.{ .expand = .horizontal }).override(muted));

    var right_buf: [160]u8 = undefined;
    const font = if (state.fonts.len > 0) state.fonts[state.font_choice].name else "-";
    const fa = frameAverage();
    const right = std.fmt.bufPrint(&right_buf, "{s} · {d:.1} px/mm · solve {d:.1} ms · frame {d:.1} ms", .{ font, state.view.ppm, state.solve_ms, fa.ms }) catch "";
    dvui.labelNoFmt(@src(), right, .{}, field.override(muted));
}

// Populating tracks --------------------------------------------------------
//
// A track is one flow: tiles, blanks, runs of text or equations, and hard
// breaks, poured in order through its rows or columns. With a region as
// the context, a click in its tracks puts the flow cursor between items.
// Things go in at the cursor from the insert palette, or by its keys:
// digits for tiles, the row below them for blanks, A for text or an
// equation (typed in the expression line), Enter for a hard break.
// Backspace removes the item before the cursor, Delete the one after;
// arrows move it along the flow, or to the next row or column.

/// Where things go in: before item `index` of a track's flow.
/// The flow cursor: in the flow of track `region` of `panel` (the first of
/// its thread), before item `index`, or `offset` bytes into the run there.
const TrackCursor = struct { parent: Parent, region: usize, index: usize, offset: u32 = 0 };
var track_cursor: ?TrackCursor = null;
/// Where a selection in the flow started (Shift with a movement key): it
/// runs from here to the cursor.
var flow_anchor: ?struct { index: usize, offset: u32 } = null;
/// The canvas, and the palette's buttons, from the last frame: the
/// cursor's keys work while one of them has the keyboard.
var canvas_id: ?dvui.Id = null;
var palette_ids: [24]dvui.Id = undefined;
var palette_id_count: usize = 0;
/// How opaque the palette and its buttons are over the canvas.
const palette_alpha = 0.6;
const palette_button_alpha = 0.45;


/// The prototype the insert palette's tile row inserts, once switched with
/// Tab; null for the track's own.
var palette_prototype: ?layout.model.PrototypeId = null;

/// Switches the palette's tile row to the next (or previous) prototype that
/// is not a spacer.
fn cyclePalettePrototype(back: bool) void {
    const c = track_cursor orelse return;
    const pal = paletteFor(c.parent, c.region) orelse return;
    const protos = state.model.prototypes.items;
    var at = protoPos(pal.prototype);
    for (0..protos.len) |_| {
        at = if (back) (if (at == 0) protos.len - 1 else at - 1) else (at + 1) % protos.len;
        if (!protos[at].spacer) break;
    }
    palette_prototype = protos[at].id;
}

/// The palette's choices for a region: tile lengths along its tracks (the
/// prototype's allowed sizes, or its steps from the smallest) and blank
/// lengths (multiples of its step), ten of each at most.
const InsertPalette = struct {
    prototype: layout.model.PrototypeId,
    tiles: [10]f64 = undefined,
    tile_count: usize = 0,
    blanks: [10]f64 = undefined,
};

fn paletteFor(panel: Parent, region: usize) ?InsertPalette {
    if (state.model.prototypes.items.len == 0) return null;
    const r = state.model.regionsIn(panel)[region];
    // The prototype the tile row inserts: the one chosen with Tab, else the
    // track's own.
    const own = if (r.prototype) |rp| (if (state.model.protoIndex(rp) != null) rp else state.model.prototypes.items[0].id) else state.model.prototypes.items[0].id;
    const id = if (palette_prototype) |pp| (if (state.model.protoIndex(pp) != null and !state.model.proto(pp).spacer) pp else own) else own;
    const p = state.model.proto(id).*;
    var out: InsertPalette = .{ .prototype = id };
    const sizes = if (r.major() == .row) p.widths else p.heights;
    const grows = if (r.major() == .row) p.expand.horizontal else p.expand.vertical;
    const step_ = p.step(r.major(), .along);
    if (grows and sizes.len > 0) {
        out.tile_count = @min(10, sizes.len);
        @memcpy(out.tiles[0..out.tile_count], sizes[0..out.tile_count]);
    } else if (grows) {
        const smallest = p.smallest(r.major(), .along);
        out.tile_count = 10;
        for (&out.tiles, 0..) |*t, k| t.* = smallest + @as(f64, @floatFromInt(k)) * step_;
    } else {
        out.tile_count = 1;
        out.tiles[0] = 1;
    }
    for (&out.blanks, 1..) |*b, k| b.* = @as(f64, @floatFromInt(k)) * step_;
    return out;
}

/// The region the context is, which the flow cursor belongs to. A track
/// as the context is for moving it, not filling it.
fn contextRegion() ?struct { parent: Parent, region: usize } {
    return switch (state.context) {
        .region => |r| .{ .parent = r.parent, .region = r.region },
        else => null,
    };
}

/// The item of a region's flow that a click `along` mm into segment `seg`
/// goes before: the first in that segment whose middle lies beyond it, else
/// the segment's hard break (the end of its line), else past its last item.
fn indexAt(pi: Parent, region: usize, seg: usize, along: f64) usize {
    var after: ?usize = null;
    for (flowItems(pi, region)) |it| {
        if (it.segment != seg) continue;
        if (isBreak(pi, it)) return it.index;
        if ((it.span[0] + it.span[1]) / 2 > along) return it.index;
        after = it.index + 1;
    }
    return after orelse state.model.flowItems(pi, region).len;
}

/// How many rows or columns a track's flow reached in the last solve.
fn segmentCount(pi: Parent, region: usize) usize {
    // A thread's flow has a part on each panel it runs through.
    var n: usize = 0;
    for (state.solved.items) |pl| for (pl.flows) |f| {
        if (f.flow_parent.eql(pi) and f.region == region) n = @max(n, f.segments);
    };
    return n;
}

/// The placed items of the flow of track `region` of panel `pi` (the
/// first of its thread), on every panel it runs through.
fn flowItems(pi: Parent, region: usize) []const layout.place.PlacedItem {
    var list: std.ArrayList(layout.place.PlacedItem) = .empty;
    const a = dvui.currentWindow().arena();
    for (state.solved.items) |pl| for (pl.items) |it| {
        if (it.flow_parent.eql(pi) and it.region == region) list.append(a, it) catch {};
    };
    return list.items;
}

/// Segment `t` of the flow of track `region` (the first of its thread), as
/// the last solve placed it.
fn placedTrack(pi: Parent, region: usize, t: usize) ?layout.place.PlacedTrack {
    for (state.solved.items) |pl| for (pl.tracks) |tr| {
        if (tr.flow_parent.eql(pi) and tr.region == region and tr.track == t) return tr;
    };
    return null;
}

/// The segments lying in track `ri`, as the last solve placed them (a
/// threaded track's are its thread's flow's).
fn tracksIn(pi: Parent, ri: usize) []const layout.place.PlacedTrack {
    if (placedOf(pi) == null) return &.{};
    var list: std.ArrayList(layout.place.PlacedTrack) = .empty;
    const a = dvui.currentWindow().arena();
    for (placedOf(pi).?.tracks) |tr| if (tr.member == ri) list.append(a, tr) catch {};
    return list.items;
}

/// Where row or column `t` of a track's path lies, from the last solve.
fn segmentOrigin(pi: Parent, region: usize, t: usize) ?layout.model.Segment {
    return if (placedTrack(pi, region, t)) |tr| tr.origin else null;
}

/// The model's item for a placed one, while the model still has it: the
/// placement is from the last solve, and an edit since may have removed it.
fn modelItem(pi: Parent, it: layout.place.PlacedItem) ?layout.model.Item {
    _ = pi;
    // The flow is its thread's first track's, on whichever panel.
    if (!state.model.hasParent(it.flow_parent)) return null;
    if (it.region >= state.model.regionsIn(it.flow_parent).len) return null;
    const items = state.model.flowItems(it.flow_parent, it.region);
    if (it.index >= items.len) return null;
    return items[it.index];
}

fn isBreak(pi: Parent, it: layout.place.PlacedItem) bool {
    const item = modelItem(pi, it) orelse return false;
    return item.breaks();
}

/// The cursor a click at worksheet point `at` puts in the context region's
/// tracks: in the row or column under it, between the items either side.
fn cursorAt(at: geom.Point) ?TrackCursor {
    if (canvas_eq != null) leaveCanvasEquation();
    const cr = contextRegion() orelse return null;
    const crp = placedOf(cr.parent) orelse return null;
    // In any of the context's thread's segments on its panel: a cursor in
    // the thread's flow.
    const head = state.model.threadHead(cr.parent, cr.region);
    for (crp.tracks) |t| {
        if (!t.flow_parent.eql(head.parent) or t.region != head.region) continue;
        const b = onSheet(cr.parent, t.box);
        if (!contains(b, at)) continue;
        const along = if (t.major == .row) at.x - b.x0 else b.y1 - at.y;
        flow_anchor = null;
        typing_seq += 1;
        // The nearest place in that segment the cursor can stop.
        var best: ?Stop = null;
        for (flowStops(head.parent, head.region)) |st| {
            if (!st.parent.eql(cr.parent) or st.segment != t.track) continue;
            if (best == null or @abs(st.along - along) < @abs(best.?.along - along)) best = st;
        }
        if (best) |st| return .{ .parent = head.parent, .region = head.region, .index = st.index, .offset = st.offset };
        return .{ .parent = head.parent, .region = head.region, .index = indexAt(head.parent, head.region, t.track, along) };
    }
    // An empty flow has no segment placed yet: a click in one of its
    // tracks starts it, at its beginning.
    if (state.model.flowItems(head.parent, head.region).len == 0) {
        const r = state.model.regionsIn(cr.parent)[cr.region];
        if (contains(onSheet(cr.parent, r.bounds()), at)) {
            flow_anchor = null;
            typing_seq += 1;
            return .{ .parent = head.parent, .region = head.region, .index = 0 };
        }
    }
    return null;
}

// Clicking into text ------------------------------------------------------------
//
// A press well inside a used segment of a text track (one holding content,
// so placed) puts the flow cursor there and starts typing, in Select
// boundaries too: only within reach of a segment's edge does the press go
// to the boundaries. A drag from there selects text; Shift-click extends
// the selection.

/// The text track one of whose placed segments holds worksheet point `at`
/// clearly inside: farther than a couple of edge widths from its sides (a
/// quarter of the segment's height or width at most).
fn textSegmentAt(at: geom.Point) ?struct { parent: Parent, region: usize } {
    const margin_full = 2 * edgeMm();
    for (0..state.model.parentCount()) |k| {
        const pi = state.model.parentAt(k);
        if (!shownIn(pi) or !parentLayerOpen(pi)) continue;
        const pl = placedOf(pi) orelse continue;
        const regions = state.model.regionsIn(pi);
        for (pl.tracks) |t| {
            if (t.member >= regions.len or regions[t.member].style == null) continue;
            const b = onSheet(pi, t.box);
            const m = @min(margin_full, 0.25 * @min(b.width(), b.height()));
            if (at.x >= b.x0 + m and at.x <= b.x1 - m and at.y >= b.y0 + m and at.y <= b.y1 - m) return .{ .parent = pi, .region = t.member };
        }
    }
    return null;
}

/// The place in the flow of thread head `head` nearest worksheet point
/// `at` on panel `pi`: in the segment holding it, else (`clamp`, for a
/// drag) the nearest of the thread's segments there.
fn flowPlaceAt(pi: Parent, head: layout.model.TrackRef, at: geom.Point, clamp: bool) ?layout.model.FlowPos {
    const pl = placedOf(pi) orelse return null;
    var best_t: ?layout.place.PlacedTrack = null;
    var best_d: f64 = std.math.inf(f64);
    for (pl.tracks) |t| {
        if (!t.flow_parent.eql(head.parent) or t.region != head.region) continue;
        const b = onSheet(pi, t.box);
        const dx = @max(@max(b.x0 - at.x, at.x - b.x1), 0);
        const dy = @max(@max(b.y0 - at.y, at.y - b.y1), 0);
        const d = dx * dx + dy * dy;
        if (d < best_d) {
            best_d = d;
            best_t = t;
        }
    }
    const t = best_t orelse return null;
    if (best_d > 0 and !clamp) return null;
    const b = onSheet(pi, t.box);
    const cx = std.math.clamp(at.x, b.x0, b.x1);
    const cy = std.math.clamp(at.y, b.y0, b.y1);
    const along = if (t.major == .row) cx - b.x0 else b.y1 - cy;
    var best: ?Stop = null;
    for (flowStops(head.parent, head.region)) |st| {
        if (!st.parent.eql(pi) or st.segment != t.track) continue;
        if (best == null or @abs(st.along - along) < @abs(best.?.along - along)) best = st;
    }
    if (best) |st| return .{ .index = st.index, .offset = st.offset };
    return .{ .index = indexAt(head.parent, head.region, t.track, along), .offset = 0 };
}

/// A drag in text under way: the pointer selects from where it went down.
var text_drag = false;

/// A plain press at `at` clearly inside a text track's segment: that track
/// the context and the flow cursor where pressed, ready for typing (and a
/// drag from here selecting). With `extend` (Shift), the selection runs
/// from the cursor that was to here, in the same flow. Whether it was one.
fn textPress(at: geom.Point, extend: bool) bool {
    // The innermost text first: a slot's text in a tile (a sort in this
    // flow, or a key anywhere) edited where pressed. While an expression
    // is edited, its own objects and caret places come first (hoverPress).
    if (!extend) if (slotTextAt(at)) |x| {
        const in_edited = if (canvas_eq != null) if (hoverTargetAt(at)) |h| h == .eq_object or h == .eq_caret else false else false;
        if (!in_edited) return slotPress(x);
    };
    // A tile's body elsewhere is the tile's: not the flow's text.
    if (tileBodyAt(at)) return false;
    const t = textSegmentAt(at) orelse return false;
    const head = state.model.threadHead(t.parent, t.region);
    if (extend) {
        const c = track_cursor orelse return false;
        if (!c.parent.eql(head.parent) or c.region != head.region) return false;
    }
    const pos = flowPlaceAt(t.parent, head, at, true) orelse return false;
    if (canvas_eq != null) leaveCanvasEquation();
    if (extend) {
        const c = track_cursor.?;
        if (flow_anchor == null) flow_anchor = .{ .index = c.index, .offset = c.offset };
    } else {
        flow_anchor = null;
        hunt_clear();
        selection.clearRetainingCapacity();
        state.context = .{ .region = .{ .parent = t.parent, .region = t.region } };
    }
    track_cursor = .{ .parent = head.parent, .region = head.region, .index = pos.index, .offset = pos.offset };
    typing_seq += 1;
    text_drag = true;
    text_drag_parent = t.parent;
    last_click = null;
    revealInTree(state.context);
    return true;
}
var text_drag_parent: Parent = .{ .space = 0 };

/// The pointer at `at` in a text drag: the cursor follows it, the anchor
/// staying where the drag began.
fn textDragTo(at: geom.Point) void {
    const c = track_cursor orelse return;
    const pos = flowPlaceAt(text_drag_parent, .{ .parent = c.parent, .region = c.region }, at, true) orelse return;
    if (pos.index == c.index and pos.offset == c.offset) return;
    if (flow_anchor == null) flow_anchor = .{ .index = c.index, .offset = c.offset };
    track_cursor.?.index = pos.index;
    track_cursor.?.offset = pos.offset;
}

// The character cursor ------------------------------------------------------
//
// The flow cursor stops before each item and at each character of the text
// set: before every glyph of a run, and at the end of each piece of it (so
// at both sides of a space between words). Its keys are dvui's text-field
// bindings: character, word, line (segment) start and end, text start and
// end, and the line before or after; Shift selects.

/// A place the flow cursor can stop: before item `index`, or `offset`
/// bytes into the run there; where it shows: on panel `panel`, in flow
/// segment `segment`, `along` mm into it.
const Stop = struct { index: usize, offset: u32, parent: Parent, segment: usize, along: f64 };

fn stopBefore(x: Stop, y: Stop) bool {
    return x.index < y.index or (x.index == y.index and x.offset < y.offset);
}

/// Every place the cursor can stop in the flow of track `fr` of panel `fp`
/// (the first of its thread), in order, from the last solve.
fn flowStops(fp: Parent, fr: usize) []Stop {
    const a = dvui.currentWindow().arena();
    var list: std.ArrayList(Stop) = .empty;
    if (!state.model.hasParent(fp) or fr >= state.model.regionsIn(fp).len) return &.{};
    const items = state.model.flowItems(fp, fr);
    var last: ?Stop = null;
    for (state.solved.items, 0..) |pl, k| {
        const pi = state.model.parentAt(k);
        for (pl.items) |it| {
            if (!it.flow_parent.eql(fp) or it.region != fr or it.index >= items.len) continue;
            list.append(a, .{ .index = it.index, .offset = 0, .parent = pi, .segment = it.segment, .along = it.span[0] }) catch {};
            var end: Stop = .{ .index = it.index + 1, .offset = 0, .parent = pi, .segment = it.segment, .along = it.span[1] };
            // After a break or paragraph end the cursor is at the next
            // line's start, even when nothing is set there yet (Enter at the
            // end of the text).
            if (items[it.index].breaks()) for (pl.tracks) |t| {
                if (t.flow_parent.eql(fp) and t.region == fr and t.track == it.segment + 1) {
                    end.segment = t.track;
                    end.along = 0;
                    break;
                }
            };
            if (last == null or !stopBefore(end, last.?)) last = end;
        }
        // The characters of the runs set here.
        for (pl.labels) |l| {
            const r = l.run orelse continue;
            if (!r.parent.eql(fp) or r.region != fr or r.item >= items.len or items[r.item].what != .run) continue;
            const content = items[r.item].what.run.content;
            const t = trackHolding(pi, fp, fr, l.origin) orelse continue;
            const add = struct {
                fn f(lst: *std.ArrayList(Stop), al: std.mem.Allocator, item: usize, off: u32, len: usize, parent: Parent, seg: usize, along: f64) void {
                    const s0: Stop = if (off >= len) .{ .index = item + 1, .offset = 0, .parent = parent, .segment = seg, .along = along } else .{ .index = item, .offset = off, .parent = parent, .segment = seg, .along = along };
                    lst.append(al, s0) catch {};
                }
            }.f;
            for (l.render.items) |ri| switch (ri) {
                .glyph => |g| {
                    if (g.source < r.from or g.source >= r.from + r.len) continue;
                    add(&list, a, r.item, g.source, content.len, pi, t.track, l.origin.x + g.transform.e - t.box.x0);
                },
                else => {},
            };
            const piece_end = r.from + r.len;
            if (l.render.caret(piece_end)) |cr| add(&list, a, r.item, piece_end, content.len, pi, t.track, l.origin.x + cr.x - t.box.x0);
            // An equation's anchor points, where Tab puts the cursor (an
            // empty slot has no glyph to stop at).
            if (items[r.item].what.run.equation) for (layout.edit.slots(a, content) catch &.{}) |at| {
                if (at < r.from or at >= piece_end) continue;
                if (l.render.caret(at)) |cr| add(&list, a, r.item, at, content.len, pi, t.track, l.origin.x + cr.x - t.box.x0);
            };
        }
    }
    if (last) |e| list.append(a, e) catch {};
    if (list.items.len == 0) {
        // An empty flow: its first segment's start.
        for (state.solved.items, 0..) |pl, k| for (pl.tracks) |t| {
            if (t.flow_parent.eql(fp) and t.region == fr and t.track == 0) return a.dupe(Stop, &.{.{ .index = 0, .offset = 0, .parent = state.model.parentAt(k), .segment = 0, .along = 0 }}) catch &.{};
        };
        return &.{};
    }
    std.mem.sort(Stop, list.items, {}, struct {
        fn lt(_: void, x: Stop, y: Stop) bool {
            return stopBefore(x, y);
        }
    }.lt);
    // One stop per place: the first found (a run's start in its first piece).
    var w: usize = 0;
    for (list.items) |st| {
        if (w > 0 and list.items[w - 1].index == st.index and list.items[w - 1].offset == st.offset) continue;
        list.items[w] = st;
        w += 1;
    }
    return list.items[0..w];
}

/// The placed segment of the flow of track `fr` of panel `fp` on panel
/// `pi` that holds point `p` (panel frame): the one whose band it is in.
fn trackHolding(pi: Parent, fp: Parent, fr: usize, p: geom.Point) ?layout.place.PlacedTrack {
    var best: ?layout.place.PlacedTrack = null;
    var best_d: f64 = std.math.inf(f64);
    const pl = placedOf(pi) orelse return null;
    for (pl.tracks) |t| {
        if (!t.flow_parent.eql(fp) or t.region != fr) continue;
        const b = t.box;
        const dy = if (p.y < b.y0) b.y0 - p.y else if (p.y > b.y1) p.y - b.y1 else 0;
        const dx = if (p.x < b.x0) b.x0 - p.x else if (p.x > b.x1) p.x - b.x1 else 0;
        const d = dx + dy;
        if (d < best_d) {
            best_d = d;
            best = t;
        }
    }
    return best;
}

/// The stop for flow position (`index`, `offset`): its own, else the last
/// before it.
fn stopAt(stops: []const Stop, index: usize, offset: u32) ?usize {
    if (stops.len == 0) return null;
    var k: usize = 0;
    for (stops, 0..) |st, i| {
        if (st.index < index or (st.index == index and st.offset <= offset)) k = i else break;
    }
    return k;
}

/// The character at a stop, for telling words apart: none (null) before an
/// item that is not text.
fn stopChar(fp: Parent, fr: usize, st: Stop) ?u8 {
    const items = state.model.flowItems(fp, fr);
    if (st.index >= items.len or items[st.index].what != .run) return null;
    const content = items[st.index].what.run.content;
    return if (st.offset < content.len) content[st.offset] else null;
}

fn isWordChar(ch: ?u8) bool {
    const c = ch orelse return false;
    return std.mem.indexOfScalar(u8, dvui.TextLayoutWidget.word_breaks, c) == null;
}

/// A movement key for the flow cursor (dvui's text-field bindings), with
/// Shift selecting. Whether it was one.
/// A caret movement of the flow (`canvas.flow.caret.*`, or with Shift
/// `canvas.flow.select.*`); whether `a` was one.
/// A caret motion through a flow's stops.
const Move = enum { char_left, char_right, word_left, word_right, line_start, line_end, text_start, text_end, char_up, char_down };

/// Where motion `move` takes the cursor `c`: the stop it lands on. The one
/// place motions are worked out, for moving, selecting and deleting.
fn motionStop(c: TrackCursor, move: Move) ?Stop {
    const stops = flowStops(c.parent, c.region);
    const i = stopAt(stops, c.index, c.offset) orelse return null;
    const here = stops[i];
    var j = i;
    switch (move) {
        .char_left => j = i -| 1,
        .char_right => j = @min(i + 1, stops.len - 1),
        .word_left => {
            j = i -| 1;
            while (j > 0 and !(isWordChar(stopChar(c.parent, c.region, stops[j])) and !isWordChar(stopChar(c.parent, c.region, stops[j - 1])))) j -= 1;
        },
        .word_right => {
            j = @min(i + 1, stops.len - 1);
            while (j + 1 < stops.len and !(isWordChar(stopChar(c.parent, c.region, stops[j])) and !isWordChar(stopChar(c.parent, c.region, stops[j - 1])))) j += 1;
        },
        .line_start => while (j > 0 and stops[j - 1].parent.eql(here.parent) and stops[j - 1].segment == here.segment) {
            j -= 1;
        },
        .line_end => while (j + 1 < stops.len and stops[j + 1].parent.eql(here.parent) and stops[j + 1].segment == here.segment) {
            j += 1;
        },
        .text_start => j = 0,
        .text_end => j = stops.len - 1,
        .char_up, .char_down => {
            // The nearest stop on the line before or after.
            const down = move == .char_down;
            var target: ?usize = null;
            var best_seg: usize = 0;
            for (stops) |st| {
                const ok = if (down) st.segment > here.segment else st.segment < here.segment;
                if (!ok) continue;
                if (target == null or (if (down) st.segment < best_seg else st.segment > best_seg)) {
                    best_seg = st.segment;
                    target = 0;
                }
            }
            if (target != null) {
                var best: ?usize = null;
                for (stops, 0..) |st, n| {
                    if (st.segment != best_seg) continue;
                    if (best == null or @abs(st.along - here.along) < @abs(stops[best.?].along - here.along)) best = n;
                }
                if (best) |b| j = b;
            } else if (down) {
                // On the last line, Down goes to its end; on the first,
                // Up to its start.
                while (j + 1 < stops.len and stops[j + 1].parent.eql(here.parent) and stops[j + 1].segment == here.segment) j += 1;
            } else while (j > 0 and stops[j - 1].parent.eql(here.parent) and stops[j - 1].segment == here.segment) {
                j -= 1;
            }
        },
    }
    return stops[j];
}

fn flowMoveAction(a: keymap.ActionId) bool {
    const c = track_cursor orelse return false;
    const moves = [_]struct { name: []const u8, move: Move }{
        .{ .name = "char-left", .move = .char_left },   .{ .name = "char-right", .move = .char_right },
        .{ .name = "word-left", .move = .word_left },   .{ .name = "word-right", .move = .word_right },
        .{ .name = "line-start", .move = .line_start }, .{ .name = "line-end", .move = .line_end },
        .{ .name = "text-start", .move = .text_start }, .{ .name = "text-end", .move = .text_end },
        .{ .name = "line-up", .move = .char_up },       .{ .name = "line-down", .move = .char_down },
    };
    var found: ?struct { move: Move, select: bool } = null;
    inline for (moves) |m| {
        if (a == kact("canvas.flow.caret." ++ m.name)) found = .{ .move = m.move, .select = false };
        if (a == kact("canvas.flow.select." ++ m.name)) found = .{ .move = m.move, .select = true };
    }
    const f = found orelse return false;
    const j = motionStop(c, f.move) orelse return true;
    if (f.select) {
        if (flow_anchor == null) flow_anchor = .{ .index = c.index, .offset = c.offset };
    } else flow_anchor = null;
    track_cursor.?.index = j.index;
    track_cursor.?.offset = j.offset;
    return true;
}

/// The selection in the flow, faintly: across each segment it covers.
fn drawFlowSelection(area: dvui.Rect.Physical, pi: Parent, placed: *const layout.place.Placed, c: TrackCursor) void {
    const an = flow_anchor orelse return;
    const stops = flowStops(c.parent, c.region);
    const a0 = stopAt(stops, an.index, an.offset) orelse return;
    const c0 = stopAt(stops, c.index, c.offset) orelse return;
    if (a0 == c0) return;
    const lo = @min(a0, c0);
    const hi = @max(a0, c0);
    var k = lo;
    while (k < hi) {
        // A run of stops on one segment.
        const st = stops[k];
        var e = k;
        while (e + 1 <= hi and stops[e + 1].parent.eql(st.parent) and stops[e + 1].segment == st.segment) e += 1;
        const to = if (e < hi) stops[e].along else stops[hi].along;
        // Past its last stop the selection runs on to the segment's end
        // when it goes on beyond it.
        if (st.parent.eql(pi)) for (placed.tracks) |t| {
            if (!t.flow_parent.eql(c.parent) or t.region != c.region or t.track != st.segment) continue;
            const b = onSheet(pi, t.box);
            const x1 = if (e < hi) b.x1 else b.x0 + to;
            const r: geom.Box = .{ .x0 = b.x0 + st.along, .x1 = @max(b.x0 + st.along, x1), .y0 = b.y0, .y1 = b.y1 };
            state.view.rect(area, r).fill(.square, .{ .color = .{ .color = colors.select.opacity(0.22) } });
            break;
        };
        k = e + 1;
    }
}

/// Where the cursor shows: the segment and the distance along it, mm.
fn cursorPlace(c: TrackCursor) ?struct { segment: usize, along: f64 } {
    if (placedOf(c.parent) == null) return null;
    var prev: ?layout.place.PlacedItem = null;
    var here: ?layout.place.PlacedItem = null;
    for (flowItems(c.parent, c.region)) |it| {
        // A run set word by word has several pieces: the cursor goes after
        // the last of the item before it, before the first of its own.
        if (it.index + 1 == c.index) prev = it;
        if (it.index == c.index and here == null) here = it;
    }
    // After a hard break: the start of the next segment.
    if (prev) |p| if (isBreak(c.parent, p)) {
        const seg = if (here) |h| h.segment else @min(p.segment + 1, @max(1, segmentCount(c.parent, c.region)) - 1);
        return .{ .segment = seg, .along = 0 };
    };
    if (here) |h| {
        if (prev) |p| if (p.segment == h.segment) return .{ .segment = h.segment, .along = (p.span[1] + h.span[0]) / 2 };
        return .{ .segment = h.segment, .along = h.span[0] };
    }
    if (prev) |p| return .{ .segment = p.segment, .along = p.span[1] };
    return .{ .segment = 0, .along = 0 };
}

/// The run of text or an equation the expression line edits while the
/// cursor is in a track: the one just before the cursor, else the one just
/// after it.
fn runAtCursor() ?struct { parent: Parent, region: usize, item: usize } {
    const c = track_cursor orelse return null;
    const items = state.model.flowItems(c.parent, c.region);
    if (c.offset > 0 and c.index < items.len and items[c.index].what == .run) return .{ .parent = c.parent, .region = c.region, .item = c.index };
    if (c.index > 0 and c.index <= items.len and items[c.index - 1].what == .run) return .{ .parent = c.parent, .region = c.region, .item = c.index - 1 };
    if (c.index < items.len and items[c.index].what == .run) return .{ .parent = c.parent, .region = c.region, .item = c.index };
    return null;
}

/// Fits a region's rows or columns to their content: as long as its
/// longest paragraph needs, from the last solve. Whether it changed.
fn fitRegion(pi: Parent, region: usize) bool {
    if (placedOf(pi) == null) return false;
    for (placedOf(pi).?.flows) |f| {
        if (f.region != region) continue;
        const r = state.model.regionsIn(pi)[region];
        if (!(f.natural > 0) or @abs(f.natural - r.segmentLength()) < 1e-9) return false;
        act(.setSegmentLength, .{pi, region, f.natural}) catch return false;
        return true;
    }
    return false;
}

/// Drops the cursor when its region stops being the context, and keeps it
/// within the flow as items come and go.
fn validateCursor() void {
    // Out of the flow, the palette goes back to each track's own prototype.
    const c = track_cursor orelse {
        palette_prototype = null;
        return;
    };
    const cr = contextRegion() orelse {
        track_cursor = null;
        return;
    };
    const head = state.model.threadHead(cr.parent, cr.region);
    if (!head.parent.eql(c.parent) or head.region != c.region or !state.model.hasParent(c.parent)) {
        track_cursor = null;
        return;
    }
    const r_items = state.model.flowItems(c.parent, c.region);
    track_cursor.?.index = @min(c.index, r_items.len);
    // Within a run, only while there is a run there and the offset is in it.
    const tc = &track_cursor.?;
    if (tc.offset > 0) {
        const in_run = tc.index < r_items.len and r_items[tc.index].what == .run;
        if (!in_run) tc.offset = 0 else if (tc.offset >= r_items[tc.index].what.run.content.len) {
            tc.index += 1;
            tc.offset = 0;
        }
    }
}

fn cursorKeysReach() bool {
    const focused = dvui.focusedWidgetId() orelse return true;
    if (canvas_id != null and focused == canvas_id.?) return true;
    for (palette_ids[0..palette_id_count]) |id| if (id == focused) return true;
    return false;
}

/// Acts on a key for the flow cursor; whether it was one.
/// The content palette's rows of tiles and blanks, in a track of tiles
/// (not one of text, where letters type): shown since 2026-11-18, by
/// buttons only (digits and letters type text in a flow, so the keys they
/// had are gone; Tab still switches the prototype).
fn tileRowsShown() bool {
    return !inTextTrack();
}

/// An action of mode `canvas.flow`, at the flow cursor; whether it was
/// done.
fn flowAction(inv: keymap.Invocation) bool {
    const c = track_cursor orelse return false;
    // Movement as in a text field (the toolkit's bindings), Shift
    // selecting.
    if (flowMoveAction(inv.action)) {
        typing_seq += 1;
        return true;
    }
    const region = state.model.regionsIn(c.parent)[c.region];
    const len = state.model.flowItems(c.parent, c.region).len;
    switch (inv.action) {
        kact("canvas.flow.copy") => copyFlowSelection(false),
        kact("canvas.flow.cut") => copyFlowSelection(true),
        kact("canvas.flow.paste") => {
            const text = dvui.clipboardText();
            if (text.len > 0) typeIntoFlow(text);
            typing_seq += 1;
        },
        kact("canvas.flow.select.all") => {
            const stops = flowStops(c.parent, c.region);
            if (stops.len > 0) {
                flow_anchor = .{ .index = stops[0].index, .offset = stops[0].offset };
                track_cursor.?.index = stops[stops.len - 1].index;
                track_cursor.?.offset = stops[stops.len - 1].offset;
            }
        },
        // Equation mode, typing going to the expression line.
        kact("canvas.flow.edit-equation") => enterEquation(),
        kact("canvas.flow.tab") => {
            // At or in an equation, Tab goes round its anchor points
            // (Shift+Tab back).
            if (equationAtCursor(c) == null) return false;
            tabEquation(inv.arg == 1);
        },
        // In text, Enter ends the paragraph and Shift+Enter the line (a run
        // is split where the cursor is); in a track of tiles, Enter ends
        // the row.
        kact("canvas.flow.new-paragraph"), kact("canvas.flow.new-line") => {
            _ = deleteFlowSelection();
            const cc = track_cursor.?;
            const line = inv.action == kact("canvas.flow.new-line");
            const pos = act(.breakAt, .{ cc.parent, cc.region, flowPos(cc), !(line or region.style == null) }) catch return true;
            setFlowPos(pos);
            typing_seq += 1;
        },
        kact("canvas.flow.delete-back") => {
            if (deleteFlowSelection()) return true;
            const from = charBeforeCursor(c) orelse return true;
            const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, from, flowPos(c) }) catch return true;
            setFlowPos(pos);
        },
        // linenoise's kills: to the line's end (at it, the break after
        // it), the whole line, the word before; and swapping two
        // characters.
        kact("canvas.flow.delete-line-end") => {
            if (deleteFlowSelection()) return true;
            var to = motionStop(c, .line_end) orelse return true;
            if (to.index == c.index and to.offset == c.offset) to = motionStop(c, .char_right) orelse return true;
            deleteFlowTo(c, .{ .index = to.index, .offset = to.offset });
        },
        kact("canvas.flow.delete-line") => {
            if (deleteFlowSelection()) return true;
            const from = motionStop(c, .line_start) orelse return true;
            const to = motionStop(c, .line_end) orelse return true;
            const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, layout.model.FlowPos{ .index = from.index, .offset = from.offset }, layout.model.FlowPos{ .index = to.index, .offset = to.offset } }) catch return true;
            setFlowPos(pos);
        },
        kact("canvas.flow.delete-word-back") => {
            if (deleteFlowSelection()) return true;
            const from = motionStop(c, .word_left) orelse return true;
            deleteFlowTo(c, .{ .index = from.index, .offset = from.offset });
        },
        kact("canvas.flow.transpose") => transposeChars(c),
        kact("canvas.flow.choose-case") => {
            case_picker = true;
            case_query_len = 0;
            case_hi = 0;
        },
        // A digit: the row it numbers; Enter: the highlighted row.
        kact("canvas.flow.case-picker.pick"), kact("canvas.flow.case-picker.take") => {
            // A digit is bound by its key's place: the text it types is not
            // typed.
            if (inv.action == kact("canvas.flow.case-picker.pick")) swallow_text = true;
            var buf: [case_rows_max]?usize = undefined;
            const rows = caseRows(&buf);
            const n: usize = if (inv.action == kact("canvas.flow.case-picker.take")) case_hi else @intCast(inv.arg);
            if (n >= @min(rows.len, 10)) return true;
            case_picker = false;
            chooseCase(rows[n]);
        },
        kact("canvas.flow.case-picker.move") => {
            var buf: [case_rows_max]?usize = undefined;
            const rows = caseRows(&buf);
            if (rows.len == 0) return true;
            case_hi = if (inv.arg < 0) case_hi -| 1 else @min(case_hi + 1, @min(rows.len, 10) - 1);
        },
        kact("canvas.flow.case-picker.back") => if (case_query_len > 0) {
            case_query_len -= 1;
            case_hi = 0;
        },
        // Space: the case before, unless a name is being typed (then a
        // space in it); Ctrl+Space (arg 0) always.
        kact("canvas.flow.case-picker.previous") => {
            if (inv.arg == 1 and case_query_len > 0) {
                caseQueryAdd(" ");
                return true;
            }
            case_picker = false;
            chooseCase(prev_case);
        },
        kact("canvas.flow.case-picker.cancel") => case_picker = false,
        kact("canvas.flow.delete-forward") => {
            if (deleteFlowSelection()) return true;
            const to = charAfterCursor(c, len) orelse return true;
            const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, flowPos(c), to }) catch return true;
            setFlowPos(pos);
        },
        kact("canvas.flow.leave") => {
            // A selection first; then the cursor.
            if (flow_anchor != null) {
                flow_anchor = null;
                return true;
            }
            track_cursor = null;
        },
        else => return false,
    }
    return true;
}

// Editing the flow in place -----------------------------------------------------

/// Typing since the cursor last moved is one undo step.
var typing_seq: u64 = 0;

fn typingKey() u64 {
    const c = track_cursor orelse return 0;
    return mergeKey(.{ "type", c.parent, c.region, typing_seq });
}

fn flowPos(c: TrackCursor) layout.model.FlowPos {
    return .{ .index = c.index, .offset = c.offset };
}

fn setFlowPos(p: layout.model.FlowPos) void {
    if (track_cursor) |*c| {
        c.index = p.index;
        c.offset = p.offset;
    }
    flow_anchor = null;
}

/// The selection in the flow, when there is one: its two ends.
fn flowSelection() ?[2]layout.model.FlowPos {
    const c = track_cursor orelse return null;
    const an = flow_anchor orelse return null;
    if (an.index == c.index and an.offset == c.offset) return null;
    return .{ .{ .index = an.index, .offset = an.offset }, flowPos(c) };
}

/// Deletes the selection, if there is one; whether there was.
fn deleteFlowSelection() bool {
    const c = track_cursor orelse return false;
    const sel = flowSelection() orelse return false;
    const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, sel[0], sel[1] }) catch return true;
    setFlowPos(pos);
    return true;
}

// Cases of sorts ------------------------------------------------------------
//
// A case puts sorts on the keyboard's keys while typing in a flow (see
// `layout.model.Case`): Ctrl+Space, then a digit, chooses one (0: plain
// text); Space instead goes back to the case before, so Ctrl+Space, Space
// switches between two.

fn isModifierKey(k: dvui.enums.Key) bool {
    return switch (k) {
        .left_control, .right_control, .left_shift, .right_shift, .left_alt, .right_alt, .left_command, .right_command => true,
        else => false,
    };
}

/// The case the keys type from (an index into Graven's cases, then the
/// document's), null for plain text; the one before it.
var active_case: ?usize = null;
var prev_case: ?usize = null;
/// Whether the next typed text is dropped: a key bound by its place
/// (`@E01`) acted, and its text event follows.
var swallow_text = false;
/// Whether Ctrl+Space was pressed and a case is being chosen.
var case_picker = false;

/// Case `i`: Graven's own first, then the document's.
fn caseAt(i: usize) ?layout.model.Case {
    const b = layout.model.builtin_cases;
    if (i < b.len) return b[i];
    const d = state.model.cases.items;
    return if (i - b.len < d.len) d[i - b.len] else null;
}

fn caseCount() usize {
    return layout.model.builtin_cases.len + state.model.cases.items.len;
}

fn chooseCase(i: ?usize) void {
    if (i) |c| {
        // Most recent first.
        var k: usize = std.mem.indexOfScalar(usize, case_recent[0..case_recent_len], c) orelse @min(case_recent_len, case_recent.len - 1);
        if (k == case_recent_len) case_recent_len += 1;
        while (k > 0) : (k -= 1) case_recent[k] = case_recent[k - 1];
        case_recent[0] = c;
    }
    if (i == active_case) return;
    prev_case = active_case;
    active_case = i;
}

/// The name being typed to find a case, and the row highlighted.
var case_query: [64]u8 = undefined;
var case_query_len: usize = 0;
var case_hi: usize = 0;
/// The cases chosen lately, most recent first.
var case_recent: [32]usize = undefined;
var case_recent_len: usize = 0;
const case_rows_max = 512;

fn caseQueryAdd(txt: []const u8) void {
    const n = @min(txt.len, case_query.len - case_query_len);
    @memcpy(case_query[case_query_len..][0..n], txt[0..n]);
    case_query_len += n;
    case_hi = 0;
}

fn caseName(i: ?usize) []const u8 {
    const c = i orelse return "Text";
    return if (caseAt(c)) |cs| cs.name else "";
}

/// How well `name` answers `q` (ASCII case ignored): 3 starts with it, 2
/// has it, 1 has its characters in order; 0 not at all.
fn caseMatch(name: []const u8, q: []const u8) u8 {
    if (q.len == 0) return 3;
    if (std.ascii.startsWithIgnoreCase(name, q)) return 3;
    if (std.ascii.findIgnoreCase(name, q) != null) return 2;
    var k: usize = 0;
    for (name) |ch| {
        if (k < q.len and std.ascii.toLower(ch) == std.ascii.toLower(q[k])) k += 1;
    }
    return if (k == q.len) 1 else 0;
}

/// The picker's rows (null: plain text): with no name typed, Text, then
/// the cases chosen lately, then the rest in order; with one, the cases it
/// finds, best first.
fn caseRows(buf: *[case_rows_max]?usize) []?usize {
    var n: usize = 0;
    const q = case_query[0..case_query_len];
    const n_cases = caseCount();
    if (q.len == 0) {
        buf[n] = null;
        n += 1;
        for (case_recent[0..case_recent_len]) |c| if (c < n_cases and n < buf.len) {
            buf[n] = c;
            n += 1;
        };
        for (0..n_cases) |c| {
            if (n >= buf.len) break;
            if (std.mem.indexOfScalar(usize, case_recent[0..case_recent_len], c) != null) continue;
            buf[n] = c;
            n += 1;
        }
        return buf[0..n];
    }
    var grade: u8 = 3;
    while (grade > 0) : (grade -= 1) {
        if (caseMatch("Text", q) == grade and n < buf.len) {
            buf[n] = null;
            n += 1;
        }
        for (0..n_cases) |c| if (n < buf.len and caseMatch(caseName(c), q) == grade) {
            buf[n] = c;
            n += 1;
        };
    }
    return buf[0..n];
}

/// The sort typed text `txt` stands for in the active case, if any.
fn caseSort(txt: []const u8) ?layout.model.Sort {
    const i = active_case orelse return null;
    const c = caseAt(i) orelse return null;
    return c.sortFor(&keymap.layout, txt);
}

/// Puts `sort` in at the flow cursor (over the selection; a run it is in
/// split there), the cursor after it.
fn insertSort(sort: layout.model.Sort) void {
    if (sort == .text) return typeIntoFlow(sort.text);
    _ = deleteFlowSelection();
    const c = track_cursor orelse return;
    const pal = paletteFor(c.parent, c.region) orelse return;
    const index = act(.splitAt, .{ c.parent, c.region, flowPos(c) }) catch return;
    setFlowPos(.{ .index = index });
    switch (sort) {
        .text => unreachable,
        .tile => |t| {
            const proto = if (t.prototype) |p| (if (state.model.protoIndex(p) != null) p else pal.prototype) else pal.prototype;
            const size = switch (t.size) {
                .units => |u| u,
                .step => |k| if (k < pal.tile_count) pal.tiles[k] else return,
            };
            _ = act(.insertTile, .{ c.parent, c.region, index, proto, size }) catch return;
        },
        .blank => |b| {
            const size = switch (b.size) {
                .units => |u| u,
                .step => |k| if (k < pal.blanks.len) pal.blanks[k] else return,
            };
            const r = state.model.regionsIn(c.parent)[c.region];
            const unit = state.model.proto(pal.prototype).unitIn(r.pitch);
            _ = act(.insertBlank, .{ c.parent, c.region, index, size * unit / r.pitch }) catch return;
        },
    }
    setFlowPos(.{ .index = index + 1 });
}

/// A sort as a key of the overlay shows it: text as it is, a tile or a
/// blank by its length.
fn sortLabel(a: std.mem.Allocator, sort: layout.model.Sort) []const u8 {
    const c = track_cursor;
    const pal = if (c) |cc| paletteFor(cc.parent, cc.region) else null;
    // The length it would have here, for its short id.
    const size: ?layout.model.SortSize = switch (sort) {
        .text => null,
        .tile => |t| t.size,
        .blank => |b| b.size,
    };
    const length: ?f64 = if (size) |sz| switch (sz) {
        .units => |u| u,
        .step => |k| if (pal) |p| (if (sort == .tile) (if (k < p.tile_count) p.tiles[k] else null) else (if (k < p.blanks.len) p.blanks[k] else null)) else null,
    } else null;
    const buf = a.alloc(u8, 32) catch return "";
    return sort.shortId(buf, length);
}

/// The active case on a keyboard, over the canvas's foot (the gray
/// overlay back, 2026-11-24): each key labelled as the user's layout has
/// it, its sort below, its upper case's above right. Keys the case leaves
/// alone are faint.
fn caseOverlay() void {
    if (track_cursor == null or case_picker) return;
    const ci = active_case orelse return;
    const cs = caseAt(ci) orelse return;
    const a = dvui.currentWindow().arena();
    const kb = layout.keys;
    // Each position's key of the case.
    var at: [kb.count]?layout.model.CaseKey = @splat(null);
    for (cs.keys) |k| if (k.key.on(&keymap.layout)) |p| if (kb.index(p)) |i| {
        at[i] = k;
    };
    const rows = [_]struct { row: kb.Row, from: u8, to: u8, indent: f32 }{
        .{ .row = .E, .from = 0, .to = 12, .indent = 0 },
        .{ .row = .D, .from = 1, .to = 12, .indent = 1.5 },
        .{ .row = .C, .from = 1, .to = 11, .indent = 1.75 },
        .{ .row = .B, .from = 1, .to = 10, .indent = 2.25 },
    };
    const key_w: f32 = 56;
    const key_h: f32 = 54;
    const gap: f32 = 3;
    const w: f32 = 13.5 * (key_w + gap) + 16;
    const h: f32 = 4 * (key_h + gap) + 36;
    const cr = canvas_rect;
    if (cr.w < w * 0.5) return;
    // Clear of the expression line and status bar at the window's foot.
    const foot = @min(cr.y + cr.h, dvui.windowRect().h - 96);
    const rect: dvui.Rect = .{ .x = cr.x + @max(0, (cr.w - w) / 2), .y = @max(cr.y, foot - h - 8), .w = @min(w, cr.w), .h = h };
    var fw: dvui.FloatingWidget = undefined;
    fw.init(@src(), .{ .mouse_events = false }, .{
        .rect = rect,
        .background = true,
        .color_fill = .{ .color = dvui.Color.gray.opacity(palette_alpha) },
        .corners = .all(8),
        .padding = .all(6),
    });
    defer fw.deinit();
    const small = ghost_pane.fieldFont().withSize(11);
    const big = ghost_pane.fieldFont().withSize(22);
    dvui.labelNoFmt(@src(), std.fmt.allocPrint(a, "Case: {s}   (Ctrl+Space: another)", .{cs.name}) catch "", .{}, .{ .font = small, .color_text = .{ .color = dvui.Color.white }, .padding = .{ .x = 2, .y = 0, .w = 2, .h = 4 } });
    for (rows, 0..) |r, ri| {
        var hb = dvui.box(@src(), .{ .dir = .horizontal }, .{ .id_extra = ri, .margin = .{ .h = gap } });
        defer hb.deinit();
        _ = dvui.spacer(@src(), .{ .min_size_content = .{ .w = r.indent * (key_w + gap), .h = 1 } });
        var col = r.from;
        while (col <= r.to) : (col += 1) {
            const pos: kb.Position = .{ .row = r.row, .col = col };
            const i = kb.index(pos) orelse continue;
            const ck = at[i];
            const used = ck != null and (ck.?.lower != null or ck.?.upper != null);
            var kbx = dvui.overlay(@src(), .{
                .id_extra = col,
                .min_size_content = .{ .w = key_w, .h = key_h },
                .max_size_content = .{ .w = key_w, .h = key_h },
                .margin = .{ .w = gap },
                .background = true,
                .border = .all(1),
                .corners = .all(4),
                .color_fill = .{ .color = if (used) dvui.Color.black.opacity(0.35) else dvui.Color.black.opacity(0.12) },
                .color_border = .{ .color = dvui.Color.white.opacity(if (used) 0.45 else 0.15) },
            });
            defer kbx.deinit();
            // The key as the layout has it, top left; its upper sort top
            // right; its sort below.
            dvui.labelNoFmt(@src(), keymap.layout.typed(pos, false), .{}, .{ .font = small, .color_text = .{ .color = dvui.Color.white.opacity(0.55) }, .padding = .{ .x = 3, .y = 1 } });
            if (ck) |k| if (k.upper) |u| dvui.labelNoFmt(@src(), sortLabel(a, u), .{}, .{ .font = small, .color_text = .{ .color = dvui.Color.white.opacity(0.85) }, .gravity_x = 1.0, .padding = .{ .w = 3, .y = 1 } });
            if (ck) |k| if (k.lower) |l| dvui.labelNoFmt(@src(), sortLabel(a, l), .{}, .{ .font = if (l == .text) big else small, .color_text = .{ .color = dvui.Color.white }, .gravity_x = 0.5, .gravity_y = 1.0, .padding = .{ .h = 3 } });
        }
    }
}

/// By the caret while a case is active: its name; while one is chosen,
/// the cases with their digits.
fn caseHint() void {
    if (track_cursor == null) {
        case_picker = false;
        return;
    }
    if (!case_picker and active_case == null) return;
    const S = struct {
        var shown: u64 = 0;
    };
    const key: u64 = (if (case_picker) @as(u64, 1) else 0) | (@as(u64, active_case orelse 0xff) << 1) | (@as(u64, caseCount()) << 10) | (@as(u64, case_query_len) << 30) | (@as(u64, case_hi) << 40) | (@as(u64, std.hash.Wyhash.hash(0, case_query[0..case_query_len]) & 0xfff) << 48);
    if (key != S.shown) dvui.refresh(null, @src(), null);
    S.shown = key;
    const a = dvui.currentWindow().arena();
    const font = ghost_pane.fieldFont();
    var lines: std.ArrayList([]const u8) = .empty;
    var hi_line: ?usize = null;
    if (case_picker) {
        var buf: [case_rows_max]?usize = undefined;
        const rows = caseRows(&buf);
        const q = case_query[0..case_query_len];
        lines.append(a, if (q.len == 0) "Case: type to find, a digit or Enter to take, Space for the one before" else std.fmt.allocPrint(a, "Case: {s}_", .{q}) catch "") catch {};
        for (rows[0..@min(rows.len, 10)], 0..) |r, k| {
            if (k == case_hi) hi_line = lines.items.len;
            lines.append(a, std.fmt.allocPrint(a, "{d}  {s}{s}", .{ k, caseName(r), if (r == active_case) "  (now)" else "" }) catch "") catch {};
        }
        if (rows.len > 10) lines.append(a, std.fmt.allocPrint(a, "   … {d} more: type to find", .{rows.len - 10}) catch "") catch {};
        if (rows.len == 0) lines.append(a, "   no case has that name") catch {};
    } else {
        const c = caseAt(active_case.?) orelse return;
        lines.append(a, std.fmt.allocPrint(a, "Case: {s}", .{c.name}) catch "") catch {};
    }
    const line_h = font.textHeight() + 6;
    var w: f32 = 0;
    for (lines.items) |l| w = @max(w, font.textSize(l).w);
    w += 24;
    const h: f32 = 10 + line_h * @as(f32, @floatFromInt(lines.items.len));
    const cm = caret_mark orelse return;
    const ns = dvui.windowNaturalScale();
    const win = dvui.windowRect();
    // Above the caret (a digraph's hint goes below it).
    const y = if (cm.y / ns - h - 8 >= 0) cm.y / ns - h - 8 else (cm.y + cm.h) / ns + 8;
    const at: dvui.Rect.Natural = .{ .x = @min(@max(0, cm.x / ns - 16), @max(0, win.w - w)), .y = y, .w = w, .h = h };
    var fw: dvui.FloatingWidget = undefined;
    fw.init(@src(), .{ .stay_above_parent = false, .mouse_events = false }, .{
        .rect = .{ .x = at.x, .y = at.y, .w = at.w, .h = at.h },
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) },
        .border = .all(1),
        .corners = .all(6),
        .padding = .all(4),
    });
    defer fw.deinit();
    dvui.raiseSubwindow(fw.data().id);
    for (lines.items, 0..) |l, i| {
        const hl = hi_line != null and hi_line.? == i;
        dvui.labelNoFmt(@src(), l, .{}, .{ .id_extra = i, .font = font, .padding = .{ .x = 4, .y = 2, .w = 4, .h = 2 }, .expand = .horizontal, .background = hl, .color_fill = if (hl) .{ .color = dvui.themeGet().color(.highlight, .fill) } else null });
    }
}

/// Deletes between the cursor and `to` (either side of it).
fn deleteFlowTo(c: TrackCursor, to: layout.model.FlowPos) void {
    const here = flowPos(c);
    if (to.index == here.index and to.offset == here.offset) return;
    const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, here, to }) catch return;
    setFlowPos(pos);
}

/// Swaps the characters before and at the cursor, moving on past both (at
/// a line's end, the two before it), as linenoise's Ctrl+T. Only plain
/// characters of text: never a break, a tile or part of an equation.
fn transposeChars(c: TrackCursor) void {
    const stops = flowStops(c.parent, c.region);
    var i = stopAt(stops, c.index, c.offset) orelse return;
    if (i + 1 >= stops.len or stops[i + 1].segment != stops[i].segment or !stops[i + 1].parent.eql(stops[i].parent)) i -|= 1;
    if (i == 0 or i + 1 >= stops.len) return;
    const items = state.model.flowItems(c.parent, c.region);
    for ([_]Stop{ stops[i - 1], stops[i] }) |st| {
        if (st.index >= items.len or items[st.index].what != .run or items[st.index].what.run.equation) return;
    }
    const p0: layout.model.FlowPos = .{ .index = stops[i - 1].index, .offset = stops[i - 1].offset };
    const p1: layout.model.FlowPos = .{ .index = stops[i].index, .offset = stops[i].offset };
    const p2: layout.model.FlowPos = .{ .index = stops[i + 1].index, .offset = stops[i + 1].offset };
    const a = dvui.currentWindow().arena();
    const t0 = state.model.flowText(a, c.parent, c.region, p0, p1) catch return;
    const t1 = state.model.flowText(a, c.parent, c.region, p1, p2) catch return;
    if (t0.len == 0 or t1.len == 0 or std.mem.indexOfScalar(u8, t0, '\n') != null or std.mem.indexOfScalar(u8, t1, '\n') != null) return;
    const pos = actM(typingKey(), .deleteRange, .{ c.parent, c.region, p0, p2 }) catch return;
    setFlowPos(pos);
    typeIntoFlow(std.mem.concat(a, u8, &.{ t1, t0 }) catch return);
}

/// Types `text` in at the cursor, over the selection if there is one.
fn typeIntoFlow(text: []const u8) void {
    _ = deleteFlowSelection();
    const c = track_cursor orelse return;
    const style = state.model.regionsIn(c.parent)[c.region].style orelse (labelStyle() catch return);
    const pos = actM(typingKey(), .insertText, .{ c.parent, c.region, flowPos(c), text, style }) catch return;
    setFlowPos(pos);
}

/// Copies the selection as plain text (and with `cut`, deletes it).
fn copyFlowSelection(cut: bool) void {
    const c = track_cursor orelse return;
    const sel = flowSelection() orelse return;
    const text = state.model.flowText(state.gpa, c.parent, c.region, sel[0], sel[1]) catch return;
    defer state.gpa.free(text);
    dvui.clipboardTextSet(text);
    if (cut) {
        _ = deleteFlowSelection();
        typing_seq += 1;
    }
}

/// Where the character before the cursor starts: in the run it is in,
/// else at the end of the run before, else the item before.
fn charBeforeCursor(c: TrackCursor) ?layout.model.FlowPos {
    const a = dvui.currentWindow().arena();
    const items = state.model.flowItems(c.parent, c.region);
    if (c.offset > 0 and c.index < items.len and items[c.index].what == .run) {
        const at = layout.edit.charBefore(a, items[c.index].what.run.content, c.offset, items[c.index].what.run.equation) catch null;
        return .{ .index = c.index, .offset = at orelse 0 };
    }
    if (c.index == 0) return null;
    const k = c.index - 1;
    if (items[k].what == .run) {
        const content = items[k].what.run.content;
        if (layout.edit.charBefore(a, content, @intCast(content.len), items[k].what.run.equation) catch null) |at| return .{ .index = k, .offset = at };
    }
    return .{ .index = k };
}

/// Where the character at the cursor ends.
fn charAfterCursor(c: TrackCursor, len: usize) ?layout.model.FlowPos {
    if (c.index >= len) return null;
    const items = state.model.flowItems(c.parent, c.region);
    if (items[c.index].what == .run) {
        const content = items[c.index].what.run.content;
        const end = (layout.edit.charAfter(dvui.currentWindow().arena(), content, c.offset, items[c.index].what.run.equation) catch null) orelse @as(u32, @intCast(content.len));
        return if (end >= content.len) .{ .index = c.index + 1 } else .{ .index = c.index, .offset = end };
    }
    return .{ .index = c.index + 1 };
}

/// Inserts at the cursor, which moves past it: a tile or a blank `size` u
/// long, a hard break, or an empty run of markup, whose text the expression
/// line then takes.
fn insertAtCursor(kind: enum { tile, blank, run, hard_break, paragraph }, size: f64) void {
    // Within a run, for now, what is put in goes after it.
    if (track_cursor) |*tc| if (tc.offset > 0) {
        tc.index += 1;
        tc.offset = 0;
    };
    flow_anchor = null;
    const c = track_cursor orelse return;
    switch (kind) {
        .tile => {
            const pal = paletteFor(c.parent, c.region) orelse return;
            _ = act(.insertTile, .{c.parent, c.region, c.index, pal.prototype, size}) catch return;
        },
        .blank => {
            const pal = paletteFor(c.parent, c.region) orelse return;
            // The palette's blanks are in the prototype's u, as its tiles
            // are; a blank is stored in its track's unit.
            const r = state.model.regionsIn(c.parent)[c.region];
            const unit = state.model.proto(pal.prototype).unitIn(r.pitch);
            _ = act(.insertBlank, .{c.parent, c.region, c.index, size * unit / r.pitch}) catch return;
        },
        .hard_break => {
            // With the track's indent, a blank follows: the cursor goes past
            // it, to where the new paragraph's content starts.
            const n = act(.insertBreak, .{c.parent, c.region, c.index}) catch return;
            track_cursor.?.index += n;
            return;
        },
        .paragraph => {
            // The new paragraph takes the style of the one it splits; at
            // its end, that style's next (FrameMaker's Next ¶ Tag).
            const style = state.model.paragraphStyleAfter(c.parent, c.region, c.index);
            act(.insertParagraph, .{c.parent, c.region, c.index, style}) catch return;
        },
        .run => {
            const style = state.model.regionsIn(c.parent)[c.region].style orelse (labelStyle() catch return);
            act(.insertRun, .{c.parent, c.region, c.index, .{ .style = style, .content = "" }}) catch return;
            focus_expression = true;
        },
    }
    track_cursor.?.index += 1;
}

/// Joins the items either side of the cursor into one group, or parts them:
/// a group breaks as one.
fn toggleBindAtCursor() void {
    const c = track_cursor orelse return;
    const items = state.model.flowItems(c.parent, c.region);
    if (c.index == 0 or c.index >= items.len) {
        state.status = "Put the cursor between two items to join or part them. ";
        return;
    }
    const before = items[c.index - 1];
    if (before.breaks() or items[c.index].breaks()) {
        state.status = "A hard break cannot be part of a group. ";
        return;
    }
    act(.setBind, .{c.parent, c.region, c.index - 1, !before.bind}) catch return;
    state.status = if (before.bind) "Parted: a break may fall here. " else "Joined: no break falls here. ";
}

/// Set when a new run wants the expression line to take the keyboard.
var focus_expression = false;
/// Where the expression line's cursor goes when it takes the keyboard.
var focus_expression_at: ?usize = null;

// Equation mode ---------------------------------------------------------------
//
// Ctrl+\ at the flow cursor builds an equation there: an equation run of
// its own, whose markup the expression line takes while typing goes to it.
// At or in an equation already, it opens that one. Ctrl+\ again (or Enter,
// or Esc) returns typing to the flow, after the equation; one left empty
// goes. At or in an equation in the flow, Tab goes round its anchor
// points, the argument slots, for editing it in place.

/// The equation the expression line builds while equation mode is on;
/// `shown` once the line has had the keyboard.
var equation_edit: ?struct { parent: Parent, region: usize, item: usize, shown: bool = false } = null;

/// The equation being built, while it is still one.
fn equationEdited() ?@TypeOf(equation_edit.?) {
    const e = equation_edit orelse return null;
    if (!state.model.hasParent(e.parent) or e.region >= state.model.regionsIn(e.parent).len) return null;
    const items = state.model.flowItems(e.parent, e.region);
    if (e.item >= items.len or items[e.item].what != .run or !items[e.item].what.run.equation) return null;
    return e;
}

/// The equation at or around the cursor: the one it is in, else the one
/// just before it, else the one just after it; with the cursor's offset in
/// its markup.
fn equationAtCursor(c: TrackCursor) ?struct { item: usize, offset: u32 } {
    const items = state.model.flowItems(c.parent, c.region);
    const isEq = struct {
        fn f(its: []const layout.model.Item, i: usize) bool {
            return i < its.len and its[i].what == .run and its[i].what.run.equation;
        }
    }.f;
    if (c.offset > 0 and isEq(items, c.index)) return .{ .item = c.index, .offset = c.offset };
    if (c.offset == 0 and c.index > 0 and isEq(items, c.index - 1)) return .{ .item = c.index - 1, .offset = @intCast(items[c.index - 1].what.run.content.len) };
    if (c.offset == 0 and isEq(items, c.index)) return .{ .item = c.index, .offset = 0 };
    return null;
}

/// Ends equation mode: an empty equation goes; with `to_flow`, the flow
/// cursor goes after it.
fn leaveEquation(to_flow: bool) void {
    const e = equationEdited() orelse {
        equation_edit = null;
        return;
    };
    equation_edit = null;
    typing_seq += 1;
    state.status = "";
    const content = state.model.flowItems(e.parent, e.region)[e.item].what.run.content;
    // Empty: nothing typed (an equation of empty slots stays).
    if (content.len == 0) {
        const pos = act(.deleteRange, .{ e.parent, e.region, layout.model.FlowPos{ .index = e.item }, layout.model.FlowPos{ .index = e.item + 1 } }) catch return;
        if (track_cursor) |*tc| if (tc.parent.eql(e.parent) and tc.region == e.region) {
            tc.index = pos.index;
            tc.offset = pos.offset;
        };
        return;
    }
    if (!to_flow) return;
    if (track_cursor) |*tc| if (tc.parent.eql(e.parent) and tc.region == e.region) {
        tc.index = e.item + 1;
        tc.offset = 0;
    };
    flow_anchor = null;
}

/// Tab at or in an equation: the cursor goes to its next anchor point
/// (with `back`, the one before), round from the last to the first.
fn tabEquation(back: bool) void {
    const c = track_cursor orelse return;
    const eq = equationAtCursor(c) orelse return;
    const content = state.model.flowItems(c.parent, c.region)[eq.item].what.run.content;
    const anchors = layout.edit.slots(dvui.currentWindow().arena(), content) catch return;
    if (anchors.len == 0) {
        state.status = "This equation has no slots to go round. ";
        return;
    }
    // From outside it (before or after), Tab starts at its first slot and
    // Shift+Tab at its last.
    const inside = c.index == eq.item and c.offset > 0;
    var to = if (back) anchors[anchors.len - 1] else anchors[0];
    if (inside) {
        if (back) {
            var k = anchors.len;
            while (k > 0) {
                k -= 1;
                if (anchors[k] < c.offset) {
                    to = anchors[k];
                    break;
                }
            }
        } else for (anchors) |x| if (x > c.offset) {
            to = x;
            break;
        };
    }
    track_cursor.?.index = eq.item;
    track_cursor.?.offset = to;
    flow_anchor = null;
    typing_seq += 1;
}

// Editing an equation on the canvas -------------------------------------------
//
// Ctrl+\ at or in an equation (or a new one) puts an editing caret into it.
// Typing goes into its source as it is typed (math: ^ is a script), { pairs
// with its }, Left and Right step through the source's characters and
// fields, Backspace and Delete take a character. Tab and Shift+Tab go
// through its stops in field order: each structure's head (its own
// symbol: a fraction's rule, √, Σ, a fence, an accent), then its fields.
// On a head, single keys style it, written into the source in the call
// form (\set(…){…}): = and - scale it by a tenth, the arrow keys nudge it,
// [ and ] turn it 15°, 0 clears what was set; i opens or hides a root's
// index, u and b the upper and lower slots (limits, scripts). Esc, Enter
// or Ctrl+\ leave, the flow cursor after the equation.

const CanvasEq = struct {
    /// What is edited: a run of a track's flow (an equation, or a text
    /// run's math between dollars), or a tile's track.
    target: ExprTarget,
    /// Its source is all math (an equation); else a legend (text, math
    /// between dollars).
    math: bool,
    /// The caret: a byte offset in the source (a tile track's text: its
    /// runs, a newline for each break).
    offset: u32,
    /// An object chosen (a head reached by Tab, or any object chosen by
    /// a click, ↑ or Tab among objects): its source start (the caret's
    /// offset), and its end when known (a structure and its base can
    /// start at the same byte: d² and d).
    head: ?u32 = null,
    head_end: ?u32 = null,
};

var canvas_eq: ?CanvasEq = null;
var canvas_eq_seq: u64 = 0;

/// What is edited's source, while it is still there (and an equation is
/// still one).
fn eqContent(q: CanvasEq) ?[]const u8 {
    switch (q.target) {
        .run => |r| {
            if (!state.model.hasParent(r.parent) or r.region >= state.model.regionsIn(r.parent).len) return null;
            const items = state.model.flowItems(r.parent, r.region);
            if (r.item >= items.len or items[r.item].what != .run or items[r.item].what.run.equation != q.math) return null;
            return items[r.item].what.run.content;
        },
        .tile_track => |tt| {
            if (state.model.tileIndex(tt.tile) == null or state.model.tileTrackIndex(tt.tile, tt.track) == null) return null;
            return state.model.tileTrackText(dvui.currentWindow().arena(), tt.tile, tt.track) catch null;
        },
    }
}

const EqParse = struct { e: glyphic.Expr, spans: glyphic.entry.Spans };

fn eqParse(a: std.mem.Allocator, src: []const u8, math: bool) ?EqParse {
    var p: EqParse = .{ .e = glyphic.Expr.init(a) catch return null, .spans = .{} };
    glyphic.latex.parse(&p.e, &p.spans, src, if (math) .math else .legend) catch return null;
    return p;
}

/// Chooses the object whose source is [`start`, `end`).
fn eqPick(from: u32, to: u32) void {
    eqMove(from, from);
    canvas_eq.?.head_end = to;
}

/// The object chosen in `q`, in parse `p`: by its span when its end is
/// known, else the structure whose head starts there.
fn pickAt(p: *const EqParse, q: CanvasEq) ?glyphic.Id {
    const h = q.head orelse return null;
    if (q.head_end) |end| {
        for (p.e.nodes.items, 0..) |n, k| {
            if (!n.live or n.kind == .row) continue;
            const id: glyphic.Id = @enumFromInt(k);
            if (id == p.e.root) continue;
            const sp = p.spans.get(id);
            if (sp.start == h and sp.end == end) return id;
        }
    }
    return headAt(p, h);
}

/// The objects of parse `p` in source order, what holds others before
/// them (d² before d), and empty fields (places to type): Tab's order
/// among objects.
const EqStop = struct { start: u32, end: u32, field: bool };

fn eqStops(a: std.mem.Allocator, p: *const EqParse) []EqStop {
    var out: std.ArrayList(EqStop) = .empty;
    for (p.e.nodes.items, 0..) |n, k| {
        if (!n.live) continue;
        const id: glyphic.Id = @enumFromInt(k);
        if (id == p.e.root or n.kind == .soft_hyphen) continue;
        const sp = p.spans.get(id);
        if (sp.start == glyphic.entry.Span.none.start) continue;
        if (n.kind == .row) {
            if (n.items.items.len > 0) continue;
            out.append(a, .{ .start = @intCast(sp.start), .end = @intCast(sp.end), .field = true }) catch {};
            continue;
        }
        out.append(a, .{ .start = @intCast(sp.start), .end = @intCast(sp.end), .field = false }) catch {};
    }
    std.mem.sort(EqStop, out.items, {}, struct {
        fn lt(_: void, x: EqStop, y: EqStop) bool {
            if (x.start != y.start) return x.start < y.start;
            return x.end > y.end;
        }
    }.lt);
    return out.items;
}

/// The structure whose head starts at byte `at`.
fn headAt(p: *const EqParse, at: u32) ?glyphic.Id {
    for (p.e.nodes.items, 0..) |n, k| {
        if (!n.live or !n.kind.hasHead()) continue;
        const id: glyphic.Id = @enumFromInt(k);
        if (p.spans.get(id).start == at) return id;
    }
    return null;
}

fn eqStore(q: CanvasEq, text: []const u8) void {
    const key = mergeKey(.{ "canvas equation", q.target.key(), canvas_eq_seq });
    const done = switch (q.target) {
        .run => |r| actM(key, .setRunContent, .{ r.parent, r.region, r.item, text }),
        .tile_track => |tt| actM(key, .setTileTrackText, .{ tt.tile, tt.track, text }),
    };
    done catch {
        state.status = "The text could not be changed. ";
    };
}

/// Sets the caret, leaving any head; the inspector follows it.
fn eqMove(offset: u32, head: ?u32) void {
    if (canvas_eq == null) return;
    canvas_eq.?.offset = offset;
    canvas_eq.?.head = head;
    canvas_eq.?.head_end = null;
    expr_inspect = .{ .key = canvas_eq.?.target.key(), .offset = offset };
}

/// Every place in `src` the caret can stop, in order: its ends, each
/// character's ends, each field's ends.
fn eqPlaces(a: std.mem.Allocator, src: []const u8, math: bool) []u32 {
    var out: std.ArrayList(u32) = .empty;
    out.append(a, 0) catch {};
    out.append(a, @intCast(src.len)) catch {};
    // In a legend, inside each pair of dollars too.
    if (!math) for (src, 0..) |ch, i| if (ch == '$' and (i == 0 or src[i - 1] != '\\')) {
        out.append(a, @intCast(i)) catch {};
        out.append(a, @intCast(i + 1)) catch {};
    };
    for (layout.edit.chars(a, src, math) catch &.{}) |c| {
        out.append(a, c.start) catch {};
        out.append(a, c.end) catch {};
    }
    if (eqParse(a, src, math)) |p| for (p.e.nodes.items, 0..) |n, k| {
        if (!n.live or n.kind != .row or k == @intFromEnum(p.e.root)) continue;
        const sp = p.spans.get(@enumFromInt(k));
        if (sp.start == glyphic.entry.Span.none.start) continue;
        out.append(a, sp.start) catch {};
        out.append(a, sp.end) catch {};
    };
    std.mem.sort(u32, out.items, {}, std.sort.asc(u32));
    return out.items;
}

/// The text run whose math (between dollars) the flow cursor is in, or
/// just after (past its closing $, or at the start of the item after a run
/// ending in math), with the caret's place in that run's source.
fn inlineMathAt(c: TrackCursor) ?struct { item: usize, offset: u32 } {
    const items = state.model.flowItems(c.parent, c.region);
    const isText = struct {
        fn f(its: []const layout.model.Item, i: usize) bool {
            return i < its.len and its[i].what == .run and !its[i].what.run.equation;
        }
    }.f;
    var item = c.index;
    var off = c.offset;
    if (off == 0 and c.index > 0 and isText(items, c.index - 1)) {
        item = c.index - 1;
        off = @intCast(items[item].what.run.content.len);
    }
    if (!isText(items, item)) return null;
    const src = items[item].what.run.content;
    if (layout.edit.mathAt(src, off) != null) return .{ .item = item, .offset = off };
    // Just past a closing $: before it, inside.
    if (off > 0 and src[off - 1] == '$') if (layout.edit.mathAt(src, off - 1)) |m| return .{ .item = item, .offset = m[1] };
    return null;
}

fn enterEquation() void {
    const c = track_cursor orelse return;
    var item: usize = 0;
    var offset: u32 = 0;
    // In a text run's math (between dollars): that run, its source edited
    // on the canvas as a legend.
    if (inlineMathAt(c)) |at| {
        {
            flow_anchor = null;
            canvas_eq = .{ .target = .{ .run = .{ .parent = c.parent, .region = c.region, .item = at.item } }, .math = false, .offset = at.offset };
            canvas_eq_seq += 1;
            eqMove(at.offset, null);
            state.status = "Inline math: type into it; Tab: heads and fields; Up or a click chooses an object: arrows nudge it, Tab the next, o out, = - [ ] 0 i u b style it, Esc back to typing; Esc leaves. ";
            return;
        }
    }
    if (equationAtCursor(c)) |eq| {
        item = eq.item;
        offset = eq.offset;
    } else {
        _ = deleteFlowSelection();
        const cc = track_cursor orelse return;
        const style = state.model.regionsIn(cc.parent)[cc.region].style orelse (labelStyle() catch return);
        item = act(.insertEquation, .{ cc.parent, cc.region, flowPos(cc), style }) catch return;
    }
    flow_anchor = null;
    canvas_eq = .{ .target = .{ .run = .{ .parent = c.parent, .region = c.region, .item = item } }, .math = true, .offset = offset };
    canvas_eq_seq += 1;
    eqMove(offset, null);
    state.status = "Equation: type into it; Tab: heads and fields; Up or a click chooses an object: arrows nudge it, Tab the next, o out, = - [ ] 0 i u b style it, Esc back to typing; Esc leaves. ";
}

/// Ctrl+\ on a selected tile: its track's text (the expression line's
/// track) edited on the canvas as a legend, the caret at its end.
fn enterTileTrack(id: TileId) void {
    const tr = exprTrackOf(id) orelse return;
    const target: ExprTarget = .{ .tile_track = .{ .tile = id, .track = tr } };
    canvas_eq = .{ .target = target, .math = false, .offset = 0 };
    const src = eqContent(canvas_eq.?) orelse {
        canvas_eq = null;
        return;
    };
    canvas_eq_seq += 1;
    eqMove(@intCast(src.len), null);
    state.status = "Tile text: type into it ($ starts math); Tab: heads and fields; Up or a click chooses an object: arrows nudge it, Tab the next, o out, = - [ ] 0 i u b style it, Esc back to typing; Esc leaves. ";
}

/// Leaves the equation: one with nothing in it goes; the flow cursor goes
/// after it (in a text run, after the math the caret was in).
fn leaveCanvasEquation() void {
    const q = canvas_eq orelse return;
    const content = eqContent(q);
    canvas_eq = null;
    state.status = "";
    typing_seq += 1;
    const src = content orelse return;
    const r = switch (q.target) {
        .run => |r| r,
        // A tile stays selected.
        .tile_track => return,
    };
    if (!q.math) {
        // A text run: the flow cursor after the math the caret was in.
        if (track_cursor) |*tc| if (tc.parent.eql(r.parent) and tc.region == r.region) {
            const end = if (layout.edit.mathAt(src, q.offset)) |m| @min(m[1] + 1, @as(u32, @intCast(src.len))) else q.offset;
            tc.index = r.item;
            tc.offset = end;
            if (end >= src.len) {
                tc.index = r.item + 1;
                tc.offset = 0;
            }
        };
        flow_anchor = null;
        return;
    }
    // Nothing in it (empty, or only empty structures): it goes.
    if (!(layout.edit.hasChars(dvui.currentWindow().arena(), src, true) catch true)) {
        const pos = act(.deleteRange, .{ r.parent, r.region, layout.model.FlowPos{ .index = r.item }, layout.model.FlowPos{ .index = r.item + 1 } }) catch return;
        if (track_cursor) |*tc| {
            tc.index = pos.index;
            tc.offset = pos.offset;
        }
        return;
    }
    if (track_cursor) |*tc| if (tc.parent.eql(r.parent) and tc.region == r.region) {
        tc.index = r.item + 1;
        tc.offset = 0;
    };
    flow_anchor = null;
}

/// Text typed into the equation (or, on a head, a head's key).
fn eqType(txt: []const u8) void {
    const q = canvas_eq orelse return;
    const src = eqContent(q) orelse {
        canvas_eq = null;
        return;
    };
    const a = dvui.currentWindow().arena();
    const at = @min(q.offset, @as(u32, @intCast(src.len)));
    // } over a } already there, or in a legend's math $ over its closing
    // $: step past it.
    const closes = (std.mem.eql(u8, txt, "}") and at < src.len and src[at] == '}') or
        (!q.math and std.mem.eql(u8, txt, "$") and at < src.len and src[at] == '$' and layout.edit.mathAt(src, at) != null);
    if (closes) {
        eqMove(at + 1, null);
        return;
    }
    // { with its }, and in a legend's text $ with its $: the caret between.
    const pair = std.mem.eql(u8, txt, "{") or (!q.math and std.mem.eql(u8, txt, "$") and layout.edit.mathAt(src, at) == null);
    const insert = if (!pair) txt else if (txt[0] == '{') "{}" else "$$";
    const next = std.mem.concat(a, u8, &.{ src[0..at], insert, src[at..] }) catch return;
    eqStore(q, next);
    eqMove(at + @as(u32, @intCast(if (pair) 1 else txt.len)), null);
}

/// While typing in an expression on the canvas: the object at the caret
/// chosen (else its first object). Whether one was.
fn eqChooseAtCaret() bool {
    const q = canvas_eq orelse return false;
    const src = eqContent(q) orelse return false;
    const a = dvui.currentWindow().arena();
    const p = eqParse(a, src, q.math) orelse return false;
    if (glyphic.entry.objectAt(&p.e, p.spans, q.offset)) |id| {
        const sp = p.spans.get(id);
        canvas_eq_seq += 1;
        eqPick(@intCast(sp.start), @intCast(sp.end));
        return true;
    }
    for (eqStops(a, &p)) |x| if (!x.field) {
        canvas_eq_seq += 1;
        eqPick(x.start, x.end);
        return true;
    };
    return false;
}

/// The chosen object's holder (the structure its field belongs to)
/// chosen. Whether it has one.
fn eqOut() bool {
    const q = canvas_eq orelse return false;
    const src = eqContent(q) orelse return false;
    const a = dvui.currentWindow().arena();
    const p = eqParse(a, src, q.math) orelse return false;
    const id = pickAt(&p, q) orelse return false;
    const h = p.e.holder(id) orelse return false;
    const sp = p.spans.get(h.structure);
    if (sp.start == glyphic.entry.Span.none.start) return false;
    canvas_eq_seq += 1;
    eqPick(@intCast(sp.start), @intCast(sp.end));
    return true;
}

/// Back to typing: the caret after what was chosen.
fn eqRelease() void {
    const q = canvas_eq orelse return;
    const a = dvui.currentWindow().arena();
    const p = if (eqContent(q)) |src| eqParse(a, src, q.math) else null;
    const end: u32 = if (p) |pp| (if (pickAt(&pp, q)) |id| @intCast(pp.spans.get(id).end) else q.offset) else q.offset;
    canvas_eq_seq += 1;
    eqMove(end, null);
}

/// The chosen object's first part chosen (the first object inside it).
/// Whether it has one.
fn eqIn() bool {
    const q = canvas_eq orelse return false;
    const src = eqContent(q) orelse return false;
    const a = dvui.currentWindow().arena();
    const p = eqParse(a, src, q.math) orelse return false;
    const id = pickAt(&p, q) orelse return false;
    const sp = p.spans.get(id);
    for (eqStops(a, &p)) |x| {
        if (x.field or x.start < sp.start or x.end > sp.end) continue;
        if (x.start == sp.start and x.end == sp.end) continue;
        canvas_eq_seq += 1;
        eqPick(x.start, x.end);
        return true;
    }
    return false;
}

/// How far an arrow nudges the chosen object, cap heights.
const nudge_step: f32 = 0.02;

/// A head's key: a parameter changed, or a slot opened, hidden or shown.
/// `dx`, `dy`: an arrow's nudge, cap heights.
fn eqHeadKey(ch: u8, dx: f32, dy: f32) void {
    const q = canvas_eq orelse return;
    const head = q.head orelse return;
    const src = eqContent(q) orelse return;
    const a = dvui.currentWindow().arena();
    var p = eqParse(a, src, q.math) orelse return;
    const id = pickAt(&p, q) orelse {
        eqMove(q.offset, null);
        return;
    };
    const n = p.e.node(id);
    const P = glyphic.Param;
    const num = struct {
        fn f(e: *const glyphic.Expr, i: glyphic.Id, prm: P) f32 {
            return if (e.override(i, prm)) |v| v.number else glyphic.param.def(prm).default.number;
        }
        fn round(x: f32) f32 {
            return @round(x * 1000) / 1000;
        }
    };
    // Opening a slot the source does not have yet: written in, the caret
    // in it.
    const open: ?struct { at: u32, text: []const u8, caret: u32 } = switch (ch) {
        'i' => blk: {
            if (n.kind != .radical or p.e.slot(id, .index) != .none) break :blk null;
            // After its \sqrt (a call around it comes first).
            const sp = p.spans.get(id);
            const at = std.mem.indexOfPos(u8, src[0..sp.end], sp.start, "\\sqrt") orelse break :blk null;
            break :blk .{ .at = @as(u32, @intCast(at + "\\sqrt".len)), .text = "[]", .caret = 1 };
        },
        'u', 'b' => blk: {
            const sl: glyphic.expr.Slot = if (ch == 'u') .sup else .sub;
            if (n.kind == .large_op and p.e.slot(id, sl) != .none) break :blk null;
            break :blk .{ .at = p.spans.get(id).end, .text = if (ch == 'u') "^{}" else "_{}", .caret = 2 };
        },
        else => null,
    };
    if (open) |o| {
        const next = std.mem.concat(a, u8, &.{ src[0..o.at], o.text, src[o.at..] }) catch return;
        eqStore(q, next);
        eqMove(o.at + o.caret, null);
        return;
    }
    switch (ch) {
        '=', '+' => p.e.set(id, .scale, glyphic.param.num(num.round(@min(10, num.f(&p.e, id, .scale) * 1.1)))) catch {},
        '-' => p.e.set(id, .scale, glyphic.param.num(num.round(@max(0.1, num.f(&p.e, id, .scale) / 1.1)))) catch {},
        '[' => p.e.set(id, .rotate, glyphic.param.num(std.math.clamp(num.f(&p.e, id, .rotate) - 15, -180, 180))) catch {},
        ']' => p.e.set(id, .rotate, glyphic.param.num(std.math.clamp(num.f(&p.e, id, .rotate) + 15, -180, 180))) catch {},
        '0' => {
            var k = p.e.node(id).overrides.items.len;
            while (k > 0) {
                k -= 1;
                const o = p.e.node(id).overrides.items[k];
                if (!glyphic.entry.implied(&p.e, id, o.param)) p.e.clear(id, o.param);
            }
        },
        'i', 'u', 'b' => {
            // A slot there: hidden (its contents kept), or shown again.
            const sl: glyphic.expr.Slot = if (ch == 'i') .index else if (ch == 'u') .sup else .sub;
            const prm = sl.showParam().?;
            const hidden = if (p.e.override(id, prm)) |v| glyphic.param.as(glyphic.param.SlotShow, v) == .hidden else false;
            if (hidden) p.e.clear(id, prm) else p.e.set(id, prm, glyphic.param.of(glyphic.param.SlotShow.hidden)) catch {};
        },
        0 => {
            // Nudged: further from (or closer to) the object before it,
            // what follows moving along; up or down from its baseline.
            if (dx != 0) p.e.set(id, .space_before, glyphic.param.num(num.round(std.math.clamp(num.f(&p.e, id, .space_before) + dx, -4, 4)))) catch {};
            if (dy != 0) p.e.set(id, .shift_y, glyphic.param.num(num.round(std.math.clamp(num.f(&p.e, id, .shift_y) + dy, -4, 4)))) catch {};
            // Back to nothing set: its own value cleared.
            inline for (.{ glyphic.Param.space_before, glyphic.Param.shift_y }) |prm| if (p.e.override(id, prm)) |v| if (v.number == 0) p.e.clear(id, prm);
        },
        else => return,
    }
    const sp = p.spans.get(id);
    const next = glyphic.entry.rewriteCall(a, src, sp, &p.e, id) catch return;
    eqStore(q, next);
    // It starts where it did (its call, if any, begins there); its end
    // moved by what the call added or took.
    const grown: i64 = @as(i64, @intCast(next.len)) - @as(i64, @intCast(src.len));
    eqPick(head, @intCast(@as(i64, @intCast(sp.end)) + grown));
}

/// A key while editing an equation on the canvas; whether it was one.
/// An action of mode `canvas.equation` (or, on a head,
/// `canvas.equation.head`); whether it was done.
fn eqAction(inv: keymap.Invocation) bool {
    const q = canvas_eq orelse return false;
    const src = eqContent(q) orelse {
        canvas_eq = null;
        return false;
    };
    const a = dvui.currentWindow().arena();
    const back = inv.arg == 1;
    // On a head: its keys, as the character each is.
    const head_chars = [_]struct { name: []const u8, ch: u8 }{
        .{ .name = "scale-up", .ch = '=' },   .{ .name = "scale-down", .ch = '-' },
        .{ .name = "turn-left", .ch = '[' },  .{ .name = "turn-right", .ch = ']' },
        .{ .name = "reset", .ch = '0' },      .{ .name = "slot-index", .ch = 'i' },
        .{ .name = "slot-upper", .ch = 'u' }, .{ .name = "slot-lower", .ch = 'b' },
    };
    inline for (head_chars) |hc| if (inv.action == kact("canvas.equation.head." ++ hc.name)) {
        if (q.head == null) return false;
        eqHeadKey(hc.ch, 0, 0);
        return true;
    };
    switch (inv.action) {
        kact("canvas.equation.leave") => {
            leaveCanvasEquation();
            return true;
        },
        kact("canvas.equation.head.nudge") => {
            if (q.head == null) return false;
            switch (inv.dir()) {
                .left => eqHeadKey(0, -nudge_step, 0),
                .right => eqHeadKey(0, nudge_step, 0),
                .up => eqHeadKey(0, 0, nudge_step),
                .down => eqHeadKey(0, 0, -nudge_step),
            }
            return true;
        },
        kact("canvas.equation.choose") => {
            _ = eqChooseAtCaret();
            return true;
        },
        kact("canvas.equation.head.next") => {
            // The next (or previous) object; an empty field: the caret in it.
            const p = eqParse(a, src, q.math) orelse return true;
            const all = eqStops(a, &p);
            if (all.len == 0) return true;
            const cur: EqStop = .{ .start = q.head.?, .end = q.head_end orelse if (pickAt(&p, q)) |id| @intCast(p.spans.get(id).end) else q.head.?, .field = false };
            const at: ?usize = for (all, 0..) |x, k| {
                if (x.start == cur.start and x.end == cur.end and !x.field) break k;
            } else null;
            const to: EqStop = if (back) blk: {
                const k = at orelse all.len;
                break :blk if (k == 0) all[all.len - 1] else all[k - 1];
            } else blk: {
                const k = if (at) |i| i + 1 else 0;
                break :blk if (k >= all.len) all[0] else all[k];
            };
            canvas_eq_seq += 1;
            if (to.field) eqMove(to.start, null) else eqPick(to.start, to.end);
            return true;
        },
        kact("canvas.equation.head.out") => {
            _ = eqOut();
            return true;
        },
        kact("canvas.equation.head.release") => {
            eqRelease();
            return true;
        },
        kact("canvas.equation.tab") => {
            var p = eqParse(a, src, q.math) orelse return true;
            var g = glyphic.Engine.init(state.gpa);
            defer g.deinit();
            const r = glyphic.Resolver.init(&g, &p.e, &.{});
            const on: ?glyphic.Id = if (q.head) |h| headAt(&p, h) else null;
            const to = (glyphic.stops.tabStop(a, &r, p.spans, q.offset, on, back) catch null) orelse return true;
            const off: u32 = @intCast(glyphic.stops.offset(p.spans, to) orelse return true);
            canvas_eq_seq += 1;
            eqMove(off, if (to == .head) off else null);
            return true;
        },
        kact("canvas.equation.caret.left"), kact("canvas.equation.caret.right"), kact("canvas.equation.caret.start"), kact("canvas.equation.caret.end") => {
            const places = eqPlaces(a, src, q.math);
            var to = q.offset;
            switch (inv.action) {
                kact("canvas.equation.caret.start") => to = 0,
                kact("canvas.equation.caret.end") => to = @intCast(src.len),
                kact("canvas.equation.caret.left") => {
                    var i = places.len;
                    while (i > 0) : (i -= 1) if (places[i - 1] < q.offset) {
                        to = places[i - 1];
                        break;
                    };
                },
                else => for (places) |x| if (x > q.offset) {
                    to = x;
                    break;
                },
            }
            canvas_eq_seq += 1;
            eqMove(to, null);
            return true;
        },
        kact("canvas.equation.delete-back"), kact("canvas.equation.delete-forward") => {
            const backspace = inv.action == kact("canvas.equation.delete-back");
            if (q.head != null) {
                eqMove(q.offset, null);
                return true;
            }
            const cs = layout.edit.chars(a, src, q.math) catch return true;
            var hit: ?layout.edit.Char = null;
            if (backspace) {
                for (cs) |c| if (c.end <= q.offset) {
                    hit = c;
                };
            } else for (cs) |c| if (c.start >= q.offset) {
                hit = c;
                break;
            };
            const c = hit orelse return true;
            const next = layout.edit.deleteChars(a, src, c.start, c.start + 1, q.math) catch return true;
            eqStore(q, next);
            eqMove(if (backspace) c.start else q.offset, null);
            return true;
        },
        else => return false,
    }
}

/// Which part of what is edited placed label `l` of panel `pi` draws: its
/// run's source bytes [`from`, `from + len`) (len 0: all of it), counted
/// from `base` in what is edited (0 for a run of a flow; for a tile's
/// track, past the runs and breaks before it). Null when it draws
/// something else.
const EqPiece = struct { from: u32, len: u32, base: u32 };

fn eqPiece(pi: Parent, l: layout.place.PlacedLabel) ?EqPiece {
    const q = canvas_eq orelse return null;
    if (placedOf(pi) == null) return null;
    return switch (q.target) {
        .run => |t| blk: {
            const run = l.run orelse return null;
            if (!run.parent.eql(t.parent) or run.region != t.region or run.item != t.item) return null;
            break :blk .{ .from = run.from, .len = run.len, .base = 0 };
        },
        .tile_track => |tt| blk: {
            const tr = l.tile_run orelse return null;
            if (l.tile == null or l.tile.? != tt.tile) return null;
            const k = state.model.tileTrackIndex(tt.tile, tt.track) orelse return null;
            if (l.slot != k) return null;
            const f = state.model.tileFlow(tt.tile, tt.track) orelse return null;
            var base: u32 = 0;
            for (f.items.items[0..@min(tr.item, f.items.items.len)]) |it| base += switch (it.what) {
                .run => |r| @intCast(r.content.len),
                .hard_break, .paragraph => 1,
                .tile => 0,
            };
            break :blk .{ .from = tr.from, .len = tr.len, .base = base };
        },
    };
}

/// The object chosen while an expression is edited on the canvas (the
/// head's structure, else the object at the caret), with its neighbours
/// in its row: source spans in what is edited, and its own nudges.
const EqChoice = struct {
    const Span = struct { start: u32, end: u32 };
    object: Span,
    prev: ?Span,
    next: ?Span,
    kind: glyphic.Kind,
    text: []const u8,
    /// Its own space_before and shift_y, cap heights.
    space_before: f32,
    shift_y: f32,
};

fn eqChoice(a: std.mem.Allocator) ?EqChoice {
    const q = canvas_eq orelse return null;
    const src = eqContent(q) orelse return null;
    const p = eqParse(a, src, q.math) orelse return null;
    const id = pickAt(&p, q) orelse glyphic.entry.objectAt(&p.e, p.spans, q.offset) orelse return null;
    const span = struct {
        fn of(pp: *const EqParse, x: glyphic.Id) ?EqChoice.Span {
            const sp = pp.spans.get(x);
            if (sp.start == glyphic.entry.Span.none.start) return null;
            return .{ .start = @intCast(sp.start), .end = @intCast(sp.end) };
        }
    };
    const n = p.e.node(id);
    var prev: ?EqChoice.Span = null;
    var next: ?EqChoice.Span = null;
    if (n.parent != .none) {
        const items = p.e.node(n.parent).items.items;
        if (std.mem.indexOfScalar(glyphic.Id, items, id)) |k| {
            if (k > 0) prev = span.of(&p, items[k - 1]);
            if (k + 1 < items.len) next = span.of(&p, items[k + 1]);
        }
    }
    const num = struct {
        fn f(e: *const glyphic.Expr, i: glyphic.Id, prm: glyphic.Param) f32 {
            return if (e.override(i, prm)) |v| v.number else 0;
        }
    };
    return .{
        .object = span.of(&p, id) orelse return null,
        .prev = prev,
        .next = next,
        .kind = n.kind,
        .text = n.text,
        .space_before = num.f(&p.e, id, .space_before),
        .shift_y = num.f(&p.e, id, .shift_y),
    };
}

/// The box in render `r` drawing source span `sp` of what is edited (a
/// piece at `base`): a leaf's or a structure's, not a field's.
fn eqBoxOf(r: *const layout.render.Render, sp: ?EqChoice.Span, base: u32) ?layout.render.ObjectBox {
    const s = sp orelse return null;
    if (s.start < base) return null;
    for (r.boxes) |b| if (b.kind != .field and b.start == s.start - base and b.end == s.end - base) return b;
    return null;
}

/// What an expression edited on the canvas is, for the properties: a
/// tile's slot ("K12, slot top") or a run of a flow ("equation 3 in Row1").
fn eqTargetName(buf: []u8, q: CanvasEq) []const u8 {
    return switch (q.target) {
        .tile_track => |tt| blk: {
            const t = state.model.tileConst(tt.tile);
            const slot = for (state.model.prototypeOf(tt.tile).tracks) |tr| {
                if (tr.id == tt.track) break tr.name;
            } else "?";
            break :blk std.fmt.bufPrint(buf, "{s}, slot {s}", .{ if (t.designator.len > 0) t.designator else "a tile", slot }) catch "a tile's slot";
        },
        .run => |r| std.fmt.bufPrint(buf, "{s} {d} in {s}", .{ if (q.math) "equation" else "text run", r.item + 1, state.model.regionsIn(r.parent)[r.region].name }) catch "a run",
    };
}

/// What the chosen object measures, as last drawn: its gaps to its
/// neighbours along the baseline and its baseline's height above the
/// slot's, mm; its cap height, for the nudges in cap heights.
const EqMeasure = struct { of: struct { offset: u32, head: ?u32, head_end: ?u32 }, gap_before: ?f64, gap_after: ?f64, raised: f64, cap: f64, width: f64, height: f64, depth: f64 };
var eq_measure: ?EqMeasure = null;

fn boxBounds(b: layout.render.ObjectBox) geom.Box {
    var out: geom.Box = .empty;
    for (b.corners) |c| out = out.addPoint(c);
    return out;
}

fn strokeQuad(area: dvui.Rect.Physical, c: [4]geom.Point, at: geom.Point, colour: dvui.Color, width: f32) void {
    var pts: [4]dvui.Point.Physical = undefined;
    for (c, &pts) |q, *o| o.* = state.view.toPx(area, .{ .x = q.x + at.x, .y = q.y + at.y });
    dvui.Path.stroke(.{ .points = &pts }, .{ .thickness = width, .color = .{ .color = colour }, .closed = true });
}

/// The equation in placed label `l` of panel `pi`, while it is edited:
/// every layout object's box, the slot's baseline, the chosen object
/// strong (its neighbours a little stronger than the rest), then the
/// caret: a bar, or on a head nothing more (its box is the choice).
/// Drawn at worksheet offset `o`.
fn drawCanvasEq(area: dvui.Rect.Physical, pi: Parent, l: layout.place.PlacedLabel, o: geom.Point) void {
    const q = canvas_eq orelse return;
    const piece = eqPiece(pi, l) orelse return;
    const px = dvui.windowNaturalScale();
    const at: geom.Point = .{ .x = l.origin.x + o.x, .y = l.origin.y + o.y };
    const a = dvui.currentWindow().arena();
    const r = l.render;

    // The slot's baseline, across what this piece draws.
    if (r.boxes.len > 0) {
        var x0: f64 = r.design.x0;
        var x1: f64 = r.design.x1;
        for (r.boxes) |b| {
            x0 = @min(x0, b.baseline[0].x);
            x1 = @max(x1, b.baseline[1].x);
        }
        const p0 = state.view.toPx(area, .{ .x = at.x + x0, .y = at.y });
        const p1 = state.view.toPx(area, .{ .x = at.x + x1, .y = at.y });
        dvui.Path.stroke(.{ .points = &.{ p0, p1 } }, .{ .thickness = px, .color = .{ .color = construction.baseline.opacity(0.7) } });
    }
    // Every object's box: fields faintest, then leaves and structures.
    for (r.boxes) |b| {
        const alpha: f32 = if (b.kind == .field) 0.18 else 0.35;
        strokeQuad(area, b.corners, at, colors.select.opacity(alpha), px);
    }
    const choice = eqChoice(a);
    if (choice) |c| {
        const mine = eqBoxOf(r, c.object, piece.base);
        const before = eqBoxOf(r, c.prev, piece.base);
        const after = eqBoxOf(r, c.next, piece.base);
        if (before) |b| strokeQuad(area, b.corners, at, colors.select.opacity(0.6), 1.5 * px);
        if (after) |b| strokeQuad(area, b.corners, at, colors.select.opacity(0.6), 1.5 * px);
        if (mine) |b| {
            strokeQuad(area, b.corners, at, colors.select, 2 * px);
            // Its own baseline, where it stands.
            const p0 = state.view.toPx(area, .{ .x = at.x + b.baseline[0].x, .y = at.y + b.baseline[0].y });
            const p1 = state.view.toPx(area, .{ .x = at.x + b.baseline[1].x, .y = at.y + b.baseline[1].y });
            dvui.Path.stroke(.{ .points = &.{ p0, p1 } }, .{ .thickness = 2 * px, .color = .{ .color = construction.baseline } });
            const bb = boxBounds(b);
            const cap: f64 = if (b.element < r.elements.len) r.elements[b.element].cap_height else 1;
            const m: EqMeasure = .{
                .of = .{ .offset = q.offset, .head = q.head, .head_end = q.head_end },
                .gap_before = if (before) |p| bb.x0 - boxBounds(p).x1 else null,
                .gap_after = if (after) |n| boxBounds(n).x0 - bb.x1 else null,
                .raised = b.baseline[0].y,
                .cap = cap,
                .width = b.baseline[1].x - b.baseline[0].x,
                .height = bb.y1 - b.baseline[0].y,
                .depth = b.baseline[0].y - bb.y0,
            };
            const changed = if (eq_measure) |was| !std.meta.eql(was, m) else true;
            eq_measure = m;
            if (changed) dvui.refresh(null, @src(), null);
        }
    }
    if (q.head != null) return;
    if (q.offset < piece.base) return;
    const local = q.offset - piece.base;
    if (piece.len > 0 and (local < piece.from or local > piece.from + piece.len)) return;
    const c = caretAt(r, local) orelse return;
    const p0 = state.view.toPx(area, .{ .x = at.x + c.x, .y = at.y + c.y0 });
    const p1 = state.view.toPx(area, .{ .x = at.x + c.x, .y = at.y + c.y1 });
    markCaret(p0, p1);
    speckleCaret(p0, p1);
}

// Pointing (decided 2026-11-20): near a container's outline the
// pointer highlights the container, and a press selects it; inside, away
// from the outline, it highlights the content, and a press goes into it:
// an editable text at the nearest place between its glyphs. Inside an
// expression being edited, the same for its objects: near an object's
// box, the object (chosen); inside it, the caret.

/// How near an outline counts as on it, in screen pixels.
const edge_px: f64 = 5;

/// What the pointer is over.
const HoverTarget = union(enum) {
    /// Near a container's outline: the container.
    tile: struct { id: TileId, box: geom.Box },
    track: struct { parent: Parent, region: usize, box: geom.Box },
    /// A segment of a track that holds content (an empty one has no
    /// boundary until it does): `panel` and `region` name the track holding
    /// the flow, `row` the segment's index in it.
    row: struct { parent: Parent, region: usize, row: usize, box: geom.Box },
    panel: struct { panel: usize, box: geom.Box },
    /// A grid on a panel (keys placed on a pitch grid): its whole extent.
    grid: struct { parent: Parent, index: usize },
    art: struct { panel: usize, index: usize, box: geom.Box },
    /// A placed figure, by its boundary.
    figure_place: struct { space: usize, index: usize, box: geom.Box },
    /// Near a construction line: the line (its part in view).
    guide: struct { space: usize, index: usize, seg: [2]geom.Point },
    /// Inside a tile, a slot's text: its label, and where in its source.
    slot: struct { tile: TileId, parent: Parent, label: usize, box: geom.Box, offset: u32 },
    /// In an expression being edited: near an object's box (chosen by a
    /// press), or inside text (the caret put there).
    eq_object: struct { start: u32, end: u32, corners: [4]geom.Point, at: geom.Point },
    eq_caret: struct { offset: u32 },
};

/// The edge tolerance in mm at the view's zoom.
fn edgeMm() f64 {
    return edge_px / @max(state.view.ppm, 1e-6);
}

/// How far `p` is from box `b`'s outline (inside or out), mm.
fn outlineDistance(b: geom.Box, p: geom.Point) f64 {
    const inside = p.x >= b.x0 and p.x <= b.x1 and p.y >= b.y0 and p.y <= b.y1;
    if (inside) return @min(@min(p.x - b.x0, b.x1 - p.x), @min(p.y - b.y0, b.y1 - p.y));
    const dx = @max(@max(b.x0 - p.x, 0), p.x - b.x1);
    const dy = @max(@max(b.y0 - p.y, 0), p.y - b.y1);
    return @sqrt(dx * dx + dy * dy);
}

/// A label's box on the worksheet (its design box, the ink's where wider).
fn labelBox(pi: Parent, l: layout.place.PlacedLabel) geom.Box {
    const o = parentOrigin(pi);
    const d = l.render.design.join(l.render.ink);
    return .{ .x0 = d.x0 + l.origin.x + o.x, .y0 = d.y0 + l.origin.y + o.y, .x1 = d.x1 + l.origin.x + o.x, .y1 = d.y1 + l.origin.y + o.y };
}

/// Where the caret at source offset `off` stands in render `r`: at the
/// edge of the innermost object or field that starts or ends there (so
/// every place inside an expression's braces has one: after the last of
/// a script's characters, before its `}`), else where the render's own
/// stops put it.
fn caretAt(r: *const layout.render.Render, off: u32) ?layout.render.Caret {
    var best: ?struct { c: layout.render.Caret, nest: u8 } = null;
    for (r.boxes) |b| {
        if (b.kind == .structure) continue;
        // A leaf's edges are its characters' (inside \mathrm{…}'s braces).
        const at_start = (if (b.kind == .leaf) b.inner_start else b.start) == off;
        const at_end = (if (b.kind == .leaf) b.inner_end else b.end) == off;
        if (!at_start and !at_end) continue;
        if (best != null and best.?.nest >= b.nest) continue;
        const bb = boxBounds(b);
        // A field's height is its contents'; an empty one keeps a little.
        const y0 = @min(bb.y0, b.baseline[0].y);
        const y1 = @max(bb.y1, b.baseline[0].y + 0.3);
        best = .{ .c = .{ .x = if (at_end) bb.x1 else bb.x0, .y0 = y0, .y1 = y1 }, .nest = b.nest };
    }
    if (best) |x| return x.c;
    return r.caret(off);
}

/// The source offset in label `l` of panel `pi` (counted from `base` in
/// what it is part of) whose caret is nearest worksheet point `p`.
fn nearestCaret(pi: Parent, l: layout.place.PlacedLabel, p: geom.Point, src_len: u32) u32 {
    const o = parentOrigin(pi);
    const local: geom.Point = .{ .x = p.x - l.origin.x - o.x, .y = p.y - l.origin.y - o.y };
    var best: u32 = 0;
    var best_d: f64 = std.math.inf(f64);
    var off: u32 = 0;
    while (off <= src_len) : (off += 1) {
        const c = caretAt(l.render, off) orelse continue;
        const dy = if (local.y < c.y0) c.y0 - local.y else if (local.y > c.y1) local.y - c.y1 else 0;
        const d = @abs(c.x - local.x) + 4 * dy;
        if (d < best_d) {
            best_d = d;
            best = off;
        }
    }
    return best;
}

/// The end of the source label `l` draws (its elements' last byte).
fn renderEnd(l: layout.place.PlacedLabel) u32 {
    var end: u32 = 0;
    for (l.render.elements) |e| end = @max(end, e.end);
    return end;
}

/// What the pointer at worksheet point `p` is over (see "Pointing").
fn hoverTargetAt(p: geom.Point) ?HoverTarget {
    const tol = edgeMm();
    // In an expression being edited: its objects first.
    if (canvas_eq) |q| {
        var best: ?struct { b: layout.render.ObjectBox, base: u32, pi: Parent, l: layout.place.PlacedLabel } = null;
        for (state.solved.items, 0..) |placed, k| for (placed.labels) |l| {
            const pi = state.model.parentAt(k);
            const piece = eqPiece(pi, l) orelse continue;
            const o = parentOrigin(pi);
            const local: geom.Point = .{ .x = p.x - l.origin.x - o.x, .y = p.y - l.origin.y - o.y };
            for (l.render.boxes) |b| {
                if (b.kind == .field) continue;
                const bb = boxBounds(b);
                const grown: geom.Box = .{ .x0 = bb.x0 - tol, .y0 = bb.y0 - tol, .x1 = bb.x1 + tol, .y1 = bb.y1 + tol };
                if (!contains(grown, local)) continue;
                if (best == null or b.nest > best.?.b.nest) best = .{ .b = b, .base = piece.base, .pi = pi, .l = l };
            }
        };
        if (best) |h| {
            const o = parentOrigin(h.pi);
            const local: geom.Point = .{ .x = p.x - h.l.origin.x - o.x, .y = p.y - h.l.origin.y - o.y };
            if (outlineDistance(boxBounds(h.b), local) <= tol)
                return .{ .eq_object = .{ .start = h.b.start + h.base, .end = h.b.end + h.base, .corners = h.b.corners, .at = .{ .x = h.l.origin.x + o.x, .y = h.l.origin.y + o.y } } };
            _ = q;
            return .{ .eq_caret = .{ .offset = h.base + nearestCaret(h.pi, h.l, p, renderEnd(h.l)) } };
        }
    }
    // A construction line, drawn over everything: near it, the line.
    if (canvas_px) |area| if (guideNear(area, p)) |g| return .{ .guide = .{ .space = shown_space, .index = g.index, .seg = g.seg } };
    // A tile: near its outline, the tile; inside, the slot nearest.
    for (state.solved.items, 0..) |placed, pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi)) continue;
        for (placed.tiles) |t| {
            if (t.spacer) continue;
            const body = onSheet(pi, t.body);
            const grown: geom.Box = .{ .x0 = body.x0 - tol, .y0 = body.y0 - tol, .x1 = body.x1 + tol, .y1 = body.y1 + tol };
            if (!contains(grown, p)) continue;
            if (outlineDistance(body, p) <= tol) return .{ .tile = .{ .id = t.id, .box = body } };
            var best: ?struct { k: usize, d: f64, box: geom.Box } = null;
            for (placed.labels, 0..) |l, k| {
                if (l.tile == null or l.tile.? != t.id) continue;
                const lb = labelBox(pi, l);
                const d = outlineDistance(lb, p) * @as(f64, if (contains(lb, p)) -1 else 1);
                if (best == null or d < best.?.d) best = .{ .k = k, .d = d, .box = lb };
            }
            const hit = best orelse return .{ .tile = .{ .id = t.id, .box = body } };
            const l = placed.labels[hit.k];
            return .{ .slot = .{ .tile = t.id, .parent = pi, .label = hit.k, .box = hit.box, .offset = nearestCaret(pi, l, p, renderEnd(l)) } };
        }
    }
    // A track's outline, then a panel's.
    for (state.solved.items, 0..) |placed, k| {
        const pi = state.model.parentAt(k);
        if (!shownIn(pi)) continue;
        for (placed.tracks) |t| {
            const b = onSheet(pi, t.box);
            if (outlineDistance(b, p) <= tol) return .{ .track = .{ .parent = t.parent, .region = t.member, .box = b } };
        }
    }
    for (state.model.panels.items, 0..) |panel, pi| {
        if (!shownPanel(pi)) continue;
        const b = panel.box();
        if (outlineDistance(b, p) <= tol) return .{ .panel = .{ .panel = pi, .box = b } };
    }
    return null;
}

/// Whether worksheet point `p` is on one of the selection's resize
/// handles (a press there drags it).
fn selectionHandleAt(p: geom.Point) bool {
    var hb: [8]Handle = undefined;
    const tol = 6 / state.view.ppm;
    for (hb[0..resizeHandles(&hb)]) |h| {
        if (@abs(h.at.x - p.x) <= tol and @abs(h.at.y - p.y) <= tol) return true;
    }
    return false;
}

/// Boundaries' halos (`haloBox`, `haloSegment`), logical pixels: half the
/// core stroke, the glow's opacity at the core and its falloff radius
/// (a(t) = a0 / (1 + (t/r0)²)), and the opacity it is cut off at. The
/// owner, 2026-11-21, twice: too wide (core 3 px, r0 5 then 3 px, reaching
/// some 19 px); now a 1.5 px core and a glow gone within 6 px.
const halo_core_half: f64 = 0.75;
const halo_a0: f64 = 0.45;
const halo_r0: f64 = 1.5;
const halo_cut: f64 = 0.03;

/// A line's halo (device pixels, `p0` to `p1`): the inverse-square glow of
/// `haloBox` round a segment, its rings stadiums (a segment offset).
fn haloSegment(p0: dvui.Point.Physical, p1: dvui.Point.Physical, colour: dvui.Color) void {
    const Index = dvui.Vertex.Index;
    const ns: f64 = dvui.windowNaturalScale();
    const dx: f64 = p1.x - p0.x;
    const dy: f64 = p1.y - p0.y;
    const len = @sqrt(dx * dx + dy * dy);
    if (!(len > 0)) return;
    const base = std.math.atan2(dy, dx);
    const hw = halo_core_half * ns;
    const a0: f64 = halo_a0;
    const r0 = halo_r0 * ns;
    const t_max = r0 * @sqrt(a0 / halo_cut - 1);
    var rings: [26]struct { r: f64, a: f64 } = undefined;
    var n: usize = 0;
    rings[n] = .{ .r = 0.01, .a = 0.95 };
    n += 1;
    rings[n] = .{ .r = hw, .a = 0.95 };
    n += 1;
    rings[n] = .{ .r = hw + 0.8 * ns, .a = a0 };
    n += 1;
    var k: f64 = 1;
    while (n < rings.len - 1) : (k += 1) {
        const t = r0 * (std.math.pow(f64, 2, k * 0.5) - 1);
        if (t >= t_max) break;
        rings[n] = .{ .r = hw + 0.8 * ns + t, .a = a0 / (1 + (t / r0) * (t / r0)) };
        n += 1;
    }
    rings[n] = .{ .r = hw + 0.8 * ns + t_max, .a = 0 };
    n += 1;
    const K = 8;
    const per = 2 * K;
    const lifo = dvui.currentWindow().lifo();
    var tb = dvui.Triangles.Builder.init(lifo, n * per, (n - 1) * per * 6) catch return;
    defer tb.deinit(lifo);
    const ends = [2][2]f64{ .{ p1.x, p1.y }, .{ p0.x, p0.y } };
    for (rings[0..n]) |r| {
        const col: dvui.Color.PMA = .fromColor(colour.opacity(@floatCast(r.a)));
        for (0..2) |e| for (0..K) |i| {
            const th = base - 0.5 * std.math.pi + @as(f64, @floatFromInt(e)) * std.math.pi + std.math.pi * @as(f64, @floatFromInt(i)) / (K - 1);
            tb.appendVertex(.{ .pos = .{ .x = @floatCast(ends[e][0] + r.r * @cos(th)), .y = @floatCast(ends[e][1] + r.r * @sin(th)) }, .col = col });
        };
    }
    for (0..n - 1) |j| for (0..per) |i| {
        const a: Index = @intCast(j * per + i);
        const b: Index = @intCast(j * per + (i + 1) % per);
        const c: Index = @intCast((j + 1) * per + i);
        const d: Index = @intCast((j + 1) * per + (i + 1) % per);
        const v = tb.vertexes.items;
        tb.appendTriangles(&ccw(v[a].pos, v[b].pos, v[c].pos, a, b, c));
        tb.appendTriangles(&ccw(v[b].pos, v[d].pos, v[c].pos, b, d, c));
    };
    dvui.renderTriangles(tb.build_unowned(), null) catch {};
}

/// A drag point's halo: the same inverse-square glow as `haloBox`, round
/// about a grip of half size `half` at `q` (device pixels), drawn under it.
fn haloPoint(q: dvui.Point.Physical, half: f32, colour: dvui.Color) void {
    const Index = dvui.Vertex.Index;
    const ns: f64 = dvui.windowNaturalScale();
    // Grab points: a fuller glow than boundaries' (the owner: subtle at 4 px).
    const a0: f64 = 0.7;
    const r0 = 5 * ns;
    const t_max = r0 * @sqrt(a0 / 0.012 - 1);
    const inner: f64 = @as(f64, half) * 1.2;
    var radii: [24]struct { r: f64, a: f64 } = undefined;
    var n: usize = 0;
    radii[n] = .{ .r = inner, .a = a0 };
    n += 1;
    var k: f64 = 1;
    while (n < radii.len - 1) : (k += 1) {
        const t = r0 * (std.math.pow(f64, 2, k * 0.5) - 1);
        if (t >= t_max) break;
        radii[n] = .{ .r = inner + t, .a = a0 / (1 + (t / r0) * (t / r0)) };
        n += 1;
    }
    radii[n] = .{ .r = inner + t_max, .a = 0 };
    n += 1;
    const seg = 28;
    const lifo = dvui.currentWindow().lifo();
    var tb = dvui.Triangles.Builder.init(lifo, n * seg, (n - 1) * seg * 6) catch return;
    defer tb.deinit(lifo);
    for (radii[0..n]) |r| {
        const col: dvui.Color.PMA = .fromColor(colour.opacity(@floatCast(r.a)));
        for (0..seg) |i| {
            const th = 2 * std.math.pi * @as(f64, @floatFromInt(i)) / seg;
            tb.appendVertex(.{ .pos = .{ .x = q.x + @as(f32, @floatCast(r.r * @cos(th))), .y = q.y + @as(f32, @floatCast(r.r * @sin(th))) }, .col = col });
        }
    }
    for (0..n - 1) |j| for (0..seg) |i| {
        const a: Index = @intCast(j * seg + i);
        const b: Index = @intCast(j * seg + (i + 1) % seg);
        const c: Index = @intCast((j + 1) * seg + i);
        const d: Index = @intCast((j + 1) * seg + (i + 1) % seg);
        const v = tb.vertexes.items;
        tb.appendTriangles(&ccw(v[a].pos, v[b].pos, v[c].pos, a, b, c));
        tb.appendTriangles(&ccw(v[b].pos, v[d].pos, v[c].pos, b, d, c));
    };
    dvui.renderTriangles(tb.build_unowned(), null) catch {};
}

// Construction lines ------------------------------------------------------
//
// Infinite guide lines in a space (decided 2026-11-21): made with the
// Construction line tool, from two points (a drag, or a click, release and
// a click), Shift turning by 15° steps. On a canvas a line runs on without
// end: it is drawn where it crosses the view. In a frame it ends at the
// frame's boundary. Never output; a guide for alignment and attachment.

/// The first point of a line being made, and where it was pressed.
var guide_start: ?geom.Point = null;
var guide_press_px: dvui.Point.Physical = .{};
/// The first point was a click: the next click is the second.
var guide_pending = false;

/// What a space's lines are drawn within: a frame's boundary, or (the
/// canvas) the view as it is now.
fn guideClipBox(area: dvui.Rect.Physical, space: usize) geom.Box {
    if (space < state.model.spaces.items.len) if (state.model.spaces.items[space].bound) |b| return b;
    const a = state.view.toMm(area, .{ .x = area.x, .y = area.y });
    const b = state.view.toMm(area, .{ .x = area.x + area.w, .y = area.y + area.h });
    return .{ .x0 = @min(a.x, b.x), .y0 = @min(a.y, b.y), .x1 = @max(a.x, b.x), .y1 = @max(a.y, b.y) };
}

/// A line through `p0` and `p1` added to the shown space (`steps`: its
/// angle to the nearest 15°), and made the context.
fn addGuideThrough(p0: geom.Point, p1: geom.Point, steps: bool) void {
    if (p0.x == p1.x and p0.y == p1.y) return;
    var angle = layout.model.lineAngle(p0, p1);
    angle = if (steps) @round(angle / 15) * 15 else @round(angle * 1000) / 1000;
    const i = act(.addGuide, .{ shown_space, p0, angle }) catch return;
    state.context = .{ .guide = .{ .space = shown_space, .index = i } };
    selection.clearRetainingCapacity();
    state.status = "Construction line added. ";
}

/// The shown space's construction lines, where they cross what is drawn.
fn drawGuides(area: dvui.Rect.Physical) void {
    if (shown_space >= state.model.spaces.items.len) return;
    const ns = dvui.windowNaturalScale();
    const clip = guideClipBox(area, shown_space);
    for (state.model.spaces.items[shown_space].guides.items, 0..) |g, gi| {
        const seg = g.clip(clip) orelse continue;
        const chosen = switch (state.context) {
            .guide => |c| c.space == shown_space and c.index == gi,
            else => false,
        };
        dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, seg[0]), state.view.toPx(area, seg[1]) } }, .{ .thickness = (if (chosen) @as(f32, 1.6) else 1) * ns, .color = .{ .color = colors.construction.opacity(if (chosen) 1 else 0.7) } });
    }
}

/// The line being made: through its first point and the pointer.
fn drawConstructionPreview(area: dvui.Rect.Physical) void {
    if (state.tool != .construction) return;
    const p0 = guide_start orelse return;
    const m = state.mouse orelse return;
    if (p0.x == m.x and p0.y == m.y) return;
    const ns = dvui.windowNaturalScale();
    var angle = layout.model.lineAngle(p0, m);
    if (shiftHeld()) angle = @round(angle / 15) * 15;
    const g: layout.model.Guide = .{ .at = p0, .angle = angle };
    const seg = g.clip(guideClipBox(area, shown_space)) orelse return;
    dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, seg[0]), state.view.toPx(area, seg[1]) } }, .{ .thickness = ns, .color = .{ .color = colors.construction.opacity(0.45) } });
    skRing(state.view.toPx(area, p0), 4 * ns, colors.construction, 1.5 * ns);
}

/// Whether Shift is held now.
fn shiftHeld() bool {
    return dvui.currentWindow().modifiers.shift();
}

/// The construction line nearest worksheet point `p` in the shown space,
/// within the edge tolerance.
const GuideHit = struct { index: usize, seg: [2]geom.Point };

fn guideNear(area: dvui.Rect.Physical, p: geom.Point) ?GuideHit {
    if (shown_space >= state.model.spaces.items.len or !ViewLayer.guides.shown()) return null;
    const clip = guideClipBox(area, shown_space);
    var best: ?GuideHit = null;
    var best_d = edgeMm();
    for (state.model.spaces.items[shown_space].guides.items, 0..) |g, gi| {
        const seg = g.clip(clip) orelse continue;
        const d = g.distance(p);
        if (d <= best_d) {
            best_d = d;
            best = .{ .index = gi, .seg = seg };
        }
    }
    return best;
}

/// A construction line's properties: name, a point it passes through,
/// its angle and what holds it; Remove.
fn guideProperties(space: usize, index: usize) void {
    const saved_group = pushGroup("guide");
    defer popGroup(saved_group);
    if (space >= state.model.spaces.items.len or index >= state.model.spaces.items[space].guides.items.len) return;
    const g = state.model.spaces.items[space].guides.items[index];
    propText("Name", "{s}", .{g.name}, 1);
    if (numberProp("Through across, mm", g.at.x, -1e6, 1e6, 2)) |v| actM(mergeKey(.{ "guide", g.id }), .setGuide, .{ space, index, geom.Point{ .x = v, .y = g.at.y }, g.angle, g.lock }) catch {};
    if (numberProp("Through up, mm", g.at.y, -1e6, 1e6, 3)) |v| actM(mergeKey(.{ "guide", g.id }), .setGuide, .{ space, index, geom.Point{ .x = g.at.x, .y = v }, g.angle, g.lock }) catch {};
    if (g.lock == .free) {
        if (numberProp("Angle, °", g.angle, -360, 360, 4)) |v| actM(mergeKey(.{ "guide", g.id }), .setGuide, .{ space, index, g.at, v, g.lock }) catch {};
    } else propText("Angle, °", "{d:.2}", .{g.angle}, 4);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 5 });
        defer row.deinit();
        propName("Held");
        const names = [_][]const u8{ "free", "its angle", "horizontal", "vertical" };
        var c: usize = @intFromEnum(g.lock);
        if (tdropdown(@src(), &names, .{ .choice = &c }, .{}, .{ .expand = .horizontal }) and c != @intFromEnum(g.lock)) {
            actM(mergeKey(.{ "guide lock", g.id }), .setGuide, .{ space, index, g.at, g.angle, @as(layout.model.GuideLock, @enumFromInt(c)) }) catch {};
        }
    }
    keyButton(@src(), "Remove", 0, .{ .expand = .horizontal, .id_extra = 6, .margin = .{ .y = 6 }, .tag = "guide.remove" });
}

/// Select boundaries: what the pointer would pick, its whole boundary (an
/// object's path, `geom.path`), and the nearest point on it.
const BoundaryHit = struct {
    target: HoverTarget,
    boundary: Boundary,
    at: geom.Point,
};

/// Select boundaries: the object whose boundary path is nearest worksheet
/// point `p` (tiles, tracks with all their rows, line art, panels by their
/// edge, construction lines), within reach of it (the pointer inside, or
/// near: 40 px); the smaller of two as near. Each object gives its whole
/// boundary (`objectBoundary`), so any part of it picks the object.
fn nearestBoundary(p: geom.Point) ?BoundaryHit {
    const reach = 40 * edgeMm() / edge_px;
    const a = dvui.currentWindow().arena();
    var best: ?BoundaryHit = null;
    var best_d: f64 = std.math.inf(f64);
    var best_area: f64 = std.math.inf(f64);
    var best_inside = false;
    const Pick = struct {
        p: geom.Point,
        reach: f64,
        best: *?BoundaryHit,
        best_d: *f64,
        best_area: *f64,
        best_inside: *bool,
        /// Nearest wins. Where boundaries coincide (a track and its first
        /// row share a top edge; a panel and a tile may touch), nesting
        /// decides: a line first (it has no inside), then the one the
        /// pointer is inside, the smallest of those (from inside a track,
        /// its row); from outside them all, the largest (the container).
        fn consider(k: @This(), t: HoverTarget, bd: Boundary) void {
            const n = bd.nearest(k.p) orelse return;
            const inside = bd.contains(k.p);
            if (n.d > k.reach and !inside) return;
            const ar = bd.area();
            const tie = @abs(n.d - k.best_d.*) <= 1e-6;
            const better = if (!tie) n.d < k.best_d.* else if (ar == 0 or k.best_area.* == 0)
                ar == 0 and k.best_area.* != 0
            else if (inside != k.best_inside.*)
                inside
            else if (inside)
                ar < k.best_area.*
            else
                ar > k.best_area.*;
            if (better) {
                k.best.* = .{ .target = t, .boundary = bd, .at = n.at };
                k.best_d.* = n.d;
                k.best_area.* = ar;
                k.best_inside.* = inside;
            }
        }
    };
    const cand: Pick = .{ .p = p, .reach = reach, .best = &best, .best_d = &best_d, .best_area = &best_area, .best_inside = &best_inside };
    // Curves flattened to a tenth of a pixel.
    const tol = 0.1 * edgeMm() / edge_px;
    for (state.solved.items, 0..) |placed, pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi)) continue;
        const o = parentOrigin(pi);
        for (placed.tiles) |t| {
            if (t.spacer) continue;
            const b = onSheet(pi, t.body);
            // Its body: the back layer of its art (a key cap's outline),
            // else its body box.
            const bd = (if (t.shapes.len > 0 and t.shapes[0].outline.contours.len > 0)
                Boundary.outline(a, t.shapes[0].outline, tol, o)
            else
                Boundary.box(a, b)) catch continue;
            cand.consider(.{ .tile = .{ .id = t.id, .box = b } }, bd);
        }
        // Each track once, whole: every row (or column) it has, filled or
        // not, inside one outline.
        for (0..state.model.regionsIn(pi).len) |ri| {
            const pts = trackOutline(pi, ri);
            if (pts.len < 3) continue;
            var b = geom.Box.empty;
            for (pts) |q| b = b.join(.{ .x0 = q.x, .y0 = q.y, .x1 = q.x, .y1 = q.y });
            const bd = Boundary.polygon(a, pts) catch continue;
            cand.consider(.{ .track = .{ .parent = pi, .region = ri, .box = b } }, bd);
        }
        // Grids: the outline round all their cells (half a cell beyond
        // the outer rows and columns, as they are drawn).
        for (0..state.model.gridsIn(pi).len) |gi| {
            const sh = state.model.gridShape(pi, gi);
            if (sh.cols == 0 or sh.rows == 0) continue;
            const cols: f64 = @floatFromInt(sh.cols);
            const rows: f64 = @floatFromInt(sh.rows);
            const corners = [4][2]f64{ .{ -0.5, -0.5 }, .{ cols - 0.5, -0.5 }, .{ cols - 0.5, rows - 0.5 }, .{ -0.5, rows - 0.5 } };
            const pts = a.alloc(geom.Point, 4) catch continue;
            for (corners, pts) |c, *q| {
                const g = state.model.gridPoint(pi, gi, c[0], c[1]);
                q.* = .{ .x = g.x + o.x, .y = g.y + o.y };
            }
            const bd = Boundary.polygon(a, pts) catch continue;
            cand.consider(.{ .grid = .{ .parent = pi, .index = gi } }, bd);
        }
        // Its segments that hold content, each a boundary within it.
        for (placed.tracks) |t| {
            const b = onSheet(pi, t.box);
            const bd = Boundary.box(a, b) catch continue;
            cand.consider(.{ .row = .{ .parent = t.flow_parent, .region = t.region, .row = t.track, .box = b } }, bd);
        }
        if (pi.panelIndex()) |ai| for (placed.art) |pa| {
            const b = onSheet(pi, pa.box);
            var rings: std.ArrayList(geom.path.Ring) = .empty;
            for (pa.shapes) |sh| {
                const one = Boundary.outline(a, sh.outline, tol, o) catch continue;
                rings.appendSlice(a, one.rings) catch {};
            }
            var bd: Boundary = if (rings.items.len > 0) .{ .rings = rings.items } else Boundary.box(a, b) catch continue;
            // A figure's with a wrap: its border.
            if (pa.index < state.model.panels.items[ai].art.items.len) {
                const ma = state.model.panels.items[ai].art.items[pa.index];
                if (ma.figure != .none and ma.border.fractions() != null) {
                    if (ma.border.outline(a, ma.box(), ma.clearance)) |ol| {
                        bd = Boundary.outline(a, ol, tol, o) catch bd;
                    } else |_| {}
                }
            }
            cand.consider(.{ .art = .{ .panel = ai, .index = pa.index, .box = b } }, bd);
        };
    }
    for (0..state.model.panels.items.len) |pi| {
        if (!shownPanel(pi)) continue;
        const b = panelBox(pi);
        // Its edge path when it has one (a sketch made a panel), else its
        // rectangle.
        const edge: ?geom.Outline = if (placedOf(.{ .panel = pi })) |pl| pl.edge else null;
        const bd = (if (edge) |e| Boundary.outline(a, e, tol, panelOrigin(pi)) else Boundary.box(a, b)) catch continue;
        cand.consider(.{ .panel = .{ .panel = pi, .box = b } }, bd);
    }
    // Placed figures: their boundaries.
    if (shown_space < state.model.spaces.items.len) for (state.model.spaces.items[shown_space].figure_places.items, 0..) |fp, k| {
        if (!layerOpen(shown_space, fp.layer)) continue;
        const b = fp.box();
        const bd = (if (fp.border.fractions() != null)
            Boundary.outline(a, fp.border.outline(a, fp.inkBox(), fp.margin) catch continue, tol, .{ .x = 0, .y = 0 })
        else
            Boundary.box(a, b)) catch continue;
        cand.consider(.{ .figure_place = .{ .space = shown_space, .index = k, .box = b } }, bd);
    };
    // Construction lines in the shown space (while their layer shows): a
    // boundary too, by their distance from the pointer; a line has no
    // area, so it wins a tie with a box's edge it lies on.
    if (shown_space < state.model.spaces.items.len and ViewLayer.guides.shown()) {
        const far = 1e5;
        const clip: geom.Box = if (canvas_free) |cf| guideClipBox(cf.area, shown_space) else .{ .x0 = -far, .x1 = far, .y0 = -far, .y1 = far };
        for (state.model.spaces.items[shown_space].guides.items, 0..) |g, gi| {
            const seg = g.clip(clip) orelse continue;
            const bd = Boundary.segment(a, seg[0], seg[1]) catch continue;
            cand.consider(.{ .guide = .{ .space = shown_space, .index = gi, .seg = seg } }, bd);
        }
    }
    return best;
}

/// A highlighted boundary path that is not a plain rectangle: the core
/// stroke and the inverse-square glow of `haloBox`, made as strokes of the
/// path stacked from widest to narrowest, each adding the opacity that
/// brings the glow to a(t) at its edge (so they compose to the falloff in
/// steps), and the inward glow kept (a stroke is centred on the path).
fn haloPath(area: dvui.Rect.Physical, bd: Boundary, colour: dvui.Color) void {
    const ns: f64 = dvui.windowNaturalScale();
    const hw = halo_core_half * ns;
    const r0 = halo_r0 * ns;
    const t_max = r0 * @sqrt(halo_a0 / halo_cut - 1);
    const lifo = dvui.currentWindow().lifo();
    // Ring radii (from the core's edge) and the glow there, widest first.
    var ts: [16]f64 = undefined;
    var n: usize = 0;
    ts[n] = t_max;
    n += 1;
    {
        var k: f64 = 8;
        while (k >= 1 and n < ts.len) : (k -= 1) {
            const t = r0 * (std.math.pow(f64, 2, k * 0.5) - 1);
            if (t < t_max) {
                ts[n] = t;
                n += 1;
            }
        }
    }
    const glow = struct {
        fn f(t: f64, a0: f64, r: f64, tm: f64) f64 {
            return if (t >= tm) 0 else a0 / (1 + (t / r) * (t / r));
        }
    }.f;
    for (bd.rings) |r| {
        if (r.pts.len < 2) continue;
        if (!r.closed and r.pts.len == 2) {
            haloSegment(state.view.toPx(area, r.pts[0]), state.view.toPx(area, r.pts[1]), colour);
            continue;
        }
        const q = lifo.alloc(dvui.Point.Physical, r.pts.len) catch continue;
        defer lifo.free(q);
        for (r.pts, q) |p, *o| o.* = state.view.toPx(area, p);
        // Opacity so far beneath (composited from the outside in).
        var below: f64 = 0;
        for (0..n) |i| {
            const inner = if (i + 1 < n) ts[i + 1] else 0;
            const want = glow(inner, halo_a0, r0, t_max);
            if (want <= below) continue;
            const step = (want - below) / (1 - below);
            below = want;
            const w = 2 * (hw + 0.8 * ns + ts[i]);
            dvui.Path.stroke(.{ .points = q }, .{ .thickness = @floatCast(w), .color = .{ .color = colour.opacity(@floatCast(step)) }, .closed = r.closed });
        }
        dvui.Path.stroke(.{ .points = q }, .{ .thickness = @floatCast(2 * hw), .color = .{ .color = colour.opacity(0.95) }, .closed = r.closed });
    }
}

/// A boundary's halo: the box halo for a plain rectangle, else the path's.
fn haloBoundary(area: dvui.Rect.Physical, bd: Boundary, colour: dvui.Color) void {
    if (bd.asBox()) |b| haloBox(area, b, colour) else haloPath(area, bd, colour);
}

/// A highlighted boundary: a medium stroke along box `b` (worksheet mm)
/// with a translucent halo either side whose opacity falls off as the
/// inverse square of the distance from the stroke's edge,
/// a(t) = a0 / (1 + (t / r0)²). DVUI has no shaders to blur or shade a
/// distance field, so the halo is geometry: rings of the outline offset
/// outward (rounded, as an offset rectangle is) and inward, each vertex
/// coloured with the falloff's opacity at its distance, the opacity
/// interpolated between rings, blended over what is beneath (premultiplied).
/// Rings are closer where the falloff is steep.
fn haloBox(area: dvui.Rect.Physical, b: geom.Box, colour: dvui.Color) void {
    const Index = dvui.Vertex.Index;
    const ns: f64 = dvui.windowNaturalScale();
    const p0 = state.view.toPx(area, .{ .x = b.x0, .y = b.y0 });
    const p1 = state.view.toPx(area, .{ .x = b.x1, .y = b.y1 });
    const x0: f64 = @min(p0.x, p1.x);
    const x1: f64 = @max(p0.x, p1.x);
    const y0: f64 = @min(p0.y, p1.y);
    const y1: f64 = @max(p0.y, p1.y);
    const hw = halo_core_half * ns; // half the core stroke
    const aa = 0.8 * ns; // the core's anti-aliased edge
    const core: f64 = 0.95;
    const a0: f64 = halo_a0;
    const r0 = halo_r0 * ns;
    const t_max = r0 * @sqrt(a0 / halo_cut - 1);
    const inner_room = @min(x1 - x0, y1 - y0) / 2;
    // The rings: signed distance from the outline, and opacity there.
    var rings: [48]struct { d: f64, a: f64 } = undefined;
    var n: usize = 0;
    const falloff = struct {
        fn f(t: f64, a: f64, r: f64) f64 {
            return a / (1 + (t / r) * (t / r));
        }
    }.f;
    // Inward, from the halo's inner end to the core.
    var steps: [20]f64 = undefined;
    var ns_steps: usize = 0;
    {
        var k: f64 = 1;
        while (ns_steps < steps.len) : (k += 1) {
            const t = r0 * (std.math.pow(f64, 2, k * 0.5) - 1);
            if (t >= t_max) break;
            steps[ns_steps] = t;
            ns_steps += 1;
        }
    }
    {
        // Inner glow, deepest first (only as far as the box has room).
        var i: usize = ns_steps + 1;
        while (i > 0) {
            i -= 1;
            const t = if (i == ns_steps) t_max else steps[i];
            const d = -(hw + aa + t);
            if (-d >= inner_room) continue;
            rings[n] = .{ .d = d, .a = if (i == ns_steps) 0 else falloff(t, a0, r0) };
            n += 1;
        }
        if (hw + aa < inner_room) {
            rings[n] = .{ .d = -(hw + aa), .a = a0 };
            n += 1;
        }
        rings[n] = .{ .d = -@min(hw, inner_room), .a = core };
        n += 1;
        rings[n] = .{ .d = hw, .a = core };
        n += 1;
        rings[n] = .{ .d = hw + aa, .a = a0 };
        n += 1;
        for (0..ns_steps + 1) |j| {
            const t = if (j == ns_steps) t_max else steps[j];
            rings[n] = .{ .d = hw + aa + t, .a = if (j == ns_steps) 0 else falloff(t, a0, r0) };
            n += 1;
        }
    }
    // Each ring: 4 corners, K points each (an outward ring's corners are
    // arcs; an inward ring's are its corners, repeated).
    const K = 6;
    const per = 4 * K;
    const lifo = dvui.currentWindow().lifo();
    var tb = dvui.Triangles.Builder.init(lifo, n * per, (n - 1) * per * 6) catch return;
    defer tb.deinit(lifo);
    const corner = [4][2]f64{ .{ x0, y0 }, .{ x1, y0 }, .{ x1, y1 }, .{ x0, y1 } };
    const arc_from = [4]f64{ std.math.pi, 1.5 * std.math.pi, 0, 0.5 * std.math.pi };
    const inward = [4][2]f64{ .{ 1, 1 }, .{ -1, 1 }, .{ -1, -1 }, .{ 1, -1 } };
    for (rings[0..n]) |r| {
        const col: dvui.Color.PMA = .fromColor(colour.opacity(@floatCast(r.a)));
        for (0..4) |c| for (0..K) |k| {
            var x = corner[c][0];
            var y = corner[c][1];
            if (r.d >= 0) {
                const th = arc_from[c] + 0.5 * std.math.pi * @as(f64, @floatFromInt(k)) / (K - 1);
                x += r.d * @cos(th);
                y += r.d * @sin(th);
            } else {
                x += -r.d * inward[c][0];
                y += -r.d * inward[c][1];
            }
            tb.appendVertex(.{ .pos = .{ .x = @floatCast(x), .y = @floatCast(y) }, .col = col });
        };
    }
    for (0..n - 1) |j| for (0..per) |i| {
        const a: Index = @intCast(j * per + i);
        const bb: Index = @intCast(j * per + (i + 1) % per);
        const c: Index = @intCast((j + 1) * per + i);
        const d: Index = @intCast((j + 1) * per + (i + 1) % per);
        const va = tb.vertexes.items[a].pos;
        const vb = tb.vertexes.items[bb].pos;
        const vc = tb.vertexes.items[c].pos;
        const vd = tb.vertexes.items[d].pos;
        tb.appendTriangles(&ccw(va, vb, vc, a, bb, c));
        tb.appendTriangles(&ccw(vb, vd, vc, bb, d, c));
    };
    dvui.renderTriangles(tb.build_unowned(), null) catch {};
}

/// The hover target as last found (for drawing), and what was found for.
var hover_target: ?HoverTarget = null;

/// Draws what the pointer is over: a container's outline, a slot's text,
/// an object's box; and sets the pointer's shape.
fn drawHover(area: dvui.Rect.Physical) void {
    hover_target = null;
    if (state.tool != .select) return;
    if (state.drag != null or panel_edit != null or sketch_edit != null or canvas_prompt or engagingPoint()) return;
    const m = state.mouse orelse return;
    const hit: ?BoundaryHit = if (boundary_mode) nearestBoundary(m) else null;
    const over_text: ?HoverTarget = if (boundary_mode and canvas_eq == null) (if (slotTextAt(m)) |x| HoverTarget{ .slot = x } else null) else null;
    const t = over_text orelse (if (boundary_mode) (if (hit) |h| h.target else null) else hoverTargetAt(m)) orelse return;
    hover_target = t;
    const px = dvui.windowNaturalScale();
    const hover = colors.select.opacity(0.75);
    // Halos mark what can be selected only while Select boundaries is on
    // (off, hovering shows only a slot's text; the owner, 2026-11-22), and
    // only while nothing is selected: with a selection its drag points
    // glow (drawSelection); while content is edited, nothing does (the
    // caret is the speckle).
    const halo_ok = boundary_mode and selection.items.len == 0 and canvas_eq == null and track_cursor == null;
    // Select boundaries: the picked object's whole boundary haloed, and
    // the point on it nearest the pointer marked.
    if (over_text == null) if (hit) |h| if (halo_ok) {
        haloBoundary(area, h.boundary, colors.select);
        const c = state.view.toPx(area, h.at);
        skRing(c, 3 * px, colors.select, 1.5 * px);
    };
    switch (t) {
        .tile, .track, .row, .panel, .grid, .art, .guide, .figure_place => {},
        .slot => |x| {
            state.view.rect(area, x.box).fill(.square, .{ .color = .{ .color = colors.select.opacity(0.08) } });
            state.view.rect(area, x.box).stroke(.square, .{ .thickness = px, .color = .{ .color = hover } });
            dvui.cursorSet(.ibeam);
        },
        .eq_object => |x| strokeQuad(area, x.corners, x.at, hover, 2.5 * px),
        .eq_caret => dvui.cursorSet(.ibeam),
    }
}

/// A plain press at worksheet point `p`: what the pointer is over, taken
/// (a container selected, a slot's text edited there, an object chosen,
/// the caret put). Whether it took the press.
fn hoverPress(p: geom.Point) bool {
    const t = (if (boundary_mode) (if (nearestBoundary(p)) |h| h.target else null) else hoverTargetAt(p)) orelse return false;
    switch (t) {
        .tile => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .tile = x.id });
        },
        .track => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .region = .{ .parent = x.parent, .region = x.region } });
            // The container is the selection: its drag points show.
            if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
        },
        .panel => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .panel = x.panel });
            // The container is the selection: its drag points show.
            if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
        },
        .grid => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .grid = .{ .parent = x.parent, .index = x.index } });
        },
        .row => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .row = .{ .parent = x.parent, .region = x.region, .row = x.row } });
        },
        .guide => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .guide = .{ .space = x.space, .index = x.index } });
        },
        .figure_place => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .figure_place = .{ .space = x.space, .index = x.index } });
            // The container is the selection: its drag points show.
            if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
        },
        .art => |x| {
            if (canvas_eq != null) leaveCanvasEquation();
            track_cursor = null;
            levelSet(.{ .art = .{ .panel = x.panel, .index = x.index } });
            // The container is the selection: its drag points show.
            if (objectOfContext(state.context)) |id| selection.append(state.gpa, id) catch {};
        },
        .slot => |x| return slotPress(x),
        .eq_object => |x| {
            canvas_eq_seq += 1;
            eqPick(x.start, x.end);
        },
        .eq_caret => |x| {
            canvas_eq_seq += 1;
            eqMove(x.offset, null);
        },
    }
    dvui.refresh(null, @src(), null);
    return true;
}

const SlotHit = @FieldType(HoverTarget, "slot");

/// A press on a slot's text: that slot's text edited, the caret where
/// pressed. Whether it took the press.
fn slotPress(x: SlotHit) bool {
    const l = (placedOf(x.parent) orelse return false).labels[x.label];
    const k = l.slot;
    const tracks = state.model.prototypeOf(x.tile).tracks;
    if (k >= tracks.len) return false;
    if (canvas_eq != null) leaveCanvasEquation();
    track_cursor = null;
    flow_anchor = null;
    levelSet(.{ .tile = x.tile });
    expr_track = tracks[k].id;
    enterTileTrack(x.tile);
    if (canvas_eq == null) return true;
    // The caret: the press's place in this piece, past what comes before
    // the piece in the slot's text.
    const base: u32 = if (eqPiece(x.parent, l)) |pc| pc.base else 0;
    canvas_eq_seq += 1;
    eqMove(base + x.offset, null);
    dvui.refresh(null, @src(), null);
    return true;
}

/// The slot text clearly under worksheet point `p`: inside a tile, away
/// from its outline (that is the tile's), within the box of one of its
/// slots' text (the smallest, where they overlap). Text is text wherever
/// it sits: a press on it edits it, in Select boundaries too.
fn slotTextAt(p: geom.Point) ?SlotHit {
    const tol = edgeMm();
    var best: ?SlotHit = null;
    var best_area: f64 = std.math.inf(f64);
    for (state.solved.items, 0..) |placed, pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi) or !parentLayerOpen(pi)) continue;
        for (placed.tiles) |t| {
            if (t.spacer) continue;
            const body = onSheet(pi, t.body);
            if (!contains(body, p) or outlineDistance(body, p) <= tol) continue;
            for (placed.labels, 0..) |l, k| {
                if (l.tile == null or l.tile.? != t.id) continue;
                const lb = labelBox(pi, l);
                if (!contains(lb, p)) continue;
                const ar = lb.width() * lb.height();
                if (ar >= best_area) continue;
                best_area = ar;
                best = .{ .tile = t.id, .parent = pi, .label = k, .box = lb, .offset = nearestCaret(pi, l, p, renderEnd(l)) };
            }
        }
    }
    return best;
}

/// Whether worksheet point `p` is on a tile's body (a sort in a flow is
/// the tile's to take, not the flow's text).
fn tileBodyAt(p: geom.Point) bool {
    for (state.solved.items, 0..) |placed, pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi) or !parentLayerOpen(pi)) continue;
        for (placed.tiles) |t| {
            if (!t.spacer and contains(onSheet(pi, t.body), p)) return true;
        }
    }
    return false;
}

/// A press at worksheet point `p` while an expression is edited on the
/// canvas: the innermost object box there (not a field's) chosen, a
/// structure with a head by its head, anything else with the caret at its
/// start. Whether one was there.
fn eqBoxPress(p: geom.Point) bool {
    if (canvas_eq == null) return false;
    var best: ?struct { b: layout.render.ObjectBox, base: u32 } = null;
    for (state.solved.items, 0..) |placed, k| {
        const pi = state.model.parentAt(k);
        const o = parentOrigin(pi);
        for (placed.labels) |l| {
            const piece = eqPiece(pi, l) orelse continue;
            const local: geom.Point = .{ .x = p.x - l.origin.x - o.x, .y = p.y - l.origin.y - o.y };
            for (l.render.boxes) |b| {
                if (b.kind == .field or !insideQuad(b.corners, local)) continue;
                if (best == null or b.nest > best.?.b.nest) best = .{ .b = b, .base = piece.base };
            }
        }
    }
    const hit = best orelse return false;
    canvas_eq_seq += 1;
    eqPick(hit.b.start + hit.base, hit.b.end + hit.base);
    return true;
}

/// Whether `p` is inside the quadrilateral `c` (convex, either winding).
fn insideQuad(c: [4]geom.Point, p: geom.Point) bool {
    var sign: f64 = 0;
    for (0..4) |i| {
        const a = c[i];
        const b = c[(i + 1) % 4];
        const cross = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
        if (cross == 0) continue;
        if (sign == 0) sign = cross else if ((cross > 0) != (sign > 0)) return false;
    }
    return true;
}

/// The cursor: a bar across its row or column between items.
fn drawCursor(area: dvui.Rect.Physical, pi: Parent, placed: *const layout.place.Placed, c: TrackCursor) void {
    drawFlowSelection(area, pi, placed, c);
    const stops = flowStops(c.parent, c.region);
    const at: struct { segment: usize, along: f64 } = if (stopAt(stops, c.index, c.offset)) |k| blk: {
        if (!stops[k].parent.eql(pi)) return;
        break :blk .{ .segment = stops[k].segment, .along = stops[k].along };
    } else blk: {
        const p = cursorPlace(c) orelse return;
        break :blk .{ .segment = p.segment, .along = p.along };
    };
    for (placed.tracks) |t| {
        if (!t.flow_parent.eql(c.parent) or t.region != c.region or t.track != at.segment) continue;
        const pos = at.along;
        const b = onSheet(pi, t.box);
        // The cursor pulses: it is where typing goes.
        const focus = colors.select.opacity(pulse());
        // The segment, faintly, then the bar a little past its edges.
        state.view.rect(area, b).fill(.square, .{ .color = .{ .color = focus.opacity(0.06) } });
        const over = 1.0;
        const p0: geom.Point = if (t.major == .row) .{ .x = b.x0 + pos, .y = b.y0 - over } else .{ .x = b.x0 - over, .y = b.y1 - pos };
        const p1: geom.Point = if (t.major == .row) .{ .x = b.x0 + pos, .y = b.y1 + over } else .{ .x = b.x1 + over, .y = b.y1 - pos };
        speckleCaret(state.view.toPx(area, p0), state.view.toPx(area, p1));
        markCaret(state.view.toPx(area, p0), state.view.toPx(area, p1));
        return;
    }
}

/// A box outlined in dashes, about 2 mm long, on the worksheet.
/// The active selection's outline: dashes that march round box `b`,
/// fixed in screen size whatever the zoom. Keeps the canvas redrawing
/// while it shows.
fn marchingBox(area: dvui.Rect.Physical, b: geom.Box, colour: dvui.Color, width: f32) void {
    const ns = dvui.windowNaturalScale();
    const r = state.view.rect(area, b);
    const pts = [_]dvui.Point.Physical{ .{ .x = r.x, .y = r.y }, .{ .x = r.x + r.w, .y = r.y }, .{ .x = r.x + r.w, .y = r.y + r.h }, .{ .x = r.x, .y = r.y + r.h } };
    const dash: f32 = 6 * ns;
    const phase: f32 = @floatCast(@mod(@as(f64, @floatFromInt(@divTrunc(dvui.frameTimeNS(), std.time.ns_per_ms))) * 0.03 * ns, 2 * dash));
    glowUnder(&pts, true, width, colour);
    // Under the dashes, a faint solid line, so the box reads between them.
    r.stroke(.square, .{ .thickness = width, .color = .{ .color = colour.opacity(0.25) } });
    var walked: f32 = -phase;
    for (0..4) |i| {
        const a = pts[i];
        const z = pts[(i + 1) % 4];
        const len = @sqrt((z.x - a.x) * (z.x - a.x) + (z.y - a.y) * (z.y - a.y));
        if (len <= 0) continue;
        // Dashes start every 2·dash along the whole perimeter.
        var d: f32 = @mod(-walked, 2 * dash);
        if (d > dash) d -= 2 * dash;
        while (d < len) : (d += 2 * dash) {
            const s0 = @max(0, d);
            const s1 = @min(len, d + dash);
            if (s1 <= s0) continue;
            const p0: dvui.Point.Physical = .{ .x = a.x + (z.x - a.x) * s0 / len, .y = a.y + (z.y - a.y) * s0 / len };
            const p1: dvui.Point.Physical = .{ .x = a.x + (z.x - a.x) * s1 / len, .y = a.y + (z.y - a.y) * s1 / len };
            dvui.Path.stroke(.{ .points = &.{ p0, p1 } }, .{ .thickness = width, .color = .{ .color = colour } });
        }
        walked += len;
    }
    animate();
}

/// How strongly the flow cursor shows now, 0.55 to 1: a slow pulse.
/// The caret's colour: a laser's red, unlike anything else drawn.
const laser: dvui.Color = .{ .r = 0xff, .g = 0x1f, .b = 0x2d };

/// The caret drawn as laser speckle (decided 2026-11-21: in content
/// editing the caret attracts the eye, and nothing is haloed): from `p0` to
/// `p1` (device pixels), a faint core line under grains whose brightness
/// follows laser speckle's statistics, negative exponential (most grains
/// dim, a few blazing: I = −ln U), peaked across the bar, the pattern
/// re-drawn 25 times a second so it boils as a laser spot does.
fn speckleCaret(p0: dvui.Point.Physical, p1: dvui.Point.Physical) void {
    const Index = dvui.Vertex.Index;
    animate();
    const ns: f32 = dvui.windowNaturalScale();
    const dx = p1.x - p0.x;
    const dy = p1.y - p0.y;
    const len = @sqrt(dx * dx + dy * dy);
    if (!(len > 0)) return;
    const u: [2]f32 = .{ dx / len, dy / len };
    const nrm: [2]f32 = .{ -u[1], u[0] };
    // The core: where the caret is, always legible.
    dvui.Path.stroke(.{ .points = &.{ p0, p1 } }, .{ .thickness = 1.2 * ns, .color = .{ .color = laser.opacity(0.55) } });
    const cell: f32 = 1.3 * ns;
    const along: usize = @intFromFloat(@ceil(len / cell));
    const across = 5;
    const sigma: f32 = 1.4 * ns;
    // The pattern: one per 40 ms, the same within a frame.
    const tick: u64 = @intCast(@divTrunc(@max(0, platform.monotonicNs()), 40 * std.time.ns_per_ms));
    var prng = std.Random.DefaultPrng.init(tick *% 0x9E3779B97F4A7C15 +% @as(u64, @intFromFloat(@abs(p0.x) * 7 + @abs(p0.y))));
    const rnd = prng.random();
    const n = along * across;
    const lifo = dvui.currentWindow().lifo();
    var tb = dvui.Triangles.Builder.init(lifo, 4 * n, 6 * n) catch return;
    defer tb.deinit(lifo);
    var k: usize = 0;
    for (0..along) |i| for (0..across) |jj| {
        const j: f32 = @as(f32, @floatFromInt(jj)) - (across - 1) / 2.0;
        const off = j * cell * 0.8;
        const env = @exp(-(off * off) / (2 * sigma * sigma));
        const intensity: f32 = -@log(1 - rnd.float(f32) * 0.999);
        const a = std.math.clamp(0.75 * intensity * env, 0, 1);
        if (a < 0.04) continue;
        const t = (@as(f32, @floatFromInt(i)) + 0.5 + (rnd.float(f32) - 0.5) * 0.6) * cell;
        if (t > len) continue;
        const cx = p0.x + u[0] * t + nrm[0] * (off + (rnd.float(f32) - 0.5) * 0.5 * cell);
        const cy = p0.y + u[1] * t + nrm[1] * (off + (rnd.float(f32) - 0.5) * 0.5 * cell);
        const h = 0.5 * cell * (0.6 + 0.4 * @min(1, intensity / 2));
        const col: dvui.Color.PMA = .fromColor(laser.opacity(a));
        const base: Index = @intCast(4 * k);
        tb.appendVertex(.{ .pos = .{ .x = cx - h, .y = cy - h }, .col = col });
        tb.appendVertex(.{ .pos = .{ .x = cx + h, .y = cy - h }, .col = col });
        tb.appendVertex(.{ .pos = .{ .x = cx + h, .y = cy + h }, .col = col });
        tb.appendVertex(.{ .pos = .{ .x = cx - h, .y = cy + h }, .col = col });
        const v = tb.vertexes.items;
        tb.appendTriangles(&ccw(v[base].pos, v[base + 1].pos, v[base + 2].pos, base, base + 1, base + 2));
        tb.appendTriangles(&ccw(v[base].pos, v[base + 2].pos, v[base + 3].pos, base, base + 2, base + 3));
        k += 1;
    };
    if (k > 0) dvui.renderTriangles(tb.build_unowned(), null) catch {};
}

fn pulse() f32 {
    animate();
    const t: f64 = @as(f64, @floatFromInt(@divTrunc(dvui.frameTimeNS(), std.time.ns_per_ms))) / 1000;
    return @floatCast(0.775 + 0.225 * @sin(t * 2 * std.math.pi / 1.4));
}

/// Keeps the canvas redrawing about 25 times a second while something on
/// it moves.
fn animate() void {
    const id = canvas_id orelse return;
    if (dvui.timerDoneOrNone(id)) dvui.timer(id, 40_000);
}

fn guideBox(area: dvui.Rect.Physical, b: geom.Box, colour: dvui.Color, px: f32) void {
    const corners = [_]geom.Point{ .{ .x = b.x0, .y = b.y1 }, .{ .x = b.x1, .y = b.y1 }, .{ .x = b.x1, .y = b.y0 }, .{ .x = b.x0, .y = b.y0 } };
    guideOutline(area, &corners, colour, px);
}

/// Track `ri`'s boundary in panel `pi`, sheet mm: down one edge and back up
/// the other, each a segment's half length from the path.
fn trackOutline(pi: Parent, ri: usize) []const geom.Point {
    const r = state.model.regionsIn(pi)[ri];
    const a = dvui.currentWindow().arena();
    const reach = r.crossLength();
    const n: usize = @intFromFloat(@min(1000, @max(8, @ceil(reach * 8))));
    var pts: std.ArrayList(geom.Point) = .empty;
    for (0..2) |side| for (0..n + 1) |k0| {
        const k = if (side == 0) k0 else n - k0;
        const across = reach * @as(f64, @floatFromInt(k)) / @as(f64, @floatFromInt(n));
        const e = r.edgesAt(across);
        // `pathToMm` puts a place across mid-row; the edges run the whole
        // reach, from the first row's top to the last row's bottom.
        const p = pathToMm(pi, ri, e[side], across - 0.5);
        pts.append(a, p) catch return &.{};
    };
    return pts.items;
}

/// The selected tile's tracks: their boxes on its face, outlined; the one
/// the expression line edits stronger.
fn drawTileTracks(area: dvui.Rect.Physical, pi: Parent, t: layout.place.PlacedTile) void {
    const px = dvui.windowNaturalScale();
    const edited = exprTrackOf(t.id);
    for (state.model.prototypeOf(t.id).tracks) |tt| {
        const b = tt.place.inset.inset(t.face);
        if (!(b.width() > 0 and b.height() > 0)) continue;
        const strong = edited != null and edited.? == tt.id;
        guideBox(area, onSheet(pi, b), if (strong) colors.select.opacity(0.8) else colors.guide.opacity(0.6), px);
    }
}

/// A closed outline through `pts` (sheet mm): one solid line, thin
/// (decided 2026-11-21: layout regions' outlines solid, not dashed).
fn guideOutline(area: dvui.Rect.Physical, pts: []const geom.Point, colour: dvui.Color, px: f32) void {
    if (pts.len < 2) return;
    const lifo = dvui.currentWindow().lifo();
    const q = lifo.alloc(dvui.Point.Physical, pts.len) catch return;
    defer lifo.free(q);
    for (pts, q) |p, *o| o.* = state.view.toPx(area, p);
    glowUnder(q, true, px, colour);
    dvui.Path.stroke(.{ .points = q }, .{ .thickness = px, .color = .{ .color = colour }, .closed = true });
}

/// Whether text is being typed (the flow cursor is in a track, not in an
/// equation edited on the canvas) and Ctrl is not held: the canvas then
/// shows content layouts as soft bands, without outlines, centre lines
/// or origin marks.
fn quietText() bool {
    if (track_cursor == null or canvas_eq != null) return false;
    return !primaryMod(dvui.currentWindow().modifiers);
}

/// Content layout `ri` of panel `pi` while text is typed: a soft band
/// around the area its content may take (half a row wide, 1 to 4 mm),
/// the area itself left clear; a little deeper for the one typed in.
fn contentBand(area: dvui.Rect.Physical, pi: Parent, ri: usize, on: bool) void {
    const pts = trackOutline(pi, ri);
    if (pts.len < 2) return;
    var b: geom.Box = .{ .x0 = pts[0].x, .x1 = pts[0].x, .y0 = pts[0].y, .y1 = pts[0].y };
    for (pts) |q| {
        b.x0 = @min(b.x0, q.x);
        b.x1 = @max(b.x1, q.x);
        b.y0 = @min(b.y0, q.y);
        b.y1 = @max(b.y1, q.y);
    }
    const r = state.model.regionsIn(pi)[ri];
    const w = std.math.clamp(0.5 * r.pitch, 1, 4);
    const tint: dvui.Color = colors.guide.opacity(if (on) 0.16 else 0.09);
    const sides = [_]geom.Box{
        .{ .x0 = b.x0 - w, .x1 = b.x1 + w, .y0 = b.y1, .y1 = b.y1 + w },
        .{ .x0 = b.x0 - w, .x1 = b.x1 + w, .y0 = b.y0 - w, .y1 = b.y0 },
        .{ .x0 = b.x0 - w, .x1 = b.x0, .y0 = b.y0, .y1 = b.y1 },
        .{ .x0 = b.x1, .x1 = b.x1 + w, .y0 = b.y0, .y1 = b.y1 },
    };
    for (sides) |sd| state.view.rect(area, sd).fill(.square, .{ .color = .{ .color = tint } });
}

/// What the flow holds that output leaves out, drawn faintly while editing:
/// each hard break as a down-and-left arrow (a carriage return) at the end
/// of its segment's content, each paragraph separator as a pilcrow, each
/// empty run as a dashed slot, and each forced wrap (a word cut to fit its
/// line) as a hooked arrow, right then down, at the end of its line.
fn drawFlowMarks(area: dvui.Rect.Physical, pi: Parent, placed: *const layout.place.Placed) void {
    const px = dvui.windowNaturalScale();
    const ghost = colors.guide.opacity(0.55);
    for (placed.wraps) |w| {
        const r = state.model.regionsIn(w.flow_parent)[w.region];
        if (r.major() != .row) continue;
        const band = for (placed.tracks) |t| {
            if (t.region == w.region and t.flow_parent.eql(w.flow_parent) and t.track == w.segment) break onSheet(pi, t.box);
        } else continue;
        const u = r.pitch * 0.32;
        const x0 = band.x0 + w.along + u * 0.25;
        const mid = (band.y0 + band.y1) / 2 + u * 0.35;
        const right = x0 + u * 0.8;
        const low = mid - u;
        const pts = [_]geom.Point{ .{ .x = x0, .y = mid }, .{ .x = right, .y = mid }, .{ .x = right, .y = low } };
        var phys: [3]dvui.Point.Physical = undefined;
        for (pts, &phys) |q, *o| o.* = state.view.toPx(area, q);
        dvui.Path.stroke(.{ .points = &phys }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
        const h = u * 0.3;
        const head = [_]geom.Point{ .{ .x = right - h, .y = low + h }, .{ .x = right, .y = low }, .{ .x = right + h, .y = low + h } };
        var hp: [3]dvui.Point.Physical = undefined;
        for (head, &hp) |q, *o| o.* = state.view.toPx(area, q);
        dvui.Path.stroke(.{ .points = &hp }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
    }
    // Groups: a tie along the foot of the row (or the side of the column)
    // from each item to the next one it is bound to.
    for (placed.items, 0..) |it, k| {
        const item = modelItem(pi, it) orelse continue;
        if (k + 1 >= placed.items.len) break;
        const nx = placed.items[k + 1];
        if (nx.region != it.region or !nx.flow_parent.eql(it.flow_parent) or nx.segment != it.segment) continue;
        _ = modelItem(pi, nx) orelse continue;
        _ = item;
        const r = state.model.regionsIn(it.flow_parent)[it.region];
        // Bound by hand, or a letter tile to its word.
        if (nx.index != it.index + 1 or !state.model.bound(state.model.flowItems(it.flow_parent, it.region), it.index)) continue;
        const band = for (placed.tracks) |t| {
            if (t.region == it.region and t.flow_parent.eql(it.flow_parent) and t.track == it.segment) break onSheet(pi, t.box);
        } else continue;
        const a_mid = (it.span[0] + it.span[1]) / 2;
        const b_mid = (nx.span[0] + nx.span[1]) / 2;
        const inset = r.pitch * 0.08;
        const p0: geom.Point = if (r.major() == .row) .{ .x = band.x0 + a_mid, .y = band.y0 + inset } else .{ .x = band.x1 - inset, .y = band.y1 - a_mid };
        const p1: geom.Point = if (r.major() == .row) .{ .x = band.x0 + b_mid, .y = band.y0 + inset } else .{ .x = band.x1 - inset, .y = band.y1 - b_mid };
        dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, p0), state.view.toPx(area, p1) } }, .{ .thickness = 2 * px, .color = .{ .color = colors.select.opacity(0.7) } });
    }
    for (placed.items) |it| {
        const what = (modelItem(pi, it) orelse continue).what;
        const r = state.model.regionsIn(it.flow_parent)[it.region];
        if (what != .hard_break and what != .paragraph and !(what == .run and what.run.content.len == 0)) continue;
        const band = for (placed.tracks) |t| {
            if (t.region == it.region and t.flow_parent.eql(it.flow_parent) and t.track == it.segment) break onSheet(pi, t.box);
        } else continue;
        const rows = r.major() == .row;
        if (what == .run) {
            const box: geom.Box = if (rows)
                .{ .x0 = band.x0 + it.span[0], .x1 = band.x0 + it.span[1], .y0 = band.y0 + r.pitch * 0.2, .y1 = band.y1 - r.pitch * 0.2 }
            else
                .{ .x0 = band.x0 + r.pitch * 0.2, .x1 = band.x1 - r.pitch * 0.2, .y1 = band.y1 - it.span[0], .y0 = band.y1 - it.span[1] };
            state.view.rect(area, box).stroke(.square, .{ .thickness = px, .color = .{ .color = ghost } });
            continue;
        }
        const u = r.pitch * 0.32;
        if (what == .paragraph) {
            // A pilcrow just past the content: its bowl and two stems.
            const x0 = if (rows) band.x0 + it.span[0] + u * 0.4 else (band.x0 + band.x1) / 2 - u / 2;
            const top = if (rows) (band.y0 + band.y1) / 2 + u * 0.6 else band.y1 - it.span[0] - u * 0.4;
            const bottom = top - u * 1.2;
            const s1 = x0 + u * 0.55;
            const s2 = x0 + u * 0.85;
            const bowl_r = u * 0.28;
            var bowl: [10]dvui.Point.Physical = undefined;
            for (&bowl, 0..) |*o, k| {
                const t = std.math.pi * (0.5 + @as(f64, @floatFromInt(k)) / 9.0);
                o.* = state.view.toPx(area, .{ .x = s1 + bowl_r * @cos(t), .y = top - bowl_r + bowl_r * @sin(t) });
            }
            dvui.Path.stroke(.{ .points = &bowl }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            const lines = [_][2]geom.Point{
                .{ .{ .x = s1, .y = top }, .{ .x = s2, .y = top } },
                .{ .{ .x = s1, .y = top }, .{ .x = s1, .y = bottom } },
                .{ .{ .x = s2, .y = top }, .{ .x = s2, .y = bottom } },
            };
            for (lines) |ln| dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, ln[0]), state.view.toPx(area, ln[1]) } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            continue;
        }
        // The arrow, about a third of a unit, just past the content: down
        // from the top, then left, with a head.
        const x0 = if (rows) band.x0 + it.span[0] + u * 0.4 else (band.x0 + band.x1) / 2 - u / 2;
        const ytop = if (rows) (band.y0 + band.y1) / 2 + u / 2 else band.y1 - it.span[0] - u * 0.4;
        const right = x0 + u;
        const low = ytop - u;
        const pts = [_]geom.Point{ .{ .x = right, .y = ytop }, .{ .x = right, .y = low }, .{ .x = x0, .y = low } };
        var phys: [3]dvui.Point.Physical = undefined;
        for (pts, &phys) |q, *o| o.* = state.view.toPx(area, q);
        dvui.Path.stroke(.{ .points = &phys }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
        const h = u * 0.3;
        const head = [_]geom.Point{ .{ .x = x0 + h, .y = low + h }, .{ .x = x0, .y = low }, .{ .x = x0 + h, .y = low - h } };
        var hp: [3]dvui.Point.Physical = undefined;
        for (head, &hp) |q, *o| o.* = state.view.toPx(area, q);
        dvui.Path.stroke(.{ .points = &hp }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
    }
}

/// The insert palette: a row of tile buttons and a row of blank buttons,
/// each drawn to scale, with its key and its size. A click inserts at the
/// cursor, as the key does.
fn trackPalette() void {
    palette_id_count = 0;
    if (track_cursor == null) return;
    const palette = if (tileRowsShown()) paletteFor(track_cursor.?.parent, track_cursor.?.region) else null;
    if (palette) |pal| {
        const name = state.model.proto(pal.prototype).name;
        dvui.label(@src(), "Insert {s} tiles, blanks, text or equations, and breaks at the cursor · Backspace and Delete remove · arrows move · Esc ends", .{name}, .{ .font = dvui.Font.theme(.body).larger(-2), .padding = .{ .x = 6, .y = 2, .h = 2 } });
    } else dvui.labelNoFmt(@src(), "Insert text or equations, and breaks, at the cursor · Backspace and Delete remove · arrows move · Esc ends", .{}, .{ .font = dvui.Font.theme(.body).larger(-2), .padding = .{ .x = 6, .y = 2, .h = 2 } });
    if (palette) |pal| inline for (.{ .tile, .blank }) |kind| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .id_extra = @backingInt(@as(enum { tile, blank }, kind)) });
        defer row.deinit();
        const n = if (kind == .tile) pal.tile_count else pal.blanks.len;
        for (0..n) |i| {
            const size = if (kind == .tile) pal.tiles[i] else pal.blanks[i];
            _ = paletteButton(kind == .tile, size, i);
        }
    };
    // The flow's other items: a run of text or an equation, and a hard break.
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{});
    defer row.deinit();
    _ = flowButton(.run, 0);
    _ = flowButton(.join, 3);
    if (palette != null) _ = flowButton(.next_prototype, 2);
    _ = flowButton(.hard_break, 1);
    // A new paragraph anywhere: in a track of keys, a paragraph style's
    // space before is a row gap.
    _ = flowButton(.paragraph, 4);
}

/// Whether the flow cursor is in a track of text (sized to a style):
/// there Enter ends the paragraph, and Shift+Enter the line.
fn inTextTrack() bool {
    const c = track_cursor orelse return false;
    return state.model.regionsIn(c.parent)[c.region].style != null;
}

/// A palette button for an item that is not a tile: its key, a picture and
/// what it puts in.
fn flowButton(kind: enum { run, hard_break, paragraph, next_prototype, join }, i: usize) bool {
    palette_arg = 0;
    const tag: ?[]const u8 = std.fmt.allocPrint(dvui.currentWindow().arena(), "palette.{s}", .{switch (kind) {
        .run => "run",
        .hard_break => "hard-break",
        .paragraph => "paragraph",
        .next_prototype => "next-prototype",
        .join => "join",
    }}) catch null;
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{
        .tag = tag,
        .id_extra = i,
        .margin = .all(2),
        .padding = .{ .x = 8, .w = 8, .y = 3, .h = 3 },
        .corners = .all(4),
        .color_fill = .{ .color = dvui.themeGet().color(.control, .fill).opacity(palette_button_alpha) },
    });
    bw.processEvents();
    bw.drawBackground();
    // A virtual key: a press is an event for its action (run next frame).
    if (tag) |t| {
        recordDrawn(t, palette_arg);
        if (bw.clicked()) pushButtonEvent(t, palette_arg);
    }
    const clicked = false;
    if (palette_id_count < palette_ids.len) {
        palette_ids[palette_id_count] = bw.data().id;
        palette_id_count += 1;
    }
    {
        var line = dvui.box(@src(), .{ .dir = .horizontal }, .{});
        defer line.deinit();
        dvui.labelNoFmt(@src(), switch (kind) {
            // Letters type text now: these two have no key.
            .run => "",
            .hard_break => if (inTextTrack()) "⇧Enter" else "Enter",
            .paragraph => if (inTextTrack()) "Enter" else "",
            .next_prototype => "Tab",
            .join => "",
        }, .{}, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.mono).withWeight(.bold), .padding = .{ .w = 8 } });
        var pic = dvui.box(@src(), .{}, .{ .gravity_y = 0.5, .min_size_content = .{ .w = 22, .h = 18 }, .max_size_content = .{ .w = 22, .h = 18 } });
        const r = pic.data().contentRectScale().r;
        pic.deinit();
        const px = dvui.windowNaturalScale();
        const ghost = colors.edge.opacity(0.55);
        if (kind == .paragraph) {
            // A pilcrow: a bowl and two stems.
            const s1 = r.x + r.w * 0.5;
            const s2 = r.x + r.w * 0.72;
            const top = r.y + r.h * 0.1;
            const bottom = r.y + r.h * 0.9;
            const br = r.h * 0.22;
            var bowl: [10]dvui.Point.Physical = undefined;
            for (&bowl, 0..) |*o, k| {
                const t = std.math.pi * (0.5 + @as(f32, @floatFromInt(k)) / 9.0);
                o.* = .{ .x = s1 + br * @cos(t), .y = top + br - br * @sin(t) };
            }
            dvui.Path.stroke(.{ .points = &bowl }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            dvui.Path.stroke(.{ .points = &.{ .{ .x = s1, .y = top }, .{ .x = s2, .y = top } } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            dvui.Path.stroke(.{ .points = &.{ .{ .x = s1, .y = top }, .{ .x = s1, .y = bottom } } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            dvui.Path.stroke(.{ .points = &.{ .{ .x = s2, .y = top }, .{ .x = s2, .y = bottom } } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
        } else if (kind == .hard_break) {
            // Down, then left, with a head: a carriage return, ghosted as
            // it is on the canvas.
            const right = r.x + r.w * 0.8;
            const left = r.x + r.w * 0.15;
            const top = r.y + r.h * 0.1;
            const low = r.y + r.h * 0.75;
            const h = r.h * 0.25;
            dvui.Path.stroke(.{ .points = &.{ .{ .x = right, .y = top }, .{ .x = right, .y = low }, .{ .x = left, .y = low } } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
            dvui.Path.stroke(.{ .points = &.{ .{ .x = left + h, .y = low - h }, .{ .x = left, .y = low }, .{ .x = left + h, .y = low + h } } }, .{ .thickness = 1.5 * px, .color = .{ .color = ghost } });
        } else if (kind == .join) {
            // Two tiles with a tie under them: one group.
            const w = r.w * 0.38;
            const a_r: dvui.Rect.Physical = .{ .x = r.x + r.w * 0.06, .y = r.y + r.h * 0.1, .w = w, .h = r.h * 0.55 };
            const b_r: dvui.Rect.Physical = .{ .x = r.x + r.w * 0.56, .y = r.y + r.h * 0.1, .w = w, .h = r.h * 0.55 };
            a_r.stroke(.all(2 * px), .{ .thickness = px, .color = .{ .color = colors.edge } });
            b_r.stroke(.all(2 * px), .{ .thickness = px, .color = .{ .color = colors.edge } });
            const y = r.y + r.h * 0.85;
            dvui.Path.stroke(.{ .points = &.{ .{ .x = a_r.x + w / 2, .y = y }, .{ .x = b_r.x + w / 2, .y = y } } }, .{ .thickness = 2 * px, .color = .{ .color = dvui.themeGet().focus } });
        } else if (kind == .next_prototype) {
            // Two tiles side by side: another kind of tile.
            const w = r.w * 0.42;
            const a_r: dvui.Rect.Physical = .{ .x = r.x, .y = r.y + r.h * 0.2, .w = w, .h = r.h * 0.6 };
            const b_r: dvui.Rect.Physical = .{ .x = r.x + r.w - w, .y = r.y + r.h * 0.2, .w = w, .h = r.h * 0.6 };
            a_r.stroke(.all(2 * px), .{ .thickness = px, .color = .{ .color = ghost } });
            b_r.fill(.all(2 * px), .{ .color = .{ .color = colors.face } });
            b_r.stroke(.all(2 * px), .{ .thickness = px, .color = .{ .color = colors.edge } });
        } else {
            // A dashed-looking slot with a caret: text to be typed.
            r.stroke(.square, .{ .thickness = px, .color = .{ .color = ghost } });
            const x = r.x + r.w * 0.3;
            dvui.Path.stroke(.{ .points = &.{ .{ .x = x, .y = r.y + 3 * px }, .{ .x = x, .y = r.y + r.h - 3 * px } } }, .{ .thickness = 1.5 * px, .color = .{ .color = dvui.themeGet().focus } });
        }
        const next_name = blk: {
            if (kind != .next_prototype) break :blk "";
            const c = track_cursor orelse break :blk "";
            const pal = paletteFor(c.parent, c.region) orelse break :blk "";
            break :blk std.fmt.allocPrint(dvui.currentWindow().arena(), "Tiles: {s} · next kind", .{state.model.proto(pal.prototype).name}) catch "";
        };
        dvui.labelNoFmt(@src(), switch (kind) {
            .run => "Text or equation",
            .hard_break => "Line break",
            .paragraph => "New paragraph",
            .next_prototype => next_name,
            .join => "Join or part",
        }, .{}, .{ .gravity_y = 0.5, .font = dvui.Font.theme(.body).larger(-2), .padding = .{ .x = 8 } });
    }
    bw.drawFocus();
    bw.deinit();
    return clicked;
}

/// The argument of the palette or move button being drawn (which size,
/// which arrow).
var palette_arg: i32 = 0;

/// One palette button: the tile or blank drawn to scale, its key, its size.
fn paletteButton(tile: bool, size: f64, i: usize) bool {
    palette_arg = @intCast(i);
    // palette.key.1-25u: a size's place, its "." a "-".
    var size_buf: [32]u8 = undefined;
    const sz: []u8 = std.fmt.bufPrint(&size_buf, "{d}u", .{size}) catch size_buf[0..0];
    for (sz) |*c| if (c.* == '.') {
        c.* = '-';
    };
    const tag: ?[]const u8 = std.fmt.allocPrint(dvui.currentWindow().arena(), "palette.{s}.{s}", .{ if (tile) "key" else "blank", sz }) catch null;
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{
        .tag = tag,
        .id_extra = i,
        .margin = .all(2),
        .padding = .all(4),
        .min_size_content = .{ .w = 44, .h = 40 },
        .corners = .all(4),
        .color_fill = .{ .color = dvui.themeGet().color(.control, .fill).opacity(palette_button_alpha) },
    });
    bw.processEvents();
    bw.drawBackground();
    // A virtual key: a press is an event for its action (run next frame).
    if (tag) |t| {
        recordDrawn(t, palette_arg);
        if (bw.clicked()) pushButtonEvent(t, palette_arg);
    }
    const clicked = false;
    if (palette_id_count < palette_ids.len) {
        palette_ids[palette_id_count] = bw.data().id;
        palette_id_count += 1;
    }
    {
        var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .gravity_x = 0.5 });
        defer col.deinit();
        // To scale: 18 px a unit.
        const w: f32 = @floatCast(@max(4, size * 18));
        _ = dvui.box(@src(), .{}, .{
            .min_size_content = .{ .w = w, .h = 16 },
            .max_size_content = .{ .w = w, .h = 16 },
            .gravity_x = 0.5,
            .background = tile,
            .border = .all(1),
            .corners = .all(3),
            .color_fill = if (tile) .{ .color = colors.face } else null,
            .color_border = .{ .color = if (tile) colors.edge else colors.edge.opacity(0.5) },
        }).deinit();
        var sb: [16]u8 = undefined;
        dvui.labelNoFmt(@src(), std.fmt.bufPrint(&sb, "{d} u", .{size}) catch "", .{}, .{ .gravity_x = 0.5, .font = dvui.Font.theme(.body).larger(-3), .padding = .{} });
    }
    bw.drawFocus();
    bw.deinit();
    return clicked;
}

// Moving tracks ------------------------------------------------------------
//
// With a track (a row or a column) as the context, the arrow keys, or the
// move palette's inverted-T buttons, move it in its prototype's smallest
// step: along its length, or across. Its origin moves and the path bends
// through it, so rows that only continue the path follow; kept ones stay.

/// The step a region's tracks move in: the finer of its prototype's size
/// steps along and across (0.25 u for keyboard keys).
fn moveStep(panel: Parent, region: usize) f64 {
    const r = state.model.regionsIn(panel)[region];
    if (state.model.prototypes.items.len == 0) return 0.25;
    const p = state.model.proto(r.prototype orelse state.model.prototypes.items[0].id).*;
    return @min(p.step(r.major(), .along), p.step(r.major(), .across));
}

const Arrow = enum { up, left, down, right };

/// Moves the selected track one step the way an arrow points, on screen.
fn moveTrackArrow(arrow: Arrow) void {
    const t = switch (state.context) {
        .row => |r| r,
        else => return,
    };
    const major = state.model.regionsIn(t.parent)[t.region].major();
    const s = moveStep(t.parent, t.region);
    // Rows run right and stack down; columns run down and set right.
    var along: f64 = 0;
    var across: f64 = 0;
    switch (arrow) {
        .left => if (major == .row) {
            along = -s;
        } else {
            across = -s;
        },
        .right => if (major == .row) {
            along = s;
        } else {
            across = s;
        },
        .up => if (major == .row) {
            across = -s;
        } else {
            along = -s;
        },
        .down => if (major == .row) {
            across = s;
        } else {
            along = s;
        },
    }
    // Rows keep their pitch: a row moves along, bending the track's path
    // where it attaches (a control point there); the rows around it follow
    // the curve.
    if (across != 0) {
        state.status = "Rows keep an even pitch: move a row along, or set paragraph spacing. ";
        return;
    }
    const pt = placedTrack(t.parent, t.region, t.row) orelse return;
    const o = pt.origin;
    _ = actM(mergeKey(.{ "bend", pt.parent, pt.member, t.row }), .bendPath, .{ pt.parent, pt.member, o.across, o.along + along, o.across }) catch {
        state.status = "It did not move. ";
        return;
    };
    state.status = "";
}

fn moveTrackKey(code: dvui.enums.Key) bool {
    const arrow: Arrow = switch (code) {
        .up => .up,
        .left => .left,
        .down => .down,
        .right => .right,
        else => return false,
    };
    moveTrackArrow(arrow);
    return true;
}

/// The move palette: the arrow keys as an inverted T, each moving the
/// selected track one step, and where it now sits.
fn movePalette() void {
    palette_id_count = 0;
    const t = switch (state.context) {
        .row => |r| r,
        else => return,
    };
    const region = state.model.regionsIn(t.parent)[t.region];
    const s = moveStep(t.parent, t.region);
    const word = trackWord(region.major());
    var body = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .both });
    defer body.deinit();
    {
        var keys = dvui.box(@src(), .{ .dir = .vertical }, .{ .padding = .{ .x = 6, .y = 4, .w = 12 } });
        defer keys.deinit();
        {
            var top = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 0.5 });
            defer top.deinit();
            _ = arrowButton(.up, 0);
        }
        var bottom = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 0.5 });
        defer bottom.deinit();
        for ([_]Arrow{ .left, .down, .right }, 1..) |a, i| {
            _ = arrowButton(a, i);
        }
    }
    var info = dvui.box(@src(), .{ .dir = .vertical }, .{ .gravity_y = 0.5 });
    defer info.deinit();
    dvui.label(@src(), "Move {s} {d} of {s} in {d} u steps", .{ word, t.row + 1, region.name, s }, .{ .font = dvui.Font.theme(.heading) });
    dvui.label(@src(), "Arrow keys or these buttons move it, tiles and all. The path bends through it: rows that only continue the path follow; the rest stay.", .{}, .{ .font = dvui.Font.theme(.body).larger(-2) });
    var where_buf: [96]u8 = undefined;
    dvui.labelNoFmt(@src(), trackWhere(&where_buf, t.parent, t.region, t.row), .{}, .{ .font = dvui.Font.theme(.mono) });
}

/// Where a row or column sits from where a straight path would put it, in
/// plain words: "0.25 u up · 1.5 u left" (a row) or "1 u right · 0.5 u
/// down" (a column).
fn trackWhere(buf: []u8, pi: Parent, region: usize, t: usize) []const u8 {
    const pt = placedTrack(pi, region, t) orelse return "";
    const o = pt.origin;
    const member = state.model.regionsIn(pt.parent)[pt.member];
    // Straight on from its track's origin, one thickness each.
    const across = o.across - @as(f64, @floatFromInt(pt.local));
    // Along, from where an unshaped track's segment sits (its middle on
    // the track's middle).
    const along = o.along - member.middle();
    const rows = member.major() == .row;
    const across_word = if (rows) (if (across < 0) "up" else "down") else (if (across < 0) "left" else "right");
    const along_word = if (rows) (if (along < 0) "left" else "right") else (if (along < 0) "up" else "down");
    return std.fmt.bufPrint(buf, "{d} u {s} · {d} u {s}", .{ @abs(across), across_word, @abs(along), along_word }) catch "";
}

/// One arrow key of the move palette: its arrow, drawn as a keycap.
fn arrowButton(arrow: Arrow, i: usize) bool {
    palette_arg = @intFromEnum(arrow);
    const tag: ?[]const u8 = std.fmt.allocPrint(dvui.currentWindow().arena(), "move.{s}", .{@tagName(arrow)}) catch null;
    var bw: dvui.ButtonWidget = undefined;
    bw.init(@src(), .{}, .{
        .tag = tag,
        .id_extra = i,
        .margin = .all(2),
        .padding = .all(6),
        .min_size_content = .{ .w = 34, .h = 34 },
        .corners = .all(5),
        .border = .all(1),
        .color_fill = .{ .color = dvui.themeGet().color(.control, .fill).opacity(palette_button_alpha) },
    });
    bw.processEvents();
    bw.drawBackground();
    // A virtual key: a press is an event for its action (run next frame).
    if (tag) |t| {
        recordDrawn(t, palette_arg);
        if (bw.clicked()) pushButtonEvent(t, palette_arg);
    }
    const clicked = false;
    if (palette_id_count < palette_ids.len) {
        palette_ids[palette_id_count] = bw.data().id;
        palette_id_count += 1;
    }
    const icon = switch (arrow) {
        .up => dvui.entypo.arrow_bold_up,
        .left => dvui.entypo.arrow_bold_left,
        .down => dvui.entypo.arrow_bold_down,
        .right => dvui.entypo.arrow_bold_right,
    };
    dvui.icon(@src(), @tagName(arrow), icon, .{}, .{ .gravity_x = 0.5, .gravity_y = 0.5, .min_size_content = .{ .w = 20, .h = 20 } });
    bw.drawFocus();
    bw.deinit();
    if (clicked) if (canvas_id) |id| dvui.focusWidget(id, null, null);
    return clicked;
}

// Constraints -------------------------------------------------------------------
//
// The Constrain tool picks a feature (an edge, centre line or origin line)
// of an object, then a second on the same axis: of the same object, a peer
// in the same parent, or the parent itself. A prompt then asks for the
// relation and its value, offering the current measurement; applying it
// moves the first object into place. Constraints show as dimension glyphs
// in the annotation hue (flagged ones in the warning hue), and an object's
// properties list its constraints, with their values to edit, and its
// object origin to choose.

const constrain = layout.constrain;
const ConstraintEnd = layout.model.ConstraintEnd;
const Feature = layout.model.Feature;

/// A feature under the pointer: the end a constraint would take, the
/// parent it is measured in, and its line, space mm.
const FeatureHit = struct {
    end: ConstraintEnd,
    parent: constrain.Parent,
    p0: geom.Point,
    p1: geom.Point,
};

var constrain_hover: ?FeatureHit = null;
var constrain_first: ?FeatureHit = null;
var constrain_prompt: ?struct {
    a: ConstraintEnd,
    b: ConstraintEnd,
    equal: bool = false,
    /// In the document's units, never negative.
    value: f64,
    /// Which way it runs, as measured (`Constraint.side`).
    side: f64 = 1,
    new: bool = true,
    /// Made for every object of `constrain_batch` (end `a` each one's,
    /// its side as measured), not only end `a`.
    batch: bool = false,
} = null;

/// Several objects constrained at once (K on a selection): their IDs, and
/// what is made: each one's `feature` kept to a feature picked next, or
/// the gaps between neighbours, across or down.
var constrain_batch: ?struct {
    ids: [64]layout.model.ObjectId = undefined,
    n: usize = 0,
    kind: enum { edge, gap } = .edge,
    feature: Feature = .left,
    /// For gaps: stacked (gaps down), else across.
    down: bool = false,
} = null;

var constraint_issues: []constrain.Issue = &.{};
var constraint_issues_rev: u64 = std.math.maxInt(u64);

/// The flagged constraints, checked again when the model has changed.
fn constraintIssues() []const constrain.Issue {
    if (constraint_issues_rev != state.model.revision) {
        state.gpa.free(constraint_issues);
        constraint_issues = constrain.check(&state.model, state.gpa) catch &.{};
        constraint_issues_rev = state.model.revision;
    }
    return constraint_issues;
}

fn constraintIssue(id: layout.model.ObjectId) ?constrain.Issue {
    for (constraintIssues()) |i| if (i.constraint == id) return i;
    return null;
}

/// The positioning object the context is, if it is one.
fn contextObject() ?layout.model.ObjectId {
    const m = &state.model;
    return switch (state.context) {
        .panel => |pi| m.panels.items[pi].id,
        .region => |r| m.regionsIn(r.parent)[r.region].id,
        .art => |l| m.panels.items[l.panel].art.items[l.index].id,
        .image => |im| if (imageAt(im.space, im.index)) |image| image.id else null,
        .figure_place => |c| if (figurePlaceAt(c.space, c.index)) |fp| fp.id else null,
        else => null,
    };
}

/// The objects constraints may be put on in the shown space.
fn constrainables(a: std.mem.Allocator) []layout.model.ObjectId {
    var list: std.ArrayList(layout.model.ObjectId) = .empty;
    const m = &state.model;
    if (shown_space < m.spaces.items.len) for (m.spaces.items[shown_space].regions.items) |r| {
        list.append(a, r.id) catch {};
        for (r.path.items) |cp| list.append(a, cp.id) catch {};
    };
    for (m.panels.items) |p| {
        if (p.space != spaceId(shown_space)) continue;
        list.append(a, p.id) catch {};
        for (p.regions.items) |r| {
            list.append(a, r.id) catch {};
            for (r.path.items) |cp| list.append(a, cp.id) catch {};
        }
        for (p.art.items) |x| list.append(a, x.id) catch {};
    }
    if (shown_space < m.spaces.items.len) for (m.spaces.items[shown_space].images.items) |im| list.append(a, im.id) catch {};
    if (shown_space < m.spaces.items.len) for (m.spaces.items[shown_space].figure_places.items) |fp| list.append(a, fp.id) catch {};
    return list.items;
}

fn offsetBox(b: geom.Box, o: geom.Point) geom.Box {
    return .{ .x0 = b.x0 + o.x, .x1 = b.x1 + o.x, .y0 = b.y0 + o.y, .y1 = b.y1 + o.y };
}

const all_features = [_]Feature{ .left, .centre_x, .right, .origin_x, .bottom, .centre_y, .top, .origin_y, .baseline };

/// Feature `f`'s line on box `b` (space mm), at `pos` on its axis; a point
/// object's line is a short one through it.
fn featureLine(f: Feature, pos: f64, b: geom.Box) [2]geom.Point {
    const reach = 10 / state.view.ppm;
    if (f.vertical()) {
        const x0 = if (b.width() > 0) b.x0 else b.x0 - reach;
        const x1 = if (b.width() > 0) b.x1 else b.x1 + reach;
        return .{ .{ .x = x0, .y = pos }, .{ .x = x1, .y = pos } };
    }
    const y0 = if (b.height() > 0) b.y0 else b.y0 - reach;
    const y1 = if (b.height() > 0) b.y1 else b.y1 + reach;
    return .{ .{ .x = pos, .y = y0 }, .{ .x = pos, .y = y1 } };
}

/// The feature nearest `at` (space mm) within a few pixels: any, or once a
/// first is picked, one on its axis of the same object, a peer or the
/// parent.
fn featureHit(at: geom.Point) ?FeatureHit {
    const m = &state.model;
    const a = dvui.currentWindow().arena();
    const tol = 7 / state.view.ppm;
    var best: ?FeatureHit = null;
    var best_d: f64 = std.math.inf(f64);
    const consider = struct {
        fn f(hit: FeatureHit, p: geom.Point, t: f64, rank: f64, bh: *?FeatureHit, bd: *f64) void {
            const vertical = hit.end.feature.vertical();
            const along_lo = if (vertical) @min(hit.p0.x, hit.p1.x) else @min(hit.p0.y, hit.p1.y);
            const along_hi = if (vertical) @max(hit.p0.x, hit.p1.x) else @max(hit.p0.y, hit.p1.y);
            const along = if (vertical) p.x else p.y;
            if (along < along_lo - t or along > along_hi + t) return;
            const d = @abs(if (vertical) p.y - hit.p0.y else p.x - hit.p0.x);
            if (d > t) return;
            const score = d + rank * t * 0.2;
            if (score < bd.*) {
                bd.* = score;
                bh.* = hit;
            }
        }
    }.f;
    const rank = struct {
        fn of(f: Feature) f64 {
            return switch (f) {
                .left, .right, .bottom, .top => 0,
                .origin_x, .origin_y => 1,
                .baseline => 0.5,
                .centre_x, .centre_y => 2,
            };
        }
    }.of;
    const first = constrain_first;
    const first_parent: ?constrain.Parent = if (first) |f| f.parent else null;
    // The parent panel, if the first pick's parent is one: its features
    // are offered as the parent's, not as a peer's.
    const parent_panel_id: ?layout.model.ObjectId = if (first_parent) |fp| switch (fp) {
        .panel => |pi| m.panels.items[pi].id,
        .space => null,
    } else null;
    for (constrainables(a)) |id| {
        if (parent_panel_id != null and id == parent_panel_id.?) continue;
        const parent = constrain.parentOf(m, id) orelse continue;
        // Any frame of the first pick's workspace (a column in a panel
        // against a line on the canvas): positions are in one space.
        if (first_parent) |fp| if (constrain.spaceOf(m, fp) != constrain.spaceOf(m, parent)) continue;
        const off = constrain.frameOffset(m, parent);
        const box = offsetBox(constrain.boxOf(m, id) orelse continue, off);
        const point = isControlPoint(id);
        for (all_features) |f| {
            if (first) |fh| if (f.vertical() != fh.end.feature.vertical()) continue;
            // A path's point has only its place: its origin.
            if (point and f != .origin_x and f != .origin_y) continue;
            const end: ConstraintEnd = .{ .object = id, .feature = f };
            if (first) |fh| if (std.meta.eql(fh.end, end)) continue;
            const pos = (constrain.featureAt(m, parent, end) orelse continue) + if (f.vertical()) off.y else off.x;
            const line = featureLine(f, pos, box);
            consider(.{ .end = end, .parent = parent, .p0 = line[0], .p1 = line[1] }, at, tol, rank(f), &best, &best_d);
        }
    }
    // Construction lines in the shown space: a horizontal one's height, a
    // vertical one's place across (`origin_y`, `origin_x`: its point), each
    // offered along the line itself. A line at another angle has no single
    // place on either axis, so is not offered.
    if (shown_space < m.spaces.items.len) {
        const parent: constrain.Parent = .{ .space = shown_space };
        if (first_parent == null or constrain.spaceOf(m, first_parent.?) == shown_space) {
            const far = 1e5;
            const clip: geom.Box = if (canvas_free) |cf| guideClipBox(cf.area, shown_space) else .{ .x0 = -far, .x1 = far, .y0 = -far, .y1 = far };
            for (m.spaces.items[shown_space].guides.items) |g| {
                const r = g.angle * std.math.pi / 180;
                const horizontal = @abs(@sin(r)) < 1e-9;
                const vertical_line = @abs(@cos(r)) < 1e-9;
                if (!horizontal and !vertical_line) continue;
                const f: Feature = if (horizontal) .origin_y else .origin_x;
                if (first) |fh| if (f.vertical() != fh.end.feature.vertical()) continue;
                const end: ConstraintEnd = .{ .object = g.id, .feature = f };
                if (first) |fh| if (std.meta.eql(fh.end, end)) continue;
                const seg = g.clip(clip) orelse continue;
                consider(.{ .end = end, .parent = parent, .p0 = seg[0], .p1 = seg[1] }, at, tol, 0, &best, &best_d);
            }
        }
    }
    // The parent's own features, once a first is picked.
    if (first) |fh| {
        const parent = fh.parent;
        const off = constrain.frameOffset(m, parent);
        const far = 1e5;
        var pbox: geom.Box = .{ .x0 = -far, .x1 = far, .y0 = -far, .y1 = far };
        if (parent == .panel) pbox = m.panels.items[parent.panel].box();
        for (all_features) |f| {
            if (f.vertical() != fh.end.feature.vertical()) continue;
            const end: ConstraintEnd = .{ .feature = f };
            const pos = (constrain.featureAt(m, parent, end) orelse continue) + if (f.vertical()) off.y else off.x;
            const line = featureLine(f, pos, pbox);
            consider(.{ .end = end, .parent = parent, .p0 = line[0], .p1 = line[1] }, at, tol, rank(f) + 0.5, &best, &best_d);
        }
    }
    return best;
}

/// A track's flow: which it is (chosen from the document's), where the
/// track comes in it, what it continues and goes on into, and buttons to
/// join a track after it or take it out of its flow.
fn threadProperties(pi: Parent, ri: usize) void {
    const m = &state.model;
    const before = m.threadBefore(pi, ri);
    const after = m.threadAfter(pi, ri);
    var buf: [160]u8 = undefined;
    if (m.trackFlow(pi, ri)) |cur| {
        const a = dvui.currentWindow().arena();
        const names = a.alloc([]const u8, m.flows.items.len) catch return;
        var choice: usize = 0;
        for (m.flows.items, names, 0..) |f, *n, k| {
            n.* = if (f.tracks.items.len == 0) (std.fmt.allocPrint(a, "{s} · unplaced", .{f.name}) catch f.name) else f.name;
            if (f.id == cur.id) choice = k;
        }
        const was = choice;
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
            defer row.deinit();
            propName(asElement("track.flow.choice"));
            if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 29 })) if (choice != was) {
                const to = m.flows.items[choice].id;
                if (act(.assignTrack, .{ pi, ri, to, null })) {
                    state.status = "The track now runs the flow chosen, after its other tracks. ";
                } else |err| state.status = if (err == error.BadJoin) "That flow's tracks run the other way. " else "The track was not moved to that flow. ";
            };
        }
        if (m.trackFlow(pi, ri)) |f| {
            const k = for (f.tracks.items, 0..) |t, i| {
                if (t == m.regionsIn(pi)[ri].id) break i;
            } else 0;
            propText(asElement("track.flow.position"), "track {d} of {d}", .{ k + 1, f.tracks.items.len }, 32);
            actionButton(@src(), "track.flow.show", null, 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        }
    }
    if (before) |b| propText(asElement("track.flow.before"), "{s}", .{trackLabel(&buf, b, pi)}, 30);
    if (after) |n| propText(asElement("track.flow.after"), "{s}", .{trackLabel(&buf, n, pi)}, 31);
    actionButton(@src(), "track.flow.join-after", null, 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
    const f = m.trackFlow(pi, ri);
    const detachable = f != null and (f.?.tracks.items.len > 1 or f.?.items.items.len > 0);
    if (detachable) actionButton(@src(), "track.flow.take-out", null, 0, .{ .expand = .horizontal });
}

/// The document's flows: how many, how many unplaced, and a new one.
fn flowsProperties() void {
    const saved_group = pushGroup("flows");
    defer popGroup(saved_group);
    var unplaced: usize = 0;
    for (state.model.flows.items) |f| {
        if (f.tracks.items.len == 0) unplaced += 1;
    }
    propText("Flows", "{d}", .{state.model.flows.items.len}, 1);
    propText("Unplaced", "{d}", .{unplaced}, 2);
    actionButton(@src(), "flows.new", null, 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// Removing a flow with content takes a second click: the flow armed.
var flow_remove_armed: ?layout.model.ObjectId = null;

/// A flow: its name, its tracks in order (or unplaced), what it holds,
/// and its removal.
fn flowProperties(id: layout.model.ObjectId) void {
    const saved_group = pushGroup("flow");
    defer popGroup(saved_group);
    const m = &state.model;
    const fi = m.flowIndex(id) orelse return;
    const f = m.flows.items[fi];
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        defer row.deinit();
        propName("Name");
        if (accepted.textField(@src(), f.name, .{ .expand = .horizontal, .id_extra = @intFromEnum(id) }, .{}, accepted.nonEmpty)) |name| act(.renameFlow, .{ id, name }) catch {};
    }
    if (f.tracks.items.len == 0) {
        propText("Tracks", "{s}", .{"none: unplaced"}, 2);
    } else for (f.tracks.items, 0..) |tid, k| {
        var nb: [24]u8 = undefined;
        var tb: [160]u8 = undefined;
        const label = std.fmt.bufPrint(&nb, "Track {d}", .{k + 1}) catch "Track";
        const where = if (m.trackById(tid)) |t| trackPlaceLabel(&tb, t) else "missing";
        // Its tracks in order: flow.track.1, flow.track.2 …
        var gb: [32]u8 = undefined;
        const saved = pushGroup("flow.track");
        next_element = std.fmt.bufPrint(&gb, "flow.track.{d}", .{k + 1}) catch null;
        propText(label, "{s}", .{where}, 10 + k);
        popGroup(saved);
    }
    // What it holds.
    var runs: usize = 0;
    var tiles: usize = 0;
    var words: usize = 0;
    for (f.items.items) |item| switch (item.what) {
        .run => |r| {
            runs += 1;
            var it = std.mem.tokenizeAny(u8, r.content, " \t\n");
            while (it.next()) |_| words += 1;
        },
        .tile => tiles += 1,
        else => {},
    };
    if (tiles > 0) propText("Holds", "{d} words, {d} tiles", .{ words, tiles }, 3) else propText("Holds", "{d} words", .{words}, 3);
    // Where its imported text came from.
    for (f.sources.items, 0..) |src, k| {
        var tb: [24]u8 = undefined;
        propText(if (k == 0) "Source" else "", "{s}, {s}", .{ src.uri, stamp(&tb, src.imported, ':') }, 40 + k);
    }
    if (flow_remove_armed != null and flow_remove_armed.? != id) flow_remove_armed = null;
    const armed = flow_remove_armed != null;
    actionButton(@src(), "flow.remove", if (armed) "Remove it and all it holds: press again" else "Remove flow", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// A track's name, with its panel's when that is not panel `here`.
fn trackLabel(buf: []u8, t: layout.model.TrackRef, here: Parent) []const u8 {
    const name = state.model.regionsIn(t.parent)[t.region].name;
    if (t.parent.eql(here)) return name;
    return std.fmt.bufPrint(buf, "{s} (on {s})", .{ name, state.model.parentName(t.parent) }) catch name;
}

/// The track under `at` (sheet mm) in the shown space: the one a placed
/// segment there lies in, or whose boundary holds it.
fn trackUnder(at: geom.Point) ?struct { parent: Parent, region: usize } {
    for (0..state.model.parentCount()) |pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi)) continue;
        const pl = placedOf(pi) orelse continue;
        for (pl.tracks) |t| if (contains(onSheet(pi, t.box), at)) return .{ .parent = pi, .region = t.member };
        for (state.model.regionsIn(pi), 0..) |r, k| if (contains(onSheet(pi, r.bounds()), at)) return .{ .parent = pi, .region = k };
    }
    return null;
}

/// A click with the Join tool: the track clicked goes on after the one
/// joining.
fn joinClick(at: geom.Point) void {
    const from = join_from orelse return;
    state.tool = .select;
    join_from = null;
    const to = trackUnder(at) orelse {
        state.status = "No track there: nothing joined. ";
        return;
    };
    act(.threadTracks, .{ from.parent, from.region, to.parent, to.region }) catch {
        state.status = "Not joined: a flow joins tracks running the same way, and the track joined must start its own flow. ";
        return;
    };
    state.status = "Joined: the flow goes on into it. ";
}

/// Each thread's links, faintly: from where its flow leaves one track (its
/// last segment there) to where it enters the next, by the shortest route
/// that leaves and arrives along the tracks with a bounded bend
/// (`geom.dubins`; the owner, 2026-11-22).
fn drawThreads(area: dvui.Rect.Physical, pi: Parent, placed: *const layout.place.Placed) void {
    const m = &state.model;
    const px = dvui.windowNaturalScale();
    const ink: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.7) };
    for (m.regionsIn(pi), 0..) |r, ri| {
        const nt = m.threadAfter(pi, ri) orelse continue;
        // On another panel: drawn when both are in the shown space.
        if (m.spaceOfParent(nt.parent) != m.spaceOfParent(pi)) continue;
        // Leaving: its last segment the flow reached, else its first.
        var from_box: geom.Box = r.boxAt(.{ .along = r.pathAt(0), .across = 0 });
        for (placed.tracks) |t| if (t.member == ri) {
            from_box = t.box;
        };
        const nr = m.regionsIn(nt.parent)[nt.region];
        var to_box: geom.Box = nr.boxAt(.{ .along = nr.pathAt(0), .across = 0 });
        if (placedOf(nt.parent)) |npl| for (npl.tracks) |t| if (t.member == nt.region and t.local == 0) {
            to_box = t.box;
        };
        const rows = r.major() == .row;
        const p0: geom.Point = if (rows) .{ .x = from_box.x1, .y = (from_box.y0 + from_box.y1) / 2 } else .{ .x = (from_box.x0 + from_box.x1) / 2, .y = from_box.y0 };
        const p1: geom.Point = if (rows) .{ .x = to_box.x0, .y = (to_box.y0 + to_box.y1) / 2 } else .{ .x = (to_box.x0 + to_box.x1) / 2, .y = to_box.y1 };
        // Rows run to the right, columns down: the route leaves the one
        // track's end that way and comes into the next track's start
        // that way, bending no more sharply than `thread_bend` of the
        // track's thickness allows.
        const angle: f64 = if (rows) 0 else -std.math.pi / 2.0;
        const thick = if (rows) from_box.height() else from_box.width();
        const radius = std.math.clamp(thread_bend * thick, 1.0, 8.0);
        const lead = thread_lead * radius;
        const rt = geom.dubins.route(
            .{ .at = onSheetPoint(pi, p0), .angle = angle, .lead = lead },
            .{ .at = onSheetPoint(nt.parent, p1), .angle = angle, .lead = lead },
            radius,
        );
        var mm_buf: [256]geom.Point = undefined;
        const tol = 0.3 / @max(state.view.ppm, 1e-6);
        const mm_pts = rt.flatten(tol, &mm_buf);
        if (mm_pts.len < 2) continue;
        var px_buf: [256]dvui.Point.Physical = undefined;
        for (mm_pts, 0..) |q, k| px_buf[k] = state.view.toPx(area, q);
        const b = px_buf[mm_pts.len - 1];
        dvui.Path.stroke(.{ .points = px_buf[0..mm_pts.len] }, .{ .thickness = 1.25 * px, .color = ink });
        // An arrowhead where it enters, along the track (y down on screen).
        const ux: f32 = @floatCast(@cos(rt.end_angle));
        const uy: f32 = @floatCast(-@sin(rt.end_angle));
        const s: f32 = 6 * px;
        dvui.Path.stroke(.{ .points = &.{ .{ .x = b.x - s * ux + s * 0.5 * uy, .y = b.y - s * uy - s * 0.5 * ux }, b, .{ .x = b.x - s * ux - s * 0.5 * uy, .y = b.y - s * uy + s * 0.5 * ux } } }, .{ .thickness = 1.25 * px, .color = ink });
    }
}

/// The line from one track to the next in a flow: its tightest bend, as a
/// share of the track's thickness (a radius, clamped to 1..8 mm), and the
/// straight run at each end, as a share of that radius.
const thread_bend = 0.3;
const thread_lead = 0.6;

fn onSheetPoint(pi: Parent, p: geom.Point) geom.Point {
    const o = parentOrigin(pi);
    return .{ .x = o.x + p.x, .y = o.y + p.y };
}

// Selecting, moving and resizing ------------------------------------------------
//
// Ctrl-click (Cmd on macOS) near a container's edge puts the nearest
// container in the selection, or takes it out; Tab hunts on to the
// next-nearest from the same click. A selection holds containers of one
// parent. Each selected container shows a translucent box: a drag on it
// moves the selection, and a lone selected container has handles on the
// edges it may be resized by. Moves and resizes go only where constraints
// leave freedom: the constraints are solved as the drag goes, so what
// they bind stays and what keeps to the moved follows.

/// The last Ctrl-click: where, the containers whose edges were near it
/// (nearest first), and which of them it took.
var hunt: ?struct { at: geom.Point, ids: []layout.model.ObjectId, k: usize } = null;

/// A press on a selected container's box: once dragged, it moves the
/// selection from where each was (boxes in their parents' frames).
var sel_press: ?struct { start: geom.Point, moved: bool, key: u64, ids: []layout.model.ObjectId, boxes: []geom.Box } = null;

/// A drag on a resize handle of the lone selected container.
const Edges = struct { left: bool = false, right: bool = false, bottom: bool = false, top: bool = false };
const Handle = struct { at: geom.Point, edges: Edges };
var resize_drag: ?struct { id: layout.model.ObjectId, edges: Edges, start: geom.Point, box: geom.Box, key: u64 } = null;

/// Which ways the lone selected container may move and resize, worked
/// out once per document revision.
var free_cache: ?struct { id: layout.model.ObjectId, rev: u64, f: constrain.Freedom } = null;
var drag_count: u64 = 0;

/// Whether Ctrl (or Cmd) is held for a click: as the event says, or as
/// the keyboard is now. The event's modifiers are those of the last key
/// event the window had, which a Ctrl pressed before the window had the
/// keyboard (or reported only as a modifier change, as Wayland may) never
/// was; SDL keeps the live state.
fn primaryMod(mod: dvui.enums.Mod) bool {
    if (mod.control() or mod.command()) return true;
    if (dvui.backend.kind != .sdl3) return false;
    const c = dvui.backend.c;
    const live = c.SDL_GetModState();
    return (live & (c.SDL_KMOD_CTRL | c.SDL_KMOD_GUI)) != 0;
}

fn hunt_clear() void {
    if (hunt) |h| state.gpa.free(h.ids);
    hunt = null;
}

/// A container's box on the canvas (its space's frame), mm.
fn containerBox(id: layout.model.ObjectId) ?geom.Box {
    if (state.model.group(id) != null) {
        const b = idBox(id);
        return if (b.isEmpty()) null else b;
    }
    const parent = constrain.parentOf(&state.model, id) orelse return null;
    const b = constrain.boxOf(&state.model, id) orelse return null;
    return offsetBox(b, constrain.frameOffset(&state.model, parent));
}

/// How far `p` is from box `b`'s edges, mm.
fn edgeDistance(b: geom.Box, p: geom.Point) f64 {
    const inside = p.x >= b.x0 and p.x <= b.x1 and p.y >= b.y0 and p.y <= b.y1;
    if (inside) return @min(@min(p.x - b.x0, b.x1 - p.x), @min(p.y - b.y0, b.y1 - p.y));
    const dx = @max(@max(b.x0 - p.x, 0), p.x - b.x1);
    const dy = @max(@max(b.y0 - p.y, 0), p.y - b.y1);
    return @sqrt(dx * dx + dy * dy);
}

/// The containers in the shown space whose edges lie within a few pixels
/// of `at`, nearest first.
fn containersNear(at: geom.Point) []layout.model.ObjectId {
    const a = dvui.currentWindow().arena();
    const tol = 8 / state.view.ppm;
    const Near = struct { id: layout.model.ObjectId, d: f64 };
    var list: std.ArrayList(Near) = .empty;
    for (constrainables(a)) |id| {
        if (isControlPoint(id)) continue;
        const b = containerBox(id) orelse continue;
        const d = edgeDistance(b, at);
        if (d <= tol) list.append(a, .{ .id = id, .d = d }) catch {};
    }
    std.mem.sort(Near, list.items, {}, struct {
        fn lt(_: void, x: Near, y: Near) bool {
            return x.d < y.d;
        }
    }.lt);
    var ids = a.alloc(layout.model.ObjectId, list.items.len) catch return &.{};
    for (list.items, 0..) |n, k| ids[k] = n.id;
    return ids;
}

fn selectedAt(id: layout.model.ObjectId) ?usize {
    return std.mem.indexOfScalar(layout.model.ObjectId, selection.items, id);
}

/// Puts `id` in the selection, or takes it out. A container of another
/// parent starts a new selection.
fn toggleSelected(id: layout.model.ObjectId) void {
    if (selectedAt(id)) |k| {
        _ = selection.orderedRemove(k);
        return;
    }
    if (selection.items.len > 0) {
        const a = constrain.parentOf(&state.model, selection.items[0]);
        const b = constrain.parentOf(&state.model, id);
        if (!std.meta.eql(a, b)) {
            selection.clearRetainingCapacity();
            state.status = "A selection holds containers of one parent: a new one starts. ";
        }
    }
    selection.append(state.gpa, id) catch {};
}

fn ctrlPick(at: geom.Point) void {
    hunt_clear();
    const near = containersNear(at);
    if (near.len == 0) {
        state.status = "No container's edge there. ";
        return;
    }
    hunt = .{ .at = at, .ids = state.gpa.dupe(layout.model.ObjectId, near) catch return, .k = 0 };
    toggleSelected(near[0]);
    state.context = .selection;
    if (near.len > 1) state.status = "Tab takes the next-nearest container instead. ";
}

/// Swaps the container the last Ctrl-click took for the next-nearest (or,
/// back, the one before).
fn huntNext(back: bool) bool {
    if (hunt == null) return false;
    const h = &hunt.?;
    if (h.ids.len < 2) return false;
    if (selectedAt(h.ids[h.k])) |k| _ = selection.orderedRemove(k);
    h.k = if (back) (h.k + h.ids.len - 1) % h.ids.len else (h.k + 1) % h.ids.len;
    if (selectedAt(h.ids[h.k]) == null) toggleSelected(h.ids[h.k]);
    state.context = .selection;
    state.status = std.fmt.bufPrint(&status_hunt_buf, "Selected {s}. ", .{objectName(h.ids[h.k])}) catch "";
    return true;
}
var status_hunt_buf: [128]u8 = undefined;

/// An action of mode `canvas.selection`: Tab hunts on to the next-nearest
/// container of the last Ctrl-click (Shift+Tab back), Esc empties the
/// selection, the arrows move it. Whether it was done.
fn selectionAction(inv: keymap.Invocation) bool {
    switch (inv.action) {
        kact("canvas.selection.hunt") => {
            // Taken even with nothing to hunt to: left to the toolkit, Tab
            // would take the keyboard from the canvas to the next widget.
            if (!huntNext(inv.arg == 1)) state.status = "Nothing else is near the last Ctrl-click for Tab to take. ";
            return true;
        },
        kact("canvas.selection.clear") => {
            selection.clearRetainingCapacity();
            hunt_clear();
            if (state.context == .selection) state.context = .worksheet;
            return true;
        },
        kact("canvas.selection.nudge"), kact("canvas.selection.nudge-far") => {
            const step = selectionStep(inv.action == kact("canvas.selection.nudge-far"));
            const d: geom.Point = switch (inv.dir()) {
                .left => .{ .x = -step, .y = 0 },
                .right => .{ .x = step, .y = 0 },
                .up => .{ .x = 0, .y = step },
                .down => .{ .x = 0, .y = -step },
            };
            moveSelectionBy(d, mergeKey(.{ "nudge", selection.items.len, selection.items[0] }));
            var lb: [32]u8 = undefined;
            state.status = std.fmt.bufPrint(&nudge_status, "Moved {s}. ", .{lengthText(&lb, step)}) catch "";
            return true;
        },
        else => return false,
    }
}

var nudge_status: [64]u8 = undefined;

/// The selection's nudge step, mm: a lone track's own step (its pitch
/// times its tiles' step; major: its pitch, a whole unit), else the grid's
/// minor or major unit (`nudgeStep`).
fn selectionStep(major: bool) f64 {
    if (selection.items.len == 1) {
        for (0..state.model.parentCount()) |k| for (state.model.regionsIn(state.model.parentAt(k)), 0..) |r, ri| {
            if (r.id == selection.items[0]) return if (major) r.pitch else moveStep(state.model.parentAt(k), ri) * r.pitch;
        };
    }
    return nudgeStep(major);
}

/// Moves the selection by `d` mm from where each is now (a group as a
/// whole).
fn moveSelectionBy(d: geom.Point, key: u64) void {
    const a = dvui.currentWindow().arena();
    var ids: std.ArrayList(layout.model.ObjectId) = .empty;
    var boxes: std.ArrayList(geom.Box) = .empty;
    for (selection.items) |id| if (state.model.group(id) != null) {
        _ = actM(key, .moveGroup, .{ id, d.x, d.y }) catch {};
    };
    for (selection.items) |id| {
        if (state.model.group(id) != null) continue;
        const b = constrain.boxOf(&state.model, id) orelse continue;
        ids.append(a, id) catch return;
        boxes.append(a, .{ .x0 = b.x0 + d.x, .x1 = b.x1 + d.x, .y0 = b.y0 + d.y, .y1 = b.y1 + d.y }) catch return;
    }
    if (ids.items.len == 0) return;
    _ = actM(key, .placeObjects, .{ ids.items, boxes.items }) catch {
        state.status = "It did not move. ";
    };
}

fn freedomOf(id: layout.model.ObjectId) constrain.Freedom {
    if (free_cache) |c| if (c.id == id and c.rev == state.model.revision) return c.f;
    const f = constrain.freedom(state.gpa, &state.model, id) catch constrain.Freedom{};
    free_cache = .{ .id = id, .rev = state.model.revision, .f = f };
    return f;
}

/// The lone selected container's resize handles: where each is on the
/// canvas, and which edges it moves. Only edges it may be resized by.
fn resizeHandles(buf: []Handle) usize {
    if (selection.items.len != 1) return 0;
    const id = selection.items[0];
    if (state.model.group(id) != null) return 0;
    const b = containerBox(id) orelse return 0;
    const f = freedomOf(id);
    const mx = (b.x0 + b.x1) / 2;
    const my = (b.y0 + b.y1) / 2;
    var n: usize = 0;
    const all = [_]struct { at: geom.Point, edges: Edges, ok: bool }{
        .{ .at = .{ .x = b.x0, .y = my }, .edges = .{ .left = true }, .ok = f.left },
        .{ .at = .{ .x = b.x1, .y = my }, .edges = .{ .right = true }, .ok = f.right },
        .{ .at = .{ .x = mx, .y = b.y0 }, .edges = .{ .bottom = true }, .ok = f.bottom },
        .{ .at = .{ .x = mx, .y = b.y1 }, .edges = .{ .top = true }, .ok = f.top },
        // A corner with either edge free: it goes along that one.
        .{ .at = .{ .x = b.x0, .y = b.y0 }, .edges = .{ .left = f.left, .bottom = f.bottom }, .ok = f.left or f.bottom },
        .{ .at = .{ .x = b.x1, .y = b.y0 }, .edges = .{ .right = f.right, .bottom = f.bottom }, .ok = f.right or f.bottom },
        .{ .at = .{ .x = b.x0, .y = b.y1 }, .edges = .{ .left = f.left, .top = f.top }, .ok = f.left or f.top },
        .{ .at = .{ .x = b.x1, .y = b.y1 }, .edges = .{ .right = f.right, .top = f.top }, .ok = f.right or f.top },
    };
    for (all) |h| if (h.ok and n < buf.len) {
        buf[n] = .{ .at = h.at, .edges = h.edges };
        n += 1;
    };
    return n;
}

/// A press with the select tool: on a resize handle, or on a selected
/// container's box. Whether it was.
fn selectionPress(at: geom.Point) bool {
    if (selection.items.len == 0) return false;
    drag_count += 1;
    var hb: [8]Handle = undefined;
    const tol = 6 / state.view.ppm;
    for (hb[0..resizeHandles(&hb)]) |h| {
        if (@abs(h.at.x - at.x) > tol or @abs(h.at.y - at.y) > tol) continue;
        const id = selection.items[0];
        resize_drag = .{ .id = id, .edges = h.edges, .start = at, .box = constrain.boxOf(&state.model, id) orelse return false, .key = mergeKey(.{ "resize", drag_count }) };
        return true;
    }
    const on = for (selection.items) |id| {
        const b = containerBox(id) orelse continue;
        if (contains(b, at)) break true;
    } else false;
    if (!on) return false;
    const ids = state.gpa.dupe(layout.model.ObjectId, selection.items) catch return false;
    const boxes = state.gpa.alloc(geom.Box, ids.len) catch {
        state.gpa.free(ids);
        return false;
    };
    for (ids, boxes) |id, *b| b.* = constrain.boxOf(&state.model, id) orelse .empty;
    sel_press = .{ .start = at, .moved = false, .key = mergeKey(.{ "selmove", drag_count }), .ids = ids, .boxes = boxes };
    return true;
}

fn selectionDrag(at: geom.Point) void {
    if (resize_drag) |r| {
        const dx = at.x - r.start.x;
        const dy = at.y - r.start.y;
        var b = r.box;
        const min = 1.0;
        if (r.edges.left) b.x0 = @min(b.x0 + dx, b.x1 - min);
        if (r.edges.right) b.x1 = @max(b.x1 + dx, b.x0 + min);
        if (r.edges.bottom) b.y0 = @min(b.y0 + dy, b.y1 - min);
        if (r.edges.top) b.y1 = @max(b.y1 + dy, b.y0 + min);
        // The edges it moves on the grid (the canvas's, so in the frame's
        // offset).
        snap_guide = .{};
        if (snapStep()) |st| if (constrain.parentOf(&state.model, r.id)) |parent| {
            const off = constrain.frameOffset(&state.model, parent);
            if (r.edges.left) b.x0 = @min(snapAxis(b.x0 + off.x, st, &snap_guide.x) - off.x, b.x1 - min);
            if (r.edges.right) b.x1 = @max(snapAxis(b.x1 + off.x, st, &snap_guide.x) - off.x, b.x0 + min);
            if (r.edges.bottom) b.y0 = @min(snapAxis(b.y0 + off.y, st, &snap_guide.y) - off.y, b.y1 - min);
            if (r.edges.top) b.y1 = @max(snapAxis(b.y1 + off.y, st, &snap_guide.y) - off.y, b.y0 + min);
        };
        if (figureProportions(r.id)) |pr| b = keepFigureProportions(pr, r.box, b, r.edges);
        _ = actM(r.key, .placeObjects, .{ &[_]layout.model.ObjectId{r.id}, &[_]geom.Box{b} }) catch {};
        return;
    }
    if (sel_press == null) return;
    const sp = &sel_press.?;
    const dx = at.x - sp.start.x;
    const dy = at.y - sp.start.y;
    // A few pixels before it is a drag, not a click.
    if (!sp.moved and @sqrt(dx * dx + dy * dy) * state.view.ppm < 4) return;
    sp.moved = true;
    // The first one's origin (its top-left) on the grid; the rest with it.
    var mx = dx;
    var my = dy;
    snap_guide = .{};
    if (snapStep()) |st| if (sp.ids.len > 0) if (constrain.parentOf(&state.model, sp.ids[0])) |parent| {
        const off = constrain.frameOffset(&state.model, parent);
        mx = snapShift(sp.boxes[0].x0 + off.x, dx, st, &snap_guide.x);
        my = snapShift(sp.boxes[0].y1 + off.y, dy, st, &snap_guide.y);
    };
    const a = dvui.currentWindow().arena();
    const boxes = a.alloc(geom.Box, sp.boxes.len) catch return;
    for (sp.boxes, boxes) |b, *o| o.* = .{ .x0 = b.x0 + mx, .x1 = b.x1 + mx, .y0 = b.y0 + my, .y1 = b.y1 + my };
    _ = actM(sp.key, .placeObjects, .{ sp.ids, boxes }) catch {};
}

fn selectionDragEnd() void {
    resize_drag = null;
    if (sel_press) |sp| {
        state.gpa.free(sp.ids);
        state.gpa.free(sp.boxes);
    }
    sel_press = null;
}

/// What the pointer shows over the selection: a system cursor (resize
/// arrows), or a mark drawn at it: an open hand where a drag would move
/// the selection, a closed one while it does, a lock where it cannot move.
const PointerMark = union(enum) { cursor: dvui.enums.Cursor, grab, grabbing, locked };
var pointer_mark: ?struct { mark: PointerMark, p: dvui.Point.Physical } = null;

fn selectionPointer(at: geom.Point) ?PointerMark {
    if (selection.items.len == 0) return null;
    if (resize_drag) |r| return .{ .cursor = edgesCursor(r.edges) };
    if (sel_press) |sp| if (sp.moved) return .grabbing;
    var hb: [8]Handle = undefined;
    const tol = 6 / state.view.ppm;
    for (hb[0..resizeHandles(&hb)]) |h| {
        if (@abs(h.at.x - at.x) <= tol and @abs(h.at.y - at.y) <= tol) return .{ .cursor = edgesCursor(h.edges) };
    }
    const over = for (selection.items) |id| {
        const b = containerBox(id) orelse continue;
        if (contains(b, at)) break true;
    } else false;
    if (!over) return null;
    return if (selectionMovable()) .grab else .locked;
}

fn edgesCursor(e: Edges) dvui.enums.Cursor {
    const h = e.left or e.right;
    const v = e.bottom or e.top;
    if (h and v) return if ((e.left and e.top) or (e.right and e.bottom)) .arrow_nw_se else .arrow_ne_sw;
    return if (h) .arrow_w_e else .arrow_n_s;
}

/// Whether the selection can move at all: every container in it free
/// along one axis at least. Worked out once per revision and selection.
var movable_cache: ?struct { rev: u64, key: u64, movable: bool } = null;

fn selectionMovable() bool {
    const key = mergeKey(.{selection.items});
    if (movable_cache) |c| if (c.rev == state.model.revision and c.key == key) return c.movable;
    var movable = true;
    for (selection.items) |id| {
        if (state.model.group(id) != null) continue;
        const f = if (selection.items.len == 1) freedomOf(id) else (constrain.freedom(state.gpa, &state.model, id) catch constrain.Freedom{});
        if (!f.x and !f.y) movable = false;
    }
    movable_cache = .{ .rev = state.model.revision, .key = key, .movable = movable };
    return movable;
}


// Engagement points ---------------------------------------------------------
//
// As in sketches, the pointer engages what it is near: every container on
// the canvas offers its corners and edge midpoints (resize two edges, one
// edge), its edges (resize one) and its centre (move). The nearest within
// a few pixels is highlighted, and an annunciator beside the pointer says
// what a press would do, or what holds it. Tab locks onto it (and on to the
// next-nearest; Shift+Tab back; Esc lets go, as does going well away). A
// drag from an engagement point moves that point itself, so it lands
// exactly where it is taken; the system pointer cannot be put on it
// (Wayland does not allow it), so while dragging it is hidden and the
// point, standing in for it, scintillates.
//
// A policy for the whole interface: a point that stands in for the
// pointer (a locked point, a point being dragged with the pointer hidden)
// scintillates, to draw the eye.

/// What an engagement point does: the origin and the centre move the
/// container (the origin is its grab point: a track's top-left mark); a
/// corner resizes two edges, an edge's midpoint or the edge itself one.
const EngageKind = enum { origin, centre, corner, edge_mid, edge, dim_value, dim_line };

/// Whether a hit is a constraint's dimension (its `id` the constraint's).
fn isDimKind(k: EngageKind) bool {
    return k == .dim_value or k == .dim_line;
}

/// Whether a press there moves the whole (else it resizes).
fn engageMoves(k: EngageKind) bool {
    return k == .origin or k == .centre;
}

const EngageHit = struct {
    id: layout.model.ObjectId,
    kind: EngageKind,
    /// The edges it moves (none: it moves the whole).
    edges: Edges,
    /// Where it is, on the canvas (the shown space's frame), mm.
    at: geom.Point,
    /// Distance from the pointer, device pixels.
    d: f32,
};

var engage_hits: [16]EngageHit = undefined;
var engage_n: usize = 0;
/// The hit Tab locked onto, and the pointer's place then (device pixels).
var engage_lock: ?EngageHit = null;
var engage_lock_px: dvui.Point.Physical = .{};
var engage_lock_index: usize = 0;
/// Where the pointer was when the points were found (canvas mm), and the
/// model's revision then: a change (an undo, say) finds them again.
var engage_at: ?geom.Point = null;
var engage_rev: u64 = 0;
/// Where the pointer was at the last position event (one comes every
/// frame, moved or not).
var engage_last_px: dvui.Point.Physical = .{};
/// A drag from an engagement point: the container, what moves, its box at
/// the start (its parent's frame), the frame's offset, where the point was
/// and where the pointer was (canvas mm).
var engage_drag: ?struct {
    hit: EngageHit,
    box: geom.Box,
    offset: geom.Point,
    pointer0: geom.Point,
    moved: bool = false,
    key: u64,
    /// The point now (canvas mm), standing in for the pointer.
    now: geom.Point,
} = null;

/// Whether engaging is on: the select tool, the canvas itself (no sketch,
/// panel editing or equation on the canvas).
/// Whether an engagement point or edge of the selection is under the
/// pointer (or locked): moving and sizing come before pointing.
fn engagingPoint() bool {
    return engaging() and (engage_n > 0 or engage_lock != null);
}

fn engaging() bool {
    return state.tool == .select and sketch_edit == null and panel_edit == null and canvas_eq == null and !canvas_prompt;
}

/// Finds the engagement points near device point `px` (canvas mm `at`),
/// nearest first: points within 10 px before edges within 6 px.
fn findEngagements(area: dvui.Rect.Physical, at: geom.Point) void {
    engage_n = 0;
    engage_at = at;
    engage_rev = state.model.revision;
    if (!engaging()) return;
    const a = dvui.currentWindow().arena();
    const ns = dvui.windowNaturalScale();
    const point_r: f32 = 10 * ns;
    const edge_r: f32 = 6 * ns;
    var points: std.ArrayList(EngageHit) = .empty;
    var edges: std.ArrayList(EngageHit) = .empty;
    const pp = state.view.toPx(area, at);
    for (constrainables(a)) |id| {
        if (isControlPoint(id)) continue;
        // Drag points are the selection's (decided 2026-11-21): with
        // nothing selected, the halo shows what a click would select.
        if (std.mem.indexOfScalar(layout.model.ObjectId, selection.items, id) == null) continue;
        const b = containerBox(id) orelse continue;
        const mx = (b.x0 + b.x1) / 2;
        const my = (b.y0 + b.y1) / 2;
        const group = state.model.group(id) != null;
        // Its origin, on the canvas: where it is held from, its grab point.
        const origin: ?geom.Point = if (group) null else if (constrain.originOf(&state.model, id)) |o| blk: {
            const pr = constrain.parentOf(&state.model, id) orelse break :blk null;
            const off = constrain.frameOffset(&state.model, pr);
            break :blk geom.Point{ .x = o.x + off.x, .y = o.y + off.y };
        } else null;
        if (origin) |o| {
            const q = state.view.toPx(area, o);
            const d = @sqrt((q.x - pp.x) * (q.x - pp.x) + (q.y - pp.y) * (q.y - pp.y));
            if (d <= point_r) points.append(a, .{ .id = id, .kind = .origin, .edges = .{}, .at = o, .d = d }) catch {};
        }
        const cands = [_]struct { at: geom.Point, kind: EngageKind, edges: Edges }{
            .{ .at = .{ .x = mx, .y = my }, .kind = .centre, .edges = .{} },
            .{ .at = .{ .x = b.x0, .y = b.y0 }, .kind = .corner, .edges = .{ .left = true, .bottom = true } },
            .{ .at = .{ .x = b.x1, .y = b.y0 }, .kind = .corner, .edges = .{ .right = true, .bottom = true } },
            .{ .at = .{ .x = b.x0, .y = b.y1 }, .kind = .corner, .edges = .{ .left = true, .top = true } },
            .{ .at = .{ .x = b.x1, .y = b.y1 }, .kind = .corner, .edges = .{ .right = true, .top = true } },
            .{ .at = .{ .x = b.x0, .y = my }, .kind = .edge_mid, .edges = .{ .left = true } },
            .{ .at = .{ .x = b.x1, .y = my }, .kind = .edge_mid, .edges = .{ .right = true } },
            .{ .at = .{ .x = mx, .y = b.y0 }, .kind = .edge_mid, .edges = .{ .bottom = true } },
            .{ .at = .{ .x = mx, .y = b.y1 }, .kind = .edge_mid, .edges = .{ .top = true } },
        };
        for (cands) |c| {
            // A group moves as a whole: only its centre.
            if (group and c.kind != .centre) continue;
            const q = state.view.toPx(area, c.at);
            const d = @sqrt((q.x - pp.x) * (q.x - pp.x) + (q.y - pp.y) * (q.y - pp.y));
            if (d <= point_r) points.append(a, .{ .id = id, .kind = c.kind, .edges = c.edges, .at = c.at, .d = d }) catch {};
        }
        if (group) continue;
        // Whole edges are not engaged (the owner, 2026-11-21): the drag
        // points (corners, edge middles, origin) do their work.
    }
    // Nearest first; at one place (a track's origin is its top-left
    // corner), moving before resizing.
    // Constraint dimensions: the value (a point) and the line (none while
    // the Constraints layer is hidden).
    if (ViewLayer.constraints.shown()) for (state.model.constraints.items) |c| {
        const g = dimGeom(c) orelse continue;
        const lq = state.view.toPx(area, g.d.text_at);
        const dl = @sqrt((lq.x - pp.x) * (lq.x - pp.x) + (lq.y - pp.y) * (lq.y - pp.y));
        var tb: [32]u8 = undefined;
        if (strokefont.hit(dimText(&tb, c), dimTextPlace(area, g), .{ .x = pp.x, .y = pp.y }, 4 * ns)) {
            points.append(a, .{ .id = c.id, .kind = .dim_value, .edges = .{}, .at = g.d.text_at, .d = dl }) catch {};
            continue;
        }
        const dd = segDistPx(pp, state.view.toPx(area, g.d.line[0]), state.view.toPx(area, g.d.line[1]));
        if (dd <= edge_r) edges.append(a, .{ .id = c.id, .kind = .dim_line, .edges = .{}, .at = at, .d = dd }) catch {};
    };
    const by_d = struct {
        fn lt(_: void, x: EngageHit, y: EngageHit) bool {
            if (@abs(x.d - y.d) > 0.5) return x.d < y.d;
            return @intFromEnum(x.kind) < @intFromEnum(y.kind);
        }
    }.lt;
    std.mem.sort(EngageHit, points.items, {}, by_d);
    std.mem.sort(EngageHit, edges.items, {}, by_d);
    for (points.items) |h| if (engage_n < engage_hits.len) {
        engage_hits[engage_n] = h;
        engage_n += 1;
    };
    for (edges.items) |h| if (engage_n < engage_hits.len) {
        engage_hits[engage_n] = h;
        engage_n += 1;
    };
}

/// What is engaged, as a number that changes when it does (the target,
/// whether locked, where an edge's point is).
fn engageKey() u64 {
    const t = engageTarget() orelse return 0;
    return mergeKey(.{ t.id, @intFromEnum(t.kind), t.edges.left, t.edges.right, t.edges.bottom, t.edges.top, @as(i64, @intFromFloat(@round(t.at.x * 100))), @as(i64, @intFromFloat(@round(t.at.y * 100))), engage_lock != null });
}

/// What a press would engage: the locked point, else the nearest.
fn engageTarget() ?EngageHit {
    if (engage_lock) |l| return l;
    if (engage_n > 0) return engage_hits[0];
    return null;
}

/// What of hit `h` its container's constraints leave free: for a move,
/// the axes; for a resize, the edges. As in sketches, a point goes as far
/// as its constraints let it: along a free axis though the other is held.
fn engageFreedom(h: EngageHit) struct { x: bool, y: bool, edges: Edges } {
    if (isDimKind(h.kind) or state.model.group(h.id) != null) return .{ .x = true, .y = true, .edges = h.edges };
    const f = freedomOf(h.id);
    return .{
        .x = f.x,
        .y = f.y,
        .edges = .{ .left = h.edges.left and f.left, .right = h.edges.right and f.right, .bottom = h.edges.bottom and f.bottom, .top = h.edges.top and f.top },
    };
}

fn anyEdge(e: Edges) bool {
    return e.left or e.right or e.bottom or e.top;
}

/// Whether hit `h` can do anything at all: move along one axis, or move
/// one of its edges.
fn engageFree(h: EngageHit) bool {
    if (isDimKind(h.kind)) return true;
    const fr = engageFreedom(h);
    return if (engageMoves(h.kind)) fr.x or fr.y else anyEdge(fr.edges);
}

/// Whether hit `h` is held in part: a corner with one edge held, a move
/// along one axis only.
fn engagePartly(h: EngageHit) bool {
    if (isDimKind(h.kind)) return false;
    const fr = engageFreedom(h);
    if (engageMoves(h.kind)) return fr.x != fr.y;
    return !std.meta.eql(fr.edges, h.edges) and anyEdge(fr.edges);
}

fn edgesName(e: Edges) []const u8 {
    if (e.left and e.bottom) return "bottom-left corner";
    if (e.right and e.bottom) return "bottom-right corner";
    if (e.left and e.top) return "top-left corner";
    if (e.right and e.top) return "top-right corner";
    if (e.left) return "left edge";
    if (e.right) return "right edge";
    if (e.bottom) return "bottom edge";
    return "top edge";
}

var engage_text_buf: [160]u8 = undefined;

/// The annunciator's words for hit `h`.
fn engageText(h: EngageHit) []const u8 {
    if (isDimKind(h.kind)) {
        const c = constraintById(h.id) orelse return "";
        var b1: [120]u8 = undefined;
        var lb: [32]u8 = undefined;
        var b2: [120]u8 = undefined;
        return std.fmt.bufPrint(&engage_text_buf, "{s}: {s} from {s} · drag {s} to place it, click to pick it", .{ lengthText(&lb, @abs(c.value)), endText(&b1, c.a, null), endText(&b2, c.b, c.a.object), if (h.kind == .dim_value) "the value" else "the line" }) catch "";
    }
    const name = objectName(h.id);
    if (!engageFree(h)) {
        return std.fmt.bufPrint(&engage_text_buf, "{s}: {s} held by a constraint", .{ name, if (engageMoves(h.kind)) "position" else edgesName(h.edges) }) catch "";
    }
    if (engagePartly(h)) {
        const fr = engageFreedom(h);
        if (engageMoves(h.kind)) {
            return std.fmt.bufPrint(&engage_text_buf, "Move {s}{s}: {s} only, {s} held by a constraint", .{ name, if (h.kind == .origin) " by its origin" else "", if (fr.x) "across" else "up and down", if (fr.x) "up and down" else "across" }) catch "";
        }
        var held: Edges = .{ .left = h.edges.left and !fr.edges.left, .right = h.edges.right and !fr.edges.right, .bottom = h.edges.bottom and !fr.edges.bottom, .top = h.edges.top and !fr.edges.top };
        _ = &held;
        return std.fmt.bufPrint(&engage_text_buf, "Resize {s}: {s} ({s} only; {s} held by a constraint)", .{ name, edgesName(h.edges), edgesName(fr.edges), edgesName(held) }) catch "";
    }
    return switch (h.kind) {
        .centre => std.fmt.bufPrint(&engage_text_buf, "Move {s}", .{name}) catch "",
        .origin => std.fmt.bufPrint(&engage_text_buf, "Move {s} by its origin", .{name}) catch "",
        else => std.fmt.bufPrint(&engage_text_buf, "Resize {s}: {s}", .{ name, edgesName(h.edges) }) catch "",
    };
}

/// Tab: locks the pointer onto the nearest engagement point, then onto
/// the next (Shift+Tab: the one before). Whether there was one.
fn engageLock(back: bool) bool {
    if (engage_n == 0 and engage_lock == null) return false;
    if (engage_n == 0) return true;
    if (engage_lock == null) {
        engage_lock_index = 0;
    } else {
        engage_lock_index = if (back) (engage_lock_index + engage_n - 1) % engage_n else (engage_lock_index + 1) % engage_n;
    }
    engage_lock = engage_hits[@min(engage_lock_index, engage_n - 1)];
    engage_lock_px = dvui.currentWindow().mouse_pt;
    warpPointerTo(engage_lock.?.at);
    return true;
}

/// Puts the system pointer on canvas point `p` where the system allows it
/// (X11; not Wayland).
fn warpPointerTo(p: geom.Point) void {
    if (dvui.backend.kind != .sdl3) return;
    const c = dvui.backend.c;
    const drv = c.SDL_GetCurrentVideoDriver() orelse return;
    if (std.mem.eql(u8, std.mem.span(drv), "wayland")) return;
    const area = canvas_px orelse return;
    const q = state.view.toPx(area, p);
    const ns = dvui.windowNaturalScale();
    c.SDL_WarpMouseInWindow(dvui.currentWindow().backend.impl.window, q.x / ns, q.y / ns);
    engage_lock_px = q;
}

/// The canvas area last drawn, device pixels.
var canvas_px: ?dvui.Rect.Physical = null;

/// A press with the select tool at canvas point `at` on an engagement
/// point: a drag from it starts. Whether it was on one (one held by a
/// constraint takes the press and says so).
fn engagePress(at: geom.Point) bool {
    const h = engageTarget() orelse return false;
    if (isDimKind(h.kind)) {
        dimPress(h, at);
        return true;
    }
    if (!engageFree(h)) {
        state.status = engageText(h);
        return true;
    }
    const parent = constrain.parentOf(&state.model, h.id);
    const offset = if (parent) |pr| constrain.frameOffset(&state.model, pr) else geom.Point{ .x = 0, .y = 0 };
    const box = if (state.model.group(h.id) != null) (containerBox(h.id) orelse return false) else (constrain.boxOf(&state.model, h.id) orelse return false);
    drag_count += 1;
    engage_drag = .{ .hit = h, .box = box, .offset = offset, .pointer0 = at, .key = mergeKey(.{ "engage", drag_count }), .now = h.at };
    return true;
}

/// The drag goes on: the engaged point follows the pointer's motion from
/// where it was taken; its container moves or resizes to put it there.
fn engageMotion(at: geom.Point) void {
    const d = &(engage_drag orelse return);
    const dx = at.x - d.pointer0.x;
    const dy = at.y - d.pointer0.y;
    if (!d.moved and @sqrt(dx * dx + dy * dy) * state.view.ppm < 3) return;
    d.moved = true;
    // The point goes only where it may: a held axis keeps it in place.
    const fr0 = engageFreedom(d.hit);
    const free_x = if (engageMoves(d.hit.kind)) fr0.x else (fr0.edges.left or fr0.edges.right);
    const free_y = if (engageMoves(d.hit.kind)) fr0.y else (fr0.edges.bottom or fr0.edges.top);
    const p = snapPoint(.{ .x = d.hit.at.x + (if (free_x) dx else 0), .y = d.hit.at.y + (if (free_y) dy else 0) }, free_x, free_y);
    d.now = p;
    // The point in the container's parent's frame.
    const q: geom.Point = .{ .x = p.x - d.offset.x, .y = p.y - d.offset.y };
    const h0: geom.Point = .{ .x = d.hit.at.x - d.offset.x, .y = d.hit.at.y - d.offset.y };
    var b = d.box;
    const fr = engageFreedom(d.hit);
    if (engageMoves(d.hit.kind)) {
        // Along the free axes only: a held one stays where it is.
        const mx = if (fr.x) q.x - h0.x else 0;
        const my = if (fr.y) q.y - h0.y else 0;
        b = .{ .x0 = b.x0 + mx, .x1 = b.x1 + mx, .y0 = b.y0 + my, .y1 = b.y1 + my };
        if (state.model.group(d.hit.id) != null) {
            actM(mergeKey(.{ "moveGroupKey", d.key }), .moveGroup, .{ d.hit.id, b.x0 - groupBox0(d).x0, b.y0 - groupBox0(d).y0 }) catch {};
            return;
        }
    } else {
        const min = 1.0;
        // Edges go exactly where the point is (a midpoint moves its one
        // edge; an edge's point moves it across).
        // Only the edges its constraints leave free.
        if (fr.edges.left) b.x0 = @min(q.x, b.x1 - min);
        if (fr.edges.right) b.x1 = @max(q.x, b.x0 + min);
        if (fr.edges.bottom) b.y0 = @min(q.y, b.y1 - min);
        if (fr.edges.top) b.y1 = @max(q.y, b.y0 + min);
        // A placed figure keeps its proportions.
        if (figureProportions(d.hit.id)) |pr| b = keepFigureProportions(pr, d.box, b, fr.edges);
    }
    _ = actM(d.key, .placeObjects, .{ &[_]layout.model.ObjectId{d.hit.id}, &[_]geom.Box{b} }) catch {};
}

/// A group's box as it is now (it moves by steps, from where it was).
fn groupBox0(d: anytype) geom.Box {
    return containerBox(d.hit.id) orelse d.box;
}

/// The drag ends; a press that did not move was a click.
fn engageRelease() bool {
    const d = engage_drag orelse return false;
    engage_drag = null;
    engage_lock = null;
    return d.moved;
}

/// What engaging draws: the hovered point (a ring; an edge, thickened) and
/// the annunciator; a locked or dragged point scintillates.
fn drawEngagement(area: dvui.Rect.Physical) void {
    canvas_px = area;
    if (!engaging()) return;
    // The model changed under them (an undo, a redo, an edit): the points
    // as they are now, and a lock on one no longer there lets go.
    if (engage_drag == null and state.model.revision != engage_rev) {
        if (engage_at) |at| findEngagements(area, at) else engage_n = 0;
        engage_rev = state.model.revision;
        if (engage_lock) |l| {
            const still = for (engage_hits[0..engage_n]) |h| {
                if (h.id == l.id and h.kind == l.kind and std.meta.eql(h.edges, l.edges)) break true;
            } else false;
            if (!still) engage_lock = null;
        }
    }
    const ns = dvui.windowNaturalScale();
    if (engage_drag) |d| {
        if (!d.moved) return;
        const q = state.view.toPx(area, d.now);
        if (!sparkCursor(q, false)) {
            scintillate(q, 8 * ns);
            dvui.cursorSet(.hidden);
        }
        annunciate(area, q, engageText(d.hit));
        return;
    }
    if (dim_drag) |d| {
        if (d.moved) if (constraintById(d.id)) |c| if (dimGeom(c)) |g| annunciate(area, (struct {
            fn below(q: dvui.Point.Physical) dvui.Point.Physical {
                return .{ .x = q.x, .y = q.y + 30 * dvui.windowNaturalScale() };
            }
        }).below(state.view.toPx(area, g.d.text_at)), engageText(.{ .id = d.id, .kind = d.kind, .edges = .{}, .at = g.d.text_at, .d = 0 }));
        return;
    }
    const h = engageTarget() orelse return;
    if (isDimKind(h.kind)) {
        // The dimension draws itself highlighted (drawConstraintMarks).
        const mp = dvui.currentWindow().mouse_pt;
        annunciate(area, .{ .x = mp.x, .y = mp.y + 30 * dvui.windowNaturalScale() }, engageText(h));
        return;
    }
    const free = engageFree(h);
    const colour = if (free) colors.select else colors.overflow;
    const q = state.view.toPx(area, h.at);
    if (h.kind == .edge) {
        const b = containerBox(h.id) orelse return;
        const pts: [2]geom.Point = if (h.edges.left) .{ .{ .x = b.x0, .y = b.y0 }, .{ .x = b.x0, .y = b.y1 } } else if (h.edges.right) .{ .{ .x = b.x1, .y = b.y0 }, .{ .x = b.x1, .y = b.y1 } } else if (h.edges.bottom) .{ .{ .x = b.x0, .y = b.y0 }, .{ .x = b.x1, .y = b.y0 } } else .{ .{ .x = b.x0, .y = b.y1 }, .{ .x = b.x1, .y = b.y1 } };
        // The edge, haloed.
        haloBox(area, .{ .x0 = @min(pts[0].x, pts[1].x), .y0 = @min(pts[0].y, pts[1].y), .x1 = @max(pts[0].x, pts[1].x), .y1 = @max(pts[0].y, pts[1].y) }, colour);
    }
    if (engage_lock != null) {
        if (!sparkCursor(q, true)) scintillate(q, 8 * ns);
    } else {
        // The drag point, haloed.
        haloPoint(q, 4 * ns, colour);
        skRing(q, 6 * ns, colour, 1.5 * ns);
    }
    annunciate(area, q, engageText(h));
}


// The spark as the cursor --------------------------------------------------
//
// A point standing in for the pointer scintillates (see "Engagement
// points"). Where SDL can make an animated cursor, the spark is the
// cursor: its image holds the spark where the point is, off from the
// hotspot by the point's offset from the pointer, and the compositor plays
// it, so Graven draws nothing while it runs. Made afresh when the offset
// changes; otherwise (no animated cursors, a point too far for a cursor's
// image, or GRAVEN_DRAWN_SPARK set) the spark is drawn, redrawing the
// canvas 25 times a second.

var spark_cursor: ?*dvui.backend.c.SDL_Cursor = null;
/// One made before, to free once it is no longer the cursor.
var spark_old: ?*dvui.backend.c.SDL_Cursor = null;
var spark_key: u64 = 0;
/// Whether a spark cursor was asked for this frame.
var spark_wanted = false;
var spark_drawn_only: ?bool = null;

fn sparkColor(c: dvui.Color) spark.Color {
    return .{ .r = @as(f32, @floatFromInt(c.r)) / 255, .g = @as(f32, @floatFromInt(c.g)) / 255, .b = @as(f32, @floatFromInt(c.b)) / 255, .a = @as(f32, @floatFromInt(c.a)) / 255 };
}

/// Point `q` (device pixels) standing in for the pointer, as the cursor;
/// with `arrow`, the pointer's own arrow shows at the hotspot. Whether it
/// could be (else the caller draws the spark).
fn sparkCursor(q: dvui.Point.Physical, arrow: bool) bool {
    if (dvui.backend.kind != .sdl3) return false;
    if (spark_drawn_only == null) spark_drawn_only = platform.env("GRAVEN_DRAWN_SPARK") != null;
    if (spark_drawn_only.?) return false;
    const c = dvui.backend.c;
    const win = dvui.currentWindow();
    const m = win.mouse_pt;
    const ns = dvui.windowNaturalScale();
    // Cursor images are in the window's own (logical) pixels.
    const dx = @round((q.x - m.x) / ns);
    const dy = @round((q.y - m.y) / ns);
    const key = mergeKey(.{ @as(i32, @intFromFloat(dx)), @as(i32, @intFromFloat(dy)), arrow, @as(i32, @intFromFloat(@round(ns * 100))) });
    if (spark_cursor == null or key != spark_key) {
        const made = makeSpark(dx, dy, arrow, ns) orelse return false;
        if (spark_cursor) |old| {
            if (spark_old) |o| c.SDL_DestroyCursor(o);
            spark_old = old;
        }
        spark_cursor = made;
        spark_key = key;
    }
    spark_wanted = true;
    keepSpark();
    return true;
}

/// Makes the animated cursor for a spark `dx`, `dy` from the pointer.
fn makeSpark(dx: f32, dy: f32, arrow: bool, ns: f32) ?*dvui.backend.c.SDL_Cursor {
    const c = dvui.backend.c;
    const base: spark.Spec = .{
        .dx = dx,
        .dy = dy,
        .arrow = arrow,
        .a = sparkColor(colors.select),
        .b = sparkColor(colors.overflow),
        .ink = sparkColor(colors.ink),
        .paper = sparkColor(colors.paper),
    };
    const sz1 = spark.size(base) orelse return null;
    var hi = base;
    hi.scale = ns;
    const szh: ?spark.Size = if (ns > 1.01) spark.size(hi) else null;
    var infos: [spark.frames]c.SDL_CursorFrameInfo = undefined;
    var made: usize = 0;
    defer for (infos[0..made]) |f| c.SDL_DestroySurface(f.surface);
    for (0..spark.frames) |k| {
        const surf = sparkSurface(base, sz1, k) orelse return null;
        infos[k] = .{ .surface = surf, .duration = spark.frame_ms };
        made += 1;
        // At the screen's scale, where it is not 1.
        if (szh) |sh| if (sparkSurface(hi, sh, k)) |alt| {
            _ = c.SDL_AddSurfaceAlternateImage(surf, alt);
            c.SDL_DestroySurface(alt);
        };
    }
    return c.SDL_CreateAnimatedCursor(&infos, @intCast(made), @intCast(sz1.hot_x), @intCast(sz1.hot_y));
}

fn sparkSurface(sp: spark.Spec, sz: spark.Size, k: usize) ?*dvui.backend.c.SDL_Surface {
    const c = dvui.backend.c;
    const surf = c.SDL_CreateSurface(@intCast(sz.w), @intCast(sz.h), c.SDL_PIXELFORMAT_RGBA32) orelse return null;
    const a = dvui.currentWindow().arena();
    const buf = a.alloc(u8, sz.w * sz.h * 4) catch {
        c.SDL_DestroySurface(surf);
        return null;
    };
    spark.frame(sp, sz, k, buf);
    const pitch: usize = @intCast(surf.*.pitch);
    const dst: [*]u8 = @ptrCast(surf.*.pixels orelse {
        c.SDL_DestroySurface(surf);
        return null;
    });
    for (0..sz.h) |y| @memcpy(dst[y * pitch ..][0 .. sz.w * 4], buf[y * sz.w * 4 ..][0 .. sz.w * 4]);
    return surf;
}

/// Keeps the spark the cursor: DVUI sets the cursor only when the one asked
/// for changes, so it is asked for the one it set last (if that was "none",
/// a visible one first, then the spark again next frame).
fn keepSpark() void {
    const c = dvui.backend.c;
    const cur = spark_cursor orelse return;
    const back = dvui.currentWindow().backend.impl;
    if (back.cursor_last == .hidden) {
        dvui.cursorSet(.arrow);
        dvui.refresh(null, @src(), null);
        return;
    }
    dvui.cursorSet(back.cursor_last);
    if (c.SDL_GetCursor() != cur) _ = c.SDL_SetCursor(cur);
}

/// Once a frame, after drawing: a spark cursor not asked for this frame
/// gives way to DVUI's again, and one no longer the cursor is freed.
fn sparkFrameEnd() void {
    if (dvui.backend.kind != .sdl3) return;
    const c = dvui.backend.c;
    if (spark_old) |o| if (c.SDL_GetCursor() != o) {
        c.SDL_DestroyCursor(o);
        spark_old = null;
    };
    if (!spark_wanted) if (spark_cursor) |cur| {
        // DVUI puts its own back at the frame's end.
        dvui.currentWindow().backend.impl.cursor_last = .bad;
        if (spark_old) |o| c.SDL_DestroyCursor(o);
        spark_old = cur;
        spark_cursor = null;
        dvui.refresh(null, @src(), null);
    };
    spark_wanted = false;
}

/// A label beside canvas point `q` (device pixels): what a press there does.
fn annunciate(area: dvui.Rect.Physical, q: dvui.Point.Physical, text: []const u8) void {
    const font = dvui.Font.theme(.body).larger(-2);
    const ns = dvui.windowNaturalScale();
    var r = annotationRect(area, .{ .x = q.x + 14 * ns, .y = q.y - 6 * ns }, font, 300);
    // Its text, its padding and its border.
    r.w = font.textSize(text).w + 2 * (annotation_pad + 2) + 8;
    dvui.labelNoFmt(@src(), text, .{}, .{
        .rect = r,
        .padding = .{ .x = annotation_pad + 2, .w = annotation_pad + 2, .y = annotation_pad, .h = annotation_pad },
        .background = true,
        .color_fill = .{ .color = colors.paper.opacity(0.92) },
        .color_text = .{ .color = colors.ink },
        .border = .all(1),
        .color_border = .{ .color = colors.select.opacity(0.6) },
        .corners = .all(3),
        .font = font,
        .id_extra = 71000,
    });
}

/// A point standing in for the pointer: a ring of short rays that turns,
/// in two colours that trade places, brightening and dimming quickly, so
/// the eye finds it at once (the interface's sign for it).
fn scintillate(q: dvui.Point.Physical, r: f32) void {
    animate();
    const t: f32 = @floatCast(@as(f64, @floatFromInt(@divTrunc(dvui.frameTimeNS(), std.time.ns_per_ms))) / 1000);
    const ns = dvui.windowNaturalScale();
    const glow = spark.glow(t);
    const rays = spark.rays;
    for (0..rays) |i| {
        const ang = @as(f32, @floatFromInt(i)) * 2 * std.math.pi / rays + spark.angle(t);
        const c = @cos(ang);
        const s_ = @sin(ang);
        const inner = r * 0.75;
        const outer = r * 1.55;
        const col = if (spark.firstColour(i, t)) colors.select else colors.overflow;
        dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x + c * inner, .y = q.y + s_ * inner }, .{ .x = q.x + c * outer, .y = q.y + s_ * outer } } }, .{ .thickness = 2 * ns, .color = .{ .color = col.opacity(glow) } });
    }
    skRing(q, r * 0.55, colors.select, 1.5 * ns);
    // The exact point.
    const l: f32 = r * 0.4;
    dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x - l, .y = q.y }, .{ .x = q.x + l, .y = q.y } } }, .{ .thickness = ns, .color = .{ .color = colors.ink } });
    dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x, .y = q.y - l }, .{ .x = q.x, .y = q.y + l } } }, .{ .thickness = ns, .color = .{ .color = colors.ink } });
}

/// An action of mode `canvas.engage`: Tab locks onto the next engagement
/// point (Shift+Tab the one before), Esc lets go. Whether it was done.
fn engageAction(inv: keymap.Invocation) bool {
    switch (inv.action) {
        kact("canvas.engage.lock") => return engageLock(inv.arg == 1),
        kact("canvas.engage.release") => {
            if (engage_lock == null) return false;
            engage_lock = null;
            return true;
        },
        else => return false,
    }
}

/// The hand or lock at the pointer, over the selection.
fn drawPointerMark() void {
    const pm = pointer_mark orelse return;
    const px = dvui.windowNaturalScale();
    const size: f32 = 22 * px;
    const r: dvui.Rect.Physical = .{ .x = pm.p.x - size / 2, .y = pm.p.y - size / 2, .w = size, .h = size };
    const ink = dvui.themeGet().color(.control, .text);
    switch (pm.mark) {
        .grab => icons.drawAt(.hand, r, ink, colors.paper),
        .grabbing => icons.drawAt(.hand_grabbing, r, ink, colors.paper),
        .locked => icons.drawAt(.lock, r, ink, colors.overflow.opacity(0.5)),
        .cursor => {},
    }
}

/// The selection: a translucent box over each selected container, and
/// the lone one's resize handles.
fn drawSelection(area: dvui.Rect.Physical) void {
    if (selection.items.len == 0) return;
    const px = dvui.windowNaturalScale();
    for (selection.items) |id| {
        const b = containerBox(id) orelse continue;
        const r = state.view.rect(area, b);
        r.fill(.square, .{ .color = .{ .color = colors.select.opacity(0.14) } });
        r.stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select.opacity(0.7) } });
    }
    var hb: [8]Handle = undefined;
    for (hb[0..resizeHandles(&hb)]) |h| {
        const q = state.view.toPx(area, h.at);
        const s: f32 = 4.5 * px;
        // A selection's drag points glow, set apart from the drawing.
        if (canvas_eq == null and track_cursor == null) haloPoint(q, s, colors.select);
        const grip: dvui.Rect.Physical = .{ .x = q.x - s, .y = q.y - s, .w = 2 * s, .h = 2 * s };
        grip.fill(.square, .{ .color = .{ .color = colors.paper } });
        grip.stroke(.square, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } });
    }
}

/// The text track (one sized to a text style) whose segment `at` lies in,
/// in the shown space.
fn textTrackAt(at: geom.Point) ?struct { parent: Parent, region: usize } {
    for (0..state.model.parentCount()) |pk| {
        const pi = state.model.parentAt(pk);
        if (!shownIn(pi)) continue;
        const pl = placedOf(pi) orelse continue;
        const regions = state.model.regionsIn(pi);
        for (pl.tracks) |t| {
            if (t.member >= regions.len or regions[t.member].style == null) continue;
            if (contains(onSheet(pi, t.box), at)) return .{ .parent = pi, .region = t.member };
        }
    }
    return null;
}

/// A click with the Constrain tool: the first feature, then the second,
/// which opens the prompt.
fn constrainClick() void {
    const hit = constrain_hover orelse return;
    if (constrain_first) |first| {
        if (constrain_batch != null and first.end.feature.vertical() != hit.end.feature.vertical()) {
            state.status = if (first.end.feature.vertical()) "Pick a horizontal feature: a line, an edge, a top or bottom. " else "Pick a vertical feature: a line, an edge, a left or right. ";
            return;
        }
        if (constrain_measure) {
            constrain_measure = false;
            constrain_first = null;
            constrain_hover = null;
            state.tool = .select;
            addMeasure(first.end, hit.end);
            return;
        }
        const value = constrain.measure(&state.model, .{ .a = first.end, .b = hit.end }) orelse 0;
        const k = docUnits().perMm();
        constrain_prompt = .{ .a = first.end, .b = hit.end, .value = @round(@abs(value) * k * 10) / 10, .side = if (value < 0) -1 else 1, .batch = constrain_batch != null };
        constrain_first = null;
        constrain_hover = null;
        state.tool = .select;
        return;
    }
    if (hit.end.object == .none) return;
    constrain_batch = null;
    constrain_first = hit;
}

/// The batch's constraints, one undo step: each object's feature kept
/// `mm` from `to` (each on its own side, as measured), or each gap between
/// neighbours `mm`.
fn applyBatch(to: ConstraintEnd, mm: f64) void {
    const cb = constrain_batch orelse return;
    drag_count += 1;
    const key = mergeKey(.{ "constrain-batch", drag_count });
    var made: usize = 0;
    switch (cb.kind) {
        .edge => for (cb.ids[0..cb.n]) |id| {
            const a: ConstraintEnd = .{ .object = id, .feature = cb.feature };
            const measured = constrain.measure(&state.model, .{ .a = a, .b = to }) orelse continue;
            _ = actM(key, .addConstraint, .{.{ .a = a, .b = to, .value = mm, .side = if (measured < 0) -1 else 1 }}) catch continue;
            made += 1;
        },
        // Neighbours in order: the next one's near edge `mm` past the
        // last one's far edge (down: below its bottom).
        .gap => for (1..cb.n) |k| {
            const prev = cb.ids[k - 1];
            const next = cb.ids[k];
            const c: layout.model.Constraint = if (cb.down)
                .{ .a = .{ .object = next, .feature = .top }, .b = .{ .object = prev, .feature = .bottom }, .value = mm, .side = -1 }
            else
                .{ .a = .{ .object = next, .feature = .left }, .b = .{ .object = prev, .feature = .right }, .value = mm, .side = 1 };
            _ = actM(key, .addConstraint, .{c}) catch continue;
            made += 1;
        },
    }
    const B = struct {
        var buf: [64]u8 = undefined;
    };
    state.status = std.fmt.bufPrint(&B.buf, "{d} constraints made. ", .{made}) catch "";
}

/// The objects chosen for constraining (the selection, else the chosen
/// object), into `out`; how many.
fn chosenObjects(out: []layout.model.ObjectId) usize {
    var n: usize = 0;
    for (selection.items) |id| {
        if (n == out.len) break;
        if (constrain.boxOf(&state.model, id) == null) continue;
        out[n] = id;
        n += 1;
    }
    if (n == 0) if (objectOfContext(state.context)) |id| if (constrain.boxOf(&state.model, id) != null) {
        out[0] = id;
        n = 1;
    };
    return n;
}

/// K on chosen objects: their pop-up (equal widths and heights, gaps,
/// edges to a feature picked next). Whether there were any.
fn openObjectsMenu() bool {
    var cb: @TypeOf(constrain_batch.?) = .{};
    cb.n = chosenObjects(&cb.ids);
    if (cb.n == 0) return false;
    constrain_batch = cb;
    constrain_objects_menu = true;
    const m = dvui.currentWindow().mouse_pt;
    const ns = dvui.windowNaturalScale();
    constrain_menu_from = .{ .x = m.x / ns, .y = m.y / ns, .w = 1, .h = 1 };
    constrain_menu_frame = dvui.frameTimeNS();
    dvui.refresh(null, @src(), null);
    return true;
}

/// The objects' pop-up is open.
var constrain_objects_menu = false;

fn closeObjectsMenu() void {
    constrain_objects_menu = false;
    closeConstrainMenu();
}

fn objectsMenuClosed(_: *anyopaque, _: dvui.MenuWidget.CloseReason) void {
    closeObjectsMenu();
}

const objects_menu_ids = .{ "constrain-objects.equal-width", "constrain-objects.equal-height", "constrain-objects.gap", "constrain-objects.top", "constrain-objects.bottom", "constrain-objects.left", "constrain-objects.right", "constrain-objects.measure" };

/// The objects' pop-up: each choice with its key; those needing two or
/// more objects dimmed with one.
fn objectsMenu() void {
    if (!constrain_objects_menu) return;
    const cb = constrain_batch orelse {
        constrain_objects_menu = false;
        return;
    };
    const prev_root = dvui.MenuWidget.Root.set(.{ .ptr = @ptrCast(&constrain_objects_menu), .close = objectsMenuClosed });
    defer _ = dvui.MenuWidget.Root.set(prev_root);
    var fm = dvui.floatingMenu(@src(), .{ .from = constrain_menu_from, .style = .popup }, .{});
    defer fm.deinit();
    inline for (objects_menu_ids, 0..) |id, i| {
        const tag = uniqueTag(id);
        recordDrawn(tag, 0);
        const off = i < 3 and cb.n < 2;
        var bw: dvui.ButtonWidget = undefined;
        bw.init(@src(), .{}, .{ .expand = .horizontal, .id_extra = i, .tag = tag, .margin = .all(1), .padding = .{ .x = 8, .w = 8, .y = 3, .h = 4 } });
        bw.processEvents();
        bw.drawBackground();
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
            defer row.deinit();
            const ink = dvui.themeGet().color(.window, .text);
            dvui.labelNoFmt(@src(), comptime elements.get(id).label, .{}, .{ .padding = .all(0), .margin = .all(0), .expand = .horizontal, .color_text = if (off) .{ .color = ink.opacity(0.4) } else null });
            var kb: [24]u8 = undefined;
            if (keymap.shortcut(&kb, kmode("canvas.constrain-objects"), kact(id), 0)) |sc| dvui.labelNoFmt(@src(), sc, .{}, .{ .padding = .{ .x = 16 }, .margin = .all(0), .color_text = .{ .color = ink.opacity(0.55) } });
        }
        if (bw.clicked()) pushButtonEvent(tag, 0);
        bw.drawFocus();
        bw.deinit();
    }
}

/// Equal widths (or heights) for the chosen objects: each held equal to
/// the first, one undo step.
fn equalSizes(vertical: bool) void {
    const cb = constrain_batch orelse return;
    closeObjectsMenu();
    constrain_batch = null;
    if (cb.n < 2) {
        state.status = "Equal sizes need two or more objects chosen. ";
        return;
    }
    drag_count += 1;
    const key = mergeKey(.{ "constrain-equal", drag_count });
    const f: Feature = if (vertical) .bottom else .left;
    for (cb.ids[1..cb.n]) |id| _ = actM(key, .addConstraint, .{.{ .kind = .equal_size, .a = .{ .object = id, .feature = f }, .b = .{ .object = cb.ids[0], .feature = f } }}) catch {};
    state.status = if (vertical) "Equal heights. " else "Equal widths. ";
}

/// Gaps between the chosen objects: in order across (or down, when they
/// are stacked), the value asked for, the first gap's as it is offered.
fn gapsPrompt() void {
    var cb = constrain_batch orelse return;
    closeObjectsMenu();
    if (cb.n < 2) {
        constrain_batch = null;
        state.status = "Gaps need two or more objects chosen. ";
        return;
    }
    // Stacked when they spread further down than across.
    var lo: geom.Point = .{ .x = std.math.inf(f64), .y = std.math.inf(f64) };
    var hi: geom.Point = .{ .x = -std.math.inf(f64), .y = -std.math.inf(f64) };
    for (cb.ids[0..cb.n]) |id| {
        const b = constrain.boxOf(&state.model, id) orelse continue;
        const c: geom.Point = .{ .x = (b.x0 + b.x1) / 2, .y = (b.y0 + b.y1) / 2 };
        lo = .{ .x = @min(lo.x, c.x), .y = @min(lo.y, c.y) };
        hi = .{ .x = @max(hi.x, c.x), .y = @max(hi.y, c.y) };
    }
    cb.down = hi.y - lo.y > hi.x - lo.x;
    cb.kind = .gap;
    const Ctx = struct { down: bool };
    const order = struct {
        fn lt(cx: Ctx, x: layout.model.ObjectId, y: layout.model.ObjectId) bool {
            const bx = constrain.boxOf(&state.model, x).?;
            const by = constrain.boxOf(&state.model, y).?;
            return if (cx.down) bx.y1 > by.y1 else bx.x0 < by.x0;
        }
    }.lt;
    std.mem.sort(layout.model.ObjectId, cb.ids[0..cb.n], Ctx{ .down = cb.down }, order);
    constrain_batch = cb;
    const b0 = constrain.boxOf(&state.model, cb.ids[0]).?;
    const b1 = constrain.boxOf(&state.model, cb.ids[1]).?;
    const gap = if (cb.down) b0.y0 - b1.y1 else b1.x0 - b0.x1;
    const k = docUnits().perMm();
    constrain_prompt = .{ .a = .{ .object = cb.ids[1], .feature = if (cb.down) .top else .left }, .b = .{ .object = cb.ids[0], .feature = if (cb.down) .bottom else .right }, .value = @round(@abs(gap) * k * 10) / 10, .batch = true };
}

/// Each chosen object's `f` kept to a feature: the next click picks it.
fn edgesPick(f: Feature) void {
    var cb = constrain_batch orelse return;
    closeObjectsMenu();
    cb.kind = .edge;
    cb.feature = f;
    constrain_batch = cb;
    const id = cb.ids[0];
    const parent = constrain.parentOf(&state.model, id) orelse return;
    const b = offsetBox(constrain.boxOf(&state.model, id) orelse return, constrain.frameOffset(&state.model, parent));
    const p0: geom.Point, const p1: geom.Point = switch (f) {
        .top => .{ .{ .x = b.x0, .y = b.y1 }, .{ .x = b.x1, .y = b.y1 } },
        .bottom => .{ .{ .x = b.x0, .y = b.y0 }, .{ .x = b.x1, .y = b.y0 } },
        .left => .{ .{ .x = b.x0, .y = b.y0 }, .{ .x = b.x0, .y = b.y1 } },
        else => .{ .{ .x = b.x1, .y = b.y0 }, .{ .x = b.x1, .y = b.y1 } },
    };
    state.tool = .constrain;
    constrain_first = .{ .end = .{ .object = id, .feature = f }, .parent = parent, .p0 = p0, .p1 = p1 };
    state.status = if (f.vertical()) "Click what their edges keep to: a horizontal line, an edge, a top or bottom. " else "Click what their edges keep to: a vertical line, an edge, a left or right. ";
}

/// A constraint just added that contradicts what holds is kept as a
/// reference dimension instead (in the same undo step): it shows what is
/// there, and moves nothing.
fn keepOrMeasure(key: u64, id: layout.model.ObjectId) void {
    const issues = constrain.check(&state.model, state.gpa) catch return;
    defer state.gpa.free(issues);
    for (issues) |i| if (i.constraint == id and (i.kind == .conflict or i.kind == .inverted)) {
        _ = actM(key, .setConstraintDriving, .{ id, false, 0.0, 1.0 }) catch return;
        state.status = "That contradicts the constraints already there: kept as a reference dimension (in parentheses). ";
        return;
    };
}

/// A reference dimension made between two picks (M): what they measure,
/// shown, never driving.
fn addMeasure(a: ConstraintEnd, b: ConstraintEnd) void {
    const measured = constrain.measure(&state.model, .{ .a = a, .b = b }) orelse {
        state.status = "Those two cannot be measured. ";
        return;
    };
    _ = act(.addConstraint, .{.{ .a = a, .b = b, .value = @abs(measured), .side = if (measured < 0) -1 else 1, .driving = false }}) catch {
        state.status = "That dimension could not be added. ";
        return;
    };
    state.status = "Reference dimension: it follows what it measures. ";
}

/// The Constrain tool's next two picks make a reference dimension.
var constrain_measure = false;

fn featureName(f: Feature) []const u8 {
    return switch (f) {
        .left => "left edge",
        .right => "right edge",
        .centre_x => "centre",
        .origin_x => "origin",
        .bottom => "bottom edge",
        .top => "top edge",
        .centre_y => "middle",
        .origin_y => "origin",
        .baseline => "first baseline",
    };
}

fn isControlPoint(id: layout.model.ObjectId) bool {
    for (0..state.model.parentCount()) |k| for (state.model.regionsIn(state.model.parentAt(k))) |r| for (r.path.items) |cp| if (cp.id == id) return true;
    return false;
}

/// An object's name, as the tree shows it, or "the panel"/"the canvas"
/// for a parent.
fn objectName(id: layout.model.ObjectId) []const u8 {
    const m = &state.model;
    if (id == .none) return "the parent";
    for (m.spaces.items) |sp| {
        if (sp.id == id) return sp.name;
        for (sp.regions.items) |r| {
            if (r.id == id) return r.name;
            for (r.path.items, 0..) |cp, k| if (cp.id == id)
                return std.fmt.allocPrint(dvui.currentWindow().arena(), "{s} path point {d}", .{ r.name, k + 1 }) catch r.name;
        }
    }
    for (m.panels.items) |p| {
        if (p.id == id) return p.name;
        for (p.regions.items) |r| {
            if (r.id == id) return r.name;
            for (r.path.items, 0..) |cp, k| if (cp.id == id)
                return std.fmt.allocPrint(dvui.currentWindow().arena(), "{s} path point {d}", .{ r.name, k + 1 }) catch r.name;
        }
        for (p.art.items) |x| if (x.id == id) return x.name;
    }
    for (m.spaces.items) |s| {
        for (s.images.items) |im| if (im.id == id) return im.name;
        for (s.guides.items, 0..) |g, k| if (g.id == id) return if (g.name.len > 0) g.name else std.fmt.allocPrint(dvui.currentWindow().arena(), "construction line {d}", .{k + 1}) catch "a construction line";
        for (s.figure_places.items) |fp| if (fp.id == id) return fp.name;
    }
    return "(removed)";
}

/// "the right edge of Panel 1", or of "itself" when it is `self`.
fn endText(buf: []u8, end: ConstraintEnd, self: ?layout.model.ObjectId) []const u8 {
    if (end.object == .none) return std.fmt.bufPrint(buf, "the parent's {s}", .{featureName(end.feature)}) catch "";
    if (self != null and end.object == self.?) return std.fmt.bufPrint(buf, "its {s}", .{featureName(end.feature)}) catch "";
    return std.fmt.bufPrint(buf, "{s}'s {s}", .{ objectName(end.object), featureName(end.feature) }) catch "";
}

/// The prompt after the second pick: the relation, and its value.
fn constrainPromptWindow() void {
    const saved_group = pushGroup("dialog.constrain");
    defer popGroup(saved_group);
    const pr = &(constrain_prompt orelse return);
    const c = region_rect;
    if (c.w <= 0 or c.h <= 0) return;
    const w: f32 = 470;
    const h: f32 = 215;
    var r: dvui.Rect = .{ .x = c.x + (c.w - w) / 2, .y = c.y + 40, .w = w, .h = h };
    var fw = dvui.floatingWindow(@src(), .{ .rect = &r, .resize = .none }, overlayOptions(13));
    defer fw.deinit();
    var body = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .both, .padding = .all(12) });
    defer body.deinit();
    dvui.labelNoFmt(@src(), "Constrain", .{}, .{ .font = dvui.Font.theme(.heading) });
    var b1: [120]u8 = undefined;
    var b2: [120]u8 = undefined;
    if (pr.batch) if (constrain_batch) |cb| {
        if (cb.kind == .gap)
            dvui.label(@src(), "The {d} gaps between {d} objects, {s}", .{ cb.n - 1, cb.n, if (cb.down) "down" else "across" }, .{ .font = dvui.Font.theme(.body).larger(-1), .margin = .{ .y = 4 } })
        else
            dvui.label(@src(), "Each of {d} objects' {s}, against {s}", .{ cb.n, featureName(cb.feature), endText(&b2, pr.b, null) }, .{ .font = dvui.Font.theme(.body).larger(-1), .margin = .{ .y = 4 } });
    } else dvui.label(@src(), "{s}, against {s}", .{ endText(&b1, pr.a, null), endText(&b2, pr.b, pr.a.object) }, .{ .font = dvui.Font.theme(.body).larger(-1), .margin = .{ .y = 4 } });
    var go = false;
    var cancel = false;
    for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => go = true,
            kact("dialog.cancel") => cancel = true,
            else => continue,
        }
        e.handle(@src(), fw.data());
    }
    const two_objects = pr.b.object != pr.a.object;
    if (!pr.batch) {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
        defer row.deinit();
        propName("Relation");
        const names = [_][]const u8{ "Distance between them", "Size difference" };
        var choice: usize = if (pr.equal) 1 else 0;
        if (tdropdown(@src(), names[0..if (two_objects) 2 else 1], .{ .choice = &choice }, .{}, .{ .expand = .horizontal })) {
            pr.equal = choice == 1;
            const k = docUnits().perMm();
            const measured = constrain.measure(&state.model, .{ .kind = if (pr.equal) .equal_size else .offset, .a = pr.a, .b = pr.b }) orelse 0;
            pr.value = if (pr.equal) 0 else @round(@abs(measured) * k * 10) / 10;
            pr.side = if (measured < 0) -1 else 1;
        }
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        defer row.deinit();
        var nb: [32]u8 = undefined;
        propName(std.fmt.bufPrint(&nb, "Value, {s}", .{docUnits().symbol()}) catch "Value");
        var twd: dvui.WidgetData = undefined;
        const te = dvui.textEntryNumber(@src(), f64, .{ .value = &pr.value, .min = 0, .max = 100000 }, .{ .expand = .horizontal, .data_out = &twd });
        if (pr.new) {
            dvui.focusSubwindow(fw.data().id, null);
            dvui.focusWidget(twd.id, fw.data().id, null);
            pr.new = false;
        }
        if (te.enter_pressed) go = true;
    }
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_x = 1, .margin = .{ .y = 8 } });
        defer row.deinit();
        keyButton(@src(), "Cancel", 0, .{});
        keyButton(@src(), "Apply", 0, .{});
        // Its buttons as Enter and Esc: the answer pressed.
        if (dialogAnswered(kact("dialog.confirm"))) go = true;
        if (dialogAnswered(kact("dialog.cancel"))) cancel = true;
    }
    if (cancel) {
        constrain_prompt = null;
        constrain_batch = null;
        dvui.refresh(null, @src(), null);
        return;
    }
    if (!go) return;
    const value_mm = pr.value / docUnits().perMm();
    if (pr.batch) {
        applyBatch(pr.b, @abs(value_mm));
        constrain_prompt = null;
        constrain_batch = null;
        // The keyboard back on the canvas (the prompt's window had it).
        const main_sw = dvui.currentWindow().data().id;
        dvui.focusSubwindow(main_sw, null);
        if (canvas_id) |id| dvui.focusWidget(id, main_sw, null);
        dvui.refresh(null, @src(), null);
        return;
    }
    drag_count += 1;
    const add_key = mergeKey(.{ "constrain-add", drag_count });
    if (actM(add_key, .addConstraint, .{.{ .kind = if (pr.equal) .equal_size else .offset, .a = pr.a, .b = pr.b, .value = @abs(value_mm), .side = pr.side }})) |new_id| {
        keepOrMeasure(add_key, new_id);
    } else |_| {
        state.status = "That constraint could not be added. ";
    }
    constrain_prompt = null;
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
    dvui.refresh(null, @src(), null);
}

/// The constraints of the shown space as dimension glyphs, the features
/// under the pointer and picked, and the context object's origin.

// Stroke text ----------------------------------------------------------------
//
// Dimension values and constraint marks are drawn in the stroke font
// (geom.strokefont): polylines, turned to any angle, drawn each frame.

const strokefont = geom.strokefont;

/// The cap height of dimension text, logical pixels.
const dim_cap: f32 = 9;

const StrokeInk = struct {
    colour: dvui.Color,
    thick: f32,

    fn emit(k: StrokeInk, pts: []const geom.Point) void {
        var buf: [strokefont.max_points]dvui.Point.Physical = undefined;
        for (pts, 0..) |q, i| buf[i] = .{ .x = @floatCast(q.x), .y = @floatCast(q.y) };
        dvui.Path.stroke(.{ .points = buf[0..pts.len] }, .{ .thickness = k.thick, .color = .{ .color = k.colour } });
    }
};

/// Draws `text` as placed by `p` (device pixels, y down).
fn strokeText(text: []const u8, p: strokefont.Place, colour: dvui.Color) void {
    strokefont.strokes(text, p, StrokeInk{ .colour = colour, .thick = dvui.windowNaturalScale() }, StrokeInk.emit);
}

/// Text along the screen line from `a` to `b`, upright (it never reads
/// upside down), its middle at `t` of the way, standing clear of the line.
fn alongPlace(a: dvui.Point.Physical, b: dvui.Point.Physical, t: f32) strokefont.Place {
    var angle = std.math.atan2(b.y - a.y, b.x - a.x);
    // Upright: turned no more than a quarter either way (a vertical line
    // reads upward, as drawings do).
    if (@cos(angle) < -1e-3 or (@abs(@cos(angle)) <= 1e-3 and @sin(angle) > 0)) angle += std.math.pi;
    return .{
        .at = .{ .x = a.x + (b.x - a.x) * t, .y = a.y + (b.y - a.y) * t },
        .size = dim_cap * dvui.windowNaturalScale(),
        .angle = angle,
        .y_down = true,
        .align_x = 0.5,
        .align_y = -0.45,
    };
}

// Constraint dimensions ------------------------------------------------------
//
// An offset constraint is drawn as a dimension: a line from the
// reference's feature to the constrained one, its ends ticked, its value
// beside it. Where it is drawn is the constraint's own (`place`, in the
// model, so it is kept, undone and saved): the line `across` mm from the
// middle of the constrained object, the value `along` of its way. Both
// can be dragged (the line sideways; the value along the line and, with
// it, the line); a click selects the constraint, Delete removes it.

/// A layout dimension as drawn: what it measures and its drafting
/// geometry (workspace mm, `graven_constraint.dimension`), and whether its
/// features coincide on screen (an alignment, drawn as a double bar).
const DimGeom = struct { ms: cdim.Measure, d: cdim.Drawn, aligned: bool };

fn dimGeom(c: layout.model.Constraint) ?DimGeom {
    const m = &state.model;
    const parent = constrain.parentOf(m, c.a.object) orelse return null;
    if (constrain.spaceOf(m, parent) != shown_space) return null;
    const ms = constrain.dimensionOf(m, c) orelse return null;
    var tb: [32]u8 = undefined;
    const px = dvui.windowNaturalScale();
    const w = strokefont.width(dimText(&tb, c)) * dim_cap * px;
    const d = cdim.linear(ms, c.place, cdim.Style.screen(state.view.ppm / px, w / px));
    const span = @abs((ms.p1.x - ms.p0.x) * ms.dir.x + (ms.p1.y - ms.p0.y) * ms.dir.y);
    return .{ .ms = ms, .d = d, .aligned = span * state.view.ppm < 2 };
}

/// The constraint picked by a click on its dimension, while it is.
var picked_constraint: ?layout.model.ObjectId = null;

/// A drag of a dimension: which, the part taken, its place at the start,
/// where the pointer was and the dimension's length then (canvas mm).
var dim_drag: ?struct {
    id: layout.model.ObjectId,
    kind: EngageKind,
    place: layout.model.ConstraintPlace,
    pointer0: geom.Point,
    /// What it measures (placing it moves nothing).
    g: DimGeom,
    moved: bool = false,
    key: u64,
} = null;

/// A dimension's value as drawn, in the document's units.
/// A reference dimension's in parentheses: what the geometry measures.
fn dimText(buf: []u8, c: layout.model.Constraint) []const u8 {
    const v = @round(constrain.shownValue(&state.model, c) * docUnits().perMm() * 100) / 100;
    return (if (c.driving) std.fmt.bufPrint(buf, "{d}", .{v}) else std.fmt.bufPrint(buf, "({d})", .{v})) catch "";
}

/// Where a dimension's value is drawn: on its line, upright (device
/// pixels).
fn dimTextPlace(area: dvui.Rect.Physical, g: DimGeom) strokefont.Place {
    const d = g.d;
    const q0 = state.view.toPx(area, d.text_at);
    const q1 = state.view.toPx(area, .{ .x = d.text_at.x + d.text_dir.x, .y = d.text_at.y + d.text_dir.y });
    var p = alongPlace(q0, q1, 0);
    p.at = .{ .x = q0.x, .y = q0.y };
    return p;
}

fn constraintById(id: layout.model.ObjectId) ?layout.model.Constraint {
    for (state.model.constraints.items) |c| if (c.id == id) return c;
    return null;
}

/// Distance from `q` to segment `a`–`b`, device pixels.
fn segDistPx(q: dvui.Point.Physical, a: dvui.Point.Physical, b: dvui.Point.Physical) f32 {
    const vx = b.x - a.x;
    const vy = b.y - a.y;
    const len2 = vx * vx + vy * vy;
    const t = if (len2 > 0) std.math.clamp(((q.x - a.x) * vx + (q.y - a.y) * vy) / len2, 0, 1) else 0;
    const dx = a.x + t * vx - q.x;
    const dy = a.y + t * vy - q.y;
    return @sqrt(dx * dx + dy * dy);
}

/// Starts a drag of dimension hit `h`.
fn dimPress(h: EngageHit, at: geom.Point) void {
    const c = constraintById(h.id) orelse return;
    const g = dimGeom(c) orelse return;
    drag_count += 1;
    dim_drag = .{ .id = h.id, .kind = h.kind, .place = c.place, .pointer0 = at, .g = g, .key = mergeKey(.{ "dim", drag_count }) };
}

/// The dimension follows the pointer: the line sideways; the value along
/// the line, and the line with it.
fn dimMotion(at: geom.Point) void {
    const d = &(dim_drag orelse return);
    const dx = at.x - d.pointer0.x;
    const dy = at.y - d.pointer0.y;
    if (!d.moved and @sqrt(dx * dx + dy * dy) * state.view.ppm < 3) return;
    d.moved = true;
    // The line through the pointer; the value, taken, at it along the line.
    const place = cdim.withinReach(d.g.ms, if (d.kind == .dim_value) cdim.textAt(d.g.ms, d.place, at) else cdim.offsetThrough(d.g.ms, d.place, at), dimReach());
    _ = actM(d.key, .setConstraintPlace, .{ d.id, place }) catch {};
}

/// How far a dimension may be dragged from what it measures, mm: 12 mm,
/// or 90 points on screen when zoomed far out.
fn dimReach() f64 {
    return @max(12.0, 90.0 * @as(f64, dvui.windowNaturalScale()) / @as(f64, state.view.ppm));
}

/// The drag ends; one that did not move picks the constraint. Whether
/// there was one.
fn dimRelease() bool {
    const d = dim_drag orelse return false;
    dim_drag = null;
    if (!d.moved) {
        picked_constraint = d.id;
        selection.clearRetainingCapacity();
        track_cursor = null;
        state.status = "Constraint picked: drag its line or value to place it; Delete removes it. ";
    }
    return true;
}

/// The picked constraint, in the properties: what it holds, its value,
/// its place reset, its removal.
fn pickedConstraintProperties() bool {
    const saved_group = pushGroup("constraint");
    defer popGroup(saved_group);
    const id = picked_constraint orelse return false;
    const c = constraintById(id) orelse {
        picked_constraint = null;
        return false;
    };
    heading("Constraint", .{}, 9580);
    var b1: [120]u8 = undefined;
    var b2: [120]u8 = undefined;
    var b3: [260]u8 = undefined;
    const what = if (c.kind == .equal_size)
        std.fmt.bufPrint(&b3, "{s} size − {s}", .{ endText(&b1, c.a, null), endText(&b2, c.b, c.a.object) }) catch ""
    else
        std.fmt.bufPrint(&b3, "{s} from {s}", .{ endText(&b1, c.a, null), endText(&b2, c.b, c.a.object) }) catch "";
    dvui.labelNoFmt(@src(), what, .{}, .{ .expand = .horizontal, .font = dvui.Font.theme(.body).larger(-1), .id_extra = 9581 });
    const k = docUnits().perMm();
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        defer row.deinit();
        propName("Value");
        if (c.driving) {
            const v0 = @round(c.value * k * 1000) / 1000;
            accepted.label_unit = if (k == 1) .mm else .in;
            if (accepted.numberField(@src(), f64, v0, -100000, 100000, .{ .min_size_content = .{ .w = 60 }, .max_size_content = .{ .w = 70, .h = 100 }, .gravity_y = 0.5, .id_extra = 9582 })) |v| setConstraintValue(c.id, v / k);
        } else {
            var vb: [32]u8 = undefined;
            dvui.labelNoFmt(@src(), dimText(&vb, c), .{}, .{ .gravity_y = 0.5, .id_extra = 9583 });
        }
    }
    propText("Kind", "{s}", .{if (c.driving) "Driving: it sets where things are" else "Reference: it reports, and moves nothing"}, 9584);
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
        defer row.deinit();
        keyButton(@src(), "Driving or reference", 0, .{});
        keyButton(@src(), "Place it as at first", 0, .{});
        keyButton(@src(), "Remove", 0, .{});
    }
    return true;
}

/// "Column1's left edge from construction line 1, 20", a constraint in a
/// line; "Abandoned: …" when an object it names is gone.
fn constraintText(buf: []u8, c: layout.model.Constraint) []const u8 {
    var b1: [120]u8 = undefined;
    var b2: [120]u8 = undefined;
    var vb: [32]u8 = undefined;
    const gone = constrain.abandoned(&state.model, c);
    const rel = if (c.kind == .equal_size) "size equal to" else "from";
    const what = if (c.kind == .equal_size) std.fmt.bufPrint(&b2, "{s}'s", .{objectName(c.b.object)}) catch "" else endText(&b2, c.b, c.a.object);
    return std.fmt.bufPrint(buf, "{s}{s} {s} {s}{s}{s}", .{
        if (gone) "Abandoned: " else "",
        if (c.kind == .equal_size) objectName(c.a.object) else endText(&b1, c.a, null),
        rel,
        what,
        if (c.kind == .equal_size) "" else ", ",
        if (c.kind == .equal_size or gone) "" else dimText(&vb, c),
    }) catch "";
}

/// The document's constraints: how many, the abandoned ones (an object
/// they name was removed) removed together, each listed to choose.
fn constraintsProperties() void {
    const saved_group = pushGroup("constraints-list");
    defer popGroup(saved_group);
    const m = &state.model;
    var gone: usize = 0;
    for (m.constraints.items) |c| if (constrain.abandoned(m, c)) {
        gone += 1;
    };
    propText("Constraints", "{d}", .{m.constraints.items.len}, 9650);
    propText("Abandoned", "{d}", .{gone}, 9651);
    if (gone > 0) keyButton(@src(), "Remove abandoned", 0, .{});
    for (m.constraints.items, 0..) |c, ci| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = ci, .margin = .{ .y = 2 } });
        defer row.deinit();
        if (icons.button(@src(), .trash, "Remove this constraint", .{ .id_extra = ci, .size = 14, .opts = .{ .gravity_y = 0.5 } })) {
            act(.removeConstraint, .{c.id}) catch {};
            return;
        }
        var b: [300]u8 = undefined;
        const flagged = constrain.abandoned(m, c) or constraintIssue(c.id) != null;
        if (dvui.labelClick(@src(), "{s}", .{constraintText(&b, c)}, .{}, .{ .expand = .horizontal, .gravity_y = 0.5, .font = dvui.Font.theme(.body).larger(-2), .color_text = if (flagged) .{ .color = colors.overflow } else null, .id_extra = ci })) {
            state.context = .{ .constraint = c.id };
            picked_constraint = c.id;
        }
    }
}

/// Every abandoned constraint removed: one step.
fn removeAbandoned() void {
    const m = &state.model;
    var ids: std.ArrayList(layout.model.ObjectId) = .empty;
    defer ids.deinit(state.gpa);
    for (m.constraints.items) |c| if (constrain.abandoned(m, c)) ids.append(state.gpa, c.id) catch return;
    hist.beginStep();
    for (ids.items) |id| _ = hist.join(m, .removeConstraint, .{id}) catch {};
    if (picked_constraint) |p| if (constraintById(p) == null) {
        picked_constraint = null;
    };
    state.status = "Abandoned constraints removed. ";
}

/// Constraint `id` made a reference, or driving at what it measures now
/// (so nothing moves).
fn toggleDriving(id: layout.model.ObjectId) void {
    const c = constraintById(id) orelse return;
    if (c.driving) {
        _ = act(.setConstraintDriving, .{ id, false, 0.0, 1.0 }) catch {};
        state.status = "A reference dimension now: it follows what it measures. ";
        return;
    }
    const measured = constrain.measure(&state.model, c) orelse return;
    _ = act(.setConstraintDriving, .{ id, true, @abs(measured), @as(f64, if (measured < 0) -1 else 1) }) catch {};
    state.status = "Driving now: it holds what it measured. ";
}

/// A constraint's value as typed: never negative (its side stays as it
/// was made).
fn setConstraintValue(id: layout.model.ObjectId, mm: f64) void {
    if (mm < 0) {
        state.status = "A distance is never negative: the side is kept as drawn. ";
        return;
    }
    _ = act(.setConstraintValue, .{ id, mm }) catch {};
}

/// The Constraints layer: space `space`'s constraints, as dimensions and
/// equal marks.
fn drawConstraintsLayer(area: dvui.Rect.Physical, space: usize) void {
    const m = &state.model;
    const px = dvui.windowNaturalScale();
    for (m.constraints.items) |c| {
        const parent = constrain.parentOf(m, c.a.object) orelse continue;
        if (constrain.spaceOf(m, parent) != space) continue;
        const off = constrain.frameOffset(m, parent);
        const hot = (picked_constraint != null and picked_constraint.? == c.id) or (if (engageTarget()) |h| isDimKind(h.kind) and h.id == c.id else false) or (dim_drag != null and dim_drag.?.id == c.id);
        const lit = if (constraintIssue(c.id) != null) colors.overflow else if (hot) colors.select else colors.guide;
        // A reference dimension: quieter, it only reports.
        const colour = if (c.driving or hot) lit else lit.opacity(0.6);
        const ink: dvui.ColorOrGradient = .{ .color = colour };
        const v = c.a.feature.vertical();
        _ = off;
        switch (c.kind) {
            .offset => {
                const g = dimGeom(c) orelse continue;
                if (g.aligned) {
                    // Aligned: a small double bar across the shared line.
                    const q0 = state.view.toPx(area, g.d.ends[0]);
                    const t: f32 = 4 * px;
                    for ([_]f32{ -2, 2 }) |d| {
                        const pts: [2]dvui.Point.Physical = if (v) .{ .{ .x = q0.x + d * px, .y = q0.y - t }, .{ .x = q0.x + d * px, .y = q0.y + t } } else .{ .{ .x = q0.x - t, .y = q0.y + d * px }, .{ .x = q0.x + t, .y = q0.y + d * px } };
                        dvui.Path.stroke(.{ .points = &pts }, .{ .thickness = px, .color = ink });
                    }
                    continue;
                }
                var buf: [32]u8 = undefined;
                drawDimension(area, .{ .x = 0, .y = 0 }, g.ms, c.place, dimText(&buf, c), colour, hot);
            },
            .equal_size => {
                // "=" on each object's extent.
                const eoff = constrain.frameOffset(m, parent);
                for ([_]layout.model.ObjectId{ c.a.object, c.b.object }) |id| {
                    if (id == .none) continue;
                    const b = offsetBox(constrain.boxOf(m, id) orelse continue, eoff);
                    const at: geom.Point = if (v) .{ .x = b.x1, .y = (b.y0 + b.y1) / 2 } else .{ .x = (b.x0 + b.x1) / 2, .y = b.y1 };
                    const q = state.view.toPx(area, at);
                    strokeText("=", .{ .at = .{ .x = q.x + 3 * px, .y = q.y + 2 * px }, .size = dim_cap * px, .y_down = true, .align_y = 1 }, colour);
                }
            },
        }
    }
}

/// The constraint marks of the view being worked in: the context object's
/// origin and, while constraining, the picks.
fn drawConstraintMarks(area: dvui.Rect.Physical) void {
    const m = &state.model;
    const px = dvui.windowNaturalScale();
    // The context object's origin: a ring with a cross (not while text is
    // typed: `quietText`).
    if (!quietText()) if (contextObject()) |id| if (constrain.parentOf(m, id)) |parent| if (constrain.originOf(m, id)) |o| {
        const off = constrain.frameOffset(m, parent);
        const q = state.view.toPx(area, .{ .x = o.x + off.x, .y = o.y + off.y });
        const r: f32 = 5 * px;
        var ring: [17]dvui.Point.Physical = undefined;
        for (&ring, 0..) |*p, k| {
            const t = @as(f32, @floatFromInt(k)) / 16.0 * 2 * std.math.pi;
            p.* = .{ .x = q.x + r * @cos(t), .y = q.y + r * @sin(t) };
        }
        const ink: dvui.ColorOrGradient = .{ .color = colors.guide };
        dvui.Path.stroke(.{ .points = &ring }, .{ .thickness = 1.5 * px, .color = ink });
        dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x - 2 * r, .y = q.y }, .{ .x = q.x + 2 * r, .y = q.y } } }, .{ .thickness = px, .color = ink });
        dvui.Path.stroke(.{ .points = &.{ .{ .x = q.x, .y = q.y - 2 * r }, .{ .x = q.x, .y = q.y + 2 * r } } }, .{ .thickness = px, .color = ink });
    };
    drawLayFlash(area);
    // While constraining: the first pick, and what is under the pointer.
    if (state.tool == .constrain) {
        if (constrain_first) |f| strokeFeature(area, f, colors.guide, 3);
        if (constrain_hover) |h| strokeFeature(area, h, colors.select, 2.5);
    }
}

fn strokeFeature(area: dvui.Rect.Physical, h: FeatureHit, colour: dvui.Color, width: f32) void {
    const px = dvui.windowNaturalScale();
    dvui.Path.stroke(.{ .points = &.{ state.view.toPx(area, h.p0), state.view.toPx(area, h.p1) } }, .{ .thickness = width * px, .color = .{ .color = colour } });
}

/// A constraint's end picked in Properties, shown on the canvas while the
/// context object stays the same.
var lay_flash: ?struct { context: layout.model.ObjectId, c: layout.model.ObjectId, end: usize } = null;

fn layConstraintIcon(c: layout.model.Constraint) icons.GIcon {
    if (c.kind == .equal_size) return .con_equal;
    if (c.driving and c.value == 0) return .con_coincident;
    return if (c.a.feature.vertical()) .con_distance_y else .con_distance_x;
}

/// Showing (or no longer showing) one end of a container's constraint.
fn layFlashEnd(arg: i32) void {
    const id = contextObject() orelse return;
    const ci: usize = @intCast(@divTrunc(arg, 2));
    const e: usize = @intCast(@mod(arg, 2));
    if (ci >= state.model.constraints.items.len) return;
    const cid = state.model.constraints.items[ci].id;
    if (lay_flash) |f| if (f.c == cid and f.end == e) {
        lay_flash = null;
        return;
    };
    lay_flash = .{ .context = id, .c = cid, .end = e };
}

/// The picked constraint end, drawn: a feature's line across its object
/// (or its parent), or for a size the object's box.
fn drawLayFlash(area: dvui.Rect.Physical) void {
    const f = lay_flash orelse return;
    const m = &state.model;
    const c = for (m.constraints.items) |x| {
        if (x.id == f.c) break x;
    } else return;
    const end = if (f.end == 0) c.a else c.b;
    const other = if (f.end == 0) c.b else c.a;
    const parent = constrain.parentOf(m, if (end.object != .none) end.object else other.object) orelse return;
    const off = constrain.frameOffset(m, parent);
    const far = 1e5;
    const box: geom.Box = if (end.object != .none)
        offsetBox(constrain.boxOf(m, end.object) orelse return, off)
    else if (parent == .panel) offsetBox(m.panels.items[parent.panel].box(), off) else .{ .x0 = -far, .x1 = far, .y0 = -far, .y1 = far };
    const px = dvui.windowNaturalScale();
    if (c.kind == .equal_size) {
        const pts = [_]geom.Point{ .{ .x = box.x0, .y = box.y0 }, .{ .x = box.x1, .y = box.y0 }, .{ .x = box.x1, .y = box.y1 }, .{ .x = box.x0, .y = box.y1 }, .{ .x = box.x0, .y = box.y0 } };
        var q: [5]dvui.Point.Physical = undefined;
        for (pts, &q) |p, *o| o.* = state.view.toPx(area, p);
        dvui.Path.stroke(.{ .points = &q }, .{ .thickness = 8 * px, .color = .{ .color = flash_colour.opacity(0.35) } });
        dvui.Path.stroke(.{ .points = &q }, .{ .thickness = 2.5 * px, .color = .{ .color = flash_colour } });
        return;
    }
    const pos = (constrain.featureAt(m, parent, end) orelse return) + if (end.feature.vertical()) off.y else off.x;
    const line = featureLine(end.feature, pos, box);
    const h: FeatureHit = .{ .end = end, .parent = parent, .p0 = line[0], .p1 = line[1] };
    strokeFeature(area, h, flash_colour.opacity(0.35), 9);
    strokeFeature(area, h, flash_colour, 3);
}

/// The context object's origin and constraints, below its properties.
fn constraintProperties() void {
    const saved_group = pushGroup("constraints");
    defer popGroup(saved_group);
    const id = contextObject() orelse return;
    const m = &state.model;
    heading("Constraints", .{}, 9600);
    originPicker(id);
    var any = false;
    const k = docUnits().perMm();
    if (lay_flash) |f| if (f.context != id) {
        lay_flash = null;
    };
    for (m.constraints.items, 0..) |c, ci| {
        if (c.a.object != id and c.b.object != id) continue;
        any = true;
        const flagged = constraintIssue(c.id);
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{
            .expand = .horizontal,
            .id_extra = ci,
            .margin = .{ .y = 1 },
            .background = flagged != null,
            .color_fill = if (flagged != null) .{ .color = colors.overflow.opacity(0.18) } else null,
            .corners = .all(4),
        });
        defer row.deinit();
        var b1: [120]u8 = undefined;
        var b2: [120]u8 = undefined;
        var b3: [260]u8 = undefined;
        const what = if (c.kind == .equal_size)
            std.fmt.bufPrint(&b3, "Equal size: {s} − {s}", .{ endText(&b1, c.a, id), endText(&b2, c.b, c.a.object) }) catch ""
        else
            std.fmt.bufPrint(&b3, "{s} from {s}", .{ endText(&b1, c.a, id), endText(&b2, c.b, c.a.object) }) catch "";
        const pad: dvui.Rect = .all(2);
        keyIcon(@src(), "Constraint", icons.gravenAny(layConstraintIcon(c)) orelse dvui.entypo.link, @intCast(ci), .{ .id_extra = 0, .gravity_y = 0.5, .padding = pad, .min_size_content = .{ .w = 22, .h = 22 }, .label = .{ .text = what } });
        for ([2]ConstraintEnd{ c.a, c.b }, 0..) |e, ei| {
            const on = if (lay_flash) |f| f.c == c.id and f.end == ei else false;
            var nb: [120]u8 = undefined;
            const tip = if (c.kind == .equal_size) (std.fmt.bufPrint(&nb, "{s} size", .{if (e.object == .none) "The parent's" else objectName(e.object)}) catch "") else endText(&nb, e, null);
            keyIcon(@src(), "Constraint object", icons.gravenAny(if (c.kind == .equal_size) .geo_edge else .geo_segment) orelse dvui.entypo.dot_single, @intCast(ci * 2 + ei), .{
                .id_extra = 1 + ei,
                .gravity_y = 0.5,
                .padding = pad,
                .min_size_content = .{ .w = 22, .h = 22 },
                .label = .{ .text = tip },
                .background = true,
                .color_fill = if (on) .{ .color = flash_colour.opacity(0.45) } else null,
                .border = if (on) .all(1) else null,
                .color_border = if (on) .{ .color = flash_colour } else null,
            });
        }
        _ = dvui.spacer(@src(), .{ .expand = .horizontal });
        if (!c.driving) {
            var vb: [32]u8 = undefined;
            dvui.labelNoFmt(@src(), dimText(&vb, c), .{}, .{ .gravity_y = 0.5, .id_extra = ci });
        } else {
            const v0 = @round(c.value * k * 1000) / 1000;
            accepted.label_unit = if (k == 1) .mm else .in;
            if (accepted.numberField(@src(), f64, v0, -100000, 100000, .{ .min_size_content = .{ .w = 60 }, .max_size_content = .{ .w = 70, .h = 100 }, .gravity_y = 0.5, .id_extra = ci })) |v| setConstraintValue(c.id, v / k);
        }
        if (icons.button(@src(), .trash, "Remove this constraint", .{ .id_extra = ci, .size = 14, .opts = .{ .gravity_y = 0.5 } })) {
            act(.removeConstraint, .{c.id}) catch {};
            return;
        }
    }
    if (!any) dvui.labelNoFmt(@src(), "None. Constrain (in the tools) picks a feature, then another.", .{}, .{ .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.65) } });
    for (constraintIssues()) |i| {
        for (m.constraints.items) |c| if (c.id == i.constraint and (c.a.object == id or c.b.object == id)) {
            propText("Issue", "{s}", .{switch (i.kind) {
                .missing_object => "a constraint names something removed",
                .cross_parent => "a constraint crosses workspaces",
                .no_parent_edge => "the parent has no edges to keep to",
                .mixed_axes => "a constraint mixes axes",
                .conflict => "a constraint contradicts others: left out",
                .inverted => "constraints turn it inside out",
                .no_feature => "a constraint names a feature it lacks",
            }}, 9700);
            break;
        };
    }
}

/// Nine buttons, the object's box's corners, edge midpoints and centre:
/// the one lit is its object origin. Choosing moves nothing.
fn originPicker(id: layout.model.ObjectId) void {
    const m = &state.model;
    const holds: layout.model.OriginPoint = blk: {
        for (m.panels.items) |p| {
            if (p.id == id) break :blk p.holds;
            for (p.regions.items) |r| if (r.id == id) break :blk r.holds;
            for (p.art.items) |x| if (x.id == id) break :blk x.holds;
        }
        for (m.spaces.items) |s| for (s.regions.items) |r| if (r.id == id) break :blk r.holds;
        for (m.spaces.items) |s| for (s.images.items) |im| if (im.id == id) break :blk im.holds;
        return;
    };
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
    defer row.deinit();
    propName("Origin");
    var grid = dvui.box(@src(), .{ .dir = .vertical }, .{});
    defer grid.deinit();
    const ys = [_]layout.model.Third{ .high, .mid, .low };
    const xs = [_]layout.model.Third{ .low, .mid, .high };
    for (ys, 0..) |y, yi| {
        var line = dvui.box(@src(), .{ .dir = .horizontal }, .{ .id_extra = yi });
        defer line.deinit();
        for (xs, 0..) |x, xi| {
            const on = holds.x == x and holds.y == y;
            var nb: [16]u8 = undefined;
            keyButton(@src(), "", @intCast(yi * 3 + xi), .{
                // Which point of it is its origin: constraints.origin-at.high-low …
                .tag = listTag("constraints.origin-at", std.fmt.bufPrint(&nb, "{s} {s}", .{ @tagName(y), @tagName(x) }) catch "x"),
                .id_extra = yi * 3 + xi,
                .min_size_content = .{ .w = 10, .h = 10 },
                .margin = .all(1),
                .padding = .all(3),
                .color_fill = if (on) .{ .color = colors.guide } else null,
            });
        }
    }
}

// Track paths -------------------------------------------------------------------
//
// While a track (or one of its rows) is the context, its path shows through
// its rows' starts with its control points. Dragging a point moves it;
// dragging anywhere else on the path makes a point there and moves it; a
// click on the path adds a point, and a click on a point selects it, for
// Delete. Rows keep their pitch: the path only sets where each starts.

var path_drag: ?struct {
    parent: Parent,
    region: usize,
    id: ?layout.model.ObjectId,
    from_across: f64,
    start: geom.Point,
    at: geom.Point,
} = null;
var path_selected: ?layout.model.ObjectId = null;

/// The track whose path is shown: the context's, or its row's.
fn pathRegion() ?struct { parent: Parent, region: usize } {
    return switch (state.context) {
        .region => |r| .{ .parent = r.parent, .region = r.region },
        // The track the row lies in (in a thread, not always the flow's).
        .row => |r| if (placedTrack(r.parent, r.region, r.row)) |pt| .{ .parent = pt.parent, .region = pt.member } else .{ .parent = r.parent, .region = r.region },
        else => null,
    };
}

/// A path point (u from the region's origin) on the canvas, mm: at the
/// start of a row, half a row in (the middle of its thickness).
fn pathToMm(pi: Parent, ri: usize, along: f64, across: f64) geom.Point {
    const o = parentOrigin(pi);
    const r = state.model.regionsIn(pi)[ri];
    return if (r.major() == .row)
        .{ .x = o.x + r.origin.x + along * r.pitch, .y = o.y + r.origin.y - (across + 0.5) * r.pitch }
    else
        .{ .x = o.x + r.origin.x + (across + 0.5) * r.pitch, .y = o.y + r.origin.y - along * r.pitch };
}

fn pathFromMm(pi: Parent, ri: usize, p: geom.Point) struct { along: f64, across: f64 } {
    const o = parentOrigin(pi);
    const r = state.model.regionsIn(pi)[ri];
    return if (r.major() == .row)
        .{ .along = (p.x - o.x - r.origin.x) / r.pitch, .across = (o.y + r.origin.y - p.y) / r.pitch - 0.5 }
    else
        .{ .along = (o.y + r.origin.y - p.y) / r.pitch, .across = (p.x - o.x - r.origin.x) / r.pitch - 0.5 };
}

/// How far across the path is drawn: its soft area, its last point, or
/// its last row, whichever is furthest.
fn pathReach(pi: Parent, ri: usize) f64 {
    const r = state.model.regionsIn(pi)[ri];
    var reach = r.h;
    if (r.major() == .column) reach = r.w;
    for (r.path.items) |cp| reach = @max(reach, cp.across + 1);
    if (segmentOrigin(pi, ri, segmentCount(pi, ri) -| 1)) |o| reach = @max(reach, o.across + 1);
    return reach;
}

/// The path point at `at` (canvas mm): a control point (its ID), or a
/// place on the path (no ID), with where it is across.
fn pathHit(at: geom.Point) ?struct { id: ?layout.model.ObjectId, across: f64 } {
    const t = pathRegion() orelse return null;
    const r = state.model.regionsIn(t.parent)[t.region];
    const tol = 7 / state.view.ppm;
    for (r.path.items) |cp| {
        const q = pathToMm(t.parent, t.region, cp.along, cp.across);
        if (@abs(q.x - at.x) <= tol and @abs(q.y - at.y) <= tol) return .{ .id = cp.id, .across = cp.across };
    }
    const u = pathFromMm(t.parent, t.region, at);
    if (u.across < -0.5 or u.across > pathReach(t.parent, t.region)) return null;
    const across = @max(0, u.across);
    if (@abs(u.along - r.pathAt(across)) * r.pitch > tol) return null;
    return .{ .id = null, .across = across };
}

fn finishPathDrag() void {
    const pd = path_drag orelse return;
    path_drag = null;
    const moved = @abs(pd.at.x - pd.start.x) + @abs(pd.at.y - pd.start.y);
    if (moved * state.view.ppm < 3) {
        // A click: select the point, or add one where the path is.
        if (pd.id) |id| {
            path_selected = id;
            state.status = "Control point: drag it to bend the path; Delete removes it. ";
            return;
        }
        const r = state.model.regionsIn(pd.parent)[pd.region];
        path_selected = act(.addControlPoint, .{ pd.parent, pd.region, r.pathAt(pd.from_across), pd.from_across }) catch null;
        state.status = "A control point: drag it to bend the path. ";
        return;
    }
    const u = pathFromMm(pd.parent, pd.region, pd.at);
    const across = @max(0, u.across);
    if (pd.id) |id| {
        act(.moveControlPoint, .{ id, u.along, across }) catch {};
        path_selected = id;
    } else {
        path_selected = act(.bendPath, .{ pd.parent, pd.region, pd.from_across, u.along, across }) catch null;
    }
    state.status = "";
}

/// The context track's path, its control points (the selected one lit)
/// and, while one is dragged, where it goes.
fn drawTrackPath(area: dvui.Rect.Physical) void {
    if (quietText()) return;
    const t = pathRegion() orelse {
        path_selected = null;
        return;
    };
    if (!state.model.hasParent(t.parent) or t.region >= state.model.regionsIn(t.parent).len) return;
    const r = state.model.regionsIn(t.parent)[t.region];
    const px = dvui.windowNaturalScale();
    const reach = pathReach(t.parent, t.region);
    var pts: std.ArrayList(dvui.Point.Physical) = .empty;
    const a = dvui.currentWindow().arena();
    const steps: usize = @intFromFloat(@min(2000, @ceil(reach * 8)));
    for (0..steps + 1) |k| {
        const across = reach * @as(f64, @floatFromInt(k)) / @as(f64, @floatFromInt(@max(1, steps)));
        pts.append(a, state.view.toPx(area, pathToMm(t.parent, t.region, r.pathAt(across), across))) catch return;
    }
    const ink: dvui.ColorOrGradient = .{ .color = colors.guide.opacity(0.85) };
    if (pts.items.len >= 2) dvui.Path.stroke(.{ .points = pts.items }, .{ .thickness = 1.5 * px, .color = ink });
    for (r.path.items) |cp| {
        const dragged = if (path_drag) |pd| pd.id != null and pd.id.? == cp.id else false;
        const at = if (dragged) path_drag.?.at else pathToMm(t.parent, t.region, cp.along, cp.across);
        const q = state.view.toPx(area, at);
        const s: f32 = 4 * px;
        const box: dvui.Rect.Physical = .{ .x = q.x - s, .y = q.y - s, .w = 2 * s, .h = 2 * s };
        const lit = path_selected != null and path_selected.? == cp.id;
        box.fill(.square, .{ .color = .{ .color = if (lit) colors.select else colors.guide } });
    }
    if (path_drag) |pd| if (pd.id == null) {
        const q = state.view.toPx(area, pd.at);
        const s: f32 = 4 * px;
        const box: dvui.Rect.Physical = .{ .x = q.x - s, .y = q.y - s, .w = 2 * s, .h = 2 * s };
        box.fill(.square, .{ .color = .{ .color = colors.select } });
    };
}

// Sketch mode ------------------------------------------------------------------
//
// A sketch is entered to be drawn and constrained (New sketch, a
// double-click on one, or Edit sketch in its properties); everything else
// is dimmed and cannot be picked meanwhile. The pointer highlights the
// nearest point of interest (a geometry's points first, then the nearest
// place on a curve); Tab locks the pointer onto it, and further Tabs onto
// the next-closest, so a click cannot slip off it (Esc releases the lock,
// which adds no constraint). A held click on a point drags it as far as
// its constraints let it. Drawing tools take clicks and add only the
// geometry drawn: every constraint is added on purpose, from the
// selection, by a palette button or a single key (C coincident, H
// horizontal, V vertical, O on object, D distance, R radius, A angle). Esc
// ends, in turn, the pointer lock, a dimension being entered, a drawing
// tool, the selection; it never leaves sketch mode. Enter shows the
// sketch's summary; there, Enter accepts and leaves, and Esc goes back.

const skl = layout.model.sketch_;

/// A view of a sketch in a space.
const SketchRef = struct { space: usize, index: usize };

/// The sketch being edited, while sketch mode is on, and where its origin
/// sits in the space shown (its view's place, or its panel's).
const SkEdit = struct { sketch: usize, space: usize, at: geom.Point };
var sketch_edit: ?SkEdit = null;

/// A sketch with the place its origin sits, as drawn.
const SkPlace = struct {
    item: *layout.model.SketchItem,
    sketch: *skl.Sketch,
    name: []const u8,
    at: geom.Point,

    fn of(index: usize, at: geom.Point) ?SkPlace {
        if (index >= state.model.sketches.items.len) return null;
        const it = &state.model.sketches.items[index];
        return .{ .item = it, .sketch = &it.sketch, .name = it.name, .at = at };
    }
};

/// A sketch view's sketch, placed.
fn viewPlace(space: usize, view: usize) ?SkPlace {
    const v = state.model.sketchView(space, view) catch return null;
    var p = SkPlace.of(state.model.sketchIndex(v.sketch) orelse return null, v.at) orelse return null;
    // A view is a use: it shows the sketch as last accepted.
    p.sketch = p.item.used();
    return p;
}

const SkTool = enum { none, point, segment, polyline, arc_centre, arc_3pt, circle, circle_3pt, line, ray, polar_array, rect_array, polygon };

/// The geometry buttons, in order, and each one's sub-options (its tools),
/// the first its default. A button remembers the sub-option last used.
const SkGeo = enum { point, line, polyline, arc, circle, polygon, array };
const sk_geo_tools = [_][]const SkTool{ &.{.point}, &.{ .segment, .ray, .line }, &.{.polyline}, &.{ .arc_centre, .arc_3pt }, &.{ .circle, .circle_3pt }, &.{.polygon}, &.{ .polar_array, .rect_array } };
var sk_geo_last = [_]SkTool{ .point, .segment, .polyline, .arc_centre, .circle, .polygon, .polar_array };
/// The polygon tool's number of sides.
var polygon_sides: u32 = 6;

/// The geometry button tool `t` belongs to.
fn skGeoOf(t: SkTool) ?SkGeo {
    for (sk_geo_tools, 0..) |tools, g| for (tools) |x| {
        if (x == t) return @enumFromInt(g);
    };
    return null;
}

/// Whether tool `t` can be chosen now: rays and lines are construction
/// geometry only.
fn skToolAllowed(t: SkTool) bool {
    return (t != .ray and t != .line) or sk_construction;
}

/// Chooses tool `t` (remembered for its button), starting it afresh.
fn skChooseTool(t: SkTool) void {
    if (!skToolAllowed(t)) return;
    sk_tool = t;
    sk_nclicks = 0;
    if (skGeoOf(t)) |g| sk_geo_last[@intFromEnum(g)] = t;
}

/// M: the active button's next sub-option it allows.
fn skCycleTool() void {
    const g = skGeoOf(sk_tool) orelse return;
    const tools = sk_geo_tools[@intFromEnum(g)];
    var k: usize = for (tools, 0..) |x, i| {
        if (x == sk_tool) break i;
    } else 0;
    for (0..tools.len) |_| {
        k = (k + 1) % tools.len;
        if (skToolAllowed(tools[k])) return skChooseTool(tools[k]);
    }
}

/// Sets construction geometry on or off for new geometry and the
/// selection; off, a ray or line tool falls back to the segment.
fn skSetConstruction(on: bool) void {
    sk_construction = on;
    for (sk_sel.items) |p| switch (p) {
        .curve => |g| _ = skEdit(.{ .construction = .{ .g = g, .on = on } }),
        .point => |r| if (r.role == .point) {
            _ = skEdit(.{ .construction = .{ .g = r.geom, .on = on } });
        },
        .constraint => {},
    };
    if (!on and (sk_tool == .ray or sk_tool == .line)) skChooseTool(.segment);
    if (!on) sk_geo_last[@intFromEnum(SkGeo.line)] = .segment;
}
var sk_tool: SkTool = .none;
/// New geometry is construction geometry.
var sk_construction = false;
/// The clicks of the drawing tool so far, in the sketch's frame.
var sk_clicks: [3]geom.Point = undefined;
var sk_nclicks: usize = 0;

/// Something picked in a sketch: a point of a geometry, a curve, or a
/// constraint (from the list).
const SkPick = union(enum) {
    point: skl.PointRef,
    curve: skl.GeomId,
    constraint: skl.ConstraintId,
};
var sk_sel: std.ArrayList(SkPick) = .empty;

/// Points of interest near the pointer, nearest first (points before
/// curves), with where each is (the sketch's frame).
const SkHit = struct { pick: SkPick, at: geom.Point };
var sk_hits: [24]SkHit = undefined;
var sk_nhits: usize = 0;
/// The hit Tab locked the pointer onto, and where on the screen.
var sk_lock: ?SkHit = null;
var sk_lock_px: dvui.Point.Physical = .{};
/// Where the pointer was at the last position event in sketch mode.
var sk_last_px: dvui.Point.Physical = .{};
var sk_lock_index: usize = 0;
/// The pointer, in the sketch's frame.
var sk_pointer: ?geom.Point = null;
/// A point being dragged (`moved` once it has), each drag one undo step.
var sk_drag: ?struct { p: skl.PointRef, moved: bool, start: geom.Point } = null;
/// A drag of a dimension's value: the value slides along its line and the
/// line across with it (its placement, saved with it).
var sk_dim_drag: ?struct { c: skl.ConstraintId, moved: bool, start: geom.Point, seq: u64 } = null;
var sk_drag_seq: u64 = 0;
/// A selection box being dragged out on empty space.
var sk_box: ?struct { start: geom.Point, at: geom.Point } = null;
var sk_press_ctrl = false;
var sk_summary = false;
/// A dimension's value being entered.
var sk_dim: ?struct { c: skl.ConstraintId, at: dvui.Point.Physical, fresh: bool = true, focus_tries: u8 = 6 } = null;
var sk_status_buf: [160]u8 = undefined;
var sk_dim_id: ?dvui.Id = null;

/// The analysis of the sketch being edited, kept until the model changes.
var sk_an: ?skl.solver.Analysis = null;
var sk_an_arena: ?std.heap.ArenaAllocator = null;
var sk_an_rev: u64 = std.math.maxInt(u64);

/// Double-click: the last pick, when and on which sketch.
var sk_last_pick: ?struct { ref: SketchRef, ns: i128 } = null;

fn skItem() ?SkPlace {
    const r = sketch_edit orelse return null;
    return SkPlace.of(r.sketch, r.at);
}

fn skLocal(it: SkPlace, p: geom.Point) geom.Point {
    return .{ .x = p.x - it.at.x, .y = p.y - it.at.y };
}

fn skPx(area: dvui.Rect.Physical, it: anytype, p: geom.Point) dvui.Point.Physical {
    return state.view.toPx(area, .{ .x = p.x + it.at.x, .y = p.y + it.at.y });
}

fn skAnalysis() ?skl.solver.Analysis {
    const it = skItem() orelse return null;
    if (sk_an != null and sk_an_rev == state.model.revision) return sk_an;
    if (sk_an_arena) |*ar| ar.deinit();
    sk_an_arena = .init(state.gpa);
    sk_an = it.sketch.analyse(state.gpa, sk_an_arena.?.allocator()) catch null;
    sk_an_rev = state.model.revision;
    return sk_an;
}

fn enterSketch(ref: SketchRef) void {
    const v = state.model.sketchView(ref.space, ref.index) catch return;
    enterSketchAt(state.model.sketchIndex(v.sketch) orelse return, ref.space, v.at);
    state.context = .{ .sketch = .{ .space = ref.space, .index = ref.index } };
}

/// GRAVEN_SAMPLE=sketch: the ready-made rectangle sketch edited on the
/// canvas, its width dimension moved below it (extension lines) and its
/// value along, its height's to the right: dimensions after drafting
/// practice, to look at.
/// Three text columns in a panel, kept by constraints to two construction
/// lines on the canvas (`GRAVEN_SAMPLE=columns`): the first column's top
/// 12 mm below the horizontal line and its left 8 mm right of the
/// vertical one (ends in different frames), its width 55 mm, gutters of
/// 6 mm, the others as wide as it and level with it.
fn loadColumnsSample() !void {
    return loadColumnsSampleWith(true);
}

fn loadColumnsSampleWith(constrained: bool) !void {
    const m = &state.model;
    const space = shown_space;
    const style = try labelStyle();
    const p = try m.placePanel(.{ .name = "Panel", .space = m.spaces.items[space].id, .origin = .{ .x = 30, .y = 20 }, .w = 210, .h = 150 });
    var ids: [3]layout.model.ObjectId = undefined;
    for ([_]f64{ 15, 80, 150 }, [_]f64{ 48, 60, 44 }, [_]f64{ 125, 118, 121 }, 0..) |x, w, top, k| {
        var nb: [16]u8 = undefined;
        const r = try m.addTracks(.{ .panel = p }, .{ .name = try std.fmt.bufPrint(&nb, "Column{d}", .{k + 1}), .origin = .{ .x = x, .y = top }, .style = style, .count = 16, .length = w / 6, .pitch = 6 });
        ids[k] = m.panels.items[p].regions.items[r].id;
    }
    const hi = try m.addGuide(space, .{ .x = 0, .y = 175 }, 0);
    m.spaces.items[space].guides.items[hi].lock = .horizontal;
    const hid = m.spaces.items[space].guides.items[hi].id;
    const vi = try m.addGuide(space, .{ .x = 40, .y = 0 }, 90);
    m.spaces.items[space].guides.items[vi].lock = .vertical;
    const vid = m.spaces.items[space].guides.items[vi].id;
    try hist.snapshot(m);
    state.view.fit = .{ .x0 = 25, .y0 = 15, .x1 = 245, .y1 = 185 };
    if (!constrained) return;
    const C = layout.model.Constraint;
    const list = [_]C{
        .{ .a = .{ .object = ids[0], .feature = .top }, .b = .{ .object = hid, .feature = .origin_y }, .value = 12, .side = -1 },
        .{ .a = .{ .object = ids[0], .feature = .left }, .b = .{ .object = vid, .feature = .origin_x }, .value = 8 },
        .{ .a = .{ .object = ids[0], .feature = .right }, .b = .{ .object = ids[0], .feature = .left }, .value = 55 },
        .{ .a = .{ .object = ids[1], .feature = .left }, .b = .{ .object = ids[0], .feature = .right }, .value = 6 },
        .{ .a = .{ .object = ids[2], .feature = .left }, .b = .{ .object = ids[1], .feature = .right }, .value = 6 },
        .{ .kind = .equal_size, .a = .{ .object = ids[1], .feature = .left }, .b = .{ .object = ids[0], .feature = .left } },
        .{ .kind = .equal_size, .a = .{ .object = ids[2], .feature = .left }, .b = .{ .object = ids[0], .feature = .left } },
        .{ .a = .{ .object = ids[1], .feature = .top }, .b = .{ .object = ids[0], .feature = .top } },
        .{ .a = .{ .object = ids[2], .feature = .top }, .b = .{ .object = ids[0], .feature = .top } },
    };
    for (list, 0..) |c, k| {
        const id = try act(.addConstraint, .{c});
        // The dimensions off the columns: above them, or left of them.
        const across: f64 = switch (k) {
            0 => 33,
            1, 2, 3, 4 => -57,
            else => 0,
        };
        if (across != 0) _ = act(.setConstraintPlace, .{ id, layout.model.ConstraintPlace{ .offset = across } }) catch {};
    }
    state.view.fit = .{ .x0 = 25, .y0 = 15, .x1 = 245, .y1 = 185 };
}

fn loadSketchSample() void {
    const index = act(.addShapeSketch, .{layout.model.ShapeSketch.rectangle}) catch return;
    enterSketchAt(index, shown_space, .{ .x = 0, .y = 0 });
    const sk = &state.model.sketches.items[index].sketch;
    for (sk.constraints.items, 0..) |c, ci| {
        if (std.mem.eql(u8, c.expr, "w")) _ = skEdit(.{ .place = .{ .c = @intCast(ci), .place = .{ .offset = -12, .text = 3 } } });
        if (std.mem.eql(u8, c.expr, "h")) _ = skEdit(.{ .place = .{ .c = @intCast(ci), .place = .{ .offset = -10 } } });
    }
    state.view.cx = 0;
    state.view.cy = -3;
    state.view.ppm = 40;
    state.view.fit = null;
}

/// GRAVEN_SAMPLE=sketch-panel: the ready-made rectangle, its edges and a
/// circle inside inked, inserted onto the canvas as a panel (the circle a
/// hole in it).
fn loadSketchPanelSample() void {
    const index = act(.addShapeSketch, .{layout.model.ShapeSketch.rectangle}) catch return;
    _ = act(.editSketch, .{ index, layout.model.SketchEdit{ .param = .{ .name = "w", .expr = "70" } } }) catch {};
    _ = act(.editSketch, .{ index, layout.model.SketchEdit{ .param = .{ .name = "h", .expr = "30" } } }) catch {};
    // A ring round a switch's hole (a cutout fill), right of the text.
    const ring = act(.editSketch, .{ index, layout.model.SketchEdit{ .circle = .{ .c = .{ .x = 22, .y = 0 }, .r = 7 } } }) catch return;
    const hole = act(.editSketch, .{ index, layout.model.SketchEdit{ .circle = .{ .c = .{ .x = 22, .y = 0 }, .r = 3.5 } } }) catch return;
    const sk = &state.model.sketches.items[index].sketch;
    for (sk.geometry.items, 0..) |g, gi| {
        if (g.removed or g.reference or g.construction) continue;
        if (g.kind == .segment) _ = act(.setInk, .{ index, @as(u32, @intCast(gi)), true }) catch {};
    }
    _ = act(.setInk, .{ index, ring, true }) catch {};
    _ = act(.setFill, .{ index, @as([]const u32, &.{hole}), true, true }) catch {};
    const pi = act(.insertSketchPanel, .{ shown_space, index, geom.Point{ .x = 0, .y = 0 } }) catch return;
    // Text across the panel, flowing round the ring.
    const style = labelStyle() catch return;
    const pitch = 6.0;
    const r = state.model.addTracks(.{ .panel = pi }, .{ .name = "Text", .origin = .{ .x = 4, .y = 25 }, .style = style, .count = 3, .length = 62.0 / pitch, .pitch = pitch }) catch return;
    state.model.insertRun(.{ .panel = pi }, r, 0, .{ .style = style, .content = "Text on a panel cut from a sketch flows round its ink." }) catch {};
    state.context = .{ .panel = pi };
    state.view.cx = 0;
    state.view.cy = 0;
    state.view.ppm = 14;
    state.view.fit = null;
}

/// Edits sketch `index` with its origin at `at` in space `space`.
fn enterSketchAt(index: usize, space: usize, at: geom.Point) void {
    sketch_edit = .{ .sketch = index, .space = space, .at = at };
    shown_space = space;
    state.tool = .select;
    sk_tool = .none;
    sk_nclicks = 0;
    sk_sel.clearRetainingCapacity();
    sk_lock = null;
    sk_summary = false;
    sk_dim = null;
    sk_an_rev = std.math.maxInt(u64);
    selection.clearRetainingCapacity();
    track_cursor = null;
    if (canvas_id) |id| dvui.focusWidget(id, null, null);
    state.status = "Sketch mode: draw from the palette; Tab locks the pointer; Enter shows the summary. ";
}

/// The one selected point a caption may be added to (on a circle or an
/// arc, which `addCaption` checks).
fn skCaptionPoint() ?skl.PointRef {
    if (sk_sel.items.len != 1) return null;
    return switch (sk_sel.items[0]) {
        .point => |r| r,
        else => null,
    };
}

/// The sketch view being edited, by ID.
fn skViewId() ?layout.model.ObjectId {
    const r = sketch_edit orelse return null;
    if (r.space >= state.model.spaces.items.len) return null;
    const sid = state.model.sketches.items[r.sketch].id;
    for (state.model.spaces.items[r.space].sketch_views.items) |v| {
        if (v.sketch == sid and v.at.x == r.at.x and v.at.y == r.at.y) return v.id;
    }
    return null;
}

/// Add caption: a leader from the selected point and a track of text held
/// to its end; the sketch is left, the cursor waiting in the track.
fn skAddCaption() void {
    const p = skCaptionPoint() orelse return;
    const view = skViewId() orelse {
        state.status = "A caption needs the sketch placed on a canvas or panel: this one is only being defined. ";
        return;
    };
    const key = mergeKey(.{ "caption", view, p.geom, @intFromEnum(p.role), state.model.revision });
    const style = labelStyleIn(key) catch {
        state.status = "Add caption: no text style for it. ";
        return;
    };
    const pitch = styleLinePitch(style) orelse {
        state.status = "Add caption: no text style for it. ";
        return;
    };
    const cap = actM(key, .addCaption, .{ view, p, style, pitch, 30 }) catch |err| {
        state.status = if (err == error.NotOnACurve) "A caption goes on a point of a circle or an arc. " else "The caption could not be added. ";
        return;
    };
    // Its text in the caption's style, with no paragraph style, so the
    // track's alignment (toward the leader) holds.
    if (state.model.trackFlow(cap.parent, cap.region)) |fl| {
        const tid = defaultTemplate() catch null;
        if (tid) |t| _ = hist.join(&state.model, .setFlowStyle, .{ fl.id, style, @as(?layout.model.ParaId, null), @as(?layout.model.Leading, null), t }) catch {};
    }
    leaveSketch();
    state.context = .{ .region = .{ .parent = cap.parent, .region = cap.region } };
    track_cursor = .{ .parent = cap.parent, .region = cap.region, .index = 0 };
    state.expanded.put(state.gpa, Context.key(parentContext(cap.parent)), true) catch {};
}

/// The selected curves of the sketch being edited (points' curves are
/// not: ink is drawn on lines and arcs).
fn skInkable(buf: []skl.GeomId) []skl.GeomId {
    var n: usize = 0;
    for (sk_sel.items) |p| switch (p) {
        .curve => |g| if (n < buf.len) {
            buf[n] = g;
            n += 1;
        },
        else => {},
    };
    return buf[0..n];
}

/// Whether geometry `g` of the sketch being edited is inked in the
/// current stroke style.
fn skInked(g: skl.GeomId) bool {
    const r = sketch_edit orelse return false;
    const fi = state.model.sketchFigure(state.model.sketches.items[r.sketch].id) orelse return false;
    const cur = state.model.currentStroke() orelse return false;
    for (skMarks(fi).inks) |k| if (k.geom == g and k.style == cur) return true;
    return false;
}

/// Ink (I): the selected curves drawn in the current stroke style, the
/// sketch's figure; when every one is inked in it already, the ink comes off.
fn skInk() void {
    const r = sketch_edit orelse return;
    var buf: [256]skl.GeomId = undefined;
    const gs = skInkable(&buf);
    if (gs.len == 0) {
        state.status = "Ink: select lines or arcs first. ";
        return;
    }
    var all = true;
    for (gs) |g| if (!skInked(g)) {
        all = false;
    };
    const key = mergeKey(.{ "ink", r.sketch, state.model.revision });
    for (gs) |g| _ = actM(key, .setInkDraft, .{ r.sketch, g, !all }) catch {};
    state.status = if (all) "Ink taken off. " else "Inked in the current stroke style. ";
}

/// Ink in sketch-mode Properties: inking the selection, and the stroke
/// style it takes (chosen, its width, a new one).
fn sketchInkProperties() void {
    const saved_group = pushGroup("ink");
    defer popGroup(saved_group);
    heading("{s}", .{"Ink"}, 8195);
    var buf: [256]skl.GeomId = undefined;
    _ = &buf;
    const m = &state.model;
    if (m.stroke_styles.items.len > 0) {
        const ar = dvui.currentWindow().arena();
        const names = ar.alloc([]const u8, m.stroke_styles.items.len) catch return;
        for (m.stroke_styles.items, 0..) |st, i| names[i] = st.name;
        const cur = m.currentStroke().?;
        var choice: usize = m.strokeStyleIndex(cur) orelse 0;
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8196 });
            defer row.deinit();
            propName("Stroke style");
            if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 8196 })) actV(.setCurrentStroke, .{m.stroke_styles.items[choice].id});
        }
        const st = m.stroke_styles.items[choice];
        if (numberProp("Width, mm", st.stroke.width, 0.01, 100, 8197)) |w| {
            var next = st.stroke;
            next.width = w;
            _ = actM(mergeKey(.{ "stroke-width", st.id }), .setStrokeStyle, .{ st.id, st.name, next }) catch {};
        }
    } else propText("Pen", "{s}", .{"0.3 mm black, made with the first ink"}, 8196);
    keyButton(@src(), "New stroke style", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
}

/// A new stroke style, like the current one (or a fine black pen), made
/// current.
fn newStrokeStyle() void {
    const m = &state.model;
    var stroke: layout.figure.Stroke = .{ .color = .{ .r = 0, .g = 0, .b = 0 }, .width = 0.3, .cap = .round, .join = .round };
    if (m.currentStroke()) |id| stroke = m.stroke_styles.items[m.strokeStyleIndex(id).?].stroke;
    var buf: [32]u8 = undefined;
    const name = std.fmt.bufPrint(&buf, "Pen {d}", .{m.stroke_styles.items.len + 1}) catch "Pen";
    const key = mergeKey(.{ "new-stroke", m.revision });
    const id = actM(key, .addStrokeStyle, .{ name, stroke }) catch return;
    _ = actM(key, .setCurrentStroke, .{id}) catch {};
}

/// Whether Fill (F) fills the closed paths inside the boundary too
/// (otherwise they are left out, holes).
var fill_enclosed = false;

/// The figure fill of the sketch being edited whose boundary is exactly
/// `gs` (any order), if any.
fn skFillOf(gs: []const skl.GeomId) ?usize {
    const r = sketch_edit orelse return null;
    const fi = state.model.sketchFigure(state.model.sketches.items[r.sketch].id) orelse return null;
    for (skMarks(fi).fills, 0..) |f, i| {
        if (f.geoms.len != gs.len) continue;
        var all = true;
        for (gs) |g| if (std.mem.indexOfScalar(u32, f.geoms, g) == null) {
            all = false;
        };
        if (all) return i;
    }
    return null;
}

/// Fill (F): the area the selected curves close filled in the current
/// fill style (its enclosed paths filled or left out as Properties says);
/// a boundary filled already has its fill taken off.
fn skFill() void {
    const r = sketch_edit orelse return;
    var buf: [256]skl.GeomId = undefined;
    const gs = skInkable(&buf);
    if (gs.len == 0) {
        state.status = "Fill: select the lines and arcs (or the circle) around the area first. ";
        return;
    }
    const on = skFillOf(gs) == null;
    act(.setFillDraft, .{ r.sketch, gs, fill_enclosed, on }) catch |err| {
        state.status = if (err == error.NotEnclosed) "Fill: the selection must close a path (end to end, round to its start). " else "The fill could not be made. ";
        return;
    };
    state.status = if (on) "Filled in the current fill style. " else "Fill taken off. ";
}

/// Fill in sketch-mode Properties: filling the selection, the fill style
/// it takes (chosen, its pattern, angle, spacing, line width, what it
/// means), whether enclosed paths are filled, a new style.
fn sketchFillProperties() void {
    const saved_group = pushGroup("fill");
    defer popGroup(saved_group);
    heading("{s}", .{"Fill"}, 8180);
    var buf: [256]skl.GeomId = undefined;
    const gs = skInkable(&buf);
    // The selection's own fill's setting, when it has one; else the one
    // new fills take.
    const own: ?usize = if (gs.len > 0) skFillOf(gs) else null;
    if (own) |k| {
        const r = sketch_edit.?;
        const fi = state.model.sketchFigure(state.model.sketches.items[r.sketch].id).?;
        var on = skMarks(fi).fills[k].enclosed;
        if (tcheckbox(@src(), &on, "Fill enclosed paths", .{ .id_extra = 8181 })) {
            fill_enclosed = on;
            actV(.setFillDraft, .{ r.sketch, gs, on, true });
        }
    } else _ = tcheckbox(@src(), &fill_enclosed, "Fill enclosed paths", .{ .id_extra = 8181 });
    const m = &state.model;
    if (m.fill_styles.items.len == 0) {
        propText("Style", "{s}", .{"Hatch 45°, made with the first fill"}, 8182);
    } else {
        const ar = dvui.currentWindow().arena();
        const names = ar.alloc([]const u8, m.fill_styles.items.len) catch return;
        for (m.fill_styles.items, 0..) |st, i| names[i] = st.name;
        var choice: usize = m.fillStyleIndex(m.currentFill().?) orelse 0;
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8182 });
            defer row.deinit();
            propName("Fill style");
            if (tdropdown(@src(), names, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 8182 })) actV(.setCurrentFill, .{m.fill_styles.items[choice].id});
        }
        const st = m.fill_styles.items[choice];
        var next = st;
        var changed = false;
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8183 });
            defer row.deinit();
            propName("Pattern");
            const kinds = [_][]const u8{ "Solid", "Hatch" };
            var k: usize = @intFromEnum(std.meta.activeTag(st.pattern));
            if (tdropdown(@src(), &kinds, .{ .choice = &k }, .{}, .{ .expand = .horizontal, .id_extra = 8183 })) {
                next.pattern = if (k == 0) .solid else .{ .hatch = .{} };
                changed = true;
            }
        }
        switch (st.pattern) {
            .solid => {},
            .hatch => |h| {
                var nh = h;
                if (numberProp("Angle, °", h.angle, -360, 360, 8184)) |v| {
                    nh.angle = v;
                    changed = true;
                }
                if (numberProp("Spacing, mm", h.spacing, 0.05, 100, 8185)) |v| {
                    nh.spacing = v;
                    changed = true;
                }
                if (numberProp("Line width, mm", h.width, 0.01, 100, 8186)) |v| {
                    nh.width = v;
                    changed = true;
                }
                if (changed and std.meta.activeTag(next.pattern) == .hatch) next.pattern = .{ .hatch = nh };
            },
        }
        var cut = st.cutout;
        if (tcheckbox(@src(), &cut, "Means a cutout", .{ .id_extra = 8187 })) {
            next.cutout = cut;
            changed = true;
        }
        if (changed) _ = actM(mergeKey(.{ "fill-style", st.id }), .setFillStyle, .{ st.id, next }) catch {
            state.status = "A hatch's lines must be narrower than their spacing. ";
        };
    }
    keyButton(@src(), "New fill style", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
}

/// A new fill style, like the current one (or a 45° hatch), made current.
fn newFillStyle() void {
    const m = &state.model;
    var st: layout.model.FillStyle = .{ .name = "", .color = .{ .r = 0, .g = 0, .b = 0 }, .pattern = .{ .hatch = .{} }, .cutout = true };
    if (m.currentFill()) |id| st = m.fill_styles.items[m.fillStyleIndex(id).?];
    var buf: [32]u8 = undefined;
    st.name = std.fmt.bufPrint(&buf, "Fill {d}", .{m.fill_styles.items.len + 1}) catch "Fill";
    const key = mergeKey(.{ "new-fill", m.revision });
    const id = actM(key, .addFillStyle, .{st}) catch return;
    _ = actM(key, .setCurrentFill, .{id}) catch {};
}

fn leaveSketch() void {
    if (sketch_edit) |r| skAccept(r.sketch);
    sketch_edit = null;
    sk_summary = false;
    sk_dim = null;
    sk_lock = null;
    sk_drag = null;
    sk_dim_drag = null;
    sk_box = null;
    sk_sel.clearRetainingCapacity();
    state.status = "";
}

/// Accepts sketch `index`'s draft, if one is pending: its uses follow it.
fn skAccept(index: usize) void {
    if (index >= state.model.sketches.items.len or state.model.sketches.items[index].accepted == null) return;
    _ = act(.acceptSketch, .{index}) catch {
        state.status = "The sketch's changes were not accepted. ";
        return;
    };
    state.status = "The sketch's changes are accepted: what uses it follows them. ";
}

/// Whether the sketch being edited has changes not yet accepted.
fn skPending() bool {
    const r = sketch_edit orelse return false;
    return r.sketch < state.model.sketches.items.len and state.model.sketches.items[r.sketch].accepted != null;
}

/// A new sketch in a space of its own, shown in a tab of the active
/// window and edited there.
fn newSketchInOwnSpace() void {
    var buf: [32]u8 = undefined;
    const name = state.model.freshName(&buf, .sketches, "Sketch");
    const idx = act(.addSketchSpace, .{name}) catch {
        state.status = "The sketch was not started. ";
        return;
    };
    state.model.sketches.items[idx].default_name = true;
    const home = state.model.homeOf(state.model.sketches.items[idx].id) orelse return;
    openHome(home);
}

/// Shows sketch space `home` in the active window (its tab, or a new
/// one); showing it starts editing its sketch (`followHome`).
fn openHome(home: usize) void {
    if (sketch_edit != null) leaveSketch();
    const leaf = vl.leafOf(vl.active) orelse return;
    _ = openInWindow(leaf, .{ .target = spaceTarget(home) }, home, false);
    // The context the sketch: the shown space follows the context, and
    // the canvas's would take it back.
    if (state.model.sketchIndex(state.model.spaces.items[home].home)) |ski| state.context = .{ .sketch_def = ski };
}

/// A sketch's own space is only for editing it: shown (in the active
/// view), its sketch is being edited; another space shown, an edit
/// begun there is accepted and left.
fn followHome() void {
    if (state.model.isHome(shown_space)) {
        if (sketch_edit) |r| if (r.space == shown_space) return;
        if (sketch_edit != null) leaveSketch();
        const ski = state.model.sketchIndex(state.model.spaces.items[shown_space].home) orelse return;
        enterSketchAt(ski, shown_space, .{ .x = 0, .y = 0 });
        state.status = "The sketch in its own space: draw from the ribbon; U updates its uses. ";
    } else if (sketch_edit) |r| if (state.model.isHome(r.space)) leaveSketch();
}

/// Figure `fi`'s marks as the sketch editor shows them: pending, else
/// its own.
fn skMarks(fi: usize) layout.figure.Marks {
    const f = state.model.figures.items[fi];
    return f.pending orelse .{ .inks = f.inks, .fills = f.fills };
}

/// Drops the sketch being edited's draft (geometry, constraints, ink and
/// fills): back to the sketch as last accepted.
fn skDiscard() void {
    const r = sketch_edit orelse return;
    if (!skPending()) {
        state.status = "Nothing to discard. ";
        return;
    }
    _ = act(.discardSketchDraft, .{r.sketch}) catch {
        state.status = "The sketch's changes were not discarded. ";
        return;
    };
    sk_sel.clearRetainingCapacity();
    sk_drag = null;
    sk_dim_drag = null;
    state.status = "The sketch's changes since the last update are discarded. ";
}

/// A new sketch in the shown space, its origin at `at`, then edited.
fn newSketchAt(at: geom.Point) void {
    var buf: [32]u8 = undefined;
    const name = state.model.freshName(&buf, .sketches, "Sketch");
    const p: geom.Point = .{ .x = @round(at.x * 2) / 2, .y = @round(at.y * 2) / 2 };
    const idx = act(.addSketch, .{ shown_space, name, p }) catch {
        state.status = "The sketch was not started. ";
        return;
    };
    state.model.sketches.items[idx].default_name = true;
    enterSketch(.{ .space = shown_space, .index = state.model.spaces.items[shown_space].sketch_views.items.len - 1 });
}

fn skEdit(edit: layout.model.SketchEdit) ?u32 {
    const r = sketch_edit orelse return null;
    return act(.editSketchDraft, .{ r.sketch, edit }) catch |err| {
        state.status = switch (err) {
            error.NotConstruction => "Infinite lines and rays are construction only. ",
            error.WrongKind, error.NoSuchPoint => "That constraint does not fit what is selected. ",
            else => "That change could not be made. ",
        };
        return null;
    };
}

/// The sketch's box in the space (its own box moved by its origin).
fn sketchBox(it: SkPlace) ?geom.Box {
    const b = (it.sketch.box(dvui.currentWindow().arena()) catch return null) orelse return null;
    return .{ .x0 = b.x0 + it.at.x, .y0 = b.y0 + it.at.y, .x1 = b.x1 + it.at.x, .y1 = b.y1 + it.at.y };
}

/// The sketch under space point `at` in the shown space, by its box.
fn sketchUnder(at: geom.Point) ?SketchRef {
    if (shown_space >= state.model.spaces.items.len) return null;
    var found: ?SketchRef = null;
    for (state.model.spaces.items[shown_space].sketch_views.items, 0..) |_, i| {
        const b = sketchBox(viewPlace(shown_space, i) orelse continue) orelse continue;
        const m = 1.0;
        if (at.x >= b.x0 - m and at.x <= b.x1 + m and at.y >= b.y0 - m and at.y <= b.y1 + m) found = .{ .space = shown_space, .index = i };
    }
    return found;
}

/// Picks a sketch for its properties; a second pick on it soon after
/// enters it.
fn pickSketch(ref: SketchRef) void {
    state.context = .{ .sketch = .{ .space = ref.space, .index = ref.index } };
    const now = dvui.frameTimeNS();
    if (sk_last_pick) |lp| if (std.meta.eql(lp.ref, ref) and now - lp.ns < 500 * std.time.ns_per_ms) {
        sk_last_pick = null;
        enterSketch(ref);
        return;
    };
    sk_last_pick = .{ .ref = ref, .ns = now };
}

// Geometry questions, in the sketch's frame -------------------------------------

fn skVal(s: *const skl.Sketch, p: skl.Pt) geom.Point {
    return .{ .x = s.vars.items[p.x], .y = s.vars.items[p.y] };
}

fn skDist(a: geom.Point, b: geom.Point) f64 {
    return @sqrt((a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y));
}

fn normAngle(t: f64) f64 {
    var x = @mod(t, 2 * std.math.pi);
    if (x < 0) x += 2 * std.math.pi;
    return x;
}

/// A straight geometry's point and unit direction.
fn skLineOf(s: *const skl.Sketch, g: skl.Geometry) ?struct { p: geom.Point, d: geom.Point } {
    switch (g.kind) {
        .segment => |sg| {
            const a = skVal(s, sg.a);
            const b = skVal(s, sg.b);
            const l = skDist(a, b);
            if (l == 0) return null;
            return .{ .p = a, .d = .{ .x = (b.x - a.x) / l, .y = (b.y - a.y) / l } };
        },
        .line => |ln| {
            const th = s.vars.items[ln.theta];
            const rho = s.vars.items[ln.rho];
            return .{ .p = .{ .x = rho * @cos(th), .y = rho * @sin(th) }, .d = .{ .x = -@sin(th), .y = @cos(th) } };
        },
        .ray => |ry| {
            const an = s.vars.items[ry.angle];
            return .{ .p = skVal(s, ry.o), .d = .{ .x = @cos(an), .y = @sin(an) } };
        },
        else => return null,
    }
}

/// The nearest place on geometry `g` to `q`, if it has one there.
fn skNearestOn(s: *const skl.Sketch, g: skl.Geometry, q: geom.Point) ?geom.Point {
    switch (g.kind) {
        .point, .affine => return null,
        .segment, .line, .ray => {
            const l = skLineOf(s, g) orelse return null;
            var t = (q.x - l.p.x) * l.d.x + (q.y - l.p.y) * l.d.y;
            switch (g.kind) {
                .segment => |sg| t = std.math.clamp(t, 0, skDist(skVal(s, sg.a), skVal(s, sg.b))),
                .ray => t = @max(t, 0),
                else => {},
            }
            return .{ .x = l.p.x + t * l.d.x, .y = l.p.y + t * l.d.y };
        },
        .circle => |ci| {
            const c = skVal(s, ci.c);
            const r = s.vars.items[ci.r];
            const d = skDist(q, c);
            if (d == 0) return null;
            return .{ .x = c.x + (q.x - c.x) * r / d, .y = c.y + (q.y - c.y) * r / d };
        },
        .arc => |ar| {
            const c = skVal(s, ar.c);
            const a = skVal(s, ar.a);
            const b = skVal(s, ar.b);
            const r = skDist(a, c);
            const d = skDist(q, c);
            if (d == 0) return null;
            const a0 = std.math.atan2(a.y - c.y, a.x - c.x);
            const sweep = normAngle(std.math.atan2(b.y - c.y, b.x - c.x) - a0);
            if (normAngle(std.math.atan2(q.y - c.y, q.x - c.x) - a0) > sweep) return null;
            return .{ .x = c.x + (q.x - c.x) * r / d, .y = c.y + (q.y - c.y) * r / d };
        },
    }
}

/// The points of a geometry, with their roles.
fn skPointsOf(g: skl.Geometry, buf: *[3]skl.PointRef, id: skl.GeomId) []skl.PointRef {
    const roles: []const @FieldType(skl.PointRef, "role") = switch (g.kind) {
        .point, .affine => &.{.point},
        .segment => &.{ .start, .end },
        .circle => &.{.centre},
        .arc => &.{ .centre, .start, .end },
        .ray => &.{.origin},
        .line => &.{},
    };
    for (roles, 0..) |r, i| buf[i] = .{ .geom = id, .role = r };
    return buf[0..roles.len];
}

/// The points of interest within `radius` of `q`: points first, nearest
/// first, then curves.
fn skFindHits(s: *const skl.Sketch, q: geom.Point, radius: f64) void {
    sk_nhits = 0;
    var curves: [24]SkHit = undefined;
    var ncurves: usize = 0;
    var pdist: [24]f64 = undefined;
    var cdist: [24]f64 = undefined;
    for (s.geometry.items, 0..) |g, gi| {
        if (g.removed) continue;
        var buf: [3]skl.PointRef = undefined;
        for (skPointsOf(g, &buf, @intCast(gi))) |r| {
            const p = s.point(r) catch continue;
            const d0 = skDist(p, q);
            if (d0 > radius or sk_nhits >= sk_hits.len) continue;
            // The sketch's own origin after its geometry at the same place
            // (an array's centre sits on it).
            const d = if (g.reference) d0 + radius else d0;
            // Insertion by distance.
            var k = sk_nhits;
            while (k > 0 and pdist[k - 1] > d) : (k -= 1) {
                sk_hits[k] = sk_hits[k - 1];
                pdist[k] = pdist[k - 1];
            }
            sk_hits[k] = .{ .pick = .{ .point = r }, .at = p };
            pdist[k] = d;
            sk_nhits += 1;
        }
        if (skNearestOn(s, g, q)) |p| {
            const d = skDist(p, q);
            if (d > radius or ncurves >= curves.len) continue;
            var k = ncurves;
            while (k > 0 and cdist[k - 1] > d) : (k -= 1) {
                curves[k] = curves[k - 1];
                cdist[k] = cdist[k - 1];
            }
            curves[k] = .{ .pick = .{ .curve = @intCast(gi) }, .at = p };
            cdist[k] = d;
            ncurves += 1;
        }
    }
    // Dimensions, by their value or their line (after points, before
    // curves): pressed and dragged, they are placed.
    const px = dvui.windowNaturalScale();
    for (s.constraints.items, 0..) |c, ci| {
        if (sk_nhits >= sk_hits.len) break;
        if (c.place.hidden) continue;
        const ms = skDimMeasure(s, c) orelse continue;
        const d = cdim.linear(ms, c.place, cdim.Style.screen(state.view.ppm / px, 0));
        const near = @min(skDist(d.text_at, q), segPointDist(d.line[0], d.line[1], q));
        if (near > radius) continue;
        sk_hits[sk_nhits] = .{ .pick = .{ .constraint = @intCast(ci) }, .at = d.text_at };
        sk_nhits += 1;
    }
    for (curves[0..ncurves]) |c| {
        if (sk_nhits >= sk_hits.len) break;
        sk_hits[sk_nhits] = c;
        sk_nhits += 1;
    }
}

/// How far point `q` is from the segment `a`–`b`.
fn segPointDist(a: geom.Point, b: geom.Point, q: geom.Point) f64 {
    const vx = b.x - a.x;
    const vy = b.y - a.y;
    const len2 = vx * vx + vy * vy;
    const t = if (len2 > 0) std.math.clamp(((q.x - a.x) * vx + (q.y - a.y) * vy) / len2, 0, 1) else 0;
    return skDist(.{ .x = a.x + t * vx, .y = a.y + t * vy }, q);
}

/// What the pointer is on: the locked hit, else the nearest.
fn skTarget() ?SkHit {
    if (sk_lock) |l| return l;
    if (sk_nhits > 0) return sk_hits[0];
    return null;
}

/// Where a click lands: on the locked point of interest, else at the
/// pointer.
fn skClickPoint() ?geom.Point {
    if (sk_lock) |l| return l.at;
    return sk_pointer;
}

// Drawing tools -----------------------------------------------------------------

fn skToolClicks(t: SkTool) usize {
    return switch (t) {
        .none => 0,
        .point => 1,
        .segment, .polyline, .circle, .line, .ray, .polar_array, .rect_array, .polygon => 2,
        .arc_centre, .arc_3pt, .circle_3pt => 3,
    };
}

/// A click of the drawing tool at `p`: geometry once it has its clicks.
fn skToolClick(p: geom.Point) void {
    sk_clicks[sk_nclicks] = p;
    sk_nclicks += 1;
    if (sk_nclicks < skToolClicks(sk_tool)) return;
    const c = sk_clicks;
    const cons = sk_construction;
    switch (sk_tool) {
        .none => {},
        .point => _ = skEdit(.{ .point = .{ .at = c[0], .construction = cons } }),
        .segment, .polyline => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .segment = .{ .a = c[0], .b = c[1], .construction = cons } });
        },
        .circle => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .circle = .{ .c = c[0], .r = skDist(c[0], c[1]), .construction = cons } });
        },
        .line => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .line = .{ .through = c[0], .angle = std.math.atan2(c[1].y - c[0].y, c[1].x - c[0].x) } });
        },
        .ray => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .ray = .{ .o = c[0], .angle = std.math.atan2(c[1].y - c[0].y, c[1].x - c[0].x) } });
        },
        // An array: its centre then its edge (its first border there), or
        // two corners; its counts from the array tool's.
        .polar_array => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .array = .{ .polar = true, .at = c[0], .to = c[1], .cols = array_tool.around, .rows = array_tool.rings, .sweep = array_tool.sweep } });
        },
        .rect_array => if (@abs(c[0].x - c[1].x) > 1e-9 and @abs(c[0].y - c[1].y) > 1e-9) {
            _ = skEdit(.{ .array = .{ .polar = false, .at = c[0], .to = c[1], .cols = array_tool.cols, .rows = array_tool.rows } });
        },
        // A regular polygon: its centre, then a corner.
        .polygon => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .polygon = .{ .c = c[0], .corner = c[1], .sides = polygon_sides, .construction = cons } });
        },
        .arc_centre => if (skDist(c[0], c[1]) > 1e-9) {
            _ = skEdit(.{ .arc = .{ .c = c[0], .a = c[1], .b = c[2], .construction = cons } });
        },
        .circle_3pt => if (circleThrough(c[0], c[1], c[2])) |centre| {
            _ = skEdit(.{ .circle = .{ .c = centre, .r = skDist(centre, c[0]), .construction = cons } });
        } else {
            state.status = "The three points are in line: no circle passes through them. ";
        },
        .arc_3pt => if (circleThrough(c[0], c[2], c[1])) |centre| {
            // From the first click to the second, through the third: the
            // way round that passes it, counter-clockwise.
            const a0 = std.math.atan2(c[0].y - centre.y, c[0].x - centre.x);
            const sweep = normAngle(std.math.atan2(c[1].y - centre.y, c[1].x - centre.x) - a0);
            const through = normAngle(std.math.atan2(c[2].y - centre.y, c[2].x - centre.x) - a0);
            if (through < sweep) {
                _ = skEdit(.{ .arc = .{ .c = centre, .a = c[0], .b = c[1], .construction = cons } });
            } else _ = skEdit(.{ .arc = .{ .c = centre, .a = c[1], .b = c[0], .construction = cons } });
        } else {
            state.status = "The three points are in line: no arc passes through them. ";
        },
    }
    // A polyline goes on from its last point; other tools start again.
    if (sk_tool == .polyline) {
        sk_clicks[0] = c[1];
        sk_nclicks = 1;
    } else sk_nclicks = 0;
}

/// The centre of the circle through three points; null when they are in
/// line.
fn circleThrough(a: geom.Point, b: geom.Point, c: geom.Point) ?geom.Point {
    const d = 2 * (a.x * (b.y - c.y) + b.x * (c.y - a.y) + c.x * (a.y - b.y));
    if (@abs(d) < 1e-12) return null;
    const a2 = a.x * a.x + a.y * a.y;
    const b2 = b.x * b.x + b.y * b.y;
    const c2 = c.x * c.x + c.y * c.y;
    return .{
        .x = (a2 * (b.y - c.y) + b2 * (c.y - a.y) + c2 * (a.y - b.y)) / d,
        .y = (a2 * (c.x - b.x) + b2 * (a.x - c.x) + c2 * (b.x - a.x)) / d,
    };
}

// Constraints from the selection --------------------------------------------------

const SkKind = enum { coincident, horizontal, vertical, point_on, distance, distance_x, distance_y, radius, angle, fixed, parallel, perpendicular, tangent, equal, symmetric };

const SkSelParts = struct {
    points: [8]skl.PointRef = undefined,
    np: usize = 0,
    curves: [8]skl.GeomId = undefined,
    nc: usize = 0,
};

fn skParts() SkSelParts {
    var out: SkSelParts = .{};
    for (sk_sel.items) |p| switch (p) {
        .point => |r| if (out.np < 8) {
            out.points[out.np] = r;
            out.np += 1;
        },
        .curve => |g| if (out.nc < 8) {
            out.curves[out.nc] = g;
            out.nc += 1;
        },
        .constraint => {},
    };
    return out;
}

fn skIsStraight(s: *const skl.Sketch, g: skl.GeomId) bool {
    return switch (s.geometry.items[g].kind) {
        .segment, .line, .ray => true,
        else => false,
    };
}

fn skIsRound(s: *const skl.Sketch, g: skl.GeomId) bool {
    return switch (s.geometry.items[g].kind) {
        .circle, .arc => true,
        else => false,
    };
}

/// The constraints `kind` makes from the selection: how many (0 when it
/// does not fit), into `out`.
fn skConstraintsFor(kind: SkKind, out: []skl.Constraint) usize {
    const it = skItem() orelse return 0;
    const s = it.sketch;
    const p = skParts();
    var n: usize = 0;
    switch (kind) {
        .coincident => if (p.np == 2 and p.nc == 0) {
            out[0] = .{ .kind = .{ .coincident = .{ p.points[0], p.points[1] } } };
            n = 1;
        },
        .horizontal, .vertical => {
            if (p.np == 2 and p.nc == 0) {
                const lin: skl.Linear = .{ .points = .{ p.points[0], p.points[1] } };
                out[0] = if (kind == .horizontal) .{ .kind = .{ .horizontal = lin } } else .{ .kind = .{ .vertical = lin } };
                n = 1;
            } else if (p.np == 0 and p.nc > 0) {
                for (p.curves[0..p.nc]) |g| {
                    if (!skIsStraight(s, g)) return 0;
                    out[n] = if (kind == .horizontal) .{ .kind = .{ .horizontal = .{ .geom = g } } } else .{ .kind = .{ .vertical = .{ .geom = g } } };
                    n += 1;
                }
            }
        },
        .point_on => if (p.np == 1 and p.nc == 1 and s.geometry.items[p.curves[0]].kind != .point) {
            out[0] = .{ .kind = .{ .point_on = .{ .p = p.points[0], .on = p.curves[0] } } };
            n = 1;
        },
        .distance, .distance_x, .distance_y => {
            var a: skl.PointRef = undefined;
            var b: skl.PointRef = undefined;
            if (p.np == 2 and p.nc == 0) {
                a = p.points[0];
                b = p.points[1];
            } else if (p.np == 0 and p.nc == 1 and s.geometry.items[p.curves[0]].kind == .segment) {
                a = .{ .geom = p.curves[0], .role = .start };
                b = .{ .geom = p.curves[0], .role = .end };
            } else if (kind == .distance and p.np == 1 and p.nc == 1 and skIsStraight(s, p.curves[0])) {
                const q = s.point(p.points[0]) catch return 0;
                const l = skLineOf(s, s.geometry.items[p.curves[0]]) orelse return 0;
                const d = @abs((q.x - l.p.x) * l.d.y - (q.y - l.p.y) * l.d.x);
                out[0] = .{ .kind = .{ .line_distance = .{ .p = p.points[0], .line = p.curves[0], .value = d } } };
                return 1;
            } else return 0;
            const pa = s.point(a) catch return 0;
            const pb = s.point(b) catch return 0;
            out[0] = switch (kind) {
                .distance => .{ .kind = .{ .distance = .{ .a = a, .b = b, .value = skDist(pa, pb) } } },
                .distance_x => .{ .kind = .{ .distance_x = .{ .a = a, .b = b, .value = pb.x - pa.x } } },
                else => .{ .kind = .{ .distance_y = .{ .a = a, .b = b, .value = pb.y - pa.y } } },
            };
            n = 1;
        },
        .radius => if (p.np == 0 and p.nc > 0) {
            for (p.curves[0..p.nc]) |g| {
                if (!skIsRound(s, g)) return 0;
                const r = switch (s.geometry.items[g].kind) {
                    .circle => |ci| s.vars.items[ci.r],
                    .arc => |ar| skDist(skVal(s, ar.a), skVal(s, ar.c)),
                    else => unreachable,
                };
                out[n] = .{ .kind = .{ .radius = .{ .g = g, .value = r } } };
                n += 1;
            }
        },
        .angle => if (p.np == 0 and (p.nc == 1 or p.nc == 2)) {
            const ga = if (p.nc == 2) p.curves[0] else skl.h_axis;
            const gb = p.curves[p.nc - 1];
            if (!skIsStraight(s, ga) or !skIsStraight(s, gb)) return 0;
            const la = skLineOf(s, s.geometry.items[ga]) orelse return 0;
            const lb = skLineOf(s, s.geometry.items[gb]) orelse return 0;
            const v = std.math.atan2(la.d.x * lb.d.y - la.d.y * lb.d.x, la.d.x * lb.d.x + la.d.y * lb.d.y);
            out[0] = .{ .kind = .{ .angle = .{ .a = ga, .b = gb, .value = v } } };
            n = 1;
        },
        .fixed => if (p.np > 0 and p.nc == 0) {
            for (p.points[0..p.np]) |r| {
                out[n] = .{ .kind = .{ .fixed = .{ .p = r, .at = s.point(r) catch return 0 } } };
                n += 1;
            }
        },
        .parallel, .perpendicular => if (p.np == 0 and p.nc == 2 and skIsStraight(s, p.curves[0]) and skIsStraight(s, p.curves[1])) {
            out[0] = if (kind == .parallel) .{ .kind = .{ .parallel = .{ .a = p.curves[0], .b = p.curves[1] } } } else .{ .kind = .{ .perpendicular = .{ .a = p.curves[0], .b = p.curves[1] } } };
            n = 1;
        },
        .tangent => if (p.np == 0 and p.nc == 2) {
            const a = p.curves[0];
            const b = p.curves[1];
            const ok = (skIsRound(s, a) and skIsRound(s, b)) or (skIsRound(s, a) and skIsStraight(s, b)) or (skIsStraight(s, a) and skIsRound(s, b));
            if (ok) {
                out[0] = .{ .kind = .{ .tangent = .{ .a = a, .b = b } } };
                n = 1;
            }
        },
        // The first with each of the others: all segments, or all round.
        .equal => if (p.np == 0 and p.nc >= 2) {
            const round = skIsRound(s, p.curves[0]);
            for (p.curves[0..p.nc]) |g| {
                if (round != skIsRound(s, g)) return 0;
                if (!round and s.geometry.items[g].kind != .segment) return 0;
            }
            for (p.curves[1..p.nc]) |g| {
                out[n] = .{ .kind = .{ .equal = .{ .a = p.curves[0], .b = g } } };
                n += 1;
            }
        },
        // Two points about a straight geometry, or about a third point.
        .symmetric => {
            if (p.np == 2 and p.nc == 1 and skIsStraight(s, p.curves[0])) {
                out[0] = .{ .kind = .{ .symmetric = .{ .p = p.points[0], .q = p.points[1], .line = p.curves[0] } } };
                n = 1;
            } else if (p.np == 3 and p.nc == 0) {
                out[0] = .{ .kind = .{ .symmetric = .{ .p = p.points[0], .q = p.points[1], .point = p.points[2] } } };
                n = 1;
            }
        },
    }
    return n;
}

/// Adds the constraints `kind` makes from the selection; a dimension then
/// opens for its value.
fn skConstrain(kind: SkKind, area: dvui.Rect.Physical) void {
    var buf: [8]skl.Constraint = undefined;
    const n = skConstraintsFor(kind, &buf);
    if (n == 0) {
        state.status = "That constraint does not fit what is selected. ";
        return;
    }
    var last: ?u32 = null;
    for (buf[0..n]) |c| last = skEdit(.{ .constrain = c });
    sk_sel.clearRetainingCapacity();
    if (last) |id| switch (kind) {
        .distance, .distance_x, .distance_y, .radius, .angle => {
            const at = skDimAnchor(area, id) orelse dvui.Point.Physical{ .x = area.x + area.w / 2, .y = area.y + area.h / 2 };
            sk_dim = .{ .c = id, .at = at };
        },
        else => {},
    };
}

/// A constraint's value as shown: lengths in the document's units, angles
/// in degrees.
fn skShownValue(c: skl.Constraint) ?f64 {
    return switch (c.kind) {
        inline .distance, .distance_x, .distance_y => |d| d.value * docUnits().perMm(),
        .line_distance => |d| d.value * docUnits().perMm(),
        .radius => |r| r.value * docUnits().perMm(),
        .angle => |a| a.value * 180 / std.math.pi,
        else => null,
    };
}

/// Where an angle between two segments is marked: inside the corner
/// where their nearest ends meet, a little way towards their middles.
fn skCornerAnchor(s: *const skl.Sketch, a: skl.GeomId, b: skl.GeomId) ?geom.Point {
    if (a >= s.geometry.items.len or b >= s.geometry.items.len) return null;
    const sa = switch (s.geometry.items[a].kind) {
        .segment => |sg| [2]geom.Point{ skVal(s, sg.a), skVal(s, sg.b) },
        else => return null,
    };
    const sb = switch (s.geometry.items[b].kind) {
        .segment => |sg| [2]geom.Point{ skVal(s, sg.a), skVal(s, sg.b) },
        else => return null,
    };
    var q = skMid(sa[0], sb[0]);
    var bd: f64 = std.math.inf(f64);
    for (sa) |pa| for (sb) |pb| {
        const d = skDist(pa, pb);
        if (d < bd) {
            bd = d;
            q = skMid(pa, pb);
        }
    };
    const m = skMid(skMid(sa[0], sa[1]), skMid(sb[0], sb[1]));
    return .{ .x = q.x + 0.9 * (m.x - q.x), .y = q.y + 0.9 * (m.y - q.y) };
}

/// Sets of equal sizes and angles in a sketch (the owner, 2026-11-24:
/// where a number of values are equal, one annotation: θ = 108°, s =
/// 10.48): the equal and equal-angle constraints joined into sets by what
/// they share, each set named (s, s′, s″ for lengths; r … for radii; θ …
/// for angles), each member marked with the equal symbol (= for sizes, ≅ for angles; the
/// owner: the user will know what θ and s mean), the value noted once.
const EqualSets = struct {
    const Member = struct { kind: enum { len, radius, angle }, a: skl.GeomId, b: skl.GeomId = 0 };
    members: std.ArrayList(Member) = .empty,
    parent: std.ArrayList(usize) = .empty,
    /// Each member's set (its root's index into `names`).
    set_of: []usize = &.{},
    names: std.ArrayList([]const u8) = .empty,
    /// Per set: its kind's member, for the value.
    first: std.ArrayList(usize) = .empty,

    fn find(e: *EqualSets, i: usize) usize {
        var x = i;
        while (e.parent.items[x] != x) x = e.parent.items[x];
        return x;
    }

    fn add(e: *EqualSets, ar: std.mem.Allocator, m: Member) usize {
        for (e.members.items, 0..) |x, i| if (std.meta.eql(x, m)) return i;
        e.members.append(ar, m) catch return 0;
        e.parent.append(ar, e.members.items.len - 1) catch {};
        return e.members.items.len - 1;
    }

    fn pair(c: skl.Constraint, s: *const skl.Sketch) ?[2]Member {
        return switch (c.kind) {
            .equal => |q| blk: {
                const round = q.a < s.geometry.items.len and s.geometry.items[q.a].kind != .segment;
                const k: @FieldType(Member, "kind") = if (round) .radius else .len;
                break :blk .{ .{ .kind = k, .a = q.a }, .{ .kind = k, .a = q.b } };
            },
            .equal_angle => |q| .{ .{ .kind = .angle, .a = q.a, .b = q.b }, .{ .kind = .angle, .a = q.c, .b = q.d } },
            else => null,
        };
    }

    fn build(e: *EqualSets, ar: std.mem.Allocator, s: *const skl.Sketch) void {
        for (s.constraints.items) |c| {
            const pr = pair(c, s) orelse continue;
            const i = e.add(ar, pr[0]);
            const j = e.add(ar, pr[1]);
            if (i >= e.parent.items.len or j >= e.parent.items.len) continue;
            const ri = e.find(i);
            const rj = e.find(j);
            if (ri != rj) e.parent.items[rj] = ri;
        }
        e.set_of = ar.alloc(usize, e.members.items.len) catch return;
        var roots: std.ArrayList(usize) = .empty;
        var counts = [3]usize{ 0, 0, 0 };
        for (e.members.items, 0..) |m, i| {
            const r = e.find(i);
            const k = for (roots.items, 0..) |x, n| {
                if (x == r) break n;
            } else blk: {
                roots.append(ar, r) catch return;
                const base: []const u8 = switch (m.kind) {
                    .len => "s",
                    .radius => "r",
                    .angle => "θ",
                };
                const n = counts[@intFromEnum(m.kind)];
                counts[@intFromEnum(m.kind)] += 1;
                const name = switch (n) {
                    0 => base,
                    1 => std.fmt.allocPrint(ar, "{s}′", .{base}) catch base,
                    2 => std.fmt.allocPrint(ar, "{s}″", .{base}) catch base,
                    else => std.fmt.allocPrint(ar, "{s}{d}", .{ base, n + 1 }) catch base,
                };
                e.names.append(ar, name) catch return;
                e.first.append(ar, i) catch return;
                break :blk roots.items.len - 1;
            };
            e.set_of[i] = k;
        }
    }
};

/// Where a set member is marked, in the sketch's frame.
fn skMemberAt(s: *const skl.Sketch, m: EqualSets.Member) ?geom.Point {
    if (m.a >= s.geometry.items.len) return null;
    return switch (m.kind) {
        .angle => skCornerAnchor(s, m.a, m.b),
        .len => switch (s.geometry.items[m.a].kind) {
            .segment => |sg| skMid(skVal(s, sg.a), skVal(s, sg.b)),
            else => null,
        },
        .radius => switch (s.geometry.items[m.a].kind) {
            .circle => |ci| blk: {
                const cc = skVal(s, ci.c);
                const r = s.vars.items[ci.r];
                break :blk .{ .x = cc.x + r * 0.7071, .y = cc.y + r * 0.7071 };
            },
            .arc => |a| skArcMid(skVal(s, a.c), skVal(s, a.a), skVal(s, a.b)),
            else => null,
        },
    };
}

/// A set's value now: a length or radius (document units), or an angle
/// (degrees, 0 to 180).
fn skMemberValue(s: *const skl.Sketch, m: EqualSets.Member) ?f64 {
    if (m.a >= s.geometry.items.len) return null;
    return switch (m.kind) {
        .angle => blk: {
            var v = s.measure(.{ .kind = .{ .angle = .{ .a = m.a, .b = m.b, .value = 0 } } }) orelse return null;
            if (v < 0) v += std.math.pi;
            break :blk v * 180 / std.math.pi;
        },
        .len => switch (s.geometry.items[m.a].kind) {
            .segment => |sg| skDist(skVal(s, sg.a), skVal(s, sg.b)) * docUnits().perMm(),
            else => null,
        },
        .radius => switch (s.geometry.items[m.a].kind) {
            .circle => |ci| s.vars.items[ci.r] * docUnits().perMm(),
            .arc => |a| skDist(skVal(s, a.c), skVal(s, a.a)) * docUnits().perMm(),
            else => null,
        },
    };
}

/// Each equal set's members marked with its name, and its value noted
/// once, at the middle of its members (sets meeting there stacked).
fn skDrawEqualSets(area: dvui.Rect.Physical, it: SkPlace, e: *const EqualSets) void {
    const s = it.sketch;
    const px = dvui.windowNaturalScale();
    const colour = colors.guide;
    for (e.members.items) |m| {
        const at = skMemberAt(s, m) orelse continue;
        const q = skPx(area, it, at);
        // The equal constraint's own symbol; the note names the set.
        const mark: []const u8 = if (m.kind == .angle) "≅" else "=";
        strokeText(mark, .{ .at = .{ .x = q.x, .y = q.y }, .size = dim_cap * px, .y_down = true, .align_x = 0.5, .align_y = 0.5 }, colour);
    }
    var placed: std.ArrayList(dvui.Point.Physical) = .empty;
    const ar = dvui.currentWindow().arena();
    for (e.names.items, 0..) |name, k| {
        var sum: geom.Point = .{ .x = 0, .y = 0 };
        var n: f64 = 0;
        for (e.members.items, 0..) |m, i| {
            if (e.set_of[i] != k) continue;
            const at = skMemberAt(s, m) orelse continue;
            sum.x += at.x;
            sum.y += at.y;
            n += 1;
        }
        if (n == 0) continue;
        var q = skPx(area, it, .{ .x = sum.x / n, .y = sum.y / n });
        // Below the middle (a centre point is often there), clear of any
        // note already there.
        q.y += 2 * dim_cap * px;
        for (placed.items) |o| if (@abs(o.x - q.x) < 40 * px and @abs(o.y - q.y) < 1.8 * dim_cap * px) {
            q.y = o.y + 1.8 * dim_cap * px;
        };
        placed.append(ar, q) catch {};
        const m = e.members.items[e.first.items[k]];
        const v = skMemberValue(s, m) orelse continue;
        var buf: [48]u8 = undefined;
        const text = if (m.kind == .angle)
            std.fmt.bufPrint(&buf, "{s} = {d:.1}°", .{ name, v }) catch name
        else
            std.fmt.bufPrint(&buf, "{s} = {d:.2}", .{ name, v }) catch name;
        strokeText(text, .{ .at = .{ .x = q.x, .y = q.y }, .size = dim_cap * px, .y_down = true, .align_x = 0.5, .align_y = 0.5 }, colour);
    }
}

/// What equal angles come to now (degrees, 0 to 180): the second
/// angle's reading, as lines (modulo a half turn).
fn skEqualAngle(c: skl.Constraint) ?f64 {
    const e = switch (c.kind) {
        .equal_angle => |x| x,
        else => return null,
    };
    const it = skItem() orelse return null;
    var v = it.sketch.measure(.{ .kind = .{ .angle = .{ .a = e.c, .b = e.d, .value = 0 } } }) orelse return null;
    if (v < 0) v += std.math.pi;
    return v * 180 / std.math.pi;
}

fn skFromShown(c: skl.Constraint, v: f64) f64 {
    return switch (c.kind) {
        .angle => v * std.math.pi / 180,
        else => v / docUnits().perMm(),
    };
}

fn skConstraintText(buf: []u8, c: skl.Constraint) []const u8 {
    const unit = docUnits().symbol();
    const name: []const u8 = switch (c.kind) {
        .coincident => "Coincident",
        .horizontal => "Horizontal",
        .vertical => "Vertical",
        .point_on => "On object",
        .fixed => "Locked",
        .distance => "Distance",
        .distance_x => "Horizontal distance",
        .distance_y => "Vertical distance",
        .line_distance => "Distance to line",
        .radius => "Radius",
        .angle => "Angle",
        .parallel => "Parallel",
        .perpendicular => "Perpendicular",
        .tangent => "Tangent",
        .equal => "Equal",
        .symmetric => "Symmetric",
        .equal_distance => "Equal distance",
        .equal_angle => "Equal angles",
    };
    // Implied: shown, not solved (it follows from the rest).
    if (!c.driving and !c.isDimension()) {
        if (c.kind == .equal_angle) if (skEqualAngle(c)) |v| return std.fmt.bufPrint(buf, "{s}, implied ({d:.3}°)", .{ name, v }) catch name;
        return std.fmt.bufPrint(buf, "{s}, implied", .{name}) catch name;
    }
    // Equal angles: what they come to, followed (in parentheses).
    if (c.kind == .equal_angle) if (skEqualAngle(c)) |v| return std.fmt.bufPrint(buf, "{s} ({d:.3}°)", .{ name, v }) catch name;
    if (skShownValue(c)) |v| {
        const u = if (c.kind == .angle) "°" else unit;
        // A reference dimension in parentheses; an expression before what
        // it comes to.
        const open: []const u8 = if (c.driving) "" else "(";
        const close: []const u8 = if (c.driving) "" else ")";
        if (c.expr.len > 0) return std.fmt.bufPrint(buf, "{s}{s} = {s}  ({d:.3}{s}){s}", .{ open, name, c.expr, v, u, close }) catch name;
        return std.fmt.bufPrint(buf, "{s}{s} {d:.3}{s}{s}", .{ open, name, v, u, close }) catch name;
    }
    return name;
}

/// Where a constraint's glyph or value is drawn, on the screen.
fn skDimAnchor(area: dvui.Rect.Physical, id: skl.ConstraintId) ?dvui.Point.Physical {
    const it = skItem() orelse return null;
    const p = skAnchor(it.sketch, it.sketch.constraints.items[id]) orelse return null;
    return skPx(area, it, p);
}

fn skMid(a: geom.Point, b: geom.Point) geom.Point {
    return .{ .x = (a.x + b.x) / 2, .y = (a.y + b.y) / 2 };
}

/// A constraint's anchor in the sketch's frame.
/// A radius's leader: the centre of circle or arc `g` and the point of the
/// curve it passes through (a circle's at 45°, an arc's middle).
fn skRadiusLeader(s: *const skl.Sketch, g: skl.GeomId) ?struct { centre: geom.Point, on: geom.Point } {
    if (g >= s.geometry.items.len) return null;
    switch (s.geometry.items[g].kind) {
        .circle => |ci| {
            const cc = skVal(s, ci.c);
            const r = s.vars.items[ci.r];
            return .{ .centre = cc, .on = .{ .x = cc.x + r * 0.7071, .y = cc.y + r * 0.7071 } };
        },
        .arc => |ar| {
            const cc = skVal(s, ar.c);
            return .{ .centre = cc, .on = skArcMid(cc, skVal(s, ar.a), skVal(s, ar.b)) };
        },
        else => return null,
    }
}

/// The middle of the arc about `c` from `a` to `b` (anticlockwise).
fn skArcMid(c: geom.Point, a: geom.Point, b: geom.Point) geom.Point {
    const r = skDist(c, a);
    const t0 = std.math.atan2(a.y - c.y, a.x - c.x);
    var sweep = std.math.atan2(b.y - c.y, b.x - c.x) - t0;
    if (sweep <= 0) sweep += 2 * std.math.pi;
    const t = t0 + sweep / 2;
    return .{ .x = c.x + r * @cos(t), .y = c.y + r * @sin(t) };
}

const cdim = skl.constraint.dimension;

/// What a sketch distance measures, for drawing it after drafting practice
/// (`graven_constraint`'s dimensions): a horizontal or vertical distance
/// along its axis, its line placed up or left; an aligned one along the
/// points' join, placed to its left.
fn skDimMeasure(s: *const skl.Sketch, c: skl.Constraint) ?cdim.Measure {
    switch (c.kind) {
        inline .distance, .distance_x, .distance_y => |d| {
            const pa = s.point(d.a) catch return null;
            const pb = s.point(d.b) catch return null;
            return switch (c.kind) {
                .distance_x => .{ .p0 = pa, .p1 = pb, .dir = .{ .x = 1, .y = 0 }, .normal = .{ .x = 0, .y = 1 } },
                .distance_y => .{ .p0 = pa, .p1 = pb, .dir = .{ .x = 0, .y = 1 }, .normal = .{ .x = -1, .y = 0 } },
                else => blk: {
                    const len = skDist(pa, pb);
                    const u: geom.Point = if (len > 1e-12) .{ .x = (pb.x - pa.x) / len, .y = (pb.y - pa.y) / len } else .{ .x = 1, .y = 0 };
                    break :blk .{ .p0 = pa, .p1 = pb, .dir = u, .normal = .{ .x = -u.y, .y = u.x } };
                },
            };
        },
        else => return null,
    }
}

/// A dimension drawn after drafting practice: extension lines, the
/// dimension line, filled arrowheads and its value, in screen sizes.
/// The measure's frame is the workspace's moved by `at` (a sketch's
/// origin; 0 for a layout's).
fn drawDimension(area: dvui.Rect.Physical, at: geom.Point, ms: cdim.Measure, place: cdim.Placement, text: []const u8, colour: dvui.Color, hot: bool) void {
    const it = struct {
        at: geom.Point,
    }{ .at = at };
    const px = dvui.windowNaturalScale();
    const w = strokefont.width(text) * dim_cap * px;
    const d = cdim.linear(ms, place, cdim.Style.screen(state.view.ppm / px, w / px));
    const thin: dvui.ColorOrGradient = .{ .color = colour.opacity(0.7) };
    for (d.ext) |e| if (e) |pts| {
        dvui.Path.stroke(.{ .points = &.{ skPx(area, it, pts[0]), skPx(area, it, pts[1]) } }, .{ .thickness = px, .color = thin });
    };
    dvui.Path.stroke(.{ .points = &.{ skPx(area, it, d.line[0]), skPx(area, it, d.line[1]) } }, .{ .thickness = if (hot) 2 * px else px, .color = thin });
    if (d.arrows) |arrows| for (arrows) |a| {
        const pts = [_]dvui.Point.Physical{ skPx(area, it, a.tip), skPx(area, it, a.wings[0]), skPx(area, it, a.wings[1]) };
        dvui.Path.fillConvex(.{ .points = &pts }, .{ .color = .{ .color = colour } });
    };
    // The value on its line, upright, at its place.
    const q0 = skPx(area, it, d.text_at);
    const q1 = skPx(area, it, .{ .x = d.text_at.x + d.text_dir.x, .y = d.text_at.y + d.text_dir.y });
    var pl = alongPlace(q0, q1, 0);
    pl.at = .{ .x = q0.x, .y = q0.y };
    strokeText(text, pl, colour);
}

fn skAnchor(s: *const skl.Sketch, c: skl.Constraint) ?geom.Point {
    const curveMid = struct {
        fn f(sk_: *const skl.Sketch, g: skl.GeomId) ?geom.Point {
            if (g >= sk_.geometry.items.len) return null;
            const geo = sk_.geometry.items[g];
            return switch (geo.kind) {
                .segment => |sg| skMid(skVal(sk_, sg.a), skVal(sk_, sg.b)),
                .circle => |ci| blk: {
                    const cc = skVal(sk_, ci.c);
                    break :blk .{ .x = cc.x + sk_.vars.items[ci.r] * 0.7071, .y = cc.y + sk_.vars.items[ci.r] * 0.7071 };
                },
                .arc => |ar| skArcMid(skVal(sk_, ar.c), skVal(sk_, ar.a), skVal(sk_, ar.b)),
                .ray => |ry| skVal(sk_, ry.o),
                .line => |ln| blk: {
                    const th = sk_.vars.items[ln.theta];
                    const rho = sk_.vars.items[ln.rho];
                    break :blk .{ .x = rho * @cos(th), .y = rho * @sin(th) };
                },
                .point => |pp| skVal(sk_, pp),
                .affine => .{ .x = 0, .y = 0 },
            };
        }
    }.f;
    return switch (c.kind) {
        .coincident => |ps| s.point(ps[0]) catch null,
        .horizontal, .vertical => |l| switch (l) {
            .geom => |g| curveMid(s, g),
            .points => |ps| skMid(s.point(ps[0]) catch return null, s.point(ps[1]) catch return null),
        },
        .point_on => |po| s.point(po.p) catch null,
        .fixed => |f| s.point(f.p) catch null,
        .distance, .distance_x, .distance_y => blk: {
            const ms = skDimMeasure(s, c) orelse break :blk null;
            // Where its value sits, as placed (the drafting rules may move a
            // value that does not fit; this is where it is picked).
            const d = cdim.linear(ms, c.place, cdim.Style.screen(state.view.ppm / dvui.windowNaturalScale(), 0));
            break :blk d.text_at;
        },
        .line_distance => |d| s.point(d.p) catch null,
        .radius => |r| curveMid(s, r.g),
        .angle => |a| curveMid(s, a.b),
        inline .parallel, .perpendicular, .tangent, .equal => |a| curveMid(s, a.b),
        // Within the corner of its second angle.
        .equal_angle => |e| skCornerAnchor(s, e.c, e.d),
        .symmetric => |sy| skMid(s.point(sy.p) catch return null, s.point(sy.q) catch return null),
        .equal_distance => |e| switch (e.b) {
            .points, .x, .y => |ps| skMid(s.point(ps[0]) catch return null, s.point(ps[1]) catch return null),
            .to_line => |t| s.point(t.p) catch null,
        },
    };
}

// Events ----------------------------------------------------------------------------

/// Takes every canvas event while sketch mode is on.
fn sketchEvent(e: *dvui.Event, box: *dvui.BoxWidget, area: dvui.Rect.Physical) void {
    const it = skItem() orelse {
        leaveSketch();
        return;
    };
    if (e.handled) return;
    if (e.evt == .key) {
        // Keys reach the sketch only while the canvas has the keyboard (a
        // dimension's entry takes its own).
        if (!cursorKeysReach()) return;
        if (sk_summary) {
            const inv = keymap.match1(e, kmode("sketch.summary")) orelse return;
            switch (inv.action) {
                kact("sketch.summary.leave") => leaveSketch(),
                kact("sketch.summary.back") => sk_summary = false,
                else => return,
            }
            e.handle(@src(), box.data());
            dvui.refresh(null, @src(), box.data().id);
            return;
        }
        // Ctrl or Cmd with a letter is the app's (undo, copy), not a
        // constraint: the sketch's letters are bound unchorded.
        const inv = keymap.match1(e, kmode("sketch")) orelse return;
        var used = true;
        switch (inv.action) {
            kact("sketch.tab") => skTab(area, inv.arg == 1),
            kact("sketch.cancel") => {
                if (sk_lock != null) {
                    sk_lock = null;
                } else if (sk_nclicks > 0) {
                    sk_nclicks = 0;
                } else if (sk_tool != .none) {
                    sk_tool = .none;
                } else sk_sel.clearRetainingCapacity();
            },
            kact("sketch.finish") => {
                sk_nclicks = 0;
                sk_summary = true;
            },
            kact("sketch.delete") => skDeleteSelection(),
            kact("sketch.constraint.coincident") => skConstrain(.coincident, area),
            kact("sketch.constraint.horizontal") => skConstrain(.horizontal, area),
            kact("sketch.constraint.vertical") => skConstrain(.vertical, area),
            kact("sketch.constraint.point-on") => skConstrain(.point_on, area),
            kact("sketch.constraint.tangent") => skConstrain(.tangent, area),
            kact("sketch.constraint.perpendicular") => skConstrain(.perpendicular, area),
            kact("sketch.constraint.equal") => skConstrain(.equal, area),
            kact("sketch.constraint.distance") => skConstrain(.distance, area),
            kact("sketch.constraint.radius") => skConstrain(.radius, area),
            kact("sketch.constraint.angle") => skConstrain(.angle, area),
            kact("sketch.constraint.lock") => skConstrain(.fixed, area),
            kact("sketch.tool.next") => skCycleTool(),
            kact("sketch.ink") => skInk(),
            kact("sketch.fill") => skFill(),
            kact("sketch.end.update") => if (sketch_edit) |r| skAccept(r.sketch),
            kact("sketch.end.discard") => skDiscard(),
            else => used = false,
        }
        if (used) {
            e.handle(@src(), box.data());
            dvui.refresh(null, @src(), box.data().id);
        }
        return;
    }
    if (e.evt != .mouse) return;
    // Only the canvas's own: a click in a pane is the pane's.
    if (!dvui.eventMatchSimple(e, box.data())) return;
    const me = e.evt.mouse;
    const at_space = state.view.toMm(area, me.p);
    const q = skLocal(it, at_space);
    switch (me.action) {
        .focus => {
            e.handle(@src(), box.data());
            dvui.focusWidget(box.data().id, null, e.num);
        },
        .position => {
            // A position event comes every frame: redrawn only when the
            // pointer has moved.
            const moved = me.p.x != sk_last_px.x or me.p.y != sk_last_px.y;
            sk_last_px = me.p;
            state.mouse = at_space;
            sk_pointer = q;
            const radius = 10 * dvui.windowNaturalScale() / state.view.ppm;
            skFindHits(it.sketch, q, radius);
            // A lock lets go when the pointer goes well away.
            if (sk_lock != null) {
                const dx = me.p.x - sk_lock_px.x;
                const dy = me.p.y - sk_lock_px.y;
                if (dx * dx + dy * dy > 60 * 60 * dvui.windowNaturalScale() * dvui.windowNaturalScale()) sk_lock = null;
            }
            dvui.cursorSet(if (sk_tool != .none) .crosshair else .arrow);
            if (moved) dvui.refresh(null, @src(), box.data().id);
        },
        .press => if (area.contains(me.p)) {
            e.handle(@src(), box.data());
            dvui.captureMouse(box.data(), e.num);
            if (me.button == .middle) {
                dvui.dragPreStart(me.button, me.p, .{});
                return;
            }
            if (!me.button.pointer() or sk_summary) return;
            if (sk_tool != .none) {
                if (skClickPoint()) |p| skToolClick(p);
                sk_lock = null;
                return;
            }
            sk_press_ctrl = primaryMod(me.mod);
            const target = skTarget();
            if (target != null and target.?.pick == .point and !sk_press_ctrl) {
                sk_drag = .{ .p = target.?.pick.point, .moved = false, .start = q };
                sk_drag_seq += 1;
            } else if (target != null and target.?.pick == .constraint and !sk_press_ctrl and target.?.pick.constraint < it.sketch.constraints.items.len and skDimMeasure(it.sketch, it.sketch.constraints.items[target.?.pick.constraint]) != null) {
                sk_drag_seq += 1;
                sk_dim_drag = .{ .c = target.?.pick.constraint, .moved = false, .start = q, .seq = sk_drag_seq };
            } else sk_box = .{ .start = q, .at = q };
        },
        .motion => if (dvui.captured(box.data().id)) {
            e.handle(@src(), box.data());
            if (sk_drag) |*d| {
                const moved_px = skDist(d.start, q) * state.view.ppm;
                if (d.moved or moved_px > 3) {
                    d.moved = true;
                    const r = sketch_edit.?;
                    _ = actM(mergeKey(.{ "skdrag", sk_drag_seq }), .editSketchDraft, .{ r.sketch, .{ .drag = .{ .p = d.p, .to = q } } }) catch {};
                }
            } else if (sk_dim_drag) |*d| {
                const moved_px = skDist(d.start, q) * state.view.ppm;
                if (d.moved or moved_px > 3) {
                    d.moved = true;
                    const c = it.sketch.constraints.items[d.c];
                    if (skDimMeasure(it.sketch, c)) |ms| {
                        const r = sketch_edit.?;
                        _ = actM(mergeKey(.{ "skdim", d.seq }), .editSketchDraft, .{ r.sketch, .{ .place = .{ .c = d.c, .place = cdim.withinReach(ms, cdim.textAt(ms, c.place, q), dimReach()) } } }) catch {};
                    }
                }
            } else if (sk_box) |*b| {
                b.at = q;
            } else if (dvui.dragging(me, null)) |d| {
                state.view.fit = null;
                state.view.cx -= d.x / state.view.ppm;
                state.view.cy += d.y / state.view.ppm;
            }
            dvui.refresh(null, @src(), box.data().id);
        },
        .release => if (dvui.captured(box.data().id)) {
            e.handle(@src(), box.data());
            if (sk_drag) |d| {
                if (!d.moved) skClickSelect(.{ .point = d.p }, false);
                sk_drag = null;
            } else if (sk_dim_drag) |d| {
                if (!d.moved) skClickSelect(.{ .constraint = d.c }, false);
                sk_dim_drag = null;
            } else if (sk_box) |b| {
                sk_box = null;
                if (skDist(b.start, b.at) * state.view.ppm < 4) {
                    if (skTarget()) |t| skClickSelect(t.pick, sk_press_ctrl) else if (!sk_press_ctrl) sk_sel.clearRetainingCapacity();
                } else skBoxSelect(it.sketch, b.start, b.at, sk_press_ctrl);
            }
            sk_lock = null;
            dvui.captureMouse(null, e.num);
            dvui.dragEnd(me.button);
            dvui.refresh(null, @src(), box.data().id);
        },
        else => {},
    }
}

/// Tab: locks the pointer onto the nearest point of interest, then the
/// next-closest (Shift+Tab back), round.
fn skTab(area: dvui.Rect.Physical, back: bool) void {
    const it = skItem() orelse return;
    if (sk_nhits == 0) return;
    if (sk_lock == null) {
        sk_lock_index = 0;
    } else if (back) {
        sk_lock_index = if (sk_lock_index == 0) sk_nhits - 1 else sk_lock_index - 1;
    } else sk_lock_index = (sk_lock_index + 1) % sk_nhits;
    sk_lock = sk_hits[sk_lock_index];
    sk_lock_px = skPx(area, it, sk_lock.?.at);
}

/// A click on `p`: it alone is selected, or with Ctrl it goes in or out.
fn skClickSelect(p: SkPick, toggle: bool) void {
    for (sk_sel.items, 0..) |x, i| if (std.meta.eql(x, p)) {
        if (toggle) _ = sk_sel.orderedRemove(i);
        return;
    };
    if (!toggle) sk_sel.clearRetainingCapacity();
    sk_sel.append(state.gpa, p) catch {};
}

/// Selects every point and whole curve inside the box.
fn skBoxSelect(s: *const skl.Sketch, a: geom.Point, b: geom.Point, add: bool) void {
    if (!add) sk_sel.clearRetainingCapacity();
    const x0 = @min(a.x, b.x);
    const x1 = @max(a.x, b.x);
    const y0 = @min(a.y, b.y);
    const y1 = @max(a.y, b.y);
    const inside = struct {
        fn f(p: geom.Point, bx: [4]f64) bool {
            return p.x >= bx[0] and p.x <= bx[1] and p.y >= bx[2] and p.y <= bx[3];
        }
    }.f;
    const bx = [4]f64{ x0, x1, y0, y1 };
    for (s.geometry.items, 0..) |g, gi| {
        if (g.removed or g.reference) continue;
        var buf: [3]skl.PointRef = undefined;
        const pts = skPointsOf(g, &buf, @intCast(gi));
        var all = pts.len > 0 and g.kind != .ray;
        for (pts) |r| {
            const p = s.point(r) catch continue;
            if (inside(p, bx)) sk_sel.append(state.gpa, .{ .point = r }) catch {} else all = false;
        }
        if (g.kind == .circle) {
            const c = skVal(s, g.kind.circle.c);
            const r = s.vars.items[g.kind.circle.r];
            all = inside(.{ .x = c.x - r, .y = c.y - r }, bx) and inside(.{ .x = c.x + r, .y = c.y + r }, bx);
        }
        if (all and g.kind != .point) sk_sel.append(state.gpa, .{ .curve = @intCast(gi) }) catch {};
    }
}

/// Removes the selected constraints, then the selected geometry (with
/// its constraints).
fn skDeleteSelection() void {
    const it = skItem() orelse return;
    var cons: std.ArrayList(skl.ConstraintId) = .empty;
    defer cons.deinit(state.gpa);
    var geos: std.ArrayList(skl.GeomId) = .empty;
    defer geos.deinit(state.gpa);
    for (sk_sel.items) |p| switch (p) {
        .constraint => |c| cons.append(state.gpa, c) catch {},
        .curve => |g| geos.append(state.gpa, g) catch {},
        .point => |r| if (r.role == .point) geos.append(state.gpa, r.geom) catch {},
    };
    // Constraints last first, so the indices hold.
    std.mem.sort(skl.ConstraintId, cons.items, {}, std.sort.desc(skl.ConstraintId));
    for (cons.items) |c| _ = skEdit(.{ .unconstrain = c });
    for (geos.items) |g| {
        if (g < it.sketch.geometry.items.len and !it.sketch.geometry.items[g].reference and !it.sketch.geometry.items[g].removed) _ = skEdit(.{ .remove = g });
    }
    sk_sel.clearRetainingCapacity();
}

fn skSelected(p: SkPick) bool {
    for (sk_sel.items) |x| if (std.meta.eql(x, p)) return true;
    return false;
}

// Drawing ------------------------------------------------------------------------------

/// The shown space's sketches, other than the one being edited: what is
/// output, and their construction faintly within their boxes.
fn drawSketches(area: dvui.Rect.Physical) void {
    if (shown_space >= state.model.spaces.items.len) return;
    const px = dvui.windowNaturalScale();
    for (state.model.spaces.items[shown_space].sketch_views.items, 0..) |v, i| {
        const ref: SketchRef = .{ .space = shown_space, .index = i };
        const it = viewPlace(shown_space, i) orelse continue;
        // The one being edited draws in sketch mode.
        if (sketch_edit) |e| if (e.space == shown_space and state.model.sketchIndex(v.sketch) == e.sketch and e.at.x == v.at.x and e.at.y == v.at.y) continue;
        const b = sketchBox(it) orelse continue;
        // Construction, clipped to the box (display only).
        {
            const r = state.view.rect(area, b);
            const clip = dvui.clip(r);
            defer dvui.clipSet(clip);
            for (it.sketch.geometry.items) |g| {
                if (g.removed or g.reference or !g.construction) continue;
                skDrawGeometry(area, it, g, colors.guide.opacity(0.35), px, true);
            }
        }
        for (it.sketch.geometry.items) |g| {
            if (g.removed or g.reference or g.construction) continue;
            skDrawGeometry(area, it, g, colors.ink, 1.5 * px, false);
        }
        drawSketchFigure(area, it, 1);
        const picked = switch (state.context) {
            .sketch => |sc| sc.space == ref.space and sc.index == ref.index,
            else => false,
        };
        if (picked) guideBox(area, b, colors.select, px);
    }
}

/// The figure drawn over a sketch, if it has one: its ink where the
/// sketch is.
fn drawSketchFigure(area: dvui.Rect.Physical, it: SkPlace, alpha: f32) void {
    const fi = state.model.sketchFigure(it.item.id) orelse return;
    // The editor shows the draft's ink; views, the accepted ink.
    const draft = it.sketch == &it.item.sketch and it.item.accepted != null;
    const ft = (if (draft) figureDraftTris(fi) else figureTris(fi)) orelse return;
    const fb = ft.bounds;
    if (fb.isEmpty()) return;
    drawFigureTris(area, ft, .{ .x0 = fb.x0 + it.at.x, .x1 = fb.x1 + it.at.x, .y0 = fb.y0 + it.at.y, .y1 = fb.y1 + it.at.y }, alpha);
}

/// One geometry, stroked: infinite lines and rays across the view.
fn skDrawGeometry(area: dvui.Rect.Physical, it: SkPlace, g: skl.Geometry, colour: dvui.Color, thick: f32, dashed: bool) void {
    const s = it.sketch;
    const a = dvui.currentWindow().arena();
    switch (g.kind) {
        .point => |p| skDot(skPx(area, it, skVal(s, p)), 2.5 * dvui.windowNaturalScale(), colour),
        .affine => {},
        .segment, .circle, .arc => {
            var segs: std.ArrayList(geom.Segment) = .empty;
            s.appendSegments(a, g, &segs) catch return;
            var pts: std.ArrayList(geom.Point) = .empty;
            if (segs.items.len == 0) return;
            pts.append(a, segs.items[0].start()) catch return;
            for (segs.items) |seg| flatten(a, &pts, seg, 0.5 / state.view.ppm) catch return;
            const phys = a.alloc(dvui.Point.Physical, pts.items.len) catch return;
            for (pts.items, phys) |p, *o| o.* = skPx(area, it, p);
            if (dashed) {
                skDashed(phys, colour, thick);
            } else dvui.Path.stroke(.{ .points = phys }, .{ .thickness = thick, .color = .{ .color = colour } });
        },
        .line, .ray => {
            const l = skLineOf(s, g) orelse return;
            // Far enough to cross the whole view.
            const far = (area.w + area.h) / state.view.ppm * 2 + skDist(.{ .x = state.view.cx - it.at.x, .y = state.view.cy - it.at.y }, l.p);
            const t0: f64 = if (g.kind == .ray) 0 else -far;
            const p0: geom.Point = .{ .x = l.p.x + t0 * l.d.x, .y = l.p.y + t0 * l.d.y };
            const p1: geom.Point = .{ .x = l.p.x + far * l.d.x, .y = l.p.y + far * l.d.y };
            if (dashed) {
                skDashed(&.{ skPx(area, it, p0), skPx(area, it, p1) }, colour, thick);
            } else dvui.Path.stroke(.{ .points = &.{ skPx(area, it, p0), skPx(area, it, p1) } }, .{ .thickness = thick, .color = .{ .color = colour } });
        },
    }
}

/// An open polyline, dashed on the screen.
fn skDashed(pts: []const dvui.Point.Physical, colour: dvui.Color, thick: f32) void {
    const dash: f32 = 5 * dvui.windowNaturalScale();
    var phase: f32 = 0;
    for (1..pts.len) |i| {
        const a = pts[i - 1];
        const b = pts[i];
        const len = @sqrt((b.x - a.x) * (b.x - a.x) + (b.y - a.y) * (b.y - a.y));
        if (len == 0) continue;
        var t: f32 = 0;
        while (t < len) {
            const in_dash = @mod(phase + t, 2 * dash) < dash;
            const step = @min(len - t, dash - @mod(phase + t, dash));
            if (in_dash) {
                const p0: dvui.Point.Physical = .{ .x = a.x + (b.x - a.x) * t / len, .y = a.y + (b.y - a.y) * t / len };
                const p1: dvui.Point.Physical = .{ .x = a.x + (b.x - a.x) * (t + step) / len, .y = a.y + (b.y - a.y) * (t + step) / len };
                dvui.Path.stroke(.{ .points = &.{ p0, p1 } }, .{ .thickness = thick, .color = .{ .color = colour } });
            }
            t += @max(step, 0.01);
        }
        phase += len;
    }
}

/// The primitive picked in Properties' constraint list: haloed.
fn skDrawFlash(area: dvui.Rect.Physical, it: SkPlace) void {
    const r = sk_flash orelse return;
    const s = it.sketch;
    const px = dvui.windowNaturalScale();
    const hi = flash_colour;
    switch (r) {
        .geom => |g| {
            if (g >= s.geometry.items.len or s.geometry.items[g].removed) return;
            const geo = s.geometry.items[g];
            skDrawGeometry(area, it, geo, hi.opacity(0.35), 9 * px, false);
            skDrawGeometry(area, it, geo, hi, 3 * px, false);
        },
        .point => |pr| {
            const p = s.point(pr) catch return;
            const q = skPx(area, it, p);
            // A curve's end or centre: the curve too, fainter, so a point
            // shared by several (coincident) says whose it is.
            if (pr.role != .point and pr.geom < s.geometry.items.len and !s.geometry.items[pr.geom].removed)
                skDrawGeometry(area, it, s.geometry.items[pr.geom], hi.opacity(0.6), 2.5 * px, false);
            skDot(q, 9 * px, hi.opacity(0.35));
            skRing(q, 7 * px, hi, 2 * px);
            skDot(q, 3.5 * px, hi);
        },
    }
}

fn skDot(c: dvui.Point.Physical, r: f32, colour: dvui.Color) void {
    var pts: [12]dvui.Point.Physical = undefined;
    for (&pts, 0..) |*p, k| {
        const t: f32 = @as(f32, @floatFromInt(k)) / 12 * 2 * std.math.pi;
        p.* = .{ .x = c.x + r * @cos(t), .y = c.y + r * @sin(t) };
    }
    dvui.Path.fillConvex(.{ .points = &pts }, .{ .color = .{ .color = colour } });
}

fn skRing(c: dvui.Point.Physical, r: f32, colour: dvui.Color, thick: f32) void {
    var pts: [16]dvui.Point.Physical = undefined;
    for (&pts, 0..) |*p, k| {
        const t: f32 = @as(f32, @floatFromInt(k)) / 16 * 2 * std.math.pi;
        p.* = .{ .x = c.x + r * @cos(t), .y = c.y + r * @sin(t) };
    }
    dvui.Path.stroke(.{ .points = &pts }, .{ .thickness = thick, .color = .{ .color = colour }, .closed = true });
}

/// The sketch being edited, over the dimmed canvas.
fn drawSketchMode(area: dvui.Rect.Physical) void {
    const it = skItem() orelse return;
    const s = it.sketch;
    const px = dvui.windowNaturalScale();
    area.fill(.square, .{ .color = .{ .color = colors.paper.opacity(0.72) } });
    drawSketchFigure(area, it, 0.85);
    const an = skAnalysis();
    // Geometry the conflicting constraints touch.
    const conflicted = struct {
        fn f(anl: ?skl.solver.Analysis, sk_: *const skl.Sketch, g: skl.GeomId) bool {
            const x = anl orelse return false;
            for (x.conflicting) |ci| if (ci < sk_.constraints.items.len and skl.refersTo(sk_.constraints.items[ci], g)) return true;
            return false;
        }
    }.f;
    const isFree = struct {
        fn f(anl: ?skl.solver.Analysis, g: skl.GeomId) bool {
            const x = anl orelse return true;
            for (x.free) |fg| if (fg == g) return true;
            return false;
        }
    }.f;
    // The origin and axes, faintly.
    for (s.geometry.items[0..3]) |g| skDrawGeometry(area, it, g, colors.guide.opacity(0.4), px, true);
    // The box.
    if (sketchBox(it)) |b| guideBox(area, b, colors.guide.opacity(0.6), px);
    for (s.geometry.items, 0..) |g, gi| {
        if (g.removed or g.reference) continue;
        const id: skl.GeomId = @intCast(gi);
        var colour = if (isFree(an, id)) colors.ink else colors.guide;
        if (conflicted(an, s, id)) colour = colors.overflow;
        if (skSelected(.{ .curve = id })) colour = colors.select;
        skDrawGeometry(area, it, g, if (g.construction) colour.opacity(0.75) else colour, if (g.construction) px else 2 * px, g.construction);
        var buf: [3]skl.PointRef = undefined;
        for (skPointsOf(g, &buf, id)) |r| {
            const p = s.point(r) catch continue;
            const sel = skSelected(.{ .point = r });
            const rad: f32 = if (sel) 4 else 2.5;
            skDot(skPx(area, it, p), rad * px, if (sel) colors.select else colour);
        }
    }
    skDrawFlash(area, it);
    // Equal sizes and angles in named sets: each member marked with its
    // set's name, the set's value noted once.
    var eq_sets: EqualSets = .{};
    eq_sets.build(dvui.currentWindow().arena(), s);
    skDrawEqualSets(area, it, &eq_sets);
    // Constraint glyphs and values.
    for (s.constraints.items, 0..) |c, ci| {
        const anchor = skAnchor(s, c) orelse continue;
        const q = skPx(area, it, anchor);
        var colour = colors.guide;
        if (an) |x| {
            for (x.conflicting) |k| if (k == ci) {
                colour = colors.overflow;
            };
            for (x.redundant) |k| if (k == ci) {
                colour = colors.overflow.opacity(0.6);
            };
        }
        // Implied (not solved: it follows from the rest), fainter.
        if (!c.driving and !c.isDimension()) colour = colour.opacity(0.55);
        if (skSelected(.{ .constraint = @intCast(ci) })) colour = colors.select;
        var tb: [64]u8 = undefined;
        const text: []const u8 = switch (c.kind) {
            .coincident => {
                skRing(q, 5 * px, colour, 1.5 * px);
                continue;
            },
            .horizontal => "H",
            .vertical => "V",
            // Marks drawn in the stroke font's private glyphs: a point on
            // an arc, a line touching an arc (the owner's, 2026-11-24).
            .point_on => "\u{E001}",
            .fixed => "lock",
            .parallel => "||",
            .perpendicular => "perp",
            .tangent => "\u{E000}",
            // Equal sizes and angles: their sets are named and noted once
            // (`skDrawEqualSets`); a selected one shows its set's name.
            .equal, .equal_angle => blk: {
                if (!skSelected(.{ .constraint = @intCast(ci) })) continue;
                break :blk if (c.kind == .equal_angle) "≅" else "=";
            },
            .symmetric => "sym",
            .equal_distance => "=",
            .distance, .distance_x, .distance_y, .line_distance, .radius, .angle => blk: {
                const v = skShownValue(c).?;
                const u: []const u8 = if (c.kind == .angle) "°" else "";
                const pre: []const u8 = switch (c.kind) {
                    .radius => "R",
                    .distance_x => "↔",
                    .distance_y => "↕",
                    else => "",
                };
                // A reference dimension in parentheses, fainter.
                if (!c.driving) {
                    colour = colour.opacity(0.55);
                    break :blk std.fmt.bufPrint(&tb, "({s}{d:.2}{s})", .{ pre, @abs(v), u }) catch "";
                }
                if (c.expr.len > 0) break :blk std.fmt.bufPrint(&tb, "{s}{s} = {d:.2}{s}", .{ pre, c.expr, @abs(v), u }) catch "";
                break :blk std.fmt.bufPrint(&tb, "{s}{d:.2}{s}", .{ pre, @abs(v), u }) catch "";
            },
        };
        // A distance draws its line, its value along it; a radius a leader
        // from the centre through the curve, its value turned along it;
        // the rest their mark beside their anchor.
        switch (c.kind) {
            .distance, .distance_x, .distance_y => if (skDimMeasure(s, c)) |ms| {
                if (c.place.hidden) continue;
                drawDimension(area, it.at, ms, c.place, text, colour, sk_dim_drag != null and sk_dim_drag.?.c == ci);
                continue;
            },
            .radius => |r| if (skRadiusLeader(s, r.g)) |ld| {
                const qc = skPx(area, it, ld.centre);
                const qr = skPx(area, it, ld.on);
                const len = @sqrt((qr.x - qc.x) * (qr.x - qc.x) + (qr.y - qc.y) * (qr.y - qc.y));
                if (len >= 1) {
                    // Out past the curve far enough for the value.
                    const ux = (qr.x - qc.x) / len;
                    const uy = (qr.y - qc.y) / len;
                    const w: f32 = @floatCast(strokefont.width(text) * dim_cap * px);
                    const out = 6 * px + w + 4 * px;
                    const qo: dvui.Point.Physical = .{ .x = qr.x + ux * out, .y = qr.y + uy * out };
                    dvui.Path.stroke(.{ .points = &.{ qc, qo } }, .{ .thickness = px, .color = .{ .color = colour.opacity(0.7) } });
                    // An arrowhead on the curve, pointing out.
                    const h = 7 * px;
                    const ah = 2.5 * px;
                    dvui.Path.stroke(.{ .points = &.{
                        .{ .x = qr.x - ux * h - uy * ah, .y = qr.y - uy * h + ux * ah },
                        qr,
                        .{ .x = qr.x - ux * h + uy * ah, .y = qr.y - uy * h - ux * ah },
                    } }, .{ .thickness = px, .color = .{ .color = colour } });
                    // The value over the leader's part beyond the curve.
                    const beyond: dvui.Point.Physical = .{ .x = qr.x + ux * 6 * px, .y = qr.y + uy * 6 * px };
                    strokeText(text, alongPlace(beyond, qo, 0.5), colour);
                    continue;
                }
            },
            else => {},
        }
        strokeText(text, .{ .at = .{ .x = q.x + 6 * px, .y = q.y }, .size = dim_cap * px, .y_down = true, .align_y = 1 }, colour);
    }
    // The pointer's point of interest: a ring; locked, a ring and a cross.
    if (skTarget()) |t| {
        const q = skPx(area, it, t.at);
        const locked = sk_lock != null;
        // Locked, it stands in for the pointer: it scintillates.
        if (locked) {
            if (!sparkCursor(q, true)) scintillate(q, 8 * px);
        } else skRing(q, 6 * px, colors.select, 1.5 * px);
    }
    // The drawing tool's clicks so far, to the pointer.
    if (sk_tool != .none and sk_nclicks > 0) if (skClickPoint()) |p| {
        const last = sk_clicks[sk_nclicks - 1];
        switch (sk_tool) {
            .circle => {
                const r = skDist(sk_clicks[0], p);
                var buf4: [4]geom.Segment = undefined;
                const segs = geom.arc(sk_clicks[0], r, 0, 2 * std.math.pi, &buf4);
                skPreview(area, it, segs);
            },
            .polygon => if (skDist(sk_clicks[0], p) > 1e-9) {
                const c0 = sk_clicks[0];
                const r = skDist(c0, p);
                const t0 = std.math.atan2(p.y - c0.y, p.x - c0.x);
                const n = polygon_sides;
                const ar = dvui.currentWindow().arena();
                const segs = ar.alloc(geom.Segment, n) catch return;
                for (0..n) |i| {
                    const ta = t0 + 2 * std.math.pi * @as(f64, @floatFromInt(i)) / @as(f64, @floatFromInt(n));
                    const tb = t0 + 2 * std.math.pi * @as(f64, @floatFromInt(i + 1)) / @as(f64, @floatFromInt(n));
                    segs[i] = .{ .line = .{ .{ .x = c0.x + r * @cos(ta), .y = c0.y + r * @sin(ta) }, .{ .x = c0.x + r * @cos(tb), .y = c0.y + r * @sin(tb) } } };
                }
                skPreview(area, it, segs);
            },
            else => dvui.Path.stroke(.{ .points = &.{ skPx(area, it, last), skPx(area, it, p) } }, .{ .thickness = 1.5 * px, .color = .{ .color = colors.select } }),
        }
        for (sk_clicks[0..sk_nclicks]) |c| skDot(skPx(area, it, c), 3 * px, colors.select);
    };
    if (sk_box) |b| {
        const r = state.view.rect(area, .{ .x0 = @min(b.start.x, b.at.x) + it.at.x, .y0 = @min(b.start.y, b.at.y) + it.at.y, .x1 = @max(b.start.x, b.at.x) + it.at.x, .y1 = @max(b.start.y, b.at.y) + it.at.y });
        r.fill(.square, .{ .color = .{ .color = colors.select.opacity(0.1) } });
        r.stroke(.square, .{ .thickness = px, .color = .{ .color = colors.select } });
    }
    // The readout.
    if (an) |x| {
        state.status = if (!x.solved)
            std.fmt.bufPrint(&sk_status_buf, "{s}: {d} conflicting constraint{s} · Enter for the summary ", .{ it.name, x.conflicting.len, if (x.conflicting.len == 1) "" else "s" }) catch ""
        else if (x.fully_constrained)
            std.fmt.bufPrint(&sk_status_buf, "{s}: fully constrained · Enter for the summary ", .{it.name}) catch ""
        else
            std.fmt.bufPrint(&sk_status_buf, "{s}: {d} degree{s} of freedom left · Enter for the summary ", .{ it.name, x.dof, if (x.dof == 1) "" else "s" }) catch "";
    }
    skDimEntry(area);
    if (sk_summary) skSummary(area);
}

fn skPreview(area: dvui.Rect.Physical, it: SkPlace, segs: []const geom.Segment) void {
    const a = dvui.currentWindow().arena();
    var pts: std.ArrayList(geom.Point) = .empty;
    pts.append(a, segs[0].start()) catch return;
    for (segs) |seg| flatten(a, &pts, seg, 0.5 / state.view.ppm) catch return;
    const phys = a.alloc(dvui.Point.Physical, pts.items.len) catch return;
    for (pts.items, phys) |p, *o| o.* = skPx(area, it, p);
    dvui.Path.stroke(.{ .points = phys }, .{ .thickness = 1.5 * dvui.windowNaturalScale(), .color = .{ .color = colors.select } });
}

/// A dimension's value being entered, by the dimension: Enter sets it,
/// Esc leaves it as it is.
fn skDimEntry(area: dvui.Rect.Physical) void {
    const d = &(sk_dim orelse return);
    const it = skItem() orelse return;
    if (d.c >= it.sketch.constraints.items.len) {
        sk_dim = null;
        return;
    }
    const c = it.sketch.constraints.items[d.c];
    const ns = dvui.windowNaturalScale();
    // A plain widget in the canvas, by the dimension: in the main window,
    // so it takes the keyboard as the expression line does.
    var holder = dvui.box(@src(), .{}, .{ .rect = .{ .x = (d.at.x - area.x) / ns + 8, .y = (d.at.y - area.y) / ns - 42, .w = 150, .h = 40 }, .background = true, .border = .all(1), .corners = .all(4), .padding = .all(2), .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) } });
    defer holder.deinit();
    // Enter and Esc, taken before the entry sees them (it would keep
    // Enter for itself).
    var enter = false;
    var close = false;
    if (sk_dim_id) |id| if (id == dvui.focusedWidgetId()) for (dvui.events()) |*e| {
        const inv = keymap.match1(e, kmode("dialog")) orelse continue;
        switch (inv.action) {
            kact("dialog.confirm") => enter = true,
            kact("dialog.cancel") => close = true,
            else => continue,
        }
        e.handle(@src(), holder.data());
    };
    var te = dvui.textEntry(@src(), .{}, .{ .expand = .horizontal, .font = .theme(.mono) });
    sk_dim_id = te.data().id;
    if (d.fresh) {
        var buf: [32]u8 = undefined;
        const v = skShownValue(c) orelse 0;
        const shown = if (c.expr.len > 0) c.expr else std.fmt.bufPrint(&buf, "{d:.3}", .{if (c.kind == .angle) v else @abs(v)}) catch "";
        te.textSet(shown, true);
        d.fresh = false;
    }
    // Asked for over a few frames: a new entry takes focus once it exists.
    if (d.focus_tries > 0) {
        if (te.data().id == dvui.focusedWidgetId()) {
            d.focus_tries = 0;
        } else {
            d.focus_tries -= 1;
            dvui.focusSubwindow(null, null);
            dvui.focusWidget(te.data().id, null, null);
            dvui.refresh(null, @src(), null);
        }
    }
    if (enter) {
        const text = std.mem.trim(u8, te.textGet(), " ");
        // An expression of the parameters (mm, or degrees), kept with the
        // dimension; a plain number, in the document's units, is a value.
        if (!skl.expr.isNumber(text) and text.len > 0) {
            _ = skEdit(.{ .expr = .{ .c = d.c, .text = text } });
            if (skItem()) |it2| if (it2.sketch.exprError(d.c)) |err| {
                state.status = switch (err) {
                    error.UnknownName => "That expression names a parameter the sketch does not have. ",
                    error.Syntax => "That expression cannot be read. ",
                    error.Cycle => "Those parameters refer to each other in a circle. ",
                    error.Domain => "That expression has no value (a division by zero, say). ",
                };
            };
        } else if (std.fmt.parseFloat(f64, text)) |v| {
            // No distance is negative (the owner, 2026-11-24); its side is
            // the constraint's own.
            if (v < 0 and c.kind != .angle) {
                state.status = "A distance is never negative: the side is kept as drawn. ";
            } else {
                if (c.expr.len > 0) _ = skEdit(.{ .expr = .{ .c = d.c, .text = "" } });
                _ = skEdit(.{ .value = .{ .c = d.c, .value = skFromShown(c, v) } });
            }
        } else |_| state.status = "Not a number. ";
        close = true;
    }
    te.deinit();
    if (close) {
        sk_dim = null;
        if (canvas_id) |id| dvui.focusWidget(id, null, null);
    }
}

/// The summary: what holds the sketch, before leaving it.
fn skSummary(area: dvui.Rect.Physical) void {
    const saved_group = pushGroup("sketch.summary");
    defer popGroup(saved_group);
    const it = skItem() orelse return;
    const an = skAnalysis();
    const ns = dvui.windowNaturalScale();
    const w: f32 = 380;
    var fw: dvui.FloatingWidget = undefined;
    fw.init(@src(), .{}, .{ .rect = .{ .x = (area.x + area.w / 2) / ns - w / 2, .y = (area.y + area.h / 3) / ns, .w = w, .h = 0 }, .background = true, .border = .all(1), .corners = .all(8), .padding = .all(12), .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) } });
    defer fw.deinit();
    var col = dvui.box(@src(), .{ .dir = .vertical }, .{ .expand = .horizontal });
    defer col.deinit();
    dvui.label(@src(), "{s}", .{it.name}, .{ .font = dvui.Font.theme(.heading) });
    var n_geo: usize = 0;
    for (it.sketch.geometry.items) |g| {
        if (!g.removed and !g.reference) n_geo += 1;
    }
    if (an) |x| {
        if (x.fully_constrained)
            dvui.labelNoFmt(@src(), "Fully constrained.", .{}, .{})
        else
            dvui.label(@src(), "Not fully constrained: {d} degree{s} of freedom left.", .{ x.dof, if (x.dof == 1) "" else "s" }, .{ .color_text = .{ .color = colors.overflow } });
        if (x.conflicting.len > 0) dvui.label(@src(), "Conflicting: {d} constraint{s}, marked in the list.", .{ x.conflicting.len, if (x.conflicting.len == 1) "" else "s" }, .{ .color_text = .{ .color = colors.overflow } });
        if (x.redundant.len > 0) dvui.label(@src(), "Redundant: {d} constraint{s}, marked in the list.", .{ x.redundant.len, if (x.redundant.len == 1) "" else "s" }, .{ .color_text = .{ .color = colors.overflow } });
    }
    dvui.label(@src(), "{d} geometr{s}, {d} constraint{s}.", .{ n_geo, if (n_geo == 1) "y" else "ies", it.sketch.constraints.items.len, if (it.sketch.constraints.items.len == 1) "" else "s" }, .{});
    if (sketchBox(it)) |b| dvui.label(@src(), "Box {d:.2} × {d:.2} {s}.", .{ b.width() * docUnits().perMm(), b.height() * docUnits().perMm(), docUnits().symbol() }, .{});
    dvui.labelNoFmt(@src(), "Enter accepts and leaves · Esc goes back to sketching", .{}, .{ .margin = .{ .y = 8 }, .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.65) } });
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
    defer row.deinit();
    keyButton(@src(), "Accept and leave", 0, .{});
    keyButton(@src(), "Back to sketching", 0, .{});
}

// Palette and properties ----------------------------------------------------------

fn sketchPalette() void {
    // The sketch editor's ribbon, in groups (the owner, 2026-11-25: one
    // editor, its tools in the ribbon): Geometry, Constrain, Ink; Update
    // and Finish at the far right.
    const on_fill = dvui.themeGet().focus.opacity(0.35);
    var bar = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .padding = .{ .x = 2, .w = 2 }, .gravity_y = 0.5 });
    defer bar.deinit();
    var below: dvui.Rect.Physical = undefined;
    {
        const saved_group = pushGroup("sketch.palette");
        defer popGroup(saved_group);
        var geo = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_y = 0.5 });
        defer geo.deinit();
        skPaletteKey(@src(), "Select", dvui.entypo.mouse_pointer, 0, 0, sk_tool == .none, "Select: pick geometry and constraints; drag points");
        skPaletteKey(@src(), "Construction", icons.graven(.construction_line) orelse dvui.entypo.flow_line, 0, 1, sk_construction, "Construction: what is drawn next is construction geometry (dashed)");
        const names = [_][]const u8{ "Point", "Line", "Polyline", "Arc", "Circle", "Polygon", "Array" };
        const tvgs = [_][]const u8{
            icons.graven(.geo_point) orelse dvui.entypo.dot_single,
            icons.graven(.geo_segment) orelse dvui.entypo.flow_line,
            dvui.entypo.line_graph,
            icons.graven(.geo_arc) orelse dvui.entypo.circle,
            icons.graven(.geo_circle) orelse dvui.entypo.circle,
            dvui.entypo.triangle_up,
            dvui.entypo.grid,
        };
        for (names, tvgs, 0..) |name, tvg, gi| {
            const on = if (skGeoOf(sk_tool)) |x| @intFromEnum(x) == gi else false;
            skPaletteKey(@src(), name, tvg, @intCast(gi), 10 + gi, on, name);
        }
        below = geo.data().borderRectScale().r;
    }
    ribbonGap(1);
    sketchConstrainKeys();
    ribbonGap(2);
    sketchInkKeys();
    _ = dvui.spacer(@src(), .{ .expand = .horizontal });
    {
        const saved_group = pushGroup("sketch.end");
        defer popGroup(saved_group);
        {
            const pending = skPending();
            const prev_a = faintUnless(pending);
            defer dvui.alphaSet(prev_a);
            var uwd: dvui.WidgetData = undefined;
            ribbon_next_badge = "U";
            keyIcon(@src(), "Update", dvui.entypo.cycle, 0, .{ .data_out = &uwd, .color_fill = if (pending) .{ .color = colors.overflow.opacity(0.25) } else null });
            dvui.tooltip(@src(), .{ .active_rect = uwd.borderRectScale().r }, "{s}", .{if (pending) "Update: accept the changes so far, so what uses the sketch follows them, and keep editing (U)" else "Update: nothing to accept; what uses the sketch shows it as it is (U)"}, .{});
        }
        {
            const pending = skPending();
            const prev_a = faintUnless(pending);
            defer dvui.alphaSet(prev_a);
            var dwd: dvui.WidgetData = undefined;
            ribbon_next_badge = "X";
            keyIcon(@src(), "Discard", dvui.entypo.back_in_time, 0, .{ .data_out = &dwd });
            dvui.tooltip(@src(), .{ .active_rect = dwd.borderRectScale().r }, "{s}", .{if (pending) "Discard: drop the changes since the last update, back to the sketch as its uses see it (X)" else "Discard: no changes to drop (X)"}, .{});
        }
        ribbon_next_badge = "\u{21B5}";
        var fwd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Finish", dvui.entypo.check, 0, .{ .data_out = &fwd });
        dvui.tooltip(@src(), .{ .active_rect = fwd.borderRectScale().r }, "Finish: accept the sketch and leave (Enter shows its summary first)", .{}, .{});
    }
    _ = on_fill;
    const g = skGeoOf(sk_tool) orelse return;
    skToolOverlay(g, below);
}

/// A key of the sketch ribbon's Geometry group, tinted while on.
fn skPaletteKey(src: std.builtin.SourceLocation, name: []const u8, tvg: []const u8, arg: i32, id_extra: usize, on: bool, tip: []const u8) void {
    // Its own parent, so its tooltip's ID is its own.
    var b = dvui.box(src, .{}, .{ .id_extra = id_extra, .gravity_y = 0.5 });
    defer b.deinit();
    var wd: dvui.WidgetData = undefined;
    keyIcon(@src(), name, tvg, arg, .{ .data_out = &wd, .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null });
    dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "{s}", .{tip}, .{});
}

/// The sketch ribbon's Constrain group: a key for each kind, its single
/// key in its fade, faint where the selection does not suit it.
fn sketchConstrainKeys() void {
    const saved_group = pushGroup("sketch.constrain");
    defer popGroup(saved_group);
    const kinds = [_]struct { k: SkKind, name: []const u8, key: ?[]const u8 = null, icon: icons.GIcon }{
        .{ .k = .coincident, .name = "Coincident", .key = "C", .icon = .con_coincident },
        .{ .k = .horizontal, .name = "Horizontal", .key = "H", .icon = .con_horizontal },
        .{ .k = .vertical, .name = "Vertical", .key = "V", .icon = .con_vertical },
        .{ .k = .point_on, .name = "On object", .key = "O", .icon = .con_on_object },
        .{ .k = .tangent, .name = "Tangent", .key = "T", .icon = .con_tangent },
        .{ .k = .perpendicular, .name = "Perpendicular", .key = "P", .icon = .con_perpendicular },
        .{ .k = .parallel, .name = "Parallel", .icon = .con_parallel },
        .{ .k = .equal, .name = "Equal", .key = "E", .icon = .con_equal },
        .{ .k = .symmetric, .name = "Symmetric", .icon = .con_symmetric },
        .{ .k = .distance, .name = "Distance", .key = "D", .icon = .con_distance },
        .{ .k = .distance_x, .name = "Horizontal distance", .icon = .con_distance_x },
        .{ .k = .distance_y, .name = "Vertical distance", .icon = .con_distance_y },
        .{ .k = .radius, .name = "Radius", .key = "R", .icon = .con_radius },
        .{ .k = .angle, .name = "Angle", .key = "A", .icon = .con_angle },
        .{ .k = .fixed, .name = "Lock", .key = "L", .icon = .con_locked },
    };
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_y = 0.5 });
    defer row.deinit();
    for (kinds, 0..) |k, i| {
        var buf: [8]skl.Constraint = undefined;
        const fits = skConstraintsFor(k.k, &buf) > 0;
        const prev_a = faintUnless(fits);
        defer dvui.alphaSet(prev_a);
        ribbon_next_badge = k.key;
        var wd: dvui.WidgetData = undefined;
        keyIcon(@src(), k.name, icons.gravenAny(k.icon) orelse dvui.entypo.link, @intFromEnum(k.k), .{ .id_extra = 100 + i, .data_out = &wd });
        dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "{s}: constrain the selection", .{k.name}, .{ .id_extra = 100 + i });
    }
}

/// The sketch ribbon's Ink group: ink the selection in the current stroke
/// style, fill the area it closes in the current fill style.
fn sketchInkKeys() void {
    var buf: [256]skl.GeomId = undefined;
    const gs = skInkable(&buf);
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_y = 0.5 });
    defer row.deinit();
    skDrawingChoice();
    {
        const saved_group = pushGroup("ink");
        defer popGroup(saved_group);
        const prev_a = faintUnless(gs.len > 0);
        defer dvui.alphaSet(prev_a);
        ribbon_next_badge = "I";
        var wd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Ink selection  I", dvui.entypo.brush, 0, .{ .data_out = &wd });
        dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "Ink: stroke the selected lines and arcs in the current stroke style, or take their ink off", .{}, .{});
    }
    {
        const saved_group = pushGroup("fill");
        defer popGroup(saved_group);
        const prev_a = faintUnless(gs.len > 0);
        defer dvui.alphaSet(prev_a);
        ribbon_next_badge = "F";
        var wd: dvui.WidgetData = undefined;
        keyIcon(@src(), "Fill selection  F", dvui.entypo.drop, 0, .{ .data_out = &wd });
        dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "Fill: fill the area the selection closes in the current fill style, or take its fill off", .{}, .{});
    }
}

/// The Ink group's drawing: which of the sketch's drawings (ink
/// contexts) ink and fills go into, and New drawing.
fn skDrawingChoice() void {
    const r = sketch_edit orelse return;
    const saved_group = pushGroup("ink");
    defer popGroup(saved_group);
    const ar = dvui.currentWindow().arena();
    const sid = state.model.sketches.items[r.sketch].id;
    var names: std.ArrayList([]const u8) = .empty;
    var ids: std.ArrayList(layout.model.ObjectId) = .empty;
    for (state.model.figures.items) |f| if (f.sketch == sid) {
        names.append(ar, f.name) catch return;
        ids.append(ar, f.id) catch return;
    };
    if (names.items.len > 1) {
        var col = dvui.box(@src(), .{ .dir = .horizontal }, .{ .gravity_y = 0.5, .min_size_content = .{ .w = 130 } });
        defer col.deinit();
        tagParent("Drawing");
        var choice: usize = 0;
        if (state.model.sketchFigure(sid)) |fi| for (ids.items, 0..) |id, k| {
            if (id == state.model.figures.items[fi].id) choice = k;
        };
        if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .gravity_y = 0.5 })) {
            actV(.setSketchDrawing, .{ r.sketch, ids.items[choice] });
        }
    }
    var wd: dvui.WidgetData = undefined;
    keyIcon(@src(), "New drawing", dvui.entypo.add_to_list, 0, .{ .data_out = &wd });
    dvui.tooltip(@src(), .{ .active_rect = wd.borderRectScale().r }, "New drawing: another ink context over this sketch (its own ink and fills), made the one ink goes into", .{}, .{});
}

/// The overlay below the geometry buttons for the active one: its
/// sub-options first (M goes to the next), then the step being placed,
/// with typed values for it.
fn skToolOverlay(g: SkGeo, buttons: dvui.Rect.Physical) void {
    const saved_group = pushGroup("sketch.tool");
    defer popGroup(saved_group);
    const ns = dvui.windowNaturalScale();
    const pad: dvui.Rect = .{ .x = 6, .w = 6, .y = 3, .h = 3 };
    const tools = sk_geo_tools[@intFromEnum(g)];
    // Floating over what is below the buttons, as tall as its rows.
    const fields: f32 = @floatFromInt(skStepFieldCount());
    const hint_rows: f32 = if (tools.len > 1) (if (g == .line and !sk_construction) 2 else 1) else 0;
    const counts: f32 = if (g == .array) (if (sk_tool == .polar_array) 3 else 2) else if (g == .polygon) 3 else 0;
    const h: f32 = 20 + (if (tools.len > 1) @as(f32, 32) else 0) + hint_rows * 24 + 28 + (fields + counts) * 40;
    var fw: dvui.FloatingWidget = undefined;
    fw.init(@src(), .{}, .{
        .rect = .{ .x = buttons.x / ns, .y = (buttons.y + buttons.h) / ns + 4, .w = buttons.w / ns, .h = h },
        .background = true,
        .color_fill = .{ .color = dvui.themeGet().color(.window, .fill) },
        .border = .all(1),
        .corners = .all(6),
        .padding = .all(6),
    });
    defer fw.deinit();
    // Clicked, it takes the keyboard (a floating widget's own fields get
    // keys only while its subwindow has focus), as floating windows do.
    for (dvui.events()) |*e| {
        if (!dvui.eventMatch(e, .{ .id = fw.data().id, .r = fw.data().rectScale().r })) continue;
        if (e.evt == .mouse and e.evt.mouse.action == .focus) dvui.focusSubwindow(fw.data().id, e.num);
    }
    if (tools.len > 1) {
        var flex = dvui.flexbox(@src(), .{ .justify_content = .start }, .{ .expand = .horizontal });
        defer flex.deinit();
        for (tools, 0..) |t, i| {
            const name = skToolName(t);
            if (!skToolAllowed(t)) {
                dvui.labelNoFmt(@src(), name, .{}, .{ .id_extra = i, .margin = .all(1), .padding = pad, .color_text = .{ .color = dvui.themeGet().color(.window, .text).opacity(0.35) } });
                continue;
            }
            const on = sk_tool == t;
            keyButton(@src(), name, @intFromEnum(t), .{ .id_extra = i, .margin = .all(1), .padding = pad, .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null });
        }
    }
    const faint = dvui.themeGet().color(.control, .text).opacity(0.65);
    if (tools.len > 1) dvui.labelNoFmt(@src(), "M: next option", .{}, .{ .color_text = .{ .color = faint } });
    if (g == .line and !sk_construction) dvui.labelNoFmt(@src(), "Ray and line: construction only", .{}, .{ .color_text = .{ .color = faint } });
    if (g == .array) skArrayCounts();
    if (g == .polygon) skPolygonSides();
    dvui.label(@src(), "{s}: point {d} of {d}", .{ skToolName(sk_tool), sk_nclicks + 1, skToolClicks(sk_tool) }, .{ .color_text = .{ .color = faint } });
    skStepFields();
}

/// The array macro's counts (the array tool's, shared): a polar array's
/// columns round, rings and sweep; a rectangular one's columns and rows.
fn skArrayCounts() void {
    const saved = pushGroup("array");
    defer popGroup(saved);
    const polar = sk_tool == .polar_array;
    const labels: [3][]const u8 = if (polar) .{ "Around", "Rings", "Sweep, °" } else .{ "Columns", "Rows", "" };
    inline for (0..3) |i| if (i < 2 or polar) {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = i });
        defer row.deinit();
        propName(labels[i]);
        if (i == 2) {
            if (accepted.numberField(@src(), f64, array_tool.sweep, 1, 360, .{ .id_extra = i, .expand = .horizontal })) |v| array_tool.sweep = v;
        } else {
            const cur: *u32 = if (polar) (if (i == 0) &array_tool.around else &array_tool.rings) else (if (i == 0) &array_tool.cols else &array_tool.rows);
            if (accepted.numberField(@src(), f64, @floatFromInt(cur.*), 1, 999, .{ .id_extra = i, .expand = .horizontal })) |v| cur.* = @intFromFloat(@round(v));
        }
    };
}

/// The polygon tool's sides: the common ones by name, or any number.
const polygon_names = [_][]const u8{ "Triangle", "Square", "Pentagon", "Hexagon", "Heptagon", "Octagon" };
fn skPolygonSides() void {
    const saved = pushGroup("polygon");
    defer popGroup(saved);
    const pad: dvui.Rect = .{ .x = 6, .w = 6, .y = 3, .h = 3 };
    {
        var flex = dvui.flexbox(@src(), .{ .justify_content = .start }, .{ .expand = .horizontal });
        defer flex.deinit();
        for (polygon_names, 3..) |name, n| {
            const on = polygon_sides == n;
            keyButton(@src(), name, @intCast(n), .{ .id_extra = n, .margin = .all(1), .padding = pad, .color_fill = if (on) .{ .color = dvui.themeGet().focus.opacity(0.35) } else null });
        }
    }
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal });
    defer row.deinit();
    propName("Sides");
    if (accepted.numberField(@src(), f64, @floatFromInt(polygon_sides), 3, 360, .{ .expand = .horizontal })) |v| polygon_sides = @intFromFloat(@round(v));
}

fn skToolName(t: SkTool) []const u8 {
    return switch (t) {
        .none => "Select",
        .point => "Point",
        .segment => "Segment",
        .ray => "Ray",
        .line => "Line",
        .polyline => "Polyline",
        .arc_centre => "Centre",
        .arc_3pt => "3 points",
        .circle => "Centre",
        .circle_3pt => "3 points",
        .polar_array => "Polar",
        .rect_array => "Rectangular",
        .polygon => "Polygon",
    };
}

/// How many typed values the step being placed has (see `skStepFields`).
fn skStepFieldCount() usize {
    const n = sk_nclicks;
    const arc_end = sk_tool == .arc_centre and n == 2;
    const from_prev = n > 0 and switch (sk_tool) {
        .segment, .ray, .line, .polyline, .circle => true,
        .arc_centre => n == 1,
        else => false,
    };
    return 2 + @as(usize, if (from_prev) 2 else if (arc_end) 1 else 0);
}

/// The typed values of the step being placed: where it goes (x, y), and,
/// from the point before, how far and at what angle (a circle's or an
/// arc's radius); an arc's end, at what angle from its centre. Shown live
/// from the pointer; Enter in one places the step there.
var sk_step_text: [4][24]u8 = undefined;
/// Values typed for the step being placed: kept, not followed live, until
/// it is placed (or the tool changes).
var sk_step_typed = [4]?f64{ null, null, null, null };
var sk_step_of: struct { tool: SkTool, n: usize } = .{ .tool = .none, .n = 0 };

fn skStepFields() void {
    const saved_group = pushGroup("sketch.step");
    defer popGroup(saved_group);
    const p = skClickPoint() orelse geom.Point{ .x = 0, .y = 0 };
    const n = sk_nclicks;
    const prev: ?geom.Point = if (n > 0) sk_clicks[n - 1] else null;
    const arc_end = sk_tool == .arc_centre and n == 2;
    const from_prev = prev != null and switch (sk_tool) {
        .segment, .ray, .line, .polyline, .circle => true,
        .arc_centre => n == 1,
        else => false,
    };
    const base: geom.Point = if (arc_end) sk_clicks[0] else prev orelse p;
    const live_len = skDist(base, p);
    const live_ang = std.math.atan2(p.y - base.y, p.x - base.x) * 180 / std.math.pi;
    const radius_word = sk_tool == .circle or sk_tool == .arc_centre;
    // A new step (or tool) forgets what was typed for the last.
    if (sk_step_of.tool != sk_tool or sk_step_of.n != n) {
        sk_step_typed = .{ null, null, null, null };
        sk_step_of = .{ .tool = sk_tool, .n = n };
    }
    var vals = [4]f64{ p.x, p.y, live_len, live_ang };
    for (&vals, sk_step_typed) |*v, t| if (t) |x| {
        v.* = x;
    };
    var entered: ?usize = null;
    const labels = [4][]const u8{ "x, mm", "y, mm", if (radius_word) "Radius, mm" else "Length, mm", if (arc_end) "End angle, °" else "Angle, °" };
    for (0..4) |k| {
        if (k == 2 and !from_prev) continue;
        if (k == 3 and !from_prev and !arc_end) continue;
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = k });
        defer row.deinit();
        propName(labels[k]);
        const live = std.fmt.bufPrint(&sk_step_text[k], "{d:.2}", .{vals[k]}) catch "";
        // Typed values are drawn bold: they hold until the step is placed.
        var te = dvui.textEntry(@src(), .{}, .{ .expand = .horizontal, .id_extra = 7700 + k, .font = if (sk_step_typed[k] != null) dvui.Font.theme(.body).withWeight(.bold) else null });
        const focused = te.data().id == dvui.focusedWidgetId();
        if (!focused and sk_step_typed[k] == null and !std.mem.eql(u8, te.textGet(), live)) te.textSet(live, false);
        if (te.text_changed and focused) {
            sk_step_typed[k] = std.fmt.parseFloat(f64, std.mem.trim(u8, te.textGet(), " ")) catch null;
        }
        if (std.fmt.parseFloat(f64, std.mem.trim(u8, te.textGet(), " "))) |v| vals[k] = v else |_| {}
        if (focused and te.enter_pressed) entered = k;
        te.deinit();
    }
    const k = entered orelse return;
    const target: geom.Point = switch (k) {
        0, 1 => .{ .x = vals[0], .y = vals[1] },
        else => blk: {
            const r = if (arc_end) skDist(sk_clicks[0], sk_clicks[1]) else vals[2];
            const a = vals[3] * std.math.pi / 180;
            break :blk .{ .x = base.x + r * @cos(a), .y = base.y + r * @sin(a) };
        },
    };
    skToolClick(target);
}


/// The canvas area in physical pixels, from the last frame.
fn canvasArea() dvui.Rect.Physical {
    const ns = dvui.windowNaturalScale();
    return .{ .x = canvas_rect.x * ns, .y = canvas_rect.y * ns, .w = canvas_rect.w * ns, .h = canvas_rect.h * ns };
}

/// The sketch being edited: its readout and its constraints.
fn sketchModeProperties() void {
    const saved_group = pushGroup("sketch-mode");
    defer popGroup(saved_group);
    const it = skItem() orelse return;
    propText("Sketch", "{s}", .{it.name}, 1);
    if (skAnalysis()) |x| {
        if (x.fully_constrained) propText("State", "{s}", .{"fully constrained"}, 2) else propText("Freedom", "{d} left", .{x.dof}, 2);
        if (x.conflicting.len > 0) propText("Conflicts", "{d}", .{x.conflicting.len}, 3);
        if (x.redundant.len > 0) propText("Redundant", "{d}", .{x.redundant.len}, 4);
    }
    // A point on a circle or an arc: a caption for it.
    if (skCaptionPoint() != null) keyButton(@src(), "Add caption", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
    sketchInkProperties();
    sketchFillProperties();
    skConstraintList(it);
    sketchPhysicalWhen(it);
    sketchParameters(it);
}

/// A primitive a constraint names, picked in Properties to show it on the
/// canvas (drawn highlighted until picked again or the selection changes).
var sk_flash: ?skl.Ref = null;
/// What a constraint's object picked in Properties is drawn in: a pigment
/// of its own, apart from the selection's.
const flash_colour: dvui.Color = .{ .r = canvas_theme.fluor_construction.r, .g = canvas_theme.fluor_construction.g, .b = canvas_theme.fluor_construction.b };
var sk_flash_sel: usize = 0;

/// The constraints of the selected geometry (all of them when nothing is
/// selected), one a line: its kind's icon (choosing the constraint), then
/// a button for each primitive it names, its icon the primitive's kind
/// (showing it on the canvas), a dimension's value, drive or reference,
/// and remove.
fn skConstraintList(it: SkPlace) void {
    const s = it.sketch;
    // The selected geometry.
    var picked: [32]skl.GeomId = undefined;
    var np: usize = 0;
    for (sk_sel.items) |p| {
        const g: skl.GeomId = switch (p) {
            .curve => |c| c,
            .point => |r| r.geom,
            .constraint => continue,
        };
        if (np < picked.len) {
            picked[np] = g;
            np += 1;
        }
    }
    // A highlight lasts while the selection it was made for does.
    if (sk_flash != null and sk_flash_sel != selHash()) sk_flash = null;
    if (np == 0) heading("{s}", .{"Constraints"}, 8200) else heading("Constraints of the selection", .{}, 8200);
    const an = skAnalysis();
    var shown: usize = 0;
    for (s.constraints.items, 0..) |c, ci| {
        if (np > 0) {
            var hit = false;
            for (picked[0..np]) |g| if (skl.refersTo(c, g)) {
                hit = true;
            };
            if (!hit) continue;
        }
        shown += 1;
        var flagged: ?dvui.Color = null;
        if (an) |x| {
            for (x.conflicting) |k| if (k == ci) {
                flagged = colors.overflow;
            };
            for (x.redundant) |k| if (k == ci) {
                flagged = colors.overflow.opacity(0.7);
            };
        }
        const sel = skSelected(.{ .constraint = @intCast(ci) });
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{
            .expand = .horizontal,
            .id_extra = ci,
            .margin = .{ .y = 1 },
            .background = sel or flagged != null,
            .color_fill = if (sel) .{ .color = dvui.themeGet().focus.opacity(0.3) } else if (flagged) |f| .{ .color = f.opacity(0.18) } else null,
            .corners = .all(4),
        });
        defer row.deinit();
        var tb: [96]u8 = undefined;
        const text = skConstraintText(&tb, c);
        const pad: dvui.Rect = .all(2);
        keyIcon(@src(), "Constraint", icons.gravenAny(skConstraintIcon(c)) orelse dvui.entypo.link, @intCast(ci), .{ .id_extra = 0, .gravity_y = 0.5, .padding = pad, .min_size_content = .{ .w = 22, .h = 22 }, .label = .{ .text = text } });
        var rb: [4]skl.Ref = undefined;
        for (skl.refs(c, &rb), 0..) |r, k| {
            var nb: [64]u8 = undefined;
            const on = sk_flash != null and std.meta.eql(sk_flash.?, r);
            keyIcon(@src(), "Constraint object", icons.gravenAny(skRefIcon(s, r)) orelse dvui.entypo.dot_single, @intCast(ci * 4 + k), .{
                .id_extra = 1 + k,
                .gravity_y = 0.5,
                .padding = pad,
                .min_size_content = .{ .w = 22, .h = 22 },
                .label = .{ .text = skRefName(&nb, s, r) },
                .color_fill = if (on) .{ .color = flash_colour.opacity(0.45) } else null,
                .background = true,
                .border = if (on) .all(1) else null,
                .color_border = if (on) .{ .color = flash_colour } else null,
            });
        }
        // A dimension's value (in parentheses: reference only).
        if (skShownValue(c)) |v| {
            var vb: [48]u8 = undefined;
            const u = if (c.kind == .angle) "°" else docUnits().symbol();
            const vt = if (c.driving) std.fmt.bufPrint(&vb, "{d:.3}{s}", .{ @abs(v), u }) catch "" else std.fmt.bufPrint(&vb, "({d:.3}{s})", .{ @abs(v), u }) catch "";
            dvui.labelNoFmt(@src(), vt, .{}, .{ .gravity_y = 0.5, .margin = .{ .x = 6 }, .color_text = if (flagged) |f| .{ .color = f } else null });
        }
        _ = dvui.spacer(@src(), .{ .expand = .horizontal });
        // A dimension drives, or (in parentheses) only reports.
        if (c.isDimension()) {
            keyButton(@src(), if (c.driving) "drive" else "ref", @intCast(ci), .{ .gravity_y = 0.5, .padding = .{ .x = 5, .w = 5, .y = 2, .h = 2 } });
        }
        keyIcon(@src(), "Remove constraint", dvui.entypo.cross, @intCast(ci), .{ .gravity_y = 0.5 });
    }
    if (shown == 0) dvui.labelNoFmt(@src(), if (np == 0) "None yet." else "None on the selection.", .{}, .{ .font = dvui.Font.theme(.body).larger(-2), .color_text = .{ .color = dvui.themeGet().color(.control, .text).opacity(0.65) } });
}

/// A hash of the selection, to tell when it changed.
fn selHash() usize {
    return std.hash.Wyhash.hash(0, std.mem.sliceAsBytes(sk_sel.items));
}

/// Choosing a constraint from its icon: selected; a dimension opens for
/// its value.
fn skPickConstraint(ci: skl.ConstraintId) void {
    const it = skItem() orelse return;
    if (ci >= it.sketch.constraints.items.len) return;
    const c = it.sketch.constraints.items[ci];
    // Keep the geometry the list is for selected; the constraint joins it.
    if (!skSelected(.{ .constraint = ci })) sk_sel.append(state.gpa, .{ .constraint = ci }) catch {};
    sk_flash_sel = selHash();
    if (skShownValue(c) != null) {
        const at = skDimAnchor(canvasArea(), ci) orelse dvui.Point.Physical{ .x = 0, .y = 0 };
        sk_dim = .{ .c = ci, .at = at };
    }
}

/// Showing (or no longer showing) one primitive a constraint names.
fn skFlashRef(arg: i32) void {
    const it = skItem() orelse return;
    const ci: usize = @intCast(@divTrunc(arg, 4));
    const k: usize = @intCast(@mod(arg, 4));
    if (ci >= it.sketch.constraints.items.len) return;
    var rb: [4]skl.Ref = undefined;
    const rs = skl.refs(it.sketch.constraints.items[ci], &rb);
    if (k >= rs.len) return;
    sk_flash = if (sk_flash != null and std.meta.eql(sk_flash.?, rs[k])) null else rs[k];
    sk_flash_sel = selHash();
}

fn skConstraintIcon(c: skl.Constraint) icons.GIcon {
    return switch (c.kind) {
        .coincident => .con_coincident,
        .horizontal => .con_horizontal,
        .vertical => .con_vertical,
        .point_on => .con_on_object,
        .fixed => .con_locked,
        .distance => .con_distance,
        .distance_x => .con_distance_x,
        .distance_y => .con_distance_y,
        .line_distance => .con_line_distance,
        .radius => .con_radius,
        .angle => .con_angle,
        .parallel => .con_parallel,
        .perpendicular => .con_perpendicular,
        .tangent => .con_tangent,
        .equal => .con_equal,
        .equal_angle => .con_angle,
        .equal_distance => .con_equal_distance,
        .symmetric => .con_symmetric,
    };
}

fn skRefIcon(s: *const skl.Sketch, r: skl.Ref) icons.GIcon {
    const g = switch (r) {
        .point => return .geo_point,
        .geom => |g| g,
    };
    if (g >= s.geometry.items.len) return .geo_point;
    return switch (s.geometry.items[g].kind) {
        .point, .affine => .geo_point,
        .segment => .geo_segment,
        .circle => .geo_circle,
        .arc => .geo_arc,
        .line => .geo_line,
        .ray => .geo_ray,
    };
}

/// "Segment 4", "End of segment 4", "Centre of circle 2": a primitive as
/// its button's tooltip names it (numbered from 1, as drawn).
fn skRefName(buf: []u8, s: *const skl.Sketch, r: skl.Ref) []const u8 {
    const g: skl.GeomId = switch (r) {
        .point => |p| p.geom,
        .geom => |g| g,
    };
    if (g >= s.geometry.items.len) return "(removed)";
    const geo = s.geometry.items[g];
    const kind: []const u8 = if (geo.reference) (if (g == 0) "origin" else if (g == 1) "horizontal axis" else "vertical axis") else switch (geo.kind) {
        .point, .affine => "point",
        .segment => if (geo.construction) "construction segment" else "segment",
        .circle => if (geo.construction) "construction circle" else "circle",
        .arc => if (geo.construction) "construction arc" else "arc",
        .line => "construction line",
        .ray => "ray",
    };
    const role: []const u8 = switch (r) {
        .geom => "",
        .point => |p| switch (p.role) {
            .point => "",
            .start => "start of ",
            .end => "end of ",
            .centre => "centre of ",
            .origin => "origin of ",
        },
    };
    const text = if (geo.reference) std.fmt.bufPrint(buf, "{s}{s}", .{ role, kind }) catch kind else std.fmt.bufPrint(buf, "{s}{s} {d}", .{ role, kind, g }) catch kind;
    if (text.len > 0) buf[0] = std.ascii.toUpper(buf[0]);
    return text;
}

var sk_pw_text: [64]u8 = @splat(0);
var sk_pw_for: ?skl.GeomId = null;

/// For one selected construction geometry: the parameter that makes it
/// output while not 0 (a tile switches it on).
fn sketchPhysicalWhen(it: SkPlace) void {
    const saved_group = pushGroup("sketch.physical");
    defer popGroup(saved_group);
    if (sk_sel.items.len != 1) return;
    const g: skl.GeomId = switch (sk_sel.items[0]) {
        .curve => |c| c,
        .point => |r| if (r.role == .point) r.geom else return,
        .constraint => return,
    };
    const geo = it.sketch.geometry.items[g];
    if (!geo.construction or geo.kind == .line or geo.kind == .ray) return;
    if (sk_pw_for == null or sk_pw_for.? != g) {
        sk_pw_for = g;
        @memset(&sk_pw_text, 0);
        @memcpy(sk_pw_text[0..@min(geo.physical_when.len, 63)], geo.physical_when[0..@min(geo.physical_when.len, 63)]);
    }
    heading("{s}", .{"Output while a parameter is on"}, 8250);
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8251 });
    defer row.deinit();
    var te = dvui.textEntry(@src(), .{ .text = .{ .buffer = sk_pw_text[0..63] }, .placeholder = "parameter (empty: never)" }, .{ .expand = .horizontal, .font = .theme(.mono) });
    const enter = te.enter_pressed;
    te.deinit();
    keyButton(@src(), "Set", 0, .{ .gravity_y = 0.5 });
    if (enter) skSetPhysicalWhen();
}

/// What the parameter entry holds: "name = expression".
var sk_param_text: [128]u8 = @splat(0);

/// The sketch's parameters: each with its expression and value; a line to
/// add or change one ("name = expression"), Enter or Set to apply.
fn sketchParameters(it: SkPlace) void {
    const saved_group = pushGroup("sketch.parameters");
    defer popGroup(saved_group);
    heading("{s}", .{"Parameters"}, 8300);
    for (it.sketch.params.items, 0..) |p, pi| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = pi });
        defer row.deinit();
        var tb: [160]u8 = undefined;
        const text = if (it.sketch.paramValue(p.name)) |v|
            (std.fmt.bufPrint(&tb, "{s} = {s}  ({d:.3})", .{ p.name, p.expr, v }) catch p.name)
        else |_|
            (std.fmt.bufPrint(&tb, "{s} = {s} (no value)", .{ p.name, p.expr }) catch p.name);
        // A click puts it in the entry, to change.
        if (dvui.labelClick(@src(), "{s}", .{text}, .{}, .{ .expand = .horizontal })) {
            const line = std.fmt.bufPrint(sk_param_text[0 .. sk_param_text.len - 1], "{s} = {s}", .{ p.name, p.expr }) catch "";
            sk_param_text[line.len] = 0;
            sk_param_reset = true;
        }
        keyIcon(@src(), "Remove parameter", dvui.entypo.cross, @intCast(pi), .{ .gravity_y = 0.5 });
    }
    var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 9999 });
    defer row.deinit();
    var enter = false;
    var te = dvui.textEntry(@src(), .{ .text = .{ .buffer = sk_param_text[0 .. sk_param_text.len - 1] }, .placeholder = "name = expression" }, .{ .expand = .horizontal, .font = .theme(.mono) });
    if (sk_param_reset) {
        sk_param_reset = false;
        te.textLayout.selection.moveCursor(std.mem.indexOfScalar(u8, &sk_param_text, 0) orelse 0, false);
    }
    enter = te.enter_pressed;
    te.deinit();
    keyButton(@src(), "Set", 0, .{ .gravity_y = 0.5 });
    if (enter) skSetParam();
}

var sk_param_reset = false;

/// A sketch's properties, outside sketch mode.
fn sketchProperties(space: usize, index: usize) void {
    const saved_group = pushGroup("sketch-view");
    defer popGroup(saved_group);
    const it = viewPlace(space, index) orelse return;
    propText("Sketch", "{s}", .{it.name}, 1);
    propText("Origin", "({d:.2}, {d:.2}) {s}", .{ it.at.x * docUnits().perMm(), it.at.y * docUnits().perMm(), docUnits().symbol() }, 2);
    if (sketchBox(it)) |b| propText("Box", "{d:.2} × {d:.2} {s}", .{ b.width() * docUnits().perMm(), b.height() * docUnits().perMm(), docUnits().symbol() }, 3);
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    if (it.sketch.analyse(state.gpa, arena.allocator())) |x| {
        propText("Constrained", "{s}", .{if (x.fully_constrained) "fully" else "not fully"}, 4);
    } else |_| {}
    keyButton(@src(), "Edit sketch", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    // An enclosed sketch may be made a panel (or part) here.
    keyButton(@src(), "Make panel", 0, .{ .expand = .horizontal });
}

/// A sketch of the document (from the tree): its views, and where to place
/// one.
/// The document's sketches: how many, and New sketch (in its own space).
fn sketchesProperties() void {
    const saved_group = pushGroup("sketches");
    defer popGroup(saved_group);
    propText("Sketches", "{d}", .{state.model.sketches.items.len}, 1);
    keyButton(@src(), "New sketch", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

fn sketchDefProperties(index: usize) void {
    const saved_group = pushGroup("sketch");
    defer popGroup(saved_group);
    const sk = state.model.sketchAt(index) catch return;
    propText("Name", "{s}", .{sk.name}, 1);
    var views: usize = 0;
    for (state.model.spaces.items) |sp| for (sp.sketch_views.items) |v| {
        if (v.sketch == sk.id) views += 1;
    };
    var panels: usize = 0;
    for (state.model.panels.items) |pn| {
        if (pn.sketch == sk.id) panels += 1;
    }
    propText("Views", "{d}", .{views}, 2);
    propText("Panels", "{d}", .{panels}, 3);
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    if (sk.sketch.analyse(state.gpa, arena.allocator())) |x| {
        propText("Constrained", "{s}", .{if (x.fully_constrained) "fully" else "not fully"}, 4);
    } else |_| {}
    // Shown in a canvas or a frame: a view of it at the middle of what is
    // shown, or (enclosed) a panel there, its edge the sketch's outline.
    if (!state.model.isHome(shown_space)) {
        keyButton(@src(), "Place a view here", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
        keyButton(@src(), "Insert as a panel here", 0, .{ .expand = .horizontal, .margin = .{ .y = 2 } });
        keyButton(@src(), "Edit in its own space", 0, .{ .expand = .horizontal, .margin = .{ .y = 2, .h = 8 } });
    }
    keyButton(@src(), "Delete sketch", 0, .{ .expand = .horizontal });
}

/// The document's figures: how many, and Import SVG.
fn figuresProperties() void {
    const saved_group = pushGroup("figures");
    defer popGroup(saved_group);
    propText("Figures", "{d}", .{state.model.figures.items.len}, 1);
    keyButton(@src(), "Import SVG…", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
}

/// A figure's properties: its name, where it came from, its size and
/// paths, a drawing of its ink; Remove figure.
fn figureProperties(index: usize) void {
    const saved_group = pushGroup("figure");
    defer popGroup(saved_group);
    if (index >= state.model.figures.items.len) return;
    const f = state.model.figures.items[index];
    if (textProp("Name", f.name, 1)) |v| act(.renameFigure, .{ index, v }) catch {};
    if (f.source.len > 0) propText("From", "{s}", .{f.source}, 2);
    const ink = figureInk(index) orelse return;
    const b = layout.figure.inkBounds(ink);
    if (b.isEmpty()) propText("Size", "{s}", .{"no ink"}, 3) else propText("Size", "{d:.2} × {d:.2} mm", .{ b.width(), b.height() }, 3);
    var strokes: usize = 0;
    for (f.paths) |p| {
        if (p.stroke != null) strokes += 1;
    }
    propText("Paths", "{d} ({d} stroked)", .{ f.paths.len, strokes }, 4);
    const uses = state.model.figureUses(index);
    propText("Placed", "{d} {s}", .{ uses, if (uses == 1) "time" else "times" }, 6);
    // The ink, fitted into a box the pane's width.
    {
        var box = dvui.box(@src(), .{}, .{ .expand = .horizontal, .min_size_content = .{ .w = 120, .h = 220 }, .margin = .{ .y = 8 }, .background = true, .color_fill = .{ .color = colors.paper }, .border = .all(1), .id_extra = 5 });
        defer box.deinit();
        drawInk(box.data().contentRectScale().r, index, ink, b);
    }
    keyButton(@src(), "Replace from SVG…", 0, .{ .expand = .horizontal, .margin = .{ .y = 8 } });
    keyButton(@src(), "Remove figure", 0, .{ .expand = .horizontal, .margin = .{ .y = 4 } });
}

/// Remove figure pressed once on a figure still placed: the figure's id,
/// so a second press removes it and its placements.
var remove_figure_armed: layout.model.ObjectId = .none;

/// Replace from SVG: the file's drawing becomes the chosen figure's, and
/// every placement of it follows.
fn replaceFigureFrom(path: []const u8) void {
    const index = switch (state.context) {
        .figure_def => |i| i,
        else => return,
    };
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, a, .limited(64 << 20)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    const r = layout.svg.parse(a, bytes) catch {
        state.status = "That file is not an SVG drawing. ";
        return;
    };
    if (r.paths.len == 0) {
        state.status = "That drawing has no shapes Graven reads yet. ";
        return;
    }
    act(.replaceFigure, .{ index, r.paths, std.fs.path.basename(path) }) catch {
        state.status = "The figure was not replaced. ";
        return;
    };
    state.status = "Replaced: every placement follows. ";
}

/// A figure's ink, worked out once per figure and document revision.
var figure_ink: struct {
    arena: ?std.heap.ArenaAllocator = null,
    index: usize = std.math.maxInt(usize),
    revision: u64 = std.math.maxInt(u64),
    shapes: []const layout.art.Shape = &.{},
    regions: []const geom.fill.Region = &.{},
} = .{};

fn figureInk(index: usize) ?[]const layout.art.Shape {
    if (index >= state.model.figures.items.len) return null;
    const fi = &figure_ink;
    if (fi.index == index and fi.revision == state.model.revision and fi.arena != null) return fi.shapes;
    if (fi.arena) |*ar| ar.deinit();
    fi.arena = .init(state.gpa);
    const a = fi.arena.?.allocator();
    fi.index = index;
    fi.revision = state.model.revision;
    fi.shapes = layout.figure.ink(a, state.model.figures.items[index], figure_tol) catch &.{};
    const regions = a.alloc(geom.fill.Region, fi.shapes.len) catch return fi.shapes;
    for (fi.shapes, regions) |sh, *r| {
        const lines = a.alloc([]const geom.Point, sh.outline.contours.len) catch return fi.shapes;
        for (sh.outline.contours, lines) |c, *l| {
            var pts: std.ArrayList(geom.Point) = .empty;
            for (c.segments) |seg| flatten(a, &pts, seg, figure_tol) catch {};
            l.* = pts.items;
        }
        r.* = geom.fill.nonzero(a, lines, figure_tol * 0.1) catch .{ .loops = &.{}, .triangles = &.{} };
    }
    fi.regions = regions;
    return fi.shapes;
}

/// The tolerance figures' strokes and drawings are flattened to, mm.
const figure_tol = layout.model.figure_tolerance;

/// Figure `id` made the context: chosen in the Browser, its node shown.
fn showFigure(id: layout.model.ObjectId) void {
    const fi = state.model.figureIndex(id) orelse {
        state.status = "Its figure has been removed. ";
        return;
    };
    selection.clearRetainingCapacity();
    state.context = .{ .figure_def = fi };
    state.expanded.put(state.gpa, Context.key(.figures), true) catch {};
}

/// Draws figure `index`'s ink (`shapes`, bounds `b`) fitted into `r`.
fn drawInk(r: dvui.Rect.Physical, index: usize, shapes: []const layout.art.Shape, b: geom.Box) void {
    _ = index;
    if (b.isEmpty() or !(b.width() > 0 or b.height() > 0)) return;
    const pad: f64 = 8 * dvui.windowNaturalScale();
    const sx = (@as(f64, r.w) - 2 * pad) / @max(b.width(), 1e-9);
    const sy = (@as(f64, r.h) - 2 * pad) / @max(b.height(), 1e-9);
    const s = @max(0, @min(sx, sy));
    const ox = @as(f64, r.x) + (@as(f64, r.w) - b.width() * s) / 2;
    const oy = @as(f64, r.y) + (@as(f64, r.h) + b.height() * s) / 2;
    const lifo = dvui.currentWindow().lifo();
    const Index = dvui.Vertex.Index;
    for (shapes, 0..) |sh, k| {
        if (k >= figure_ink.regions.len) break;
        const col = switch (sh.paint.fill) {
            .solid => |c| c,
            else => continue,
        };
        const pma: dvui.Color.PMA = .fromColor(.{ .r = col.r, .g = col.g, .b = col.b, .a = col.a });
        const tris = figure_ink.regions[k].triangles;
        const batch = 20000;
        var from: usize = 0;
        while (from < tris.len) : (from += batch) {
            const part = tris[from..@min(from + batch, tris.len)];
            var tb = dvui.Triangles.Builder.init(lifo, 3 * part.len, 3 * part.len) catch return;
            defer tb.deinit(lifo);
            for (part, 0..) |t, j| {
                var v: [3]dvui.Point.Physical = undefined;
                for (t, &v) |q, *o| o.* = .{ .x = @floatCast(ox + (q.x - b.x0) * s), .y = @floatCast(oy - (q.y - b.y0) * s) };
                for (v) |pos| tb.appendVertex(.{ .pos = pos, .col = pma });
                const i: Index = @intCast(3 * j);
                tb.appendTriangles(&ccw(v[0], v[1], v[2], i, i + 1, i + 2));
            }
            dvui.renderTriangles(tb.build_unowned(), null) catch {};
        }
    }
}

/// File, Import figure (SVG): the file's drawing as a new figure, named
/// after the file, made the context.
fn importFigure(path: []const u8) void {
    var arena: std.heap.ArenaAllocator = .init(state.gpa);
    defer arena.deinit();
    const a = arena.allocator();
    const bytes = std.Io.Dir.cwd().readFileAlloc(dvui.io, path, a, .limited(64 << 20)) catch {
        state.status = "That file could not be read. ";
        return;
    };
    const r = layout.svg.parse(a, bytes) catch {
        state.status = "That file is not an SVG drawing. ";
        return;
    };
    if (r.paths.len == 0) {
        state.status = "That drawing has no shapes Graven reads yet. ";
        return;
    }
    const base = std.fs.path.basename(path);
    const stem = base[0 .. base.len - std.fs.path.extension(base).len];
    var nb: [96]u8 = undefined;
    const name = state.model.freshOrSame(&nb, .figures, stem, "Figure");
    const i = act(.addFigure, .{ name, r.paths, base }) catch {
        state.status = "The figure was not added. ";
        return;
    };
    state.context = .{ .figure_def = i };
    state.expanded.put(state.gpa, Context.key(.figures), true) catch {};
    const rep = r.report;
    const sb = &import_status_buf;
    state.status = if (rep.skipped() + rep.gradients + rep.dashes == 0)
        std.fmt.bufPrint(sb, "Imported {d} shapes as figure {s}. ", .{ rep.shapes, name }) catch "Imported. "
    else
        std.fmt.bufPrint(sb, "Imported {d} shapes as figure {s}; not read yet: {d} text, {d} use, {d} images, {d} clipped or masked, {d} gradients (painted black), {d} dashed (drawn solid). ", .{ rep.shapes, name, rep.text, rep.uses, rep.images, rep.clips, rep.gradients, rep.dashes }) catch "Imported, with parts not read yet. ";
}

/// A sketch panel's own properties: its sketch, and how it cuts.
fn sketchPanelProperties(pi: usize) void {
    const saved_group = pushGroup("sketch-panel");
    defer popGroup(saved_group);
    const pn = state.model.panels.items[pi];
    const si = state.model.sketchIndex(pn.sketch) orelse return;
    propText("Outline from", "{s}", .{state.model.sketches.items[si].name}, 70);
    // Which of the sketch's drawings it carries.
    {
        const ar = dvui.currentWindow().arena();
        var names: std.ArrayList([]const u8) = .empty;
        var ids: std.ArrayList(layout.model.ObjectId) = .empty;
        for (state.model.figures.items) |f| if (f.sketch == pn.sketch) {
            names.append(ar, f.name) catch return;
            ids.append(ar, f.id) catch return;
        };
        if (names.items.len > 0) {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 73 });
            defer row.deinit();
            propName("Drawing");
            var choice: usize = 0;
            if (state.model.panelDrawing(pi)) |fi| for (ids.items, 0..) |id, k| {
                if (id == state.model.figures.items[fi].id) choice = k;
            };
            if (tdropdown(@src(), names.items, .{ .choice = &choice }, .{}, .{ .expand = .horizontal, .id_extra = 73 })) actV(.setPanelDrawing, .{ pi, ids.items[choice] });
        }
    }
    var islands = pn.islands;
    if (tcheckbox(@src(), &islands, "Islands: a hole's holes stay solid", .{ .id_extra = 71 })) actV(.setPanelIslands, .{ pi, islands });
    keyButton(@src(), "Edit its sketch", 0, .{ .expand = .horizontal, .id_extra = 72 });
}

// Tiles from sketches -------------------------------------------------------------
//
// A tile prototype takes its own copy of a fully constrained sketch (Apply,
// from the prototype's properties): the sketch's parameters chosen for the
// tile's horizontal and vertical size are set to each tile's size (mm), and
// it is solved again for that size, its closed profiles drawn on the tile at
// the offset from the tile's origin. Later edits to the sketch reach the
// prototype only when it is applied again. Construction geometry a parameter
// switches on is switched per tile, in the tile's properties.

var proto_sk_choice: usize = 0;
var proto_sk_w: usize = 0;
var proto_sk_h: usize = 1;
var proto_sk_off: [2]f64 = .{ 0, 0 };
var proto_preview: [2]f64 = .{ 1, 1 };



fn prototypeSketch(id: layout.model.PrototypeId) void {
    const saved_group = pushGroup("prototype.sketch");
    defer popGroup(saved_group);
    const proto = state.model.proto(id).*;
    heading("{s}", .{"Drawn from a sketch"}, 8400);
    if (proto.sketch) |ps| {
        // Its copy: where it came from, and how it sits on its tiles.
        const from_ref: ?usize = state.model.sketchIndex(ps.from);
        const from_name: []const u8 = if (from_ref) |fi| state.model.sketches.items[fi].name else "a sketch since removed";
        propText("Copy of", "{s}", .{from_name}, 8401);
        propText("Width from", "{s}", .{ps.width_param}, 8402);
        propText("Height from", "{s}", .{ps.height_param}, 8403);
        propText("Offset", "({d:.2}, {d:.2}) mm", .{ ps.offset.x, ps.offset.y }, 8404);
        // The size preview: solved at another size, the tiles untouched.
        for ([_][]const u8{ "Preview width, u", "Preview height, u" }, 0..) |label, k| {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8405 + k * 10 });
            defer row.deinit();
            propName(label);
            _ = dvui.textEntryNumber(@src(), f64, .{ .value = &proto_preview[k], .min = 0.25, .max = 20 }, .{ .expand = .horizontal });
        }
        sketchPreview(id, ps);
        {
            var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8406 });
            defer row.deinit();
            if (from_ref != null) keyButton(@src(), "Apply again", 0, .{});
            keyButton(@src(), "Remove", 0, .{});
        }
    }
    // Apply a sketch: which one, its size parameters, the offset.
    const nsk = state.model.sketches.items.len;
    if (nsk == 0) {
        propText("Sketches", "{s}", .{"none in the document yet"}, 8410);
        return;
    }
    const arena = dvui.currentWindow().arena();
    const names = arena.alloc([]const u8, nsk) catch return;
    for (state.model.sketches.items, names) |sk_, *n| n.* = sk_.name;
    if (proto_sk_choice >= nsk) proto_sk_choice = 0;
    {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8411 });
        defer row.deinit();
        propName("Sketch");
        _ = tdropdown(@src(), names, .{ .choice = &proto_sk_choice }, .{}, .{ .expand = .horizontal });
    }
    const chosen = proto_sk_choice;
    const sk = &state.model.sketches.items[chosen].sketch;
    if (sk.params.items.len == 0) {
        propText("Parameters", "{s}", .{"none: give the sketch two, for width and height"}, 8412);
        return;
    }
    const pnames = arena.alloc([]const u8, sk.params.items.len) catch return;
    for (sk.params.items, pnames) |pp, *n| n.* = pp.name;
    if (proto_sk_w >= pnames.len) proto_sk_w = 0;
    if (proto_sk_h >= pnames.len) proto_sk_h = @min(1, pnames.len - 1);
    inline for (.{ .{ "Width from", &proto_sk_w, 8413 }, .{ "Height from", &proto_sk_h, 8414 } }) |row_def| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = row_def[2] });
        defer row.deinit();
        propName(row_def[0]);
        _ = tdropdown(@src(), pnames, .{ .choice = row_def[1] }, .{}, .{ .expand = .horizontal });
    }
    for ([_][]const u8{ "Offset across, mm", "Offset up, mm" }, 0..) |label, k| {
        var row = dvui.box(@src(), .{ .dir = .horizontal }, .{ .expand = .horizontal, .id_extra = 8415 + k * 10 });
        defer row.deinit();
        propName(label);
        _ = dvui.textEntryNumber(@src(), f64, .{ .value = &proto_sk_off[k], .min = -1000, .max = 1000 }, .{ .expand = .horizontal });
    }
    keyButton(@src(), "Apply sketch to this prototype", 0, .{ .expand = .horizontal, .margin = .{ .y = 6 } });
}

fn applyError(err: anyerror) []const u8 {
    return switch (err) {
        error.NotFullyConstrained => "Only a fully constrained sketch can be applied: finish constraining it first. ",
        error.NoSuchParameter => "The sketch has no parameter of that name. ",
        else => "The sketch could not be applied. ",
    };
}

/// The prototype's sketch solved at the preview size, drawn to fit a box.
fn sketchPreview(id: layout.model.PrototypeId, ps: layout.model.PrototypeSketch) void {
    const proto = state.model.proto(id).*;
    const unit = proto.unit orelse 19.05;
    const w = proto_preview[0] * unit;
    const h = proto_preview[1] * unit;
    var box = dvui.box(@src(), .{}, .{ .expand = .horizontal, .min_size_content = .{ .h = 140 }, .background = true, .color_fill = .{ .color = colors.paper }, .border = .all(1), .id_extra = 8420 });
    defer box.deinit();
    const r = box.data().contentRectScale().r;
    if (state.labels == null) return;
    const labels = &state.labels.?;
    const pitch: geom.Box = .{ .x0 = 0, .y0 = 0, .x1 = w, .y1 = h };
    const shapes = (labels.sketchShapes(dvui.currentWindow().arena(), ps, &.{}, pitch) catch null) orelse {
        dvui.labelNoFmt(@src(), "It does not solve at this size.", .{}, .{ .gravity_x = 0.5, .gravity_y = 0.5, .color_text = .{ .color = colors.overflow } });
        return;
    };
    // Fit the pitch box, with a margin.
    const m = 8 * dvui.windowNaturalScale();
    const k = @min((r.w - 2 * m) / @as(f32, @floatCast(w)), (r.h - 2 * m) / @as(f32, @floatCast(h)));
    const ox = r.x + (r.w - k * @as(f32, @floatCast(w))) / 2;
    const oy = r.y + (r.h + k * @as(f32, @floatCast(h))) / 2;
    const toPx = struct {
        fn f(p: geom.Point, kk: f32, x0: f32, y0: f32) dvui.Point.Physical {
            return .{ .x = x0 + kk * @as(f32, @floatCast(p.x)), .y = y0 - kk * @as(f32, @floatCast(p.y)) };
        }
    }.f;
    const px = dvui.windowNaturalScale();
    // The pitch box, faint.
    const corners = [_]geom.Point{ .{ .x = 0, .y = 0 }, .{ .x = w, .y = 0 }, .{ .x = w, .y = h }, .{ .x = 0, .y = h } };
    var cp: [4]dvui.Point.Physical = undefined;
    for (corners, &cp) |c, *o| o.* = toPx(c, k, ox, oy);
    dvui.Path.stroke(.{ .points = &cp }, .{ .thickness = px, .color = .{ .color = colors.guide.opacity(0.5) }, .closed = true });
    const a = dvui.currentWindow().arena();
    for (shapes) |sh| for (sh.outline.contours) |c| {
        var pts: std.ArrayList(geom.Point) = .empty;
        if (c.segments.len == 0) continue;
        pts.append(a, c.segments[0].start()) catch return;
        for (c.segments) |seg| flatten(a, &pts, seg, 0.5 / @as(f64, k)) catch return;
        // Closed: the last point is the first again.
        if (pts.items.len > 1) _ = pts.pop();
        const phys = a.alloc(dvui.Point.Physical, pts.items.len) catch return;
        for (pts.items, phys) |p, *o| o.* = toPx(p, k, ox, oy);
        dvui.Path.stroke(.{ .points = phys }, .{ .thickness = 1.5 * px, .color = .{ .color = colors.ink }, .closed = true });
    };
}

/// A tile's switches: each parameter its prototype's sketch uses to switch
/// construction geometry on.
fn tileSketchParams(id: TileId) void {
    const saved_group = pushGroup("tile.sketch");
    defer popGroup(saved_group);
    const t = state.model.tileConst(id);
    const ps = state.model.proto(t.prototype).sketch orelse return;
    var seen: [16][]const u8 = undefined;
    var n: usize = 0;
    for (ps.sketch.geometry.items) |g| {
        if (g.removed or g.physical_when.len == 0) continue;
        const dup = for (seen[0..n]) |x| {
            if (std.mem.eql(u8, x, g.physical_when)) break true;
        } else false;
        if (dup or n >= seen.len) continue;
        seen[n] = g.physical_when;
        n += 1;
    }
    if (n == 0) return;
    heading("{s}", .{"Sketch switches"}, 8500);
    for (seen[0..n], 0..) |name, i| {
        var on = for (t.params.items) |p| {
            if (std.mem.eql(u8, p.name, name)) break p.value != 0;
        } else ((ps.sketch.paramValue(name) catch 0) != 0);
        if (tcheckbox(@src(), &on, name, .{ .id_extra = i })) {
            actV(.setTileParam, .{ id, name, @as(?f64, if (on) 1 else 0) });
        }
    }
}
